// Build canonical NASA TOPS sheet URL for a patent. Pattern is consistent
// across the public T2 portal: technology.nasa.gov/patent/{CASE_NUMBER}
const officialNasaUrl = (tech) =>
  tech.type === "patent"
    ? `https://technology.nasa.gov/patent/${tech.id}`
    : `https://software.nasa.gov/software/${tech.id}`;


const TECHNOLOGIES_RAW = [{"forgeId":"forge_nasa_drc_tops_1","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-TOPS-1","sourceUrl":"https://technology.nasa.gov/patent/DRC-TOPS-1","confidence":"high"},"type":"patent","title":"Outer Aileron Yaw Damper","abstract":"In recent years, NASA, along with partners Boeing and Area-I Inc., have developed the spanwise adaptive wing (SAW). SAWs leverage a thermally-triggered actuator made from a NASA-developed shape memory alloy (SMA) to allow outer portions of aircraft wings and control surfaces to be folded to achieve optimal angles during flight. For supersonic aircraft , SAWs can reduce drag and increase performance during the transition from subsonic to supersonic speeds. For subsonic aircraft , SAWs offer increased control and reduced dependency on the tail rudder and associated hydraulic systems - a particularly heavy part of the aircraft . Engineers at NASA AFRC realized the aircraft weight savings that could be achieved by reducing or eliminating rudder dependency, since this would allow for rudder size to be reduced. So, they set out to develop an alternative system capable of providing the same \"yaw control\" functionality as traditional rudders. This work resulted in the invention of NASAs outer aileron yaw damper system, which includes novel control algorithms that drive flight control surfaces to produce desired flight conditions.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_drc_tops_19","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-TOPS-19","sourceUrl":"https://technology.nasa.gov/patent/DRC-TOPS-19","confidence":"high"},"type":"patent","title":"Improved Ground Collision Avoidance System","abstract":"Researchers at NASA's Armstrong Flight Research Center have dramatically improved upon existing ground collision avoidance technology for aircraft . NASA's system leverages leading-edge fighter safety technology, adapting it to civil aviation use as an advanced warning system. It offers higher fidelity terrain mapping, enhanced vehicle performance modeling, multidirectional avoidance techniques, more efficient data-handling methods, and user-friendly warning systems. The algorithms have been incorporated into an app for tablet/handheld mobile devices that can be used by pilots in the cockpit, enabling significantly safer general aviation. This will enable pilots to have access to this lifesaving safety tool regardless of what type of aircraft they are flying. The system also can be incorporated into electronic flight bags (EFBs) and/or aircraft avionics systems.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_drc_tops_36","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-TOPS-36","sourceUrl":"https://technology.nasa.gov/patent/DRC-TOPS-36","confidence":"high"},"type":"patent","title":"New Wing Design Exponentially Increases Total Aircraft Efficiency","abstract":"Innovators at NASA's Armstrong Flight Research Center are experimenting with a new wing design that removes adverse yaw and dramatically increases aircraft efficiency by reducing drag. Known as the PRANDTL-D wing, this design addresses integrated bending moments and lift to achieve a 12 percent drag reduction. The approach to handling adverse yaw employs fine wing adjustments rather than an aircraft 's vertical tail. The technology has the potential to significantly increase total aircraft efficiency by optimizing overall aircraft configuration through the reduction in size or removal of the vertical tail as well as the reduction of structural weight.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_drc_tops_7","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-TOPS-7","sourceUrl":"https://technology.nasa.gov/patent/DRC-TOPS-7","confidence":"high"},"type":"patent","title":"Interactive Sonic Boom Display","abstract":"Engineers at NASA's Armstrong Flight Research Center have developed a Real-Time Sonic Boom Display for aircraft that enables pilots to control boom placement. The system can be integrated into a cockpit or flight control room to help pilots place loud booms in specific locations away from populated areas or prevent them from occurring. Armstrong's sonic boom display system leverages existing tools co-developed and enhanced by the U.S. Air Force and NASA to predict sonic boom propagation to the ground. The technology can be used on current-generation supersonic aircraft, which generate loud sonic booms, as well as future-generation low-boom aircraft, anticipated to be quiet enough to be flown over land.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_10","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-10","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-10","confidence":"high"},"type":"patent","title":"AeroPod","abstract":"The AeroPod is a passive device that uses aerodynamic forces to stabilize an instrument package suspended from a kite or tethered blimp. It is a low-altitude custom remote sensing platform craft designed for, but not limited to, agricultural and environmental research purposes. AeroPods can be used for a variety of remote sensing and in-situ observations.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_225","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-225","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-225","confidence":"high"},"type":"patent","title":"Novel Antenna Concept for CubeSat Platforms","abstract":"Current Cubesat antenna technology requires packaging during the launch and deployment mechanisms during orbit. This packaging and deployment hardware adds extra volume, weight and complexity to a payload. Additionally, there is a risk of deployment mechanism failure. By integrating the antenna into the structure of a Cubesat, the need for extruding antennas, packaging considerations and deployment mechanism are eliminated. The resulting antenna has reduced weight and volume and increased dependability.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_241","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-241","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-241","confidence":"high"},"type":"patent","title":"SpaceCube 3.0 Flight Processor Card","abstract":"SpaceCube 3.0 is a family of high-performance reconfigurable systems designed for spaceflight applications requiring on-board processing. SpaceCube 3.0 has greater processing performance over previous generations of SpaceCube. Many proposed missions require next generation on-board processing capabilities to meet specified mission goals. Advanced laser altimeter, radar, lidar, and hyper-spectral instruments are proposed for future missions, and all of these instrument systems require advanced onboard processing capabilities to facilitate data conversion. Besides an increased processing performance need, there is a need for a processor card capable of detecting and reacting to events, producing data products on-board, enabling sensor web multi-platform collaboration, performing on-board lossless data reduction by migrating typical ground-based processing functions on-board. In general, the processing needs of emerging space missions require a stronger flight processor card. SpaceCube 3.0 Flight Processor Card represents an improved flight processing system.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_286","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-286","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-286","confidence":"high"},"type":"patent","title":"SmallSat Standardized Architecture","abstract":"Over the past decade, SmallSats have been established as having great potential for science exploration and commercialization of space. SmallSats aim to decrease the cost of space development, making space exploration more accessible. Space agencies, as well as the commercial and defense sectors, are considering innovative uses of disaggregated SmallSat constellations to accomplish the same objectives previously achievable by large singular spacecrafts, which have long lead times and high cost. Smaller satellites can be launched more affordably by launching with larger primary payloads. In general, SmallSats represent an emerging class of satellites, with small size, mass, and cost.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_293","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-293","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-293","confidence":"high"},"type":"patent","title":"SpaceCube 3.0 Mini Processor Card","abstract":"SpaceCube 3.0 is a family of high-performance reconfigurable systems designed for spaceflight applications requiring on-board processing. Many proposed missions require next-generation, on-board processing capabilities to meet specified mission goals. Advanced laser altimeter, radar, lidar, and hyperspectral instruments are proposed for many upcoming missions, and all of these instrument systems will require advanced onboard processing capabilities to facilitate the timely conversion of science data into science information and data products. Both an order of magnitude increase in processing power and the ability to reconfigure on-the-fly are required to implement algorithms that detect and react to events, produce data products on-board for applications, enable sensor web multi-platform collaboration, and perform on-board lossless data reduction. The SpaceCube 3.0 Mini Processor Card is designed for the processing needs of emerging science missions.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_330","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-330","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-330","confidence":"high"},"type":"patent","title":"Hypergol Refueling Tool (HRT) and Quick Disconnect (QD) System","abstract":"A non-cooperative satellite is a satellite that was not designed with on-orbit servicing in mind. Compared to a cooperative servicing interface, non-cooperative interfaces pose unique difficulties and challenges. Refueling is important to resupply of propellant and required pressurants or other media that allow a satellite with depleted fuel stores to extend its life. A potential, and likely, end-of-life event for a satellite is the depletion of propellant. Historically, satellites whose hardware and software components are still functioning properly will be decommissioned or de-orbited because the lack of onboard propellant does not permit proper spacecraft attitude and navigational control. The HRT and QD System can service non-cooperative satellites, addressing the challenges presented by noncooperative interfaces in order to access, interface, and manipulate non-cooperative assets.","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_353","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-353","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-353","confidence":"high"},"type":"patent","title":"3D Lidar for Autonomous Landing Site Selection","abstract":"Next generation autonomous planetary exploration missions require advanced sensing capabilities for choosing proper landing areas for the vehicles. Current tools do not have the capability to allow vehicles outside the range of terrestrial control to autonomously perform safe landing operations. The Ocellus 3D lidar developed by the NASA Goddard Space Flight Center is a lightweight, small-footprint 3D lidar system for planetary and lunar exploration. The new 3D lidar can perform both altimetry (or range-finding) measurements from high altitudes and, at lower altitudes, terrain mapping and imaging. These measurements provide the necessary data for autonomous systems to select safe landing areas for planetary exploration vehicles. Developed to aid in the safe landing and navigation of the rotocopter for the Dragonfly mission to explore Titan, the Ocellus 3D lidar may be used for a wide variety of altimetry and terrain mapping purposes both in space and terrestrially.","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_36","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-36","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-36","confidence":"high"},"type":"patent","title":"Diminutive Assembly for Nanosatellite deploYables (DANY)","abstract":"SmallSats (i.e., mass below 500 kg) are increasingly becoming big business. More than 100 global organizations across academia, governments, and industry are involved in the development of SmallSats of the nanosat/microsat variety (i.e., mass of 1-50 kg). According to SpaceWorks, up to 2,750 such nanosats/microsats will be launched from 2014 to 2020. To extract the most utility from these small packages, peripheral parts of the satellite (e.g., solar panels, antennae, sun shades, etc.) are deployed after a small sat is positioned in orbit. Meanwhile, these \"deployables\" are restrained close to the small sat body until extended using a release signal and mechanism.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_37","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-37","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-37","confidence":"high"},"type":"patent","title":"Dellingr 6U CubeSat","abstract":"CubeSats, once the domain of university researchers, have become increasingly more popular in recent years among government researchers. Motivated in large by their growing capabilities and relatively inexpensive cost, NASA and other government agencies are increasing their investments in CubeSats. NASA now is funding CubeSat mission opportunities through various programs. In addition to their low cost, CubeSats enable mission configurations not possible with more traditional approaches. Instead of launching just one satellite , mission planners could deploy swarms or constellations of these tiny platforms to execute simultaneous, multi-point observations. Technologists, meanwhile, also are interested in using CubeSats. Before mission planners can infuse a prototype technology, its developers must first demonstrate the technology in a relevant end-to-end space environment. CubeSats have the potential to offer the needed access at greatly reduced costs.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_40","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-40","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-40","confidence":"high"},"type":"patent","title":"CubeSat Form Factor Thermal Control Louvers","abstract":"As small spacecraft become a part of NASAs repertoire of missions, one reoccurring theme is an increased need for thermal control as power budgets increase and tight instrument temperature tolerances are introduced on smaller platforms. Until now CubeSats have not needed thermal control outside of resistive heaters due to the low power and short lifespan of most CubeSat missions. However, in the past few years CubeSat solar panels have been developed by private companies which can produce up to 80W of power for a 3U (30X10X10 cm) spacecraft . Now, CubeSat and small satellite missions are being proposed which rise to meet this new technological envelope, with high power instruments and multiple months or years of mission life. Therefore it is critical that a thermal control system be designed for small spacecraft missions. The CubeSat Form Factor Thermal Control Louvers use passive thermal control to significantly improve the internal thermal stability of small spacecraft , creating a difference of several watts in dissipated heat between open and closed louvers.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_97","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-97","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-97","confidence":"high"},"type":"patent","title":"Deployed Electromagnetic Radiation Deflector Shield","abstract":"Spaceflight outside of the Earth's protective magnetic field is dangerous from a cosmic radiation perspective. Inside Earth's magnetic field, where the manned International Space Station (ISS) orbits, the radiation encountered is minimal and almost all is deflected by our planet's magnetic fields. However, outside that protective shield, the Sun's solar wind (high energy radiation, solar energetic particles or SEPs) consisting of protons, electrons, alpha particles and plasmas continuously bombards the spacecraft for the months or years of spaceflight. On occasion the Sun produces a CME (Coronal Mass Ejection) that vastly increases the energy and volume of this radiation. These particles damage human DNA as well as living tissue and can destroy sensitive electronics. The Deployed Electromagnetic Radiation Deflector Shield (DERDS) provides a magnetic field that will deflect SEPs and CMEs and other harmful solar and cosmic rays away from a manned spacecraft , robotic spacecraft , or manned extra-planetary base stations using an electromagnet that is deployed between the spacecraft /station and the source of radiation and creates a magnetosphere or zone of minimal radiation in which the spacecraft or base station would reside.","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_232","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-232","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-232","confidence":"high"},"type":"patent","title":"Aerodynamically Actuated Thrust Vectoring Device","abstract":"NASA's Langley Research Center has developed a thrust-actuating device for a Vertical Take-Off and Landing (VTOL) aircraft . The technology is unique because no mechanically driven actuation is required to transition from hover flight to wing born flight. The result is lower empty weight and robust aircraft that has a benign response to wind gusts and shear. In addition, the aircraft fuselage can be designed for exceptional pilot visibility.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_241","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-241","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-241","confidence":"high"},"type":"patent","title":"VTOL UAV With the Cruise Efficiency of a Conventional Fixed Wing UAV","abstract":"NASA Langley Research Center has developed Greased Lightning, the first UAV that combines vertical take-off and landing (VTOL) capability with long endurance flight. Previously these two capabilities have been considered mutually exclusive. For example, helicopters offer VTOL capability, yet are inefficient for long-endurance travel. The UAV market is large (multi-billion USD) and growing, with a global reach and many regional markets. This presents numerous opportunities and entry points for a new and superior UAV technology.","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_244","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-244","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-244","confidence":"high"},"type":"patent","title":"Reliable Geo-Limitation Algorithm for Unmanned Aircraft","abstract":"NASA Langley Research Center has developed a an assured safety net technology for UAS, Safeguard, that can alleviate hazards with unmanned aircraft (UA) flying beyond their authorized perimeters and into no-fly zones. Safeguard works by continuously detecting a UAs proximity to virtual perimeters established around no-fly-zones (i.e., stay-out or stay-in regions and altitude limits), and taking action to guarantee the perimeters are not breached. The key to the design is streamlined functionality that has been formally verified to guarantee detection of possible perimeter violations. Safeguard is applicable to both rotary- and fixed-wing systems and substantially outperforms embedded geo-fences in terms of reliably and dependably stopping excursions into no-fly zones. Safeguard has the potential to provide a means to comply with pending regulatory directives for geo-limitation for a burgeoning UAS industry.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_283","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-283","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-283","confidence":"high"},"type":"patent","title":"Vertical Take Off and Landing (VTOL) Aircraft with Vectored Thrust for Control and Continuously Variable Pitch Attitude in Hover","abstract":"Most fixed wing VTOL UAVs takeoff vertically, then transition to horizontal flight. This is new type of UAV which has unique capability. It can vary its hover position from \"nose up\" (tailsitter) to \"nose forward\" (non-tailsitter) incrementally and continuously, and even hold a position at any angle in between.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_293","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-293","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-293","confidence":"high"},"type":"patent","title":"Small Compound-Wing VTOL UAS","abstract":"Typically small UAS, because of their light weight and small size, have difficulty flying in adverse environmental conditions, especially gusty winds. In some cases, small UAS such as multi-copters can handle somewhat higher gust conditions, but have limited endurance. Fixed-wing configurations have good endurance but need large open areas for launch and recovery and are typically not very wind-robust. This vehicle combines VTOL convenience with fixed-wing endurance while enhancing operations in adverse environments.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_311","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-311","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-311","confidence":"high"},"type":"patent","title":"Supersonic Laminar Flow Control","abstract":"NASA's Langley Research Center has developed a technology that is projected to extend the laminar flow area over supersonic flight configurations by delaying the transition of boundary layer flow from laminar to turbulent state. This controls laminar flow over airframe components including wings, empennage, engine nacelles, and the nose region of an aircraft fuselage. It can be used in combination with many of the existing techniques for passive and active laminar flow control, but is particularly well-suited for a supersonic natural laminar flow design by virtue of avoiding the space, weight, system complexity, and maintenance penalties associated with suction based laminar flow control.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_325","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-325","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-325","confidence":"high"},"type":"patent","title":"Multirotor Aircraft Noise Reduction","abstract":"Multirotor aircraft typically create a significant amount of tonal noise from each rotor. Groups of rotors operating at the same rotation rate with an appropriate phase offset can be used to reduce the tonal noise of the aircraft when there are multiple rotors on each side of the aircraft . Reducing tonal noise, depending on the aircraft design, can effectively reduce the total noise output for a given flight scenario. Aircraft can be designed with this technology to prioritize quieter take-off and landing, or can be designed for decreased noise in cruise. Existing designs may benefit from this technology as well, but what type of benefits can be gained depend on the design of the aircraft . Using this method, multiple rotors can be significantly quieter than a single rotor, without sacrificing thrust.","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_338","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-338","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-338","confidence":"high"},"type":"patent","title":"Fixed Wing Angle eVTOL","abstract":"Current electric vertical takeoff and landing aircraft (eVTOL) configurations for Urban Air Mobility (UAM) applications often require performance-hindering equipment only used for a specific operation (e.g., takeoff or cruising). The need for such equipment, such as separate lift and thrust mechanisms, often stems from the challenge posed by transitioning from hovering to forward flight. For example, tilt-wing eVTOLs have complex transition periods that can result in large pitching movements or wing stalling without adequate propulsion, potentially causing catastrophic loss of control. Increased equipment requirements for eVTOLs also increase system mass, negatively impacting performance. Innovators at NASA's Langley Research Center recognized this issue and have developed a novel eVTOL solution design. The technology is a distributed electric propulsion, modular wing aircraft capable of vertical takeoff and landing, without requiring near 90&#176; wing tilt. Instead, NASA's eVTOL uses large flaps and a fixed slight wing tilt to generate upward force, enabling VTOL operations, benign transition from hovering to forward flight, and increased safety and simplicity of operations.","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_343","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-343","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-343","confidence":"high"},"type":"patent","title":"Improved Fixed-Wing Gust Load Alleviation Device","abstract":"Gust load alleviation is an increasing concern for the design of fixed-wing aircraft with ultra-high aspect wings. Innovators at NASAs Langley Research Center developed a mechanical solution to control gust-load on fixed plane wings. By manipulating the wings natural response to gust loads, the technology may minimize aerodynamic and structural loads and improve flight efficiency of future aircraft. Current computer-controlled, active gust-alleviation devices delay the wing response such that gust loads experienced are mitigated less than 10% while the present invention has demonstrated the ability to improve gust load alleviation up to 30%. Along with the reduced response time that alleviates gust load, NASAs mechanical innovation offers the advantage of a simplified design and potentially improves passenger flight experience during turbulence.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_363","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-363","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-363","confidence":"high"},"type":"patent","title":"System for Flight Control of Extremely Fast (Hypersonic) Aircraft","abstract":"Researchers at NASA\u2019s Langley Research Center have designed an electrode-based system for guidance, navigation and control of aircraft or spacecraft moving at hypersonic speeds in ionizing atmospheres. The system is composed of two electrodes that sit on the surface of a craft\u2019s thermal protection system (TPS) and an electromagnet positioned beneath the craft\u2019s TPS. The system operates based on the principles of magnetohydrodynamics (MHD) and uses energy harvested from the ionized flow occurring during flight at hypersonic speeds to power the electromagnet and generate extremely large Lorentz forces capable of augmenting lift and drag forces to steer and control the craft. The energy harvested can alternatively be stored for later use. NASA\u2019s system is simpler than conventional methods for control of hypersonic craft (e.g., chemical propulsion, shifting flight center of gravity, or trim tabs) and enables new entry, descent, and landing mission architectures.","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_364","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-364","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-364","confidence":"high"},"type":"patent","title":"Improved Hypersonic Aircraft Flight Control System","abstract":"Researchers at NASA\u2019s Langley Research Center have designed an improved electrode-based system for guidance, navigation and control of aircraft or spacecraft moving at hypersonic speeds in ionizing atmospheres. The system is composed of two electrodes that are recessed into angled channels on the surface of a craft\u2019s thermal protection system (TPS) and an electromagnet positioned beneath the craft\u2019s TPS. The system operates based on the principles of magnetohydrodynamics (MHD) and uses energy harvested from the ionized flow occurring during flight at hypersonic speeds to power the electromagnet and generate large Lorentz forces capable of augmenting lift and drag forces to steer and control the craft. The energy harvested can alternatively be stored for later use. This improved design increases electrode separation from the shock layer and decreases thermal loads experienced by the electrodes to mitigate thermal degradation.","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_371","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-371","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-371","confidence":"high"},"type":"patent","title":"eVTOL UAS with Lunar Lander Trajectory","abstract":"Lunar landers are critical to enabling NASA\u2019s mission of sustained human presence on the Moon. These spacecraft require advanced landing technologies (e.g., sensors, algorithms, navigation loops) to enable automated and precise entry, descent, and landing (EDL) on planetary surfaces. EDL operations rely on advanced, high-accuracy sensors that enhance navigation precision and improve the control performance of the spacecraft. These sensors must undergo rigorous testing and validation on Earth before mission use. To test EDL sensors today, organizations generally use helicopter or rocket flights to simulate lander trajectories. However, helicopters are not capable of achieving the rapid descents experienced by landers (due to vortex ring state). Rocket flights are expensive, high risk, often not repeatable, and cannot be performed in rapid succession. This limits the volume and quality of data available for EDL sensor verification and validation, making iterative testing and development slower and lower fidelity than desired. In response to this challenge, engineers at NASA\u2019s Langley Research Center (LaRC) have developed an electric vertical takeoff and landing (eVTOL) unmanned aerial system (UAS) designed to fly trajectories with high similitude to those flown by lunar landers. The NASA invention is poised to enable rapid development and testing of EDL sensors and improve EDL sensor testing data quality at a fraction of the cost of alternative methods.","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_383","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-383","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-383","confidence":"high"},"type":"patent","title":"Foldable Solid RF Reflector Architectures","abstract":"Inventors at the NASA Langley Research Center have designed innovative foldable large-scale parabolic reflectors. This solution addresses the challenges of scaling solid surface reflectors to beyond 10-meter diameter, enabling higher gains, improved data transfer rates, and superior overall performance. Leveraging an independently developed shape memory composite, two new foldable reflector architectures were designed that may be deployed through embedded compliant mechanisms. The concentric stack-and-connect architecture features a set of rigid reflective panels that packages concentrically while the umbrella architecture utilizes a thin shell reflective surface that stows like an umbrella. These designs overcome the scaling complexities of other solid reflectors and prioritize lightweight materials and high packing efficiency. The precisely controlled deployment mechanisms ensure accurate shaping and alignment, making it an ideal solution for space communications and radio astronomy.","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_384","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-384","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-384","confidence":"high"},"type":"patent","title":"Mitigating Risk in Commercial Aviation Operations","abstract":"Researchers at the NASA Langley Research Center have invented a software based on machine learning algorithms that uses data from over 200 airports and over 400 individual systems to predict aviation related risks. One source of the National Airspace System (NAS)\u2019s flight operations data is available from the System Wide Information Management (SWIM) program which are not adequately leveraged due to their relative inaccessibility and the lack of software to collate and interpret the information. The new NASA software can transform the data into a usable form, then support real-time dispatchers guiding aircraft approaches and departures through the developed machine learning models. This has the potential to improve safety within commercial aviation terminal area operations, which will be especially pertinent as the number of flights per day increases. This software may also be leveraged to manage autonomous flight activity.","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_87","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-87","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-87","confidence":"high"},"type":"patent","title":"Autonomous Slat-Cove Filler Device","abstract":"NASA's Langley Research Center developed a deployable and stowable mechanical design for filling the cavity behind the leading-edge slat (i.e., slat cove), when it is extended upon landing approach of an aircraft. Aerodynamic flow over an unfilled cavity typically exhibits strongly unsteady behavior that is a source of aeroacoustic noise. Conventional leading-edge slat devices for high lift are a good example of such geometric and flow conditions and are a prominent source of airframe noise. Experimental and computational results have shown that a slat-cove filler device could significantly reduce the noise produced by slat structures without aerodynamic penalty. The proposed structural concept will enable autonomous achievement of the desired deployed shape. The design will facilitate a clean cruise configuration with minimal weight addition to the aircraft. NASA is seeking development partners and potential licensees.","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_109","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-109","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-109","confidence":"high"},"type":"patent","title":"A Method for Reducing Broadband Noise","abstract":"Researchers at NASA's Glenn and Langley Research Centers have developed a groundbreaking bio-mimicking acoustic liner for quieting noisy environments. Conventional approaches have not been able to absorb sound effectively in the 400-3000 Hz range, thereby subjecting humans to excessive noise pollution at the low end of the auditory range. The NASA innovation relies on parallel-stacked tube filters, which improve noise reduction in this range by as much as 25% over conventional melamine or honeycomb solutions. Inspired by the structure of natural reeds, these porous tubes are arranged to maximize acoustic absorption while also realizing significant benefits in weight, size, and extreme-temperature functionality. Since broadband noise represents one of the most significant potential environmental constraints to increasing capacity, efficiency, and flexibility in a host of different arenas, this technology could prove invaluable in multiple applications including aircraft cabin liners, school buses and other vehicles, industrial environments, and building construction.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_52","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-52","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-52","confidence":"high"},"type":"patent","title":"New Concepts in Film Cooling for Turbine Blades","abstract":"To run at maximum efficiency, turbine engines often experience temperatures of more than 2000 degrees Kelvin, and these elevated temperatures can lead to compromised integrity and failure of the blades. One method for addressing this problem is film cooling, in which cool air is bled from the compressor, ducted to one or more internal chambers of the turbine blades, and discharged through one or more cooling holes to form cooling jets. As a result of the cooling jets, convective heat transfer to the surface of the turbine blade can be reduced. Innovators at NASA's Glenn Research Center have developed two new ways to improve the effectiveness of film cooling. One involves using a shaped recess to create a counter-rotating vortex pair, splitting the incoming flow to a high-energy and a low-energy stream. The other innovation employs various techniques to mitigate the aerodynamic losses that sometime accompany film cooling. These novel approaches make film cooling a much more efficient and successful means of keeping turbine blades operable.","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_52","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-52","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-52","confidence":"high"},"type":"patent","title":"Foot Pedal Controller","abstract":"Innovators at the NASA Johnson Space Center (JSC) have developed a novel foot-pedal operated system and device to control movement of an object in three-dimensional (3D) space. The Foot Pedal Controller system enables operators to control movement of spacecraft, aircraft , and watercraft using only foot pedals. This design leaves the hands free for simultaneous operation of other equipment. The Foot Pedal Controller integrates six articulating mechanisms and motion sensors and provides continuous positional feedback to the operator. Motion control across six degrees-of-freedom is enabled by three-control motions for each foot. Specifically, the foot pedal controller moves the object forward/backward, up/down, left/right (translation in three perpendicular axes) combined with rotation about three perpendicular axes, often termed pitch, yaw, and roll. This NASA Technology is available for your company to license and develop into a commercial product. NASA does not manufacture products for commercial sale.","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_90","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-90","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-90","confidence":"high"},"type":"patent","title":"Spacecraft to Remove Orbital Debris","abstract":"Innovators at NASA Johnson Space Center have designed an Active Debris Removal Vehicle (ADRV) that can remove large orbital debris from low-Earth orbit (LEO). The ADRV will approach a debris object, assess its characteristics and motion, determine an initial capture trajectory, match its rotation rates, execute a capture maneuver, and control and deorbit the object. This concept can help mitigate catastrophic collisions with debris involving astronauts, their spacecraft , and other valuable space assets. The ADRV incorporates several NASA inventions including a novel spacecraft control system, debris object characterization system, and capture and release system. These NASA ADRV technologies may also be applied to satellite servicing and orbital adjustments. The Active Debris Removal Vehicle (ADRV) is at technology readiness level (TRL) 6 (which means the system/sub-system model or prototype has been demonstrated in an operational environment) and the related issued patent is now available to license. Please note that NASA does not manufacture products itself for commercial sale.","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_109","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-109","sourceUrl":"https://technology.nasa.gov/patent/TOP2-109","confidence":"high"},"type":"patent","title":"FACET: Future Air Traffic Management Concepts Evaluation Tool","abstract":"The NASA Ames Research Center offers the opportunity to license FACET, a flexible software tool for air traffic management. With thousands of planes flying overhead in the U.S. at any given time, there is an urgent need for tools that help avoid air traffic incidents and delays. To help air traffic control centers improve airline safety and efficiency, NASA developed FACET, a system software for performing powerful computational simulations for evaluating advanced concepts of air-traffic management. It includes a program that generates a graphical user interface plus programs and databases that implement computational models of weather, airspace, airports, navigation aids, aircraft performance, and aircraft trajectories.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_162","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-162","sourceUrl":"https://technology.nasa.gov/patent/TOP2-162","confidence":"high"},"type":"patent","title":"Transformable Hypersonic Aerodynamic Decelerator","abstract":"NASA has developed a game changing deployable aeroshell concept for entry, descent and landing (EDL) of large science and exploration-class payloads.The Adaptable, Deployable Entry Placement Technology (ADEPT) concept is a mechanically deployable semi-rigid aeroshell entry system capable of achieving low ballistic coefficient during entry suitable for a variety of planetary or earth return missions. It leverages Ames expertise in Thermal Protection systems (TPS) material and entry system design, development and testing. The deployable decelerator systems offer a lighter-weight solution to current rigid, high ballistic coefficient aeroshells. The deployable feature of ADEPT allows each mission to utilize an entry system design that fits within existing launch vehicle systems and later transforms into a low ballistic coefficient configuration for EDL. Consisting of rigid ribs and a TPS, deployment can be done for inspection in Earth orbit by extending the ribs and stretching the TPS in between (in a method similar to an opening umbrella) and thereby reducing the mission risk.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_165","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-165","sourceUrl":"https://technology.nasa.gov/patent/TOP2-165","confidence":"high"},"type":"patent","title":"Nanosatellite Launch Adapter System","abstract":"NASA has developed and patented a technology called Nanosatellite Launch Adapter System (NLAS) that maximizes the efficiency of satellite launch opportunities. NLAS increases access to space while simplifying the integration process of miniature satellites, called nanosats or cubesats, onto launch vehicles. Each complete NLAS consists of an adapter, four dispensers, and a sequencer. The adapter is mounted to the upper surface of the launch vehicle and the lower deck of the primary spacecraft . The dispensers are mounted inside the adapter and house a variety of cubesats in fully enclosed bays. NLAS is stackable, allowing for the expansion of spacecraft deployments. An NLAS sequencer can initiate a secondary sequencer, allowing for the expansion of actuator and deployment capability. NLAS provides an integrated system which meets the needs of nearly any mission. NLAS flight demonstration has shown the potential value of multiple, nanosatellites as tools for a wide array of scientific, commercial, and academic space research.","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_166","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-166","sourceUrl":"https://technology.nasa.gov/patent/TOP2-166","confidence":"high"},"type":"patent","title":"Variable Geometry Aircraft Wing Supported By Struts and/or Trusses","abstract":"NASA has patented a new technology for an aircraft configuration that utilizes a strut/truss-braced oblique variable-sweep wing mounted on a constant cross-section geometry fuselage. In practice, the wing would start in a position closely aligned with the fuselage. This allows the aircraft to easily maneuver within the terminal/ramp area, and promotes higher density terminal operations. During the runup/checkout before takeoff, the wing would be rotated to the unswept position for increased climb performance. Once airborne, the wing would be pivoted to the sweep angle that provides the best aerodynamic performance and noise abatement at the current speed. During cruise, both speed and sweep angles could be adjusted accordingly. Before final approach, the wing would again be rotated to the perpendicular position in order to improve the aircraft's low-speed performance. As the aircraft departs the runway for the taxiway, the wing would be rotated again to align with the fuselage, greatly reducing the possibility of collisions during taxiing.","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_168","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-168","sourceUrl":"https://technology.nasa.gov/patent/TOP2-168","confidence":"high"},"type":"patent","title":"Dynamic Weather Routes Tool","abstract":"NASA has developed a ground-based aircraft flight automation system and tool that can save significant amounts of time and fuel in challenging weather situations. The Dynamic Weather Routes (DWR) tool continuously and automatically analyzes in-flight aircraft in en-route airspace to find corrections to preselected weather avoidance routes. Convective weather, such as severe thunderstorm activity, is the largest cause of delay in the U.S. National Airspace System. When such weather is present or forecast on preferred flight routes, weather avoidance routes are selected before takeoff. They often include large buffers to compensate for forecast uncertainty. As flights progress, airline dispatchers and Federal Aviation Administration (FAA) traffic managers strive to find improved routes to reduce delay. However, operators are busy, especially during weather events, and may miss opportunities for more time-and-fuel-efficient routes. Automation hasn't previously existed to help operators determine when weather avoidance routes could be modified or eliminated to reduce delay.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_196","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-196","sourceUrl":"https://technology.nasa.gov/patent/TOP2-196","confidence":"high"},"type":"patent","title":"Co-Optimization of Blunt Body Shapes for Moving Vehicles","abstract":"NASA has patented a design optimization method for optimal shapes for hypersonic vehicles with mid-range lift/drag ratios that enter or operate in planetary atmospheres, including Earth. The design method provides optimized aerodynamic properties (maximizing maneuverability and stability) and aero-thermodynamic properties. The method provides automatic generation of geometry and analysis grids (meshes) rapidly created from a small set of parameters, which can be interpreted in a straightforward and intuitive manner. The vehicle shapes are known as Co-Optimized Blunt Re-Entry Aero (COBRA) geometries. A key advantage for design work is that this approach uses a parameterization that fully defines the vehicle shape without need for human intervention and is thus suitable for rapid automated optimization methods. The method automatically produces a Pareto optimized subset, from which human judgement can then be used to further explore this optimum set and down select to a particular vehicle concept based on trajectory, thermal protection sizing, structural sizing and final vehicle closure.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_200","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-200","sourceUrl":"https://technology.nasa.gov/patent/TOP2-200","confidence":"high"},"type":"patent","title":"Green aviation - improved aerodynamic efficiency and less fuel burn","abstract":"NASA has created and combined two new concepts aircraft aerodynamic control surfaces and active wing-shaping control to reduce aircraft drag and lower fuel consumption. The first concept is referred to as a variable camber continuous trailing edge flap or, alternatively, a variable camber continuous leading edge slat. Aerodynamic simulations and wind tunnel experiments have shown that this type of flap can reduce aerodynamic drag substantially as compared to a conventional flap. The second element is a new active wing-shaping control concept that is proposed in connection with the presently disclosed variable camber continuous trailing edge flap (or leading edge slat). The active wing-shaping control is designed to aeroelastically change a wing shape in-flight in order to achieve a desired wing shape for optimal drag reduction.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_237","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-237","sourceUrl":"https://technology.nasa.gov/patent/TOP2-237","confidence":"high"},"type":"patent","title":"Unmanned Aerial Systems (UAS) Traffic Management","abstract":"To enable significant commercial use of Unmanned Aerial Systems (UASs) within lower altitude airspace and airspace that does not interfere with regular National Airspace System (NAS) operations, an Unmanned Aerial Systems (UAS) Traffic Management (UTM) system is required. Such UTM system needs to support flight route adjustments of UASs that are encountering conflicts. NASA Ames Research Center has developed a traffic management system for Unmanned Aerial Systems (UASs) to maintain safe and efficient UAS operations. This novel technology can help provide solutions to these and other problems by implementing an Autonomous Situation Awareness Platform (ASAP) into UASs to allow them to autonomously resolve conflicts by UAS-to-UAS communications and onboard flight management systems, while maintaining integration with the National Airspace System. The technology enables the growth in civilian applications of UAS operations at lower altitudes by developing a UAS Traffic Management (UTM) system. There are a number of applications of UAS which includes goods and services delivery in urban, difficult terrain and rural areas, imaging and surveillance for agricultural, and utility management.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_258","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-258","sourceUrl":"https://technology.nasa.gov/patent/TOP2-258","confidence":"high"},"type":"patent","title":"Method and System for Air Traffic Rerouting for Air-space Constraint Resolution","abstract":"NASA Ames Research Center's National Airspace System (NAS) Constraint Evaluation and Notification Tool (NASCENT) is a dynamic, ground-based, airspace constraint avoidance system that automatically analyzes routes of flying or predeparture aircraft, in or near constrained regions (due to weather, Special Use Airspace (SUA), etc.) It continuously analyzes time and fuel efficient reroutes around current and predicted constraints for thousands of flights in real-time. NASCENT provides an evaluation of operationally viable and historically implemented routes that save more than a user-specified number of minutes of wind-corrected flying time savings, for all the 20 Air Route Traffic Control Centers (ARTCCs or Centers) in the NAS, simultaneously. The system includes a flexible and intuitive graphical user interface that allows users to visualize, evaluate, modify (rubber-banding functionality), if necessary, and implement proposed reroutes (under current operational procedures).","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_271","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-271","sourceUrl":"https://technology.nasa.gov/patent/TOP2-271","confidence":"high"},"type":"patent","title":"Airborne Background Oriented Schlieren Technique","abstract":"NASA has developed a novel method to render visible the density changes in air that cause a refractive index change by an airborne vehicle. These density changes include shock waves, vortices, engine exhaust, and wakes. The determination of location and strength of shockwaves and vortices is fundamental to understanding the flow around an aircraft. These features are strong enough to affect the environment that the vehicle inhabits: for example, they can cause drag and/or produce undesirable noise. The researcher must be able to predict and mitigate the effects of these flow features. This invention is a robust visualization technique that will permit the measurement of the strengths and positions of shock waves caused by supersonic vehicles. The technique is applicable to all flight regimes, however, and can be used for visualizing tip vortices, engine exhaust plumes.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_272","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-272","sourceUrl":"https://technology.nasa.gov/patent/TOP2-272","confidence":"high"},"type":"patent","title":"Method for Transferring a Spacecraft from Geosynchronous Transfer Orbit to Lunar Orbit","abstract":"This novel innovation from Ames Research Center allows spacecraft to share rides with larger spacecraft which are headed to Geosynchronous Earth Orbit (GEO). The secondary spacecraft is dropped off Geosynchronous Transfer Orbit (GTO) at any time during the day or year and will subsequently enter lunar orbit, with no constraint on the lunar orbit inclination. The secondary spacecraft can be relatively small, riding as a secondary payload with a larger primary spacecraft . The secondary spacecraft is intended to be controllable (i.e., maneuverable).","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_273","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-273","sourceUrl":"https://technology.nasa.gov/patent/TOP2-273","confidence":"high"},"type":"patent","title":"Flight Awareness Collaboration Tool (FACT)","abstract":"Winter weather such as snow, freezing precipitation, and ice can impact airport surface operations. These conditions may result in significant disruptions in arrival and departure rates. To address these issues, NASA Ames Research Center has developed a software application called the Flight Awareness Collaboration Tool (FACT). This tool is designed to reduce the number of unnecessary flight cancellations by improving situation awareness of an impending winter weather event and its effects on airports. FACT provides the necessary data for decision making and supports collaboration between the organizations involved in managing flight and airport operations. It gathers the information necessary for winter weather management into one location and has predictive tools. Being web-based, it can be available to multiple users.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_274","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-274","sourceUrl":"https://technology.nasa.gov/patent/TOP2-274","confidence":"high"},"type":"patent","title":"Affordable Vehicle Avionics (AVA)","abstract":"NASA Ames Research Center has developed a novel low-cost, self-contained Guidance, Navigation and Control (GNC) subsystem for developers and operators of small-payload Space Launch Vehicles (SLVs). Small satellites are becoming ever more capable of performing valuable missions for both government and commercial customers. However, currently these satellites can only be launched affordably as secondary payloads which makes it difficult for the small satellite mission to launch when needed into the desired orbit, and with acceptable risk. NASA's Affordable Vehicle Avionics (AVA) technology offers access to space for small-payload SLV operators with an ability to provide dedicated launch to Low Earth Orbit (LEO), when and where they need. AVA demonstrates a self-contained GNC subsystem that can be integrated and operated at a fraction of the recurring costs of existing units.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_279","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-279","sourceUrl":"https://technology.nasa.gov/patent/TOP2-279","confidence":"high"},"type":"patent","title":"Real-Time Drag Opti-mization Control Framework","abstract":"Fuel efficiency is a major aircraft design consideration. Current and future-generation aircraft wing technology is moving toward lightweight, flexible, and high aspect ratio wing design. Wing flexibility can adversely impact aircraft performance, structural integrity, stability, and control. The aerodynamic performance of the aircraft wings can vary greatly over the flight envelope too. Without changing the wing shapes, an increase in drag can incur during cruise, thereby, causing an increase in the fuel consumption, hence fuel cost. NASA Ames has developed a novel technology that is ideally suited for transport aircraft wings ranging from stiff metallic wings to flexible composite wings that are susceptible to aeroelastic deflections during flight. This enabling technology includes a method and process for optimizing drag in real-time using distributed flight control surfaces to change the shape of the wing in-flight, and helps counteract the aeroelastic effects introduced by flexible wings. This improves both aerodynamic performance and fuel efficiency.","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_282","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-282","sourceUrl":"https://technology.nasa.gov/patent/TOP2-282","confidence":"high"},"type":"patent","title":"Multi-Objective Flight Control Optimization Framework","abstract":"As aircraft wings become more flexible, adverse aerodynamic interactions with the wing structure can result in changes in the wing shapes due to aeroelastic deflections that can prevent the optimal aerodynamic performance from being realized. The flexible wing structure can also be more susceptible to vibration due to atmospheric turbulence and wind gusts which can affect passenger ride comfort and compromise the structural integrity. NASA Ames Research Center has developed a new multi-objective flight control optimization framework that can achieve multiple control objectives simultaneously. These control objectives comprise rigid-aircraft stability augmentation control, flexible mode suppression, drag optimization, and maneuver / gust load alleviation, while still maintaining traditional pilot command-tracking tasks. The technology addresses the operational constraints and the efficiency goal of modern transports simultaneously in order to arrive at optimal flight control solutions.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_297","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-297","sourceUrl":"https://technology.nasa.gov/patent/TOP2-297","confidence":"high"},"type":"patent","title":"Anti-Phase Noise Suppression Rotor Technologies","abstract":"All rotorcraft experience rotor noise and vibration that present operational challenges due to the unsteady forces that result from blade vortex shedding. Rotor noise is often a nuisance, and excessive rotor vibration can be hazardous. Several methods exist to deal with the noise and vibration from rotor blades, though many designs either aim to reduce vibration and do not address noise, or vice versa. NASA Ames Research Center has developed a novel patent-pending design and method for reducing rotor blade vibration and acoustic signatures in rotor systems using anti-phase blade vortex suppression design concepts. The design objective is to maximize reduction of noise perceived by the community while maintaining the aerodynamic thrust. These designs could be applicable in any system that uses rotor blades.","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_298","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-298","sourceUrl":"https://technology.nasa.gov/patent/TOP2-298","confidence":"high"},"type":"patent","title":"Vertiport Assessment and Mobility Operations System (VAMOS!)","abstract":"It is widely believed that Advanced Air Mobility (AAM) is poised to have a significant societal impact in the coming years to move people and cargo more rapidly and efficiently. The main goals of AAM vehicles are to reduce emissions, to increase connectivity and speed, while helping to reduce traffic congestion. These vehicles can take off and land vertically in designated urban locations called vertiports. The widespread adoption of AAM concept will necessitate vertiports to be located throughout a geographical region. There is a need to systematically evaluate and quantify which locations are better suited for vertiports and how these vertiports will work together in a network. NASA Ames Research Center has designed a novel technology called VAMOS! that evaluates a variety of factors, e.g., intermodal centers, environmental impact, zoning/land use, to determine the most suitable locations for vertiports in a desired city/region.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_303","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-303","sourceUrl":"https://technology.nasa.gov/patent/TOP2-303","confidence":"high"},"type":"patent","title":"Aerospace Vehicle Entry Flightpath Control","abstract":"The state-of-the-art in hypersonic entry Guidance and Control (G&C) is traditionally based on rigid entry vehicles, like the Orion capsule, Space Shuttle, etc., that use a Reaction Control System (RCS) to control the bank angle of the vehicle. However, for future high mass missions to Mars, advancements in hypersonic aerospace vehicle design, and evolving science goals, are stretching the performance capabilities of traditional entry systems. NASA\u2019s Pterodactyl team at Ames Research Center has developed a novel yaw-to-bank control system for a non-traditional vehicle configurations, such as a Deployable Entry Vehicle (DEV) that can be folded and stowed. The approach provides vehicle stabilization, steering, and precise targeted landing. This control architecture is agnostic to control actuators and can be used with any aerospace vehicle with a strong dihedral effect and/or different guidance control variables.","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_308","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-308","sourceUrl":"https://technology.nasa.gov/patent/TOP2-308","confidence":"high"},"type":"patent","title":"Active Turbulence Suppression System for Electric Vertical Take-Off and Landing (eVTOL) vehicles","abstract":"Electric Vertical Take-Off and Landing (eVTOL) aircraft, conceptualized to be used as air taxis for transporting cargo or passengers, are generally lighter in weight than jet-fueled aircraft, and fly at lower altitudes than commercial aircraft. These differences render them more susceptible to turbulence, leading to the possibility of instabilities such as Dutch-roll oscillations. In traditional fixed-wing aircraft, active mechanisms used to suppress oscillations include control surfaces such as flaps, ailerons, tabs, and rudders, but eVTOL aircraft do not have the control surfaces necessary for suppressing Dutch-roll oscillations. NASA Ames has developed a novel approach for actively controlling Dutch-roll oscillations of an eVTOL aircraft by using existing outboard propellers to dampen oscillations. This novel technology avoids the need to add hardware or change the design of eVTOL vehicles to address the negative effects of turbulence.","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_311","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-311","sourceUrl":"https://technology.nasa.gov/patent/TOP2-311","confidence":"high"},"type":"patent","title":"Spacecraft with Artificial Gravity Modules","abstract":"Space travel is becoming increasingly accessible in recent years with the advancement of private space programs as well as NASA space programs such as the Mars Exploration Program. For both space tourism and space exploration, there is an interest in generating artificial gravity in space for entertainment, recreational, and scientific purposes, as well as to counter the health concerns of extended exposure to a microgravity environment. Conventional systems for generating artificial gravity in space involve large rotating space stations that create an inertial force that mimics the effects of a gravitational force. In such examples, the entire space station rotates to generate the artificial gravity that creates several critical engineering and safety issues. NASA Ames Research Center has developed a novel technology that can help provide solutions to these and other problems by a system and approach for creating artificial gravity using a non-rotating spacecraft with connected moving modules, which can be used for habitation and other purposes.","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_313","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-313","sourceUrl":"https://technology.nasa.gov/patent/TOP2-313","confidence":"high"},"type":"patent","title":"Methods for Predicting Transonic Flutter Using Simple Data Models","abstract":"Aircraft moving at transonic speeds (i.e., ~0.7 to 0.85 Mach - or near the speed of sound) experience transonic wing flutter. Engineers have traditionally relied on experimental or computational methods to understand wing flutter for the design process. Modeling wing flutter using the customary computational methods require tens of hours of simulations on a supercomputer that are costly to buy or rent. Having a method to model wing flutter aerodynamics without requiring supercomputer use would (a) increase the efficiency and decrease the cost of aircraft wing design and (b) enable real-time wing-flutter modeling to aid in-flight aircraft operation and control. Ames Research Center has developed a novel closed-form solution to model wing flutter aerodynamics for any aircraft wing (within a certain thickness regime and without camber). This closed-form solution can be readily extended to wing sections with camber. The closed-form solution matches, in near real-time, the complex supercomputer simulations at a fraction of cost and time necessary to perform transonic flutter modeling for an airfoil.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_319","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-319","sourceUrl":"https://technology.nasa.gov/patent/TOP2-319","confidence":"high"},"type":"patent","title":"Wind-Optimal Cruise Airspeed Mode for Flight Management Systems (FMS)","abstract":"Energy-efficient flight is especially important for commercial viability of aviation. Even a small amount of fuel savings - 5% per flight - can be significant because of the scale of operations, with tens of thousands of flights per day in the US alone. Energy efficient flight planning is even more important for electric Vertical Takeoff and Landing (eVTOL) aircraft with battery powered distributed electric propulsion (DEP) systems because the low specific energy of the lithium-ion polymer (Li-Po) batteries necessitates energy-efficient flight planning. NASA\u2019s Ames Research Center has developed a novel speed mode for FMSs, a wind-optimal airspeed mode that optimizes route planning for minimum-energy usage based on actual and predicted wind conditions. Using real-time computation, an FMS can continuously update the wind-optimal airspeed target and try to maintain the optimal airspeed for current flight conditions for the entire cruise portion of the flight.","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_322","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-322","sourceUrl":"https://technology.nasa.gov/patent/TOP2-322","confidence":"high"},"type":"patent","title":"Vision-based Approach and Landing System (VALS)","abstract":"There are certain situations when landing an Advanced Air Mobility (AAM) aircraft is required to be performed without assistance from GPS data. For example, AAM aircraft flying in an urban environment with tall buildings and narrow canyons may affect the ability of the AAM aircraft to effectively use GPS to access a landing area. Incorporating a vision-based navigation method, NASA Ames has developed a novel Alternative Position, Navigation, and Timing (APNT) solution for AAM aircraft in environments where GPS is not available. The technology employs an aircraft -mounted camera to visually detect known features in the landing area, using a computer vision method called Coplanar Pose from Orthography and Scaling with Iterations (COPOSIT) to determine the position and orientation of the aircraft relative to the features detected from the camera images, and an extended Kalman filter to predict and correct the estimated position, velocity, and orientation of the aircraft .","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_325","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-325","sourceUrl":"https://technology.nasa.gov/patent/TOP2-325","confidence":"high"},"type":"patent","title":"Digital Twin Simulator of the National Airspace System (NAS)","abstract":"The National Airspace System (NAS) is a challenging system of systems to study and monitor due to the volume of data passing through at any given time, including all information, services, rules, regulations, policies, procedures, personnel, and equipment required to manage flight operations within the United States. Developing and running simulations of the NAS relies on the cumulative experience of engineering teams. Variances in the simulations due to differences in assumptions, software, hardware, and models make results difficult to control and reproduce. New features to be added to the NAS require testing in a time-consuming and iterative process that can delay implementation of new technologies, management protocols, and safety measures. NASA Ames has developed a novel approach for simulating the NAS by using a digital twin simulator. This novel technology can simulate a duplication of the live NAS system, and can test and simulate integration of new elements. The digital twin NAS system can also be used to test high-fidelity models of autonomous systems to validate the operation of such autonomous systems safely interacting with the NAS system.","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_326","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-326","sourceUrl":"https://technology.nasa.gov/patent/TOP2-326","confidence":"high"},"type":"patent","title":"Method And System for Enhancing Vehicle Performance and Design Using Parametric Modeling and Gradient-Based Control Integration","abstract":"Aerospace vehicles, including aircraft, spacecraft, and autonomous systems, require a balance of physical and control systems to achieve optimal performance. Traditional design approaches treat physical and control parameters separately, leading to suboptimal designs that may not meet stringent operational requirements under real-world conditions. NASA Ames has developed a novel parametric modeling approach that integrates physical design (e.g., geometry, structural load) with guidance, navigation, and control (GNC) systems, allowing for the co-optimization of these subsystems. This innovative technique applies multi-variable calculus and gradient-based methods to iterate on design parameters, enabling aerospace vehicles to achieve better performance, stability, and fuel efficiency. The technology reduces the development time and ensures a more robust design by accounting for real-world variables such as aerodynamic uncertainties, environmental disturbances, and sensor noise.","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_327","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-327","sourceUrl":"https://technology.nasa.gov/patent/TOP2-327","confidence":"high"},"type":"patent","title":"Aerodynamic Framework for Parachute Deployment from Aerial Vehicle","abstract":"Electric Vertical Take-Off and Landing (eVTOL) aircraft, conceptualized to be used as air taxis for transporting cargo or passengers, are not traditionally designed to glide to a safe landing following propulsion failure. As these aircraft may operate either in populated areas or with passengers onboard, safety measures such as parachutes must be designed and tested for safe landing during air taxi failure. In-silico design processes that employ validated computer simulations are useful for early design and testing prior to physical prototyping. However, current computational fluid dynamics (CFD) solvers can be computationally expensive and time-consuming. NASA Ames has developed a CFD based rapid simulation framework for parachute deployment from air taxis in a simulated flight by generating a database of simulated accurate aerodynamic data to be used in place of on-the-fly flow simulations, thus enabling rapid simulation and design processes.","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_329","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-329","sourceUrl":"https://technology.nasa.gov/patent/TOP2-329","confidence":"high"},"type":"patent","title":"Elastic Shape Morphing of Ultra-Light Structures by Programmable Assembly","abstract":"Aerostructure parts made from ultra-light materials, such as a lattice covered by a skin, present an opportunity to dramatically increase the efficiency of load bearing aerostructures. NASA Ames Research Center has been developing lighter-than-air vehicle and structure concepts using octahedral unit cells called voxels that are the building blocks for creating larger aerostructures. This novel addition to the family of technologies introduces interface parts to connect a skin to a voxel substructure. The skin is designed to transfer aerodynamic pressure loads directly to the substructure through the interface parts. The parts can be tuned to achieve aerodynamic efficiency gains through substructure programmability. The substructure can be morphed by aeroelastic tuning to increase aerodynamic efficiency. Tuning the substructure\u2019s torsional stiffness response can also program the anisotropic substructure stiffness to promote tip twist under aerodynamic loads.","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_330","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-330","sourceUrl":"https://technology.nasa.gov/patent/TOP2-330","confidence":"high"},"type":"patent","title":"Multistage Free-Flight Testing System","abstract":"During atmospheric entry of blunt-body vehicles, such as a crew capsule or planetary probe, travel through the supersonic and transonic regimes can induce divergent instabilities due to dynamic stability issues, the fundamental understanding of which remains incomplete. Traditional qualification methods such as ballistic ranges, wind tunnels, and computation simulations can provide aerodynamic performance data for various flight conditions, but each has limitations or requires extensive validation. To address the need to understand dynamic stability issues of re-entry vehicles, NASA Ames has developed a multistage flight system architecture capable of testing vehicles through supersonic and transonic Mach numbers. This architecture enables the acquisition of rich, flight-relevant data related to dynamic stability and other key aerodynamic parameters.","category":"aerospace","categoryRaw":"Aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_us10514454b1","source":{"institution":"NASA","subUnit":"FAA","subUnitCode":"FAA","nativeId":"US10514454B1","sourceUrl":"https://technology.nasa.gov/patent/US10514454B1","confidence":"high"},"type":"patent","title":"Adaptive Radar Thresholding for Cluttered Environments","abstract":"Teams at the Federal Aviation Administration have developed a patented radar enhancement technology that improves detection accuracy in environments where large, complex structures such as wind turbines interfere with conventional radar . By dynamically adjusting detection thresholds using both real-time and historical radar data, the system distinguishes genuine targets from environmental clutter. This minimizes false alarms while maintaining the sensitivity needed for safe and effective operation in applications such as air traffic control, national defense, and autonomous systems.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_us11579103b2","source":{"institution":"NASA","subUnit":"FAA","subUnitCode":"FAA","nativeId":"US11579103B2","sourceUrl":"https://technology.nasa.gov/patent/US11579103B2","confidence":"high"},"type":"patent","title":"Microscale Fire Calorimeter for Combustion and Toxicity Testing","abstract":"The Federal Aviation Administration have patented a method that enables precise, flame-free analysis of fire chemistry using milligram-scale material samples in a Microscale Fire Calorimeter (MFC). By premixing pyrolysis gases from a heated sample with oxygen under tightly controlled conditions, the system replicates various fire stages from oxygen-rich to oxygen-starved allowing researchers to evaluate the combustion byproducts and their toxicity. This innovation allows for highly efficient and safe flammability testing of solid materials, offering insights critical to public safety, environmental protection, and material design.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_us11847923b2","source":{"institution":"NASA","subUnit":"FAA","subUnitCode":"FAA","nativeId":"US11847923B2","sourceUrl":"https://technology.nasa.gov/patent/US11847923B2","confidence":"high"},"type":"patent","title":"Universal Data Compiler for Drone, Sensor, and System Data Integration","abstract":"The Universal Data Compiler (UDC) is a flexible, data-agnostic platform designed to integrate, process, and analyze information from diverse Unmanned Aircraft Systems (UAS). Developed by the Federal Aviation Administration, the UDC seamlessly consolidates data streams from multiple drone types and sensors, offering automatic configuration, priority-driven task execution, and customizable reporting. This innovation enables improved operational coordination, mission planning, and decision-making in complex environments such as emergency response, agriculture, and infrastructure monitoring.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_us12230143b1","source":{"institution":"NASA","subUnit":"FAA","subUnitCode":"FAA","nativeId":"US12230143B1","sourceUrl":"https://technology.nasa.gov/patent/US12230143B1","confidence":"high"},"type":"patent","title":"Multi-Protocol Remote Monitoring for Radio Networks","abstract":"Teams at the Federal Aviation Administration have developed an innovative system that enables continuous remote monitoring and control of communications equipment that use diverse protocols in an air traffic management or radio network environment. The system eliminates the need for on-site troubleshooting by allowing remote diagnostics, power control, and compatibility management. It is designed to improve safety, reduce downtime, and increase operational efficiency in complex, distributed networks.","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_us20250224279a1","source":{"institution":"NASA","subUnit":"FAA","subUnitCode":"FAA","nativeId":"US20250224279A1","sourceUrl":"https://technology.nasa.gov/patent/US20250224279A1","confidence":"high"},"type":"patent","title":"Advanced Fire Detection for Aircraft Cargo Holds","abstract":"This innovation improves how fires are detected in aircraft cargo compartments by using dynamic, time-based sensor analysis instead of relying on static thresholds. By intelligently interpreting temperature data over time, this system reduces false alarms while enabling earlier and more accurate fire detection. This is critical for ensuring passenger safety and protecting cargo in pressurized, hard-to-access environments","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_us8604965b2","source":{"institution":"NASA","subUnit":"FAA","subUnitCode":"FAA","nativeId":"US8604965B2","sourceUrl":"https://technology.nasa.gov/patent/US8604965B2","confidence":"high"},"type":"patent","title":"Virtual Aircraft Target Generator for ADS-B Testing","abstract":"This patented system, developed by the Federal Aviation Administration, enables the generation of virtual aircraft targets for safe and efficient testing of avionics systems, such as satellite-based surveillance, including ADS-B. By simulating real aircraft using RF signals embedded with synthetic GPS data, the system allows flight crews and developers to validate surveillance system performance in realistic but controlled environments without deploying additional aircraft .","category":"aerospace","categoryRaw":"aerospace","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_356","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-356","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-356","confidence":"high"},"type":"patent","title":"Improved High-Speed FPGA Optical Transmitter","abstract":"Engineers at NASA\u2019s Goddard Space Flight Center have created an algorithm that improves Field Programmable Gate Array (FPGA) optical transmitters used in optical modems. The algorithm aligns multiple high-speed FPGA transmitter channels upon power-up to deskew or minimize channel distortions in the optical modem system. This novel FPGA transmitter design directly drives the optical modulator differently from more conventional approaches based on Digital to Analog Converters (DACs) or other external drivers. By eliminating use of DACs or other such components, this innovation reduces power consumption and component costs while improving reliability. This technology is designed to enable FPGAs to directly drive the optical Quadrature phase shift keying (QPSK) modulators used for data communications in optical modems.","category":"communications","categoryRaw":"Communications","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_361","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-361","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-361","confidence":"high"},"type":"patent","title":"High Performance, All-Metal X-Band Patch Antenna","abstract":"Innovators at NASA\u2019s Goddard Space Flight Center have developed an all-metal, X-band patch antenna with built in choke rings and a polarizer circuit to meet the stringent requirements of high-precision space navigation antennas for the Geodetic Reference Instrument Transponder for Small Satellites (GRITSS) mission. GRITSS required a low-gain antenna with strong multipath mitigation and a stable phase center. Typical dielectric-patch antennas can be high-loss, susceptible to manufacturing variability, have limited power handling ability, and are temperature sensitive. Compared to commercially available path antennas, NASA\u2019s antenna is more rugged, provides a high front-to-back ratio, mitigates multipath signal interference, and is capable of higher power handling. NASA\u2019s X-band antenna was designed to be mounted on a CubeSat but has the potential of being mounted on terrestrial aircraft and vehicles for either communication or radar applications.","category":"communications","categoryRaw":"Communications","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_366","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-366","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-366","confidence":"high"},"type":"patent","title":"Integrated-Photonic Electromagnetic Signal Detector","abstract":"In remote sensing and communication systems, designers constantly face the challenge of maintaining high detection sensitivity while minimizing Size, Weight, Power consumption, and Cost (SWaP-C). Small satellites and portable communication devices, for instance, have strict size and power constraints yet require accurate detection of electromagnetic signals across microwave to millimeter-wave frequencies. Although electronics-based receivers can provide excellent performance, their components tend to increase both power consumption and overall device footprint. Developed at NASA\u2019s Goddard Space Flight Center, the Integrated-Photonic Electromagnetic Signal Detector (ESD) addresses these challenges by integrating photonic crystal technology with an electro-optic (EO) polymer and a compact antenna structure to achieve miniaturization without sacrificing precision. Furthermore, by converting an incoming electromagnetic signal into an optical domain response, the device significantly reduces reliance on traditional electronics. Thus, this NASA innovation is a promising solution for high-performance sensing or communications applications where minimized SWaP-C is essential.","category":"communications","categoryRaw":"Communications","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_369","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-369","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-369","confidence":"high"},"type":"patent","title":"Computer-Brain Interface for Display Control","abstract":"NASA has developed a novel brain-computer display interface to improve a user\u2019s ability to interact with a computer by automatically and continuously locating the position of the user\u2019s gaze on a computer display. This interaction can significantly increase the user\u2019s ability to communicate with the computer and the systems the computer controls. Compared to commercial optical eye tracking devices, the NASA innovation relies on matching signals from the visual cortex region of the brain to invisible signals embedded in the display information to directly determine the location on the display where the user is looking. A few electrodes arranged over the back part of the user\u2019s head are used to capture these brain signals. Importantly, the NASA innovation indicates eye gaze location only on the area of the display where the user is focused or paying attention, not simply where the user is looking. This technology may be paired with other eye gaze technology to provide robust gaze tracking without requiring the user to calibrate the gaze tracking system. The inventors developed this innovation specifically for aircraft and space vehicle cockpits where users rely heavily on computer display interaction but also have many other competing distractions and actions.","category":"communications","categoryRaw":"Communications","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_108","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-108","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-108","confidence":"high"},"type":"patent","title":"Secure Optical Quantum Communications","abstract":"NASA's Glenn Research Center has developed a method of using entangled-photon pairs to produce highly secure mobile communications that require mere milliwatts of power. Conventional gas Argon-ion laser sources are too large, expensive, and power-intensive to use in portable applications. By contrast, Glenn's patented optical quantum communication method produces entangled-photon pairs approximately a million times more efficiently than conventional sources, in a system that is small and light enough to be portable. Furthermore, because this method transmits digital information by detecting small temporal shifts between entangled photons, its superior signal-to-noise ratio facilitates highly secure communications in very noisy free space and fiber-optic environments. Originally developed for micro-robots used for deep space exploration, this technology represents a breakthrough for a wide variety of terrestrial, scientific, military, and other field-deployable applications including fiber-optic and satellite communications.","category":"communications","categoryRaw":"communications","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_113","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-113","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-113","confidence":"high"},"type":"patent","title":"Signal Combiner for Wideband Communication","abstract":"Innovators at NASA's Glenn Research Center have devised an efficient new method of combining primary and secondary signals with minimal loss and noise. Exploiting non-traditional uses of frequency domain multiplexers and analog-to-digital converters (ADC), Glenn's secondary signal combiner uses a frequency multiplexer in the analog domain and wideband ADC to combine electromagnetic signals (primarily MHz to GHz) with extremely low loss for both signals thereby reducing noise. With its ability to reduce system noise, this novel signal combiner delivers the best opportunity to receive a desired signal not easily distinguished from background noise. While Glenn's new technology will form part of the front-end for a new software-defined radio in ground stations, it is also poised to be an important piece in telecommunications devices, including cell phones, Wi-Fi, hot spots, satellites, and future wireless technologies.","category":"communications","categoryRaw":"communications","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_118","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-118","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-118","confidence":"high"},"type":"patent","title":"The Teletenna - A Hybrid Telescope Antenna System","abstract":"Innovators at NASA's Glenn Research Center have developed a hybrid telescope antenna system - Teletenna - to deliver high data-rate communication over great distances. Teletenna has the potential to benefit deep space missions and communications on Earth. By combining two very different communications systems - optics and radio frequency (RF) - Teletenna capitalizes on the benefits of each system while overcoming conflicting engineering requirements. Teletenna is a breakthrough innovation, particularly in the field of Deep Space Optical Communications (DSOC), in which it could deliver high-definition imagery, live video feed, and real time data-transmission 10 to 100 times faster than current state-of-the-art technology. Teletenna supports beaconless pointing, remains nearly transparent to RF, and achieves an unprecedented level of data richness and bandwidth. This exceptionally lightweight and precise instrument stands ready to revolutionize deep space exploration, satellite communications, telecommunications, and more.","category":"communications","categoryRaw":"communications","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_147","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-147","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-147","confidence":"high"},"type":"patent","title":"Vortex Radiometer for Wireless Communications","abstract":"Innovators at the NASA Glenn Research Center have developed the Vortex Radiometer (VR), an early-warning system for communication antennas that identifies atmospheric noise before it reaches the antenna and then optimizes mitigation strategies. Communication links are subject to atmospheric effects that reduce the signal power received at the antenna (i.e., a fade). If the atmospheric losses are too high, the signal level could drop below the minimum measurable power of the receiver, causing data loss across the communication link. Previous attempts to forewarn fading using predictive algorithms have yielded sub-optimal results largely because they rely on real-time performance data from the communications link itself, meaning they have very little time to respond. By contrast, NASA's VR constantly senses incoming noise, which allows real-time measurement and characterization of fading and enables maximization of data throughput.","category":"communications","categoryRaw":"communications","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_148","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-148","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-148","confidence":"high"},"type":"patent","title":"Cascaded Offset Optical Modulator","abstract":"Innovators at the NASA Glenn Research Center have developed the Cascaded Offset Optical Modulator, an electro- optic subsystem used to interface a binary output Software Defined Radio (SDR) to an optical transmission system. Traditionally, this task is accomplished through the use of a Mach Zehnder Modulator (MZM), a primarily analog component. In order to generate a high-fidelity optical signal, the input electrical signal must be of equally high fidelity, which is a difficult task due to the competing requirements of the digital components and the analog modulator. The digital components required to generate the waveform contain non-idealities which degrade the extinction ratio (ER) of the optical signal. The Cascaded Offset Optical Modulator corrects these non-idealities in the electro- optic subsystem during modulation by relieving the SDR of the extreme fidelity requirements imposed by the optical modulator. This approach is valid in any optical transmission system that requires high fidelity binary pulses without a complex component.","category":"communications","categoryRaw":"communications","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_155","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-155","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-155","confidence":"high"},"type":"patent","title":"Conformal, Lightweight, Aerogel-Based Antenna","abstract":"Innovators at the NASA Glenn Research Center have developed the Conformal, Lightweight Antenna for Aeronautical Communications Technology (CLAS-ACT), an active phased array antenna for Ku-band satellite communications on a mobile platform such as a UAV. The CLAS-ACT was developed for UAVs that require operations outside of radio line of sight which use a satellite link to increase operational coverage for command and control. The satellites typically used for this application fly a geostationary orbit at a very high altitude. The current state of practice for UAVs travelling out of line of sight is to use a large parabolic dish antenna that is pointed with a mechanical gimbal; this requires a significant volume within the UAV, adds unnecessary weight, and demands a large amount power. NASA's CLAS-ACT antenna improves upon current practice by offering a lightweight, small-sized antenna that can be mounted on the curved frame of an aircraft and has advanced beam steering/beam synthesis capabilities, enabling the efficient command and control of small or large UAVs used for a variety of purposes.","category":"communications","categoryRaw":"Communications","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_163","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-163","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-163","confidence":"high"},"type":"patent","title":"Optical Transceiver Method of QKD Encryption Suite of Technologies","abstract":"Overview The process of Quantum Key Distribution (QKD) produces variable length symmetric bit strings at both communication nodes for each QKD operation. This system combines several technologies developed at NASA\u2019s Glenn Research Center to create a secure, practical, and efficient optical transceiver system for QKD. The system uses a Space-And-Wave (SAW) division method to separate low-energy QKD photons from high-energy data transmissions. Unlike traditional methods that use entangled photons, this approach sends and receives encryption keys using weak coherent pulsed light and can be applied to the encryption of any free space optical communications. The technology includes methods for generating a random basis set on demand and for converting variable-length quantum keys into fixed-length keys compatible with mainstream symmetric encryption schemes.","category":"communications","categoryRaw":"Communications","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_178","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-178","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-178","confidence":"high"},"type":"patent","title":"Boosting Quantum Communication Efficiency","abstract":"NASA\u2019s new source array may help revolutionize quantum communication by addressing a fundamental challenge: the unwanted production of multiple entangled photon pairs that introduce noise and degrade transmission. This innovative quantum entanglement source array generates single pairs of entangled photons at a very high rate while inhibiting the production of multiple pairs. By eliminating excess photon pairs, the new source array significantly reduces noise in quantum systems, increasing the successful qubit transmission rate by a factor of 10 to 100. This breakthrough paves the way for more efficient and reliable quantum networks, supporting secure communication, sensor arrays, and quantum computer networks. As the quantum technology sector rapidly expands, the new source array offers a crucial advantage for companies looking to lead in quantum communications, with potential applications in cybersecurity, finance, and advanced computing. By addressing a key limitation in current photon sources, the source array positions itself as a cornerstone for the future of quantum information transmission. This NASA Technology is available for your company to license and develop into a commercial product. NASA does not manufacture products for commercial sale.","category":"communications","categoryRaw":"Communications","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_24","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-24","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-24","confidence":"high"},"type":"patent","title":"NanoWire Glass Switch for Radio Frequency","abstract":"NASA's Glenn Research Center has developed nanoionics-based radio frequency (RF) switches for use in devices that rely on low power RF transmissions, such as automotive systems, RFID technology, and smart phones. These groundbreaking nanoionic switches operate at speeds of semiconductor switches and are more reliable than microelectromechanical systems (MEMS) switches, while retaining the superior RF performance and low power consumption found in MEMS all without the need for higher electrical voltages. In this new process, metals are photo-dissolved into a chalcogenide glass and packaged with electrodes and a substrate to form a switch. Since the nanoionics-based switch is electrochemical in nature, it has certain advantages over switches that are mechanically based, including non-volatility, lack of moving parts that can fail, ease and efficiency of activation, and ease of fabrication. This innovative device has the potential to replace MEMS and semiconductors in a wide range of switching systems, including rectifying antennas (rectennas) and other RF antenna arrays.","category":"communications","categoryRaw":"communications","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_63","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-63","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-63","confidence":"high"},"type":"patent","title":"Optical Tunable-Based Transmitter for Multiple High-Frequency Bands","abstract":"As the demand grows for more radio frequency (RF) carrier bands in space communication systems, so does the need for a cost-effective compact optical transmitter that is capable of efficiently transmitting multiple RF bands. Traditionally, when a satellite transmits to another satellite or a ground station, a separate terminal with a corresponding antenna is needed for each radio frequency band. Equipment becomes more complex as frequencies get higher. At the higher bands, large heat sinks are needed to dissipate the waste heat. Now, however, innovators at NASA's Glenn Research Center have successfully developed a method using a single laser beam to combine and transmit - all in one unit - multiple microwave bands with different modulation formats and bandwidths. This breakthrough benefits space communication systems in important ways, including reduced size, weight, and complexity, with consequent savings in cost. With additional development, the technology could be extended to fiber optic systems for terrestrial applications.","category":"communications","categoryRaw":"Communications","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_91","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-91","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-91","confidence":"high"},"type":"patent","title":"Multimode Directional Coupler","abstract":"Researchers at NASA's Glenn Research Center have patented a novel multimode directional coupler (MDC). This rugged and easily constructed waveguide is used to extract second- or higher-order harmonics, which are generally unused but contain sufficient power to be amplified and transmitted to a receiving station on Earth. Glenn's innovators developed the MDC as a means to extract signal harmonics from a satellite transmitter, with minimum perturbation to a fundamental frequency. The ability of the MDC to allow the fundamental frequency to propagate with negligible power losses makes it a substantial upgrade over the conventional diplexer. Glenn's MDC offers an innovative way to increase the number of terrestrial stations that can receive signals from a single satellite , potentially increasing the return on the investment involved in launching and maintaining satellites.","category":"communications","categoryRaw":"communications","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_95","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-95","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-95","confidence":"high"},"type":"patent","title":"Tunable Multi-Tone, Multi-Band, High-Frequency Synthesizer","abstract":"Innovators at NASA's Glenn Research Center have developed a multi-tone, multi-band, high frequency synthesizer that enables unprecedented satellite communications and atmospheric studies. Because of the increased congestion at currently used frequency bands, it would be game-changing to open other millimeter-wave frequency bands for satellite communications with stations on Earth. When used as part of a CubeSat beacon transmitter, the synthesizer would enable rigorous characterization of atmospheric effects (e.g., rainfall, climate change, hurricane monitoring, cloud cover, and gaseous adsorption). Although the synthesizer can be used on other platforms, the use of the CubeSat allows these studies to be conducted without the huge expense of a larger satellite . The synthesizer can also be used for space-borne active remote sensors such as scatterometers.","category":"communications","categoryRaw":"communications","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_113","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-113","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-113","confidence":"high"},"type":"patent","title":"Lightweight, Self-Deployable Helical Antenna","abstract":"SmallSats are experiencing increasing adoption in the satellite industry. While initially used primarily for technology demonstrations in low Earth orbit (LEO), enhanced capabilities have enabled SmallSat use for a broad number of applications. Today, sending small spacecraft beyond LEO to Lunar or deep space environments is attracting both scientific and commercial interest. Such missions are mass and volume constrained, yet must provide high data rate communications. Historically, patch antennas have been used for SmallSat communications. While new antenna technologies are in development, some are not optimized for size, mass, and performance - especially beyond LEO. Engineers at NASA's Marshall Space Flight Center identified the need for a small form factor antenna to provide high data rate communications for such missions. In response, they developed a self-deployable helical antenna that is lightweight, low volume, and has low stowage thickness while delivering high data rate performance.","category":"communications","categoryRaw":"Communications","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_90","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-90","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-90","confidence":"high"},"type":"patent","title":"Multi-and Wide-Band Single-Feed Patch Antenna","abstract":"Researchers at NASA's Marshall Space Flight Center have developed a novel patch antenna technology. This simple antenna design provides significant benefits to NASA satellite communication applications, offering a unique wide-band/multi-band operating capability. For other commercial space or non-space applications, the antenna design also offers broad-band capability with high gain for applications where signal strength, and smaller antenna sizes are important. The technology was developed to address challenges at NASA created by the need to design antennas for satellites where the target communication frequency is unknown or unassigned.","category":"communications","categoryRaw":"Communications","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_32","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-32","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-32","confidence":"high"},"type":"patent","title":"Real-Time Tracking System","abstract":"A real-time locating system (RTLS) developed at the Johnson Space Center uses ultra-wideband (UWB) radio frequency (RF) signals for tracking and reporting the position of transmitter-equipped people and objects. The technology has 100 to 1,000 times finer granularity than conventional narrowband RF RTLS systems and achieves a tracking resolution of less than 1 percent of the range (tested up to 3,500 feet). The technology has a number of commercial applications including long-range tracking of emergency, military, and mining personnel in limited access or hostile environments where global positioning systems are not reliable. This method combines the advantages of accurate Time Difference of Arrival (TDOA) information achieved using UWB technology with the geometric advantages of two-cluster tracking to provide accurate location information at long ranges. This NASA Technology is available for your company to license and develop into a commercial product. NASA does not manufacture products for commercial sale.","category":"communications","categoryRaw":"Communications","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_72","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-72","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-72","confidence":"high"},"type":"patent","title":"Smart Enclosure using RFID for Inventory Tracking","abstract":"The NASA Johnson Space Center has developed a method for tracking collections of items in a smart container using radio -frequency identification (RFID) tags with a high level of read accuracy. Automating the tracking of a collection of items (particularly small items) represents a major industrial hurdle due to both tag size and cost. This technology promises to successfully address these hurdles. The smart enclosure innovation can track individual items in the smart containers regardless of item placement, or on conveyor belts. The technology improves the read accuracy of items moving on, for example, a conveyor belt, which in turn can enable the use of smaller, lower cost tags. The NASA patented technology is available for licensing. This NASA Technology is available for your company to license and develop into a commercial product. NASA does not manufacture products for commercial sale.","category":"communications","categoryRaw":"communications","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_248","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-248","sourceUrl":"https://technology.nasa.gov/patent/TOP2-248","confidence":"high"},"type":"patent","title":"Space Optical Communications Using Laser Beams","abstract":"NASA has developed a new laser beam pointing technology for use in space optical communications. With further development, possible applications include communications from the Earth to spacecraft in Earth orbit and in deep space, such as at the moon and Mars. A possible application is to the Artemis Program for CubeSats in low-Lunar Orbit (LLO). Current architectures use dynamical systems, (i.e., moving parts, e.g., fast-steering mirrors (FSM), and/or gimbals,) to turn the laser to point to the ground terminal and possibly use vibration isolation platforms (VIP). This patented technology from NASA Ames uses a combined lens system and a vertical-cavity surface-emitting laser (VCSEL)/Photodetector Array. This static system has the potential to replace the current dynamic systems and VIP, dependent on studies for the particular application. Laser beam pointing is very challenging for low-Earth Orbit (LEO), including science missions. Computer simulations using this design have been made for an application to a CubeSat in LEO.","category":"communications","categoryRaw":"communications","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_287","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-287","sourceUrl":"https://technology.nasa.gov/patent/TOP2-287","confidence":"high"},"type":"patent","title":"Fine-pointing Optical Communication System Using Laser Arrays","abstract":"NASA Ames has developed a novel system in its portfolio for optical data transmissions from satellites using laser arrays for laser beam pointing. It is a fine pointing capability for laser beam pointing to augment body pointing by CubeSats in Low Orbit Earth (LEO). It is simple, static and compact. It combines a small lens system and a vertical-cavity surface-emitting laser (VCSEL)/Photodetector Array in a novel way for laser beam pointing. Body pointing was used earlier for CubeSats in LEO in NASA's Optical Communications and Sensors Demonstration (OCSD) program [1]. This fine pointing capability was computer simulated for the CubeSats used in the OCSD program [2,3]. With fine pointing, the spot size on the Earth was reduced by a factor of eight with a reduction in laser output power by a factor of sixty-four, thereby mitigating the thermal load challenge on the OCSD CubeSats.","category":"communications","categoryRaw":"communications","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_134","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-134","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-134","confidence":"high"},"type":"patent","title":"Gated Chopper Integrator (GCI)","abstract":"NASAs Goddard Space Flight Center has developed an innovative technique for amplification of microvolt level signals requires gains of at least a thousand. Offsets and noise in the amplifier chain will be amplified by the same amount which can saturate the amplifier or swamp the signal so that it is not resolvable. Other methods use chopping and/or autozero techniques to lower the offset and noise. The key disadvantages of these methods are they require filters before and/or after demodulation of the amplified signal and delay equalization to account for the delay through the amplifier(s) prior to the demodulator. The gain of these circuits is generally limited to fixed values determined by resistors. These methods are also susceptible to transient noise associated with the switching action of the modulator.","category":"electronics","categoryRaw":"electrical and electronics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_179","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-179","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-179","confidence":"high"},"type":"patent","title":"Smooth-Walled Feed Horn","abstract":"NASA Goddard Space Flight Center has developed a smooth-walled feed horn that addresses the fabrication issues inherent in constructing corrugated feed horns. Corrugated feed horns offer excellent beam symmetry, main beam efficiency, and cross-polar response over wide bandwidths. However, these feed horns can be challenging to manufacture. Our technology is a smooth-walled feed horn that approximates the properties of a corrugated feed horn over a finite bandwidth, while being easier to fabricate. The novel feed horn provides diffraction-limited ~14 degree FWHM, with low cross polarization.","category":"electronics","categoryRaw":"electrical and electronics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_302","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-302","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-302","confidence":"high"},"type":"patent","title":"Serial Arrayed Waveguide Grating","abstract":"Dispersive optical elements are important for many applications. In bulk, free-space optics, prisms, and gratings are often used. In optical waveguides, particularly in integrated photonics, arrayed waveguide gratings are most commonly used. AWGs split an optical signal into different wavelength channels. An AWG splits the optical signal into several parallel waveguides, which each have different optical path lengths. Each successive path increases in path length. The bigger the difference in path length, the better the optical resolution. However, there is a practical limitation to the resolution that can be achieved due to the ability to fit the long path lengths onto a photonics chip. The Serial Arrayed Waveguide Grating enables high resolution spectroscopy.","category":"electronics","categoryRaw":"electrical and electronics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_323","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-323","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-323","confidence":"high"},"type":"patent","title":"Concept Development for Advanced Spaceborne Synthetic Aperture Radar","abstract":"Spaceborne Synthetic Aperture Radar (SAR) can globally monitor dynamic processes on the Earths Surface. The last SAR to be developed and deployed by NASA was in the year 2000. This systems high costs inhibited development of new and improved designs. NASA has developed a new, state of the art, SAR system that is capable of providing capabilities beyond established systems and at a fraction of the cost.","category":"electronics","categoryRaw":"electrical and electronics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_35","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-35","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-35","confidence":"high"},"type":"patent","title":"SpaceCube","abstract":"SpaceCube is a cross-cutting, in- flight reconfigurable Field Programmable Gate Array (FPGA) based on-board hybrid science data processing system developed at the NASA Goddard Space Flight Center (GSFC). The goal of the SpaceCube program is to provide 10x to 100x improvements in on-board computing power while lowering relative power consumption and cost. The SpaceCube design strategy incorporates commercial radiation-tolerant Xilinx Virtex FPGA technology and couples it with an integrated upset detection and correction architecture to provide reliable order of magnitude improvements in computing power over traditional fully radiation-hardened flight systems.","category":"electronics","categoryRaw":"electrical and electronics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_365","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-365","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-365","confidence":"high"},"type":"patent","title":"Self-Adjusting Gap System for Charge Mitigation and Monitoring","abstract":"NASA scientists working on the Plankton, Aerosol, Cloud, and ocean Ecosystem (PACE) mission identified a critical risk to measurement devices: uncontrolled electrical discharges from surface charging during auroral charging events over polar ice regions. Rotating components on the satellite are especially vulnerable to charge build-up. The extreme sensitivity of PACE\u2019s instrumentation eliminates traditional solutions, like slip rings, which degrade over time due to repeated discharges. These discharges not only risk damaging critical components but could also compromise the accuracy of mission data. To protect the sensitive instruments and ensure reliable operation, a novel method was needed to mitigate surface charging. Innovators at NASA\u2019s Goddard Space Flight Center have developed a novel self-adjusting gap (SAG) system for mitigating and monitoring surface charge. The SAG system is a revolutionary approach to non-conductive bearings. Not only is the system capable of mitigating discharge related risks, but also acts a sensor to measure charging on isolated components. It is self-adjusting, passive, robust, and more precisely controllable than existing technologies.","category":"electronics","categoryRaw":"Electrical and Electronics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_373","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-373","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-373","confidence":"high"},"type":"patent","title":"Broadband Metamaterial Termination for Planar Superconducting Transmission Line Circuits","abstract":"NASA scientists at Goddard Space Flight Center have developed a broadband metamaterial termination for planar superconducting transmission line circuits. This technology was created as part of a collaborative effort with researchers on the Cosmology Large Angular Scale Surveyor (CLASS) microwave telescope array. Key improvements included adding an adiabatic absorber at the magic tee and vialess crossovers, which significantly reduces reflectance and sensitivity to fabrication variations. These changes ensured better impedance matching across the system, enhancing the fidelity and performance of the microwave circuits. The redesign aimed to address the limitations of earlier narrowband, resonant-tuned terminations that were highly sensitive to manufacturing tolerances, particularly at cryogenic temperatures. These traditional designs required strict control over surface resistance to meet transmission line impedance targets, which proved challenging and resulted in poor device yield at lower temperatures. This approach also provides better adaptability for high-performance microwave circuits used in astrophysical sensors and superconducting applications, where precision and reliability are paramount.","category":"electronics","categoryRaw":"Electrical and Electronics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_374","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-374","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-374","confidence":"high"},"type":"patent","title":"Self-Bootstrapping Isolated Power Converter","abstract":"Isolated power converters (IPCs) provide safety and performance benefits like noise reduction by separating current flow between a circuit\u2019s input and output. Existing IPCs require bootstrapping the main converter on startup by using a dedicated converter to supply isolated power from the output to the input. The need for two converters decreases efficiency, increases size, weight, and power (SWaP) requirements, and adds complexity to the overall power converter. The bootstrapping problem is significant in space flight applications where SWaP considerations are critical. In response, engineers at NASA's Goddard Space Flight Center developed the Self-Bootstrapping IPC to eliminate the need for an isolated bootstrap converter by allowing bi-modal operation of a single converter. Specifically, the invention operates in transition mode for bootstrapping and then migrates to fixed frequency mode via closed feedback. This bi-modal converter allows users to benefit from reduced mass and volume, increased power density, and improved efficiency (91-94%).","category":"electronics","categoryRaw":"Electrical and Electronics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_101","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-101","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-101","confidence":"high"},"type":"patent","title":"Self-Cleaning Seals","abstract":"In space applications, seals for hatches, suit ports, airlocks, and docking systems for pressurized volumes such as habitats, rovers, and space suits must be kept clean. This is necessary to achieve the extremely low leak rates required to ensure that crews will have sufficient breathable air for extended missions on planetary surfaces. Dusty environments, such as those of the Moon and Mars, pose challenges because seals (elastomeric and otherwise) \u2013 as dust accumulates on them \u2013 will no longer perform as designed, substantially increasing leak rates. Similarly, terrestrial applications involving environments with high dust concentration and pressurized systems (e.g., mining, material handling) must maintain clean seals to ensure safety and uptime. Motivated by the hazard lunar regolith poses to seals \u2013 and thus to achieving a sustained lunar presence \u2013 researchers in the Electrostatics and Surface Physics Laboratory at NASA\u2019s Kennedy Space Center (KSC) have developed seals that actively self-clean in a continuous or periodic manner.","category":"electronics","categoryRaw":"Electrical and Electronics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_6","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-6","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-6","confidence":"high"},"type":"patent","title":"In Situ Wire Damage Detection and Rerouting System","abstract":"NASA Kennedy Space Center seeks partners interested in the commercial application of the In Situ Wire Damage Detection and Rerouting System. NASA is soliciting licensees for this innovative technology. The In Situ Wire Damage Detection and Rerouting System consists of a miniaturized inline connector containing self-monitoring electronics that use time domain reflectometry (TDR) to detect wire faults and determine fault type and fault location on powered electrical wiring. When a damaged or defective wire is identified, the system is capable of autonomously transferring electrical power and data connectivity to an alternate wire path. When used in conjunction with NASAs wire constructions that use a conductive detection layer, the system is capable of detecting and limiting damage not only to the core conductor, but also to the insulation layer before the core conductor becomes compromised.","category":"electronics","categoryRaw":"Electrical and Electronics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_159","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-159","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-159","confidence":"high"},"type":"patent","title":"Integrated Multi-Color Light Emitting Device Made With Hybrid Crystal Structure","abstract":"NASA Langley Research Center has developed a process methodology for making red, green and blue LED device structures on the same substrate (wafer), which is not possible today using current techniques. Such devices are manufactured individually because of different crystal structures. This innovation is enabled by the prior innovations by NASA Langley Research Center.","category":"electronics","categoryRaw":"electrical and electronics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_161","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-161","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-161","confidence":"high"},"type":"patent","title":"Double Sided Si(Ge)/Sapphire/III-Nitride Hybrid Structures","abstract":"NASA Langley Research Center has developed a double sided Si(Ge)/Sapphire/III-Nitride hybrid structure. This technology uses both sides of a sapphire wafer to build device structures; on one side, making either Si or SiGe devices, and on the other side, making III-nitride device structures (e.g. GaN, InGaN, AlGaN). This innovation builds upon several previous innovations by NASA Langley Research Center, all relating to making silicon germanium semiconductor device structures on sapphire wafers.","category":"electronics","categoryRaw":"electrical and electronics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_166","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-166","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-166","confidence":"high"},"type":"patent","title":"High Mobility Transport Layer Structures for Rhombohedral Si/Ge/SiGe Devices","abstract":"The innovation builds off NASA's IP portfolio for making high-quality crystalline SiGe thin films grown on sapphire substrates. In this case, a distinct layer structure is used to create quantum well structures to provide a very high mobility pathway for both p-type and n-type charge carriers. The primary intended application of this technology is for solar cells where the band gap structure and charge carrier mobility combine to provide the potential for highly efficient solar cells. Furthermore the layer structure enables back-side illumination such that the effective solar cell area for light capture is maximized. Conversion efficiency is expected to be on the order of 30% or greater.","category":"electronics","categoryRaw":"electrical and electronics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_296","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-296","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-296","confidence":"high"},"type":"patent","title":"Location Corrections Through Differential Networks System","abstract":"In recent years, the development and use of internet enabled mobile devices with built in GPS receivers (e.g. cell phones, tablet computers) have seen substantial increases. Correspondingly, the quantity and variety of applications using the GPS capabilities of these devices have also increased. However, one limiting factor for some desired uses, such as establishing drop zones for package delivery, is that these devices typically have limited precise positioning capabilities due to minimizing Size, Weight, Power and Cost (SWaP-C) for their GPS antennas and chip sets. Research suggests that the expected positional accuracy for a typical mobile device (cell phone or tablet computer) is around 3-10 meters, which is prohibitive for applications that require higher precision.","category":"electronics","categoryRaw":"electrical and electronics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_310","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-310","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-310","confidence":"high"},"type":"patent","title":"Metallic Junction Thermoelectric (MJTE) Generator","abstract":"NASA's Langley Research Center has developed a new concept thermoelectric (TE) principle based on thin-film metal - metal junctions. This approach substantially increases the TE efficiency and power density. When two metals with different vacancy states selected for the greatest possible disparity are in a junction, this junction naturally allows the greatest number of charges across the barrier by the charge disparity. Metals have higher electron pools 10 3 -10 4 C/cm 3 and the metal junctions, simpler than semiconductor junctions, can be made smaller and more energy compact.","category":"electronics","categoryRaw":"Electrical and Electronics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_320","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-320","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-320","confidence":"high"},"type":"patent","title":"Single Crystal Semiconductor Silicon-Germanium (SiGe)","abstract":"With 4x faster carrier mobility and less energy loss than single crystal silicone, single crystal SiGe offers increased processing power and decreased size, and power demands for a unit of the same size. These capabilities exceed current market options for semiconductors. In solar cell applications, SiGe offers new design features that improves its efficiency to 30~40% and the operational life to ~80 years. SiGe is also a comparatively more abundant resource, lower cost and non-toxic, unlike standard solar materials . With SiGe production technologies suite consistent quality production and lowered production costs and waste can be ensured while maintaining expeditious production. Once production is operational, the processes are expected to be equivalent in manufacturing cost to poly-crystal SiGe.","category":"electronics","categoryRaw":"Electrical and Electronics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_126","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-126","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-126","confidence":"high"},"type":"patent","title":"Metallization for SiC Semiconductors","abstract":"Scientists at NASA's Glenn Research Center have developed and patented improved ohmic contacts, and a fabrication method for them, that will speed the production of silicon carbide (SiC) sensors and electronics that operate in high-temperature, harsh environments. Conventional fabrication techniques require multiple time-consuming and costly processes to form ohmic contacts separately onto donor (n-type) and acceptor (p-type) surfaces. Glenn's innovation creates universal and simultaneous ohmic contacts for both n- and p-type SiC semiconductors without compromising reliability and contact robustness. These ohmic contacts make it significantly less expensive and easier to fabricate high-temperature SiC sensors and electronics that can monitor in real time, even within harsh environments such as jet and rocket engines.","category":"electronics","categoryRaw":"Electrical and Electronics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_137","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-137","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-137","confidence":"high"},"type":"patent","title":"Shape Memory Alloy Art (SMArt)","abstract":"Innovators at NASA's Glenn Research Center have developed an educational device and method for creating letters, numbers, characters, symbols, or a combination, using shape memory alloy (SMA) wire. The device, which is a small, portable apparatus, goes through a prescribed heating sequence which will train the shape memory alloy wire to remember the shape set by the user (e.g. a star, heart, etc.). After the heating and cooling sequence of the device is complete, the user extracts the shape then can distort the trained shape memory alloy wire. Upon application of heat, the wire will transform back into the trained shape. The innovation contributes a method for advancing science education by providing a powerful hands-on teaching tool to demonstrate cutting-edge material and science capabilities. This simple and portable tool offers adaptive, interactive, customized, and individualized shape creation for students, hobbyists, artists, and others.","category":"electronics","categoryRaw":"electrical and electronics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_160","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-160","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-160","confidence":"high"},"type":"patent","title":"Robust High Temperature SiC Op Amps Practical Fabrication","abstract":"NASA Glenn has a new way to correct for variations in transistor threshold voltage due to die location on the wafer for silicon carbide (SiC) op amps, enabling improved electrical circuits for sensor signal conditioning in harsh environments. Important system-level benefits are enabled by improved performance data from sensor circuitry mounted within very hot gas turbine flows or the primary coolant loop of a nuclear reactor, for example. Often, tiny (microvolt) signals from sensors require conditioning by high-temperature electrical components to filter, amplify and convert to levels suitable for digitization and \"smart\" system control. Op amps are a critical component for signal amplification. With the new threshold voltage correction scheme, the signal amplification of all op amps, at any position on the SiC wafer, is the same, extending reliable signal conditioning well beyond the current temperature limits of conventional silicon integrated circuits allowing useful chips to be produced across the entire SiC wafer surface.","category":"electronics","categoryRaw":"electrical and electronics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_169","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-169","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-169","confidence":"high"},"type":"patent","title":"Enhanced DC Bus Emulator","abstract":"DC bus emulators are verification testing tools that emulate power load dynamics of entire power systems, subsystems, and individual loads. Due to limitations of commercial-off-the-shelf (COTS )hardware, it is challenging and costly to evaluate the loads of complex systems using hardware alone. Innovators at NASA\u2019s Glenn Research Center developed an easily implementable enhancement to existing DC bus emulators that overcome these limitations. The inspiration for this technology arose because NASA designs power systems for a variety of loads, from spacecraft and aircraft to future lunar outputs. The busses that power these loads may include simple, individual DC-to-DC power converters, or complex, integrated systems, such as robots, propulsors, refueling equipment, and habitation hardware. Each load and each system are key to an application\u2019s function, making them critical to assess. However, using COTS DC loads it is not possible to fully, dynamically replicate power systems, subsystems, or individual loads on a small-signal basis. Further, this replication method is costly and time-consuming because hardware copies are needed to recreate each individual load that will be assessed in a DC microgrid. In contrast, using a mixture of representative filters, a Pulsed Width Modulator (PWM) dithering technique, and COTS loads, this technology provides a collaborative way to integrate individual, sub-system, and entire power systems loads.","category":"electronics","categoryRaw":"Electrical and Electronics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_33","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-33","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-33","confidence":"high"},"type":"patent","title":"Integrated Circuit Chips","abstract":"Innovators at NASA's Glenn Research Center have developed a new generation of silicon carbide (SiC) logic and mixed signal integrated circuits (ICs), unprecedented in the field of high-temperature electronics. Previously, SiC ICs could not withstand more than a few hours of 500&deg;C temperatures before degrading or failing. Now, NASA Glenn has successfully fabricated prototypes that consistently exceed 1,000 hours of continuous operation at 500&deg;C. The superior performance stems in part from previous Glenn advancements, such as the iridium interfacial stack (IrIS), a bondable and durable metallization stack that enables electrical packaging connections to SiC integrated circuits operating above 500&deg;C. The enhanced stability of these components will enable important improvements in sensing, control, and operation of harsh environment systems, by providing analog and digital circuit functionality directly where it is needed. This advancement in the manufacturing of SiC-based electronics revolutionizes and broadens the opportunities for intelligent systems by providing ICs that operate well beyond the current temperature limits of conventional (silicon) ICs.","category":"electronics","categoryRaw":"Electrical and Electronics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_47","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-47","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-47","confidence":"high"},"type":"patent","title":"Dynamic Range Enhancement of High-Speed Data Acquisition Systems","abstract":"Innovators at NASA's Glenn Research Center have developed a technique using reversible non-linear amplitude compression to overcome hardware limitations of common high-speed data acquisition systems. The NASA Glenn technique measures electronic signals with high dynamic range, wide bandwidth, and high frequency. The technique implements a custom electronic circuit applied between the input of a data acquisition device, such as an oscilloscope, and a test article to be measured. The Glenn innovation also includes a software-based algorithm that is applied to the data acquired through the applied circuit and the data acquisition system.","category":"electronics","categoryRaw":"Electrical and Electronics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_117","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-117","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-117","confidence":"high"},"type":"patent","title":"Printable IoT sensor development platform","abstract":"NASA inventors have developed a low-power wireless platform for the evaluation of sensors printed on flexible polyimide substrates. The platform simplifies development of novel environmental sensors and their end-use applications by merging Bluetooth low energy (BLE) hardware, sensors, and sensor fusion software. It consists of a printed circuit board with programmable system on a chip (PSoC) microcontroller; commercially available inertial, environmental, and gas sensors; and area for deposition of novel printed sensing elements. Outputs can be configured to send sensor data over BLE connection for recording and analysis in third party software. The platforms integrated nature reduces system size, cost, and power consumption; it includes all essential hardware to support development of IoT devices. It has been used for development of respiration and environmental monitoring sensors for astronauts aboard the International Space Station.","category":"electronics","categoryRaw":"electrical and electronics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_132","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-132","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-132","confidence":"high"},"type":"patent","title":"Composite Dielectric Inks for Humidity Sensing","abstract":"Inventors at NASA Marshall Space Flight Center (MSFC) have developed humidity sensing dielectric ink formulations for use in printed electronic and sensor manufacturing applications. Novel ceramic powders with favorable dielectric properties are mixed with liquid resins to form a polymer-ceramic composite that can be deposited and cured at room temperature, eliminating high temperature sintering steps previously required to produce ceramic elements. The inks' epoxy and UV curable resin binders form consistent dispersions with viscosities suitable for deposition via aerosol jet or screen printing processes. Prototype humidity sensors produced using the novel ink formulations demonstrate high sensitivity and rapid, log-linear response to changes in relative humidity (RH) and have been explored for in-helmet breath sensing applications for astronauts or pilots. Suitability of the ink for use in capacitive energy storage applications has also been explored.","category":"electronics","categoryRaw":"Electrical and Electronics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_134","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-134","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-134","confidence":"high"},"type":"patent","title":"Passive PCB-Mounted Thermal Switch","abstract":"Effective heat dissipation and thermal protection are critical for printed circuit boards (PCBs) used in spaceflight applications, where the boards must withstand extreme temperature fluctuations, especially during deep space or lunar surface operations. PCBs generate heat while functioning. In a vacuum, this heat can only dissipate through conduction and radiation. Ensuring efficient heat rejection requires strong thermal conductivity between the PCB and its enclosure. However, if the enclosure's temperature drops too low \u2013 due to environmental conditions, idle processors, or other factors \u2013 excessive heat rejection can cause the PCB to fail. Currently, maintaining PCBs above their minimum operating temperature of around -20C demands significant energy and mass (e.g., batteries). In response to this challenge, engineers at NASA\u2019s Marshall Space Flight Center (MSFC) have developed a PCB-mounted thermal switch that allows the PCB to toggle between being \u201cthermally mounted\u201d (heat-dissipating) and \u201cthermally unmounted\u201d (heat-conserving) to the electronics enclosure, depending on temperature conditions. This switch fits easily onto a PCB and is completely passive, eliminating the need for battery power to maintain the PCB within its operating temperature range.","category":"electronics","categoryRaw":"Electrical and Electronics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_105","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-105","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-105","confidence":"high"},"type":"patent","title":"Coil-On-Plug Igniter for Reliable Engine Starts","abstract":"Innovators at NASA Johnson Space Center have developed a coil-on-plug ignition system for integrated liquid oxygen (LOX)/liquid methane (LCH4) thermal-vacuum environment propulsion systems operating in a thermal vacuum environment. The innovation will help quell corona discharge issues and reduce overall mass. Corona discharge represents a local region surrounding a high-voltage conductor where air has undergone an electrical breakdown and become conductive due to ionization, allowing a charge to leak off the conductor and cause a possible malfunction. NASA worked with commercial vendors to modify off-the-shelf automotive coil-on-plug spark plug systems for use with LOX/LCH4 igniters. The coil-on-plug configuration eliminates the bulky standalone coil-pack and conventional high-voltage spark plug cable by combining the coil and the spark plug into a single component. The test campaign successfully proved that coil-on-plug technology can enable integrated LOX/methane propulsion systems in future spacecraft .","category":"electronics","categoryRaw":"Electrical and Electronics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_317","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-317","sourceUrl":"https://technology.nasa.gov/patent/TOP2-317","confidence":"high"},"type":"patent","title":"Highly secure all-printed Physically Unclonable Function (PUF) electronic device based on a nanomaterial network","abstract":"Assets are traditionally secured so important information can only be accessed when a key is placed in a lock (physical or electronic). Given the tremendous increase in the number of devices in the era of Internet of Things (IoT), direct access between things without human intervention is ideal. IoT related devices require unique identification codes that can be safely stored for security and that are resistant to physical attacks and exposure to harsh environments. As a solution, NASA Ames has developed a Physically Unclonable Function (PUF) electronic device using an all-printed nanomaterial network , such as a Carbon Nanotube (CNT) network. The invention leverages the intrinsic, random, and unique features of CNTs in a network for authentication, which can be used as a secret, stable, and robust key for high-level hardware security.","category":"electronics","categoryRaw":"Electrical and Electronics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_362","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-362","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-362","confidence":"high"},"type":"patent","title":"Lunar Experiment Support System and Handling (LESSH) Battery Charger Module (BCM)","abstract":"Innovators at NASA\u2019s Goddard Space Flight Center have developed a groundbreaking extravehicular activity (EVA)-compatible Battery Charger Module (BCM) as part of the Lunar Experiment Support System and Handling (LESSH) package. This first-of-its-kind technology is designed to provide wired battery charging capabilities to astronauts on the lunar surface or other harsh environments. With the Artemis III mission and beyond, NASA plans to deploy cutting-edge science instruments near the lunar South Pole landing site. To support extended lunar science operations, the EVA-compatible LESSH BCM offers seamless recharging and reliable hard-line data transfer at the modular interface bank on the Human Landing System (HLS) or other Artemis systems (rovers, vehicles, habitats, etc.). Engineered for astronaut ease-of-use, the LESSH BCM delivers an ergonomic interface to connect instruments to power and data systems. By combining battery charge monitoring with flexible data transfer capabilities, the BCM empowers astronauts to extend the scope and duration of operations on the Moon. The NASA invention is integral to creating a recharging infrastructure that enables sustainable, long-term lunar exploration.","category":"energy_power","categoryRaw":"Power Generation and Storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_62","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-62","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-62","confidence":"high"},"type":"patent","title":"Cryogenic Flux Capacitor","abstract":"NASA Kennedy Space Center seeks partners interested in the commercial application of the Cryogenic Flux Capacitor (CFC). This new technology capitalizes on the energy storage capacity of liquefied gasses. By exploiting a unique attribute of nano-porous materials, aerogel in this case, fluid commodities such as oxygen, hydrogen, methane, etc. can be stored in a molecular surface-adsorbed state. This cryogenic fluid can be stored at low to moderate pressure densities, on par with liquid, and then quickly converted to a gas, when the need arises. This solution reduces both safety-related logistics issues and the limitations of complex storage systems. Currently, high pressured gasses are stored in vessels with heavy thick walls that require constant pressurization and complex storage systems to limit boil-off. These systems are not well suited to overly dynamic situations where the tank orientation can change suddenly. NASA's CFC address all of the aforementioned issues, simplifying current operations and opening the possibilities for new applications and new markets from cryogenic liquid.","category":"energy_power","categoryRaw":"Power Generation and Storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_227","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-227","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-227","confidence":"high"},"type":"patent","title":"Nuclear Thermionic and Thermoelectric Energy System","abstract":"Nuclear Thermionic Avalanche Cells with Thermoelectric (NTAC-TE) offers direct conversion of energy carried by gamma radiation and beta particles into electricity, as well as direct energy conversion of the heat byproduct without steam driven turbines. This process is considerably more efficient, especially with the addition of Cobalt-60 and sodium-22, than traditional nuclear power generation. In the NTAC-TE system, even the Cesium byproduct of Uranium 235 fission contributes additive energy for more power output. Upgrading, or using NTAC-TE in conjunction with nuclear power plants increases power derived from the fission process. NTAC-TE cells can also use up all radioactive emission energy from radioactive materials without allowing any radioactive emission from the device. NTAC-TE can even use existing fission waste as a viable fuel and operate as a safe and mobile remote energy source.","category":"energy_power","categoryRaw":"Power Generation and Storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_375","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-375","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-375","confidence":"high"},"type":"patent","title":"Carbon Bipolar Membranes for Solid-State Batteries","abstract":"Innovators from the NASA Langley and NASA Glenn Research Centers have developed materials and processes to use carbon nanomaterials as bipolar membranes or plates for separating solid-state battery unit cells. Using carbon materials over current bipolar plates will be an enabling technology for lightweight, high energy density solid-state batteries. Bipolar membranes or plates provide a chemically inert but electrically conductive layer separating solid-state battery unit cells that allow them to be stacked within a single package. Here, the developed bipolar plate materials include films or membranes of graphene, holey graphene, and carbon nanotubes. These carbon materials provide a significant weight savings over currently used metallic materials while maintaining the necessary performance characteristics of the bipolar plates. These new bipolar membranes or plates may be employed in high energy density solid-state batteries for electrified aircraft , electric vehicles, or a variety of electric devices that require high performance batteries.","category":"energy_power","categoryRaw":"Power Generation and Storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_167","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-167","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-167","confidence":"high"},"type":"patent","title":"SABERS: Solid-State Lithium-Sulfur Battery Technology Portfolio","abstract":"SABERS (Solid-state Architecture Batteries for Enhanced Rechargeability and Safety) is a portfolio of innovations developed collaboratively by NASA's Glenn, Langley, and Ames Research Centers that addresses fundamental challenges in solid-state battery technology. Solid-state batteries replace the flammable liquid electrolytes found in conventional lithium-ion batteries with solid materials, offering transformative improvements in safety and energy density. However, realizing this potential requires solving critical problems in materials compatibility, manufacturing scalability, and system integration. SABERS tackles these challenges through several complementary innovations: novel materials, graphene-based manufacturing, dry-processing techniques, solid-state architecture developments, and computational design tools. NASA developed SABERS primarily for next-generation electric aviation propulsion, where solid-state batteries' combination of high energy density, damage tolerance, and inherent safety is essential. The technology addresses broader challenges facing solid-state battery commercialization across automotive, aerospace , energy storage, and other industries. NASA is seeking industry partners to advance this technology toward commercial deployment. SABERS is available for licensing as a complete portfolio or as individual component technologies.","category":"energy_power","categoryRaw":"Power Generation and Storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_168","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-168","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-168","confidence":"high"},"type":"patent","title":"Next Generation \u201cClosed Strayton\u201d Engine Design","abstract":"NASA\u2019s Glenn Research Center introduces the \u201cClosed Strayton\u201d generator design to efficiently deliver lightweight and sustainable electric power for clean energy applications. Optimized for hydrogen-based, zero-emission electrified aircraft propulsion from kW to MW range, the design builds on the core \u201cStrayton\u201d engine technology, which combines both Stirling and Brayton cycle elements to overcome the size and performance limitations of conventional turbines and heat engines. In its closed-cycle configuration, the design provides fuel-source agnostic, maintenance-free, quiet power generation for applications with challenging footprint and noise constraints. With additional support for open-cycle and combined-cycle implementations, as well as the capability to scale to higher power outputs, this early-stage technology offers broad applicability for both today and tomorrow\u2019s clean energy and power systems.","category":"energy_power","categoryRaw":"Power Generation and Storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_181","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-181","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-181","confidence":"high"},"type":"patent","title":"Universal Power Converter for a Lunar Power Grid","abstract":"NASA\u2019s Universal Modular Interface Converter (UMIC) innovation is a bidirectional AC/DC power converter designed to connect lunar surface power assets and enable power sharing over long distances between sources (e.g. solar) and loads. The UMIC module is intended to be lightweight and readily deployable. The UMIC innovation can essentially serve as the backbone of an electrical power grid for lunar surface exploration and development missions operated by NASA or the commercial space industry. The UMIC architecture is flexible to different grid voltages and frequencies, as well as to different controller and communication systems. The NASA inventors of this technology envision it becoming a standardized system that all users can access similarly.","category":"energy_power","categoryRaw":"Power Generation and Storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_182","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-182","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-182","confidence":"high"},"type":"patent","title":"CryoQuad","abstract":"Meeting the cooling demands of megawatt-scale superconducting systems, high-power fuel cells, and other cryogenic applications has long been limited by the mass, complexity, and capacity of traditional cryocoolers. CryoQuad, developed by innovators at NASA Glenn Research Center, is a high-efficiency cryogenic cooling system capable of operating on thermoacoustic principles, waste heat from fuel cells, or other compatible heat sources. Its flexible architecture eliminates moving parts, reduces weight, and delivers reliable, high-capacity cooling for transportation, aerospace , medical, and industrial systems. Future superconducting transportation platforms, including automobiles, maritime vessels, and aircraft, promise major gains in energy efficiency and range. However, superconductors only exhibit zero electrical resistance at extremely low temperatures (below 50 K). Without effective cryogenic cooling, their performance rapidly degrades, erasing efficiency benefits. CryoQuad provides the scalable, reliable cooling required to maintain superconductivity under operational loads and unlock the full performance potential of these advanced platforms.","category":"energy_power","categoryRaw":"Power Generation and Storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_184","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-184","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-184","confidence":"high"},"type":"patent","title":"Electrolyte for Aluminum-Air Batteries","abstract":"Aviation electrification requires energy storage that is both lightweight and exceptionally powerful, especially for emergency and backup applications where mission success is dependent on sustained reliability. Conventional batteries struggle to provide the combination of high energy density and intrinsic safety needed for aircraft electrification. NASA\u2019s Subsonic Single Aft Engine (SUSAN) Electrofan program needed an energy-dense solution to these problems. To address this challenge, innovators at NASA\u2019s Glenn Research Center have developed an advanced polymer and polymer-hybrid electrolyte specifically engineered for use in metal-air batteries, with a focus on aluminum-air systems. By embedding a high-conductivity alkaline electrolyte within a solid polymer matrix, this technology overcomes longstanding barriers such as aluminum corrosion, electrolyte leakage, and premature energy loss. This innovation paves the way for compact, high-capacity primary power sources that can support critical aerospace missions and other applications where weight, reliability, and energy security are paramount.","category":"energy_power","categoryRaw":"Power Generation and Storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_186","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-186","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-186","confidence":"high"},"type":"patent","title":"Mixed Conducting Cathodes and Dense Electrolytes for Solid-State Batteries","abstract":"NASA\u2019s SABERS 2.0 (Solid-state Architecture Batteries for Enhanced Rechargeability and Safety) project aims to improve the state of the art for battery efficiency, power, and safety. Current lithium-ion batteries use liquid electrolytes that connect to the active material. However, these electrolytes are highly volatile and flammable, which can cause catastrophic failures and carry safety risks that may impact mass-market desirability. Solid-state batteries use solid electrolytes with better conduction abilities, making them a sound alternative to lithium-ion designs, but these often contain complex cathodes that have inefficient energy pathways and can be difficult to build at scale. Teams at NASA\u2019s Glenn Research Center have created two complementary SABERS innovations to improve solid-state batteries\u2019 performance and safety: a low-temperature electrolyte densification process and a catholyte formulation that simplifies the path of conduction and reduces the number of required interfaces. These innovations work in conjunction to increase electrolyte density while simultaneously increasing cathode porosity, resulting in solid-state battery concepts with increased energy density combined with the safety improvements of higher tolerances.","category":"energy_power","categoryRaw":"Power Generation and Storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_187","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-187","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-187","confidence":"high"},"type":"patent","title":"Isostatically Pressurized and Lightweight Cell Case for Solid-State Batteries","abstract":"The SABERS 2.0 (Solid-state Architecture Batteries for Enhanced Rechargeability and Safety) portfolio is a collection of innovations focused on improving solid-state battery performance and safety. Solid-state batteries display several improvements over traditional lithium-ion batteries and have been shown to perform better when their solid components are under applied pressure. This pressure is often uniaxial (i.e., one-directional), which requires large, heavy machinery and can result in battery damage or directional dendrites which may harm the battery further. These burdens and risks create a hurdle to scalable commercialization. To address these issues and improve adoptability of solid-state batteries, scientists at NASA\u2019s Glenn Research Center have added an isostatically pressurized cell case to the SABERS 2.0 portfolio that eliminates uniaxial pressure risks, reduces packaging weight, and enhances battery performance and cycling ability.","category":"energy_power","categoryRaw":"Power Generation and Storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_188","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-188","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-188","confidence":"high"},"type":"patent","title":"Next-Generation Solid-State Lithium-Sulfur Battery Portfolio (SABERS 2.0)","abstract":"Innovators at NASA's Glenn Research Center and Langley Research Center have been developing further advancements to the foundational work in solid-state battery development from the SABERS project (LEW-TOPS-167). Building on SABERS' achievement of energy densities over 500 W-hr/kg, the SABERS 2.0 portfolio addresses critical challenges that have limited the scalability and commercial adoption of solid-state batteries. While the original SABERS portfolio demonstrated breakthrough performance in energy density and safety, SABERS 2.0 innovations focus on manufacturing scalability, battery longevity, and operational reliability. The SABERS 2.0 suite specifically addresses three key areas that enable practical implementation of solid-state batteries in demanding applications: cathode efficiency, anode stability, and packaging optimization.","category":"energy_power","categoryRaw":"Power Generation and Storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_189","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-189","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-189","confidence":"high"},"type":"patent","title":"Cost-Effective DC Source Emulator for Microgrid Testing","abstract":"Testing complex DC microgrid systems traditionally requires recreating entire power architectures with actual hardware copies, a process that can take months or years and cost millions of dollars. This is especially challenging in aerospace applications where specialty components are expensive, scarce, or still under development. Researchers at NASA\u2019s Glenn Research Center have developed a practical methodology that enables engineers to emulate DC power sources using commercially available dynamic power supplies combined with custom-designed filters and external controllers. This hardware-in-the-loop approach uses impedance matching and external control circuits to replicate the electrical characteristics of any DC power source without requiring the actual hardware. By measuring or simulating the impedance of a target power source, engineers can design equivalent filter networks and tune controller gains to make standard lab equipment behave identically to specialized systems. This technique has been validated to TRL 7 and is actively used to define power supply requirements and specifications for NASA's Gateway lunar outpost program. The methodology reduces verification testing from millions of dollars and months of effort down to tens of thousands of dollars and weeks of timeline, enabling rapid iteration and troubleshooting without risking expensive flight hardware.","category":"energy_power","categoryRaw":"Power Generation and Storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_80","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-80","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-80","confidence":"high"},"type":"patent","title":"Stirling Thermoacoustic Power Converter and Magnetostrictive Alternator","abstract":"Innovators at NASA's Glenn Research Center have developed two novel technologies that make Stirling engines more efficient and less costly. First, Glenn's thermoacoustic power converter uses sound to turn heat into electric power. Utilizing heat-driven pressures and volume oscillations from thermoacoustic sources to power piezoelectric alternators or other power-converter technologies, this device can generate electricity with unprecedented efficiencies. Unlike conventional Stirling-based devices, this thermoacoustic engine achieves high thermal-to-electrical efficiencies with no moving parts. Glenn's second advancement for Stirling engines replaces the conventional linear alternator with a magnetostrictive alternator that converts the oscillating pressure wave into electric power (see cut-away diagram above). These innovations offer a reliable and efficient way to generate power from any heat source, benefiting applications such as combined heat and power (CHP) systems, distributed generation, solar power generation, and heating and cooling systems.","category":"energy_power","categoryRaw":"Power Generation and Storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_75","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-75","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-75","confidence":"high"},"type":"patent","title":"Novel, Solid-State Hybrid Ultracapacitor Battery","abstract":"NASA's Marshall Space Flight Center has developed a solid-state ultracapacitor with a unique combination of high capacitance and battery-like discharge characteristics. The high capacitance in a solid-state form can enable a new type of ultracapacitor, and, in combination with the ability to deliver sustained power like a battery, can perhaps enable an entirely new class of energy storage devices. Test devices have demonstrated high capacitance, and uniquely, a discharge behavior that is more typical of a battery. Data show that these test devices discharge rapidly down to a certain voltage, and then discharge slowly like a battery. Hence, the term hybrid ultracapacitor is used to describe the technology. The subject technology was developed as a result of efforts to replace range-safety batteries used to power the systems that destroy off-course space launch vehicles. Other commercial applications where ultracapacitors or batteries are used may benefit as well.","category":"energy_power","categoryRaw":"Power Generation and Storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_119","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-119","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-119","confidence":"high"},"type":"patent","title":"Carbon Fiber Sleeve Tempers Battery Thermal Runaway","abstract":"Innovators at NASA Johnson Space Center have developed a carbon fiber reinforced polymer (CFRP) sleeve, that, when fitted over a cylindrical lithium-ion battery cell, can prevent cell-to-cell propagation by containing a thermal runaway (TR) event to the originating cell. TR is caused by a battery cell short-circuiting and its inability to contain the resulting increase in pressure and temperature, which may lead to a sidewall rupture (SWR). Space flight and other industrial batteries frequently utilize multiple cells, such as the 18650, that are assembled into modules or battery packs and provide power to a variety of applications. A TR event can propagate to all the cells in a battery pack, escalating into a fire that can be catastrophic. Use of CFRP sleeves for Li-ion cells provides multiple advantages over previous containment designs: increased hazard safety, lower mass, reduced cost, lack of conductivity, and manufacture with readily available materials. Hundreds of billions of 18650 battery cells are made globally and are the most common single cell format. They are used in commercially available products such as power tools, laptops, cameras, e-bikes, and electric cars.","category":"energy_power","categoryRaw":"Power Generation and Storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_135","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-135","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-135","confidence":"high"},"type":"patent","title":"ThermoArc Facilitates Low-Cost Li-Ion Battery Testing","abstract":"Innovators at NASA Johnson Space Center have developed a battery testing technology called ThermoArc that uses a plasma arc to drive a Li-ion battery cell into thermal runaway (TR) by inducing a localized short circuit. The short circuit is created when the plasma arc breaches the cell and melts a small section of the internal separator causing the anode and cathode to come into contact. This \"short\" yields rapid heat generation that, if not contained, can potentially cause a fire or explosion. This situation becomes especially dangerous if a single cell\u2019s TR event propagates to other cells within a battery pack, such as those used commercially in aerospace and electric vehicles. Therefore, various testing methodologies have been adopted by battery manufacturers to study TR and the results, and thereby improve TR containment. ThermoArc presents a method that uses a plasma arc to deliver thermal energy to heat up only a small area of a Li-ion battery cell to trigger a TR event. This method ensures that the total heat applied is minimal and does not affect the cell\u2019s thermal properties nor does it make significant electrical or mechanical alterations to the cell. Additionally, ThermoArc technology can be implemented to initiate hundreds of repeatable Li-ion battery cell TR tests significantly cheaper than other TR testing method-ologies given that the only consumables are inexpensive electrodes.","category":"energy_power","categoryRaw":"Power Generation and Storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_136","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-136","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-136","confidence":"high"},"type":"patent","title":"Ram-Dent Thermal Runaway Triggering Device","abstract":"Innovators at NASA Johnson Space Center have developed a device that projects a dome-ended nail at a Li-ion battery cell can wall to initiate a thermal runaway (TR) event by denting it. The dent and resulting internal stress wave tears the separator between the anode and cathode within the battery cell causing a short circuit that leads to TR and battery deflagration. Initiating TR in battery cells is an important part of Li-ion battery R&D to better understand the effects of TR, and to make related safety improvements. The novelty of this technology is that the separator is destroyed from the inside without perforating the battery cell can itself or adding thermal energy as a trigger mechanism. This approach results in a more accurate simulation of field-like short circuits and TR for Li-ion battery research and development compared to current state of the art (SoT). Additionally, this device could be used to enhance or supplant traditional testing methods such as those that implement heat-based TR initiation, or mechanical insult where the material integrity of a battery cell is compromised. The Ram-Dent Thermal Runaway Triggering Device was designed to be used in conjunction with NASA\u2019s fractional thermal runaway calorimeters (FTRC) to obtain calorimetry measurements of TR events for fast Li-ion battery failure evaluation. However, this device could be modified to work with other calorimeters designed for the testing of a single Li-ion battery cell or battery-pack.","category":"energy_power","categoryRaw":"Power Generation and Storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_140","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-140","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-140","confidence":"high"},"type":"patent","title":"Adaptive Pouch Cell Chamber","abstract":"Innovators at NASA Johnson Space Center have developed an adaptive pouch cell chamber, or \u201cAPCC\u201d for short, whose chamber halves com-press and constrain a battery pouch cell or a prismatic cell while it is induced into thermal runaway (TR) for analysis. The device comprises an adaptive diaphragm to accommodate variations in the thickness of these types of battery cells without requiring significant changes in the hard-ware. While NASA\u2019s previous cell chamber design was state-of-the-art, the APCC brings numerous enhancements to the prior NASA design. The prior design required two technicians and approximately one and a half hours for setup between consecutive tests. This down-time was partially caused by the needed separation of the cell chamber from the fractional thermal runaway calorimeter (FTRC) bore where the thermal energy from a TR event is measured when expelled by the APCC. Addi-tionally, various internals such as heating elements and thermal sensors required refurbishment between each test in which TR was achieved. The APCC incorporates a novel two-pin quick-disconnect whereby the cell chamber is easily separated from the FTRC. This quick release de-sign increases battery testing throughput while reducing complexity and number of parts. Furthermore, the APCC internal hardware was designed to be fully reusable, lending itself to more reliable and consistent energy yield calculations sought after by battery cell testing and manufacturing industries.","category":"energy_power","categoryRaw":"Power Generation and Storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_141","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-141","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-141","confidence":"high"},"type":"patent","title":"Thermal Ejecta Shielding System for Li-Ion Battery Packs","abstract":"Innovators at NASA Johnson Space Center have designed a thermal runaway (TR) shielding system for Li-ion cylindrical battery packs to inhibit collateral damage to adjacent battery cells during a TR event. This shielding system technology introduces eight novel improvements (detailed below) to a state-of-the-art \u201cPassively Propagation Resistant\u201d (PPR) battery pack that may be applied to other Li-ion battery packs for safety and performance improvements. TR is caused by a battery cell short-circuiting combined with the cell\u2019s inability to contain the resulting increase in pressure and temperature. For example, this inability could lead to a rupture from either end of a cylindrical cell, where ensuing hot ejecta spray could damage neighboring cells in a battery pack \u2013 or could trigger the neighboring cells into TR, which in turn could escalate into a catastrophic fire. Numerous industries such as automotive, aviation, aerospace , and consumer electronics utilize Li-ion battery cells that are assembled into modules or battery-packs to provide energy storage. This technology, Thermal Ejecta Shielding System for Li-ion Battery Packs, has a technology readiness level (TRL) of 6 (System/sub-system model or prototype demonstration in an operational environment), and is now available for patent licensing. Please note that NASA does not manufacture products itself for commercial sale.","category":"energy_power","categoryRaw":"Power Generation and Storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_148","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-148","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-148","confidence":"high"},"type":"patent","title":"Solid-State System Efficiently Generates Purified O2","abstract":"Innovators at NASA Johnson Space Center, in collaboration with inno-vators at American Oxygen, have developed a solid-state system and process that separates oxygen from ambient air and compresses the resulting purified oxygen \u2013 with a significant reduction in power con-sumption compared to prior state-of-the-art. It is based upon a proven solid oxide electrochemical oxygen separation and compression tech-nique that derives purified oxygen from ambient air and compresses it using an electrochemical pumping method. This electrically driven technology relies upon the high operating tem-perature of electrochemical cell stacks for maximum efficiency. An inverse relationship exists between high temperature and electrical resistance; thus, a heated system requires less energy to drive oxide ions across a cell membrane and compress the resulting purified oxy-gen. Ambient air that is fed and circulated for processing through the system also helps to stabilize high system operating temperatures. To prevent the ambient air from overcooling the electrochemical pro-cess, the incoming air is preheated. However, in existing systems, this pre-heating incurs a large cost penalty in power consumption. The new solid-state system design performs electrochemical reactions to generate purified oxygen but uses an embedded heat exchanger to preheat the incoming air with system waste heat without the need for supplemental heaters, significantly boosting efficiency.","category":"energy_power","categoryRaw":"Power Generation and Storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_149","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-149","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-149","confidence":"high"},"type":"patent","title":"Next Generation Li-Ion Calorimeter","abstract":"Innovators at NASA Johnson Space Center have developed a small-fractional thermal runaway calorimeter to support the determination of both total energy yield and fractional energy yield for Li-ion cylindrical format battery cells. This technology comprises updates to the previously disclosed Li-ion Cell Calorimeter (MSC-TOPS-77). By understanding the TR behavior of small format Li-ion cells, engineers can gain insight into improving design safety. This in turn helps prevent cell-to-cell TR propagation in the event of cell short-circuiting leading to battery explosion, and reduces the likelihood of hardware loss or even mission failure. Key industries that may be interested in licensing opportunities are those that provide battery testing services, and battery manufacturers that develop and sell small format Li-ion cells for a multitude of consumer electronics, EV ground transport, commercial aerospace , and the burgeoning Electric Vertical Take-Off and Landing (eVTOL) and related industries. The Next Generation Li-Ion Calorimeter and related components are at technology readiness level (TRL) 6 (System/sub-system model or prototype demonstration in an operational environment) and are now available for patent licensing. Please note that NASA does not manufacture products itself for commercial sale.","category":"energy_power","categoryRaw":"Power Generation and Storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_40","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-40","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-40","confidence":"high"},"type":"patent","title":"Battery Management System","abstract":"NASA seeks interested parties to license the Battery Management System (BMS) developed by innovators at Johnson Space Center. NASA's BMS features the ability to monitor and balance the charge of individual battery cells that are in series and provide fault detection of individual cells in parallel within a battery pack of hundreds of cells. The circuit uses fewer connections (pins) than competing technologies, which reduces complexity and improves reliability. It offers a safe and potentially low-cost management system for high-voltage battery systems, including lithium-ion (Li-ion) battery systems that are used in electric vehicles and other next-generation renewable energy applications. This NASA Technology is available for your company to license and develop into a commercial product. NASA does not manufacture products for commercial sale.","category":"energy_power","categoryRaw":"Power Generation and Storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_75","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-75","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-75","confidence":"high"},"type":"patent","title":"Internal Short Circuit Testing Device to Improve Battery Designs","abstract":"Batteries, such as lithium-ion for example that are sold for consumer use in portable electronic devices and other applications such as electrical cars, occasionally fail in the field over time. These cells have typically passed a wide variety of safety tests, such as those required by governmental shipping regulations and other certification organizations. Nevertheless, they sometimes fail by overheating, which triggers thermal runaway in the battery. This action may engulf the entire device such as a cellular phone or tablet-type devices. To better understand these failure modes, innovators at the NASA Johnson Space Center and the DOE National Energy Renewable Laboratory have developed a battery test device, which introduces latent flaws into the test batteries to produce an internal short circuit. This device can help battery manufacturers and testers determine which battery design will best minimize the spread of a thermal runaway-induced fire in the battery or bank of batteries.","category":"energy_power","categoryRaw":"Power Generation and Storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_77","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-77","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-77","confidence":"high"},"type":"patent","title":"Li-ion Cell Calorimeter","abstract":"Innovators at the NASA Johnson Space Center have developed a calorimeter that is able to measure the total heat generated when specific types of Lithium-ion (Li-ion) cells are driven into a thermal runaway condition. By understanding the behavior of a thermal runaway Li-ion battery, designers can improve the cell cases to contain or reduce damages experienced during thermal runaway. For this reason, this technology can benefit many different industries that depend on Li-ion batteries. This NASA Technology is available for your company to license and develop into a commercial product. NASA does not manufacture products for commercial sale.","category":"energy_power","categoryRaw":"Power Generation and Storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_99","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-99","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-99","confidence":"high"},"type":"patent","title":"Triggering Li-ion Battery Cells with Laser Radiation","abstract":"Innovators at NASA Johnson Space Center have developed a high-powered infrared (IR) laser that can trigger Li-ion battery cells into thermal runaway (TR) without perforating the battery\u2019s can wall like previous methods. Inducing TR in a battery cell allows engineers to test and improve the safety performance of overheated batteries that can potentially catch fire or explode. The primary advantage of this method is the heat energy delivered by the laser can be localized to the exact target spot on the battery cell minimizing thermal biasing to adjacent cells. This laser method does not require any internal modification of the test subject cell design nor require patch heating to trigger a short-circuit. Triggering Li-ion Cells with Laser Radiation could work on any commercial battery cell design with only exterior surface treatment required, which can be done by the user.","category":"energy_power","categoryRaw":"Power Generation and Storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_387","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-387","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-387","confidence":"high"},"type":"patent","title":"TerraROVER","abstract":"Innovators at NASA\u2019s Wallops Flight Center have developed the TerraROVER as part of the AEROKATS and Rover Education Network. The TerraROVER is a 3D-printable, remotely controlled wheeled platform designed for educational and research applications. It features electric propulsion for operation on various terrains, including pavement, grass, soil, and even ice or snow with appropriate traction. The platform is built to accommodate a range of sensor systems, such as surface and air temperature sensors, GPS modules, cameras, and data recording or transmission devices. Its modular design allows for easy assembly using 3D-printed parts and commercially available motors, gearboxes, batteries, and radio control components. With the ability to operate via remote control or optional pre-programmed/autonomous modes, the TerraROVER serves as an accessible and versatile tool for training, experimentation, and hands-on learning in STEM education.","category":"environment_climate","categoryRaw":"Environment","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_10","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-10","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-10","confidence":"high"},"type":"patent","title":"Sorbent Polymer Extraction and Remediation System (SPEARS)","abstract":"NASAs Kennedy Space Center has developed a novel method for the in situ removal of polychlorinated biphenyls (PCBs) found in submerged sediments. The technology consists of low-cost polymer spikes that attract and absorb PCBs. Seeking to avoid the pitfalls of current methods for handling PCB-contaminated sediments, NASA researchers developed a new approach for removing the PCBs. A series of polymer spikes, filled with an environmentally green solvent (e.g., ethanol), are first placed into a support frame. The frame is then lowered into submerged areas with PCB-contaminated sediments. Once in contact with the sediments, PCBs are drawn into the polymer spikes through diffusion. The solvent interior of the spikes helps to drive the movement of the PCBs into the spikes. Following PCB removal, the frame is removed and the spikes can be disposed of via incineration or landfilling. As an alternate approach, the spikes could potentially be decontaminated and redeployed.","category":"environment_climate","categoryRaw":"Environment","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_100","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-100","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-100","confidence":"high"},"type":"patent","title":"Modular System for Waste Treatment, Water Recycling, and Resource Recovery","abstract":"Current water recovery and purification systems aboard the International Space Station are open loop (requiring external inputs) and inefficient. Additionally, organic wastes (i.e., fecal and food wastes) are currently not recycled, thus adding additional waste processing and hazardous conditions for astronauts. This is not a viable approach for long duration space habitats and missions. The Modular System for Waste Treatment, Water Recycling, and Resource Recovery technology addresses these problems using a completely closed-loop system of modular subsystems that combine to treat and recycle wastewater streams and organic food waste to produce clean water, gases that can be used for fuel , and fertilizer constituents that can be utilized for plant growth.","category":"environment_climate","categoryRaw":"Environment","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_104","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-104","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-104","confidence":"high"},"type":"patent","title":"Compact System and Method for Treating Urine and Other Wastewater","abstract":"Current space missions face significant challenges in managing waste and recycling resources, especially in closed environments like the International Space Station (ISS). Traditional Environmental Control and Life Support Systems (ECLSS) rely heavily on physical and chemical processes, which demand constant consumable inputs and generate hazardous byproducts. These systems often struggle to efficiently treat and recover valuable resources from waste streams, such as urine and graywater, posing sustainability issues for long-duration space missions and future exploration. Our technology, the Suspended Aerobic Membrane Bioreactor (SAMBR), offers an innovative bioregenerative solution for waste treatment. This system leverages advanced biological nutrient removal (BNR) processes, carbonation, and membrane filtration to effectively treat urine and recover key resources with minimal consumable inputs. By scaling down industrial-scale biological treatment processes for space applications, SAMBR achieves high treatment efficiency within a compact footprint, making it ideal for space missions. This approach not only improves sustainability in space but also has potential applications on Earth, contributing to more efficient and eco-friendly waste management systems.","category":"environment_climate","categoryRaw":"Environment","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_78","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-78","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-78","confidence":"high"},"type":"patent","title":"Activated Metal Treatment System (AMTS) for Paints","abstract":"NASA Kennedy Space Center seeks partners interested in the commercial application of the Activated Metal Treatment System (AMTS) for treating polychlorinated biphenyls (PCBs) in paints. NASAs Kennedy Space Center is offering companies licensing or partnering opportunities in the development of this innovative remediation technology. Current physical removal methods are able to strip off PCB containing paint from surfaces (e.g., media blasting); however, these methods typically create a new waste stream that must be treated according to Toxic Substances Control Act (TSCA)regulation. In contrast, AMTS extracts PCBs and breaks them down into benign by-products while on the structure. Therefore, no additional treatment for PCBs is required. Also, because the treated surface can be reused following application, AMTS has advantages over other methods and often opens up recycling opportunities that would not have been possible prior to AMTS application.","category":"environment_climate","categoryRaw":"Environment","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_81","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-81","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-81","confidence":"high"},"type":"patent","title":"Passive Nutrient Delivery System (PONDS)","abstract":"Reliable seed germination and plant production requires an environment that is neither too dry nor too wet. PONDS was developed to improve water and nutrient delivery for plants grown on the International Space Station (ISS). The technology uses an innovative wicking material to passively link a water/nutrient reservoir to a growth cylinder where seeds are germinated and plants are produced. PONDS addresses limitations with existing ISS plant-production technology by providing consistent delivery of water/nutrients, improving oxygen transfer to plants, and allowing users to determine how much water is being applied.","category":"environment_climate","categoryRaw":"Environment","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_176","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-176","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-176","confidence":"high"},"type":"patent","title":"Carbon Capture Filter","abstract":"On the International Space Station (ISS), the Environmental Control and Life Support System (ECLSS) serves as a waste recovery system, air revitalization system, and oxygen generation system. Recently, Plasma Pyrolysis Assembly (PPA) technology, a supporting technology for CO2 chemical reduction that could enable the recovery of over 86% of the oxygen from CO2 produced on the ISS, has been under development at NASA. One of the main issues with plasma pyrolysis is that it generates effluent containing fine (100-200 nm) particles that could foul the PPA reactor and downstream ECLSS systems. To address this challenge, NASA has developed a new Carbon Capture Filter system that uses a variety of mechanisms to trap and remove solid carbon dust. This NASA invention may provide value for a variety of terrestrial applications requiring continuous or batch removal of solid carbon emissions of pyrolyzed hydrocarbons, or high-capacity removal of inert fine dust. The filter system can be scaled up or down in size to accommodate different applications, and could also be applied for consumer products including portable vacuum cleaners and filter systems.","category":"environment_climate","categoryRaw":"Environment","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_71","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-71","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-71","confidence":"high"},"type":"patent","title":"Low-Power Charged Particle Detector","abstract":"Innovators at NASA's Glenn Research Center have developed a miniature, solid-state radiation detector that can be used in situations where compact size, low weight, and low power consumption are required. Conventional scintillator-based charged particle counters rely upon a glass photomultiplier tube (PMT) to translate light energy from the radiation source into an electrical signal. Because PMTs are bulky, fragile, and require high voltages to operate, they are not well-suited for harsh environments. Glenn's technology is solid state, thus eliminating PMTs, which means the device can operate in cramped, harsh, and low-power environments. In addition, because the detector uses a low-voltage, UV-sensitive photodiode, a wave shifter is not required, improving efficiency and further minimizing weight and bulk. Originally developed for space exploration, this compact, robust particle counter can also be used in medical dosimetry, mining, oil and gas exploration, nuclear facility monitoring, and more.","category":"environment_climate","categoryRaw":"Environment","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_82","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-82","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-82","confidence":"high"},"type":"patent","title":"Air Revitalization for Vacuum Environments","abstract":"NASA has developed a lightweight atmosphere revitalization system to support short-duration human space flights. Air revitalization is a critical component of manned space flights since passenger-carrying vehicles require a way to control humidity and process metabolic carbon dioxide to sustain an environment that can support human life. For long-duration flights, metabolic water from respiration and evaporated sweat are typically treated and reclaimed, requiring extra equipment such as gas/liquid separators and condensing heat exchangers. To minimize equipment and reduce excess loads, NASA developed an adsorption-based carbon dioxide scrubber and water removal system for disposal in vacuum environments, ultimately reducing mass, power, and volume requirements. The lightweight , low-mass system is also regenerable, flexible, and can be arranged into different spatial configurations.","category":"environment_climate","categoryRaw":"Environment","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_118","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-118","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-118","confidence":"high"},"type":"patent","title":"Corkscrew Filter Extracts Liquid From Air Charge","abstract":"Innovators at NASA Johnson Space Center in collaboration with IRPI, LLC, have developed a compact inline filter that utilizes a unique multi-phase flow method to separate liquid from an incoming air charge. The filter also traps particulate matter and does so without significantly impinging upon flow velocity. Unique to the filter is a multitude of helical (corkscrew-shaped) open flow channels that are impregnated into the filter element. Due to the constant curvature of the channels, the liquid and particulates from the incoming air charge are inertially dispersed onto the channel walls using centrifugal force. Wicking material holds the liquid in place, while stepped contours within the channels also help trap particulates. Development of the filter was performed to provide the Orion Spacecraft with a method to absorb liquid water and particulates from the cabin atmosphere after a fire event and discharge of a water-based fire extinguisher. However, applications here on Earth have commercial viability for this high-flow phase separation technology. These applications may include vehicle or laboratory fire safety systems, petrochemical refining, water filtration, municipal solid waste derivatives, and wet/dry vacuum systems.","category":"environment_climate","categoryRaw":"Environment","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_147","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-147","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-147","confidence":"high"},"type":"patent","title":"Modular Container System Preserves Sample Integrity","abstract":"Innovators at NASA Johnson Space Center have developed a modular container system, or \u201cMCS\u201d for short, that provides a portable extension to laboratory gloveboxes for the contaminant-free transport and storage of samples of interest. Designed to minimize the oxygen concentration within its sample container, the MCS has been designed for containment of precious extraterrestrial sample material, and can readily facilitate sample transport to members of the global scientific community for analysis. A sample of interest needs to be kept in a low-oxygen environment during transport and storage that is comparable to its working envi-ronment within a science glovebox. Previous container designs could not provide the low-oxygen environment for more than a couple days in ambient conditions. The MCS has been tested in various configurations and sizes and is designed to provide a stable low-oxygen environment ranging from months to years. The MCS provides a high-value proposition for industries where sample or component integrity is compromised by trace oxygen and moisture. The Modular Container System (MCS) is now available for patent licens-ing. Please note that NASA does not manufacture products itself for commercial sale.","category":"environment_climate","categoryRaw":"Environment","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_44","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-44","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-44","confidence":"high"},"type":"patent","title":"Robonaut 2: Hazardous Environments","abstract":"Researchers at the NASA Johnson Space Center (JSC) in collaboration with General Motors and Oceaneering, have designed a state-of-the-art, highly dexterous, humanoid robot: Robonaut 2 (R2). R2 is made up of multiple systems and sub-components: vision systems, image recognition systems, sensors, control algorithms, and much more. R2's nearly 50 patented and patent-pending technologies have the potential to be game-changers in multiple industries. One of the most promising application for the R2 technologies is in the area of hazardous environments. R2 has the capability to work in remote locations separate from the human controller. R2 can function autonomously or it can be controlled by direct teleoperations. This NASA Technology is available for your company to license and develop into a commercial product. NASA does not manufacture products for commercial sale.","category":"environment_climate","categoryRaw":"Environment","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_53","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-53","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-53","confidence":"high"},"type":"patent","title":"Microwave-Based Water Decontamination System","abstract":"Innovators at the NASA Johnson Space Center have developed a microwave based system that eradicates bacteria. The technology can be used to treat water systems to generate potable water. The technology was originally developed to address the water purification needs and challenges on the International Space Station (ISS). Current water purification methods onboard the ISS use hazardous chemicals and require consumable products to be transported from Earth to the ISS. This NASA Technology is available for your company to license and develop into a commercial product. NASA does not manufacture products for commercial sale.","category":"environment_climate","categoryRaw":"Environment","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_68","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-68","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-68","confidence":"high"},"type":"patent","title":"Pre-Treatment Solution for Water Recovery","abstract":"Innovators at NASA Johnson Space Center have developed a pre-treatment solution, currently being used aboard the International Space Station (ISS), that increases the amount of potable water recovered through the ISS's urine processor assembly (UPA). The solution acts to stabilize flushed urine chemically for immediate storage and later distillation in the UPA and increases water recovery without precipitation of minerals that clog urine-processing hardware. Implemented by NASA aboard the ISS since 2016, the solution has increased the water recovery rate in the ISS\u2019s UPA from the prior 75% level to a steady 87%, which doubled the volume of feed processed per cycle, reduced the volume of waste brine by half, and eliminated the formation of precipitates. The benefits extend to other steps in the urine treatment process. Less precipitate reduces the frequency of filter changes in the UPA and thus the number of filters used per gallon during the distillation stage. Furthermore, this pretreatment solution can prevent bacterial and fungal growth during storage of urine. This technology is at a technology readiness level (TRL) 9 ( flight proven through successful mission operations), and the innovation is now available for your company to license. Please note that NASA does not manufacture products itself for commercial sale.","category":"environment_climate","categoryRaw":"Environment","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_295","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-295","sourceUrl":"https://technology.nasa.gov/patent/TOP2-295","confidence":"high"},"type":"patent","title":"Completely biodegradable filtration system for waste metal recovery from aqueous solution","abstract":"Rapid socio-economic development and technological advancement has made the hazardous chemical components of end-of-life electronics waste (e-waste) an imminent challenge. Conventional extraction methods rely on energy-intensive processes and are inefficient when applied to recycling e-waste or waste streams that contain mixed materials and small amounts of metals. NASA Ames Research Center has developed an inexpensive biological approach to removing or adsorbing a target substance or material, for example a metal, non-metal toxin, dye, or small molecule drug, from solution. Using a substrate such as fungal mycelium or chitin, with a peptide, the target substance is isolated and removed or recovered. This approach has a variety of useful applications, from cleaning water sources or recovering chemicals from aqueous solutions to minimize waste.","category":"environment_climate","categoryRaw":"Environment","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_208","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-208","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-208","confidence":"high"},"type":"patent","title":"Fast and widely tunable monolithic optical parametric oscillator for laser spectrometer","abstract":"For remote sensing spectrometers, wavelength-scanned laser emissions are used to capture the absorption spectrum of targets to perform measurement of soil and/or gas. Previous techniques to accomplish these measurements have involved combining multiple fixed wavelength lasers to detect a single species, limiting the scope and effectiveness of the instruments. This new technology alleviates this problem.","category":"imaging_optics","categoryRaw":"Optics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_270","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-270","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-270","confidence":"high"},"type":"patent","title":"Active Pointing and Tracking System in Laser Satellite to Satellite Tracking (SST)","abstract":"In laser satellite to satellite tracking for gravity measurements, satellite to satellite separation is measured to the highest precision possible (less than one micrometer). The measurement is conducted with laser links between two satellites, where the laser optical phase change is measured as a function of time. Satellite yaw and pitch causing optical path length change is a major error source. In current systems, path length change compensation is achieved with a sophisticated optical bench design.","category":"imaging_optics","categoryRaw":"Optics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_352","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-352","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-352","confidence":"high"},"type":"patent","title":"3D Lidar for Improved Rover Traversal and Imagery","abstract":"Planetary and lunar rover exploration missions can encounter environments that do not allow for navigation by typical, stereo camera-based systems. Stereo cameras meet difficulties in areas with low ambient light (even when lit by floodlights), direct sunlight, or washed-out environments. Improved sensors are required for safe and successful rover mobility in harsh conditions. NASA Goddard Space Flight Center has developed a Space Qualified Rover Lidar (SQRLi) system that will improve rover sensing capabilities in a small, lightweight package. The new SQRLi package is developed to survive the hazardous space environment and provide valuable image data during planetary and lunar rover exploration.","category":"imaging_optics","categoryRaw":"Optics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_355","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-355","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-355","confidence":"high"},"type":"patent","title":"Reduced PIC fabrication cost by one-step method","abstract":"Researchers at the NASA Goddard Space Center have developed an innovative technique that allows photonic integrated circuit (PIC) chips with multiple devices to be produced with only a single round of electron beam lithography and etching. Traditionally, fabricating PICs with different types of lasers or devices within the same area requires multiple costly and time-consuming lithography cycles. By introducing a central, non-etched gap along the length of the device between the etched gratings, at least two photonic devices can be fabricated during one lithography and etching cycle. The new geometry allows an engineer to design integrated devices with differing optical properties by varying the non-etched gap width and the etch depth. This innovative approach dramatically reduces manufacturing time and costs while maintaining performance with applications in PIC-based devices across the space, communication, autonomous vehicle, and biomedical industries.","category":"imaging_optics","categoryRaw":"Optics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_364","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-364","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-364","confidence":"high"},"type":"patent","title":"Portable Integrated Fourier Ptychographic Microscope","abstract":"Fourier ptychographic microscopy (FPM) seeks to address the tradeoff between resolution and field-of-view (FoV) experienced by conventional imaging methods. The technique combines multiple low-resolution images captured under varying illumination angles to reconstruct a single, high-resolution, wide FoV image. Key challenges in FPM devices include lack of portability (preventing use in the field) and long image reconstruction times (preventing real-time feedback, decreasing throughput and efficiency, and leading to poor user experience that presents a barrier to adoption). Originally designed for biosignature detection and motility in liquid samples, NASA\u2019s Goddard Space Flight Center has developed a compact, portable inferencing device comprised of a FPM integrated with a microfluidic device to perform wide FoV, sub-micron spatial resolution imaging of several different sample types. NASA has significantly improved FPM device technology by creating a small portable device that leverages algorithms to perform self-calibration of LED positions and trained, sample type-specific neural networks for recording and image reconstruction. These algorithmic optimizations allow for near real-time image reconstruction.","category":"imaging_optics","categoryRaw":"Optics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_382","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-382","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-382","confidence":"high"},"type":"patent","title":"LiDAR with Reduced-Length Linear Detector Array","abstract":"In recent years, LiDAR innovations have significantly improved instrument sensitivity and efficiency while reducing size, weight, and power requirements. Future Earth and planetary science missions require more compact and efficient ranging LiDARs capable of probing multiple profiles and enabling 3D imaging. However, a key limitation is the size of available 1D detector arrays within LiDAR systems, which constrains the footprint swath. To address this challenge, engineers at NASA Goddard Space Flight Center developed the LiDAR with Reduced-Length Linear Detector Array, an advancement in next-generation LiDAR technology that enables multi-track swath mapping with 3D imaging. This invention introduces new methods to minimize the required 1D detector array size, reduce speckle noise, and lower unwanted solar photon counts\u2014without the need for additional gratings. By substantially decreasing form factor and power requirements while enhancing performance, this innovation provides users with greater operational flexibility and expanded capabilities while reducing costs.","category":"imaging_optics","categoryRaw":"Optics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_323","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-323","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-323","confidence":"high"},"type":"patent","title":"LIDAR System Noise Reduction","abstract":"In order to overcome significant noise from solar background and backscatter this LIDAR system utilizes a laser light source that is azimuthally polarized or has Orbital Angular Momentum (OAM). A photon sieve is used to produce a ring pattern on the focal plane corresponding from the light of the return signal and causes stray light that is not polarized to produce a clustered region at the center of the ring pattern that is distinct from the laser return. The photon sieve can be used as the front end lens of a telescope or as an internal optical component after a traditional telescope. This technology can also be employed in encrypted communications and navigation.","category":"imaging_optics","categoryRaw":"Optics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_346","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-346","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-346","confidence":"high"},"type":"patent","title":"Beam Crossing Optical System","abstract":"NASA's Langley Research Center has developed a Beam Crossing Optical System for use in two-point Focused Laser Differential Interferometers (FLDI) that are used in measuring density disturbances in hypersonic flows. Conventional single point FLDI systems only measure how flow fluctuates. In contrast, with the two-point system, velocity can be measured between the two points to compute spatial changes and measure fluctuating flow. In this design, laser beams propagating between the transmitter and receiver sides of the FLDI instrument remain parallel to one another so that velocity bias errors that occur in the conventional testing region with angled beams are eliminated, increasing accuracy and decreasing uncertainty of sensitivity measurements. The technology offers a lower-cost (half the cost) alternative to a Nomarski Prism approach and enables increased manipulation capabilities for the user, such that the separation distance between points and laser beam orientation can be manually adjusted with ease.","category":"imaging_optics","categoryRaw":"Optics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_347","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-347","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-347","confidence":"high"},"type":"patent","title":"Reflection-Reducing Imaging System for Machine Vision Applications","abstract":"NASA researchers have developed a compact, cost-effective imaging system using a co-linear, high-intensity LED illumination unit to minimize window reflections for background-oriented schlieren (BOS) and machine vision measurements. The imaging system \u2013 tested in NASA wind tunnels \u2013 can reduce or eliminate shadows that occur when using many existing BOS and photogrammetric measurement systems; these shadows occur in existing systems for a variety of reasons, including the severe back-reflections from wind tunnel viewing port windows and variations in the refractive index of the imaged volume. Due to its compact size, the system can easily fit in the space behind a typical wind tunnel\u2019s view port. As a cost-effective, compact imaging system, NASA\u2019s technology could be deployed for use in BOS, Tomo BOS, photogrammetric, and general machine vision applications.","category":"imaging_optics","categoryRaw":"Optics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_378","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-378","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-378","confidence":"high"},"type":"patent","title":"Fingerprinting for Rapid Battery Inspection","abstract":"Dendrite growth in lithium-ion batteries can lead to fires and explosions, limiting battery life and safety. High resolution radiographs can be used to detect subtle precursors to battery failure, but it can be tedious to collect and combine these radiographs over the course of testing many battery samples. NASA researchers developed a novel technique for creating unique orientation fingerprints on battery samples prior to digital radiograph collection. The fingerprints enable rapid assembly of high-resolution images. This allows efficient inspection of batteries for early signs of dendrite formation, improving safety and extending useful battery life. This technology can improve efficiency in battery R&D, battery production, and other electronics applications.","category":"imaging_optics","categoryRaw":"Optics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_389","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-389","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-389","confidence":"high"},"type":"patent","title":"Thermally-Adaptive Solid State Laser Crystal Mount","abstract":"NASA\u2019s solid-state laser crystal mounting technology was developed for and implemented in high-energy pulsed 2-micron laser transmitters for airborne differential absorption LIDAR used in measuring carbon dioxide concentrations in the atmosphere and Coherent Doppler lidar used for atmospheric winds. The mount is designed for cubic, tetragonal or orthorhombic laser crystals, such as yttrium aluminum garnet (YAG), yttrium lithium fluoride (YLF), and yttrium orthoaluminate (YALO), respectively, operating in high energy pumped laser transmitters. These crystals are prone to fracturing in use due to the heat generated and resulting unsymmetrical properties, such as thermal expansion, of the crystal. Most of the energy pumped into a laser crystal becomes excess heat. The faster and more uniformly this heat is dissipated, the better the laser beam performance and the lower the chance of crystal fracture. NASA\u2019s laser crystal mount has been used in an actual laser transmitter system and has essentially eliminated the risk of thermally-induced damage to the laser crystal. Research indicated that the mount reduced the crystal damage rate from 17 crystals in a single year to no-damaged crystals for 4 years. The design offers unrestrained thermal expansion of the crystal while maintaining alignment position and continuous contact with the heat sink.","category":"imaging_optics","categoryRaw":"Optics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_393","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-393","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-393","confidence":"high"},"type":"patent","title":"All-Solid-State Frequency Agile Filter (AF2)","abstract":"A thin-film interference filter (TFIF) is an optical device that uses light interference to selectively transmit, reflect, or block specific wavelengths. TFIFs are used in imaging systems like LiDAR to control the light reaching the detector and are easily mass-produced with excellent optical performance. However, TFIFs typically target specific wavelengths or narrow bands. Thus, multispectral applications require multiple TFIFs. Traditionally, this is done with motorized filter wheels, which add bulk, cause slower response, limit spectral resolution, and introduce moving parts subject to wear and tear. Alternatively, liquid crystal tunable filters (LCTFs) enable rapid electronic tuning without mechanical movement, improving speed and compactness, though they still have limitations including polarization sensitivity, low throughput, narrow spectral range, slow switching times (milliseconds), and high cost. In an effort to improve upon the limitations of motorized filter wheels and available tunable filters, engineers at NASA\u2019s Langley Research Center have developed an all-solid-state frequency agile filter (AF2) based on exotic phase change materials (PCMs). This innovative technology is capable of fast (MHz to GHz in nanoseconds) and wide (500nm \u2013 ~15 micrometer) spectral tuning. Furthermore, the filter has no moving parts and is polarization insensitive, making it an excellent solution for applications requiring multispectral filtering.","category":"imaging_optics","categoryRaw":"Optics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_398","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-398","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-398","confidence":"high"},"type":"patent","title":"Multi-Edge Slant Target for Non-Localized MTF Measurement","abstract":"High-speed flight, whether by spacecraft, launch vehicles, or hypersonic aircraft , subjects vehicles to extreme thermal, aerodynamic, and structural loads. To refine predictive models and drive improved designs, NASA\u2019s Scientifically Calibrated In-Flight Imagery (SCIFLI) team develops and operates advanced airborne imaging systems that collect high-resolution, multispectral imagery of these flights. Characterizing imager performance is critical to ensuring spatially accurate data is collected. The Modulation Transfer Function (MTF) is a key metric for understanding the quantitative spatial performance (i.e. sharpness and image resolution) of high-precision imaging systems. Conventional slanted-edge MTF targets, however, capture only localized MTF measurements (at the center of the focal plane) or are designed only for the visible light spectrum. Thus, they overlook sharpness variations toward the corners of the focal-plane array and/or have little utility for imaging wavelengths longer than near-infrared. NASA\u2019s new Multi-edge MTF Slant Target provides a solution that fills these gaps. Developed by innovators from NASA Langley Research Center\u2019s SCIFLI team, the target\u2019s array of precisely oriented edges magnified under a large focal length lens span the entire field of view of the sensor, providing global MTF measurements from corner to corner. Materials selection and illumination strategy render the target suitable for measurements from the UV-VIS to MWIR spectra.","category":"imaging_optics","categoryRaw":"Optics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_108","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-108","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-108","confidence":"high"},"type":"patent","title":"Ruggedized Infrared Camera","abstract":"Innovators at the NASA Marshall Space Flight Center have developed a ruggedized infrared (IR) camera system for harsh environments. The new technology is a space-rated IR camera assembly based on a FLIR Systems Boson\u00ae Model No. 640. Advanced modifications allow the camera to survive high-vibration environments (e.g., launch) and improve heat removal for operation in a range of harsh conditions including vacuum. Designed for NASA use in Earth orbit and beyond, the camera has a combination of characteristics not currently available in commercial camera offerings. The IR camera assembly has been fully tested and qualified for operation in extreme conditions including high vibration, shock, vacuum, and temperature cycling. Although designed for space applications, the assembly may also be valuable for harsh environment terrestrial uses.","category":"imaging_optics","categoryRaw":"Optics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_40","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-40","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-40","confidence":"high"},"type":"patent","title":"Nested Focusing Optics for Compact Neutron Sources","abstract":"NASA's Marshall Space Flight Center has developed novel neutron grazing incidence optics for use with small-scale portable neutron generators. The technology was developed to enable the use of commercially available neutron generators for applications requiring high flux densities, including high performance imaging and analysis. Nested grazing incidence mirror optics, with high collection efficiency, are used to produce divergent, parallel, or convergent neutron beams. Ray tracing simulations of the system (with source-object separation of 10m for 5 meV neutrons) show nearly an order of magnitude neutron flux increase on a 1-mm diameter object. The technology is a result of joint development efforts between NASA and MIT researchers seeking to maximize neutron flux from diffuse sources for imaging and testing applications.","category":"imaging_optics","categoryRaw":"Optics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_134","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-134","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-134","confidence":"high"},"type":"patent","title":"Color Filtering Software Enhances Material Strain Analysis","abstract":"Innovators at NASA Johnson Space Center have developed a technology that can isolate a single direction of tensile strain in biaxially woven material. This is accomplished using traditional digital image correlation (DIC) techniques in combination with custom red-green-blue (RGB) color filtering software. DIC is a software-based method used to measure and characterize surface deformation and strain of an object. This technology was originally developed to enable the extraction of circumferential and longitudinal webbing strain information from material comprising the primary restraint layer that encompasses inflatable space structures. Whereas traditional methods of monochrome DIC can only measure strain in each of the biaxial directions separately, this DIC with RGB color filtering technology can measure strain in a single analysis. The analysis process begins by applying a speckled pattern to the subject material to which multiple photographic images are generated from a set of stereo cameras. These images are correlated/analyzed in post-processing to determine relative displacement of the speckles across a surface when testing for tensile strain. Traditional DIC software assumes a solid material substrate, but in interwoven materials the substrate consists of bi-directional patterns. This causes errors in strain data derived when the analysis is performed by DIC software alone.","category":"imaging_optics","categoryRaw":"Optics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_370","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-370","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-370","confidence":"high"},"type":"patent","title":"Ultra-low Reflectivity Black Silicon Pupil Masks","abstract":"NASA\u2019s direct imaging missions for exoplanet discovery rely on coronagraph masks to reduce light scattering and diffraction. These masks play a crucial role in improving contrast and suppressing unwanted reflections, enabling the detection of faint celestial objects. However, traditional masks have limitations in absorption and surface uniformity, leading to residual reflections that hinder optimal imaging performance. This NASA innovation is a novel process utilizing cryogenic etching of black silicon (BSi) to fabricate highly absorptive pupil masks for coronagraphs. By employing black silicon structures, the technology achieves extremely high light absorption and significantly reduces specular reflectance, thereby enhancing the effectiveness of coronagraphic imaging .","category":"manufacturing","categoryRaw":"Manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_379","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-379","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-379","confidence":"high"},"type":"patent","title":"Novel Process to Create Structured Membrane Films for Micromachining Applications","abstract":"Conventional micromachining and etching techniques used in microelectromechanical (MEMS) devices have several disadvantages such as the use of etch stop materials, the use of hazardous gases and specialized equipment, and localized heating effects. As a result, devices or membranes may be damaged or unnecessary redeposition of materials may be required. While wet etching is often employed to mitigate these issues, it presents its own challenges, such as the need to protect MEMS devices during the process and the risk of structural damage when forming openings in membranes. To address these limitations, a new process for protecting membranes during wet etching is needed. Researchers at NASA\u2019s Goddard Space Flight Center have developed an innovative method for creating structured membrane films, enabling the micromachining of ultra-thin membranes and micro/nano-scale structures. This invention utilizes XHRiC in combination with a potassium hydroxide etch to produce an ultra-thin silicon nitride membrane with metal leads and precise membrane cuts.","category":"manufacturing","categoryRaw":"Manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_385","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-385","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-385","confidence":"high"},"type":"patent","title":"Fabrication of Binary Phase Photon Sieves","abstract":"Conventional methods for focusing extreme ultraviolet (EUV) light are challenged by its high energy and short wavelength, which result in chromatic aberrations and material limitations. Photon sieves, which utilize perforated membranes, offer a solution for EUV applications requiring large-area structures. Achieving higher optical efficiency demands that the opaque region of a binary amplitude sieve to be thin enough to allow transparency while still enabling the necessary phase shift. In EUV applications, submicron-thick membranes help mitigate high material losses, but fabricating sieves with small features \u2013 such as 2 \u00b5m openings with 2 \u00b5m gaps \u2014 remains a significant challenge. To address these limitations, innovators at NASA\u2019s Goddard Space Flight Center have developed a method for fabricating binary phase photon sieves using silicon and niobium to achieve precise focus and high-resolution imaging in applications like solar observation.","category":"manufacturing","categoryRaw":"Manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_88","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-88","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-88","confidence":"high"},"type":"patent","title":"Regolith-Polymer 3D Printing","abstract":"The history of construction materials and methods has evolved over time, with Portland cement concrete being the most widely used material on Earth. Constructing habitats and infrastructure on the Moon and Mars, however, requires a different approach given the lack of such conventional construction resources and materials . Recognizing the need for in-situ resource utilization (ISRU) to support long-duration human missions to the Moon and Mars, NASA's Kennedy Space Center and Sidus Space have developed a novel three-dimensional print head apparatus using regolith-polymer mixtures as a building material. The invention paves the way for enabling the construction of habitats and other critical infrastructure on the Moon and other planetary bodies using available resources. The Regolith-Polymer 3D Printing System can also be adapted to work with other crushed rock materials or mixtures depending on resource availability at construction sites.","category":"manufacturing","categoryRaw":"manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_89","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-89","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-89","confidence":"high"},"type":"patent","title":"Lunar Landing Pads","abstract":"Lunar landing and launch pads represent critical infrastructure for enabling a sustained presence on the Moon or other planetary bodies. Such a Moon presence would require repeated lunar landings and takeoffs, preferably near an outpost or habitat. In the absence of takeoff and landing pads, such vehicles could project lunar regolith at high velocities, \u201csandblasting\u201d the surrounding infrastructure and causing damage. Conventional paver technology does not have the capability to withstand the loads experienced by landing pads during vehicle landing or take off. Use of existing technology may result in pavers being displaced by the plume of the vehicle, or exhaust from the vehicle entering spaces between paver seams and eroding the regolith underneath the landing pad. To address this issue, engineers at NASA's Kennedy Space Center and Sidus Space developed a novel interlocking paver system enabling the robotic construction of high stability vertical takeoff and landing pads.","category":"manufacturing","categoryRaw":"Manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_158","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-158","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-158","confidence":"high"},"type":"patent","title":"X-Ray Diffraction Method to Detect Defects in Cubic Semiconductor (100) Wafers","abstract":"NASA Langley Research Center has developed a method of using x-ray diffraction (XRD) to detect defects in cubic semiconductor (100) wafers. The technology allows non-destructive evaluation of wafer quality in a simple, fast, inexpensive process that can be easily incorporated into an existing fab line. The invention adds value throughout the semiconductor industry but is especially relevant in high end, high speed electronics where wafer quality has a more significant effect on yields.","category":"manufacturing","categoryRaw":"manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_225","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-225","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-225","confidence":"high"},"type":"patent","title":"Abnormal Grain Growth Suppression in Aluminum Alloys","abstract":"This innovation is a thermal processing methodology for retaining the fine-grained structure in aluminum alloys subjected to solid state welding and subsequent forming processes.","category":"manufacturing","categoryRaw":"manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_249","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-249","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-249","confidence":"high"},"type":"patent","title":"Blocking/Deblocking Resin Systems","abstract":"Similar to resin systems currently used in composites for aerospace structural applications such as toughened epoxies, this innovation is a modification to traditional resin chemistry to prevent polymerization and crosslinking of the resin when heated and pressed in an autoclave or other common resin curing system. The chemical modification uses blocking groups to block the reactive functional groups in the resin to prevent curing reactions from completing. The blocking groups can be removed by one of several means. Once deblocked, the resin can be cured in an identical manner to an unmodified resin system. The resulting structure is one continuous part without the need for additional fasteners.","category":"manufacturing","categoryRaw":"Manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_252","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-252","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-252","confidence":"high"},"type":"patent","title":"Free-Form Fabrication Using Electrically Conductive Filaments","abstract":"The use of multifunctional composites such as mechanically reinforced, electrically and thermally conductive parts is of interest in a range of application areas. Especially interesting and important is where tailorability of function is achieved by strategic placement of materials with unique functionality in locations that may not be accessible by conventional manufacturing techniques. Examples include embedded conductive paths interspersed in components to act as sensing elements, or as heaters, or to carry current to power to permit other components to be plugged in. The processing of these materials requires adhesion of filaments to each other, as well as to a substrate.","category":"manufacturing","categoryRaw":"manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_260","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-260","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-260","confidence":"high"},"type":"patent","title":"Single Crystal SiGe/Sapphire Epitaxy","abstract":"NASA&#39s Langley Research Center has developed a new, low temperature method of SiGe/sapphire growth that produces the same single crystal films with much less thermal loading effort to the substrate. This eliminates the time-consuming and costly high heating, long thermal soak times, and interfacial Si layer. Yield and throughput are increased as time to production is reduced from over 4 hours to less than 1 hour. The same quality of SiGe/sapphire is produced with far less effort and time, bringing it to within the realm of mass production.","category":"manufacturing","categoryRaw":"manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_304","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-304","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-304","confidence":"high"},"type":"patent","title":"Simplified Complimentary Metal-oxide-semiconductor Manufacturing Technique","abstract":"Current microfabrication methods are well established for processing of Si-based complementary metal-oxide-semiconductor (CMOS) and only get more complex with each iteration. This is especially true with 3D transistors that require very selective placement and selective removal of materials required to reach a working product. However, with NASA's newly developed masking and deposition processes, photoresists, UV exposures and selective etching can be eliminated, with metal removal reduced to only planarization. This revised process reduces the total material and time requirements drastically when compared to current standards. These advancements offer the benefits of increasing total possible throughput while simultaneously reducing manufacturing cost per unit.","category":"manufacturing","categoryRaw":"manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_327","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-327","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-327","confidence":"high"},"type":"patent","title":"System for In-situ Defect Detection in Composites During Cure","abstract":"Innovators at the NASA Langley Research Center, in collaboration with Analytical Mechanics Associates, have developed an automated ultrasonic scanning system for in-situ cure monitoring and defect detection of composites in an autoclave or an oven. This non-destructive evaluation system is based on an ultrasonic contact scanner enclosed in an insulated vessel placed inside of the autoclave. The system actively scans for any defects that may form in composites during the cure process and tracks movement of defects originating during layup or cure. Typically, non-destructive evaluation of composites, by ultrasound or other means, is conducted either before or after the cure process, but many defects vanish and form during cure. NASA's in-situ cure monitoring system, by contrast, provides real-time monitoring of defect formation and movement during cure. This not only offers a better understanding of defect sources and sinks, but also the ability to more accurately validate process models for the prediction of cure process defects.","category":"manufacturing","categoryRaw":"manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_337","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-337","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-337","confidence":"high"},"type":"patent","title":"Recyclable Feedstocks for Additive Manufacturing","abstract":"Innovators at the NASA Langley Research Center have developed a manufacturing technique to generate recyclable feedstocks for on-demand additive manufacturing. Additive manufacturing is a rapidly advancing art with significant recent improvements in starting materials. One common limitation has been that produced articles cannot be recycled without substantial energy costs. Development of a manufacturing technique that can generate precise, mechanically robust articles that could be reverted to feedstock for use in subsequent article manufacturing would be highly desirable for applications including long duration extra-terrestrial exploration mission planning. NASA's new manufacturing technique uses polymer-coated epoxy micro-particle systems as a recyclable feedstock material that can be used not only for in-space additive manufacturing during long-term human spaceflight but also for a wealth of applications on Earth. The resulting articles are more chemically and mechanically robust compared to the state-of-the-art materials used for most 3D printing applications.","category":"manufacturing","categoryRaw":"manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_339","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-339","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-339","confidence":"high"},"type":"patent","title":"Calibration System for Automated Fiber Placement","abstract":"Innovators at NASA's Langley Research Center have developed a Calibration System for Automated Fiber Placement (AFP) machines. AFP is a modern composites-manufacturing method offering speed, repeatability, and waste-minimization benefits over traditional layup techniques. Used to make aerospace parts and wind-turbine blades, AFP employs a robotic arm to apply strips of carbon fiber prepreg (aka composite tape, or tows) to build up a composite part layer by layer. While advantageous, any imperfectly placed (or slipped) tows generate lap-and-gap defects relative to adjacent tows which can degrade structural integrity by as much as 30%. Currently, manual visual inspection is used to identify and fix such defects before curing, which is highly labor intensive. In-situ inspection systems are emerging, but no method exists to create accurate \"defect standards\" to facilitate active system calibration. NASA's new calibration system will enable the next generation of AFP in situ inspection technologies.","category":"manufacturing","categoryRaw":"manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_342","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-342","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-342","confidence":"high"},"type":"patent","title":"Automated Tow/Tape Placement System","abstract":"In recent years, industry adoption of thermoplastic composites (TPCs) in lieu of thermosets and metallic structures has increased for the fabrication of air and launch vehicle components. Manufacturing of TPCs, performed via automated tape laying (ATL) and automated fiber placement (AFP), uses machines that place prepreg tow or tapes on molds in a unidirectional manner, which then undergo cure cycles, autoclaving, and other steps that require special tooling. The process is time, material, and energy intensive, requires large facilities to house equipment, and limits the size, mechanical properties and shapes of the parts manufactured. To address these limitations, NASA\u2019s Langley Research Center has developed a simplified, tool-less automated tow/tape placement (ATP) system. The invention uses two opposed ATP cars working in tandem to achieve tool-less operation, bidirectional lay-up, and expansion of the design space and size of TPC components that can be manufactured using ATP systems.","category":"manufacturing","categoryRaw":"Manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_357","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-357","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-357","confidence":"high"},"type":"patent","title":"AERoBOND: Large-scale Composite Manufacturing","abstract":"NASA Langley Research Center has an improved method for making composite structures. Industrial composite manufacturing is primarily accomplished through three methods: co-cure, co-bond, and secondary bond processes. Co-cure produces predictable structures and joint properties but is costly and challenging to implement on large, complex structures. Co-bond and secondary bond processes have greater applicability to complex structures but produce unpredictable material interfaces and properties. NASAs AERoBOND technology presents a method for manufacturing composites at scale with the reliability of co-cure in a bonded assembly process. AERoBOND utilizes novel epoxy and barrier ply layers with optimized chemical and physical properties to enable the bonding of large, complex composites with the advantages of co-cure assembly but without the need for redundant fasteners, thus reducing assembly time and cost.","category":"manufacturing","categoryRaw":"manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_397","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-397","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-397","confidence":"high"},"type":"patent","title":"Optimization of X-Ray CT Measurement Accuracy for Metal AM Components","abstract":"In aerospace and other industries, metal additive manufacturing (AM) technologies are poised to enable the rapid production of complex, custom components that provides a host of advantages. However, metal AM exhibits high complexity compared to conventionally manufactured parts (e.g., point-by-point deviations in grain structure, material properties, and defect conditions). These complexities make it difficult to ensure accuracy and detectability of critical defects via nondestructive evaluation (NDE). As a result, despite their promise, few metal AM parts have made their way into commercial use for safety-critical applications ( aerospace , medical, etc.). X-Ray Computed Tomography (X-Ray CT) has become the gold standard for volumetric characterization of metal AM components. However, X-Ray CT can have defect detection measurement uncertainty, particularly for porosity (the most prominent safety-critical defect in metal AM). A recent study of different labs performing X-Ray CT-based inspection of metal AM parts found that, across 10 different facilities, maximum pore size measured varied by a factor of 4.5 and bulk porosity estimated varied by over a factor of 7! Clearly, a new highly accurate and reliable technique is required that can help develop and can improve the accuracy and reliability of part-specific X-ray CT NDE to speed up certification, enabling industry to realize the advantages of metal AM components for safety-critical applications.","category":"manufacturing","categoryRaw":"Manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_6","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-6","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-6","confidence":"high"},"type":"patent","title":"Fabrication of Fiber-Metal Laminates with Non-Autoclave Processes","abstract":"NASAs Langley Research Center developed a new technique that enables the preparation of metal/composite hybrid laminates, also known as fiber-metal laminates (FML), through a one-step processing method. Currently FMLs are prepared by a compression process using a press or autoclave with metallic layers sandwiched between layers of glass or graphite prepreg (preimpregnated fibers with a matrix resin). NASAs process essentially eliminates the need to produce prepreg prior to the production of a hybrid laminate. It also allows the production of large, net shape structures that were previously not possible with autoclave or press technologies due to size constraints. This infiltration and infusion process can be accomplished using pressure (resin transfer molding [RTM]), or a vacuum induced pressure differential (vacuum assisted resin transfer molding [VARTM]).","category":"manufacturing","categoryRaw":"manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_99","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-99","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-99","confidence":"high"},"type":"patent","title":"Plasma Deposition of Metal in Composite Panels","abstract":"NASA's Langley Research Center has developed a new technique to enable the preparation of metal/composite hybrid laminates, also known as fiber metal laminates (FML), by depositing metal directly onto fabric using a plasma deposition process. FMLs provide a useful combination of structural and functional properties for both aerospace and non- aerospace applications. Currently, FMLs are prepared in a compression process utilizing a press or autoclave with metallic layers (foils) sandwiched between layers of glass or graphite prepreg (preimpregnated fibers with a matrix resin). The NASA process deposits the metal on the fiber via plasma deposition. The porosity of the coated fabric allows for resin infusion.","category":"manufacturing","categoryRaw":"manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_171","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-171","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-171","confidence":"high"},"type":"patent","title":"Rapid Aerogel Prototyping Using 3D Printing","abstract":"Inventors at NASA's Glenn Research Center have developed a novel rapid prototyping methodology for the additive manufacturing of polymer aerogels through 3D printing within a viscous sacrificial support medium. This approach overcomes longstanding limitations associated with the processing of ultra\u2013low-density polymer networks by decoupling geometric fidelity from material rheology and gravitational stability during fabrication. By directly depositing a polyimide precursor into a yield-stress, optically transparent sacrificial medium, complex three-dimensional architectures are formed with precise spatial control while preventing structural collapse, sagging, or filament coalescence during printing. This rapid prototyping technique can be used with a variety of underlying polymer architectures for applications in thermal insulation, acoustic barriers, and vibration mitigation, among others. A polymer aerogel is an ultra-lightweight, highly porous solid made from polymer networks with a nanoscale structure. Following solvent removal, the resulting aerogel provides exceptional thermal insulation and tunable mechanical and functional properties for advanced engineering applications. Conventionally, aerogels are fabricated using a molding process limiting the complexity of aerogel geometries due to the available mold designs. This limitation hinders the rapid prototyping of complex, application-specific aerogel structures with tailored geometries, such as conformal shapes around existing components, which in turn limits the rate of iterative design and innovation.","category":"manufacturing","categoryRaw":"Manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_177","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-177","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-177","confidence":"high"},"type":"patent","title":"3D Printable Polymer Aerogels Using a Two-Pot Dual Solvent Method","abstract":"Researchers at NASA\u2019s Glenn Research Center have developed a two-pot, dual-solvent system to overcome long-standing manufacturing challenges associated with 3D printed aerogels. These ultralight, porous materials are known for their exceptional thermal, acoustic, and vibration insulation properties. The new approach enables the creation of complex, finely detailed aerogel structures using additive manufacturing, expanding their potential applications across aerospace , automotive, construction, and electronics industries.","category":"manufacturing","categoryRaw":"Manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_102","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-102","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-102","confidence":"high"},"type":"patent","title":"Internal Friction Reduction (IFR) Tool","abstract":"NASA's Marshall Space Flight Center has developed a cost-effective pin tool for use in self-reacting friction stir welding (SR-FSW), making the SR-FSW process significantly more robust and cost-effective. The IFR Tool mitigates the internal friction that occurs between the weld pin and crown-shoulder during a SR-FSW weld. Testing with the IFR tool has shown a significant reduction in the number of defects found in SR-FSW welds, and the tool allows significantly longer SR-FSW welds to be performed. Utilizing the IFR Tool can reduce SR-FSW welding costs by reducing scrap/rework rates, reducing the number of pin tools required per unit weld length, and reducing the time spent changing out SR-FSW pin tools per unit weld length. Along with improving the cost-effectiveness of existing SR-FSW applications, the IFR Tool may also further expand the applications for which SR-FSW is a commercially viable solution.","category":"manufacturing","categoryRaw":"manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_120","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-120","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-120","confidence":"high"},"type":"patent","title":"Additively Manufactured Propulsion Catalysts","abstract":"In mono- propulsion systems, a propellant is flowed across a catalyst to promote a chemical reaction and generate thrust. Conventional catalyst manufacturing methods entail (a) coating the inner walls of the thruster nozzle with a catalyst (generally undesirable due to limited catalyst-propellant contact), or (b) inserting a metal or graphite foam coated with a catalyst material into the thruster chamber. Method (b), while superior in terms of thrust generation, also possesses several limitations. Metal/graphite foams are difficult and expensive to procure, stochastic/random in nature (e.g., possess high variability in terms of geometric and other properties), and must be jammed into the thruster chamber using a compression plunger during installation \u2013 a process that often leads to catalyst damage. A new manufacturing method that improves repeatability, thruster reactivity, and tailorability (e.g., mechanical, chemical, and fluid flow) while reducing cost and lead time is thus highly desirable. To address this need, NASA and EOS developed methods to additively manufacture (AM) ultra-fine lattice structure propulsion catalysts.","category":"manufacturing","categoryRaw":"Manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_126","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-126","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-126","confidence":"high"},"type":"patent","title":"Conventional friction stir extrusion machine","abstract":"NASA Marshall Space Flight Center has developed a new small-scale metal extrusion tool, called a conventional friction stir extrusion (C-FSE) machine that may be attached or added-on to a conventional friction stir welding (C-FSW) system. The C-FSE machine uses the heat generation and plastic deformation processes underpinning C-FSW to perform metal extrusion instead of metal joining. The new tool can perform small-batch extrusion runs with custom geometries that can be easily changed by replacing the modular extrusion block face plate. Compared to traditional metal extrusion processes, large billets of metal do not have to be preheated prior to the extrusion for the C-FSE machine as raw metal rods can be fed directly into the extrusion block, saving significant tooling and energy costs. The C-FSE machine can work with any metal alloy that is amenable to FSW processes, including aluminum alloys and other lightweight or exotic alloys.","category":"manufacturing","categoryRaw":"Manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_127","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-127","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-127","confidence":"high"},"type":"patent","title":"Friction Stir Deposition Innovations","abstract":"Innovators at the NASA Marshall Space Flight Center have developed two new friction stir deposition (FSD) add-on tools that allow a conventional friction stir welding (C-FSW) system to be reversibly adapted for deposition within minutes. Both FSD end effectors use the rotating pin of the FSW tool to heat and plasticly deform metal feedstock for solid-state additive processes. The first tool\u2014Conventional Friction Stir Deposition (C-FSD)\u2014allows for layer-by-layer addition of extruded metal to an existing part using a C-FSW system plus a side-loading metal bar feeder device and containment block. The exit shape of the containment sets the final geometry of the part, enabling complex shapes (e.g., domes, barrels) to be deposited directly on a substrate (e.g., stiffeners to panels). The second tool\u2014Bobbin Friction Stir Deposition (B-FSD)\u2014makes use of a self-reacting tool design to contain the metal on two sides with the filler material fed between the shoulders. When paired with an FSW machine with a Self-Reacting Friction Stir Weld (SR-FSW) adjustable pin axis, continuously varying thickness parts are printable, as well as free-forming printing of complex curvatures.","category":"manufacturing","categoryRaw":"Manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_128","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-128","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-128","confidence":"high"},"type":"patent","title":"Ultra High-throughput Small Punch Test Machine for Maximum Efficiency","abstract":"Tensile testing is a destructive testing method that provides crucial information on tensile strength, yield strength, ductility, fracture toughness, ductile-to-brittle transition temperature, and other properties related to the breaking point of materials . However, traditional methods are slow, expensive, and labor-intensive. NASAs Ultra High-Throughput Small Punch Test Machine (Ultra High-Throughput SPT) is an automated SPT machine that can estimate mechanical properties of the desired materials from a small thin disk ((generally 8 mm in diameter and 0.5 mm thick) through its high-fidelity stress-strain data output) within a sample size ranging from hundreds to thousands before human intervention is necessary. It's faster, cost-effective, and fully automated. One of the key innovations of Ultra High-Throughput SPT is its automated pinpoint clamping and testing mechanism, eliminating the need for the enclosed fixtures commonly associated with modern SPT methods. This not only accelerates the testing process but also enhances precision, a game-changer in materials assessment. Ultra High-Throughput SPT handles numerous samples efficiently, saving time and resources, making it a reliable, cost-effective solution for various industries and research. NASA seeks licensees to develop the technology into a product that will upgrade tensile testing.","category":"manufacturing","categoryRaw":"manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_41","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-41","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-41","confidence":"high"},"type":"patent","title":"Novel Overhang Support Designs for Powder-Based Electron Beam Additive Manufacturing (EBAM)","abstract":"NASA Marshall Space Flight Center, in collaboration with the University of Alabama, has developed a contact-free support structure used to fabricate overhang-type geometries via EBAM. The support structure is used for 3-D metal-printed components for the aerospace , automotive, biomedical and other industries. Current techniques use support structures to address deformation challenges inherent in 3-D metal printing. However, these structures (overhangs) are bonded to the component and need to be removed in post-processing using a mechanical tool. This new technology improves the overhang support structure design for components by eliminating associated geometric defects and post-processing requirements.","category":"manufacturing","categoryRaw":"Manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_61","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-61","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-61","confidence":"high"},"type":"patent","title":"Improving Formability of Al-Li Alloys","abstract":"NASA scientists have designed a novel heat treatment process that significantly improves the formability of high-performance aluminum-lithium (Al-Li) 2195 alloy plate stock. The heat treatment process dramatically reduces cracking and also improves the yield and range of product sizes/shapes that can be spin/stretch formed. The improved yields also provide lower costs. The NASA innovation enables the use of Al-Li 2195 alloy for large structures like rocket domes or fuel tanks of much lighter weights than if made using a conventional aluminum-copper (Al-Cu) alloy. While specifically designed to address Al-Li 2195 alloy, similar heat treatments may possibly improve the formability of other high-performance Al-Li alloys as well.","category":"manufacturing","categoryRaw":"manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_70","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-70","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-70","confidence":"high"},"type":"patent","title":"Interim, In Situ Additive Manufacturing Inspection","abstract":"Researchers at NASA Marshall Space Flight Center have developed a novel method for interim, in situ dimensional inspection of additively manufactured parts. Additive manufacturing processes currently have limited monitoring capabilities, offering users little to no options in mitigating the high levels of product and process failures. This technology uses both infrared (IR) and visual cameras that allow users to monitor the build in real-time and correct the process as needed to reduce the time and material wasted in parts that will not meet quality specifications. The technology is especially useful for the in-process inspection of a parts internal features (e.g., fluid channels and passages), which cannot be easily inspected once the print is complete. The technology has the potential to enable the implementation of a closed-loop feedback system, allowing systems for automatic real-time corrections.","category":"manufacturing","categoryRaw":"manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_81","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-81","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-81","confidence":"high"},"type":"patent","title":"Cladding and Freeform Deposition for Coolant Channel Closeout","abstract":"Low-cost, large-scale liquid rocket engines with regeneratively cooled nozzles will enable reliable and reduced-cost access to space. Coolant, contained under high pressure, circulates through a bank of channels within the nozzle to properly cool the nozzle walls to withstand high temperatures and prevent failure. It has been a challenge to affordably manufacture and close out the intricate nozzle channels. As such, NASA developed a robust and simplified additive manufacturing technology to build the nozzle liner outer jacket to close out the channels within and contain the high-pressure coolant. The new Laser Wire Direct Closeout (LWDC) capability reduces the time to fabricate the nozzle and allows for real-time inspection during the build. One variation enables a bimetallic part (copper/super-alloy, e.g.) to help optimize material where it is needed. The manufacturing process has been demonstrated on a series of different alloys. Hot-fire testing is complete&#8212the parts were exposed to extreme combustion chamber temperatures and pressure conditions for 1,000+ seconds. Micro-graph examination of the hot-fired test article has verified that the coolant channel closeout bonds are reliable and that there is very little deformation to the coolant channels. The picture above was taken during the hot-fire testing of a nozzle.","category":"manufacturing","categoryRaw":"Manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_97","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-97","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-97","confidence":"high"},"type":"patent","title":"Stronger Plug for Friction Pull Plug Welding of Thick Plates","abstract":"NASA and Geocent, LLC innovators adapted a plug to improve aluminum friction pull plug welding (FPPW). The rugged plug is less vulnerable to snapping off and helps reduce chatter. FPPW is the process that is necessary to plug the hole that is left behind as a friction stir weld (FSW) joint is completed and the pin tool of the welder retracts from the joint. The inventors have replaced the plug support with steel to improve its strength to endure the forces of the FPPW process. NASA adapted the plug to enable FPPW processing for the thicker welds and different alloys needed for NASA&#146s new Space Launch System (SLS). This new plug helps solve the well-known FPPW challenges of plug welding on thicker plates that have caused weld defects in the past such as substantial plug necking and plug rotational stalling. The new plug has been tested and used in building NASA equipment.","category":"manufacturing","categoryRaw":"Manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_99","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-99","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-99","confidence":"high"},"type":"patent","title":"High Flow Differential Cleaning","abstract":"Powder-based AM methods typically require post-fabrication component cleaning to remove residue powder from the surface and crevices of the part, a task that becomes increasingly difficult and time consuming with part complexity. Methods currently available to clean AM parts have significant drawbacks. Immersive cleaning using solvents or solutions can cause powder clumping. Forms of blasting (e.g., wet, bead, hydro, bristle, vacuum, etc.) work on line-of-site surfaces but are ineffective for recessed cavities. Such cleaning is typically manual, highly time consuming, and requires careful use of personal protective equipment to avoid powder inhalation. Thus, the AM market would benefit from a more automated, rapid, and effective method for cleaning complex parts.","category":"manufacturing","categoryRaw":"manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_106","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-106","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-106","confidence":"high"},"type":"patent","title":"X-Ray Crack Detectability","abstract":"Innovators at NASA Johnson Space Center have developed flaw size parameter modeling to determine if a specific X-ray setup can detect cracks of various sizes within materials. These models allow users to optimize X-ray radiography setups, for the detection of crack and crack-like flaws, to penetrate various materials to show internal structures such as the threaded pipe shown above. The ability to quantify crack detection sensitivity paves the way for crack detection requirements to be defined for X-ray radiography nondestructive evaluation (NDE) of manufactured parts. Improved industry requirements for reliable crack detection using x-ray radiography and improved X-ray setup optimization tools that are based on software modeling, such as this technology, may be desired by industry. The Model-Based X-Ray Crack Detection Requirements is a technology readiness level (TRL) 6 (system/sub-system model or prototype demonstrated in an operational environment). The innovation is now available for your company to license. Please note that NASA does not manufacture products itself for commercial sale.","category":"manufacturing","categoryRaw":"Manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_127","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-127","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-127","confidence":"high"},"type":"patent","title":"RTV Silicone Sealing Method for Component Interfaces","abstract":"Innovators at NASA Johnson Space Center have developed a method using low-viscosity RTV silicone to form durable seals between polymer bladder and metal bulkhead interfaces to be used for inflatable space habitats. As NASA continues to research the viability of inflatable space habitats made with flexible materials, much consideration is given to reliably maintain pressurized environments for astronauts through the use of advanced seals. In early inflatable test articles, seals between bladder and bulkhead interfaces were achieved using a combination of O-rings and gaskets alone. However, when planning for long duration missions, there was a concern that the compressive force of an O-ring could create a line load on the bladder and cause potential failure of the bladder material and overall seal. An RTV silicone sealing method was developed as a solution to this problem, and works with an arrangement of O-rings and gaskets that act as a dam to form a channel that maintains the placement of the RTV silicone. The RTV silicone sealing method may have commercial applications here on Earth as it can yield a cure-in-place seal that can form-fits to a complex channel. This sealing method has a technology readiness level (TRL) 5 (Component and/or breadboard validation in relevant environment) and is now available for patent licensing. Please note that NASA does not manufacture products itself for commercial sale.","category":"manufacturing","categoryRaw":"Manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_47","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-47","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-47","confidence":"high"},"type":"patent","title":"Robonaut 2: Industrial Opportunities","abstract":"Researchers at the NASA Johnson Space Center (JSC) in collaboration with General Motors (GM) and Oceaneering, have designed a state-of-the-art, highly dexterous, humanoid robot: Robonaut 2 (R2). R2's nearly 50 patented and patent-pending technologies have the potential to be game-changers in many applications such as the industrial environments. For example, in a traditional robotic assembly line there are multiple specialized robots that are tooled for a small set of unique tasks. R2 provides an alternative way to implement automated assembly using extraordinary task flexibility, dexterity and rapid interchangeability with human processes and tools. This can lower automation infrastructure costs and increase manufacturing flexibility. R2 can serve as an assistant or work independently. R2's dexterity is a key feature in industrial environments as the robot can handle factory work that is ergonomically difficult, fatiguing, or even unsafe.","category":"manufacturing","categoryRaw":"Manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_92","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-92","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-92","confidence":"high"},"type":"patent","title":"Automated Fabric Circuit and Antenna Fabrication","abstract":"Innovators at NASA Johnson Space Center have developed a cost-effective method to create fabric-based circuits and antennas by combining conventional embroidery with automated milling. The technology allows for higher surface conductivity, improved impedance control, expanded design and application potential, and greater choice of materials for optimized performance. Previous efforts to automate fabric circuit and antenna fabrication have faltered on either the complexity of the manufacturing hardware and associated costs, or design and application limitations of the resulting e-textiles. This fabrication method offers benefits in cost and labor savings and provides opportunities for the development of design patterns with higher geometric complexity and performance improvements.","category":"manufacturing","categoryRaw":"Manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_167","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-167","sourceUrl":"https://technology.nasa.gov/patent/TOP2-167","confidence":"high"},"type":"patent","title":"Woven Thermal Protection System","abstract":"NASA's Heatshield for Extreme Entry Environment Technology (HEEET) is a 3-D woven heatshield design made to efficiently reject extreme heating during space vehicle entry into a planetary atmosphere. HEEET is a system to protect probe or scientific payload. The technology presents a revolutionary approach to the designing and manufacturing of TPS materials. The woven TPS configuration, in both its material composition and architecture, can be adapted to cover a range of space vehicle and environment choices including vehicle entry velocity, vehicle entry flight path angle, initial time interval for vehicle deceleration, vehicle nose shape (e.g., blunt or wedge), initial entry pressure, heating rate (variable with time), cumulative heat load, time interval for heating, and relevant atmospheric characteristics, among other attributes.","category":"manufacturing","categoryRaw":"manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_218","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-218","sourceUrl":"https://technology.nasa.gov/patent/TOP2-218","confidence":"high"},"type":"patent","title":"Fabricating printable electronics and biosensor chips","abstract":"NASA has developed a unique approach for an atmospheric pressure plasma-based process for fabrication of printable electronics and functional coatings. The need for low-cost and environmentally friendly processes for fabricating printable electronics and biosensor chips is rapidly growing. This plasma-based fabrication involves aerosol-assisted room temperature printing in which an aerosol carrying the desired material for deposition is introduced into a cold plasma jet operated at atmospheric pressure. The deposition is the result of the interaction of the aerosol containing the precursor material with the atmospheric pressure plasma containing a primary gas. Aerosol-assisted plasma deposition is a high throughput and facile process for printing and patterning that is easily scalable for industrial production. Multiple jets can be used for depositing different materials and the approach can be adapted to a variety of platforms and coating a variety of materials .","category":"manufacturing","categoryRaw":"manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_299","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-299","sourceUrl":"https://technology.nasa.gov/patent/TOP2-299","confidence":"high"},"type":"patent","title":"Modular Artificial-Gravity Orbital Refinery Spacecraft","abstract":"The Modular Artificial-Gravity Orbital Refinery Spacecraft is a novel technology from NASA Ames Research Center for in-situ refining or recycling of materials in space, including mass from asteroids, Mars moons, orbiting \"space junk\" debris, and for in-situ creation of products from operations in low or micro-gravity environments. There has been considerable interest in the exploration and mining of asteroids with spacecraft as well as mitigating the growing threat of space debris. Refining operations, such as centrifugal refining processes, introduce challenges for operating in space that are not relevant on Earth, including the need for gravity in order for refining operations to function properly. This technology provides an effective and efficient approach to address these needs and challenges.","category":"manufacturing","categoryRaw":"Manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_301","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-301","sourceUrl":"https://technology.nasa.gov/patent/TOP2-301","confidence":"high"},"type":"patent","title":"Fully Automated High-Throughput Additive Manufacturing","abstract":"The Additive Manufacturing (AM) process uses a 3D printer to convert a filament into a three-dimensional manufactured object by melting the filament and depositing it in built-up layers to form the desired object, where the movement of the printing head is controlled by computer code. The automation of AM is limited and usually still requires human labor workflows, including the fundamental step of removing the finished object from the printer platform. NASA Ames Research Center has developed a novel method to increase automation of AM by embedding additional instructions into the manufacturing toolpath to create manufacturing tools in situ, such as linear springs on the printer platform, and to instruct movement of the printer\u2019s parts to autonomously move the finished object off the platform. The technology eliminates the need for humans in the loop for high-throughput applications. Testing can also be integrated into the manufacturing toolpath.","category":"manufacturing","categoryRaw":"Manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top8_95","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"TOP8-95","sourceUrl":"https://technology.nasa.gov/patent/TOP8-95","confidence":"high"},"type":"patent","title":"Ultrasonic Stir Welding","abstract":"NASA Marshall Space Flight Center (MSFC) developed Ultrasonic Stir Welding (USW) to join large pieces of very high-strength metals such as titanium and Inconel. USW, a solid-state weld process, improves current thermal stir welding processes by adding high-power ultrasonic (HPU) energy at 20 kHz frequency. The addition of ultrasonic energy significantly reduces axial, frictional, and shear forces; increases travel rates; and reduces wear on the stir rod, which results in extended stir rod life. The USW process decouples the heating, stirring, and forging elements found in the friction stir welding process allowing for independent control of each process element and, ultimately, greater process control and repeatability. Because of the independent control of USW process elements, closed-loop temperature control can be integrated into the system so that a constant weld nugget temperature can be maintained during welding.","category":"manufacturing","categoryRaw":"manufacturing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_249","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-249","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-249","confidence":"high"},"type":"patent","title":"Silicon Oxide Coated Aluminized Polyimide Film Radiator Coating","abstract":"A miniature satellite , or CubeSat, has deployable solar arrays and/or body mounted solar cells to generate adequate electrical power to meet mission power requirements. The CubeSats internal components dissipate heat. In order to maintain the component temperatures within allowable flight limits, the waste heat needs to be radiated from its exterior to deep space. Depending on the orbit parameters, one or more of the exterior surfaces could be exposed to sunlight, planet albedo (reflection of solar radiation from Earth), or infrared radiative flux. Additionally, lithium ion batteries, often used on CubeSats, are required to be above 0 C during charging. Conventionally, a combination of radiator thermal coatings, multilayer insulation (MLI) blankets, and active heater control are used to meet component thermal requirements, which are all relatively expensive. Furthermore, MLI blankets not only increase the volume of the CubeSat, but also increase the risk of entanglement during solar array deployment. The SiOx Coated Aluminized Polyimide Film Radiator Coating regulates temperature for CubeSats without these drawbacks.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_262","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-262","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-262","confidence":"high"},"type":"patent","title":"Alternative Transparent Coating Lotus Suitable for Optics with Vacuum Deposition Layer","abstract":"NASA instrumentation is at risk for contamination from dusty space environments. Additionally, contamination from water and ice buildup can affect instrumentation function. The innovation of the LOTUS coating prevents contamination on sensitive surfaces, like optics, that cannot be cleaned during space missions.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_28","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-28","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-28","confidence":"high"},"type":"patent","title":"Molecular Adsorber Coating (MAC)","abstract":"Goddard Space Flight Center has developed a portfolio of molecular adsorber coatings (MAC) to mitigate issues posed by volatile organic compounds (VOC). Many materials contain gasses that are trapped on or within the surface that, when in vacuum, will escape the host material over time - a process known as outgassing. The extent of outgassing is a function of the material, temperature, and the vacuum level present. To address outgassing issues in spacecraft , NASA has historically used zeolite based molecular adsorbers in spacecraft and instruments to collect and retain outgassed molecular effluent emanating from potting compounds, epoxies, tapes, lubricants, and other spacecraft materials, protecting critical, contamination sensitive, surfaces. Uncontrolled, molecular contamination can cause significant degradation of instrument performance, thermal control properties, solar array efficiency, optical surfaces, laser systems, detectors, cryogenic instruments, and high powered electronics. In an effort to simplify previously flown complex zeolite coated cordierite molecular adsorber puck systems, such as those flown on Hubble Space Telescope (HST), a portfolio of easily produced and applied molecular adsorber coatings have been developed.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_363","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-363","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-363","confidence":"high"},"type":"patent","title":"Advanced AlF3-Passivated Aluminum Mirrors","abstract":"Pure aluminum (Al) exhibits an intrinsically high reflectance in the 90 \u2013 2500 nm wavelengths and is commonly used for mirrors in optical applications within this range. However, in order to be used in the far-ultraviolet (FUV) range between 90 \u2013 130 nm, an optical thin film overcoat is needed to protect the Al and prevent the formation of an Al2O3 layer, which occurs upon exposure to oxygen. Conventionally, fluoride overcoat layers such as LiF or MgF2 have been used to solve this challenge. However, these coatings are opaque between 90 \u2013 102 nm and generate residual absorption even above 102 nm, limiting reflectance at these short wavelengths. Furthermore, such fluoride coatings are hygroscopic and environmentally unstable. To address this issue, engineers at NASA's Goddard Space Flight Center have developed an alternative method to prevent the oxidation of Al coatings without the drawbacks associated with fluoride coatings (opaqueness, residual absorption). This NASA innovation is an Al mirror passivation process that produces a thin AlF3 overcoat layer, preventing further oxidation. The resultant AlF3 overcoat layer offers enhanced reflectivity at shorter (FUV) wavelengths compared to MgF2 and is more environmentally stable relative to LiF. Furthermore, Al mirrors receiving this innovative NASA treatment maintain 90% reflectance at longer wavelengths, enabling the development of mirrors with broadband reflectivity (e.g., from 90 \u2013 2500 nm).","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_371","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-371","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-371","confidence":"high"},"type":"patent","title":"Waveguide-based Dielectric and Magnetic Property Measurement","abstract":"Understanding the composition of planetary surfaces is crucial for advancing space exploration and preparing for future human missions to the Moon and Mars. NASA\u2019s proposed International Mars Ice Mapping (I-MIM) mission aims to use Synthetic Aperture Radar (SAR) to identify near-surface ice deposits on Mars, which could serve as a vital resource for future explorers. To support this effort, scientists must first determine how radar signals interact with the diverse materials found on these planetary bodies, such as rock, regolith, and buried ice. An understanding of these interactions is critical to designing specialized SARs for such missions, as well as to determining their detection capabilities in specific environments. Traditional methods of analyzing such materials have provided valuable insights, but they often lack the ability to assess the 3-D electromagnetic (EM) properties of rock and soil, which are critical for improving radar-based detection capabilities. Furthermore, existing techniques require regularly shaped samples (e.g., rectangles). Martian and other planetary rock samples brought back to Earth are precious and cannot be altered, eliminating these techniques as an option. Recognizing this challenge, a team of engineers and scientists at NASA\u2019s Goddard Space Flight Center (GSFC) have developed an advanced laboratory-based system for measuring the dielectric and magnetic properties of arbitrarily shaped samples with high accuracy.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_376","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-376","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-376","confidence":"high"},"type":"patent","title":"Non-Magnetic Absorptive Material for Microwave to Far-Infrared Applications","abstract":"Researchers at NASA\u2019s Goddard Space Flight Center have developed a non-magnetic absorptive media that optimizes the dielectric function of the mixture, delivering superior optical, thermal, and mechanical properties for space-based instrumentation. Conductively loaded dielectric mixtures are widely used for electromagnetic interference control, anti-reflection, and in-band optical scattering reduction, but existing commercial coatings come with significant trade-offs. Many are magnetic, making them incompatible with superconducting electronics and sensors, while others rely on high-index ceramic fillers, magnetic materials, or conductive particles that increase area density\u2014resulting in higher reflectance, excess bulk, and added heat capacity. These drawbacks drive up mass, volume, and costs for cryogenic space instruments. By addressing these limitations, this high-emissivity, non-magnetic coating provides a lightweight, high-absorptance solution that is structurally durable, thermally compatible, and optimized for the demanding conditions of far-infrared space applications.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_377","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-377","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-377","confidence":"high"},"type":"patent","title":"Atomic Layer Deposition-Enhanced Far-to-Mid Infrared Camera Coating","abstract":"Infrared (IR) cameras for space missions require robust coatings that are cryogenically cooled to reduce thermal noise and are low-reflectance absorptive to mitigate image artifacts such as glinting, ghosting, and internal reflections. Thermal noise reduction improves as temperatures decrease (e.g., below 30 K). However, capturing the far-to-mid IR spectrum typically requires thick layers of common 'super black' coatings, which often use free-standing nanotubes or foam-like structures that become fragile below 120-150 K. In response, engineers at Goddard Space Flight Center developed an Atomic Layer Deposition (ALD)-Enhanced Far-to-Mid IR Camera Coating that can be cooled to and operate at less than 30 K while maintaining low-reflection absorption. The coating results in enhanced optical performance, increased strength, reduced total mass, and suitable ionizing radiation control.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_1","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-1","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-1","confidence":"high"},"type":"patent","title":"Smart Coating for Corrosion Detection and Protection","abstract":"NASA Kennedy Space Center seeks partners interested in the commercial application of a smart, environmentally friendly coating system for early detection and inhibition of corrosion and self-healing of mechanical damage without external intervention. This coating will have the inherent ability to detect the onset of corrosion in the coated substrate and respond autonomously to control it. The high salt content of KSCs natural marine environment in combination with the sunlight, heat, and humidity of the subtropical Florida climate makes KSC the country's most corrosive area according to the American Society of Metals. These highly corrosive conditions are exacerbated at KSCs launch pads by extreme heat and acidic exhaust from the solid rocket motors of the space vehicles.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_103","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-103","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-103","confidence":"high"},"type":"patent","title":"Polymer Composite Material","abstract":"Many municipal curbside recycling programs fund their operations by selling recyclable waste. Unfortunately, over the past several years, the price of recyclable plastic and glass waste has dropped due to lack of demand. The lack of demand also means that more recyclable waste plastic and glass is being sent to landfills rather than being put to further use in the market. This places a larger strain on waste processing facilities, landfills, and the environment. Engineers at Kennedy Space Center have developed a new process for preparing composite materials made of a solid polymer binder and a solid filler which may, in some cases, be made from recycled sources. The material is intended to minimize the amount of plastics and recycling stream waste that goes to landfill and create additional uses/markets for recycling stream based products.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_105","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-105","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-105","confidence":"high"},"type":"patent","title":"Dust-Repelling Coating for Thermal Radiators","abstract":"Space is a very unforgiving environment. Charged particles, vacuum, and thermal extremes are just a few of the conditions that make this environment challenging to explore. Lunar dust on the surface of the Moon adds complexity to this situation. Dust can be a health hazard to astronauts if they breathe it in, as well as degrade materials , decrease power generation of solar panels, and cause gasket leaks. It also acts as a blackbody, becoming hot if left in direct sunlight. This is a problem for thermal radiators where the main function is to radiate heat away from an object. If dust lands on the thermal radiator, the unit will less effectively reject heat, and it will overheat. This can lead to mission failure. Therefore, methods to mitigate the accumulation of dust need to be developed. The electrodynamic dust shield (EDS) is capable of actively removing dust from thermal radiator surfaces. NASA scientists and engineeers have invented a novel efficient coating system with EDS capabilities for thermal radiators.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_33","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-33","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-33","confidence":"high"},"type":"patent","title":"Aerofoam","abstract":"NASA Kennedy Space Center seeks partners interested in the commercial application of Aerofoam. Aerofoam is a unique foam composite insulation with improved thermal and acoustic insulation properties. The novelty of this invention comes from combining a polymer foam with a unique inorganic filler in a way that maximizes thermal performance while maintaining mechanical performance, chemical resistance, fire resistance, and acoustic insulation capabilities. The development of new manufacturing processes has also allowed for the development of these unique composite materials.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_58","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-58","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-58","confidence":"high"},"type":"patent","title":"Layered Composite Insulation for Extreme Conditions (LCX)","abstract":"NASA Kennedy Space Center seeks partners interested in the commercial application of a layered composite insulation system for nonvacuum applications and extreme environmental exposure conditions. This layered composite insulation system for extreme conditions (or LCX) is particularly suited for complex piping or tank systems that are difficult or practically impossible to insulate by conventional means. Consisting of several functional layers, the aerogel blanket-based system can be tailored to specific thermal and mechanical performance requirements. Mechanically, the LCX system not only withstands impact, vibration, and the stresses of thermal expansion and contraction, but can help support pipes and other structures, all while maintaining its thermal insulation effectiveness. NASA KSC is currently seeking companies interested in licensing LCX for commercial applications.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_59","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-59","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-59","confidence":"high"},"type":"patent","title":"Cryogenic Selective Surfaces","abstract":"Thermal control coatings, i.e. coatings with different visible versus infrared emission, have been used by NASA on the Orbiter and Hubble Telescope to reflect sunlight, while allowing heat rejection via infrared emission. However, these coatings absorb at least 6% of the Sun's irradiant power, limiting the minimum temperature that can be reached to about 200 K. NASA needs better solar reflectors to keep cryogenic fuel and oxidizers cold enough to be maintained passively in deep space for future missions. This new thermal control coating material, developed for use as a spray on coating or rigid tiles, reflects essentially all solar radiation in the space environment. The novel material has the potential to be an enabler for long-term storage of cryogenic liquids and propellants in space. It can also support the long-term operation of low-temperature devices and systems used on space craft.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_80","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-80","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-80","confidence":"high"},"type":"patent","title":"Self-Healing Aluminum Metal Matrix Composite (MMC)","abstract":"Fatigue endurance is critical for the airworthiness of civilian and military aging aircraft and for long-duration flight and deep space missions. Estimates are that 90% of structure failures are due to fatigue. NASA has developed a new metal matrix composite (MMC) that can repair itself from large fatigue cracks that occur during the service life of a structure. This novel liquid-assisted MMC recovers the strength of the structure after a healing cycle. The MMC contains both shape memory alloy (SMA) reinforcements and some low-melting phase components which, when heated, essentially clamp the crack edges back together and flow material into the crack's gap for a high strength repair. While current crack repair methods exist, such as doublers or welding overlays, these methods require complex surface prep and bonding, which can be difficult and may result in a region of decreased strength. The new material allows for the repair of fatigue cracks without additional materials or human interaction.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_99","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-99","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-99","confidence":"high"},"type":"patent","title":"Self-Cleaning Coatings for Space or Earth","abstract":"Reducing dust accumulation on any surface is key for lunar missions as dust can damage or impair the performance of everything from deployable systems to solar cells on the Moon\u2019s surface. Electrodynamic dust shields (EDSs) are a key method to actively clean surfaces by running high voltages (but low currents) through electrodes on the surface. The forces generated by the voltage efficiently remove built up, electrically charged dust particles. Innovators at the NASA Kennedy Space Center have developed a new transparent EDS for removing dust from space and lunar solar cells among other transparent surfaces. The new coatings operate at half the voltage of existing EDSs while being 90% thinner. These capabilities are enabled by an innovative combination of electrode patterning and a thin silica protective layer. The reduced thickness and lower voltage operation expands possibilities for integrating EDSs onto transparent surfaces across industries.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_122","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-122","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-122","confidence":"high"},"type":"patent","title":"Multi-layered Self-healing Material System for Impact Mitigation","abstract":"NASA Langley researchers have developed a multi-layered self-healing material system for impact mitigation from ballistic or hypervelocity events (e.g., micrometeoroids or orbital debris). The system is constructed by sandwiching a reactive liquid monomer formulation between two solid polymer panels. While developed with space exploration in mind, the innovation has many other applications, such as fuel tanks and hydraulic insulation.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_124","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-124","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-124","confidence":"high"},"type":"patent","title":"Low-Temperature Oxidation/ Reduction Catalysts","abstract":"NASA Langley researchers, in work spanning more than a decade, have developed a portfolio of technologies for low-temperature gas catalysis. Originally developed to support space-based CO2 lasers, the technology has evolved into an array of performance capabilities and processing approaches, with potential applications ranging from indoor air filtration to automotive catalytic converters and industrial smokestack applications. The technology has been used commercially in systems that provide clean air to racecar drivers, as well as incorporated into commercially available filtration system for diesel mining equipment. Backed with extensive research on these technologies, NASA welcomes interest in the portfolio for other commercial and industrial applications.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_165","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-165","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-165","confidence":"high"},"type":"patent","title":"Holey Carbon Allotropes","abstract":"Researchers at NASA have developed new methods to manufacture carbon materials (e.g., nanotubes, graphene) with holes through the graphitic surface of the particles. The methods generate materials with increased accessible surface area, increased functional groups at damage sites, and improved through-surface molecular transport properties. The materials generated using these techniques are anticipated to be applicable to a variety of industries, especially energy storage (e.g. super-capacitors and batteries) and separation membranes (e.g. for gas, ions, organics, proteins, etc.).","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_175","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-175","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-175","confidence":"high"},"type":"patent","title":"Highly Thermal Conductive Polymeric Composites","abstract":"NASA Langley Research Center has developed a method to create highly thermal conductive polymeric composites. Such materials can prove highly valuable in applications that require efficient, light-weight, and flexible thermal management solutions, such as liquid cooled ventilation garments worn by astronauts.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_182","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-182","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-182","confidence":"high"},"type":"patent","title":"Hydrophobic Epoxy Coating for Insect Adhesion Mitigation","abstract":"NASA Langley Research Center has developed fluorinated alkyl ether containing epoxies designed as an anti-insect coating. The robust and durable coating was developed to improve aircraft efficiency, but the coating could be useful in a variety of applications where reduction of insect residue adherence is desirable, such as in automotive and wind energy industries.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_183","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-183","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-183","confidence":"high"},"type":"patent","title":"Chemical and Topographical Surface Modifications for Insect Adhesion Mitigation","abstract":"NASA Langley Research Center, in collaboration with ATK Space Systems, has developed a method to reduce insect adhesion on metallic substrates, polymeric materials, engineering plastics, and other surfaces. The method topographically modifies a surface using laser ablation patterning followed by chemical modification of the surface. This innovation was originally developed to enhance aircraft laminar flow by preventing insect residue buildup, but the method provides a permanent solution for any application requiring insect adhesion mitigation as well as adhesion prevention of other typical environmental contaminants.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_2","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-2","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-2","confidence":"high"},"type":"patent","title":"Highly Aligned Electrospun Fibers and Mats","abstract":"NASA's Langley Research Center has created a modified electrospinning apparatus for spinning highly aligned polymer fibers. Fiber placement, orientation, and porosity are difficult to control using conventional electrospinning apparatus. Conventional electrospinning creates randomly oriented fibers that are well suited to nonwoven mats, but not to other applications. Now, NASA Langley has developed the capability to control the alignment and porosity of fibers for mats, which will broaden the range of engineering applications of electrospun materials to include new tissue engineering scaffolds, membrane filters, textiles, and embedded sensors and actuators. The new apparatus provides a simple and inexpensive means of producing fibers and mats of controlled fiber diameter, porosity, and thickness.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_201","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-201","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-201","confidence":"high"},"type":"patent","title":"Atomic Number (Z)-Grade Radiation Shields from Fiber Metal Laminates","abstract":"NASA Langley Research Center has developed a shapeable radiation shield made from fiber metal laminates. The technology was developed based on a need for better performing shielding of sensitive spacecraft electronics. Beyond spacecraft electronics, the invention has uses for radiation protective clothing, radioactive fluid piping shields, nuclear reactor shields, and other applications.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_212","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-212","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-212","confidence":"high"},"type":"patent","title":"Multilayered Fire Protection System","abstract":"NASA Langley has developed a flexible, light weight and portable thermal protection system. The flexible thermal protection systems are multilayer thermal blankets that are designed to handle external temperatures of up to 2000 degrees Fahrenheit. Flight tests clearly demonstrate how these new heat retardant materials can protect from the extreme conditions. This system creates an environment for protecting equipment, facilities, and people from a high intensity incident heat source, such as a fire. The system can be formed as a sleeping bag, a tent, a blanket, a vertical barrier, a curtain, a flexible rollup doorway, or a wrap.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_224","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-224","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-224","confidence":"high"},"type":"patent","title":"Puncture-healing Engineered Polymer Blends","abstract":"NASA inventors have developed a set of puncture self-healing materials comprised of commercially available, known self-healing polymer resin and additive blends. A range of puncture healing blends was developed by melt blending self-healing polymers with non-self-healing polymeric materials .","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_250","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-250","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-250","confidence":"high"},"type":"patent","title":"Novel Radiation Shielding Material for Dramatically Extending the Orbit Life of Cubesats","abstract":"The NASA Langley Research Center has developed an innovative radiation shield made by layering metal materials in the Z-shielding method. It is a new, low cost and easy to implement method to protect CubeSat electronic circuits from ionizing radiation found in Low Earth Orbits. It is estimated that this approach can extend the life of CubeSat electronics by an order of magnitude.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_272","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-272","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-272","confidence":"high"},"type":"patent","title":"Synthesis and Development of Polyurethane Coatings Containing Fluorine Groups for Adhesive Applications","abstract":"Accumulation of insect strikes on the leading edge of airplane wings is a more serious problem than one might realize. Depending on the magnitude, such accumulation changes the aerodynamic characteristics of the wing causing a change from laminar to turbulent flow and resulting in decreased lift and increased drag. Overall, this also results in decreased fuel efficiency. According to a study published in 1950, the drag coefficient measured on an aircraft wing was determined to increase as much as 100%. Although much work has been done to mitigate this problem. Proposed solutions include elastic surfaces, coatings, soluble films, and fluid covers. Each of these approaches had significant drawbacks.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_292","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-292","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-292","confidence":"high"},"type":"patent","title":"Conductive Polymer/Carbon Nanotube Structural Materials and Methods for Making Same","abstract":"Scientists at NASA Langley Research Center have developed a composite material that demonstrates improved mechanical properties, approaching those of conventional carbon fiber composites, and possesses relatively high electrical conductivity. Starting with carbon nanotube paper, tape or yarn, the CNT material was impregnated with monomeric aniline with was then polymerized in-situ to create a nanocomposite, followed by stretching, hot pressing and carbonization to densify and improve the interface integrity.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_302","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-302","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-302","confidence":"high"},"type":"patent","title":"Holey Graphene Mesh from Solvent-Free Manufacturing and Composites Thereof","abstract":"Solvent-free methods were developed to create arrays of holes with lateral dimensions of 10 micrometers and above on holey graphene-based articles from dry compression (such as films, discs, pellets) to form holey graphene mesh (HGM). HGM is enabled by the uniqueness in the dry compressibility of holey graphene and the processibility of the dry-compressed monolithic articles, both of which are unavailable with pristine graphene.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_350","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-350","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-350","confidence":"high"},"type":"patent","title":"High Atomic Number Coatings for Fabrics","abstract":"NASA Langley Research Center has developed an innovation to promote the adhesion and improve the durability of high atomic number metal coatings on oxygen- or hydroxyl-rich surfaces. This new approach is useful for building radiation shields via the Z-grading method, the process of layering metal materials with different atomic numbers to provide radiation protection for protons, electrons, and x-rays. This invention enables Z-graded coatings to be applied to lower cost and lighter weight substrates, such as glass fiber fabrics, while maintaining the durability and flexibility needed for spacecraft electronics, radiation protective clothing, and other applications.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_353","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-353","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-353","confidence":"high"},"type":"patent","title":"New Coatings Reduce Impact Ice Adhesion Strength","abstract":"Aircraft icing is a serious problem. Wintry conditions on the ground and glaze, rime and mixed icing conditions aloft can cause ice buildup on aircraft wings increasing weight, creating drag, and causing loss of lift \u2014conditions that compromise performance and safety. For commercial aircraft , active icing mitigation strategies \u2014pneumatic boots, heated surfaces, and deicing agents \u2014prevent or mitigate such ice buildup. The challenge is that they also require extra energy, added weight to the aircraft , and increased maintenance complexity. For general aviation and unmanned aerial vehicles that cannot support active anti-icing technologies, avoidance is the only recourse. Thus, there is a need for a passive durable solution for both commercial and general aviation aircraft . Scientists at NASA Langley have been developing passive solutions to this problem focusing on coatings for aircraft surfaces that will reduce the adhesion of impact ice.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_354","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-354","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-354","confidence":"high"},"type":"patent","title":"Flexible Lightweight Radiation Shielding","abstract":"Lead-filled aprons are currently used for atomic number (Z)-grade radiation shielding in the medical industry to protect personnel from hazardous gamma radiation. These apron garments are made with lead-filled elastomeric sheets encased in polymeric fabrics and are both heavy and bulky to meet necessary shielding requirements. In addition, there are environmental safety concerns surrounding disposal of these garments due to their lead content. An innovator at NASA Langley Research Center has developed a novel method for making thin, lightweight radiation shielding that can be sprayed or melted onto common textiles used in clothing such as cotton, nylon, polyester, Nomex and Kevlar. The lead-free shielding is more effective at blocking radiation as compared with similar thicknesses of lead while being up to 25% lighter. The shielding can also be formed into a variety of garments such as shirts, vests, jackets, and pants with significantly greater comfort and conformity than the aprons currently in use.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_356","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-356","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-356","confidence":"high"},"type":"patent","title":"Low Creep, Low Relaxation Fiber-Reinforced Polymer Composites","abstract":"Inflatable and deployable beams and masts such as solar sail supports used in space missions are often made of polymer composites and may be stored for one to two years in space before deployment. While stored, these polymer composites degrade on a molecular level, which can limit the ability of the beams to unfurl properly, reducing performance or even failing to unfurl. Researchers at NASAs Langley Research Center developed a fiber-reinforced polymer composite to reduce the effect of viscoelastic creep and prolong the molecular integrity of polymer-based beams over time. NASAs polymer composite technology augments the molecular structure of the resin matrix by incorporating secondary additives and adjusting the composite architecture. Test results show that the new material reduces relaxation in the modified-molecular structure to as low as 5% from the initial modulus after two years. This compares to 49% relaxation after one year for the state-of-the-art, commercially available options.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_370","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-370","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-370","confidence":"high"},"type":"patent","title":"Conductive Carbon Fiber Polymer Composite","abstract":"A team of inventors from NASA Langley and NASA Ames have created a new type of carbon fiber polymer composite that has a high thermal conductivity. This was achieved by incorporating Pyrolytic Graphite Sheets (PGSs) and Carbon Nanotubes (CNTs), which enhance the material's ability to transfer heat when compared to typical carbon fiber composites. Carbon fiber polymer composites are frequently used in aerospace structures because they are light, strong, and require minimal maintenance. However, they typically have poor thermal conductivity, which limits their use to applications where heat transfer is not required. Where heat transfer is needed, aluminum alloys are used instead, but they have drawbacks such as lower strength, higher weight, and increased maintenance needs compared to composites. The new material developed by NASA addresses this issue by combining the benefits of a carbon fiber composite with the high thermal conductivity of metal alloys. NASA is currently working on using this material for in-space applications, such as heat exchangers or radiators for removing carbon dioxide from the crew cabin atmosphere. On Earth, the composite could be used to create new radiators or heat exchangers for use in automotive or electronics applications.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_372","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-372","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-372","confidence":"high"},"type":"patent","title":"Origami-based Deployable Fiber Reinforced Composites","abstract":"Inventors at the NASA Langley Research Center have developed a new UV (ultraviolet)-curable polymer carbon fiber composite and the origami-based deployable structures that are made from the new composite. The new composite and associated origami deployment system were developed for use in stronger, more reliable deployable space structures. These structures include beams for deployable habitats, booms, solar array frames, and antenna supports among others. The polymer shape memory effect allows the origami composite structures to be stored in a small, lightweight package and deployed on-site (i.e., in orbit, on the moon, etc.) through heating. The origami-based composite assemblies outperform other composite-based deployable structures in strength, are lighter than metals, are not susceptible to gas leaks like inflatable structures, and do not require motors to deploy.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_373","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-373","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-373","confidence":"high"},"type":"patent","title":"Epitaxy of SiGe and Other Compound Semiconductors","abstract":"NASA engineers have developed a suite of technologies that enable super-hetero-epitaxial growth of silicon germanium (SiGe) and other compound semiconductors on sapphire and other trigonal and hexagonal structure substrate wafer materials. A focus for NASA has been on the development of methods to make SiGe crystal materials for the manufacture of advanced semiconductor devices for aerospace applications. This suite of technologies, however, is even more broadly applicable to making various semiconductors of Group IV, III-V, and II-VI compounds. The technologies include super-hetero-epitaxial growth using carefully engineered crystal structures/orientations combined with sputtering and control substrate heating. Also included are novel x-ray diffraction methods for detecting and mapping crystal twin defects that can arise during super-hetero-epitaxial growth. The specific case of growing highly twinned SiGe crystal layer structures for use in making high temperature thermoelectric devices is enabled as well.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_379","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-379","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-379","confidence":"high"},"type":"patent","title":"Novel Shape Memory Composite Substrate","abstract":"Shape memory polymers, like shape memory alloys, have the capability to return to their original shape from a temporary (or programmed) shape when some external stimulus is applied (e.g., temperature, electric field). However, shape memory polymers have not seen the same level of implementation as the alloys because (1) they do not have high actuation forces (i.e., the force of the shape change) and (2) the polymers do not spread stimuli well, as such, the actuation is not constant across the material. NASA inventors have developed a novel shape memory polymer composite (SMC) substrate by combining a shape memory polymer with thin carbon fiber sheets and an in-situ heating mechanism. The in-situ heating and a carbon fiber layer result in heat being spread evenly across the polymer and significantly higher actuation forces compared to the polymer alone. The capabilities of the composite substrate will enable deployable systems across various industries.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_380","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-380","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-380","confidence":"high"},"type":"patent","title":"AERoBOND+ for Manufacturing Composite Structures","abstract":"The original AERoBOND technology was developed to enable co-cure joining and manufacturing of large composite structures without the use of fasteners. The AERoBOND technology provides novel prepreg and resin formulation designs to improve the joining and manufacturing of high-performance, large composite structures such as those used in aviation and aerospace applications. AERoBOND can also be used for many other prepreg-based composite structures, small and large, in many industrial applications. The joint quality can be exceptional, and the cost and efficiency of manufacturing is improved. The new AERoBOND+ innovation is a next-generation innovation that widens the scope of potential applications of AERoBOND to include those where the mating surfaces are less than ideally matched. This new innovation is accomplished with critically designed resin/adhesive/prepreg formulations and layer designs across the joint between each of the faying surfaces.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_391","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-391","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-391","confidence":"high"},"type":"patent","title":"Advanced Isothermally Produced Next-Gen Composites","abstract":"Next-generation composite aircraft that are produced at a high rate require fundamental advances in composite materials and manufacturing processes. Innovators at NASA Langley Research Center have developed a new family of formulations and composite processing methods that enable rapid and simpler fabrication of aerospace -grade composite materials. The key innovation is the combination of materials and methods enabling resin infusion and curing steps to occur at the same temperature, thus reducing the required processing time and simplifying the overall process. The new formulations developed by NASA have applications within next-generation commercial and military aircraft but may also be used in other applications including electric vertical take-off and landing (eVTOL) aircraft, automotive, and structural (terrestrial and in-space) uses if high mechanical properties and rapid manufacturing rates are required.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_402","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-402","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-402","confidence":"high"},"type":"patent","title":"Retroreflective Temperature- and Pressure-Sensitive Paints","abstract":"Pressure-sensitive paints (PSP) and temperature-sensitive paints (TSP) are widely used for surface measurement and flow visualization, yet their application prevents simultaneous schlieren-based visualization as the model on which they're applied obstructs schlieren line-of-sight and has separate optical access and alignment requirements. By making PSP/TSP surfaces exhibit retroreflective properties, methods such as self-aligned focusing schieren (SAFS), background-oriented schlieren (BOS), and shadowgraph could leverage the surface to provide a simultaneous off-body flow visualization capability. However, achieving desired accuracy, optical clarity, and retroreflective properties within conventional PSP systems depends on coating composition, surface preparation, and optical properties. This restricts flexibility in obtaining simultaneous on-body surface measurements and off-body flow visualization. To address these limitations, researchers at NASA Langley Research Center developed Retroreflective-Enhanced PSP/TSPs for Simultaneous Schlieren-Based Measurements. This solution enables simultaneous acquisition of surface measurements and schlieren imagery from a single optical access point across wider aerodynamic testing scenarios. The retroreflective-enhanced PSP/TSP enhances combined surface and flow field measurements with improved optical efficiency, making it a versatile tool for comprehensive aerodynamic testing and flow visualization.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_5","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-5","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-5","confidence":"high"},"type":"patent","title":"Dispersion of Carbon Nanotubes in Polymers","abstract":"NASA's Langley Research Center researchers have developed an extensive technology portfolio on novel methods for effective dispersion of carbon nanotubes (CNTs) in polymers. The technology portfolio extends from making stable dispersions of CNTs in polymer resins to processes for making composite CNT/polymer films and articles. The technologies apply to a range of polymer types, enable low or high CNT loadings as needed, and can be used with a variety of standard polymer processing methods, including melt processing. Currently, the technology is being used commercially for electrically conductive polymer films for components in electronic printers and copiers.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_97","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-97","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-97","confidence":"high"},"type":"patent","title":"Particle Contamination Mitigation Methods","abstract":"NASA's Langley Research Center researchers offer you methods for particle contamination mitigation. The methods were developed for exploration of surfaces such as Moon, Mars, and asteroids. During past missions, lunar dust caused an array of issues including compromised seals, clogged filters, abraded visors and space suit surfaces, and was a significant health concern. NASA's novel methods for particle contamination mitigation include both controlled chemical and topographical modifications. These methods offer a wealth of applications and commercial opportunities. The benefits include films, coatings, and surface treatments with antifouling, dust resistance, hydrophobic to superhydrophic, low adhesion/friction, and self-cleaning characteristics. NASA is seeking development partners.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_107","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-107","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-107","confidence":"high"},"type":"patent","title":"New Methods in Preparing and Purifying Nanomaterials","abstract":"Innovators at NASA's Glenn Research Center have made several breakthroughs in treating hexagonal boron nitride (hBN) nanomaterials, improving their properties to supplant carbon nanotubes in many applications. These inventors have greatly enhanced the processes of intercalation and exfoliation. Both processes are crucial in creating usable nanomaterials and tailoring them for specific engineered applications. In addition, Glenn's researchers have devised a means of fabricating exfoliated hBN-alumina ceramic composites, which have great potential as high-thermal-conductivity electrical insulators, as well as a new method to remove impurities from nanomaterials without causing damage to their structures. All of these advances have hBN nanomaterials set to transform applications such as heat sinks, electrical insulators, lightweight piezoelectric polymers for satellites and unmanned aerial vehicles, ceramic composites for jet engines, biomedical components, and radiation shielding technology.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_115","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-115","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-115","confidence":"high"},"type":"patent","title":"Resin Transfer Molding (RTM) 370 Resin for High-Temperature Applications","abstract":"Innovators at NASA's Glenn Research Center have developed a Resin Transfer Molding (RTM) imide resin known as RTM370 that is generated using a revolutionary, solvent-free process. Its many desirable properties earned it a prestigious R&D 100 Award in 2017. RTM370 has a high glass transition temperature (T g = 370&deg;C), low-melt viscosity (20 to 30 poise), and long shelf life (up to 2 hours). It can perform at temperatures exceeding 300&deg;C. It melts at 260 to 280&deg;C and can be cured at 340 to 370&deg;C without releasing any harmful or volatile compounds. It is suitable for composite fabrication by injection molding, RTM, resin film infusion (RFI), or vacuum-assisted resin transfer molding (VARTM). Furthermore, carbon fiber filled RTM370 is adaptable to additive manufacturing and can be printed into composite parts by laser sintering - a major breakthrough in high-temperature composite fabrication. These cutting-edge carbon fiber composites can replace any metallic part, providing high-quality, lightweight materials to a variety of industries at low-cost.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_117","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-117","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-117","confidence":"high"},"type":"patent","title":"Optically Transparent Polyimide Aerogels","abstract":"Innovators at NASA's Glenn Research Center have expanded their growing portfolio of aerogels to include a new optically transparent polyimide aerogel. Aerogels - low density, highly porous, ultralight materials derived from gels - can be fabricated to achieve specific, desirable traits, including various ranges of optical transparency. In the past, high optical clarity was most commonly produced in silica aerogels, which shed dust particles and are notoriously fragile and brittle. In contrast, polyimide aerogels possess remarkable strength and flexibility. They are often used in aerospace applications due to their ability to retain their physical and mechanical properties in thermally and chemically demanding environments. Glenn's new polyimide aerogel maintains the robust nature of a polyimide network, while providing the added feature of extremely high surface areas and uniform pore size and distribution. This unique combination of strength, transparency, and exceptional insulating properties make these aerogels ideal for replacing windows, windshields, and more at a fraction of the weight and without the use of harmful or toxic chemical coatings.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_121","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-121","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-121","confidence":"high"},"type":"patent","title":"Oil-Free Lubricants","abstract":"NASA's Glenn Research Center has developed high-temperature solid lubricant materials to reduce friction and wear in mechanical components, especially in extreme temperatures. The lubricant performs in temperatures from cryogenic levels to greater than 900&deg;C. It has been formulated to provide higher density, smoother surface finish, and better dimensional stability than prior solid lubricant coatings. It can be applied either through plasma spraying as a coating, known as PS400, or as a solid composite material via powder metallurgy, known as PM400. Because of its ability to maintain thermal and chemical stability in higher temperatures, PS/PM400 enables efficiency increases of up to 40% in rotating machinery applications. Furthermore, PS/PM400 has proven durable in over 20,000 hours of turbine engine operation. PS/PM400 offers a substantial upgrade in wear resistance and efficiency for a vast range of aerospace and aeronautics applications. Its unique combination of good mechanical properties, long-term environmental durability, exceptional friction and wear-reducing characteristics, higher density, smoother finish, and better dimension stability establishes it in a class by itself among solid self-lubricating materials.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_132","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-132","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-132","confidence":"high"},"type":"patent","title":"Conductive High-Toughness Oxides","abstract":"Innovators at NASA's Glenn Research Center have developed a novel method for making oxide coatings that have excellent mechanical strength and electronic conductivity at room temperature. Using the Plasma Spray-Physical Vapor Deposition (PS-PVD) processing methodology, Glenn researchers have been able to produce a coating containing a metastable phase that no other method can achieve. Upon exposing the material to moderate temperatures (greater than 300&deg;C) in the presence of oxygen, the metastable phase is further oxidized, and the material becomes insulating while retaining its high toughness and microstructure. With this innovation, a coating can be created from any metal oxide, including rare earth oxides, zirconium oxide, hafnium oxide, titanium oxide, or any combination of two or more oxides. Glenn's innovation has great potential for industries that require increasingly tough ceramic coatings, such as electronics, chemical and petroleum refineries, the aerospace industry, and automotive and aeronautics manufacturing.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_133","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-133","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-133","confidence":"high"},"type":"patent","title":"Durable Polyimide Aerogels","abstract":"Innovators at NASA's Glenn Research Center have developed cutting-edge polyimide aerogel technologies that are 500 times stronger than traditional silica aerogels. These durable polyimide aerogels are highly flexible and foldable in contrast to traditional silica aerogels, which shed dust particles and are notoriously fragile and brittle. Polyimide aerogels possess remarkable strength, flexibility, and moisture resistance and make excellent \"wrappable\" insulators. No other aerogel possesses the compressive and tensile strength of this organic polyimide aerogel while still retaining its ability to be flexibly folded to contour to whatever shape is needed such as automotive shields, pipeline insulation, and protective clothing. Glenn's durable polyimide aerogels combine the robust nature of a polyimide network with low thermal and sound conductivity. This unique combination of strength, flexibility, and exceptional insulating properties make these aerogels ideal for insulation (thermal, electrical, and acoustic), structural elements and more - at a fraction of the weight of similar materials.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_136","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-136","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-136","confidence":"high"},"type":"patent","title":"Environmental Barrier Coatings for Ceramic Matrix Composites","abstract":"Innovators at NASA's Glenn Research Center have developed two durable environmental barrier coatings (EBCs) for use with ceramic matrix composite (CMC) components. CMCs are lightweight composites used to reduce fuel consumption in advanced gas turbines and other high-temperature, high-stress environments (up to 1482&deg;C). Glenn's breakthrough EBCs are the only coatings that can withstand such temperatures, protecting CMCs from increased wear and corrosion, oxidation, and water vapor recession in extreme environments. In addition, these EBCs can be fabricated with simpler and lower-cost methods than conventional coating processes such as plasma spraying. Glenn's EBCs add reliability and lifespan to CMCs' advantages of lighter weight, higher temperature capability, and greater oxidation resistance. This innovation is poised to facilitate the upcoming CMC revolution, from hot components in next-generation, fuel-efficient jet engines to furnaces to nuclear reactors.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_139","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-139","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-139","confidence":"high"},"type":"patent","title":"Ruthenium-Doped Thermoelectric Materials","abstract":"Innovators at NASA's Glenn Research Center have developed a novel thermoelectric material that raises the bar for solid-state power conversion devices. There is growing momentum in the aerospace and automotive industries to harvest energy from heat (such as exhaust from combustion), but advances have been hampered by the lack of environmental durability and performance levels of thermoelectric materials currently in use. Glenn's breakthrough material is a ruthenium-doped gadolinium orthotantalate that excels at directly converting heat into energy. More important, this material does not break down at higher temperatures or air environments - even without special coatings or inert packaging. Glenn's pioneering material enables designers to make great strides in developing solid-state power conversion devices for application in aerospace , automotive, and power-generation industries.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_141","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-141","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-141","confidence":"high"},"type":"patent","title":"Aerogel Reinforced Composites","abstract":"NASA's Glenn Research Center (GRC) has developed a method for fabricating low-density, flexible aerogel composites for use as thermal insulation for myriad applications. It is ideal for a variety of environments that require insulation materials that can withstand temperatures of up to 1200&deg;C. This innovation significantly advances the state of the art for composite insulation systems, reducing adherence problems and thermal conductivity limitations of conventional aerogel insulations while improving performance with lower weight and lower density, and higher efficiency, all factors contributing to greater applicability of aerogel insulation.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_144","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-144","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-144","confidence":"high"},"type":"patent","title":"High-Strength Superelastic Compounds","abstract":"NASA's Glenn Research Center has developed a new method for producing a shock- and corrosion-proof superelastic intermetallic materials including NiTiNOL 60 (60NiTi) for use in ball bearings and other mechanical components. These superelastic materials can withstand tremendous loads and stresses without permanent deformation or denting. At the same time, the nickel-titanium alloy is immune to corrosion and rust, unlike mechanical components made from iron or steel. In addition, the material does not chemically degrade or break down lubricants, a common problem with existing bearing materials. These materials are best suited for oil lubricated rolling and sliding contact applications requiring superior and intrinsic corrosion resistance, electrical conductivity, and non-magnetic properties.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_151","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-151","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-151","confidence":"high"},"type":"patent","title":"Oxide Dispersion Strengthened Medium Entropy Alloy","abstract":"Innovators at the NASA Glenn Research Center have developed a new oxide dispersion strengthened medium entropy alloy (ODS-MEA) using additive manufacturing (AM). ODS alloys, in which nano-scale ceramic particles are distributed within the metal, were originally developed to enhance mechanical properties (e.g., creep resistance, tensile strength, microstructure integrity) at extreme temperatures. Thus, such alloys show promise for metal components of gas turbines, rocket engines, nuclear reactors and other high-temperature applications. However, the conventional mechanical alloying process to produce such alloys is highly inefficient, time-consuming, and costly. By contrast, NASA's ODS-MEA is designed for production via selective laser melting. The alloy can be fabricated into complex geometries and is resistant to stress cracking and dendritic segregation. It is not susceptible to deleterious phase changes when exposed to extreme temperatures and requires limited post-processing.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_152","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-152","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-152","confidence":"high"},"type":"patent","title":"High-Temperature Ni-Based Superalloy Composition","abstract":"Innovators at the NASA Glenn Research Center have developed a nickel-based superalloy using specific alloying elements to inhibit deleterious deformation at temperatures above 700&#176;C. The drive for energy efficiency in power generation and propulsion places the development of high-performance materials at the forefront of materials science. Turbine engine efficiency and reduction in carbon emissions are directly related to engine operating temperature. With increasing temperatures, materials start to plastically deform under load, a process known as creep, which sets severe limits on performance. Therefore, increased performance in aircraft engines and land-based power generators requires the development of new high-temperature structural materials that are resistant to creep. For example, a main factor prohibiting higher operating temperatures in jet turbine engines is the creep life of the Ni-based superalloy turbine disks. NASA's new superalloy composition significantly improves the creep life of turbine disks and also increases the operating temperature limit.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_154","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-154","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-154","confidence":"high"},"type":"patent","title":"Carbon Fiber-Carbon Nanotube Yarn Hybrid Reinforcement","abstract":"Innovators at the NASA Glenn Research Center have developed a toughened hybrid reinforcement material made from carbon fiber and carbon nanotube (CNT) yarn for use in polymer matrix composites (PMCs). The new material improves toughness and damping properties of PMCs, enhancing impact resistance, fatigue life, and structural longevity. Historically, PMCs have provided insufficient toughness for some aerospace structures. Rubber toughening agents and thermoplastics are often employed to increase material toughness, but such additives increase viscosity of polymer resins and increase processing difficulty and cost. Other reinforcements like aramids exist, but also have inherent issues (e.g., Kevlar absorbs moisture which adds weight and is susceptible to degradation upon UV exposure). NASA's new carbon fiber-CNT yarn hybrid material displays excellent toughness and strength for reinforcing PMC materials while also mitigating issues associated with current hybrid reinforcements like rubber, thermoplastics, and aramids.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_172","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-172","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-172","confidence":"high"},"type":"patent","title":"Rapid Fabrication of Boron Nitride Fine Fibers","abstract":"Hexagonal boron nitride (h-BN) nanofibers have become an area of significant interest to industry given their combination of unique characteristics including excellent thermal conductivity, high electrical resistivity, chemical inertness, light weight, and mechanical strength. Potential applications for h-BN nanofibers include their use as an additive to polymers and other composites to improve material properties, high voltage cable insulation, re-entry shielding, radiation shielding, electric vehicle thermal dissipation, and much more. However, manufacturing of h-BN nanofibers is costly, difficult at scale, and could pose respiratory hazards resulting from their small scale (< 100nm). This has limited the commercial availability of h-BN nanofibers. High-cost BN nanosheets are available, but their use is limited as the form factor is already established and they are difficult to disperse. h-BN nanofibers could be a critical technology enabling the development of advanced multifunctional materials not just for space systems, but also for a variety of terrestrial applications. So, innovators at NASA\u2019s Glenn Research Center (GRC) developed a polymer derived ceramic (PDC) process utilizing forcespinning technology that enables the rapid, low-cost fabrication of h-BN fibers. Fibers generated using the process have larger diameters (\u2265 200nm), mitigating respiratory hazard risk.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_173","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-173","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-173","confidence":"high"},"type":"patent","title":"Innovative Shape Memory Metal Matrix Composites","abstract":"Researchers at the NASA Glenn Research Center have developed a new family of shape memory alloys that are strengthened by incorporating ceramic or refractory nanoparticles into the alloy. The resulting material is referred to as a shape memory metal matrix composite or SM3C. The new dispersion-strengthened metals retain the useful properties of the shape memory alloy without the typical deficiencies. Specifically, the dispersoids improve the material\u2019s dimensional and thermal stability while increasing both the creep resistance and hardness. The SM3C material is compatible with multiple manufacturing processes including additive manufacturing, mechanical alloying, or other conventional processes like melting and extrusion. Parts produced using the SM3C may be used in various aerospace , marine, or automotive applications as actuators or in the biomedical field as surgical tools and orthopedic implants.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_174","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-174","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-174","confidence":"high"},"type":"patent","title":"Precipitation Strengthened Ni-Ti-Pd Shape Memory Alloys","abstract":"Inventors at the NASA Glenn Research Center have developed a set of chemistries and processing methods to enable improved shape memory alloys (SMAs) through precipitation strengthening and crystallographic phase control. These chemistries and methods yield SMAs with higher strengths, low thermal hysteresis of the actuation temperature, improved structural stability, and faster training processes. The enhanced shape memory properties are enabled by the addition of Palladium (Pd) and small amounts of other metal elements, to base nickel-titanium (NiTi) alloys and precise control of the heat treatments performed on the new alloys that encourage the growth of precipitate phases (i.e., finely dispersed, coherent or semi-coherent, nanometer size precipitates). Components made of the new SMAs may be used as actuators in space, aeronautics , and automotive applications across a wide range of temperatures as well as in biomedical settings as surgical tools, implants, or stents.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_175","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-175","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-175","confidence":"high"},"type":"patent","title":"Economical, On-Demand GRCop Alloy Production","abstract":"Researchers at NASA Glenn Research Center have developed a new method to make high-performance GRCop alloys. This technology enables in-situ alloying of GRCop, a copper-chromium-niobium alloy, during additive manufacturing using only elemental metal powders instead of expensive pre-alloyed powders. The key advancement leverages the laser melting process step to react chromium and niobium directly within the pure copper matrix to form the Cr2Nb strengthening precipitate. This in situ processing enables significant advantages over conventional gas atomization methods including on-demand production, lower manufacturing costs, shorter lead times, and less impurity contamination. This innovative approach unlocks new design freedoms and alloy compositional flexibility for this high-performance copper alloy. The images above show that the new, patented, alloying process (in situ alloying of GRCop) produces strengthening phases (in left image) similar in size and shape to the conventional process of gas atomization of GRCop (on the right). The similarity suggests that NASA's new alloying process has the potential to perform as well as the conventional method that NASA has used to produce additively manufactured GRCop hardware.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_179","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-179","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-179","confidence":"high"},"type":"patent","title":"Advanced Materials for Electronics Insulation","abstract":"Electrical insulation materials for wires and other high-power electronics must have the additional property of high thermal conductivity to adequately dissipate heat from critical electrical components. The typical insulating materials are polymers, which are not sufficiently thermally conductive for heat management. Additives like ceramic nanoparticles may be mixed with polymers to improve the thermal properties, but the blended materials can be difficult to manufacture into appropriate shapes (e.g., ribbons) for insultation without introducing voids or agglomerates of the additives. Innovators at NASA\u2019s Glenn Research Center have developed polymer composite formulations that have high thermal conductivity while maintaining the electrically insulating properties of the polymer. Additionally, NASA has developed manufacturing processes that produce high-quality, well-mixed, void-free materials. These electrically insulating and thermally conductive composites may be used as insulation for electrical components in electric motors, power generation, or in healthcare equipment.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_20","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-20","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-20","confidence":"high"},"type":"patent","title":"Polymer Cross-Linked Aerogels (X-Aerogels)","abstract":"NASA's Glenn Research Center (GRC) has developed and produced ultra-lightweight polymer cross-linked aerogels (X-Aerogels). These mechanically robust, highly porous, low-density materials are 3 times denser than native aerogels, but more than 100 times stronger. Aerogels are ultra-lightweight glass foams with extremely small pores (on the order of 10 to 50 nanometers). These materials are extremely good thermal insulators, with R values ranging from 2 to 10 times higher than polymer foams. Unlike multilayer insulation, aerogels do not require a high vacuum to maintain their low thermal conductivity and can function as good thermal insulators at ambient pressure. In addition, they are good electrical insulators and have low refractive indices both approaching values close to air. Aerogels are also excellent vibration damping materials. Traditional aerogels, however, suffer fragility and poor environmental durability.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_25","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-25","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-25","confidence":"high"},"type":"patent","title":"Silicon Carbide (SiC) Fiber-Reinforced SiC Matrix Composites","abstract":"Innovators at NASA's Glenn Research Center have conducted leading-edge research toward the development of silicon carbide (SiC) fibers and SiC/SiC ceramic matrix composites (CMCs) that can be used in high-temperature structural applications, such as hot components in gas turbine engines. Glenn has gained recognition for the innovative design and processing technologies required for these materials. NASA's patented SiC/SiC CMC technologies use the advantages of non-oxide SiC fibers and matrices to yield ceramic composites that can withstand adverse structural and environmental conditions for long times at temperatures up to 2700&deg;F. The CMC properties offer significant benefits in comparison to other options, including metallic superalloys, monolithic ceramics, carbon fiber composites, and oxide/oxide ceramic composites. These composites are also invaluable in their ability to be engineered for specific stress, temperature, life, and environmental conditions.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_27","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-27","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-27","confidence":"high"},"type":"patent","title":"Vertically Aligned Carbon Nanotubes","abstract":"Innovators at NASA\u2019s Glenn Research Center have developed a polymer matrix composite composed of layers that alternate between a thin carbon fiber veil layer coated with nanotubes and a thicker base carbon fiber reinforcement layer. The alternating fiber layers are held together by a curable epoxy resin. The resulting composite material provides improved interlaminar strength, fracture toughness and impact resistance. The carbon fiber veils can be evenly distributed throughout the composite or targeted to specific areas of a part that are likely to require reinforcement. For example, veils can be selectively situated at a leading edge of a wind turbine blade, a helicopter blade, an engine component, an air foil, or an aircraft nose section. Since the veils themselves do not impart strength or stiffness to the composite structure, any damage to the veils does not affect the integrity of the composite structure. The embedded carbon nanotubes can provide through thickness thermal and electrical conductivity. The electrically conductive nature of the nanocomposite veils allows for their application for added lightning strike protection and electromagnetic protection.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_31","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-31","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-31","confidence":"high"},"type":"patent","title":"Polyamide Aerogels","abstract":"Sometimes referred to as \"solid smoke,\" aerogels are the world's lightest solid materials , composed of approximately 85&#37; air by volume. Polyamide aerogels open up a whole new world of applications due to their unique properties: translucent like silica aerogels; thermoplastic; ultra-low density; superior mechanical properties; low-temperature operating range; and highly flexible (as compared to NASA Glenn's polyimide aerogels). Polyamide aerogels are further novel because of their tunable glass transition temperatures, meaning that crystallinity -- and hence strength -- can be controlled via operating temperature. Addressing the key drawbacks of aerogel technology (hydroscopicity, fragility, cost), NASA Glenn's suite of organic aerogels are cost-competitive with both existing silica aerogels and, with scale-up, high-end foamed polymer insulation. Finally, Glenn's materials are truly multi-functional -- they can be structural members while providing superior thermal properties and extremely low dielectric (near that of air).","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_32","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-32","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-32","confidence":"high"},"type":"patent","title":"How to Train Shape Memory Alloys","abstract":"Shape memory alloys (SMAs), sometimes known as \"smart metals,\" provide a lightweight, solid-state alternative to conventional actuators and switches, such as hydraulic, pneumatic, or motor-based systems. To function properly, SMAs must be \"trained\" to return to a previous form when heated, and innovators at NASA's Glenn Research Center have developed a remarkable new method of completing this training at a fraction of the time and cost of conventional training techniques. Glenn's technique uses mechanical cycling, rather than more complicated and time-consuming thermal cycling, to train SMAs before implementation. In addition, this new approach to training allows SMAs to be applied to complex geometric components, so that they may be used in a broader number of applications.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_62","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-62","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-62","confidence":"high"},"type":"patent","title":"Rare Earth Aluminate Composites","abstract":"Bearing surfaces are typically either metal-on-metal (MOM), ceramic-on-ceramic (COC), or metal-on-polyethylene (MOP). MOM and MOP couplings have the drawback that metallic or polyethylene particles can sometimes separate from the couplings, which can cause significant problems, particularly in a hip or joint replacement. COC couplings are less likely to lose particles due to wear, which makes them more biocompatible, but they are more susceptible to fracture. COC couplings also have a tendency to squeak as they move. Innovators at NASA's Glenn Research Center have developed a technique using rare earth elements to fabricate a dual-phase ceramic composite that combines a wear-resistant phase and a solid-state lubricant phase. The result is a coupling material that, compared to currently used materials , exhibits a tenfold reduction in the friction coefficient, a sixfold reduction in wear, and a significant reduction in debris caused by wear. Glenn's groundbreaking rare-earth aluminate composite has considerable potential, not only in biomedical applications but also in commercial and industrial sectors.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_137","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-137","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-137","confidence":"high"},"type":"patent","title":"Printable Heat Shield Formulations Advance Spacecraft Construction","abstract":"Innovators at NASA Johnson Space Center have developed an additively manufactured thermal protection system (AMTPS) comprised of two printable heat shield material formulations. These formulations are directly applied by 3-D printer or other robotic extrusion system, and bonded to a spacecraft to devise a heat shield suitable for atmospheric entry. This technology could significantly decrease heat shield or thermal protection system (TPS) fabrication cost and time. Current state of the art TPS manufacturing and application methods are expensive, labor-intensive, and complex. These drawbacks are primarily due to the amount of skilled, manual labor needed for form fitting and bonding individual TPS tiles across a spacecraft \u2019s forebody \u2013 each tile comprised of differing thermal properties and layers \u2013 and includes filling the gaps in-between the tiles with an additional component formulation. This AMTPS technology can solve these challenges and may represent a game changing innovation in TPS manufacturing \u2013 away from convention-al labor-intensive, costly, long-schedule techniques and towards automa-tion. It reduces the complexity of TPS integration, and eases the produc-tion of large and specially contoured heat shields. Additionally, this tech-nology allows heat shields to be created as a single mold and prevents the need to treat the tile gaps of current heat shields, thus eliminating numerous potential failure points.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_34","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-34","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-34","confidence":"high"},"type":"patent","title":"Enhanced Software Suite Maximizes Non-Destructive Evaluation (NDE) Methods","abstract":"Researchers at NASA Johnson Space Center have developed novel techniques for post-processing of flash infrared (IR) thermography data, providing efficient and cost-effective enhancements to Non-Destructive Evaluation (NDE) of structures for numerous applications. Compatible with commercial IR thermography products, this suite of tools provides both quantitative and qualitative data analysis capabilities and reliable detection and characterization of anomalies in composite and some metallic hardware. By adding the Transient Thermography method, which is able to detect flaws on thicker parts faster than other methods, and the Lock-in Thermography method, which uses a sinusoidal power cycle to provide better flaw resolution, the Flash Thermography NDE Technology Suite has expanded its applicability to other commonly used infrared thermography techniques, enhancing operator accuracy and efficiency.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_89","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-89","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-89","confidence":"high"},"type":"patent","title":"\u2018Diamond Maker\u2019 Technology Simulates Subsurface Geology in Laboratories","abstract":"Innovators at NASA Johnson Space Center have developed a novel, double capsule control system that allows for high temperature and high-pressure geologic research to be performed in a contained environment relevant to a broad array of materials . It can also yield the speciation of redox-sensitive elements and is even capable of creating geologic conditions necessary to birth diamonds when used in conjunction with a multi-anvil press. Users of this technology can specify a wide range of oxygen fugacity (fO2) values during experiments. fO2 is a measure of rock oxidation that influences planetary structure and evolution and contributes directly to the study of our galactic origins. It commands some of the fundamental chemical and physical properties in planetary materials , including electrical conductivity, grain-growth kinetics, and phase stability. This technology was previously used to replicate fO2 environments relevant to core samples from the Moon and those obtained from the Earth\u2019s deep crust. It may be further extended to higher pressure and higher temperature studies where greater control of a specific experimental sample environment might allow unique chemical bonding and reactivity that would not be possible in systems that utilize the standard approaches.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_183","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-183","sourceUrl":"https://technology.nasa.gov/patent/TOP2-183","confidence":"high"},"type":"patent","title":"Surface Densification Of Phenolic Impregnated Carbon Ablator (PICA)","abstract":"This technology from NASA allows a graded-surface densification of Phenolic Impregnated Carbon Ablator (PICA). PICA was developed at NASA Ames Research Center in the 1980s for the forebody heatshield of the Stardust Return Capsule. With a low density (~0.27g/cm), coupled with efficient ablative capability at high heat fluxes, PICA became an enabling technology for the Stardust mission. At the time of the mission, PICA was a developmental material, with no previous flight heritage. For missions with high heat flux, a lower overall mass can be obtained if the Thermal Protection System (TPS) composition changes from a carbon-based ablator at the heated surface to an insulator near the inner surface. This new process delivers a graded surface-densification application to PICA allowing for optimized performance and TPS weight reduction. The desired surface densification is adaptable in terms of density of the applied surface treatment and depth of the surface treatment.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_211","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-211","sourceUrl":"https://technology.nasa.gov/patent/TOP2-211","confidence":"high"},"type":"patent","title":"Creating Low Density Flexible Ablative Materials","abstract":"NASA has created a new approach to make a low density flexible ablative Thermal Protection Surface (TPS) material. The material is foldable and can be stowed in space for very long periods of time (years) without compromising deployability or performance. These flexible ablators offer an alternative to rigid TPS materials there by reducing design complexity associated with rigid TPS materials resulting in reduced TPS cost. The low density flexible ablator is unique in that the material retains its flexibility after charring. The charred material has similar flexibility and strength to the virgin material. This is in contrast too there flexible ablator concepts whereas stiffer chairs produced during heating.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_215","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-215","sourceUrl":"https://technology.nasa.gov/patent/TOP2-215","confidence":"high"},"type":"patent","title":"A New Family of Low-Density, Flexible Ablators","abstract":"NASA has developed a method for producing a flexible, fibrous ablator thermal protection material for use on space vehicles experiencing temperatures of 1000 F (550 C) or above upon atmospheric re-entry. The flexible ablator has controllable elastic modulus and controllable flexibility to withstand a wide range of heating rates comparable to rigid ablators, such as PICA and Avcoat. A phenolic resin and/or a silicone resin can be used. The elastic modulus of the resulting material is low, in a preferred range of about 200-5000 kPa, and can be controlled by choice of a curing temperature and/or a time interval length for curing.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_226","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-226","sourceUrl":"https://technology.nasa.gov/patent/TOP2-226","confidence":"high"},"type":"patent","title":"A New Class of Strong and Flexible Carbon Fiber Reinforced Phenolic Composites","abstract":"NASA has filed a patent on a technology that creates a new class of phenolic and carbon fiber reinforced phenolic composites for thermal protection systems. The new materials have the advantage of being lightweight, strong, tough, yet heat resistant, and flexible. Their best characteristic is their remarkable capability to retain excellent mechanical strength at high temperatures. This provides better thermal protection for re-entry conditions with high heating rates. The materials incorporate thermoplastic polymer segments that are uniformly distributed throughout, and chemically bonded to the phenolic network. Phenolic resin polymers are a class of widely used thermosetting polymers. Their numerous advantages include excellent heat, radiation, corrosion/chemical resistances, and being flame retardant. They are low cost and have versatile processing/manufacturing methods.","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_241","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-241","sourceUrl":"https://technology.nasa.gov/patent/TOP2-241","confidence":"high"},"type":"patent","title":"Thermal protection supplement for reducing interface thermal mismatch","abstract":"NASA has a new innovation that represents an exciting leap forward in reusable thermal protection systems (TPS) technology. The Toughened Uni-Piece Fibrous Reinforced Oxidation-Resistant Composite (TUFROC) allows for much more affordable and sustainable operations involving Space Launch Services and other systems that utilize Earth re-entry vehicles. TUFROC has an exposed surface design and appropriate materials combination that will allow a space vehicle to survive both the mechanical stresses of the initial ascent and the extreme heating and stress of re-entry. It provides a thermal protection tile attachment system that is suitable for application to a space vehicle leading edge and for other uses in extreme heating environments (up to 3600 degree F., and possibly higher, for short time intervals).","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_244","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-244","sourceUrl":"https://technology.nasa.gov/patent/TOP2-244","confidence":"high"},"type":"patent","title":"Multifunctional Ablative Thermal Protection System","abstract":"NASA has developed a unique and robust multifunctional material called 3DMAT that meets both the structural and thermal performance needs for a lunar return mission and beyond. The 3DMAT Thermal Protection System (TPS) uses a game-changing woven technology tailored to the needs of the Orion Multi-Purpose Crew Vehicle (MPCV) compression pad in order to support the lunar return mission, EM-1, and beyond. Compression pads serve as the interface between the crew module and service module of the Orion MPCV. The compression pads must carry the structural loads generated during launch, space operations, and pyroshock separation of the two modules. They must also serve as an ablative TPS withstanding the high heating of Earth re-entry. 3DMAT leverages the NASAs investment in woven TPS to design, manufacture, test, and demonstrate a prototype material for the Orion compression pads that combines the weaving of quartz yarns with resin transfer molding.","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_260","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-260","sourceUrl":"https://technology.nasa.gov/patent/TOP2-260","confidence":"high"},"type":"patent","title":"New Resin Systems for Thermal Protection Materials","abstract":"This innovation focuses on an improved low density ablator with improved structural performance and high temperature capability. A new polymer system consisting of cyanate ester and phthalonitrile resins were used to create this carbon reinforced ablator. Cyanate ester resin is a thermoset resin which has high char stability, high decomposition temperature, low oxygen content, low moisture absorption and high glass transition temperature (400 degrees Celsius). Phthalonitrile resin is another type of thermoset resin which has very high char stability, and high decomposition temperature (480 degrees Celsius).","category":"materials_coatings","categoryRaw":"materials and coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_331","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-331","sourceUrl":"https://technology.nasa.gov/patent/TOP2-331","confidence":"high"},"type":"patent","title":"Flexible Phenolic Intermingled Carbon Ablators (PICA-Flex)","abstract":"For the past three decades, phenolic impregnated carbon ablators (PICAs) have been the state of the art in ablative entry materials for heat shields for Mars and Earth sample return missions for entry conditions. Traditional rigid PICAs have very low density and highly efficient ablative capability to provide mass efficiency for these heating regimes. Non-rigid variants of PICA provide additional benefits beyond traditional rigid PICA, offering reduced density variants with increased strain to failure. However, all three materials require lengthy infusion processes involving complex equipment and infrastructure, yield toxic byproducts, and the rigid thermal protection system (TPS) produced requires complex and costly integration processes. NASA Ames has developed a family of materials called Materials Engineered for Re-entry using Innovative Needling Operations (MERINO), a flexible PICA material based on felting and fiber intermingling techniques that can create a blanket of thermal protection material to install onto spacecraft .","category":"materials_coatings","categoryRaw":"Materials and Coatings","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_12","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-12","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-12","confidence":"high"},"type":"patent","title":"Gear Bearings","abstract":"NASA Goddard Space Flight Center (GSFC) invites companies to license the revolutionary gear bearing technology. This technology represents a mechanical architecture breakthrough by combining gear and bearing functions into a single unit that significantly improves gear drives across the board for electrical, internal combustion, and turbine motors. The gear bearing design incorporates rifle-true anti-backlash, improved thrust bearing performance, and phase-tuning techniques for superior low-speed reduction. Because it combines gear and bearing functions, it reduces weight, number of parts, size, and cost, while also increasing load capacity and performance.","category":"mechanical_systems","categoryRaw":"mechanical and fluid systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_139","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-139","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-139","confidence":"high"},"type":"patent","title":"Micro scale electro hydrodynamic (EHD) modular cartridge pump","abstract":"This NASA innovation incorporates a simplistic design that reduces the number of components required to make an assembly by up to 90% over previous iterations, insuring a solid reliable electrical connection to the electrodes that form the pumping sections and is modular in overall design to allow for flexibility in incorporating the pump cartridge into various assemblies and applications.","category":"mechanical_systems","categoryRaw":"mechanical and fluid systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_285","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-285","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-285","confidence":"high"},"type":"patent","title":"Fluid Transfer Coupler","abstract":"A fluid coupling is a hydrodynamic or hydrokinetic device used to transmit rotating mechanical power. It has been used in automobile transmissions as an alternative to a mechanical clutch. It also has widespread application in marine and industrial machine drives, where variable speed operation and controlled start-up without shock loading of the power transmission system is essential. A fluid coupling consists of a housing and two turbines, plus the hydraulic fluid. The housing contains the fluid and turbines. The hydraulic fluid is directed by a pump whose shape forces the flow in the direction of the output turbine. The motion of the fluid is effectively toroidal. The Fluid Transfer Coupler addresses trades between ball-in-grove type couplers and pivoting pawls, along with various types of seals.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_378","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-378","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-378","confidence":"high"},"type":"patent","title":"ActiVator: A High-Performance Line Climber for Kite-Based Atmospheric Sensing","abstract":"Researchers at NASA\u2019s Wallops Flight Facility have developed a high-performance line climber, the ActiVator, for kite-based atmospheric profiling and remote sensing. Designed to carry cameras, atmospheric sensors, and other instrumentation, the ActiVator maintains a precisely controlled center of gravity within a defined location envelope, ensuring stable and reliable data collection. While line climbers have been used for decades, the ActiVator represents a significant advancement with its lightweight, aerodynamically optimized design, allowing precise altitude control and adjustable climb and descent speeds. Key innovations include high-efficiency airfoil selection, a stability-enhancing tail configuration, and novel sensor integration methods, making it ideal for miniature payloads.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_102","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-102","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-102","confidence":"high"},"type":"patent","title":"Improved Lunar Regolith Simulant Ion Implantation","abstract":"The production of high-fidelity extraterrestrial regolith simulants is important for the development of future in-situ resource utilization (ISRU) and remote sensing technologies. For these materials , the mechanical properties can be readily replicated but the absorbed material, electrostatic, and dielectric properties of lunar, Martian, or asteroid regolith can be difficult to simulate. Innovators at the NASA Kennedy Space Center have developed a methodology and system that can implant helium, hydrogen, and other ions in regolith simulants to emulate the exposure of the simulated regolith to phenomena like solar winds. The system has been successfully prototyped and demonstrated to implant helium ions in simulated regolith and advancements in the material processing have led to low levels of contaminants in the regolith. The ion implanted regolith may be used to develop advanced ISRU, in-space mining, and remote sensing technologies.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_48","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-48","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-48","confidence":"high"},"type":"patent","title":"Feedthrough for Severe Environments and Temperatures","abstract":"NASA Kennedy Space Center seeks partners interested in the commercial application of the Feedthrough for Severe Environments and Temperatures. NASAs Kennedy Space Center (KSC) is offering companies licensing or partnering opportunities in the development of this innovative technology. KSC's new design provides a solution for the hermetically sealed feedthrough of wires, tubes, or fibers from one process side to another process side. Ether process side for a particular application can be high pressure or high vacuum. Additionally, the temperature of either process side can be either extremely cold (-452 degF) or elevated (305 degF). The design is capable of handling thermal cycling, pressure cycling, corrosive environments, and severe transient conditions with no leakage or other problems.","category":"mechanical_systems","categoryRaw":"mechanical and fluid systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_82","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-82","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-82","confidence":"high"},"type":"patent","title":"Miniaturized Electrospray System","abstract":"Innovators at NASA's John F. Kennedy Space Center have developed a miniaturized electrospray system that electrostatically charges and delivers liquids to grounded targets. The technology was developed as an alternative to existing options for in-space aeroponic food production applications. Typically, agricultural electrosprayers are large, high liquid-consumption devices that rely on pressurized gases to forcefully transport charged droplets up to 25 feet away from the nozzle. These existing electrosprayers are not ideal for precision applications in space. To meet this need, a miniaturized electrosprayer was created that requires only a liquid source, a nebulizing nozzle, a metallic ring positioned at the nozzle orifice, and power supply to energize the ring to facilitate droplet charging. Potential applications for the new technology include those where electrospray systems are currently employed like small-scale delivery of antimicrobial coatings (e.g., for COVID-19 disinfection), optical coatings, paint, nutrients, pesticides, water (e.g., for aeroponics), and more.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_136","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-136","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-136","confidence":"high"},"type":"patent","title":"Healable Carbon Fiber Reinforced Composites","abstract":"NASA Langley Research Center has developed carbon fiber reinforced composites with self-healing properties. The initiation and propagation of damage to carbon composites, such as in aircraft structural components, results in component failure. Typical structural repairs result in damaging practices, where material is ground away and holes are drilled to secure patches, which can act as new sites for damage. This technology exhibits effective self-repair that heals quickly following low to mid velocity impacts, while retaining structural integrity.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_189","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-189","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-189","confidence":"high"},"type":"patent","title":"Compact Vibration Damper","abstract":"NASA Langley Research Center has developed a compact tuned damper to reduce vibration occurring at a fixed frequency. Tuned dampers reduce vibration of the base structure by the dissipation of energy. The magnitude of the dissipated energy is proportional to the square of the displacement or velocity of the tuned mass, which in turn is proportional to the range of motion. The NASA damper design allows the slider mass to achieve 2x-3x greater range of motion than that found in conventional devices. This enables 4x-9x more effectiveness for the same size and weight; or the same effectiveness for a 4x-9x decrease in weight. The damper is also tunable and can be adjusted in effectiveness. The damper can be made small enough for use in wind tunnel tests or scaled up to large sizes, like those used in helicopters, wind turbines, or skyscrapers.","category":"mechanical_systems","categoryRaw":"mechanical and fluid systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_198","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-198","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-198","confidence":"high"},"type":"patent","title":"Composite Joint Connector","abstract":"NASA Langley Research Center has developed a composite joint connector that is more structurally efficient than joints currently on the market. Traditionally, composite joints can bear heavy loads along their length but tend to fail when stress is applied along multiple axes. This joint is designed to minimize stress concentrations, leading to overall increased structural efficiency when compared to traditional joints.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_268","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-268","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-268","confidence":"high"},"type":"patent","title":"SHEAth-based Rollable LEnticular-Shaped and Low-Stiction (SHEARLESS) Composite Booms","abstract":"NASA's Langley Research Center has developed the SHEARLESS composite boom with a final cross-section shape that is lenticular and is flexible enough to allow elastic flattening and subsequent coiling around a cylindrical reel / drum. The torsional stiffness of the structure is also greatly increased and becomes two orders of magnitude larger than that of the individual tape-spring components alone. The innovation enables a lightweight structure that can be stowed on a reel without appreciable shear stresses developing in its constitutive composite parts. This allows for unprecedentedly small coiling diameters for the total thickness of the structure, which can enable highly compact designs such as those required in CubeSat/small satellite applications.","category":"mechanical_systems","categoryRaw":"mechanical and fluid systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_290","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-290","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-290","confidence":"high"},"type":"patent","title":"Self-Tuning Compact Vibration Damper","abstract":"NASA Langley Research Center has developed a compact self-tuning damper to reduce vibration occurring at a fixed frequency. Tuned dampers reduce vibration of the base structure by the dissipation of energy. The magnitude of the dissipated energy is proportional to the range of motion. The NASA damper design allows the slider mass to achieve 2x-3x greater range of motion than that found in conventional devices. This enables 4x-9x more effectiveness for the same size and weight; or the same effectiveness for a 4x-9x decrease in weight. The damper is self-tunable and can be adjusted in effectiveness. The damper can be made small enough for use in wind tunnel tests or scaled up to large sizes, like those used in helicopters, wind turbines, or skyscrapers.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_314","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-314","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-314","confidence":"high"},"type":"patent","title":"Low, Drag, Variable-Depth Acoustic Liner","abstract":"A low-drag, variable-depth acoustic liner has been designed for aircraft noise reduction. The technology can be used as a conventional engine nacelle liner, or on the external surfaces of an aircraft to reduce acoustic scattering. As compared with conventional liners, the technology provides increased broadband acoustic performance with less drag. Conventional liners use a perforated facesheet as the outermost portion of the liner exposed to flow. The perforated facesheet has a higher drag than a smooth surface, but is necessary to reduce noise. The proposed innovation reduces the open area of the facesheet, and therefore reducing the drag of the liner, without compromising acoustic performance.","category":"mechanical_systems","categoryRaw":"mechanical and fluid systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_328","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-328","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-328","confidence":"high"},"type":"patent","title":"Deployable Composite Boom","abstract":"A sister to SHEARLESS booms, the Bistable Collapsible Tubular Mast (Bi-CTM) boom, offers compact storage on a cylindrical drum that deploys a composite material boom with a closed tubular cross section that has unmatched bending and torsional stiffness for the mass of the thin-shell structure. The Bi-CTM is also scalable for long booms given the load carrying capacity. The Bi-CTM's two omega-shaped composite thin-shells form a bonded closed section which can spool onto a relatively compact drum for compact launch packaging and provide unparalleled stiffness to mass ratio when deployed. When using the booms as beam-column structures with a primarily compressive load component, this ratio determines the structural mass efficiency of the components, making the Bi-CTM exceptional for lightweight deployable structural rigging with higher load demands. The improved dimensional and thermal stability offered by the closed-section shape and low coefficient of thermal expansion materials of the Bi-CTM, enables the use of the boom technology in precision applications that require high stability in harsh environments.","category":"mechanical_systems","categoryRaw":"mechanical and fluid systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_340","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-340","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-340","confidence":"high"},"type":"patent","title":"Active Flow Control System for Simple-hinged Flaps","abstract":"Conventional high-lift systems allow transport aircraft to safely operate at low speeds for landing and takeoff. These high-lift devices, such as Fowler flaps, are complex, heavy, and have high part counts. Fowler flap mechanisms also protrude externally under the wings, requiring external fairings, which increase cruise drag. Simple-hinged flaps are less complex, and an ideal choice for low-drag cruise efficiency. However, simple-hinged flaps require high flap deflections to achieve lift comparable to Fowler flaps. These flap deflections cause severe adverse pressure gradients, which generate flow separation that is difficult to control. In response to these challenges, NASA developed the High Efficiency Low Power (HELP) active flow control (AFC) system. This simple, elegant invention can control flow separation resulting from the high flap deflections required by simple-hinged flap systems \u2013 making such flaps a viable option for aircraft designers. Aircraft with simple-hinged flap systems will achieve reduced cruise drag, thereby increased fuel efficiency.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_359","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-359","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-359","confidence":"high"},"type":"patent","title":"In-Space Assembly of Structural Trusses and Shapes","abstract":"NASA engineers have developed an innovative method for simple design and modular assembly of curved, double-curved, or flat structures in space or on earth or lunar surfaces. The approach is expected to have greatest utility in structures ranging from a few meters to 100\u2019s of meters. Most current space structures are launched as a single monolithic or deployable unit and are thus limited by the mass and volume constraints. In-space assembly of modular components delivered from one or more launches is an alternative approach. However, curved structures typically are separated into many unique components which greatly complicates manufacturing and assembly. This novel technology introduces a new design that localizes the differences between truss modules to a small, easily fabricated connector. Thus, the majority of the module, even for curved surfaces, can be standardized to simplify fabrication, testing, and subsequent assembly at the destination.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_374","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-374","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-374","confidence":"high"},"type":"patent","title":"Improving VTOL Proprotor Stability","abstract":"Vertical take-off and landing (VTOL) aircraft such as tiltrotors hold the promise to provide the next generation of air transport but are limited in their forward airspeeds due to complex, coupled rotor and wing dynamic instabilities. NASA Langley\u2019s Advanced Generalized Predictive Control (AGPC) technology provides swashplate actuators with high-frequency control signals to stabilize dynamic instabilities allowing envelope expansion and to reduce vibration anywhere in the envelope. Compared to existing Generalized Predictive Control (GPC) systems, AGPC is self-adaptive and compares actual system behavior with that predicted by experimentally-derived system identification parameters. This methodology is unique in that modeling parameters are updated by observation of the operational controller and requires no or negligible excitation of the system in order for the adaptation to be successful.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_116","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-116","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-116","confidence":"high"},"type":"patent","title":"Seal with Integrated Shroud to Protect from Exposure to Extreme Environments","abstract":"Innovators at NASA's Glenn Research Center have designed a superior seal assembly that is durable and highly dependable in extremely harsh environments. This fault-tolerant design features a novel protective shroud that shields its interior seal element(s) from hazardous conditions that can quickly degrade the seal material and cause higher leak rates. The thin and flexible shroud is able to retract to expose the seal element(s) when the shroud comes into contact with the desired mating surface, ensuring a tight, leak-proof interface. When it is time to break the seal, the process reverses itself, and the shroud arms return to their extended position to cover and protect the seal element(s). Sheltering the seal element(s) when they are not in use extends the lifetime of the seal and lessens the need for expensive and inconvenient maintenance and repairs. Originally designed to protect seals from atomic oxygen, ultraviolet radiation, and impacts from debris in space, these seals are an ideal solution for a variety of industrial and chemical applications that operate in hazardous conditions.","category":"mechanical_systems","categoryRaw":"mechanical and fluid systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_122","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-122","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-122","confidence":"high"},"type":"patent","title":"Shape Memory Alloy Rock Splitters (SMARS)","abstract":"NASA's Glenn Research Center have developed a groundbreaking method for using shape memory alloys (SMAs) to split apart rock formations without explosives or hydraulics. Conventional approaches present difficulties in transportation and operation and can badly damage underlying samples during use. Glenns innovation exploits cutting-edge SMA compositions to deliver controllable stresses in excess of 1500 megapascals (MPa), which is up to four times greater than the force exerted by commercial equiatomic SMAs. The SMA compositions are also tunable to multiple activation temperatures up to 400&deg;C, depending on the usage environments. Glenns Shape Memory Alloy Rock Splitters (SMARS) device generates this power without any demolition damage to the surrounding environment, and in a package that combines reliability, ease of setup and activation, and cost-effectiveness. This technology could prove invaluable to enterprises as varied as oil drilling, mining, civil engineering, fossil collection, and search-and-rescue operations - any field that requires compact, but large, static forces.","category":"mechanical_systems","categoryRaw":"mechanical and fluid systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_129","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-129","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-129","confidence":"high"},"type":"patent","title":"NiTi Alloy Ball Bearings","abstract":"Innovators at NASA's Glenn Research Center have developed a new method for making small diameter, high-grade Nickel Titanium (NiTi) ball bearings that set a new standard for precision performance in the bearing field. Using non-corrosive NiTi alloy instead of steel is an inexpensive way to increase the load capability and reduce the weight of a ball bearing. It has been difficult, however, to produce balls less than 0.375\" in diameter using the standard baseline 60NiTi alloy. To address this challenge, Glenn innovators have created a new, more advanced alloy consisting of NiTi and Hafnium (Hf) that can produce high-quality ball bearings of any size, but most notably less than 0.25\" in diameter. Glenn's NiTi-Hf ball bearings are superior to any previously used alloy or steel. They are corrosion-resistant, shockproof, and have been rated at a grade 10 or higher on the Annular Bearing Engineering Committee (ABEC) scale (an industry-accepted tolerance standard for bearings). Thanks to their high strength and Rockwell hardness (HRC 58-60), these customizable ball bearings will facilitate new high-speed precision applications in a broad range of industries, including aerospace , automotive, industrial, medical, and more.","category":"mechanical_systems","categoryRaw":"mechanical and fluid systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_135","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-135","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-135","confidence":"high"},"type":"patent","title":"Shape Memory Alloy Mechanisms for CubeSats","abstract":"Innovators at NASA's Glenn Research Center have developed lightweight and reliable mechanisms based on shape memory alloys (SMAs) for small satellites, such as CubeSats. SMAs have a unique ability to effect a reversible phase transformation, so that they can withstand being severely deformed and recovered repeatedly. Glenn's innovation, flown in a successful space mission, uses SMA components in actuators and hinging elements to improve retention, release, and deployment of crucial structures, such as solar arrays. Compared to standard devices, the SMA-based mechanisms are much smaller and lighter, do not produce debris, and require minimal power to operate, meeting the rigorous power budget for CubeSats. These SMA-based components are a key breakthrough for CubeSats and other small satellites, where their small size and weight, reusability, and reliability are mission critical. In addition, these mechanisms can be scaled up, so their benefits can be realized in larger spacecraft as well.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_138","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-138","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-138","confidence":"high"},"type":"patent","title":"Continuous Fiber Composite for Use in Gears","abstract":"Innovators at NASA's Glenn Research Center have developed a breakthrough means of adapting strong but lightweight carbon fiber composite material to fabricate structures of complex shape, such as specialized components for drive systems. Conventional methods of using discontinuous fiber composites for forming complex shapes can produce defects, including a tendency toward weakness and fatigue at the cut ends of the fibers. Glenn's novel technology instead uses multiple layers of formable continuous fiber composite material, eliminating the cut ends that form a potential site for failure, as well as filler materials between plies. Using this method, manufacturers can provide the optimum shape of the continuous plies and thus of the structure as a whole. The structure can then meet high specific strength and high cycle fatigue resistance requirements for rotorcraft gears and other applications, including aircraft, power generation such as wind turbine systems, unmanned vehicles, and urban air mobility (UAM). Glenn's innovation brings the advantages of carbon fiber composites to a broad range of new uses.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_153","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-153","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-153","confidence":"high"},"type":"patent","title":"Shape Memory Alloy (SMA)-Enabled Actuators","abstract":"Researchers at NASA Glenn pioneered and matured SMAs to enable future aircraft with morphing airfoil surfaces and adaptive wings that fold to respond to different flight condition demands. SMAs are functional metals with unique properties that can go through solid-state phase transformations&#8212stretched, bent, heated, cooled&#8212and recover their original shape. NASA now has two novel mechanical actuators with SMA transmission elements to move parts with rotational angular twisting, delivering the same power as traditional actuators but in a lightweight, smaller footprint form factor. The new rotary actuator and ring drive actuator move in response to external stimuli, such as heating. The rotary actuator uses nested tubes of SMA to provide torque output or angular displacement; the ring drive actuator uses SMA tubes in a drive gear element to provide continual rotary output in either clockwise or counterclockwise directions. Despite the smaller footprint, the SMA tubes achieve higher power density and similar power output to larger actuators, enabling new designs based on compact actuators.","category":"mechanical_systems","categoryRaw":"mechanical and fluid systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_161","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-161","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-161","confidence":"high"},"type":"patent","title":"Shape Memory Alloy Tubular Structure","abstract":"Innovators at NASA's Glenn Research Center (GRC) have developed a next-generation, non-pneumatic, compliant tire structure based on shape memory alloy (SMA) elements. This new structure builds upon previous work related to airless tires that were designed for rovers used in planetary exploration. The use of SMAs capable of undergoing high strain as load bearing components results in a tubular structure that can withstand excessive deformation without permanent damage. These structures are capable of performing similarly to traditional pneumatic tires but with no risk of puncture or loss of tire pressure. The new technology is an extension of previous nonpneumatic metal-mesh tire designs developed at GRC, but with a structural pattern that improves manufacturability and offers design flexibility for customization. The innovation has been prototyped for use as a bicycle tire, but this SMA structure can be used in a wide range of applications including, off-road vehicles, aircraft landing gear, military ground vehicles, agricultural machinery, seals, and energy absorbers.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_170","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-170","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-170","confidence":"high"},"type":"patent","title":"High-Speed Droplet Generator","abstract":"Current methods for generating water droplets often require a tradeoff between droplet size and velocity. Small, atomized droplets can be accelerated to high speeds, while larger droplets tend to move slowly. This technology offers the best of both worlds: generating relatively large water droplets (up to 100 micrometer diameter) at high velocity (up to 115 m/s). The droplet generator was developed at NASA Glenn Research Center to provide a reliable way to evaluate icing effects and water's impact on aerospace components during flight tests and wind tunnel studies. By precisely controlling droplet size and speed, the technology ensures repeatable water droplet impact conditions for sensor calibration and materials testing. For icing studies, this technology solves challenges related to splashing, pooling, and other challenges that can impact the accuracy of hot wire anemometer probes. And unlike other sprayers which either atomize droplets or fail to achieve high velocity with large droplets, this novel design propels intact, well-defined droplets for more controlled experiments. With tunable parameters and a narrow spray area, the droplet generator may be valuable to aerospace research technology developers and various other fluid spray applications.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_97","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-97","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-97","confidence":"high"},"type":"patent","title":"High-Temperature Single Crystal Preloader","abstract":"Many aerospace vehicles require thermal barriers/seals to minimize the flow of hot gases through interfaces in thermal protection systems and propulsion systems where temperatures can exceed 1200&deg;F. One of the primary challenges is maintaining proper sealing contact at elevated temperatures. To address this challenge, preloading elements in various spring-like forms are often incorporated into or behind a seal to provide the required resiliency. At these elevated temperatures, conventional spring preloaders made from polycrystalline alloys lose strength and can exhibit excessive creep, resulting in a loss of sealing contact. Glenn innovators have developed new processes to enable the fabrication of preloaders made of single crystal superalloys that can increase the upper limit of thermal seals to greater than 2000&deg;F for short to moderate term applications, and greater than 1800&deg;F for long term applications. These preloaders can be manufactured in a variety of configurations allowing stiffness to be customized for a particular application.","category":"mechanical_systems","categoryRaw":"mechanical and fluid systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_99","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-99","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-99","confidence":"high"},"type":"patent","title":"Superelastic Tire","abstract":"Innovators at NASA's Glenn Research center have developed a game changing, non-pneumatic, compliant tire. This innovation, called the Superelastic Tire, was developed for future Moon and Mars missions, but is a viable alternative to pneumatic tires here on Earth. This technology represents the latest evolution of the Spring Tire which was invented by NASA Glenn and Goodyear, and inspired by the Apollo lunar tires. The novel use of shape memory alloys capable of undergoing high strain as load bearing components, instead of typical elastic materials, results in a tire that can withstand excessive deformation without permanent damage. Using shape memory alloy as radial stiffening elements can also increase the load carrying capacity of the tire. The Superelastic Tire offers traction equal or superior to conventional pneumatic tires and eliminates both the possibility of puncture failures and running &#34;under-inflated&#34;, thereby improving automobile fuel efficiency and safety. Also, this tire design does not require an inner frame which both simplifies and lightens the tire/wheel assembly.","category":"mechanical_systems","categoryRaw":"mechanical and fluid systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_100","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-100","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-100","confidence":"high"},"type":"patent","title":"Debris-Tolerant Valve","abstract":"Innovators at NASA's Marshall Space Flight Center (MSFC) have developed a Debris-Tolerant Valve designed for use in machines/environments with a large quantity of airborne dust or other contaminants. The invention was created for an atmospheric revitalization system on the International Space Station. On the ISS, the use of dried pelletized media in the system caused a problem with the collection of contaminants in the existing selector valve, requiring persistent valve maintenance and replacement. NASA's Debris-Tolerant Valve was offered as a solution and is currently being developed for use in future NASA missions. The new valve implements a novel design that has been extensively tested and offers substantial benefits including extended lifetime of internal valve parts, ease of maintenance, and low-cost manufacturability. Applications for the Debris-Tolerant Valve include use in aerospace or industrial processes.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_101","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-101","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-101","confidence":"high"},"type":"patent","title":"Magnetically Damped Check Valve","abstract":"Innovators at NASA's Marshall Space Flight Center (MSFC) have developed a Magnetically Damped Check Valve for eliminating chatter in passive valve systems. At low flow rates, passive valves often chatter (i.e., slightly open and shut at some frequency). Check valves, for example, are designed for full-flow conditions but oftentimes experience much lower flow levels. Over time, this chatter mechanism can degrade if not destroy a valve and/or the overall system. Valve experts have employed other damping solutions over time to minimize chatter, but such attempts would only work under certain flow conditions. NASA's Magnetically Damped Check Valve eliminated chatter under all flow conditions tested. The invention is applicable to check valves, but could also benefit other systems using passive valves.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_104","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-104","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-104","confidence":"high"},"type":"patent","title":"3D-Printed Injector for Cryogenic Fluid Management","abstract":"Innovators at the Marshall Space Flight Center have developed a system to minimize boil-off during cryogen transfer and storage using an additive manufactured injector with an augmented thermodynamic venting system (TVS). Cryogenic fluid transfer is important for both ground and space-based systems and typically requires venting of a receiver vessel during the chill and fill process to maintain a pressure favorable to fluid flow. NASA's TVS Augmented Injector offers an alternative system that gradually cools the inside of receiving tanks, improving cryogenic fluid transfer and storage efficiency and minimizing or eliminating the time the receiver tank vent needs to be open. The injector is a small piece of 3D-printed hardware that can be easily used with or integrated into tanks or filling equipment in any space or industrial application where a cryogenic fluid is being transferred. The injector may also be employed for long-term cryogenic fluid storage as a means of controlling tank pressure if integrated with a recirculation pump.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_106","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-106","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-106","confidence":"high"},"type":"patent","title":"Periodic Wave Disc Brake Rotor","abstract":"Developed by innovators at the NASA Marshall Space Flight Center, the Periodic Wave Disc Brake Rotor offers improved performance for potential applications in racings cars, motorcycles, and in particular for electric vehicles (EVs) equipped with regenerative braking systems. NASA's periodic wave rotor technology is a suite of rotor designs that provides dramatic weight reduction along with high heat dissipation, two of the primary challenges associated with high performance braking systems. Increasing any vehicle's racing performance involves decreasing the rotational moment of inertia and brake-system weight, which allow the vehicle to accelerate faster, change direction better, and require less energy when doing all of the above. For racing cars, reducing braking system weight is all about achieving better lap times. For any popular EVs, however, decreased electrical energy expenditure provides increased travel range. NASA's Periodic Wave Disc Brake Rotor can be easily implemented into any existing vehicles with either hub-mounted or wheel rim-mounted brake systems.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_109","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-109","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-109","confidence":"high"},"type":"patent","title":"Tension Element Damping (TED) \u2013 With Hydraulics for Large Displacements","abstract":"NASA engineers developed a new approach to mitigating unwanted structural vibrations that cause maintenance issues and compromise the performance and safety of large, tall structures. NASAs method is fundamentally different from conventional passive and active vibration damping methods used today. TED uses disruptive modal coupling between two different structures, each with their own vibrational behavior, to provide vibration damping for one or both of the structures. This novel reactive vibration damping method uses feedback from the vibrational displacement itself, such as the tension and compression cycles from the movement of the vibrating structure (like a wind turbine or tower), to disrupt the vibration. Line tension is provided by either hydraulic, pneumatic, or magnetic means to suit the application and the size/ displacement of the vibration. Compared to conventional spring dampers, TED devices are simple in design, lightweight , very effective, and have a smaller footprint.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_111","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-111","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-111","confidence":"high"},"type":"patent","title":"Integral Tuned Mass Absorber for Turbine Blades","abstract":"NASA\u2019s Marshall Space Flight Center has developed a novel turbine blade design and manufacturing approach that provides a significant reduction in turbine blade resonant vibration. In particular this innovation addresses the unique resonance vibration challenges of conventionally machined turbine bladed-discs, or blisks. The design approach includes an internal blade tuned mass absorber structure that can be placed at optimal location where deflection is greatest. Additive manufacturing is used to make this unique structure. Prototypes have demonstrated a 50% reduction in resonant vibration. Importantly, the innovation also enables improved predictive modelling of the resonant behavior of new blisk designs because the tuned-mass absorber acts as a linear system. In contrast, modelling of conventional blade dampers is extremely complex and therefore requires an expensive iterative test program dedicated to validation of the damper design.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_116","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-116","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-116","confidence":"high"},"type":"patent","title":"Self-aligning Poppet","abstract":"As NASA plans for manned missions to Mars, efforts are being made to identify technologies that must be improved to make such trips feasible. Valves have been identified as one technology in need of improvement \u2013 on the voyage to Mars, propellants and other stored materials will leak through seals in the lines, tanks, and valves. For example, traditional valve technologies are projected to result in a loss of 17 tons of hydrogen during a 6-year manned trip to Mars. Thus, to make a Mars mission (or other long duration manned space missions) feasible, cryogenic valve leakage rates must be reduced by several orders of magnitude. After identifying this need, engineers at NASA\u2019s Marshall Space Flight Center set out to develop a solution. The result is NASA\u2019s self-aligning poppet for low leakage valves \u2013 a seat alignment technology that eliminates the need to precisely control interfaces between poppet sealing surfaces and the valve seat seal. Instead, the seat and poppet self-align, ensuring the poppet is always centered, parallel to the seat, and perpendicular to the actuator line of action. Testing has shown that NASA\u2019s self-aligning poppet reduces leakage in aerospace cryogenic valves by three orders of magnitude.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_122","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-122","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-122","confidence":"high"},"type":"patent","title":"Miniature Separable Fill & Drain Valve","abstract":"Innovators at the NASA Marshall Space Flight Center have developed the Miniature Separable Fill & Drain Valve, a manually operated, two-part valve design for CubeSat propulsion applications. Miniature propulsion systems have been an area of significant investment over recent years as rising CubeSat and SmallSat adoption has precipitated the desire to increase the utility of such spacecraft. However, miniature propulsion systems require components that are much smaller than commonly available in industry. Due to specialized requirements for sensitivity to mass and volume as well as compatibility with the fluids used in CubeSat propulsion systems, the Miniature Separable Fill & Drain Valve was developed. This new valve design allows loading and draining of fluid while minimizing the flown component size and weight, having applications in CubeSat and miniature spacecraft propulsion systems. The valve design is also scalable, and thus may be suitable for terrestrial applications including industrial processing.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_124","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-124","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-124","confidence":"high"},"type":"patent","title":"Ocean Platform Motion Control","abstract":"NASA engineers have developed a new approach to mitigating unwanted motion in floating structures. Ideally suited to applications including offshore wind energy platforms and barges, the innovation uses water ballast as a motion damping fluid. Various designs have been developed to suit a number of different configurations depending on the specific applications. To date, target applications have included floating offshore wind energy platforms and service barges. Prototypes have been developed and tested as part of DOE\u2019s ATLANTIS floating offshore wind energy development program and have demonstrated highly effective control of the platform motion induced by wind and wave action. This innovation builds upon extensive expertise of the NASA innovators in developing novel vibration and motion damping control methods for various NASA large-scale structural applications.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_125","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-125","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-125","confidence":"high"},"type":"patent","title":"Tension Element Vibration Damping","abstract":"NASA engineers have developed a new approach to mitigating unwanted structural vibrations. NASA's method is fundamentally different from conventional passive and active vibration damping methods widely used today. Tension Element Vibration Damping uses disruptive modal coupling between two structures, each with their own vibrational behavior, to proactively provide vibration damping for one or both of the structures. This novel vibration damping method reacts to, and uses the vibrational tensile/compressive displacement itself to disrupt the vibration. Resistance to the displacement force is provided by either hydraulic, pneumatic, or magnetic means to suit the target application and the size/displacement of the vibration. Compared to conventional vibration passive and active damping methods, Tension Element Vibration Damping systems are simple in design, lightweight, highly effective, and adaptable to a range of applications with different structure sizes and types of vibration.","category":"mechanical_systems","categoryRaw":"mechanical and fluid systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_133","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-133","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-133","confidence":"high"},"type":"patent","title":"Adaptive Camera Assembly","abstract":"During the Apollo missions, lightly modified off-the-shelf cameras were used by astronauts to take imagery while performing extravehicular activities (EVAs). These cameras were cumbersome to operate in spacesuits that limit body mobility and pressurized gloves that limit finger dexterity and strength, making it difficult to interact with small camera buttons. Additionally, on the lunar surface, several environmental factors pose risks to continued camera operations (e.g., extreme temperatures, intrusive lunar regolith, radiation effects, vacuum conditions, etc.). To address these challenges, NASA has developed an adaptive camera assembly designed to enable astronauts dawning spacesuits to easily control all functions of a Nikon Z9 camera. Not only does this NASA invention address human factors considerations (i.e., ease-of-use), but also functions as an environmental protection system, defending the camera against the effects of extreme environments. NASA\u2019s adaptive camera assembly may provide advantages for terrestrial photography and videography applications involving hazardous environments where thick gloves and other thermal protective equipment are required (e.g., industrial foundries, Arctic/Antarctic research, welding, etc.). Additionally, the camera assembly may enable individuals with disabilities or health conditions that limit hand control to participate in photography.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_135","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-135","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-135","confidence":"high"},"type":"patent","title":"Modified Tuned Liquid Column Damper","abstract":"Tuned liquid column dampers (TLCDs) are widely used for vibration suppression, yet their application to floating wind turbine systems presents unique challenges due to the strict geometric constraints of offshore platforms. Achieving the desired frequency, damping, and stiffness is often difficult within the limited space available, as these parameters are highly dependent on the TLCD\u2019s column length, cross-sectional area, and fluid properties. This geometric limitation restricts flexibility in tuning the device to match the turbine\u2019s dynamic response. To address these limitations, researchers at NASA\u2019s Marshall Space Flight Center have developed the Modified Tuned Liquid Column Damper (MTLCD). By adding valves, orifices, or pressurization, TLCDs can be modified to optimize parameters such as stiffness and frequency without altering their geometry. The MTLCD builds on this capability, enabling tailored vibration suppression and providing a versatile solution for enhancing the stability and performance of floating wind turbine systems.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_136","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-136","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-136","confidence":"high"},"type":"patent","title":"Magnetically Damped Check Valve","abstract":"Passive valves are essential components in fluid systems, enabling flow control without external actuation. Among these, check valves are a widely used type of passive valve that allows fluid to flow in one direction while preventing reverse flow. They are commonly found in aerospace propulsion systems, industrial processing lines, and energy infrastructure. A major operational issue with check valves is chatter \u2013 a rapid, repeated opening and closing oscillation of the valve when the pressure differential across it is insufficient to fully open the valve. Traditional check valves are often underdamped, making them prone to chatter, or overdamped, which can hinder responsiveness and efficiency. Neither approach fully resolves the issue across varying flow conditions. To address this challenge, NASA\u2019s Marshall Space Flight Center has developed the Magnetic Critically Damped Check Valve, a novel passive valve design that uses magnetic damping to eliminate chatter and improve reliability across a wide range of operating conditions.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_2","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-2","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-2","confidence":"high"},"type":"patent","title":"Fluid Structure Coupling Technology","abstract":"NASA's Marshall Space Flight Center's Fluid Structure Coupling (FSC) technology is a highly efficient and passive method to control the way fluids and structures communicate and dictate the behavior of a system. This technology has the demonstrated potential to mitigate a multitude of different types of vibration issues and can be applied anywhere where internal or external fluids interact with physical structures. For example, in a multistory building, water from a rooftop tank or swimming pool could be used to mitigate seismic or wind-induced vibration by simply adding an FSC device that controls the way the building engages the water.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_65","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-65","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-65","confidence":"high"},"type":"patent","title":"Variable-Aperture Reciprocating Reed (VARR) Valve","abstract":"Engineers at NASA's Marshall Space Flight Center have developed a new reed valve for controlling fluid flow back and forth between two chambers. The VARR valve provides two-way flow that is proportional to flow demand. As the pressure gradient builds on one side, the reed valve responds by opening an amount that is proportionate to the gradient, or demand, allowing bidirectional flow. Some mechanical and fluid systems that rely on the controlled flow of fluids between chambers will benefit from the new design. Compared to current fixed orifice devices, VARR may expand the performance envelope by offering a more continuous flow response in applications in which the pressure environment is constantly changing. Proportional two-way flow can enable a fine-tuned system response to pressure building on one side of the valve. In these changing gradient conditions, the reed valve is better than fixed-sized orifices, which are optimized for one flow condition and are likely to over- or under-restrict flow for all other flow gradients.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_71","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-71","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-71","confidence":"high"},"type":"patent","title":"Low-Cost, Long-Lasting Valve Seal","abstract":"NASA Marshall Space Flight Center has developed a new, simplified method for installing valve seats, eliminating the need for a swaged assembly process and the additional hardware and equipment that are typically found in conventional, elastomeric valve seat installations. In addition to weight reduction, the fewer hardware components reduce the number of potential failure modes. This simplified technique saves time and installation costs, and results in comparable leakage protection by minimizing acute stress in the seal material. NASA has used the installation technique on gas-fed, pulsed, electric thrusters for propellants, which requires very specific fluid flow operation by quickly opening and closing the valves within short durations of time. The NASA technique is especially advantageous for small instrumentation valves where precise fluid control is essential.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_79","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-79","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-79","confidence":"high"},"type":"patent","title":"Pilot Assisted Check Valve for Low Pressure Applications","abstract":"Inventors at NASA have developed an advanced check valve with a pressure sensing design that allows the valve to crack open at low pressure differentials while still providing the required sealing stress on the valve seat at all pressures below cracking pressure. The design of the valve also allows it to maintain sealing stress on the seat regardless of downstream pressure. In low pressure conditions of 100 psi or less, sealing issues often occur when a low cracking pressure is desired. Alternative check valves are unable to provide the required sealing stress on the valve seat. This results in seat damage and eventual leak issues due to the rotation of internal parts relative to the seat. This valve provides a solution to low pressure applications with stringent leak requirements.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_91","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-91","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-91","confidence":"high"},"type":"patent","title":"Fluid-Filled Frequency-Tunable Mass Damper","abstract":"Innovators at the Marshall Space Flight Center (MSFC) have developed a fluids-based tunable mass damper system that allows for significant distribution of loads while also providing a simple mechanism that allows for the capability to change its frequency of mitigation with negligible impact on the damper system. For existing fluid filled pipes, ducts, ballast tanks, etc., the fluid can now be leveraged to provide vibration mitigation. This new technology enables structural engineers to set and change the fundamental mitigation attributes of the mass damper system with little to no modification of the fluid container.","category":"mechanical_systems","categoryRaw":"mechanical and fluid systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_94","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-94","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-94","confidence":"high"},"type":"patent","title":"Cryogenic Hydraulically Actuated Isolation Valve","abstract":"Researchers at NASA's Marshall Space Flight Center have developed a cryogenic isolation valve that utilizes the upstream line pressure of cryogenic fluids for actuation. Previously, the use of cryogenic fluids for actuation systems had been too difficult to control and resulted in unsafe operating conditions due to the cryogenic fluid used for actuation being separated from the main body of the valve. Once separated, the cryogenic fluid would heat too quickly and vaporize, resulting in high, volatile pressures. To avoid these issues, cryogenic fluid had historically been controlled and redirected using either electromechanical or pneumatic actuation systems. By using the upstream line pressure of the cryogenic fluid for actuation, NASA's cryogenic isolation valve eliminates the need for the complex support systems that are necessary with electromechanical and pneumatic actuation systems.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_96","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-96","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-96","confidence":"high"},"type":"patent","title":"Reverse Vortex Ring (RVR)","abstract":"Innovators at the Marshall Space Flight Center (MSFC) have developed a mechanism for improving rotordynamic stability and response in turbomachinery. The Reverse Vortex Ring (RVR) invention was created specifically to solve instability problems with turbopumps on the Space Shuttle main engine, which has been a persistent problem for NASA engineers since the 1970s. With the advent of rotating machinery, high-speed rotors have been of interest to engineers. Rotating machinery has been employed in a wide range of applications in the past century, ranging from steam turbines for electric power generation to the turbo pumps used in the Space Shuttle Main Engines. As these machines have become more commonplace, there has been an increased demand for lightweight, compact designs. The required power output of these units has also increased leading to ever high power to weight ratios. These leaner designs are the hallmark of the aerospace industry.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_107","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-107","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-107","confidence":"high"},"type":"patent","title":"Handheld Metal Tube Straightener","abstract":"Researchers at NASA Johnson Space Center have developed the Handheld Metal Tube Straightener designed to remove bends within 3.5 inches of a tube end. The tool straightens thin, malleable 4mm metal tubes like those used for fuel, pneumatic or hydraulic pressurized lines. Commercially available tube straighteners use rollers to straighten long metal tubing, but the spacing of the rollers typically prevent or complicate bend-removal near the end of the tube and can also leave linear scratches on the straightened area. The handheld tube straightener can remove small and large bends near and at the tip of a tube so that it can be swaged into any commercial swage fitting. The Handheld Metal Tube Straightener was successfully used during a spacewalk on NASA's \"EVA 61 Alpha Magnetic Spectrometer (AMS)\" repair mission.","category":"mechanical_systems","categoryRaw":"mechanical and fluid systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_109","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-109","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-109","confidence":"high"},"type":"patent","title":"Multi-Link Spherical Joint","abstract":"Innovators at NASA Johnson Space Center have designed a spherical joint which allows up to six linearly actuated links or attachments to rotate about a co-located center. Originally designed to provide joint flexibility necessary for a variable geometry truss system, the new spherical joint also allows power and data lines to pass through it without the lines being subjected to structural forces. This technology can be key for creating a deployable, variable geometry truss system, with a compact form factor that can reduce payload volume within the confines of a launch or other transport vehicle. Typically, flexible truss systems rely on joints where each of the links do not rotate around the same point, creating instability in the joints and the entire structure. The Multi-Link Spherical Joint removes those instabilities, allowing for a durable and adaptable technology with multiple space and terrestrial applications.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_125","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-125","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-125","confidence":"high"},"type":"patent","title":"Ball Valve Assembly Yields Linear Flowrate Control","abstract":"Innovators at NASA Johnson Space Center have developed an adjustable thermal control ball valve (TCBV) assembly which utilizes a unique geometric ball valve design to facilitate precise thermal control within a spacesuit. The technology meters the coolant flow going to the cooling and ventilation garment, worn by an astronaut in the next generation space suit, that expels waste heat during extra vehicular activities (EVAs) or spacewalks. In testing, the TCBV demonstrated solutions to shortcomings of previous thermal control valve iterations such as internal leakage, valve mechanism sticking, and lack of linear flowrate control. The technology could have multiple commercial applications where precise fluid flow control is desired. Examples may be in food and beverage processing, water and chemical treatment, petroleum, energy, manufacturing, and medical industries. The thermal control ball valve has a technology readiness level (TRL) 5 (component and/or breadboard validation in relevant environment) and is now available for patent licensing. Please note that NASA does not manufacture products itself for commercial sale.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_138","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-138","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-138","confidence":"high"},"type":"patent","title":"Passive Fuel Cell Surface Power System (PaCeSS)","abstract":"NASA Johnson Space Center is developing a passive thermal management cooling system for a fuel cell. The cooling system uses a radiator comprising a shape memory alloy (SMA) actuator, and a thermosyphon-based system for heat transport that can eliminate the need of moving parts. Relying upon partial gravity for operation, the innovation, called \u201cPaCeSS\u201d for short, is highly promising for power generation and storage in lunar and planetary surface operations, and may be compelling for terrestrial industries interested in passive thermal management. Current fuel cells require active thermal management components such as pumps to push liquid coolant through a fuel cell stack and electronic control valves to operate radiator panels. These components have moving parts presenting several disadvantages: they limit the operational lifetime and reliability of a fuel cell system, and are a source of parasitic power draw because they consume energy from the fuel cell stack to power their operations. PaCeSS could eliminate the wear-and-tear of moving parts and reduce complexity associated with fuel cell system thermal management. It is a system-level solution that spans heat acquisition, heat transport, and heat rejection by incorporating a two-phase thermosyphon for passively removing heat from a fuel cell stack through a transport path. It then uses an SMA mechanism to actuate a radiator panel that can vary the heat rejection rate into space.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_139","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-139","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-139","confidence":"high"},"type":"patent","title":"ARC ANGEL Reduces Gravity\u2019s Effect on Arms","abstract":"Innovators at NASA Johnson Space Center (JSC) have developed an earthbound robotic training system called \u201cARGOS\u201d for short. It can actively simulate an astronaut\u2019s weightlessness in space by using an overhead runway and bridge drive system to partially or fully offload their weight using attached cables, effectively suspending them off the ground. Although the test subject\u2019s torso and legs are offloaded, their arms and any weighty hand tools are not. Enter \u201cARC ANGEL\u201d. The Actuated Realtime Control for ARGOS Nega-tion of Gravitational Effects on the Limbs (ARC ANGEL) technology was developed to offload a space suited test subject\u2019s arms and counteract fatigue realized while performing training activities using ARGOS. Like ARGOS, ARC ANGEL provides offloading via computer-controlled active cable tension. Cables are strung between arm cuffs located just above each elbow, and a motorized reel(s) mounted to the spacesuit\u2019s backpack-like Primary Life Support System (PLSS). This active offloading technology could be used for a number of appli-cations in addition to simulating zero to one G environments. For exam-ple, a patient rehabilitating their shoulder could benefit from movement assistance that offloads arm weight or grasp load, a construction worker carrying a heavy tool could more easily manipulate it, or it could offset equipment weight for military personnel ultimately staving off limb fatigue that would otherwise occur.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_60","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-60","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-60","confidence":"high"},"type":"patent","title":"Full-Size Reduced Gravity Simulator For Humans, Robots, and Test Objects","abstract":"To train astronauts to live and work in the weightless environment on the International Space Station, NASA employs a number of techniques and facilities that simulate microgravity. Engineers at the NASA Johnson Space Center (JSC) have developed a new system called the Active Response Gravity Offload System (ARGOS) that provides a simulated reduced gravity environment within a confined interior volume for astronauts to move about and/or equipment to be moved about as if they were in a different gravity field. Each astronaut/item is connected to an overhead crane system that senses their actions (walking or jumping, for example) and then lifts, moves, and descends them as if they had performed the action in a specified reduced gravity. This NASA Technology is available for your company to license and develop into a commercial product. NASA does not manufacture products for commercial sale.","category":"mechanical_systems","categoryRaw":"mechanical and fluid systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_84","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-84","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-84","confidence":"high"},"type":"patent","title":"Liquid Sorbent Carbon Dioxide Removal System","abstract":"Innovators at the NASA Johnson Space Center (JSC), in collaboration with Jacobs Technology, and IRPI, have developed a reliable, efficient, and cost-effective carbon dioxide (CO2) removal and dehumidification system. The new system is designed for ventilation applications and utilizes a gentle, passive, and direct air/liquid contactor. The contactor is composed of a bifurcating manifold with 3D printed corrugated walls, that contain capillary channels onto which thin films of liquid sorbent are deployed. The liquid is held in place by surface tension and capillary forces. As the liquid is exposed to the air, it absorbs carbon dioxide and humidity from the environment. NASA's new CO2 removal system has significant advantages over current CO2 scrubbers. For example, the new system eliminates the need for large blowers and compressors that force air at high velocities through adsorption-based systems using solid sorbents.","category":"mechanical_systems","categoryRaw":"mechanical and fluid systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ssc_tops_10","source":{"institution":"NASA","subUnit":"Stennis Space Center","subUnitCode":"SSC","nativeId":"SSC-TOPS-10","sourceUrl":"https://technology.nasa.gov/patent/SSC-TOPS-10","confidence":"high"},"type":"patent","title":"Supersonic Spike Diffuser","abstract":"Standard cylindrical and second-throat diffusers allow supersonic gas flows to expand within their walls and pull a vacuum on any upstream void. However, the high-Mach-number shock reflections that occur in the center of the plume create substantial losses and result in an inefficient pumping process. Centerbody diffuser designs provide an improvement by reducing the maximum Mach number of the core flow, but also increase the number of oblique shocks in the system by introducing multiple turns into the system. A new type of spike diffuser recently developed by NASA Stennis Space Center is able to provide approximately double the pumping performance of second-throat diffusers via Pareto-efficient reduction of both core Mach number and flow deflection. This enables substantially lower vacuum pressures to be achieved for a given feed pressure/mass flow via the use of higher-expansion-ratio driving nozzles. Spike diffusers are also spatially compact, requiring only ~25% of the length of second-throat designs","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ssc_tops_2","source":{"institution":"NASA","subUnit":"Stennis Space Center","subUnitCode":"SSC","nativeId":"SSC-TOPS-2","sourceUrl":"https://technology.nasa.gov/patent/SSC-TOPS-2","confidence":"high"},"type":"patent","title":"Floating Piston Valve","abstract":"The valve developed consists of a solid piston floating in a medium to control the flow stream. The piston is designed to be axially and radially balanced within the flow stream whether the valve is in the open or closed position. The only force imparted onto the piston is that which the operator chooses to input on to it. The advantages to this design are (1) the elimination of a conventional actuator, which is replaced by one or two simple solenoid valves; (2) elimination of valve actuator adjustments; (3) consistent seating force regardless of the pressure drop across the valve; (4) elimination of the valve stem and stem seals; and (5) elimination of most flow induced thrust forces. Additionally, the valve consists of only five parts with a few simple seals incorporated into a well protected design. The simple design allows for use in nominal or extremely high pressures and for the use of soft or hard metal seats; this valve design reduces downtime and maintenance costs, while increasing valve reliability and seat life.","category":"mechanical_systems","categoryRaw":"mechanical and fluid systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ssc_tops_9","source":{"institution":"NASA","subUnit":"Stennis Space Center","subUnitCode":"SSC","nativeId":"SSC-TOPS-9","sourceUrl":"https://technology.nasa.gov/patent/SSC-TOPS-9","confidence":"high"},"type":"patent","title":"Cryogenic Cam Butterfly Valve","abstract":"Typical butterfly valves cannot seal at both ambient and cryogenic temperatures. At cryogenic temperatures, valves grow and shrink, changing critical dimensions such as distance between the disc and seat. Ideally, valves would compensate. The inability of existing butterfly valves to do this triggered the innovative design of the Cryogenic Cam Butterfly Valve (CCBV). The CCBV is designed so that the disc rides on a cam shaft and is held rigid by a torsion spring, which provides both axial movement of the disc in addition to the standard 90 degree rotation of a standard butterfly valve. Because the valves disc can rotate and translate, it can hold a tighter seal, preventing leakage despite dimensional changes caused by changing operating temperatures. The novel concept enables functional advantages similar to a globe valve. The CCBV enables low leakage at both ambient and cryogenic temperatures. Compared to competing valves, it is a simpler design which results in reduced manufacturing and maintenance costs.","category":"mechanical_systems","categoryRaw":"mechanical and fluid systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_302","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-302","sourceUrl":"https://technology.nasa.gov/patent/TOP2-302","confidence":"high"},"type":"patent","title":"Extractor for Chemical Analysis of Lipid Biomarkers in Regolith (ExCALiBR)","abstract":"Lipids are organic molecules used by all life on Earth, primarily for building membranes that encompass cells. The analysis of lipid biomarkers has gained increasing importance within environmental and archaeological fields because biomarkers are representative of particular plant and animal sources. Proven \u201cgold standard\u201d laboratory techniques for lipid biomarker extraction are laborious, with many opportunities for human error. As a solution, NASA Ames Research Center has developed a novel technology that provides an autonomous, miniaturized fluidic system for lipid analysis. The technology, in a single instrument , can accept an unprocessed soil, rock, or ice sample, comminute the sample, extract lipids via sonication and blending, filter out mineral residue, concentrate the analyte, and deliver the aliquot to downstream analytical instruments for molecular characterization, without requiring intervention from a human operator.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_309","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-309","sourceUrl":"https://technology.nasa.gov/patent/TOP2-309","confidence":"high"},"type":"patent","title":"Microfluidics Pressure-Based Switching and Valving Array","abstract":"Traditionally, laboratory operations in fields such as molecular biology and organic chemistry have required \u201chumans in the loop,\u201d a major inefficiency source and bottleneck for automation. Many lab-on-a-chip devices are designed to perform specific tasks, and do not offer programmable movement of microfluidic-well contents or application-specific reconfigurability. NASA Ames\u2019 researchers have developed a novel method that acts as a microfluidic switch array, determining flow paths using specific logic states achieved through the application of different combinations of pressure and flow conditions to specified valves. This technology facilitates automation of complex laboratory techniques by enabling the programming of any number of sequences by which the contents of microfluidic wells are automatically transferred to specified neighboring chambers, in ways not possible with earlier NASA automated microfluidics technologies.","category":"mechanical_systems","categoryRaw":"Mechanical and Fluid Systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_316","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-316","sourceUrl":"https://technology.nasa.gov/patent/TOP2-316","confidence":"high"},"type":"patent","title":"Additively Manufactured Oscillating Heat Pipe for High Performance Cooling in High Temperature Applications","abstract":"High performance cooling techniques for enhanced heat transfer for high temperature applications are increasingly important, particularly in the field of aerospace engineering. For example, leading edges of wings on hypersonic vehicles may reach upwards of 2000 C, and such heat quickly degrades the leading edge. Conventional heat pipes contain bends or welds in the material that can compromise the structural integrity of the wing leading edge. Oscillating Heat Pipes (OHPs) are a newer form of heat pipe which can cool more efficiently than traditional heat pipes, and are easier to manufacture. NASA Ames Research Center has developed a novel additive manufacturing technique to manufacture OHPs from Refractory High Entropy Alloys (RHEAs). These OHPs are effective in hypersonic vehicles with sharp, shape-stable wing leading edges. Additive manufacturing allows for enhancements such as alternating-diameter channels, allowing for changes in pressure.","category":"mechanical_systems","categoryRaw":"mechanical and fluid systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_drc_tops_0","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-TOPS-0","sourceUrl":"https://technology.nasa.gov/patent/DRC-TOPS-0","confidence":"high"},"type":"patent","title":"Compact, Temperature-Tuned OFDR Laser","abstract":"Fiber optic sensing systems (FOSS) have advantages over conventional sensors including lighter weight, smaller size, improved reliability, and higher accuracy. To date, wavelength division multiplexing (WDM) has perhaps been the most popular fiber optic sensing method. Drawbacks of WDM exist, however, including the importance of fiber Bragg grating (FBG) sensor locations, need for each sensor to have a unique wavelength, and limited number of sensors that can occupy any one data channel (~10). As a result, NASA has focused on OFDR, an alternative FBG interrogation technique based on laser interferometry. OFDR provides advantages over WDM, most notably higher spatial density (up to 1000 FBGs can be multiplexed into a single fiber), and reduced cost per sensor. During development of an OFDR-based FOSS system, cost and performance-based limitations of traditional excitation sources led NASA to develop a novel, wavelength-swept, solid-state laser tailored to this application.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_drc_tops_16","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-TOPS-16","sourceUrl":"https://technology.nasa.gov/patent/DRC-TOPS-16","confidence":"high"},"type":"patent","title":"Streamlined Liquid Level Sensing Using Fiber Optics","abstract":"Innovators at NASA's Armstrong Flight Research Center have developed a highly accurate method for measuring liquid levels and other tank gauging applications using optical fibers. Unlike liquid level gauges currently on the market that rely on discrete measurements to give broad approximations of liquid levels, Armstrong's innovative fiber optic method provides precise and accurate measurements. Specifically, Armstrong's novel method is capable of providing measurements at 1/4-inch intervals within a tank. This significant leap forward in precision and accuracy in liquid level sensing offers significant benefits to many industries. Originally designed by NASA to monitor a rocket's cryogenic fuel levels, this technology&#8212;part of NASA's patented fiber optic sensing system (FOSS)&#8212;can be used in many tank gauging applications.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_drc_tops_17","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-TOPS-17","sourceUrl":"https://technology.nasa.gov/patent/DRC-TOPS-17","confidence":"high"},"type":"patent","title":"Sensing Magnetic Fields","abstract":"Innovators at NASA's Armstrong Flight Research Center have developed an optical waveguide fiber Bragg grating (FBG) that is sensitive to an external magnetic field. The technology allows direct coupling of the external field to the electromagnetic (EM) wave propagating in the fiber, bypassing the need to first measure strain. The properties of the waveguide material are directly and incontrovertibly influenced when exposed to an external field. In contrast to other FBG-based methods that detect external fields via a mechanical change (e.g., magnetostriction-induced strain), this innovation uses ferromagnetic nanoparticles to achieve a direct coupling of the external field to the optical behavior of the fiber. Thus, the technology can be used as a sensor to detect and map magnetic fields. Alternately, a known magnetic field can be applied to create a particular optical transmission behavior in the waveguide, thus creating an optical switch or selective filter.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_drc_tops_24","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-TOPS-24","sourceUrl":"https://technology.nasa.gov/patent/DRC-TOPS-24","confidence":"high"},"type":"patent","title":"Shape Sensing Innovations Dramatically Improve Structural Design Tools","abstract":"Advances in fiber optic shape sensing developed at NASA's Armstrong Flight Research Center are enabling the development of next-generation flexible aircraft wings that maximize structural efficiency and reduce weight, improving fuel efficiency. These same advances will help engineers design stronger bridges, buildings, ocean vessels, and more. Fast algorithms use distributed fiber optic wavelength data to determine shape deformation of large curved and flexible structures. Dramatically improving upon earlier two- and three-dimensional (2D and 3D) shape-sensing tools by tracking multiple orientation angles&#8212;displacement, twist, and rotation&#8212;at the same time, Armstrong's technology converts distributed surface strain data into deformed shapes that can be displayed and analyzed in real time. Developed to help NASA researchers characterize complex test articles and design new aerospace structures, the innovations also will be useful for multiple applications in the transportation, infrastructure, and medical industries.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_drc_tops_25","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-TOPS-25","sourceUrl":"https://technology.nasa.gov/patent/DRC-TOPS-25","confidence":"high"},"type":"patent","title":"Enhanced Fabrication Improves Temperature Sensing in Cryogenic Humid Environments","abstract":"Researchers at NASA's Armstrong Flight Research Center have developed a new manufacturing process that improves the ability of fiber optic sensing systems to measure temperature and liquid levels when operating in humid environments. The process involves eliminating moisture from the optical fiber coating, then completing the sensor assembly within humidity-controlled conditions. The resulting sensor hardware provides precise and accurate measurements even when operating in a humid environment. Originally designed to monitor a rocket's cryogenic fuel levels in conjunction with NASA's patented Fiber Optic Sensing System (FOSS), this technology can be used in many industrial, food, and medical applications.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_drc_tops_26","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-TOPS-26","sourceUrl":"https://technology.nasa.gov/patent/DRC-TOPS-26","confidence":"high"},"type":"patent","title":"Adaptive Spatial Resolution Enables Focused Fiber Optic Sensing","abstract":"This advanced fiber optic sensing innovation developed at NASA's Armstrong Flight Research Center offers a unique combination of high-resolution processing and flexibility. The algorithm was originally developed to enhance Armstrong's multi-patented Fiber Optic Sensing System (FOSS). With over 2,000 sensors per fiber, FOSS enables thousands of high-resolution measurements at once, including strain, shape, temperature, pressure, and more. The new adaptive spatial resolution innovation allows users to specify resolution and accuracy requirements. By making it possible to optimize data transmission bandwidth and adjust processing to minimize extraneous computations, this technology effectively provides the right resolution in the right place at the right time. This new capability opens up myriad new applications for fiber optic sensing systems, including in civil engineering, transportation, oil and gas, medical, aerospace , and many more industries.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_drc_tops_37","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-TOPS-37","sourceUrl":"https://technology.nasa.gov/patent/DRC-TOPS-37","confidence":"high"},"type":"patent","title":"Fiber Optic Sensing Technologies","abstract":"NASA's Armstrong Flight Research Center is offering companies that provide sensing solutions for monitoring of structures and asset management of storage tanks a unique opportunity to expand their product line to include unprecedented capabilities. Known as FOSS (for fiber optic sensing system), NASA's patented, award-winning technology portfolio combines advanced sensors and innovative algorithms into a robust package that accurately and cost-effectively monitors a host of critical parameters in real time. These include position/deformation (displacement, twist, rotation), stiffness (bending, torsion, vibration), operational loads (bending moments, shear loads, torques), strength/stress (pressure/fatigue, breakage prediction), and magnetic fields (cracks or other flaws in safety-critical metal structures) for structural health monitoring applications. In addition to monitoring the structure of a tank, FOSS is capable of sensing the tank's inventory, including amounts, temperatures, and stratification (oil vs. water, sediment vs. liquid, thermal layers).","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_drc_tops_42","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-TOPS-42","sourceUrl":"https://technology.nasa.gov/patent/DRC-TOPS-42","confidence":"high"},"type":"patent","title":"Gateway Integrates Wireless Sensors with Existing Aircraft Systems at \"the Speed of Software\"","abstract":"Innovators at NASA's Armstrong Flight Research Center have found a way to incorporate wireless sensor technology in aerospace vehicles without adding the complexity and tonnage normally associated with physically modifying existing avionics. The solution: A single universal wireless access point or \"gateway\" that can communicate between existing onboard systems and any subscribed wireless device. This gateway can be easily reprogrammed to communicate with any wireless device, allowing engineers to add new sensing technology \"at the speed of software.\" Furthermore, this gateway approach means that once a wireless sensor has been tested on a research vehicle or platform, it can be immediately integrated into other vehicles outfitted with the gateway. The gateway's architecture also holds promise for other industries seeking ways to capitalize on the advantages of wireless sensors.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_drc_tops_9","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-TOPS-9","sourceUrl":"https://technology.nasa.gov/patent/DRC-TOPS-9","confidence":"high"},"type":"patent","title":"Lightweight Fiber Optic Sensors for Real-Time Monitoring of Structural Health","abstract":"Innovators at NASA's Armstrong Flight Research Center have developed a lightweight, robust fiber optic sensing system (FOSS) that represents a major breakthrough in sensing technology. The sensors, along with NASA's sophisticated algorithms, can be used to calculate a variety of critical parameters including shape, stress, temperature, pressure, strength, and operational load. This state-of-the-art sensor system is small, lightweight, easy to install, and fast&#8212;it processes information at rates of 100 times per second. For the first time ever, real-time strain measurements can be used to determine the shape of an aircraft's wing, monitor the structural integrity of bridges and pipelines, or ensure precise placement of the tiniest catheters, to name just a few potential applications.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_126","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-126","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-126","confidence":"high"},"type":"patent","title":"Miniaturized Laser Heterodyne Radiometer","abstract":"NASA Goddard Space Flight Center has developed a passive monitor for measuring greenhouse gases in the atmosphere including carbon dioxide, methane and carbon monoxide. Further, trace gas concentrations can be correlated with altitude, providing further delineation of composition. This is an autonomous instrument with a uniquely small footprint and is about the size of carry-on luggage.","category":"environment_climate","categoryRaw":"environment","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_138","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-138","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-138","confidence":"high"},"type":"patent","title":"CubeSat Compatible High Resolution Thermal Infrared Imager","abstract":"The CubeSat Compatible High Resolution Thermal Infrared Imager is a technology with multiple applications. It can be flown on an aircraft , deployed on the International Space Station, launched on a ride-share as an entirely self-contained 3U CubeSat, flown on a small satellite, or be a co-manifested satellite instrument.","category":"environment_climate","categoryRaw":"environment","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_194","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-194","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-194","confidence":"high"},"type":"patent","title":"On-demand, Dynamic Reconfigurable Broadcast Technology for Space Laser Communication","abstract":"Space optical networks are slated to become the dominant form of communication due to their high data rates, customizable configurations, and signal coverage. To make these networks feasible, issues to be overcome include the large coverage angles, dynamic nature of desired orbits for coverage, data losses through optical beam sizes, and unnecessary illumination of large spaces absent satellite presences.","category":"imaging_optics","categoryRaw":"optics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_196","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-196","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-196","confidence":"high"},"type":"patent","title":"Self-Phase-Locked Distributed Gain Laser Architecture","abstract":"While both high power and high efficiency laser sources are desired for many applications, limitations on their development and use include power scaling among the many gain materials due to excessive optical intensity. Moreover, as power among many gain elements can be increased, combining the power efficiency has thusfar proven elusive.","category":"imaging_optics","categoryRaw":"optics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_199","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-199","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-199","confidence":"high"},"type":"patent","title":"Micro non-planar ring oscillator (micro-NPRO","abstract":"Previous non-planar ring oscillator (NPRO) designs have stability issues in terms of frequency, polarization, beam quality, mode choice, and output power due to the fact that the non-linear cavity design length prevents avoidance of spatial hole burning. Furthermore, large NPRO crystals are susceptible optical loss and not compatible with opto-mechanical parts and electro-optics developed for standard diode lasers.","category":"imaging_optics","categoryRaw":"optics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_212","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-212","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-212","confidence":"high"},"type":"patent","title":"Kodiak 3D Lidar","abstract":"High orbit satellite servicing and planetary science missions are presented with unique challenges, including a harsh environment and long mission life, coupled with the need for long range and high speed and accurate measurements. Conventional systems suffer from high costs of bringing other solutions to market and questionable reliability.","category":"imaging_optics","categoryRaw":"optics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_22","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-22","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-22","confidence":"high"},"type":"patent","title":"Digital Beamforming Interferometry","abstract":"Synthetic Aperture Radar (SAR) is a sophisticated form of radar that implements a single antenna to successfully scan a target area, store the received signals, and coherently process the signals to resolve elements in an image of the target area. Interferometric SAR (InSAR) uses two or more SAR images to generate three dimensional maps of surface deformation or digital elevation using phase difference information. InSAR is commonly implemented with SAR systems in a repeat pass platform configuration where two SAR images are generated during each of the passes, and an interferogram between the two images provides the desired \"height\" measurement, or in a single pass configuration where the SAR system uses two separate antennas are used to generate the interferogram. NASA Goddard Space Flight Center has developed a new approach that uses a single phased array antenna and a single pass configuration to generate interferograms.","category":"imaging_optics","categoryRaw":"optics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_223","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-223","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-223","confidence":"high"},"type":"patent","title":"Space Weather Database Of Notifications, Knowledge, Information (DONKI)","abstract":"Currently there is no central database for space weather researchers and forecasters to ascertain observed space weather events. Instead, data is being recorded by scientists in a blog. However, this information is not easily searchable. This innovation is a database where weather events are entered and linkages, relationships, and cause-and-effects between various space weather events are recorded.","category":"environment_climate","categoryRaw":"environment","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_234","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-234","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-234","confidence":"high"},"type":"patent","title":"Miniaturized Astrometric Alignment Sensor","abstract":"Miniature satellites, sometimes called CubeSats, are mainly used for space research. These satellites are employed to demonstrate spacecraft technologies intended for small satellites or that present questionable feasibility and are unlikely to justify the cost of a larger satellite. Scientific experiments with unproven underlying theory may also find themselves aboard because their low cost can justify higher risks. There is a need for space-qualified pointing and alignment stellar sensor hardware. Alignment sensors can be used for virtual telescope demonstrations and other satellite experiments in heliophysics. Ultimately, dual spacecraft space telescopes capable of imaging solar flares in the x-ray band, high energy UV solar imaging, and gamma-ray imaging of galactic cores of stellar systems require alignment sensors to some degree. The Miniaturized Astrometric Alignment Sensor advances alignment stellar sensor hardware.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_243","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-243","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-243","confidence":"high"},"type":"patent","title":"SpaceCube v2.0 Processor with DDR2 Memory Upgrade","abstract":"The DDR SDRAM memory dies that had been radiation tested and flight qualified have reached end of life. The remaining stock of DDR SDRAM is rapidly dwindling and future projects will require a change to DDR2 SDRAM. Additionally, the next generation of instruments are set to produce even greater amounts of science data and require even more memory bandwidth for on-board processing. Switching to DDR2 improves support for new instruments because it can provide more than a 2x memory speedup over the DDR1 design.","category":"sensors_instruments","categoryRaw":"instrumentation","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_256","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-256","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-256","confidence":"high"},"type":"patent","title":"A Broadband, Compact Low-Power microwave Radiometer Down Converter for Small Satellite Applications","abstract":"CubeRRT (CubeSat Radiometer Radio Frequency Interface Technology) is designed for remote earth sensing. The CubeRRT payload has three critical pieces of technology, a wideband antenna unit, a radiometer front-end (RFE) unit, and a radiometer digital back-end (RDB). In order to accommodate these components, Goddard innovated the CubeRRT (CubeSat Radiometer Radio Frequency radiometer) to be compact and operate at a low-power.","category":"sensors_instruments","categoryRaw":"instrumentation","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_51","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-51","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-51","confidence":"high"},"type":"patent","title":"Miniaturized High-Speed Modulated X-Ray Source (MXS)","abstract":"This miniaturized X-ray source can be modulated in intensity from completely off to full intensity, over 100 keV, in subnanosecond timescales. The high speed switching capability and miniature size make possible many new technologies including X-ray-based communication, compact time resolved X-ray diffraction, novel X-ray fluorescence instruments, low precise dose medical X-rays, and more.","category":"imaging_optics","categoryRaw":"optics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_73","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-73","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-73","confidence":"high"},"type":"patent","title":"Passive Porous Tube Nutrient Delivery System","abstract":"A primary challenge to growing plants in microgravity is the delivery of adequate air, water and nutrients to a plant's roots. Microgravity alters convection and thus the behavior of root zone aeration which plants are evolutionarily reliant upon to grow. Current nutrient delivery techniques proposed for space involve the use of a medium for the roots to penetrate, such as arcilite, and power or frequent astronaut intervention is typically required to actively pump water to the roots. When water is actively pumped to the roots, the user must carefully calibrate the amount of water and nutrients being pumped in order to prevent over- or under watering that could inhibit plant growth. The current watering technique on the International Space Station using the Vegetable Production System (Veggie) frequently requires astronauts to manually pump water into the pillows with a syringe to sustain the plants.","category":"biomedical_health","categoryRaw":"Health Medicine and Biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_74","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-74","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-74","confidence":"high"},"type":"patent","title":"Flexible Body Control Using Fiber Optic Sensors (FlexFOS)","abstract":"NASA Kennedy Space Center seeks partners interested in the commercial application of the Flexible Body Control Using Fiber Optic Sensors (FlexFLOS) technology. The FlexFOS measures flexible dynamic state through a reference strain structure (RSS) combined with fiber optic strain sensors (FOSS). This new system for strain measurement provides users with an exponential increase in the amount of dynamic data, affording end users with a more precise and accurate assessment of critical structural dynamics. When combined with an inertial measurement sensor, FlexFOS enables end users to separate out the rigid body and flexible body components of the total motion. KSC is now seeking commercial partners for licensing or further development of this novel sensor system.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_94","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-94","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-94","confidence":"high"},"type":"patent","title":"Plasma Processing of Water and Inedible Biomass for pH Control and Nutrient Recycling","abstract":"Researchers at Kennedy Space Center have developed a technology that generates plasma activated water in pH ranges that allow for the addition of nitrates and other nutrients to the water while maintaining a healthy pH for plants. A plasma torch is used to treat inedible biomass, generating ash containing nutrients useful for plant growth. The same plasma torch is also used to treat water, which results in the formation of nitric acid that lowers the pH of the water. Adding the plasma generated ash to the plasma treated water can balance the pH of the water to make it suitable for plant growth while simultaneously adding nutrients recycled from the inedible biomass to further enhance plant development. Plasma treatment of water to high and low pH extremes can also be used for sanitation purposes, causing pH shock to undesired organisms. The uniqueness of this process is the adjustability of the pH with one system. The same plasma system can be used to treat both the water and the biomass. Additionally, the technology can be used as an on-demand, point-of-use method for producing nitric acid.","category":"biomedical_health","categoryRaw":"Health Medicine and Biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_95","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-95","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-95","confidence":"high"},"type":"patent","title":"Cryogenic Oxygen Storage Modules COSM","abstract":"NASA Kennedy Space Center engineers developed a Cryogenic Oxygen Storage Module (COSM) to store oxygen in solid-state form and deliver it as a gas to an end-use environmental control and/or life support system. Additionally, the COSM can scrub out nuisance or containment gases such as carbon dioxide and/or water vapor in conjunction with supplying oxygen, forming a synergistic system when used in a closed-loop application. Closed-loop life support systems require both oxygen supply and removal of toxic or nuisance gases such as CO2 from the breathing loop. In most deployed systems, these two requirements are accomplished independently. COSM combines these capabilities to work simultaneously which may allow for reduced system volume, mass, complexity and cost of a rebreathing device.","category":"biomedical_health","categoryRaw":"Health Medicine and Biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_106","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-106","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-106","confidence":"high"},"type":"patent","title":"Infrasound Sensor Technology","abstract":"NASA Langley Research Center scientists have developed a microphone that detects infrasound, i.e., acoustic waves ranging from 20 Hz frequencies down to dc. Infrasound is emitted in a number of hazardous atmospheric phenomena, including aircraft wake vortices, clear air turbulence, and tornadoes. It is also emitted by seismic events, such as underground nuclear tests, digging of tunnels, etc. Infrasound propagates hundreds of miles and can penetrate walls, mountains and other obstacles without loss. The NASA infrasound sensor filters out wind noise that can interfere with detection, while using less power and much less space than currently available solutions. As a result, the NASA infrasound sensor can detect tornadoes and clear air turbulence hundreds of miles away; an array of 30 could cover the entire continental US. Aircraft wake vortices can be detected in real time by microphone arrays placed along an airport runway.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_12","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-12","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-12","confidence":"high"},"type":"patent","title":"Low-Profile Wireless Sensor","abstract":"NASA's Langley Research Center researchers have developed a wireless low-profile sensor that uses a magnetic field response measurement acquisition system to provide power to the sensor and to acquire physical property measurements from it. Unique to this sensor is the shape of the electrical traces that eliminates the need for separate inductance, capacitance, and connection circuitry. This feature gives the sensor a smaller circuit footprint to enable a smaller, flexible, and easy to fabricate sensor package. The shape of the electrical trace can be readily modified to sense different physical properties. Also, arranging multiple low-profile sensors together can permit the wireless data acquisition system to read the responses from all the sensors by powering just one of them.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_123","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-123","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-123","confidence":"high"},"type":"patent","title":"Optical Head-Mounted Display System for Laser Safety Eyewear","abstract":"NASA's Langley Research Center has created a new system that allows a laser operator to safely view a laser beam while using a high-powered laser. Currently, viewing an otherwise invisible laser beam requires cumbersome equipment such as laser viewing cards and video cameras. This system uses an optical head-mounted display integrated with laser safety eyewear to allow an operator to safely see a laser beam in real-time while also providing freedom of movement. The display provides a picture-in-picture, augmented reality, which can include additional information and provide multiple viewing options.","category":"imaging_optics","categoryRaw":"optics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_129","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-129","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-129","confidence":"high"},"type":"patent","title":"Smart Skin for Composite Aircraft","abstract":"NASA's Langley Research Center has developed a sensor technology for structural health monitoring on composite aircraft surfaces. When conventional aircraft are struck by lightning, the result can range from no damage to serious damage that requires extensive repairs that can take the airplane out of service for an extended period of time. The SansEC technology is a proven wireless sensing platform capable of measuring the electrical impedance of physical matter in proximity to the sensor based on a change in its resonance response. The sensor also exhibits a unique characteristic to disperse the lightning strike current to help mitigate lightning damage. In this application, an array of SansEC sensors will cover a selective area of the aircraft surface providing both mitigation and damage sensing.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_13","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-13","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-13","confidence":"high"},"type":"patent","title":"Low Frequency Portable Acoustic Measurement System","abstract":"NASAs Langley Research Center has developed a system to detect and locate atmospheric clear air turbulence (CAT) by means of a ground-based infrasonic array to serve as an early warning system for aircraft . This system could augment existing systems such as pilot reports (PIREPs), airborne lidar, and airborne radar. The NASA system offers a benefit based on the fact that the existing electromagnetic methods lack targets at 30,000-40,000 ft and will not detect CAT. Because CAT and severe storms emit infrasound that propagates over vast distances through the Earths atmosphere, the Langley system offers an excellent early warning opportunity. The system has been able to detect known events - such as detection of the launch of the Space Shuttle in Florida all the way from Virginia.It also has correlated data with NOAAs PIREPs information.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_168","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-168","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-168","confidence":"high"},"type":"patent","title":"Super Resolution 3D Flash LIDAR","abstract":"NASA Langley Research Center has developed 3-D imaging technologies (Flash LIDAR) for real-time terrain mapping and synthetic vision-based navigation. To take advantage of the information inherent in a sequence of 3-D images acquired at video rates, NASA Langley has also developed an embedded image processing algorithm that can simultaneously correct, enhance, and derive relative motion, by processing this image sequence into a high resolution 3-D synthetic image. Traditional scanning LIDAR techniques generate an image frame by raster scanning an image one laser pulse per pixel at a time, whereas Flash LIDAR acquires an image much like an ordinary camera, generating an image using a single laser pulse. The benefits of the Flash LIDAR technique and the corresponding image to image processing enable autonomous vision based guidance and control for robotic systems. The current algorithm offers up to eight times image resolution enhancement and well as a 6 degree of freedom state vector of motion in the image frame.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_186","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-186","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-186","confidence":"high"},"type":"patent","title":"Relaxor Piezoelectric Single Crystal Multilayer Stacks for Energy Harvesting Transducers (RPSEHT)","abstract":"NASA Langley Research Center has developed a system to increase the effective piezoelectric constant and the mechanical energy input to energy harvesting transducers. This results in practical performance advantages including higher mechanical-electrical coupling and conversion efficiencies, and more efficient operation across a range of vibrational frequencies.","category":"energy_power","categoryRaw":"power generation and storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_192","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-192","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-192","confidence":"high"},"type":"patent","title":"SansEC Spectroscopy","abstract":"This innovation builds off of NASA Langley Research Center's SansEC sensing system. SansEC is an open-circuit, resonant sensor that needs no electrical connections (thus the name SansEC or \"without electrical connection\"). This technology combines the SansEC circuit with a magnetic field reader to allow for detection of magnetic or electric field changes to produce a spectroscopy readout.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_193","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-193","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-193","confidence":"high"},"type":"patent","title":"Wireless Temperature Sensor Having No Electrical Connections","abstract":"NASA Langley Research Center has developed a robust, wireless temperature sensor that does not require an electrical connection. The temperature sensor is built on NASA's SansEC sensor platform, which takes advantage of measuring dielectric changes. The temperature sensor is damage tolerant, wireless, flexible, precise, and inexpensive. One promising application is for tire temperature sensors.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_194","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-194","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-194","confidence":"high"},"type":"patent","title":"Electroactive Material for Wound Healing","abstract":"This technology is a device that uses electrical activity to facilitate the wound healing process while protecting the wound. The bandage is made of an electroactive material (pictured above) that is stimulated by the heat of the body and the pressure of cell growth, thus no external power source is required.","category":"biomedical_health","categoryRaw":"health medicine and biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_200","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-200","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-200","confidence":"high"},"type":"patent","title":"Electroactive Scaffold","abstract":"This technology, developed at NASA's Langley Research Center in collaboration with scientists at Duke University, is a novel three-dimensional scaffold structure that utilizes electroactive fibers for tissue and/or stem cell engineering. This invention enables electroactive fibers to be assembled into three-dimensional scaffolds to more closely mimic the native biological environment by providing biochemical, mechanical, and electrical cues.","category":"biomedical_health","categoryRaw":"Health Medicine and Biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_245","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-245","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-245","confidence":"high"},"type":"patent","title":"MMOD Impact Detection and Location","abstract":"Determination of micrometeoroid/orbital debris (MMOD) impact on orbiting spacecraft currently requires visual inspection. For human-rated spacecraft such as the ISS and, previously, the Space Shuttle Orbiter, this has required crew time as well as vehicle assets to identify damage due to MMOD strikes. For unmanned spacecraft, there are no human assets present to conduct detailed surveys to ascertain potential damage. NASAs Langley Research Center has developed a strain-sensing system that can be affixed to a spacecrafts micrometeoroid/orbital debris (MMOD) shielding layer or structure. This technology detects the occurrence, time, location and severity of a MMOD strike on the shield, allowing for detection and location of potentially harmful MMOD strikes on both crewed and unmanned spacecraft. This knowledge is important because prolonged exposure to the on-orbit MMOD environment increases risk to vehicles in this environment including commercial crew vehicles expected to visit and remain for considerable periods of time at ISS.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_248","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-248","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-248","confidence":"high"},"type":"patent","title":"Non-invasive Intracranial Pressure Measurement","abstract":"An acknowledged objective of critical care medicine is a timely, accurate, readily deployable, cost-effective and, importantly, safe means of assessing and/or monitoring critical aspects/parameters of patient condition such as intracranial pressure. However, ICP monitoring is complicated by a large set of variables related to the patients themselves -- presented symptoms, circumstances, and related information indicating such measurement; and relevant accompanying issues. These conditions and the various combinations thereof present attending physicians with the choice of many alternatives regarding key parameters, including but not limited to urgency, availability, appropriability, and accuracy to a minimum standard. Cost, complexity, ease of use and other issues are also meaningful factors, but the bottom line for any of the various technical approaches, whether invasive or non-invasive, is performance. Key to this technology is its capability to correlate closely with established tympanic membrane displacement (TMD) ICP monitoring technology.","category":"biomedical_health","categoryRaw":"health medicine and biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_271","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-271","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-271","confidence":"high"},"type":"patent","title":"Automated Guided Wave System for In-process Cure Monitoring of CFRP Composite Laminates","abstract":"In the polymer composites industry, cure cycles are typically developed from a trial and error or a more effective processing science approach to reduce the final porosity level in the composite laminate. Using an automated system, high-temperature piezoelectric transducers were utilized to interrogate a twenty-four ply unidirectional composite panel fabricated from Hexcel IM7/8552 prepreg during cure. It was shown that the amplitude of the guided wave increased sharply around vitrification and the TOA curve possessed an inverse relationship with degree of cure.","category":"sensors_instruments","categoryRaw":"instrumentation","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_276","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-276","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-276","confidence":"high"},"type":"patent","title":"System for Incorporating Physiological Self-Regulation Challenge into Parcourse/Orienteering Type Games and Simulations","abstract":"NASA Langley engineers have created a software tool that operates on a smartphone and incorporates functions of physiological self-regulation or biofeedback with other gaming, training or simulation activities such as orienteering, parcourse training. The central distinguishing characteristic is the integrating of mobile brainwave and physiological monitoring technology with mobile geolocation technology in a smartphone/tablet computer application for biofeedback training and/or entertainment purposes. It makes biofeedback training fun and stimulating to do thereby enabling mastery of the techniques.","category":"biomedical_health","categoryRaw":"Health Medicine and Biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_278","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-278","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-278","confidence":"high"},"type":"patent","title":"Full Spectrum Infrasonic Stethoscope for Screening Heart, Carotid Artery, and Lung Related Diseases","abstract":"NASA Langley Research Center has developed an infrasonic stethoscope that detects a broader range of physiological conditions than conventional stethoscope, use of which has declined mainly due to availability of other advance technologies such as the echocardiogram. The echocardiograms can be complex, costly and require the need of a specialist for correct interpretation. Further, it is estimated that more than 85% population of the world does not have access to advanced diagnostic tools such as echocardiogram and CT scans. This scope provides additional data to physicians by monitoring signals across full frequency bandwidths that include cardiac, carotid artery, and respiration activities something that is not available in conventional stethoscopes.","category":"biomedical_health","categoryRaw":"Health Medicine and Biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_280","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-280","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-280","confidence":"high"},"type":"patent","title":"Standoff Ultra-Compact Micro-Raman Sensor","abstract":"Traditional micro-Raman systems are capable of performing fine-scale mineralogy; but these are used for in situ analysis. Most of the micro-Raman systems are designed and implemented for dark room operation. Such Raman systems: (1) require sample collection and (2) require shielding of daylight background radiation. With the use of continuous wave (CW) lasers and a non-time gating detection approach, it is also difficult to distinguish the biofluorescence from the mineral luminescence. These limitations will significantly lower the capability of these micro-Raman systems in terms of the variety of samples that can be analyzed.","category":"sensors_instruments","categoryRaw":"instrumentation","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_282","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-282","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-282","confidence":"high"},"type":"patent","title":"Device for Providing Real-Time Rotorcraft Noise Abatement Information","abstract":"Rotorcraft typically operate near the ground throughout the duration of the operation. For this reason, military rotorcraft are vulnerable to acoustic detection and public acceptance of civil rotorcraft is limited by annoyance caused by rotor noise radiation. The purpose of this device is to inform the rotorcraft operator of the acoustic impact of rotor noise radiation so that the flight condition of the vehicle can be changed to reduce and/or redirect rotor noise away from noise sensitive areas.","category":"sensors_instruments","categoryRaw":"instrumentation","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_289","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-289","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-289","confidence":"high"},"type":"patent","title":"Apparatus and Method for Biofeedback Training","abstract":"The technology combines virtual reality (VR) with a real environment . The VR provides sensory feedback. If performance is not optimal, the environment is disruptive. If optimal, the environment is stable / normal. The system is to provide feedback to train for self-regulation (e.g. relax on command) when performing tasks. Brainwave activity modulates augmented reality (AR), then once the action is taken, then VR takes over. Mental training is made objective by physiological measures.","category":"biomedical_health","categoryRaw":"Health Medicine and Biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_294","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-294","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-294","confidence":"high"},"type":"patent","title":"Portable Compact Thermionic Power Cell","abstract":"Ideal power sources for portable equipment ideally should be small, compact, lightweight, and provide continuous power with high power density. Batteries meet all but the continuous power requirement. Radioisotope thermoelectric generators (RTG) meet the continuous power condition but none of the others. However, a compact, thermionic-based cell that converts heat to electricity can meet all the above requirements . A tightly spaced array of nanometer-scale emitter points efficiently converts the heat from Plutonium-238 (238 Pu) into usable electricity. The thermionic cell uses metals with low work-function, not semiconductors, and escapes many of the RTG limitations such as lower carrier concentration and mobility, and the difficult requirement of high electrical and low thermal conductivity. It delivers an estimated 10-20% vs. 7% efficiency for an equivalent-sized, 238Pu-based RTG. Such a power cell would be ideal for remote, hazardous or otherwise isolated applications such as remote sensors/transmitters in severe environments.","category":"energy_power","categoryRaw":"power generation and storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_315","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-315","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-315","confidence":"high"},"type":"patent","title":"Remote, Noninvasive, Cardiac Activity Tracer (RENCAT)","abstract":"NASA Langley Research Center has developed a novel laser vibrometer sensor for monitoring cardiac activities remotely and non-invasively, specifically heart functions of valve/chamber opening and closing cycles (cardiac cycles). The device provides precise magnitude and timing information, noninvasively and away from the heart region without interference by patient garments.","category":"sensors_instruments","categoryRaw":"instrumentation","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_335","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-335","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-335","confidence":"high"},"type":"patent","title":"Multi-Layer Nuclear Thermionic Avalanche Cell","abstract":"Innovators at the NASA Langley Research Center (LaRC) have developed the Multi-Layer Nuclear Thermionic Avalanche Cell (NTAC), a novel electrical generator which transforms nuclear gamma-ray photon energy directly to electric power by liberating intra-band atomic inner shell electrons. The invention consists of several NTAC layers arranged in a radially concentric series separated by a vacuum gap space. A large number of electrons liberated within the emitter material are emitted from the surface, which has a tightly spaced array of nanometer-scale emitter points. Liberated electrons go across the vacuum gap and arrive at the collector to efficiently convert energy derived from radioactive materials into usable electricity. The device provides a compact, reliable, and continuous electrical source with high power density capable of long-life operation without refueling. The Multi-Layer NTAC is based on previous work at NASA LaRC in which a single emitter device captured high energy photons; use of a multilayer structure greatly improves the performance of the electrical generator.","category":"energy_power","categoryRaw":"power generation and storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_348","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-348","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-348","confidence":"high"},"type":"patent","title":"Assembly for Simplified Hi-Res Flow Visualization","abstract":"Researchers at NASAs Langley Research Center have developed a simple, compact, easy-to-use projection focusing schlieren imaging system optical assembly that leverages a light source, a single physical grid element, and polarization optics to enable hi-res flow visualization. The assembly can simply be mounted in front of a camera to enable focusing schlieren imaging capability. The assembly was designed to drastically reduce the complexity and time required to align a focusing schlieren imaging experiment. Conventional focusing schlieren imaging systems and projection-based analogs require cumbersome grid alignment and peripheral resources to function (e.g., separate source and cutoff grids, projectors, specialized software). NASAs system leverages a single physical grid as both the source and cutoff grid, so the system is self-aligned, compact, does not require specialized software, and costs less than other projection-based alternatives.","category":"sensors_instruments","categoryRaw":"instrumentation","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_349","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-349","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-349","confidence":"high"},"type":"patent","title":"Digital Projection Focusing Schlieren System","abstract":"Researchers at NASA have developed a compact LCD-integrated optical assembly that enables a research camera to (simultaneously) collect focusing schlieren and other image-based measurement data (e.g., particle tracking velocimetry (PTV), particle imaging velocimetry (PIV), temperature pr pressure sensitive paint measurements (TSP, PSP), or photogrammetry). The assembly was designed to enhance the capabilities of NASAs patented self-aligned, single grid projection focusing schlieren imaging system described in LAR-TOPS-348, and reduce the complexity and time required to perform multiple image-based measurement experiments. Typically, multiple imaging systems are required to collect focusing schlieren and other image-based measurement data. Additionally, conventional focusing schlieren imaging systems are only sensitive to a single density gradient. NASAs digital single-grid system leverages a programmable LCD as the grid enabling on-the-fly grid adjustments (or grid deactivation) to enable an unprecedented amount of experimental flexibility for image-based measurements.","category":"sensors_instruments","categoryRaw":"instrumentation","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_76","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-76","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-76","confidence":"high"},"type":"patent","title":"Wireless Chemical Sensor","abstract":"NASA's Langley Research Center researchers have developed a wireless, open-circuit SansEC [Sans Electrical Connections] sensor that can detect the presence of chemicals without being in contact with the chemical it is detecting. This unique thin-film sensor is used in conjunction with a chemical reactant that detects the presence of the chemical. Because of the way the sensor operates, the reactant can be separated from the sensor itself and placed in caustic or harsh environments, and can still work to detect the specific chemical it was designed to discern. The ingenuity of the thin-film design with the elimination of all wires, connections, and electronic components enables the sensors to be produced cost-effectively. This is an application of the NASA award-winning SansEC sensor , which is damage resilient and environmentally friendly to manufacture and use. The sensors use a NASA award-winning magnetic field response recorder to provide power to the sensors and to acquire physical property measurements from them.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_77","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-77","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-77","confidence":"high"},"type":"patent","title":"Wireless Sensor for Pharmaceutical Packaging and Monitoring Applications","abstract":"NASA's Langley Research Center researchers have developed a wireless, open-circuit SansEC [Sans Electrical Connections] sensor that can be used for pharmaceutical applications without the need for physical contact. Many attributes of a container can be monitored, such as liquid or powder levels, temperature of contents, and changes caused by spoilage. Tampering can also be detected. The unique design of this thin-film sensor allows many of these properties to be measured with the sensor external to the container/package. Fill levels can be measured without the need to open the container. At the core of the technology is the NASA award-winning SansEC sensor , which is damage resilient and environmentally friendly to manufacture and use. The sensors use a magnetic field response measurement acquisition device to provide power to the sensors and to acquire physical property measurements from them.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_79","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-79","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-79","confidence":"high"},"type":"patent","title":"Highly Accurate Position Detection and Shape Sensing with Fiber Optics","abstract":"NASA's Langley Research Center has demonstrated a patent pending method and apparatus for determining the position, in three dimensions, of any point on an optical fiber. The new method uses low reflectance Fiber Bragg Grating (FBG) strain sensors in a multi-core fiber to determine how any point along that fiber is positioned in space. The characteristics of optical fibers and the FBGs vary with curvature, and by sensing the relative change of FBGs in each of three or more fiber cores, the three-dimensional change in position can be determined. By using this method in monitoring applications where optical fibers can be deployed--such as in structures, medical devices, or robotics--precise deflection, end position, and location can be determined in near real time. This innovative position detection method offers 10 times greater positional accuracy than comparable optical techniques.","category":"sensors_instruments","categoryRaw":"instrumentation","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_83","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-83","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-83","confidence":"high"},"type":"patent","title":"Wireless Electrical Devices Using Floating Electrodes","abstract":"NASA's Langley Research Center researchers have developed a wireless, connection-free, open circuit technology that can be used for developing electrical devices such as sensors that need no physical contact with the properties being measured. At the core of the technology is the SansEC [Sans Electrical Connections] circuit, which is damage resilient and environmentally friendly to manufacture and use. The technology uses a NASA award-winning magnetic field response measurement acquisition device to provide power to the device and, in the case of a sensor application, to acquire physical property measurements from them. This fundamental new approach using open circuits enables applications such as sensors for axial load force, linear displacement, rotation, strain, pressure, torque, and motion sensing, as well as unique designs such as for a wireless keypad or wireless rotational dial, or for energy storage.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_9","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-9","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-9","confidence":"high"},"type":"patent","title":"Damage and Tamper Detection Sensor System","abstract":"NASA's Langley Research Center researchers have developed a wireless, connection-free inductor capacitor sensor system that can be placed on or embedded in materials and structures to monitor for and detect damage. The sensors can also be used to detect package tampering and pilfering. This innovation--SansEC [sans Electrical Connections]--makes sensors more damage resilient and more environmentally friendly to manufacture and use. The sensors use a NASA award-winning magnetic field response measurement acquisition device to provide power to the sensors and to acquire physical property measurements from them. The sensors can be continuously or occasionally monitored to detect cracks, material strain, or impact damage. Damage location can also be readily identified with this system.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_95","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-95","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-95","confidence":"high"},"type":"patent","title":"Laser Linear Frequency Modulation System","abstract":"NASA's Langley Research Center has made a breakthrough improvement in laser frequency modulation. Frequency modulation technology has been used for surface mapping and measurement in sonar, radar, and time-off-light laser technologies for decades. Although adequate, the accuracy of distance measurements made by these technologies can be improved by using a high-frequency triangular-waveform laser instead of a sine waveform or lower frequency radio or microwaves. This new system generates a triangular modulation waveform with improved linearity that makes possible precision laser radar (light detection and ranging [lidar]) for a variety of applications.","category":"imaging_optics","categoryRaw":"optics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_104","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-104","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-104","confidence":"high"},"type":"patent","title":"High-Voltage Power System for Hybrid Electric Aircraft Propulsion","abstract":"Innovators at NASA's Glenn Research Center have developed a variable-frequency, alternating current (AC) power system to enable turbo-electric and hybrid electric propulsion. Glenn's technology uses double-fed electric machines and a high-voltage, variable-frequency power system to significantly decrease (by 85%) the weight of an aircraft's power electronics for turbo-electric propulsion, while still providing high specific power and variable thrust. To provide a safe system, the lightweight electric machines operate at high frequency, allowing fast detection and clearance of faults without requiring switchgear that interrupts the current. This design also reduces the protection system's weight, while improving reliability by minimizing fault energy and collateral damage potential. In addition, the system permits either sub-synchronous or super-synchronous operation relative to throttle position, without having to adjust turbine settings. Glenn's innovative system raises the ceiling for hybrid electric aircraft.","category":"energy_power","categoryRaw":"power generation and storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_110","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-110","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-110","confidence":"high"},"type":"patent","title":"Thermal Management for Aircraft Propulsion Systems","abstract":"Innovators at NASA's Glenn Research Center have developed a lightweight, reliable thermal management system, for both ambient and cryogenic propulsion systems, that increases overall fuel efficiency from 40 to 60 percent. Conventional aircraft propulsion systems struggle to keep high-powered electric motors and electronics cool without resorting to extra mass and complexity that negate the benefits of electric propulsion in aircraft. Glenn's thermal management system uses the normally wasted energy from turbofan propulsion to cool electronics and power equipment. The waste heat produces a high-intensity acoustic wave, created from the temperature gradient between the hot and cold heat exchangers. This acoustic wave energy propagates through thermoacoustic power tubes, where it can be used for component cooling or converted to electric power via a linear alternator. Glenn's system can provide highly efficient electric power to aircraft components while cooling the aircraft's propulsion system without added mass and complexity.","category":"energy_power","categoryRaw":"power generation and storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_112","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-112","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-112","confidence":"high"},"type":"patent","title":"Advanced Hydrogen and Hydrocarbon Gas Sensors","abstract":"Innovators at NASA's Glenn Research Center have developed advanced hydrogen and hydrocarbon gas sensors capable of detecting leaks, monitoring emissions, and providing in situ measurements of gas composition and pressure. These compact, rugged sensors can be used to optimize combustion and lower emissions and are designed to withstand harsh, high temperature environments. Some of the sensors, based on silicon carbide, can operate at 600&deg;C. NASA Glenn is actively seeking industrial partners to develop and apply these cutting-edge sensors cooperatively in new applications.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_114","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-114","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-114","confidence":"high"},"type":"patent","title":"Double-Fed Induction Linear Alternator","abstract":"Innovators at NASA's Glenn Research Center have developed a lightweight, double-fed induction linear alternator capable of highly efficient extreme-environment performance. While traditional linear alternators cannot withstand temperatures of 250&deg;C, this innovation has the ability to operate at 950&deg;C with increased performance and efficiency. The innovation replaces the traditional permanent magnet with a copper electromagnetic Halbach circular array (essentially a 3D printed copper coil). Its simple design also eliminates iron, slip rings, and - because it is fabricated as a single piece - adhesives. As a result, it is easy to maintain, does not require iron flux containment and experiences minimal electromagnetic interference. When used with the double action extremely light thermo-acoustic (DELTA) converter, the engine/alternator system is one-tenth the weight of a traditional system. This economical alternator enables unprecedented performance for high-temperature environments such as aircraft power systems, micro combined heat and power (CHP), and downhole drilling.","category":"energy_power","categoryRaw":"power generation and storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_119","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-119","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-119","confidence":"high"},"type":"patent","title":"Capacitive Pressure Sensor System and Packaging","abstract":"Innovators at NASA's Glenn Research Center have developed a state-of-the-art packaged capacitive pressure sensor system that provides in-situ dynamic data acquisition in harsh operating environments. Designed to monitor jet turbofan engine health, this pressure sensor can be placed directly on the engine for highly accurate, real-time data analysis. Another unique feature of this simply designed system is that it can be fitted with an antenna to transmit data wirelessly. This smart sensing technology has undergone extensive testing in extreme environments and is expected to play a key role in the development of a suite of next-generation maintenance and monitoring systems. This important sensor system and packaging can provide more accurate data, improve performance, and extend the service lifetime of commercial and military aircraft, automotive engines, power plants, and more.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_134","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-134","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-134","confidence":"high"},"type":"patent","title":"Premixed, High-Pressure, Multi-Fuel Burner","abstract":"NASA's Glenn Research Center has developed a novel design for a fully premixed high-pressure burner capable of operating on a variety of gaseous fuels and oxidizers, including hydrogen-air mixtures, with a low pressure drop. The burner provides a rapidly and uniformly mixed fuel-oxidizer mixture that is suitable for use in a fully-premixed combustion regime that has the benefit of low pollutant emissions. Further, it is free from harmful flashback effects, combustion instabilities, and thermal meltdown problems that are normally associated with premixed combustion systems operating at high pressures. This burner can be easily scaled for use in practical low-emissions combustion systems such as stationary power plants or hydrogen-air combustion for vehicles. This technology is also applicable to process gas heaters, chemical processing, process gas afterburners, kiln or furnace burners, utility boiler burners, gas reforming burners, and fuel cell processing burners.","category":"energy_power","categoryRaw":"power generation and storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_140","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-140","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-140","confidence":"high"},"type":"patent","title":"High Efficiency Megawatt Motor","abstract":"Innovators at the NASA Glenn Research Center have designed a High Efficiency Megawatt Motor (HEMM), a wound-field partially superconducting machine. The HEMM implements a combination of superconducting and non-superconducting elements, along with an integrated cryocooler, to achieve some of the benefits of a superconducting motor without the need for an external cryogenic system. This work is sponsored by the NASA Advanced Air Transportation Technologies project and the Hybrid Gas Electric subproject for use as an electrified aircraft propulsion (EAP) system. Electrification of propulsion has the potential to revolutionize the aviation industry by improving fuel efficiency, reducing emissions, and decreasing dependency on carbon-based fuels. While the HEMM is designed for future hybrid electric aircraft, the technology could be broadly applied to transportation markets including electric trains, hybrid cars, and turboelectric ships.","category":"energy_power","categoryRaw":"power generation and storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_143","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-143","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-143","confidence":"high"},"type":"patent","title":"Solar Cell Health Monitoring","abstract":"NASA's Glenn Research Center has developed a method and apparatus for in situ health monitoring of solar cells. The innovation is a novel approach to solar cell monitoring, as it is radiation-hard, consumes few system resources, and uses commercially available components. The system operates at temperatures from -55&deg;C to 225&deg;C, allowing it to reside close to the array in direct sunlight. The circuitry measures solar cell current versus voltage (I-V) curves using relatively inexpensive electronics, a single switchable +28 volt power bus, and two analog-to-digital (A/D) converter channels. A single transistor is used as a variable resistive load across the cell, rather than the large resistor arrays or active current sources normally used to characterize cells. Originally developed for space, the technology can be adapted for use in terrestrial solar power generation systems and other applications.","category":"sensors_instruments","categoryRaw":"instrumentation","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_146","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-146","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-146","confidence":"high"},"type":"patent","title":"Advanced Supercritical Water Oxidation Reactor","abstract":"Innovators at the NASA Glenn Research Center, in conjunction with Case Western Reserve University, have designed the Supercritical Water Oxidation - Flame Piloted Vortex (SCWO-FPV) Reactor. The SCWO-FPV Reactor operates at temperatures and pressures above the thermodynamic critical point of water, enabling organic material to become highly soluble, effectively oxidizing all carbonaceous waste in liquid material introduced into the reactor. NASA's new technology addresses problems that have long plagued SCWO-based systems by implementing an innovative design to limit temperatures on the reactor walls, which minimizes the typical issues of scaling, corrosion, and fouling of heat transfer surfaces. While the SCWO-FPV Reactor is being considered for space exploration missions, it has great potential for a variety of terrestrial applications across many industries, especially for water reclamation, water treatment, and waste destruction in liquid waste streams.","category":"environment_climate","categoryRaw":"environment","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_16","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-16","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-16","confidence":"high"},"type":"patent","title":"Portable Unit for Metabolic Analysis (PUMA)","abstract":"NASA's Glenn Research Center has developed the Portable Unit for Metabolic Analysis (PUMA) to provide highly precise real-time measurements of human metabolic functions. PUMA is a battery-powered, wearable device that measures concentrations of carbon dioxide and oxygen in inhaled and exhaled breath as well as heart rate, temperature, gas pressure, and inhalation and exhalation airflow rates. The device relays data wirelessly to a laptop computer for real-time analysis. Because the technology is packaged into a compact and wearable unit and can be used anywhere, a multitude of applications are possible, from ensuring the health and safety of astronauts, pilots, divers, and miners to monitoring patients with pulmonary disease and evaluating fitness levels of soldiers and athletes.","category":"biomedical_health","categoryRaw":"health medicine and biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_19","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-19","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-19","confidence":"high"},"type":"patent","title":"Multi-Parameter Aerosol Scattering Sensor","abstract":"Innovators at NASA's Glenn Research Center have developed the Multi-Parameter Aerosol Scattering Sensor (MPASS), an aerosol-detection system that characterizes atmospheric particles, enabling real-time environmental monitoring often critical for public safety. This optical sensor is superior to the present state-of-the-art in its ability to characterize virtually any particle, as small as nanometer-scale, without the need for calibration against a known aerosol. The universal sensor has the unique ability to measure total particle surface area and mass as well as particle count within the same system. Not only can the MPASS function as an independent portable sensor to quantify inaccessible conditions such as volcanic activity and wildfires through remote monitoring, it can also function as part of a sensor network within a factory or other facility for air quality and fire detection. Lightweight and compact, the unit is ideal for surveillance missions when integrated onto a drone or other unmanned aerial vehicle (UAV), or as a personal health monitoring device for first responders and public safety professionals.","category":"sensors_instruments","categoryRaw":"instrumentation","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_23","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-23","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-23","confidence":"high"},"type":"patent","title":"Fuel Cell Power Management","abstract":"An innovation from NASA's Glenn Research Center increases the efficiency and versatility of fuel cell stacks for power generation. When there is a large increase in the power demand from a fuel cell system, the voltage of the fuel cell system decreases, sometimes below the lowest acceptable threshold. To meet the requirements of a fuel cell system, engineers have typically added direct-current-to-direct-current (DC-to-DC) converters that boost the voltage produced at the ends of the fuel cell stack or added additional fuel cell systems to manage the increased power demand. However, adding DC-to-DC converters or additional fuel cell systems increases cost, reduces efficiency, and adds both mass and volume. NASA's innovative technique features multiple power points that connect different numbers of cells in an electrical series to a device connected to the fuel cell system, allowing the fuel cell system to maintain the desired voltage to the device under very large electrical power demand changes. This capability eliminates DC-to-DC converter electronics, thereby reducing cost and simplifying the system.","category":"energy_power","categoryRaw":"power generation and storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_50","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-50","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-50","confidence":"high"},"type":"patent","title":"High-Efficiency Solar Cell","abstract":"Innovators at NASA's Glenn Research Center have developed a high-efficiency multi-junction solar cell that uses a thin interlayer of selenium as the bonding material between wafers. Selenium is a unique semiconductor in that its transparent to light at photon energies below the band gap (infrared), enabling light to pass from the multi-junction top cell to the silicon-based bottom cell. The innovation allows a multi-junction solar cell to be developed without the constraint of lattice matching, and with a low-cost, robust silicon wafer as the supporting bottom substrate and bottom cell. This approach enables a cell that is simultaneously lower in cost, more rugged, and more efficient than existing space-based photovoltaic cells. This high-efficiency solar technology takes advantage of inexpensive silicon wafers and provides a more robust design for next-generation solar cells in space. For terrestrial applications, it can provide unprecedented efficiencies for auxiliary power units in vehicles, solar roof tiles, power plants, and smart grid systems.","category":"energy_power","categoryRaw":"power generation and storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_76","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-76","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-76","confidence":"high"},"type":"patent","title":"Data Transfer for Multiple Sensor Networks","abstract":"At extreme temperatures, few electronic components are available to support intelligent data transfer over a common, linear combining medium such as wire or the airwaves. NASA Glenn's innovation allows the operating frequency of a sensor instrument to be time variant because the sensor is part of the frequency generator's transfer function. Each instrument associated with a sensor imparts a unique (orthogonal) signature onto the continuous output of that sensor. As a consequence, the outputs of numerous instruments may be simultaneously superimposed upon one another via a linear combining medium and then be separated at a common receiving node in a more temperate location using any number of linear source separation techniques. A listening node, using various techniques, can pick out the signal from a single sender, if it has unique qualities; e.g., a \"voice.\" This technique is analogous to the human brain recognizing and following a single conversation in a party full of people talking and other distracting noises.","category":"sensors_instruments","categoryRaw":"instrumentation","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_78","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-78","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-78","confidence":"high"},"type":"patent","title":"Inexpensive Microsensor Fabrication Process","abstract":"Innovators at NASA's Glenn Research Center have developed a simple method of fabricating novel microsensors in large quantities using nanostructures as templates. Existing nanostructures, such as carbon nanotubes or biological structures, have excellent potential for use in sensor systems but lack certain advantages, including the ability to operate at high temperatures. Glenn's novel technique enables the advantageous properties of nanostructures to be combined with more durable materials , such as metal or metal oxides. In this way, the sensor gets the best of both worlds - the nanostructure offers a larger surface area for sensing, and the metal oxide provides durability and high-temperature capability. By fabricating chemical sensors with nanostructured materials at their core, Glenn has made it possible to develop compact, uniquely tailored sensor systems with significantly improved capabilities. These advanced microsensors can be used in a wide variety of critical applications, including fire detection, gas detection, environmental monitoring, and health monitoring.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_79","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-79","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-79","confidence":"high"},"type":"patent","title":"Polymer Electrolyte-Based Ambient Temperature Oxygen Microsensor","abstract":"Innovators at NASA's Glenn Research Center have developed an ambient temperature oxygen microsensor that can be used in fuel-leak and fire-detection applications. Because the technology detects oxygen levels from 7-21% in nitrogen, it also enables environmental and personal health monitoring. Many existing ambient temperature oxygen sensors are optically based, hard to miniaturize, and involve large, complicated, and costly instrumentation. By contrast, the Glenn microsensor is small, simple to batch-fabricate, consumes little power, and operates in a wide humidity range. Originally developed for extravehicular activity for monitoring oxygen in spacesuits, Glenn's novel design is based on a Nafion tm polymer electrolyte and manufactured using state-of-the-art thin-film technologies. It combines an innovative use of metal oxide as a reference electrode with a unique sensor design that enables miniaturization and flexibility, for a multitude of personal health monitoring and environmental applications.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_82","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-82","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-82","confidence":"high"},"type":"patent","title":"Subcutaneous Structure Imager","abstract":"Scientists at NASA's Glenn Research Center have successfully developed a novel subcutaneous structure imager for locating veins in challenging patient populations, such as juvenile, elderly, dark-skinned, or obese patients. Spurred initially by the needs of pediatric sickle-cell anemia patients in Africa, Glenn's groundbreaking system includes a camera-processor-display apparatus and uses an innovative image-processing method to provide two- or three-dimensional, high-contrast visualization of veins or other vasculature structures. In addition to assisting practitioners to find veins in challenging populations, this system can also help novice healthcare workers locate veins for procedures such as needle insertion or excision. Compared to other state-of-the-art solutions, the imager is inexpensive, compact, and very portable, so it can be used in remote third-world areas, emergency response situations, or military battlefields.","category":"biomedical_health","categoryRaw":"health medicine and biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_93","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-93","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-93","confidence":"high"},"type":"patent","title":"Multi-Stage Filtration System","abstract":"Innovators at NASA's Glenn Research Center have developed a unique multi-stage filtration system to collect a wide range of particle sizes with minimal filter changes. This breakthrough capability keeps high-efficiency media and devices from becoming overloaded with larger particles. Glenn's system uses an impactor filter to capture larger particle matter through inertial separation and impaction methods on collection surfaces. After becoming heavily loaded, this filter can be cleaned automatically through a unique feed system, thereby reducing maintenance costs. In this way, the device provides a pre-filter stage that protects the more critical stages of the filter system, thereby extending the life of high-efficiency particulate arresting (HEPA) filter systems that are designed to capture fine and ultrafine particles. In an effort to reduce maintenance even further, the fine-particle filter media is provided in a scroll mechanism that is advanced to successive clean sections as needed. Highly sensitive filtration systems can be challenging to maintain and protect, so Glenn's system, which provides time and power savings offers great potential for commercial development.","category":"environment_climate","categoryRaw":"environment","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_53","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-53","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-53","confidence":"high"},"type":"patent","title":"Tool for Rapid Identification of TCE in Plants","abstract":"In collaboration with the State University of New York and the Naval Research Laboratory, NASA Marshall Space Flight Center is developing a hyperspectral estimator to detect trichloroethylene (TCE) in plants. TCE has been a widely used industrial solvent known to be toxic to humans and animals. Although its use and disposal have become more restricted in recent years, TCE is one of the more prevalent groundwater contaminants in the United States. Current methods exist to identify the locations of TCE at contaminated sites; however, these methods typically require destructive sampling techniques as well as time-consuming and expensive laboratory analysis. In contrast, the hyperspectral estimator is being designed as a nondestructive, quick, and lower-cost way to screen for TCE across large areas. It works by using spectral signatures to determine the presence/absence of TCE in the leaves of plants that may have absorbed the contaminant from surrounding groundwater.","category":"environment_climate","categoryRaw":"environment","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_100","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-100","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-100","confidence":"high"},"type":"patent","title":"Ionic Magnetic Resonance Tailors Animal Cells/Tissues","abstract":"Innovators at NASA Johnson Space Center have designed an apparatus and method that controls the growth and proliferation of 3D biological cells and mammalian tissue in the presence of a pulsating, alternating ionic magnetic resonance field (AIMR). The present technology applies a spectrum of electromagnetic fields to control the growth of all mammalian cells and tissues while simultaneously enabling cellular dedifferentiation and lifespan extension through the control of ionic transport and particular ion frequency resonances. The innovation AIMR Multiple-Chambered, Apparatus for the Culture of Cells, Tissues and Organoid Bodies and Method of Use is at technology readiness level (TRL) 3 (which means analytical and experimental critical function and/or characteristic proof of concept has been derived) and the related issued patent is now available for your company to license.","category":"biomedical_health","categoryRaw":"health medicine and biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_131","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-131","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-131","confidence":"high"},"type":"patent","title":"Portable Microscope","abstract":"Innovators at NASA Johnson Space Center have developed a handheld digital microscope to fill the critical microscopy needs of human space exploration by providing flight crews in situ hematological diagnostic and tracking ability to assess and monitor crew health in the absence of gravity. Although currently in use aboard the International Space Station (ISS) to work in conjunction with NASA\u2019s handheld slide staining system, the microscope may have numerous applications here on Earth. The microscope is entirely self-contained, and includes optics, illumination, high-resolution imaging hardware, wireless enabled single board computer with scalable power and memory, and rechargeable battery. The microscope also acts as an internet access point and connects via Bluetooth to smart devices for wireless image transfer and remote control. The microscope is durable enough to support field use while providing submicron imaging that would typically necessitate the use of larger more expensive benchtop microscopes. Cost of manufacturing the microscope may be relatively inexpensive through the utilization of 3D-printed components, and COTS hardware such as interchangeable microscope objectives. The handheld digital microscope is at technology readiness level (TRL) 8 (actual system completed and \" flight qualified\" through test and demonstration), and is now available to license. NASA does not manufacture products for commercial sale.","category":"biomedical_health","categoryRaw":"Health Medicine and Biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_132","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-132","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-132","confidence":"high"},"type":"patent","title":"Portable Slide Staining System for Microscopy","abstract":"Innovators at NASA Johnson Space Center have developed a handheld slide staining system designed to support medical, research or environ-mental monitoring. Although deployed aboard the International Space Station to work in conjunction with NASA\u2019s high-powered handheld microscope in the absence of gravity, the system may be applicable to all known staining procedures for terrestrial field and lab microscopes. This novel system is comprised of two primary components which are entirely self-contained when assembled. One component, the dispenser, is designed with an adjustable reagent sponge delivery system that not only serves as a containment unit for fluids, but whose volume allows for multiple uses until the reagents from the dispenser are depleted. The sponges can be replenished with commercial off-the-shelf reagents. The second component, the slide staining device, traps and seals the speci-men slide which then receives the titrated reagent from the dispenser. This technology was derived for space-based missions where a speci-men\u2019s return to Earth for rapid microscopic analysis would not be viable. A situation could exist within a spacecraft necessitating a rapid in situ medical diagnosis on a crewmember in determining whether an infection is present, conducting a white blood cell count, determining blood platelet concentration, and monitoring the effects of solar particle events as it applies to hematological disturbances.","category":"biomedical_health","categoryRaw":"Health Medicine and Biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_21","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-21","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-21","confidence":"high"},"type":"patent","title":"Freeze-Resistant Hydration System","abstract":"NASA's Johnson Space Center is offering an innovative freeze-resistant hydration system for licensing. The technology substantially improves on existing hydration systems because it prevents water from freezing in the tubing, container, and mouthpiece, even in the harshest conditions on Earth. This technology is designed to work to minus 40 degrees Celsius and 15-mile-per-hour winds over a 12-hour summit day, and likely well beyond. Field testing was performed at Mt. Everest in May 2009. The device was originally conceived and designed by an astronaut-mountaineer who recognized the great risk of dehydration in high mountains and the lack of sufficient technology to meet this important need. This NASA Technology is available for your company to license and develop into a commercial product. NASA does not manufacture products for commercial sale.","category":"environment_climate","categoryRaw":"environment","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_29","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-29","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-29","confidence":"high"},"type":"patent","title":"Filtering Molecules with Nanotube Technology","abstract":"Innovators at NASA's Johnson Space Center have identified a method to create a filtration device to eliminate contaminants from water supplies. Originally developed to purify wastewater for reuse aboard the International Space Station, the innovation is applicable to numerous situations on Earth where there is a need to collect potable, medical-grade water from a contaminated water supply. The unique aspect of the technology is its use of acoustics rather than pressure to drive water through small-diameter carbon nanotubes. The invention requires less power than conventional filtration systems and is well-suited to a variety of water processing needs. This NASA patent is available for your company to license, mature the technology and develop into a commercial product. NASA does not manufacture products for commercial sale.","category":"biomedical_health","categoryRaw":"health medicine and biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_35","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-35","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-35","confidence":"high"},"type":"patent","title":"Battery Charge Equalizer System","abstract":"A battery charge equalizer developed at NASA's Johnson Space Center provides individual cell charging in multi-cell battery strings using a minimum number of transformers. By effectively keeping all the cells in a multi-cell string at the same charge state, this technology maximizes the battery's life and performance. Designed to augment a simple high-current charger that supplies overall battery system energy , the innovation achieves equalization without wasting energy or creating excess heat. NASA's battery charge equalizer complements existing high voltage chargers and instrumentation systems and offers safe and low-cost management for lithium-ion (Li-ion) batteries used in electric vehicles and other next-generation renewable energy applications. This NASA Technology is available for your company to license and develop into a commercial product. NASA does not manufacture products for commercial sale.","category":"energy_power","categoryRaw":"power generation and storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_42","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-42","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-42","confidence":"high"},"type":"patent","title":"Self-Contained Device Isolates Biological Samples","abstract":"JSC is looking to interested parties to license and commercialize this patented technology. Innovators at NASA's Johnson Space Center (JSC) developed a patented self-contained device for isolating deoxyribonucleic acid (DNA), ribonucleic acid (RNA), proteins, and cells without using pipettes or centrifuges. Composed of reagents, functionalized membranes, and multi-way valves and pumps, this novel fluidic system enables automation of highly accurate real-time polymerase chain reaction (PCR) technology to isolate genetic material from organisms and microorganisms for molecular analysis. The device is self-enclosed and leak-proof, so users are protected from chemically hazardous reagents. Developed to enable molecular diagnostics aboard the International Space Station (ISS), this easy-to-use analysis tool can be fully automated and programmed, extending laboratory isolation protocols to numerous applications in health care, forensics, and field biology.","category":"biomedical_health","categoryRaw":"Health Medicine and Biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_45","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-45","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-45","confidence":"high"},"type":"patent","title":"Robonaut 2: Medical Opportunities","abstract":"Researchers at the NASA Johnson Space Center (JSC), in collaboration with General Motors and Oceaneering, have designed a state-of-the-art, highly dexterous, humanoid robot: Robonaut 2 (R2). R2 is made up of multiple component technologies and systems making up nearly 50 patented and patent pending technologies with the potential to be game-changers in multiple industries including the medical industry. R2 technologies can aid in a variety of medical applications, ranging from telemedicine to handling the logistics of medical procedures. These activities can be done in autonomous mode or in teleoperation mode, where the robot is controlled by a technician or physician. This type of operation would be advantageous during situations where a biomedical hazard poses risks to humans, such as a contagious outbreak or a combat situation. For more routine daily use, R2 could function as an assistant to the hospital staff. This NASA Technology is available for your company to license and develop into a commercial product. NASA does not manufacture products for commercial sale.","category":"biomedical_health","categoryRaw":"Health Medicine and Biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_54","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-54","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-54","confidence":"high"},"type":"patent","title":"Micro-Organ Device Mimics Organ Structures for Lab Testing","abstract":"NASA Johnson Space Center has developed the Micro-Organ Device (MOD) platform technology that serves as a drug screening system with human or animal cell micro-organs to supplement and reduce animal studies while potentially increasing the success of clinical trials. The technology was originally developed to evaluate pharmaceuticals in zero gravity to accelerate development and validation of countermeasures for humans in space as well as evaluate space and planetary stressors on a biological level. The MOD is a microfluidic device containing a variety of microstructures and assemblies of cells, all designed to mimic a complex in vivo microenvironment by modeling one or more in vivo micro-organ structures, the architectures and composition of the extracellular matrices in the organs of interest, and the in vivo fluid flows. The fully automated technology can be used to perform early stage in vivo drug screening without the use of animal experimentation, saving time, money, and resources. This NASA Technology is available for your company to license and develop into a commercial product. NASA does not manufacture products for commercial sale.","category":"biomedical_health","categoryRaw":"Health Medicine and Biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_67","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-67","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-67","confidence":"high"},"type":"patent","title":"Digital to Analog Transformation and Reconstruction of ECG Data","abstract":"The innovators at the NASA Johnson Space Center have developed a new method and device for specialized digital to analog conversion (DAC) and reconstruction of multichannel electrocardiograms (ECGs), including 12-lead ECGs. Current devices do not have the functionality that allow for the transmission of stored digital ECG data collected from one manufacturer's ECG machine to another for an automated second opinion. With this technology the physician has the opportunity to compare results by transferring the ECG data to another ECG machine regardless of location when a patients results are difficult-to-interpret for a second opinion. The technology also allows for the use of less expensive 12-lead ECG front ends or analog to digital conversion (ADC) hardware which is advantageous when in remote locations or with patients who are mobile during research studies. The digital to analog transformation and reconstruction of ECG data technology is available for licensing.","category":"biomedical_health","categoryRaw":"health medicine and biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_73","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-73","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-73","confidence":"high"},"type":"patent","title":"Miniature Bioreactor System for Cell Culture","abstract":"Scientists at the NASA Johnson Space Center and the University of Houston have developed a miniature bioreactor system for varied term cell culturing and sampling. The miniature bioreactor allows for continuous and simultaneous short, moderate, or long-term cell culturing of several types of cells and tissues. The invention can be used to study cell cultures and their response to stressors such as pharmaceuticals, hypoxia, pathogens, and more. The bioreactor is ideally suited for periodic cell harvesting and medium processing for secreted cellular components. The miniature bioreactor system has an existing prototype and an initial proof of concept has been completed. The miniature bioreactor system is available for licensing. This NASA Technology is available for your company to license and develop into a commercial product. NASA does not manufacture products for commercial sale.","category":"biomedical_health","categoryRaw":"health medicine and biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_81","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-81","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-81","confidence":"high"},"type":"patent","title":"Split-Ring Torque Sensor","abstract":"Innovators at the NASA Johnson Space Center (JSC), in collaboration with Oceaneering and The Florida Institute for Human and Machine Cognition, have developed the Split-Ring Torque Sensor (SRTS), a device that uses optical sensors to measure the position, velocity, and torque of a rotating system. The SRTS was created for use in NASA's X1 robotic exoskeleton, an in-space, wearable exercise machine designed to supply resistance against leg movement for NASA astronauts in future missions. The X1 exoskeleton implements the SRTS in its belt-drive series elastic actuator (SEA) and provides a lower profile and lower weight system than competing designs. The SRTS offers greater flexibility in tailoring for specific applications and requirements. In addition to its applications in robotics, the SRTS has potential uses in medical fields including prosthetics, aerospace & defense applications, automotive applications, testing & measurement, and industrial markets.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_83","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-83","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-83","confidence":"high"},"type":"patent","title":"Cord Tension Measurement Device (C-Gauge)","abstract":"Innovators at the NASA Johnson Space Center (JSC) have developed the C-Gauge, a non-invasive tension measurement device for axial loaded cords. Cordage-based flexible structure systems are used by NASA as parachutes and inflatable structures. For engineers to fully design, develop, and test these types of systems, they must understand the tension and loading of the structural components including the load carrying cords. Traditional in-line load cells require cords to be severed and attached to a metallic interface. The C-Gauge attaches to the cord without any severing of the cord and can measure the structural response without affecting the dynamics of the system, providing engineers a non-invasive way to test cordage-based structures with a small, low-profile, and lightweight device. The C-Gauge has a variety of potential applications including, but not limited to, parachutes, inflatable structures, hot air balloons, weather balloons, blimps, sails, and parasails.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_86","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-86","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-86","confidence":"high"},"type":"patent","title":"Human-Powered Ventilator","abstract":"Innovators at NASA Johnson Space Center have created a human-powered ventilator that utilizes hand-pump motions, rather than hand or wrist motions such as with a Bag Valve Mask (BVM), to help stabilize respiratory distress in a patient, without electricity. By using an arm-pumping motion to operate the accordion-like ventilator, minimally trained operators can provide respiration to a patient on space-based missions with greater endurance. Due to the COVID-19 outbreak, this device was reengineered for terrestrial applications in areas where electrically powered ventilators are nonexistent or in short supply. The ventilator is designed to be made of parts that are portable and inexpensive to manufacture as well as simple to assemble and use. This allows for rapid deployment to areas in need such as resource-poor localities or for use by minimally trained personnel, allowing for quick availability to areas in need.","category":"biomedical_health","categoryRaw":"Health Medicine and Biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_91","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-91","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-91","confidence":"high"},"type":"patent","title":"RFID-Enabled Wireless Instrumentation","abstract":"Innovators at NASA Johnson Space Center have developed a wireless instrumentation system whose sensor tags can operate for years in a low-power hibernation state with instantaneous over-the-air passive RFID wakeup using only a small coin cell battery. The sensor tags, which are embedded with a processor and memory bank for acquired data, are placed about the vehicle and stream data only when queried by a fixed-location RFID interrogator. Otherwise, the tags remain dormant to preserve battery life. In the hibernating configuration, the microcontroller is the only circuit drawing power in the wireless sensor tag, and it is operating in the lowest power mode possible. This architecture proves extremely useful on long-duration missions and for early sensor tag integration into vehicles during assembly when the sensors may remain dormant years before being operated. This wireless low-mass technology will be implemented aboard the Cygnus CRS-2 NG-18 spaceflight mission.","category":"sensors_instruments","categoryRaw":"instrumentation","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_93","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-93","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-93","confidence":"high"},"type":"patent","title":"Wearable RFID Sensor Tags Yield Extended Operational Times","abstract":"Innovators at NASA Johnson Space Center have developed a method that uses Radio Frequency Identification (RFID) interrogators for use with wearable active RFID sensor tags that can operate on ultra-low power. The technique uses a store-and-forward approach to manage the collection of data from RFID active tags even when they are not in range of an individual interrogator, as they move from the coverage area of one interrogator to the next. This allows the use of RFID active tags to transport sensor data in a highly complex environment where instantaneous access to an RFID interrogator cannot be guaranteed. Using this technique, an RFID active tag battery operational lifetime can be extended.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_94","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-94","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-94","confidence":"high"},"type":"patent","title":"Human Tissue-Like Cellular Assemblies Grown for Respiratory Studies","abstract":"Innovators at NASA Johnson Space Center have developed a technology that yields three-dimensional (3D) tissue-like assemblies (TLAs) of human broncho-epithelial (HBE) cells for in vitro research on infection of humans by respiratory viruses. Compared to traditional two-dimensional (2D) monolayer cell culture, the 3D TLAs more accurately represent the active environment present in respiratory infections. It offers a cost-effective platform that functions like in vivo human tissue, reducing the need for human subject testing and supporting a more controlled testing environment free from immune system limitations. 3D TLAs provide an opportunity to study the tolerance to bioactive ingredients, the impacts of developing vaccinations on respiratory tissues, and other applications directed to product development for the cosmetics and textile industries.","category":"biomedical_health","categoryRaw":"Health Medicine and Biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_95","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-95","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-95","confidence":"high"},"type":"patent","title":"3D Mineralized Bone Constructs","abstract":"Innovators at NASA Johnson Space Center have developed a technique to grow 3D tissue constructs, similar to human bone, in a laboratory environment. Problems arise when studying both the normal state and pathophysiology of bone. As an organ system, it is slow growing, so the time to study and observe a response to a particular stimulus is relatively long. Our bioengineers have discovered that osteoblast and osteoclast cell types can be induced to aggregate into large spheroids in a specific spatial relationship under certain culture conditions when placed in a rotating-wall tissue-culture vessel (shown above). The ability to construct a 3D model of such mineralized tissue on-demand, using a co-culture of human cells that differentiate and spatially arrange themselves in a physiologically relevant manner, is a major step forward in how the process of bone formation and remodeling can be studied.","category":"biomedical_health","categoryRaw":"Health Medicine and Biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_96","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-96","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-96","confidence":"high"},"type":"patent","title":"Noninvasive Therapy for Cartilage Regeneration","abstract":"Innovators at NASA Johnson Space Center researching time-variance magnetic field (TVMF) therapies have developed a pulsed electromagnetic field (PEMF) device that can alleviate cartilage degradation in synovial joints by promoting the growth of new cartilage. Joint disorders, whether induced by rheumatism, joint dysplasia, trauma, or surgery, often degrade cartilage and result in intense patient pain. Noninvasive and painless regeneration of a patients own tissue offers fewer side-effects than surgical joint replacement or tissue engineering procedures. The PEMF device could simply be wrapped around synovial joints where cartilage-degrading inflammation is located. This pulsed electromagnetic field technology is at a technology readiness level (TRL) 6 (system/sub-system model or prototype demonstration in an operational environment ) and the related patent is available for licensing. Please note that NASA does not manufacture products itself for commercial sale.","category":"biomedical_health","categoryRaw":"health medicine and biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_npo_tops_14","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-TOPS-14","sourceUrl":"https://technology.nasa.gov/patent/NPO-TOPS-14","confidence":"high"},"type":"patent","title":"Biomarker Sensor Arrays for Microfluidics Applications","abstract":"NASA's Jet Propulsion Laboratory (JPL) offers a method to manufacture biomarker sensor arrays with nanoscale resolution and active regions on the order of 1 micron, by applying nanolithographic direct-write techniques to the fabrication of silane chemistry sensors on a transparent substrate. This novel technology enables extremely fine patterns of detectors suitable for multicolor imaging of single-molecule samples at resolutions far below the diffraction limit. The extremely small size of these sensors allows for rapid, highly specific screening for hundreds of functionalities within a single, small, integrated microfluidics chip.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_npo_tops_59","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-TOPS-59","sourceUrl":"https://technology.nasa.gov/patent/NPO-TOPS-59","confidence":"high"},"type":"patent","title":"High-Performance, Lightweight, Easy-to-Fabricate Heat Exchanger","abstract":"Researchers at NASA's Jet Propulsion Laboratory (JPL) have developed an advanced heat exchanger that addresses problems typically associated with metal-based systems. Unlike typical metal heat exchangers, which suffer from high thermal expansion and high density, JPL's innovation offers several improved properties. Its lightweight, high heat flux design offers a low coefficient of thermal expansion (CTE)&#8212;and therefore low expansion characteristics&#8212;and reduces the pressure drop during heat transfer. The design can handle high-temperature gases (up to 650 &#176;C). This technology has undergone successful preliminary testing. Developed for an aircraft exhaust energy recovery application, the system meets the requirements of high-temperature, high-specific-power thermoelectric generators and other energy recovery systems for industrial, automotive, military, and space applications.","category":"energy_power","categoryRaw":"power generation and storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ssc_tops_1","source":{"institution":"NASA","subUnit":"Stennis Space Center","subUnitCode":"SSC","nativeId":"SSC-TOPS-1","sourceUrl":"https://technology.nasa.gov/patent/SSC-TOPS-1","confidence":"high"},"type":"patent","title":"In Situ Performance Monitoring of Piezoelectric Sensors and Accelerometers","abstract":"An in situ measurement system for monitoring the performance of piezoelectric sensors, particularly accelerometers, was developed. With this technology, characteristics such as resonant frequency, response, cable status, connectivity, bonding and linear range, can be determined. Sensors can be tested in a very wide frequency range, extending to 200 MHz and beyond, without removing them from their mounted locations, and without requiring specially constructed transducers or special wiring. Assessments can be performed in situ, and can be conducted with hand held test equipment or integrated into instrumentation systems. With this monitoring system, degraded sensor performance can be quickly and economically identified with a handheld unit or integrated directly into test equipment.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_102","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-102","sourceUrl":"https://technology.nasa.gov/patent/TOP2-102","confidence":"high"},"type":"patent","title":"Spatial Standard Observer (SSO)","abstract":"The Spatial Standard Observer (SSO) was developed to predict the detectability of spatial contrast targets such as those used in the ModelFest project. The SSO is a lumped parameter model basing its predictions on the visible contrast generalized energy. Visible contrast means that the contrast has been reduced by a contrast sensitivity function (CSF). Generalized energy means that the visible contrast is raised to a power higher than 2 before spatial and temporal integration. To adapt the SSO to predict the effects of variations of optical image quality on tasks, the optical component of the SSO CSF needs to be removed, leaving the neural CSF. Also, since target detection is not the typical criterion task for assessing optical image quality, the SSO concept needs to be extended to other tasks, such as Sloan character recognition.","category":"imaging_optics","categoryRaw":"optics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_106","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-106","sourceUrl":"https://technology.nasa.gov/patent/TOP2-106","confidence":"high"},"type":"patent","title":"Contaminated Water Treatment","abstract":"Scientists at NASA Ames have developed a method and system that offers a novel way of processing and recycling of liquids to remove contaminants. Space exploration requires a life-support system that sustains astronauts on journeys lasting from a few days to several weeks or longer. The life-support system must be designed to reduce the mass required to keep humans alive in space. Water accounts for about 80 percent of a humans daily mass intake. As a result, recycling water, including urine, offers a high return on investment for space exploration missions as well as increasing mission safety. It provides an emergency supply of drinking water, when other sources are exhausted or contaminated.","category":"environment_climate","categoryRaw":"environment","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_129","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-129","sourceUrl":"https://technology.nasa.gov/patent/TOP2-129","confidence":"high"},"type":"patent","title":"Solid And Liquid Waste Drying Bag","abstract":"This invention facilitates collection, storage, concentration, and drying of liquid or mixed liquid/solid material. Material may be medical waste, aqueous hazardous waste for which disposal cost is high, such as radioactive salt solutions, or brine or sludge from water treatment operations. It can be used to dry biological specimens or concentrate water samples for analysis. It can also function as a portable toilet.","category":"biomedical_health","categoryRaw":"health medicine and biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_160","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-160","sourceUrl":"https://technology.nasa.gov/patent/TOP2-160","confidence":"high"},"type":"patent","title":"Solar Powered Carbon Dioxide (CO2) Conversion","abstract":"NASA has developed a new technology that can convert the greenhouse gas carbon dioxide (C02) into fuel by using solar-powered, thin-film devices. Metal oxide thin films are fabricated to produce a photoelectrochemical cell that is powered by solar energy. By converting CO2 to fuel before it is emitted to the atmosphere this technology can mitigate the effects of the burning of fossil fuels, the worlds major fuel source for the foreseeable future This new nanomaterial thin-film device provides a low cost, facile fabrication pathway to commercialize the technology in the sustainable energy market. More importantly, it results in a zero carbon footprint by recycling C02 to fuels that are compatible with all existing fuel utilities. This is accomplished by using solar power to convert the C02 into a useable fuel in a very compact device.","category":"energy_power","categoryRaw":"power generation and storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_164","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-164","sourceUrl":"https://technology.nasa.gov/patent/TOP2-164","confidence":"high"},"type":"patent","title":"Video Acuity Measurement System","abstract":"There is a widely acknowledged need for metrics to quantify the performance of video systems. NASAs new empirical Video Acuity metric, is simple to measure and relates directly to task performance. Video acuity is determined by the smallest letters that can be automatically identified using a video system. It is expressed most conveniently in letters per degree of visual angle. Video systems are used broadly for public safety, and range from very simple, inexpensive systems to very complex, powerful, and expensive systems. These systems are used by fire departments, police departments, homeland security, and a wide variety of commercial entities. They are used in streets, stores, banks, airports, cars, and aircraft , as well as many other settings. They are used for a variety of tasks, including detection of smoke and fire, recognition of weapons, face identification, and event perception. In all of these contexts, the quality of the video system impacts the performance in the visual task. The Video Acuity metric matches the quality of the system to the demands of its tasks.","category":"imaging_optics","categoryRaw":"optics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_169","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-169","sourceUrl":"https://technology.nasa.gov/patent/TOP2-169","confidence":"high"},"type":"patent","title":"Nanosensor Array for Medical Diagnoses","abstract":"NASA has developed an innovative approach to improve the quality and convenience of medical diagnosis, and data transmission for immediate therapy. The new technology uses a network of nanochemical sensors on a silicon chip combined with a monitoring system composed of humidity, temperature, and pressure/flow sensors for real-time chemical and physical properties measurement of human breath for non-invasive and low-cost medical diagnosis. No such technology exists in the market today. Although many research activities are ongoing, NASAs technology is readily available for this application. With a detection range of parts per million (ppm) to parts per billion (ppb) this technology, called a nanosensor array chip, provides a highly-sensitive, low-power, and compact tool for in-situ and real time analysis. It changes the way and time decisions are made to help both patient and medical care provider to minimize their cost, optimize resources, reduce risk, and cut the amount of time needed for conducting a response.","category":"biomedical_health","categoryRaw":"health medicine and biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_184","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-184","sourceUrl":"https://technology.nasa.gov/patent/TOP2-184","confidence":"high"},"type":"patent","title":"Optimum Solar Conversion Cell Configurations","abstract":"NASA has invented a new optical fiber that is suitable for solar lighting applications and electrical generation. A key feature is the integration of photovoltaic material for electricity generation. Fiber solar cells surpass both the efficiency and functionality of traditional flat-panel solar cells. A hybrid solar energy cell device manufactured from this new optical fiber consists of three or four layers of materials , including a combination of n-type nanowires and selected p-type polymers. The fiber has two key features which distinguish it from other fibers. First, the amount of visible light transmitted to the lighting application can be varied by tuning the fiber material. Second, photovoltaic material is integrated into the fiber and can be used to generate electricity - from the ultraviolet and infrared portions of the spectrum. If the fiber is tuned to reduce the amount of visible light transmitted to the lighting application, it is also used to generate electricity.","category":"energy_power","categoryRaw":"power generation and storage","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_186","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-186","sourceUrl":"https://technology.nasa.gov/patent/TOP2-186","confidence":"high"},"type":"patent","title":"HeartBeatID","abstract":"One or more biometric indicia, such as fingerprints, voice-prints, retinal scans, and facial features are often proposed to be used to identify, or to authenticate the asserted identity of a user who seeks access to a given resource. This invention provides a method and associated system for authenticating or declining to authenticate an identity asserted by a candidate person. The heartbeat system is a new biometric technique to verify someone's identity. It can be used in everything from replacing an individuals PC passwords to access a bank account.","category":"biomedical_health","categoryRaw":"health medicine and biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_197","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-197","sourceUrl":"https://technology.nasa.gov/patent/TOP2-197","confidence":"high"},"type":"patent","title":"Habitat Water Wall for Water, Solids, and Atmosphere Recycle and Reuse","abstract":"NASA has created a unique approach to water, solids, and atmosphere recycle and reuse. The membrane water wall concept includes a system for membrane-based water, solids, and air treatment functions that is embedded into the walls of inflatable or rigid habitat structures. It provides novel and potentially game changing mass reuse and structural advantages over current mechanical life support hardware. It also provides radiation protection, building materials and structural elements. This approach potentially reduces the cost of human space flight by replacing the mass, power, and volume of conventional life support hardware. It removes air, water, and waste treatment hardware from the usable habitat volume. Also, it provides structural elements to strengthen the habitat shell, provide thermal control, and provide radiation shielding.","category":"environment_climate","categoryRaw":"environment","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_202","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-202","sourceUrl":"https://technology.nasa.gov/patent/TOP2-202","confidence":"high"},"type":"patent","title":"Method and Device for Biometric Verification and Identification","abstract":"NASA has developed a method for verifying the identity of a person based on his or her heartbeat electrocardiogram signal. The technique uses an algorithm that has been shown to be more reliable than other current procedures, such as fingerprint verification, retina verification, or detecting biometric identifiers from heart signals. It eliminates artifacts and abnormal beats, thereby reducing overall error. The process automatically extracts from one or more electrocardiographic leads (channels) a set of biometric features which are characteristic to an individual and can be employed to verify the identity of one individual or to identify an individual from a group. The electrocardiographic signal is recorded in each lead from a pair of electrodes placed on the skin of the individuals arms or legs. Each electrocardiographic lead characterizes the hearts electrical vector as projected on a separate dimension. This allows a multidimensional characterization of the hearts electrical activity, which can result in improved subject verification performance.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_246","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-246","sourceUrl":"https://technology.nasa.gov/patent/TOP2-246","confidence":"high"},"type":"patent","title":"Portable Medical Diagnosis Instrument","abstract":"NASA has developed a novel technology strategy called \"The NASA Analyzer\" that would provide comprehensive in- flight medical diagnostic capability in a compact, hand-held device for human deep-space missions such as Mars. Key features of the technology include the ability to handle multiple sample types (breath, saliva, blood), and the ability to measure virtually any analyte, including future analytes as they emerge. The device provides both non-invasive and minimally invasive sampling capabilities, which will be required during long-duration exploration missions. Breath and saliva are fully non-invasive and can provide critical health assessment information very rapidly. From small blood samples, information about macromolecular analytes as well as blood cell counts can be obtained. The device consists of four cutting-edge technologies integrated into a single compact medical diagnostic tool with wireless (e.g., smart phone) capability. In addition to space applications, this innovative technology will very likely have important spin-offs in medicine and public health on Earth.","category":"sensors_instruments","categoryRaw":"instrumentation","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_256","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-256","sourceUrl":"https://technology.nasa.gov/patent/TOP2-256","confidence":"high"},"type":"patent","title":"3D Construction of Biologically Derived Materials","abstract":"NASA has developed a novel approach for macroscale biomaterial production by combining synthetic biology with 3D printing. Cells are biologically engineered to deposit desired materials , such as proteins or metals, derived from locally available resources. The bioengineered cells build different materials in a specified 3D pattern to produce novel microstructures with precise molecular composition, thickness, print pattern, and shape. Scaffolds and reagents can be used for further control over material product. This innovation provides modern design and fabrication techniques for custom-designed organic or organic-inorganic composite biomaterials produced from limited resources.","category":"biomedical_health","categoryRaw":"health medicine and biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_268","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-268","sourceUrl":"https://technology.nasa.gov/patent/TOP2-268","confidence":"high"},"type":"patent","title":"Oculometric Testing for Detecting/Characterizing Mild Neural Impairment","abstract":"This novel technology is a screening tool to screen for neurological disorders or injury detecting oculomotor signatures. The tool can be used to measure/monitor the severity and nature of such symptoms. Eye movements are the most frequent, shortest-latency, and biomechanically simplest voluntary motor behavior, and thus provide a model system to assess perceptual and sensory processing disturbances arising from trauma, fatigue, aging, environmental exposures, or disease states. Scientists at NASA have developed and validated a rapid, non-invasive, eye-movement-based testing system to evaluate neural health across a range of brain regions. The technology applies a 5-minute behavioral tracking task consisting of randomized step-ramp radial target motion to capture several aspects of neural responses to dynamic visual stimuli, including pursuit initiation, steady-state tracking, direction and speed tuning, pupillary responses, and eccentric gaze holding.","category":"biomedical_health","categoryRaw":"Health Medicine and Biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_276","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-276","sourceUrl":"https://technology.nasa.gov/patent/TOP2-276","confidence":"high"},"type":"patent","title":"Rapid Nucleic Acid Isolation Method and Fluid Handling Devices","abstract":"Sample preparation is a common bottleneck in genetic analysis. Tools that reduce time and effort are of great value in a laboratory setting. There is a need for a genetic analysis/detection system that is not only mobile, ruggedized, and easy-to-use but that also provides an enclosed fluid handling, which diminishes the risks of Ribonucleic acid (RNA) contamination and degradation during processing. NASA Ames has developed a novel assay methodology and suite of devices to isolate nucleic acids and prepare samples for Reverse Transcriptase quantitative Polymerase Chain Reaction analysis that solves the problem of contamination and degradation. Gene expression analysis reveals valuable information about molecular and cellular mechanisms that can be applied not only for protecting human health during space missions but also for fundamental biology investigations and commercial drug discovery efforts on earth. This invention enables an end-to-end ability to process a biological sample for gene expression analysis - from raw tissue to data .","category":"biomedical_health","categoryRaw":"health medicine and biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_283","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-283","sourceUrl":"https://technology.nasa.gov/patent/TOP2-283","confidence":"high"},"type":"patent","title":"In-Situ Resource Utilization (ISRU): Methylotrophic Microorganisms Expressing Soluble Methane Monooxygenase Proteins","abstract":"Long duration missions to planetary bodies and deep space will require new technological developments that support human habitation in transit and on distant bodies. Microorganisms are unique from the standpoint that they can be employed as self-replicating bio-factories to produce both native and engineered mission relevant bio-products. ISRU using In-Space Manufacturing (ISM) to generate mission relevant products could be logical for many applications. Products that consist of a significant amount of carbon (e.g. fuels, and foods etc.) could potentially be derived from single-carbon molecules available on long duration missions. NASA Ames has developed a novel patent-pending technology for an in-space bio-manufacturing of mission relevant bio-products using methane as the sole carbon substrate.","category":"biomedical_health","categoryRaw":"Health Medicine and Biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_292","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-292","sourceUrl":"https://technology.nasa.gov/patent/TOP2-292","confidence":"high"},"type":"patent","title":"Solid State Carbon Dioxide (CO2) Sensor","abstract":"Detection of Carbon Dioxide (CO2) is very important for environmental, health, safety and space applications. CO2 is a harmful pollutant at higher concentrations due to its ability to displace oxygen in large concentrations. Current commercial sensors for CO2 have issues and shortcomings particular with precision at different temperatures, pressures and high humidity levels. NASA Ames has developed a novel solid state, CO2 sensor configured for sensitive detection of CO2 having a concentration within the range of about 100 Parts Per Million (ppm) and 10,000 ppm in both dry conditions and high humidity conditions. The composite sensing material comprises Oxidized Multi-Walled Carbon Nanotubes (O-MWCNT) and a metal oxide. The composite sensing material has an inherent resistance and corresponding conductivity that is chemically modulated as the level of CO2 increases. The CO2 sensor can be easily integrated into existing electronic circuitry and hardware configurations, including the hardware of a mobile computing device, such as a smart phone or tablet device.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_293","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-293","sourceUrl":"https://technology.nasa.gov/patent/TOP2-293","confidence":"high"},"type":"patent","title":"Calculation of Unsteady Aerodynamic Loads Using Fast-Response Pressure-Sensitive Paint (PSP)","abstract":"Many important physical problems in aero-sciences involve unsteady, separated flows. The ability to measure and compute these flows has been a persistent challenge. Unsteady aerodynamics leads to unsteady loads which ultimately decrease system performance and shortens the system lifetime. Currently, dynamic pressure transducers are used to study unsteady flow in wind tunnel tests, which are expensive and do not provide accurate integrated unsteady loads on a wind tunnel model. NASA Ames has developed a first-of-its-kind technology to use a system comprised of fast-response pressure-sensitive paint (PSP), high-speed cameras, and high-powered excitation sources to collect data on pressure fluctuations on vehicle models in wind tunnels. Unsteady Pressure-Sensitive Paint (uPSP) is an emerging optical technique used in wind tunnel testing to measure fluctuating unsteady surface pressures.","category":"sensors_instruments","categoryRaw":"instrumentation","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_296","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-296","sourceUrl":"https://technology.nasa.gov/patent/TOP2-296","confidence":"high"},"type":"patent","title":"Closed Ecological System Network Data Collection, Analysis, Control, and Optimization System","abstract":"The Earth's biosphere is the most sophisticated complex adaptive system known to exist in the entire universe and has persisted for over 4 billion years. A complex adaptive system is a network of interacting adaptive systems whose nonlinear dynamics and emergent behaviors are difficult to predict and control; therefore, for such systems, past performance is no guarantee of future results, which is particularly the case for the Earths biosphere during a period of exponential technological growth. NASA Ames Research Center presents a novel, patent-pending adjustable-autonomous intelligent systems approach for developing sustainable, small-scale reproductions of subsets of the Earths biosphere that can be distributed both on and beyond Earth, for improving the quality of life for all life, expanding the diversity of life, studying and protecting life, as well as enabling life to permanently extend beyond Earth.","category":"environment_climate","categoryRaw":"environment","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_300","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-300","sourceUrl":"https://technology.nasa.gov/patent/TOP2-300","confidence":"high"},"type":"patent","title":"Room temperature oxygen sensors","abstract":"Oxygen (O 2 ) sensors are used in a wide array of applications, including electronic fuel injection and emissions control in the automotive industry, for monitoring oxygen levels in controlled environments, such as in space craft or space suits, for oxygen monitoring in medical and pharmaceutical applications, and many more. Traditional oxygen sensors, including potentiometric and amperometric sensor designs, have significant drawbacks, as metal oxide gas sensors require high temperature operation of about 300C, and suffer from high power consumption. NASA Ames Research Center has developed novel oxygen sensors made of a hybrid material comprising graphene and titanium dioxide (TiO 2 ) that is capable of detecting O 2 gas at room temperature and ambient pressure. The sensors have fast response and recovery times and can also be used to detect ozone. The sensors can be integrated into wearable-sized Internet of Things (IoT) devices.","category":"sensors_instruments","categoryRaw":"sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_307","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-307","sourceUrl":"https://technology.nasa.gov/patent/TOP2-307","confidence":"high"},"type":"patent","title":"Electrochemical Sensors Based on Enzyme-Linked Immunosorbent Assay","abstract":"Biological assays are ever evolving to move towards lower limits of detection and improved sensitivity. Improvements in trace biological molecule detection can have significant impact in healthcare, food safety and environmental safety industries. Detection of trace biological molecules can be critical to the diagnosis of early onset of diseases or infections. Researchers at NASA Ames Research Center developed an electrochemical, bead-based biological sensor based on Enzyme-Linked Immunosorbent Assay (ELISA) combining a magnetic concentration of signaling molecules and electrochemical amplification using wafer-scale fabrication of microelectrode arrays. Originally developed for the detection of the SARS-CoV-2 nucleoprotein, this invention can be easily modified to detect other environmental or human health biomarkers.","category":"biomedical_health","categoryRaw":"Health Medicine and Biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_324","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-324","sourceUrl":"https://technology.nasa.gov/patent/TOP2-324","confidence":"high"},"type":"patent","title":"Expanded COBRA Oculometrics (ECO) to Include Perimetry and Directional Assessment of Visual and Visuomotor Performance","abstract":"Injury and disease can cause localized impairment of the retina and visual cortex. However, standard functional clinical assessment of sub-regions of the visual field and retina employ a crude spatial measure, called perimetry, that is insensitive to milder localized defects and vulnerable to eye-movement artifacts. NASA Ames Research Center\u2019s current patented suite of COBRA oculometrics (TOP2-268) provides assessment of general retinal/visual health and performance for the entire visual field or retina, and would not detect defects limited to a small specific location on the retina or in the visual field. NASA Ames has developed a novel Expanded COBRA Oculometrics (ECO), which enhances COBRA by systematically exploring \u201clocalized\u201d impairment of specific portions of the retina or visual field that could be the result of patchy retinal or brain degenerative disease, brain tumors, strokes, etc., and by extending the range of retina or visual field tested using a set of concentric rings divided up into octants (or quadrants).","category":"biomedical_health","categoryRaw":"Health Medicine and Biotechnology","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_drc_tops_39","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-TOPS-39","sourceUrl":"https://technology.nasa.gov/patent/DRC-TOPS-39","confidence":"high"},"type":"patent","title":"Axial Magnetic Flux Airflow Integrated Compressor-Generator-Motor Turbojet","abstract":"Innovators at NASA's Armstrong Flight Research Center have developed a compressor-generator-motor turbojet design that integrates the generator into the aerodynamic blade structures of the compression section of turbo-machinery. This lowers both weight and volume compared with conventional turbine generator arrangements in which the turbojet or turbofan drives a separate shaft-driven generator. All manner of other conventional designs suffer from system inefficiencies. Conventional side-mounted generators require the weight of a 90-degree gearbox, while a rear-mounted generator suffers from cooling problems. Armstrong's design offers improvements over these configurations with a flight-weight electromagnetic turbo-generator that is suitable for application to distributed turboelectric systems on aircraft and aids in cooling the system. The unique technology may enable new aircraft configurations and future Turboelectric Distributed Propulsion (TeDP) aircraft designs.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_drc_tops_41","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-TOPS-41","sourceUrl":"https://technology.nasa.gov/patent/DRC-TOPS-41","confidence":"high"},"type":"patent","title":"A New Twist Makes Rotating Machinery More Efficient and Quieter","abstract":"Innovators at NASA's Armstrong Flight Research Center have designed a new shape for propeller blades that dramatically increases their efficiency while reducing noise. Based on improvements achieved via a new wing design known as PRANDTL-D, this innovative propeller design uses an alternative spanload to reduce the tip load as well as the torque at the tip of the blade. These changes dramatically reduce the power needed for rotation while maintaining other blade design parameters (e.g., thrust, diameter, rpm). With a more than 15 percent improvement in propulsive efficiency and significantly reducing noise, the technology promises to reduce power consumption for propeller aircraft . These benefits are also relevant for a wide range of rotating machinery.","category":"propulsion","categoryRaw":"Propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_16","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-16","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-16","confidence":"high"},"type":"patent","title":"SMART Solar Sail","abstract":"NASA GSFCs SMART (Super Miniaturized Autonomous Reconfigurable Technology) Solar Sail is a deployable, fully autonomous, solar sail for use in a very fine station keeping of a spacecraft . The solar sail would be highly deformable from an initially highly compressed configuration, yet also capable of enabling very fine maneuvering of the spacecraft by means of small sail-surface deformations. The SMART Solar Sail would be connected to the main body of the spacecraft by a SMART multi-tether structure, which would include microelectromechanical system (MEMS) actuators like those of the frame plus tethers in the form of longer versions of the struts in the frame.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_352","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-352","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-352","confidence":"high"},"type":"patent","title":"Improved Efficiency in Nuclear Propulsion","abstract":"Innovators at Langley Research Center (LaRC) have developed a design and method to improve efficiency in nuclear propulsion technology for long-distance space missions. The nuclear thermionic avalanche cell (NTAC) Augmented Nuclear Electric Propulsion and/or Nuclear Thermal Propulsion design surrounds the rocket chamber and reactor core with an NTAC and safely converts gamma ray radiation expelled during nuclear fission processes, which would otherwise be lost to radiation shielding, into electric power to support additional propulsion . Compared to current radiation-shielded propulsion systems, this design is more efficient and lower weight, enabling faster nuclear propulsion travel. This technology potentially has a wide range of applications including nuclear power generation applications on Earth, and for unmanned vehicles, and commercial space exploration.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_157","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-157","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-157","confidence":"high"},"type":"patent","title":"Power Processing Unit (PPU) for Small Spacecraft Electric Propulsion","abstract":"Innovators at NASAs Glenn Research Center have developed a suite of small spacecraft electric propulsion (SSEP) technologies critical to enabling new, ambitious missions into deep space. Advanced SSEP technologies are based on the use of exceptionally fuel-efficient electrostatic Hall effect thrusters with optimized magnetic shielding, achieving massive reductions in propellant mass relative to traditional chemical propulsion systems. NASAs low-power, high-throughput SSEP technology dramatically increases the capabilities of small spacecraft while maximizing reliability and reducing launch costs. The Power Processing Unit (PPU) is available for licensing on its own, or as a component of NASAs SSEP technology suite, which is available to U.S. companies through a no-cost, non-exclusive license agreement and companion Space Act Agreement. Click the LEW-TOPS-162: Small Spacecraft Electric Propulsion (SSEP) Technologies link in the Additional Information section for details.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_158","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-158","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-158","confidence":"high"},"type":"patent","title":"High Propellant Throughput Small Spacecraft Electric Propulsion Thruster","abstract":"Innovators at NASAs Glenn Research Center have developed a suite of small spacecraft electric propulsion (SSEP) technologies critical to enabling new, ambitious missions into deep space. Advanced SSEP technologies are based on the use of exceptionally fuel-efficient electrostatic Hall effect thrusters with optimized magnetic shielding, achieving massive reductions in propellant mass relative to traditional chemical propulsion systems. NASAs low-power, high-throughput SSEP technology dramatically increases the capabilities of small spacecraft while maximizing reliability and reducing launch costs. The High Propellant Throughput Small Spacecraft Electric Propulsion thruster is available for licensing on its own, or as a component of NASAs SSEP suite, which is available to U.S. companies through a no-cost, non-exclusive license agreement and companion Space Act Agreement. Click the LEW-TOPS-162: Small Spacecraft Electric Propulsion (SSEP) Technologies link in the Additional Information section for details.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_159","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-159","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-159","confidence":"high"},"type":"patent","title":"Anode Manifold Plug for Hall Effect Thrusters","abstract":"Innovators at NASA\u2019s Glenn Research Center have developed a suite of small spacecraft electric propulsion (SSEP) technologies critical to enabling new, ambitious missions into deep space. Advanced SSEP technologies are based on the use of exceptionally fuel-efficient electrostatic Hall effect thrusters with optimized magnetic shielding, achieving massive reductions in propellant mass relative to traditional chemical propulsion systems. NASA\u2019s low-power, high-throughput SSEP technology dramatically increases the capabilities of small spacecraft while maximizing reliability and reducing launch costs. The Anode Manifold Plug for Hall Effect Thrusters technology is available for licensing on its own, or as a component of NASA\u2019s SSEP technology suite, which is available to U.S. companies through a no-cost, non-exclusive license agreement and companion Space Act Agreement. Click the LEW-TOPS-162: Small Spacecraft Electric Propulsion (SSEP) Technologies link in the Additional Information section for details.","category":"propulsion","categoryRaw":"Propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_162","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-162","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-162","confidence":"high"},"type":"patent","title":"Small Spacecraft Electric Propulsion (SSEP) Technology Suite","abstract":"The NASA Glenn Research Center (GRC) has expertise in small spacecraft electric propulsion (SSEP). NASA's SSEP project is developing technologies critical to expanding spacecraft capabilities and enabling ambitious new missions into deep space. Advanced SSEP technologies are based on the use of exceptionally fuel-efficient electrostatic Hall effect thrusters with optimized magnetic shielding. Low-power, high-throughput SSEP dramatically increases the capabilities of small spacecraft, and advanced magnetic circuit designs result in game-changing thruster performance. These advances can maximize reliability while minimizing launch cost. Innovators at GRC have developed a suite of SSEP technologies. GRC seeks commercial partners to help satisfy NASA exploration and science mission requirements while improving U.S. competitiveness in the global electric propulsion market and catalyzing innovation related to SSEP technology.","category":"propulsion","categoryRaw":"Propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_180","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-180","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-180","confidence":"high"},"type":"patent","title":"Improving Hybrid Electric Propulsion Efficiency","abstract":"Propulsion system engineers at NASA\u2019s Glenn Research Center have developed a novel method for increasing the efficiency of electrically driven propulsors by improving the range of operability against stall. Stall affects both compressor and propulsion fans and can be induced from a variety of operational conditions, often transient in nature. The incidence of stall conditions requires an operating margin between the stall point and the point of optimum operating efficiency, and typically, the compressor/propulsor fan operates at a lower efficiency point to increase the stall margin. Stall must be avoided to maintain thrust and in some cases to avoid catastrophic failure. While many researchers have explored stall control in the past, it remains a prevailing issue. This innovation integrates supercapacitors in the electric drive such that the drive can quickly modulate power to avoid stall. The electric motor system can also enable improved stall detection.","category":"propulsion","categoryRaw":"Propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_185","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-185","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-185","confidence":"high"},"type":"patent","title":"Efficient Megawatt-Scale Cable for Electric Aircraft Propulsion","abstract":"The electrification of aircraft is constrained by the limitations of conventional cabling. Transmitting megawatt-scale power requires cables that are not only lightweight but also capable of maintaining efficiency and insulation integrity at high altitudes. Standard high-voltage cables add excessive mass and suffer from reduced dielectric performance in low-pressure environments, making them unsuitable for large-scale electrified aviation. To overcome these challenges, innovators at NASA\u2019s Glenn Research Center have developed a new class of lightweight, cooled high-voltage cable designed specifically for aircraft electrification. This cable is a single system that can both power and cool the motors, generators, and other power electronics of an electrified aircraft . By combining electrical and thermal functionality in one integrated solution, the technology addresses critical barriers to scaling electric propulsion in aviation.","category":"propulsion","categoryRaw":"Propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_34","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-34","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-34","confidence":"high"},"type":"patent","title":"Hall Effect Thruster Technologies","abstract":"Innovators at NASA's Glenn Research Center have developed new technologies that increase the operational lifetime of a Hall effect thruster (HET), which is used primarily on Earth-orbiting satellites and can also be used for deep-space robotic vehicles. The operational lifetime of HETs is determined by the amount of time the thruster can operate before the plasma within the channel damages the magnetic system. Prior to this innovation, the plasma would erode the ceramic chamber of the HET in just over a year of operation. Glenn's breakthrough technology prolongs this operational lifetime through two related innovations. The first is an innovative magnetic field configuration that provides magnetic shielding to eliminate interactions between the high energy xenon plasma produced by the HET and the ceramic chamber that contains it. The second is a means of replacing eroded discharge channel material via a channel wall replacement mechanism. By increasing the lifetime and efficiency of HETs, Glenn's technology will enable a new era of space propulsion.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_74","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-74","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-74","confidence":"high"},"type":"patent","title":"Annular Ion Engine","abstract":"Innovators at NASA's Glenn Research Center have developed a breakthrough in ion thruster technology. The Annular Ion Engine (AIE) features an annular discharge chamber with a set of annular ion optics, potentially configured with a centrally mounted neutralizer cathode assembly. Compared to current state-of-the-art, cylindrically shaped ion thrusters, the AIE includes two primary advantages: 1) it enables scaling of ion thruster technology to high power at specific impulse (Isp) desirable for near-term missions, and 2) it provides a substantial increase in both thrust density and thrust-to-power (F/P) ratio. With its additional increase in lifetime service and improvements in packaging, Glenn's AIE represents the next generation of electric propulsion systems that require higher power, F/P, and efficiency, such as Solar Electric Propulsion (SEP) vehicles that may transport humans to the moon and Mars.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_130","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-130","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-130","confidence":"high"},"type":"patent","title":"Fast-Acting, Deep-Throttling Hybrid Motor","abstract":"NASA Marshall Space Flight Center and collaborators at Utah State University have developed a prototype for a highly efficient hybrid motor designed for spacecraft. This innovative motor addresses the need for both substantial propulsion during orbital maneuvers and precise control for attitude adjustments and stability. Hybrid motors offer a variety of advantages over traditional liquid and solid propulsion systems. Hybrid motor systems are significantly simpler than a liquid engine system, and offer safety gains and possible throttling capabilities compared to a solid rocket motor. However, the practical implementation of rapid throttling has presented significant challenges in the industry. The NASA motor tackles this hurdle by leveraging a digital valve technology, effectively reducing full-scale throttle time to one second or less and enabling the potential for rapid restart and short pulses of thrust. This hybrid motor technology holds promise for the future of space exploration and offers potential solutions for improved motors on low earth orbit spacecraft (commercial or government) as well as sounding rockets, missiles, and other systems.","category":"propulsion","categoryRaw":"Propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_85","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-85","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-85","confidence":"high"},"type":"patent","title":"Sublimable Propellant Source for Iodine-fed Ion Propulsion System","abstract":"NASAs Marshall Research Center has developed a system for generating iodine vapor from solid iodine, for use as a propellant in a Hall or ion thruster propulsion system. Xenon has generally been the preferred propellant of choice for these spacecraft ion propulsion systems, but more recently iodine-based systems have gained significant attention due to comparable performance to xenon, and the system-level advantages of low storage pressure and higher storage density with more propellant per unit volume. However the solid iodine, in comparison to gaseous xenon, must be sublimated into a vapor for ionization, and a heat source must be used to increase the sublimation rate of the solid iodine to a level that is useful for propulsive purposes. The subject innovation is a spring-loaded mechanism to optimize the contact of the solid iodine with the heated structure in the zero-gravity environment of space.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_93","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-93","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-93","confidence":"high"},"type":"patent","title":"A One-piece Liquid Rocket Thrust Chamber Assembly","abstract":"NASA is developing a lightweight one-piece regeneratively-cooled thrust chamber assembly (TCA) for liquid rocket engines. Liquid rocket engines create thrust through the expansion of combusted propellants within the TCA. Standard manufacturing of TCAs involves individually building the injector, main combustion chamber and nozzle, and then bolting or welding the components together at the joints. However, potential seal failures in these complex joints can cause catastrophic explosions, as in the tragedy of the Space Shuttle Challenger. NASA researchers are eliminating complex joints by manufacturing a 1-piece TCA utilizing 3D printing and large-scale additive manufacturing technologies to directly deposit the nozzle onto the combustion chamber. And, by replacing a traditional solid metal jacket with a composite overwrap for support, the overall weight is reduced by over 40%. Developed under the Rapid Analysis and Manufacturing Propulsion Technology (RAMPT) project, NASA seeks public-private partnerships to develop specialized large-scale additive manufacturing vendors and accelerate reliable spaceflight hardware to the US supply chain.","category":"propulsion","categoryRaw":"Propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ssc_tops_12","source":{"institution":"NASA","subUnit":"Stennis Space Center","subUnitCode":"SSC","nativeId":"SSC-TOPS-12","sourceUrl":"https://technology.nasa.gov/patent/SSC-TOPS-12","confidence":"high"},"type":"patent","title":"HYPERFIRE","abstract":"The two main sub-scale, ground-based rocket aerodynamics testing techniques hot-fire testing and cold-flow testing pose a series of tradeoffs. Hot-fire testing is generally much more accurate, but is often burdensome, costly, and requires long lead times due to design work, infrastructure preparation, etc. Cold-flow testing is much less expensive and has a rapid turnaround time, but conventional simulants (e.g., nitrogen, steam) used in cold-flow testing yield less accurate results (i.e., results that are not sufficiently representative of test article performance). While researching methods to optimize such tradeoffs, engineers at NASAs Stennis Space Center discovered that ethane can be tuned to approximate rocket exhaust plumes generated by several common rocket propellants. This led NASA to develop the HYdrocarbon Propellants Enabling Reproduction of Flows in Rocket Engines (HYPERFIRE), a sub-scale, non-reacting flow test system. HYPERFIRE uses heated ethane to enable physical simulation of rocket engines powered by a broad range of propellants in an inexpensive, accurate, and simple fashion.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_102","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-102","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-102","confidence":"high"},"type":"patent","title":"FlashPose: Range and intensity image-based terrain and vehicle relative pose estimation algorithm","abstract":"NASA Goddard Space Flight Center has developed FlashPose, a relative navigation measurement software and VHDL, for space flight missions requiring vehicle-relative and terrain-relative navigation and control. FlashPose processes real-time or recorded range and intensity images from 3D imaging sensors such as Lidars, and compares them to known models of the target surfaces to output the position and orientation of the known target relative to the sensor coordinate frame. FlashPose provides a relative navigation (pose estimation) capability to enable autonomous rendezvous and capture of non-cooperative space-borne targets. All algorithmic processing takes place in the software application, while custom FPGA firmware interfaces directly with the Ball Vision Navigation System (VNS) Lidar and provides imagery to the algorithm.","category":"robotics_automation","categoryRaw":"robotics automation and control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_170","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-170","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-170","confidence":"high"},"type":"patent","title":"Cooperative Service Valve for In-orbit Cooperative Satellite Fueling","abstract":"NASA Goddard Space Flight Center has developed the Cooperative Service Valve (CSV) to facilitate the resupply of media, such as propellants and pressurants, to satellites. The CSV replaces a standard spacecraft fill and drain valve. Spacecraft outfitted with the CSV enable in-orbit servicing with less risk, lower costs, and a much higher chance of success. The tools used to interface with the CSV, both on the ground and in space, were also designed and tested by NASA. The CSV architecture and approach is extensible to all space assets that could potentially be fueled/re-fueled on and off the ground, including manned crew vehicles, planetary rovers, and space habitats.","category":"robotics_automation","categoryRaw":"robotics automation and control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_190","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-190","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-190","confidence":"high"},"type":"patent","title":"Robotic gripper for satellite capture and servicing","abstract":"The robotic gripper was developed at NASA Goddard Space Flight Center as part of a robotic satellite servicing mission. The gripping device can be used to autonomously or remotely grasp and control an out-of-fuel or otherwise disabled satellite. Specifically, the gripper interfaces to the separation ring (marman ring) of the client spacecraft and when closed is sufficient to constrain all six degrees of freedom of motion between the servicing spacecraft and the client. The jaws are designed with a conformable geometry which allows the same Gripper to interface to all spacecraft separation rings commonly used with Atlas V and Delta IV launch vehicles.","category":"robotics_automation","categoryRaw":"robotics automation and control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_247","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-247","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-247","confidence":"high"},"type":"patent","title":"Robot-Driven Blind Mate Interface","abstract":"Many robot operations require connecting modules, tools, or other types of hardware to accomplish assembly or servicing tasks. When working in harsh environments, robots must be enabled to make these kinds of connections without human intervention. These robotic operations must be capable of surviving all kinds of harsh environments, from outer space to the deep sea. Additionally, robot operations must be suitable for many different structures and assemblies. As a result, there is a need for a reliable robot-friendly mechanism that allows structural, electrical, and fluid connections to be made. The Robot-Driven Blind Mate Interface is capable of providing connection mechanisms for a variety of couplings and can operate in harsh environments as well.","category":"robotics_automation","categoryRaw":"robotics automation and control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_341","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-341","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-341","confidence":"high"},"type":"patent","title":"Client Berthing System (CBS)","abstract":"Historically, satellites that stop functioning due to depleted propellant, system failures, etc., are decommissioned and replaced with a newly built satellite. However, the cost and logistical complexity of satellite replacement is significant, meaning life extension via in-orbit satellite servicing (e.g., refueling, component repair / replacement) is increasingly desirable. NASA\u2019s Exploration & In-space Services (NExIS) division is at the forefront of satellite servicing technology development, leading the push into an era of more sustainable, affordable, and resilient spaceflight. NeXIS has developed a suite of technologies to enable the production of a satellite servicing spacecraft capable of autonomous rendezvous, docking, and servicing of satellites \u2013 including legacy satellites not designed or intended to be serviced. A key component of this suite is the Client Berthing System (CBS), a mechanical subsystem designed to rigidly berth and attach a client spacecraft to a servicing vehicle in-orbit for subsequent servicing.","category":"robotics_automation","categoryRaw":"Robotics Automation and Control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_351","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-351","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-351","confidence":"high"},"type":"patent","title":"New motors for next-generation in-space servicing","abstract":"Brushless direct current (BLDC) motors are of interest to drive tools for in-space servicing due to their reliability, efficiency, and controllability. Current BLDC motors do not meet the needs of space environments, nor do they have common interfaces, limiting their versatility. NASA inventors have developed four BLDC motors to power a variety of tools for in-space servicing. The motors are part of the Advanced Tool Drive System (ATDS) that is attached to the end of a robotic arm providing the power for the servicing tools. While the motors have differing performance characteristics to drive various tools, they have been designed with a common gearhead for versatility within a single frame size. The motors are built to withstand the wide temperature variations and radiation conditions of geosynchronous orbit. The BLDC motors and the ATDS will be used for spacecraft servicing in manned and unmanned missions and may also apply to terrestrial robotic systems.","category":"robotics_automation","categoryRaw":"Robotics Automation and Control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_360","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-360","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-360","confidence":"high"},"type":"patent","title":"Visual Inspection Posable Invertebrate Robot (VIPIR)","abstract":"On-orbit spacecraft maintenance and repair of components are critical for extending mission lifespans and ensuring operational safety. Traditional inspection methods, like astronaut extravehicular activities (EVAs), are risky and resource-intensive, while fixed cameras offer limited views. To address these challenges, innovators at NASA\u2019s Goddard Space Flight Center developed the Visual Inspection Posable Invertebrate Robot (VIPIR) system, a tele-operated robotic imaging system offering advanced capabilities for visual assessments of space-based assets. VIPIR is a significant leap forward in the realm of on-orbit robotic inspection, evaluation, and servicing systems. Integrating a dexterous, flexible video borescope with advanced articulation mechanisms, VIPIR allows NASA to remotely inspect spacecraft components that would otherwise be difficult or impossible to view, enabling subsequent repairs and maintenance.","category":"robotics_automation","categoryRaw":"Robotics Automation and Control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_6","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-6","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-6","confidence":"high"},"type":"patent","title":"Algorithms for stabilizing intelligent networks","abstract":"Inspired by psychology, these algorithms could be developed and applied towards creating stable, predictable, and artificially intelligent networks. These algorithms collectively represent ways for intelligent systems to identify and correct unpredictable or unstable behaviors, creating stable emotional states that govern behaviors with given specific circumstances, and establishing an evolvable synthetic neural network that can eventually be scaled from low-level functions to higher level decision making processes. These algorithms could be key to research in autonomous spacecraft , nanorobotic swarms, and sensor networks.","category":"robotics_automation","categoryRaw":"robotics automation and control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_7","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-7","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-7","confidence":"high"},"type":"patent","title":"Regolith Advanced Surface Systems Operations Robot (RASSOR) Excavator","abstract":"NASA Kennedy Space Center seeks partners interested in the commercial application of the Regolith Advanced Surface Systems Operations Robot (RASSOR) Excavator. NASAs Kennedy Space Center is soliciting licensees for this innovative technology. RASSOR is a teleoperated mobile robotic platform with a unique space regolith excavation capability. Its design incorporates net-zero reaction force, thus allowing it to load, haul, and dump space regolith under extremely low gravity conditions with high reliability. With space transportation costs hovering at approximately $4,000 per pound and tight launch vehicle shroud constraints, this compact, lightweight unit enables the launch of an efficient, rugged, versatile robotic excavator on precursor landing missions with minimum cost. RASSOR could also be scaled up and used for terrestrial mining operations in difficult-to-reach or dangerous locations.","category":"robotics_automation","categoryRaw":"Robotics Automation and Control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_243","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-243","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-243","confidence":"high"},"type":"patent","title":"Safe2Ditch Technology","abstract":"Highly capable small UAVs provide substantial business opportunity, especially if allowed to operate in the suburban market. Reliability issues force the use of a safety pilot for each vehicle in operation, which is cost-prohibitive for large scale commercial applications and limits the use of these vehicles to line-of-site (LOS) operation. Extending the use of small UAVs to beyond visual-line-of-sight (BVLOS) and to fleet operations requires a vehicle system to autonomously perform emergency management activities as a replacement to the human pilot to maintain safety to people and property in populated areas.","category":"robotics_automation","categoryRaw":"robotics automation and control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_265","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-265","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-265","confidence":"high"},"type":"patent","title":"In-situ Characterization and Inspection of Additive Manufacturing Deposits using Transient Infrared Thermography","abstract":"Researchers at NASA Langley Research Center have developed a much more reliable non-destructive evaluation method based on infrared thermography. The method provides transient temperature profiles of the surface, including the melt pool, at each step/layer. This system can measure material properties and detect defects during the additive manufacturing process. It will allow for characterization of the deposition quality and also detection of deposition defects such as voids, crack, and disbonds as the structure is manufactured layer by layer. The information, in the form of quantitative inspection images, can be archived with the manufactured part to document structural integrity. This is a more effective way of determining flaws or deposition quality during the build process.","category":"robotics_automation","categoryRaw":"robotics automation and control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_307","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-307","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-307","confidence":"high"},"type":"patent","title":"Powerline Geolocation","abstract":"The technology leverages the electrical conductors employed in power transmission for signal transmission for geolocation. Unmanned aerial vehicles have the capability to inspect high-voltage conductors and associated structures from points of view that are not available to ground-based or helicopter-based crews. In order to geolocate its position, such a vehicle relies on one or more navigation systems including: GPS, inertial measurement unit systems (IMUs), or image recognition. Geolocation accuracy via image recognition suffers from changes in lighting (e.g., time of day and weather variations) and from changes in the scene (e.g., foliage changes in spring vs. winter). Inertial systems suffer from positional drift which currently occurs on the order of minutes for compact systems. GPS suffers from multipath affects near metallic structures (which are ubiquitous in transmission line infrastructure), from satellite loss due to horizon blockage (the stadium effect), from electromagnetic interference on the radio band of GPS transmissions, and, most fundamentally, from loss of the GPS transmission by the orbital satellites. Powerline conductors are capable of transmitting signals which could be used for geolocation to aid in navigation.","category":"robotics_automation","categoryRaw":"robotics automation and control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_33","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-33","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-33","confidence":"high"},"type":"patent","title":"Low Weight Flight Controller Design","abstract":"NASA's Langley Research Center has developed a new sensing and control system for unmanned aerial vehicles (UAVs) that allows for semi-autonomous flight . With this technology, pilots need not leave the ground to conduct routine monitoring and surveillance quickly and cost-effectively. Such systems are particularly useful during long flight segments or over remote locations, or for scientific applications such as atmospheric monitoring or crop monitoring, which might require long and repeated sampling in a specific pattern. The small, lightweight technology can be quickly adapted to your specific configuration.","category":"robotics_automation","categoryRaw":"robotics automation and control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_345","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-345","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-345","confidence":"high"},"type":"patent","title":"Assemblers","abstract":"In-space and planetary surface assembly for human exploration is a challenging domain that encompasses various technological thrusts to support human missions. NASA is developing autonomous assembly agents to build structures like habitats and antennae on the Moon. These modular and reconfigurable Assembler robots will provide robotic assembly of structures, even in locations that prohibit constant human oversight and teleoperation. This system is capable of scheduling, reconfiguring, and executing structural assembly tasks; assessing construction; and correcting errors in assembly as needed. On command, the Assemblers stack themselves into robot team members for the task. For example, a few Assemblers might build a solar array as shown in the above image. The Assembler technology builds upon recent advancements in lightweight materials , state estimation, modern control theory, and machine learning. The Assembler technology builds upon recent advancements in multi-agent planning, state estimation, modern control theory, and machine learning. Compared with existing short-reach/high-accuracy and long-reach/low accuracy-assembly robots, Assemblers provides both long- and short-reach capability with accuracy and precision. NASA has developed a prototype of the technology and seeks companies that are interested in licensing the technology and commercializing it for space or other applications.","category":"robotics_automation","categoryRaw":"Robotics Automation and Control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_361","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-361","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-361","confidence":"high"},"type":"patent","title":"Lunar Surface Navigation System","abstract":"Scientists at NASA\u2019s Langley Research Center have developed a novel concept for a lunar navigation system based on the reverse-ephemeris technique. Typically, range related signal measurements from the earth\u2019s surface are used to locate and track orbital objects (satellites) and establish the ephemeris describing their orbits. For this reverse-ephemeris lunar navigation concept, the process is reversed to give lunar surface position fixes using the known ephemeris of a satellite in lunar orbit. Only a few inexpensive smallsats are required in order to implement a lunar navigation system based on this concept. Lunar navigation systems will be needed for future moon missions, including for example for rover navigation, mining operations, exploration, etc. The inventors have conducted analytical simulations to demonstrate the versatility of this innovation when used to support route determination for various autonomous or manned lunar surface operations.","category":"robotics_automation","categoryRaw":"Robotics Automation and Control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_401","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-401","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-401","confidence":"high"},"type":"patent","title":"Single-Action-Lock Structural Space Joint","abstract":"On Earth, most joining systems are effective in human centric environments with virtually unlimited joining supplies. As an assembly agent, a human possesses two 27 degree-of-freedom (DOF) hands, each attached to a 7 DOF arm, all mobilized by an adaptive human body. Humans can complete complex assembly tasks that may be hindered by physical obstructions. However, robotic systems remain the preferred workforce for future in-space assembly missions, offering lower cost, reduced risk, and minimized operational overhead. In-space structure assembly is still constrained by the finite availability of joining supplies and the limited dexterity of robotic manipulators Innovators at NASA's Langley Research Center have developed a novel Single-Action-Lock Structural Space (SSS) Joint designed for use in robotic assembly or humans in spacesuits with limited range of movement. This joint system addresses the critical need for simplified, reliable, and tool-minimal connections in environments where dexterity is constrained and every component must be optimized for mass, volume, and operational efficiency.","category":"robotics_automation","categoryRaw":"Robotics Automation and Control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_404","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-404","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-404","confidence":"high"},"type":"patent","title":"High Stiffness Self Leveling Platform","abstract":"Leveling platforms are critical for orienting equipment in environments where uneven terrain can compromise performance. Conventional solutions often rely on manual adjustment or lightweight designs intended for small instruments, which limits their usefulness for heavy-duty applications. These approaches can be cumbersome, time-consuming, and prone to error, creating inefficiencies and safety risks in industries that demand precision and reliability. Automated systems exist, but they are typically large, complex, and costly, leaving a gap for a compact, robust solution that can operate effectively in challenging conditions. Recognizing this need, NASA's Langley Research Center developed an innovative approach to automated leveling, called the High Stiffness Self Leveling Platform (HSSLP) that addresses the shortcomings of prior systems. Originally conceived to orient cranes for lunar surface operations, this technology was designed to provide a stable foundation for payload handling and offloading in dynamic environments. Beyond its aerospace origins, the concept offers strong commercial potential for terrestrial applications where precise leveling is essential, such as construction, surveying, renewable energy, and remote film production, allowing users to deploy equipment quickly, maintain alignment on uneven terrain, and improve operational safety without manual intervention.","category":"robotics_automation","categoryRaw":"Robotics Automation and Control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_73","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-73","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-73","confidence":"high"},"type":"patent","title":"Lunar Surface Manipulation System","abstract":"NASA's Langley Research Center offers a novel lifting and precision positioning device with hybrid functional characteristics of both crane-type lifting devices and robotic manipulators. The design of the Lunar Surface Manipulation System (LSMS) allows for fine positioning with complete control over both translation and rotation of the payload. In addition, the design permits several other operations using a wide variety of special purpose tools, such as a bucket, pallet forks, grappling devices, sensor and visualization packages, and dexterous robotic arms that can be quickly added to the tip. NASA is seeking development partners and potential licensees.","category":"robotics_automation","categoryRaw":"robotics automation and control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_105","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-105","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-105","confidence":"high"},"type":"patent","title":"Robotic Assembly of Photovoltaic Arrays","abstract":"NASA researchers have developed a novel process for assembling thin-film solar cells into larger solar arrays. Current methods for solar array manufacturing depend on time-consuming, manual assembly of solar cells into multi-cell arrays. Print-assisted photovoltaic assembly (PAPA) is an assembly process that leverages robotic automation to build fully functional flexible thin-film solar arrays. By increasing manufacturing efficiency, PAPA's no-touch technology can reduce labor costs, decrease time-to-market, and enable assembly of large-scale solar arrays of over 500kW. This increased efficiency can help meet growing demand for large solar arrays in residential and satellite applications. Compatible with all currently available thin-film and 3D-printed solar cell materials, PAPA is capable of integrating with current and future solar cell technologies. NASA is seeking licensees that may benefit from low-cost, automated assembly of large-scale solar arrays.","category":"robotics_automation","categoryRaw":"Robotics Automation and Control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_mfs_tops_74","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-TOPS-74","sourceUrl":"https://technology.nasa.gov/patent/MFS-TOPS-74","confidence":"high"},"type":"patent","title":"Gimbal for Steering Propelled CubeSats","abstract":"NASA is preparing for the next generation of CubeSats that are propelled and will make directional maneuvers. The new gimbal mount provides a seat for the motor and controls the position of the thrusters that propel the CubeSat as it moves about and/or changes orbits. This small-footprint device controls the rotation (360 degrees) and tilt (+/- 12 degrees) of a directional system to a very high accuracy (0.02 degrees). It alleviates the need for more traditional directional control hardware, including magnetorquers and magnetometers. The gimbal controls larger masses for its size than other positioning systems. It has a low parts count (six) and can support up to 0.5 kg mass. NASA built a prototype and conducted several tests to prove its control and precision capabilities, and its ability to withstand vibration testing. Now NASA seeks companies to commercialize the gimbal.","category":"robotics_automation","categoryRaw":"robotics automation and control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_101","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-101","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-101","confidence":"high"},"type":"patent","title":"Advanced Humanoid Robotic Arm Technologies","abstract":"NASA and General Motors, two organizations at the forefront of robotics, have developed the Robonaut 2 (R2) \u2013 a state-of-the-art, dexterous, humanoid robot capable of performing tasks in an automated fashion (or via teleoperation). The technology developed throughout the project represents the cutting edge of autonomous, humanoid robotics. These technologies are available for licensing, both in a modular framework or as an integrated system, to enhance your robotic products. R2\u2019s 5 Degrees of Freedom (DoF) arms, the topic of this flyer, use series elastic actuation to provide improved shock tolerance, accurate and stable force control, and beneficial energy storage capacity. An impedance controller limits the stiffness of the arms, ensuring workspace safety in scenarios where humans and robots are working in the same environment.","category":"robotics_automation","categoryRaw":"Robotics Automation and Control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_102","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-102","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-102","confidence":"high"},"type":"patent","title":"Advanced Humanoid Robotic Hand Technologies","abstract":"NASA and General Motors, two organizations at the forefront of robotics, have developed the Robonaut 2 (R2) \u2013 a state-of-the-art, dexterous, humanoid robot capable of performing tasks in an automated fashion (or via teleoperation). The technology developed throughout the project represents the cutting edge of autonomous, humanoid robotics. These technologies are available for licensing, both in a modular fashion or as an integrated system, to enhance your robotic products. Please see the Related Links section below for information on additional R2 robotics technologies, including those related to arms, interface/control, and sensor systems. R2\u2019s hand and forearm assembly, the topic of this flyer, is designed to approximate closely the capabilities of the human hand. The assembly is a completely self-contained unit featuring high dexterity, fine force control, and advanced sensing that enables the grasping and actuation of a broad array of tools. Relocation of components (e.g., motors, avionics) to the forearm makes room for increased sensing in the fingers and palm, where it is needed most.","category":"robotics_automation","categoryRaw":"Robotics Automation and Control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_103","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-103","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-103","confidence":"high"},"type":"patent","title":"Advanced Humanoid Robotic Interface & Control","abstract":"NASA and General Motors, two organizations at the forefront of autonomous robotics, have developed the Robonaut 2 (R2) \u2013 a state-of-the-art, dexterous, humanoid robot capable of performing tasks in an automated fashion (or via teleoperation). The technology developed throughout the project represents the cutting edge of autonomous, humanoid robotics. These technologies are available for licensing, both in a modular fashion or as an integrated system, to enhance your robotic products. Please see the Related Links section below for information on additional R2 robotics technologies, including those related to hands, arms, and sensor systems. Advanced interface and control technologies, the topic of this flyer, allow R2 (and other humanoid robotics) to achieve safe and effective autonomous or teleoperation-based control. Interfaces enable simple control, while additional control systems ensure safe robot-human interactions, monitor the health of the robotic system, provide fail-safe breaks for robotic electric motors, and ensure electrical connectivity throughout a wide range of potential motions.","category":"robotics_automation","categoryRaw":"Robotics Automation and Control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_104","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-104","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-104","confidence":"high"},"type":"patent","title":"Advanced Robotic Sensing Technologies","abstract":"NASA and General Motors, two organizations at the forefront of autonomous robotics, have collaborated to develop Robonaut 2 (R2) \u2013 a state-of-the-art, dexterous, humanoid robot capable of performing tasks in an automated fashion (or via teleoperation). The technology developed throughout the project represents the cutting edge of autonomous, humanoid robotics. These technologies are available for licensing, both in a modular fashion or as an integrated system, to enhance your robotic products. Please see the Related Links section below for information on additional R2 robotics technologies, including those related to hands, arms, and interface/control systems. Designing a humanoid robot with human-like sensory and perception systems requires an extensive sensor suite (R2 has over 350 integrated sensors). Several novel sensors were developed to accomplish this goal, including a flexible perception system, tendon tension sensor , contact state estimation sensor , and load sensors in the fingers that give R2 its tactile sense (i.e., sense of \u201ctouch\u201d).","category":"robotics_automation","categoryRaw":"Robotics Automation and Control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_113","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-113","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-113","confidence":"high"},"type":"patent","title":"Circumferential Scissor Spring Enhances Precision in Hand Controllers","abstract":"Innovators at NASA Johnson Space Center have designed a circumferential scissor spring mechanism, that when incorporated into a hand controller, improves the restorative force to a control stick\u2019s neutral position. The design also provides for operation on a more linear portion of the spring's force deflection curve, yielding better feedback to the user. Physical hand controllers, such as translational and rotational controllers, use a non-circumferential scissor spring arrangement to return the control stick to a neutral position, but the linear response of a typical scissor spring arrangement can reduce a user\u2019s sense of control by allowing slack between deflections. This innovation\u2019s design is driven by a spring mechanism whereby an expansion spring is looped around the channeled circumference of two rounded pivoting blades whose setup can be tuned to allow varying spring tension. This allows the user enhanced control stick sensitivity while operating drive systems, industrial automation, measuring technology, mobile machinery, and gaming systems. This technology is currently implemented on NASA\u2019s Orion Spacecraft training simulators using three-axis hand controllers.","category":"robotics_automation","categoryRaw":"Robotics Automation and Control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_129","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-129","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-129","confidence":"high"},"type":"patent","title":"Anonymous Feature Processing for Enhanced Navigation","abstract":"Innovators at NASA Johnson Space Center have developed an innovative algorithmic and computational approach to vision-based feature recognition called Anonymous Feature Processing (AFP). The \u2018anonymous\u2019 approach allows feature-based navigation techniques to be performed without the need for explicit correspondence/identification between visual system observations and cataloged map data, thus helping to eliminate costs and risks induced by identification procedures. By eliminating the error-prone and computationally burdensome identification and detection steps, AFP is designed to yield marked improvements in system robustness along with reducing algorithmic and software development costs. This novel method only requires a simple camera, or LIDAR sensor, and flight computer to track multiple targets and navigate vehicles more quickly, reliably, and safely. The AFP approach is adaptable to a wide range of sensor types and platforms, capable of supporting challenging space exploration and terrestrial navigation systems with low visibility conditions or with cluttered surroundings. A new technique such as AFP that eliminates preprocessing while adding system robustness could have commercial applications in autonomous vehicles, manufacturing, and research-based imaging.","category":"robotics_automation","categoryRaw":"Robotics Automation and Control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_37","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-37","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-37","confidence":"high"},"type":"patent","title":"Robo-Glove","abstract":"Researchers at the NASA Johnson Space Center (JSC) in collaboration with General Motors (GM) have designed and developed Robo-Glove, a wearable human grasp assist device, to help reduce the grasping force needed by an individual to operate tools for an extended time or when performing tasks having repetitive motion. Robo-Glove has the potential to help workers, such as construction workers, hazardous material workers, or assembly line operators, whose job requires continuous grasping and ungrasping motion. The Robo-Glove also has potential applications in prosthetic devices, rehabilitation aids, and people with impaired or limited arm and hand muscle strength. This NASA Technology is available for your company to license and develop into a commercial product. NASA does not manufacture products for commercial sale.","category":"robotics_automation","categoryRaw":"Robotics Automation and Control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_38","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-38","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-38","confidence":"high"},"type":"patent","title":"Robonaut 2 Technologies","abstract":"Researchers at NASA's Johnson Space Center (JSC), in collaboration with General Motors and Oceaneering, have designed a state-of-the-art, highly dexterous, humanoid robot: Robonaut 2 (R2). R2 is made up of multiple component technologies and systems: vision systems, image recognition systems, sensor integrations, tendon hands, control algorithms, and much more. R2's nearly 50 patented and patent-pending technologies have the potential to be game-changers in multiple industries, including logistics and distribution, medical and industrial robotics, as well as hazardous, toxic, or remote environments. This NASA Technology is available for your company to license and develop into a commercial product. NASA does not manufacture products for commercial sale.","category":"robotics_automation","categoryRaw":"Robotics Automation and Control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_46","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-46","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-46","confidence":"high"},"type":"patent","title":"Robonaut 2: Logistics and Distribution","abstract":"Researchers at the NASA Johnson Space Center (JSC), in collaboration with General Motors and Oceaneering, have designed a state-of-the-art, highly dexterous, humanoid robot: Robonaut 2 (R2). R2's nearly 50 patented and patent-pending technologies have the potential to be game-changers in multiple industries including logistics and distribution. Even though R2 is currently designed with only a mobile upper body, R2's ability to accomplish complex and delicate operations provides a higher level of sophistication not currently seen in the existing robotics field for logistics and distribution. In terms of handling inventory, R2's dexterity would allow it to handle a multitude of items, including delicate ones. R2 can safely work in close proximity to humans, making the robot suitable to work in complex environments such as distribution centers. R2 has the ability to operate equipment and machines designed for humans, like hand-held power tools or inventory-scanning equipment. R2's design enables many useful applications in logistics and distribution.","category":"robotics_automation","categoryRaw":"robotics automation and control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_70","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-70","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-70","confidence":"high"},"type":"patent","title":"Robotic System for Infra-structure Reconnaissance","abstract":"Innovators at NASA Johnson Space Center have developed a robotic system whose primary structural platform, or \u201corb\u201d, can be injected into a pipe network and perform reconnaissance of piping infrastructure and other interior volumes. When deployed, this technology uses throttled fluid flow from a companion device for passive propulsion . A tethered line facilitates directional control by the orb\u2019s operator, allowing it to navigate through various piping configurations, including 90-degree junctions. Inspired by NASA\u2019s Robonaut program for space applications, this technology was developed to facilitate a cost-effective method to inspect deep underwater oil wells residing under oceanic drilling platforms slated for decommission. Instead of initiating an expensive and environmentally risky operation to perforate the containment system of an underwater oil well to inspect its contents, the orb can be navigated through existing pipe networks to conduct real-time video and sonar investigations. The modular orb design accepts a variety of plug-and-play sensors along with a potential sample retrieving device, making it adaptable to different environments. Its housing can be easily disassembled in the field, enabl-ing a change or maintenance of its sensors or electronics. Because piping exists in a myriad of industries, such as in refineries, manufacturing and power plants, sewage systems, etc., plant operators could need a cost-effective reconnaissance device of this nature.","category":"robotics_automation","categoryRaw":"Robotics Automation and Control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_74","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-74","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-74","confidence":"high"},"type":"patent","title":"Modular Robotic Vehicle (MRV)","abstract":"Innovators at the NASA Johnson Space Center in collaboration with an automotive partner have developed the Modular Robotic Vehicle (MRV). This fully electric vehicle is well-suited for busy urban environments, industrial complexes, or large resort areas. The MRV combines a number of innovative technologies that are available for licensing as a whole system or individually as components. The MRV has no mechanical connections to the propulsion , steering, or brake actuators-- instead the driver relies on control inputs being converted to electrical signals and transmitted by wire to the motors within the vehicle. The MRV has a fully redundant, fail-operational architecture that is paramount to the safe operation of a by-wire system. The MRV is driven by four independent wheel modules, called e-corners. Each e-corner can be rotated +/- 180 degrees about its steering axis. Imagine being able to parallel park by simply driving sideways into a tight spot with ease. With the new MRV technology, this dream is now a reality.","category":"robotics_automation","categoryRaw":"robotics automation and control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_76","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-76","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-76","confidence":"high"},"type":"patent","title":"Precision Low Speed Motor Controller","abstract":"Innovators at the NASA Johnson Space Center have developed a method for controlling precise motion of a Brushless DC (BLDC) motor using relatively inexpensive components. Precision motors are usually quite expensive and inefficient when operating at slow speeds. This technology uses a method to control BLDC motors over a broad range of speeds, ranging from about 0.025 rpm to about 7000 rpm. Its ability to operate at these ranges and with high precision provides an opportunity to integrate this technology to many applications and industries. Commercial motors may employ this technology to extend their dynamic range. This technology can also be integrated into surgical robots that require advanced precision motion control systems. Hybrid and electrical vehicles can integrate this technology to their operating system to improve efficiencies.","category":"robotics_automation","categoryRaw":"Robotics Automation and Control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_80","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-80","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-80","confidence":"high"},"type":"patent","title":"Space Suit RoboGlove (SSRG)","abstract":"Innovators at NASA Johnson Space Center (JSC) have created an enhanced second-generation, robotically assisted extravehicular activity (EVA) glove. The SSRG has been engineered to further decrease the exertion required to do complex, hand-intensive EVA tasks and reduce the risk of astronaut hand injury. Originating from its predecessors, the NASA/General Motors RoboGlove, and the later first-generation Space Suit RoboGlove, the SSRG realizes improved sensing, control, interface, and avionics capabilities. Among these improvements is the implementation of a \u201cpower steering mode\u201d, which allows the user to position his/her fingers in an arbitrarily chosen position and receive assistance in holding that position. The SSRG retains the ability to operate like a conventional space suit glove while the actuators are unpowered. The design intent for the SSRG is to enhance a user\u2019s ability to perform human scale work, with considerations for speed, power, durability, dexterity, and ease of operation.","category":"robotics_automation","categoryRaw":"Robotics Automation and Control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_85","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-85","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-85","confidence":"high"},"type":"patent","title":"Upper Body Robotic Exoskeleton","abstract":"Innovators at the NASA Johnson Space Center (JSC) have developed a soft, wearable, robotic upper limb exoskeleton garment designed to actively control the shoulder and elbow, both positioning the limb in specific orientations and commanding the limb through desired motions. The invention was developed to provide effective upper extremity motor rehabilitation for patients with neurological impairments (e.g., traumatic brain injury, stroke). Due to its portable, battery-compatible design, NASA's garment allows for task-specific and intensive motor practice, an important part of rehabilitation for such patients, to be performed outside clinical environments (including in the home). In addition to upper extremity motor rehabilitation, the technology may also find applications in human performance augmentation, including in future spacesuit designs.","category":"robotics_automation","categoryRaw":"Robotics Automation and Control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_213","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-213","sourceUrl":"https://technology.nasa.gov/patent/TOP2-213","confidence":"high"},"type":"patent","title":"Monitoring and Control of Each Nanosatellite within a Cluster of Nanosatellites","abstract":"NASA has developed an innovative combination of a Magnetometer, low-powered ElectroMagnets, and Resonant Inductive Coupling (MEMRIC) to create and control relative positioning of nano satellites within a cluster. This is a game-changing approach to enable distributed nanosatellite (nanosat) clusters. The focus is on low-cost propulsion , navigation, and power sharing. Each of these functions can share the same basic technology. With the combination of a magnetometer, low-power electromagnets, and resonant inductive coupling, several nanosats can be clustered without the need of propellant-based propulsion systems, or GPS for relative positioning. By separating distinct subsystems into their own nanosat and producing them as generic, off-the-shelf components, the mission-design process is simplified, enabling the selection of the number of subsystem components that is most beneficial to the mission. The cost saving in the design cycle will pay for the extra, off-the-self power unit.","category":"robotics_automation","categoryRaw":"robotics automation and control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_240","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-240","sourceUrl":"https://technology.nasa.gov/patent/TOP2-240","confidence":"high"},"type":"patent","title":"Residual Mode Filters","abstract":"NASA has developed a unique control algorithm and synthesis method that uses a system's output to modify control inputs to cause the system to track a reference model or a fixed value in the presence of unmodeled system dynamics, varying operating environments and unpredictable disturbances. The unique feature of this algorithm is the ability to instantaneously adapt the system according to its output, rejecting persistent disturbances, and ultimately improving the systems performance. This makes the controller ideally suited for applications where there are unknown modelling parameters or uncertain operating environments. Many aerospace systems must function in unknown or highly variable environments. This technology allows the system to achieve its objectives in these types of unpredictable environments. In comparison to current adaptive controller technologies, the addition of residual mode filters allows operation when flexible modes are present that could inhibit the controller. This is especially useful for systems where initial modeling is costly or the fidelity of existing system models is low.","category":"robotics_automation","categoryRaw":"robotics automation and control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_265","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-265","sourceUrl":"https://technology.nasa.gov/patent/TOP2-265","confidence":"high"},"type":"patent","title":"Low Cost Star Tracker Software","abstract":"A star tracker or similar navigation device is needed for a Small Spacecraft , to provide highly accurate attitude information and to determine location and velocity vectors. NASA has developed a novel technology, a star tracker, as part of its extremely low cost commercial-off-the-shelf (COTS) hardware project. It uses relatively low power, is highly accurate, and is relatively inexpensive, uses an iterative pattern matching approach to identify a star configuration and associated spatial viewing direction in a database that corresponds to an observed star configuration. Orientation of a star configuration is confirmed by comparison of measured angular differences with angular differences contained in a database. Star configurations viewed from a polyhedrron defined by two, three, four or more non-coincident planes can be used to estimate a three-dimensional viewing direction of the polyhedron.","category":"robotics_automation","categoryRaw":"robotics automation and control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_267","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-267","sourceUrl":"https://technology.nasa.gov/patent/TOP2-267","confidence":"high"},"type":"patent","title":"Cost Optimized Test of Spacecraft Avionics and Technologies(COTSAT) Modular Spacecraft Software Architecture","abstract":"The Cost Optimized Test of Spacecraft Avionics and Technologies (COTSAT) was specifically developed to reduce the cost of designing and building spacecraft technologies while enabling rapid prototyping. The prototype spacecraft , also known as CheapSat, is the first of what could potentially be a series of rapidly produced low-cost spacecraft for science experiments and technology demonstration. The spacecraft platform is designed to accommodate low-cost access to space for variable remote-sensing payloads, while maintaining an architecture allowing future expansion for potential Space Life Sciences payloads.","category":"robotics_automation","categoryRaw":"robotics automation and control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_277","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-277","sourceUrl":"https://technology.nasa.gov/patent/TOP2-277","confidence":"high"},"type":"patent","title":"Airborne Machine Learning Estimates for Local Winds and Kinematics","abstract":"Future Unmanned Aerial Systems (UAS) and air taxis will require advanced onboard autonomy to operate safely within complex and dynamic urban environments. Urban landscapes are dynamic and constantly evolving. In addition to multi-directional, intense, and seemingly unpredictable winds often created in urban canyons, an exact knowledge of current building sizes, shapes, and positions is also often unavailable for real-time navigation. NASA Ames has developed a novel system, MAESTRO: MAchine learning ESTimations for uRban Operations, which not only improves the flight safety of UAS and air taxis in complex dynamic environments but also allows them to make smart and rapid on-board estimations of the local surrounding winds and vehicle kinematics using commercial off-the-shelf (COTS) sensors and advanced onboard computing.","category":"robotics_automation","categoryRaw":"Robotics Automation and Control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_281","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-281","sourceUrl":"https://technology.nasa.gov/patent/TOP2-281","confidence":"high"},"type":"patent","title":"Adaptive wind estimation for small unmanned aerial systems using motion data","abstract":"Small Unmanned Aerial Systems (sUAS) are becoming increasingly popular for research, commercial, and military usage due to their affordability resulting from their small size, low cost and simple hardware structure. Their lightweight structure and limited power make the sUAS vulnerable to wind disturbances, and hence difficult for accurate navigation and control outdoors, especially in urban environment where the wind field is more complex and has more uncertainties. NASA Ames has developed a unique and novel technology that provides fast and reliable estimation of the wind and related aerodynamic drag components for the sUAS without requiring expensive measurement components and computational power. The technology is a method to provide safe navigation and control capabilities for the multi-rotor drones in an urban wind field. It provides the critical aspects of the uses of sUAS, which is reliability while maintaining simplicity in design.","category":"robotics_automation","categoryRaw":"Robotics Automation and Control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_310","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-310","sourceUrl":"https://technology.nasa.gov/patent/TOP2-310","confidence":"high"},"type":"patent","title":"Reversible Androgynous Mechanical Fastener","abstract":"Researchers at NASA Ames Research Center have developed an androgynous fastener with high misalignment tolerance characteristics, which is suitable for robotic actuation. This fastener was developed in conjunction with a high-performance building-block structural system that can be robotically assembled by robust collective automated assembly into large, reconfigurable structures ranging from assembly of lunar habitats to terrestrial structures. The fastener mechanisms employ alignment principles similar to the International Berthing and Docking Mechanism (IBDM) in order to relax the positioning requirements of the assembly robots. This novel androgynous fastener provides the desired performance required for robotic assembly of the structural systems and also minimizes or eliminates the problems and disadvantages associated with conventional or traditional fasteners.","category":"robotics_automation","categoryRaw":"Robotics Automation and Control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_315","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-315","sourceUrl":"https://technology.nasa.gov/patent/TOP2-315","confidence":"high"},"type":"patent","title":"Method for discrete assembly of Cuboctahedron Lattice Materials","abstract":"Aeronautical and aerospace applications require strong and stiff lightweight materials and structures. The invention relates to a construction system for mechanical metamaterials based on discrete assembly of a finite set of types of parts, which can be assembled in varying orders to produce spatial variation in a range of properties such as rigidity, and auxetic behavior. This system achieves desired material properties through design of the parts such that global behavior is governed by local mechanisms. The invention describes the design methodology, production process, modeling, and experimental characterization of metamaterial behaviors. This approach benefits from incremental assembly that eliminates system deployment scale limitations, best-practice manufacturing of components for reliable, low-cost production, and interchangeability through the use of a consistent assembly process across part types.","category":"robotics_automation","categoryRaw":"Robotics Automation and Control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_321","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-321","sourceUrl":"https://technology.nasa.gov/patent/TOP2-321","confidence":"high"},"type":"patent","title":"Robotic system for assembly and maintenance of lightweight reconfigurable structures","abstract":"Missions to the moon and other planets will require large-scale infrastructure that would benefit from autonomous assembly by robots without on-site human intervention. Modular and reconfigurable structures, such as those built from lattice-based building blocks, are reusable and easy to manufacture. Furthermore, reconfigurable systems have the potential to outperform traditional, fixed infrastructure in applications that require high levels of flexibility in addition to structural strength and rigidity. NASA Ames Research Center has developed a novel and efficient mobile bipedal robot system to construct low-mass, high precision, and large-scale infrastructure. The mobile bipedal robot system is configured to carry, transfer, and place lattice-based modular unit cells, called voxels, to form a three-dimensional lattice structure. A team of mobile bipedal robots can autonomously unpack and assemble unit cells into functioning structures and systems. The technology provides an integrated system that enables large-scale surface and in-space structural assembly.","category":"robotics_automation","categoryRaw":"Robotics Automation and Control","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_214","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-214","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-214","confidence":"high"},"type":"patent","title":"Cavity Enhanced Absorption Spectroscopy (CEAS) for Ozone Detection","abstract":"Engineers at NASA's Goddard Space Flight Center tasked with measuring atmospheric Ozone, an important pollutant and greenhouse gas, quickly discovered that existing optical instrumentation would not be sufficient to achieve their performance requirements. Specifically, the current systems did not possess the precision necessary to make low concentration measurements at fast time resolution. This innovation utilizes Cavity Enhanced Absorption Spectroscopy (CEAS) with a simple and inexpensive optical and electrical design to overcome these limitations and achieve high quality Ozone measurements. The sensitivity of the instrument developed using CEAS exceeds that of commercially available instrumentations, and matches performance of complex chemiluminescence instruments.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_216","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-216","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-216","confidence":"high"},"type":"patent","title":"Hydroxyl Radical (OH) Gas Detector","abstract":"Hydroxyl radical (OH) is a greenhouse gas that is highly reactive. It reacts with many atmospheric pollutants, including itself, and is considered an important part of eliminating greenhouse gases, especially methane and ozone. OH gas plays a major role in the concentrations of greenhouse gases and is the most prevalent oxidizer in the troposphere, the lowest layer of the Earth\u2019s atmosphere. Due of its high reactivity, OH gas is short-lived (a lifetime of less than one second) and thus, difficult to measure. The OH Gas Detector can measure the absorption of OH gas for detection purposes.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_354","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-354","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-354","confidence":"high"},"type":"patent","title":"Powered Kite with Enhanced Aerial Position Control","abstract":"Inventors at NASA\u2019s Goddard Space Flight Center have developed Skyvator, a kite-based aerial observation tool that uses a single tether to effectively position the kite and adjust it to the required altitude. Currently, most kite systems require multiple tethers to support kite positioning adjustments, resulting in increased aerodynamic drag and presenting operational and handling challenges. The Skyvator can be effectively positioned with a single tether due to its airfoil rigid wing design that provides an efficient lifting surface as well as a power system that is located in the lifting surface. Skyvator, as part of NASA's Aeropod family of low-altitude custom remote sensing platform craft, also overcomes many of the challenges presented by drones for aerial observation including regulatory and training hurdles, limited times, and infrastructure costs.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_368","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-368","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-368","confidence":"high"},"type":"patent","title":"Dual-Polarized, Wideband, Lightweight P-band Antenna Element and Array","abstract":"Many critical science objectives demand the capability to penetrate meters of dust and regolith to reveal buried terrain. While NASA\u2019s primary focus includes the Moon and Mars, future missions targeting Venus, Mercury, asteroids, and other celestial bodies will also require technologies capable of deep subsurface penetration, mapping sub-surface features at meter-scale resolution. For the Space Exploration Synthetic Aperture Radar (SESAR) mission, NASA scientists needed a lightweight, beam-agile synthetic aperture radar (SAR) operating at P-band frequencies to achieve these objectives on the Lunar and Martian surfaces. Innovators at NASA\u2019s Goddard Space Flight Center have developed a dual-polarized, wideband, lightweight P-band antenna element and array for spaceborne radar applications. The antenna array utilizes lightweight, low-profile elements that serve as modular building blocks, forming \u201carray panels\u201d that can be scaled up into larger, multi-panel arrays. The novel design features a mostly planar conductor geometry paired with a robust, lightweight composite material construction. The antenna element and array design are also scalable to other frequencies (e.g., L-, S-, C-, or X-bands) for radar applications where low mass and beam agility are crucial.","category":"sensors_instruments","categoryRaw":"Instrumentation","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_369","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-369","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-369","confidence":"high"},"type":"patent","title":"Quantum Cascade Laser Source and Transceiver","abstract":"Innovators at NASA\u2019s Goddard Space Flight Center have developed a cutting-edge quantum cascade laser (QCL) source and terahertz transceiver that integrates a surface plasmon waveguide, addressing the growing demand for compact, high-resolution systems in communication, material characterization, and metrology. This state-of-the-art technology is designed for planetary science missions, enabling unprecedented characterization of planetary surfaces, including molecular inhomogeneities, isotope ratios, and compositional variation with depth. The QCL source and transceiver are optimized for use in a variety of applications, including cubesats, suborbital missions, and space-based instruments, making it integral to NASA\u2019s exploration and science missions. The system plays a critical role supporting In Situ Resource Utilization (ISRU) by mapping and quantifying lunar water resources, providing ground-truth validation for remote measurements. Its capabilities extend to analyzing surface properties such as dielectric constants, conductivity, thermal inertia, surface roughness, and porosity, advancing the potential for sustainable lunar exploration and beyond.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_375","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-375","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-375","confidence":"high"},"type":"patent","title":"Sensitive, Compact 1x8 Array 530-600 GHz Receiver","abstract":"High-resolution heterodyne-based millimeter-wave spectrometers are used in remote sensing for studying planetary atmospheres. Currently, single-pixel receivers in the submillimeter-wave range provide incomplete information on molecular targets that require simultaneous measurement of differential tangential heights (e.g., molecules with variations in their distribution, pressure, and temperature-dependent spectral features). This increases the time needed to perform a scan using bulky and high power-consumption mechanisms in order to provide accurate atmospheric molecular measurements. Additionally, the narrow intermediate frequency (IF) bandwidth of current receiver technology limits the frequency window of molecular detection during the receiver down-conversation process. These limitations in receiver technology (e.g., bulky systems, high power consumption, limited IF bandwidth) hinder the the development of miniaturized spaceborne atmospheric remote sensing instruments that can be integrated and flown on small satellites. In response to this need, innovators at NASA\u2019s Goddard Space Flight Center have developed a compact, sensitive, wideband and multi-pixel receiver to down-convert many molecular species simultaneously in the 530-600 GHz frequency range.","category":"sensors_instruments","categoryRaw":"Instrumentation","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_380","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-380","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-380","confidence":"high"},"type":"patent","title":"Wideband, Subharmonic Mixer for Spectrometers","abstract":"Heterodyne wave spectrometers include a receiver and are configured to analyze electromagnetic waves by mixing an incoming signal with a reference signal (local oscillator - LO) to produce a lower intermediate frequency (IF) for processing. Within the receiver, a mixer plays a crucial role by combining the incoming signal with a reference signal from a LO producing an IF signal, which retains the spectral information of the original signal but at a lower, more easily processed frequency. Thus, the mixer enables the receiver to convert high-frequency signals into a more manageable form for detailed analysis. Planetary observational spectrometers require a receiver with a wide IF bandwidth and low noise temperature to detect molecular species simultaneously in a desired frequency range. Existing mixers have a limited IF range, which may not be viable for future-state NASA remote-sensing applications. As a result, engineers and researchers at NASA have developed a novel compact mixer, achieving a wide IF bandwidth of approximately 70 GHz, a low noise temperature below 4,000 K, and a conversion loss under 12 dB at 470-600 GHz for space applications and may provide significant advantages to commercially-available spectrometers.","category":"sensors_instruments","categoryRaw":"Instrumentation","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_386","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-386","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-386","confidence":"high"},"type":"patent","title":"WindiWing: Atmospheric Data Collection Line Climber","abstract":"Collecting atmospheric data is crucial for climate research, meteorology, and environmental monitoring. However, traditional methods using drones come with significant challenges, including regulatory restrictions, specialized training, battery constraints, and infrastructure costs. Previous kite-based systems required active control, either through manual commands sent via radio control or autonomous adjustments powered by onboard electrical systems. While these systems improved upon drone-based limitations, they still depended on external energy sources and control mechanisms, increasing complexity and potential failure points. To address these issues, NASA researchers developed a number of kite-based systems in the Aeropod family of kite-based sensing technologies configured to capture atmospheric data efficiently. Over time, various technologies have evolved within the Aeropod family to meet emerging needs, offering expanded capabilities and greater flexibility for researchers. The latest advancement in kite-based atmospheric data collection presents a truly passive system that eliminates the need for electrical power or active controls. By leveraging aerodynamic forces, this technology enables seamless ascent and descent along a kite line, offering an efficient and low-maintenance alternative for atmospheric research.","category":"sensors_instruments","categoryRaw":"Instrumentation","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_388","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-388","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-388","confidence":"high"},"type":"patent","title":"Photon-Efficient Scanning LiDAR System","abstract":"Scanning LiDAR (Light Detection and Ranging) is an advanced remote sensing technology that uses laser pulses to create high-resolution, three-dimensional maps of surfaces. Traditional LiDAR systems often lack control over uniform scanning patterns, leading to inefficient or redundant information over uniform terrains like deserts and oceans, resulting in unnecessary power consumption and data storage challenges. Scanned data is compressed because much of the data is duplicative and can waste LiDAR resources such as photons, power, and detector capacity while also burdening data transfer, storage, and processing systems. NASA engineers have developed a novel LiDAR approach utilizing compressive coded aperture scanning to address the inefficiencies of state-of-the-art LiDAR systems to build a 3D map of a selected area more efficiently. This method enhances photon efficiency by selectively omitting certain pixels during the scan and employing sophisticated algorithms to reconstruct the missing data, thereby optimizing resource utilization without compromising data quality.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_389","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-389","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-389","confidence":"high"},"type":"patent","title":"Wide Field Receiver Calibration Device for Micro Pulse LiDAR","abstract":"Micro Pulse LiDAR (MPL) instruments \u2013 first developed in the early 1990s by a NASA scientist \u2013 are compact, eye-safe elastic-backscatter LiDARs deployable at remote locations. A federated ground network of MPLs compose the NASA MPL Network (MPLNET), which provides continuous aerosol and cloud profiling data around the globe. However, using MPLs \u2013 especially for aerosol research \u2013 in the near range (0-6 km) requires a time consuming, laborious overlap calibration process to quantify and correct the region where the emitted laser beam and detector field of view do not fully overlap. At close ranges, this overlap is often incomplete, leading to reduced signal accuracy. Accurate characterization and correction of this function are vital for precise data, especially for near-surface atmospheric features. In response to this challenge, engineers at NASA's Goddard Space Flight Center developed the Wide Field Receiver (WFR) Calibration Device for MPLs. This auxiliary receiver has a broad field of view compared to the standard MPL receiver, allowing it to capture more scattered light from the atmosphere, including regions where the standard receiver\u2019s overlap is complete. By comparing data from both standard and this NASA wide field of view receiver, users can accurately determine the overlap function and apply necessary corrections to MPL data, all with reduced time and effort relative to conventional techniques.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_22","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-22","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-22","confidence":"high"},"type":"patent","title":"Macroflash (Cup Cryostat)","abstract":"NASA Kennedy Space Center seeks partners interested in a practical method for measuring thermal performance of materials at below-ambient temperatures or subjected to a large temperature difference. The technology uses liquid nitrogen as a direct heat energy meter and is applicable to testing at a wide range of temperatures from 373 K down to 77 K and under an ambient pressure environment. The Macroflash follows the guidelines of the newly established technical standard ASTM C1774 (Annex A4) and provides a cost-effective, field-representative methodology to test any material for below-ambient temperature applications. From engineered systems to research testing to quality control in manufacturing, the technology provides utility for the fields of energy, transportation, construction, and environment.","category":"sensors_instruments","categoryRaw":"Instrumentation","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_43","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-43","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-43","confidence":"high"},"type":"patent","title":"Cryostat-500","abstract":"NASA Kennedy Space Center seeks partners interested in the guarded flat plate insulation test cryostat (Cryostat-500), a boil-off calorimeter comprised of a flat bottom test apparatus for measuring the absolute thermal performance of an insulation test specimen. This instrument provides convenient testing of many sizes and shapes of materials, enhanced automation, and a direct route for obtaining reliable thermal performance data. Testing under conditions representative of actual-use environments including large temperature differences is also provided. The test data are presented in terms of effective thermal conductivity and heat flux. In today's world, efficient, low-maintenance, low-temperature refrigeration is taking a more significant role, from the food industry, transportation, and medical applications to commercial buildings, energy, and space exploration. Worldwide, various regulations require that commercially available insulation materials are tested and evaluated by an accepted methodology. The new Cryostat-500 method goes beyond the prior capabilities of consensus technical standards to provide testing for real systems and materials operating below ambient temperature. The Cryostat-500 covers a wide range of test environments including full-temperature differences plus full-range vacuum conditions.","category":"sensors_instruments","categoryRaw":"Instrumentation","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_79","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-79","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-79","confidence":"high"},"type":"patent","title":"Cryostat-100","abstract":"NASA Kennedy Space Center seeks partners interested in the Cryostat-100, an absolute heat measurement device for precise thermal performance measurements under actual-use cryogenic-vacuum conditions. It is a liquid nitrogen boiloff calorimeter with upper and lower guard chambers and full vacuum pressure range capability. The Cryostat-100 vacuum cylinder and cold-mass assemblies include handling and manipulation devices to make sample material change-out fast, reliable, and safe for the operator. The boiloff flow from the test chamber is in direct proportion to the total heat transfer rate through the thickness of the test article. Flow rate is typically averaged over the liquid level from 88 to 92 percent to calculate the k-value.","category":"sensors_instruments","categoryRaw":"Instrumentation","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_ksc_tops_91","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-TOPS-91","sourceUrl":"https://technology.nasa.gov/patent/KSC-TOPS-91","confidence":"high"},"type":"patent","title":"Optical concentration sensor for liquid solution","abstract":"Innovators at the NASA Kennedy Space Center have developed a new optical sensor for measuring concentration in a liquid solution. The sensor was designed for measuring the pretreat solution concentration within the Universal Waste Management System (UWMS), a specialized toilet designed for the International Space Station (ISS) and other future missions. The sensor was developed to replace the current pretreat concentration sensor within the UWMS that uses electrical conductivity instead of light-based methods. Using established methodologies and commercial components, the new sensor can precisely measure the concentration or pretreat within the waste treatment solution using the light passed through and scattered by the solution. The optical sensor can be adapted to measure the concentration of solutions across various industries.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_11","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-11","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-11","confidence":"high"},"type":"patent","title":"Fluid Measurement Sensor","abstract":"NASA's Langley Research Center researchers have developed a wireless, thin-film fluid measurement sensor that uses a magnetic field response measurement acquisition system to provide power to the sensor and to acquire physical property measurements from it. In addition to measuring fluids within an enclosed container, it can be placed external to a non-conductive container to measure the level of any non-gaseous substance, including liquids, solids, and semi-solids such as powder or granular substances.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_116","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-116","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-116","confidence":"high"},"type":"patent","title":"Electric Field Imaging System","abstract":"NASA Langley Research Center's Electric Field Imaging (EFI) system is the only noncontact method capable of quantitatively measuring the magnitude and direction of electrostatic fields in near- and far-field applications. Based on low-cost, commercially available components, the EFI system uses measurement of very low-current, human-safe electric fields to construct a three-dimensional image of objects and people based on their dielectric properties. This platform technology, originally developed for measurement of the efficacy of electrical shielding around cables, could be optimized for a variety of applications, including medical imaging, security and detection, weather and natural disaster prediction, and nondestructive evaluation of composites and insulators. The EFI system has the potential to offer a lower-cost, portable, and safer alternative to the imaging systems currently used in these applications.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_127","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-127","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-127","confidence":"high"},"type":"patent","title":"Highly Accurate Level Sensor","abstract":"NASA's Langley Research Center has developed a SansEC Sensor Technology for use with aerospace fuel delivery systems. The SansEC technology is a patented and proven platform for multiple applications, including fluid level measurement. The platform utilizes a flat coil geometry antenna operated at its resonant frequency to measure dielectric properties or property changes of materials near the coil. The technology is well-suited for situations where wireless, powerless, or non-contact measurements are needed with high sensitivity and accuracy. NASA Langley Research Center is seeking industrial partners/ licensees to commercialize this technology. The research team at NASA Langley is available to assist with further development.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_128","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-128","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-128","confidence":"high"},"type":"patent","title":"Lightning Mitigation and Damage Detection","abstract":"NASA's Langley Research Center has developed a patented SansEC Sensor Technology for use in many different areas, including tall structures and wind turbines. The SansEC technology is a proven wireless sensing platform capable of measuring the electrical impedance of physical matter in proximity to the sensor based on a change in its resonance response. The SansEC sensor also exhibits a unique characteristic to disperse the lightning strike current to help mitigate lightning damage. In a turbine blade application, an array of SansEC sensors will cover the surface area of the composite blade, providing both lightning mitigation and damage sensing. NASA Langley Research Center is seeking industrial partners/ licensees to commercialize this technology. The research team at NASA Langley is available to assist with further development.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_247","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-247","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-247","confidence":"high"},"type":"patent","title":"Large Area Structural Damage Nondestructive Evaluation","abstract":"When testing composite structures, it is important to understand the response of the structure to the load. Of significance is the formation of damage and growth of that damage leading to ultimate failure. Understanding how a structure fails allows for optimal designs for improved safety and performance for the part during its life cycle. Inspection methods are required to determine damage initiation and growth in advanced composite structures during loading. Past methods for in-situ inspection of composite structures during loading have involved acoustic emission, passive thermography, digital image correlation, and fiber optics techniques. However, each of these has critical limitations. The combination of thermal and acoustic emission (AE) nondestructive evaluation (NDE) techniques, by mapping the acoustic emission events onto the thermal imagery, provides a very sensitive measurement system for detecting damage formation and growth.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_281","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-281","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-281","confidence":"high"},"type":"patent","title":"High Altitude UAV for Monitoring Meteorological Parameters","abstract":"Acoustical studies of atmospheric events like convective storms, tornadoes, shear-induced turbulence, microbursts, acoustic gravity waves and hurricanes over the last fifty years have established that these events are strong emitters of infrasound. Current methods to forecast near term weather phenomenon is EM based radar and data from radiosondes. Radar is an active remote sensor which has limited range and there is the possibility that radar beams will overshoot the mesocyclonic circulation. There is also a possibility that mesocyclonic circulation cannot be detected because of the conal region immediately above the radar set.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_301","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-301","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-301","confidence":"high"},"type":"patent","title":"Multivariate Monitoring for Human Operator and Machine Teaming","abstract":"Researchers and expert operators may be familiar with the concept of trust in automation, but how would advance automation make decisions regarding control without establishing trust in the operator? Vehicles outfitted with sensors and systems that can operate with varying degrees of autonomy are being developed. Optimizing human machine interaction remains critical for maintaining and improving safety as vehicles become increasingly autonomous . Human status is highly variable and difficult to predict. Despite a recent history of consistent reliability, in the current moment the operator status may range from completely incapacitated to ready to take control as necessary or as preferred. The intelligent system itself needs to know what the human is doing now to make decisions in real time regarding role assignments, safe operation and critical functional task allocation.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_303","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-303","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-303","confidence":"high"},"type":"patent","title":"Guided wave-based system for cure monitoring of composites using piezoelectric discs and fiber Bragg gratings (FBGs)","abstract":"The use of carbon fiber reinforced polymer composites for structural components in aircraft , automotive and other applications has grown rapidly and is in extensive use today. A prime example is the Boeing 787 Dreamliner of which the entire fuselage and wings are constructed from CRFP's. Consequently, as a quality control measure, means to monitor the cure rate of the resins as well as means to detect defects has become critically important. Inventors at NASA Langley have developed and demonstrated a system using fiber optic sensors to measure guided waves that propagate in a part as a cure monitoring system. Life-cycle monitoring is now possible because of optical fiber embedded in composite during cure.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_321","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-321","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-321","confidence":"high"},"type":"patent","title":"Extreme Low Frequency Hydrophone","abstract":"The Extreme low frequency infrasonic hydrophone, with the associated software, is capable of sensing down to .0001 Hz, a 4.999 Hz improvement from current similar systems. This ultra-low power consuming hydrophone also isolates and removes significant amounts of background noise, inherent to the electret type microphone not previously introduced into hydrophone applications. The uniquely robust unit design also permits for sub-freezing operations deep below the surface. The results promise to drastically alter lives and multiple industries, enabling totally new data for weather monitoring and earthquake/tsunami prediction among numerous other academic applications. It could also improve current hydrophone accuracy or reliability in finding oil resources, and will enable monitoring human generated infrasound in water.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_332","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-332","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-332","confidence":"high"},"type":"patent","title":"Fast & Accurate Composite Bond Strength Measurement","abstract":"Innovators at the NASA Langley Research Center, in conjunction with the National Institute of Aerospace and the University of Virginia, have developed a method for evaluation of adhesive bond strength via swept-frequency ultrasonic phase measurements. In recent years, the use of advanced composites has increased as modern designs strive for lighter weight, higher performance, and greater durability. Adhesive bonding is the preferred method of joining composite structures, requiring a nondestructive evaluation (NDE) method for ensuring adequate bonded joint strength. Conventional NDE methods have been used to detect gross bonding defects, but such methods have proven insensitive to weak adhesion. Current NDE methods that claim sensitivity to interfacial bond strength require complex, bulky, and time-intensive measurement procedures that are often not adaptable to the shop floor. NASA's new measurement system quickly and accurately measures interfacial bond strength and is easily compatible with assembly line and repair facilities.","category":"sensors_instruments","categoryRaw":"Instrumentation","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_362","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-362","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-362","confidence":"high"},"type":"patent","title":"Multi-Spectral Imaging Pyrometer","abstract":"Innovators at NASA Langley Research Center have developed a multi-spectral imaging pyrometer utilizing tunable optics. The system uses a conventional infrared imaging camera as the basis and then incorporates an ultrafast, all solid-state, tunable optical filter combined with unique data processing algorithms to function as a multi-color ratio pyrometer but with true imaging capabilities. Currently, there is no way to provide automatic, independent, emissivity-based temperature corrections at the pixel level for infrared cameras that operate with broadband detectors. Multiwavelength pyrometric systems can make emissivity-corrected temperature measurements but are not imaging devices and lack the ability to view surface gradients and other subtle variations. Optical systems that measure at several discrete wavelengths require the use of multiple optical filters and are slow, bulky and require high power.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_365","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-365","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-365","confidence":"high"},"type":"patent","title":"Projected Background-Oriented Schlieren Imaging","abstract":"Inventors at the NASA Langley Research Center (LAR) have developed a new background-oriented schlieren (BOS) imaging technique. The new technique enables vibration-tolerant, real-time, and reference-free BOS imaging for scientific investigations or industrial flow monitoring. Typically, BOS imaging requires a physical pattern on a retroreflective surface within the flow of interest to visualize that flow through changes in the pattern due to density changes between the pattern and a camera. Here, the BOS imaging technique does not require a physical pattern within the flow, and it is instead projected through the flow onto a retroreflective surface that is then imaged by a camera. Projecting the pattern allows the pattern to be changed mid-measurement and may lessen the cost of BOS imaging for a variety of flow visualization applications.","category":"sensors_instruments","categoryRaw":"Instrumentation","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_387","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-387","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-387","confidence":"high"},"type":"patent","title":"Receiver for Long-distance, Low-backscatter LiDAR","abstract":"Researchers at the NASA Langley Research Center have developed a new coherent LiDAR (light detection and ranging) receiver compatible with high-energy fiber lasers. The hybrid receiver incorporates robust bulk optics (i.e., dielectric, coated optics) to handle high pulse energy where needed and fiber optics where damage tolerance is not critical. Commercially available receivers leveraging fiber optic components for metrology and remote sensing are not compatible lasers above ~100 micro-J. This restriction limits measurement distances to only a few kilometers out and to the lower atmosphere where aerosols are abundant. The new NASA design allows full advantage to be taken of novel high-energy pulsed laser technology to enable Doppler LiDAR measurements out to longer distances (> 10 km) and/or in conditions of lower aerosol backscatter for applications in markets including wind energy, aerospace & defense, and meteorology & environmental sensing.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_392","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-392","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-392","confidence":"high"},"type":"patent","title":"Advanced Thermal Inspection with Pulsed Light Emitting Diodes (PLED) Technology","abstract":"Thermal nondestructive evaluation (NDE) is a widely used method for detecting defects such as cracks, corrosion, and dis-bond layers in metallic and composite structures. Traditional thermal inspection methods rely on a high-intensity, broadband light heat source (e.g., flash lamp, quartz lamp) that generates heat that is absorbed by the material, and an infrared camera captures the transient thermal response to generate inspection data. However, inspecting low emissivity surfaces (such as unpainted aluminum and titanium alloys) poses challenges including high reflection of the heat source light that can cause inaccurate measurement of the surface temperature response, produce false defect indications, and potential sensor damage due to high-intensity reflections. In response to this challenge, engineers at NASA Langley Research Center (LaRC) have developed a cutting-edge thermal inspection technology that enhances defect detection on low-emissivity surfaces by eliminating false readings caused by infrared reflections. By using a spectrally narrow, visible-band pulsed light emitting diodes (PLED) heat source and optical filters, this system prevents interference with infrared camera measurements, delivering a higher accuracy, improved defect contrast, and more cost-effective alternative to conventional flash thermography.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_4","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-4","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-4","confidence":"high"},"type":"patent","title":"ZONE (Zeroing Out Negative Effects)","abstract":"NASA's Langley Research Center has developed ZONE, an innovative method for improving athletes responses to stress, anxiety, and loss of concentration during competition. In the training environment, when the user successfully attains an optimal target state of psychophysiological functioning, the technology informs and/or rewards that user through real-time physical changes in the athletic equipment. For example, in the training setting, a golfer can work toward optimal concentration in the act of putting, leading to improved performance in real situations.","category":"sensors_instruments","categoryRaw":"Instrumentation","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_400","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-400","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-400","confidence":"high"},"type":"patent","title":"Reconfigurable Local Oscillator for Coherent Optical Detection","abstract":"Current coherent optical receivers use fixed local oscillators (LOs), and the characteristics of LOs, such as frequency, polarization, or spatial mode, determine which incoming signals can be detected. These constraints reduce sensitivity and restrict the range of detectable signals. Signals that fall outside the receiver\u2019s bandwidth or have mismatched polarization may not be detected. This challenge is especially relevant to NASA\u2019s Navigation Doppler LiDAR, where signals from fast or distant targets can fall outside the receiver\u2019s range or become difficult to detect due to low-frequency noise. To overcome these limitations, researchers at NASA\u2019s Langley Research Center have developed the Reconfigurable Local Oscillator for Coherent Optical Detection. This innovative technology can be applied to LiDAR, fiber-optic sensing, and optical communications. By enabling real-time adjustment of an LO\u2019s properties, the system can dynamically match incoming signal characteristics, enhancing signal recovery, improving sensitivity, and increasing adaptability across a wide range of operating conditions.","category":"sensors_instruments","categoryRaw":"Instrumentation","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_142","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-142","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-142","confidence":"high"},"type":"patent","title":"Compact Full-Field Ion Detector System (CFIDS)","abstract":"Space radiation, or \"space weather\" comes in different forms from a variety of sources. High energy X-rays, gamma rays, and other ionizing radiation, in the form of subatomic particles and ionized atoms, can be produced by black hole activity, new star formation, and even via lightning from thunderstorms. Most of the radiation from space that reaches the earth is generated by our sun, in the form of the solar wind, solar flares, and coronal mass ejections. One of the ways in which the sun releases charged particles from its corona (outer atmosphere) is in the the solar wind. Interaction between the sun\u2019s magnetic field, the solar wind, and the earth\u2019s magnetic field can lead to magnetic disturbances of the earth\u2019s magnetic field known as geomagnetic storms. Impacts of Space Radiation: High-energy radiation from space can damage electric components on satellites, space stations, and high-altitude aircraft . This damage can disrupt functionality and communication and may also lead to complete failure of those components. Ionizing radiation also leads to the slow degradation of materials that structures in space are made from. It can cause damage to DNA of astronauts and high-altitude aircraft pilots and crew. This same ionizing radiation interacts with the magnetic fields and atmospheres of planets such as the earth that have magnetic fields and atmospheres. It can disrupt radio signals, communications signals, and electrical grid performance on earth.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_156","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-156","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-156","confidence":"high"},"type":"patent","title":"Combined Pressure and Temperature Sensor for Hot Harsh Environments","abstract":"Accurate and reliable pressure data is fundamental for monitoring engine health for the safe and efficient operation of high performance engines. Innovators at NASA's Glenn Research Center have developed a single pressure and temperature sensor system that provides in-situ data in harsh operating environments like combustion. Although current SiC pressure sensors can operate at 800&#176C inside combustion chambers, the output response is sensitive to temperature changes and requires temperature compensation schemes that rely on a second separate temperature sensor to get a true measure of pressure. The new NASA pressure/temperature (P/T) sensor chip enables real-time translation of pressure and uses only a single tap for two engine measurements. This important sensor system and packaging can provide more accurate data for combustion simulations and to monitor engine health to improve performance and extend the service lifetime of commercial and military aircraft, automotive engines, and power plants.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_165","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-165","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-165","confidence":"high"},"type":"patent","title":"Portable Laser-Guided Robotic Metrology (PLGRM)","abstract":"Antennas are used in many industries and products where quality and reliability are crucial. Testing aircraft antennas is challenging since optimal tests are made after antenna installation. Aircraft are often taken to anechoic antenna test facilities which create long lead times, transportation hassle, and very high costs. This makes such testing cost-prohibitive for early R&D work. Portable alternatives exist but often have compromised testing fidelity. Innovators at the NASA Glenn Research Center (GRC) have developed the PLGRM system which allows an installed antenna to be characterized in an aircraft hangar. All PLGRM components can be packed onto pallets, shipped, and easily operated. The flexibility and portability of this system while maintaining precision and accuracy are what make PLGRM unique. While developed for aerospace , PLGRM can be used to characterize antenna systems across a range of applications. Extending applications beyond just antenna analysis may also be possible.","category":"sensors_instruments","categoryRaw":"Instrumentation","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_183","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-183","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-183","confidence":"high"},"type":"patent","title":"Capacitive Impedance Water Ice Sensor (CIWIS)","abstract":"Ice accumulation on an aircraft\u2019s surface poses a serious safety risk, causing stalls and crashes due to the distortion of the smooth flow of air necessary to maintain lift. There are a variety of sensors commonly used to identify materials collecting on the surface of an aircraft, however, they all have operational limitations. Vibrating sensors are not able to detect small amounts of accumulation, optical sensors can be blocked by dirt or debris, and magnetostrictive sensors require precise calibration and have limited range. Engineers at NASA\u2019s Glenn Research Center have developed a novel method for detecting ice or other material accumulation on the surface of aircraft. The Capacitive Impedance Water Ice Sensor (CIWIS). CIWIS works by measuring the impedance of accumulation using the phase of a smart capacitive sensor. This allows users to accurately determine when ice, water, or other materials are on the surface of an aircraft.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lew_tops_60","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-TOPS-60","sourceUrl":"https://technology.nasa.gov/patent/LEW-TOPS-60","confidence":"high"},"type":"patent","title":"Luminescence-Based Temperature Mapping and Sensing Systems","abstract":"NASA's Glenn Research Center has developed non-contact, ultra-bright luminescence-based surface temperature mapping and sensing systems capable of operating in environments with extremely high thermal radiation. This is accomplished through the use of a unique chromium-doped gadolinium aluminate (Cr:GdAlO 3 ) temperature-sensing phosphor. This technology has been proven accurate up to 1300&deg;C - a dramatic increase when compared to current state-of-the-art, which has only been demonstrated up to 600&deg;C. In addition to providing breakthrough temperature measurement capability, this innovation is immune to electromagnetic interference, making it ideal for operation in harsh, high-temperature environments. Furthermore, its unprecedented ultra-bright intensity allows for accurate temperature measurements in the presence of high levels of background radiation.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_111","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-111","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-111","confidence":"high"},"type":"patent","title":"Hyper-Distributed RFID Antenna (HYDRA) System","abstract":"Innovators at NASA Johnson Space Center have developed a method and apparatus to multiplex Radio Frequency Identification (RFID) signals efficiently. The resulting Hyper-Distributed RFID Antenna (HYDRA) system enhances distribution of the RFID reader signal, providing improved coverage for large areas as well as for small, fixed regions requiring a high density of reader antennas. This greater coverage translates into better RFID sensing capabilities, higher localization accuracy, and enhanced logistics awareness. Many conventional RFID applications require adding more readers and antennas to increase coverage in existing areas and to improve localization. Employing conventional multiplexer switches can reduce the need for additional readers but require additional control and power cabling. Both conventional options will increase mass, size, and cost of the overall infrastructure to improve sensing performance. The HYDRA system, which uses microprocessor-based low-mass multiplexers, reduces the need for additional readers and cabling over the conventional prior art, and it operates with smaller-sized antennas. As a result, the advantages of the HYDRA system include the ability to transmit data at low power, improve coverage performance, increased capability to localize RFID tags, along with reduced cost, complexity, and mass.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_117","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-117","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-117","confidence":"high"},"type":"patent","title":"Low Mass Antenna Boosts RFID Device Performance","abstract":"Innovators at NASA Johnson Space Center have developed a quarter-wavelength RFID dual mode antenna that provides polarization diversity and employs dual resonances, but in a form factor that is much smaller than other RFID antennas that provide similar functionality. Typically, antennas designed to provide this performance are on the order of half-wavelength structure which means a larger form factor. Development of this antenna was motivated by the Hyper-Distributed RFID Antenna (HYDRA) system. The HYDRA design seeks a \u201cbarely visible\u201d implementation, with a coaxial cable connecting a number of RFID antennas that are not much bigger than the coaxial cable itself. This reduced size should be useful in enclosed vehicles, office spaces, laboratories, etc. Although this RFID dual mode antenna was originally developed for the HYDRA system, this antenna has other applications. For example, small antennas with polarization diversity in handheld RFID readers have long been a challenge. The industry standard is a ceramic half-wavelength puck that is somewhat heavy and leads to ergonomic problems with handheld RFID readers. This innovation could provide a substantial improvement in handheld readers, and similarly with drone-based readers, for applications in which mass is almost always a primary factor.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_124","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-124","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-124","confidence":"high"},"type":"patent","title":"RFID Tags Collaborate for Data Retrieval","abstract":"Innovators at NASA Johnson Space Center have developed a low-cost means to refine localization and determine when specific assets have been attached or placed in set proximity of each other using radio frequency identification (RFID) technology. This innovation is comprised of both a novel RFID sensor tag that incorporates onboard microcontrollers and sensors to detect an influence, and a programmable influence tag that is attached to an asset for which RFID localization or attachment status is desired. Commercial RFID tags typically only communicate with a reader and utilize narrow spectrum frequency bands that can complicate the triangulation necessary for readers to determine an asset\u2019s location. Additionally, an extreme radio frequency scattering environment further aggravates triangulation techniques commonly used in RFID. With this new RFID tag technology, an influence tag can provide data to a sensor tag which then feeds joint information to a reader. A proliferation of these tags in arrangement allows for precise localization of assets, is extensible to large distribution cells or monitored areas, and can provide confirmation of mated or associated parts. The RFID-Enabled Connections and Sensed Localization technology is at technology readiness level (TRL) 4 (component and/or breadboard validation in a laboratory environment) and is available for patent licensing. Please note that NASA does not manufacture products itself for commercial sale.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_128","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-128","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-128","confidence":"high"},"type":"patent","title":"RFID Range Extension and Priority Data Forwarding","abstract":"Innovators at NASA Johnson Space Center have developed an adaptable Radio Frequency Identification (RFID) system that optimizes transmission for priority data as targets move in and out of passive coverage areas. The method extends the range, and reduces data latency, of ultra-low power battery-assisted passive (BAP) RFID sensor tags, improving previously developed store-and-forward techniques to support autonomous operations in complex environments where RFID interrogator access may be strained. This RFID sensor tag technology normally operates in a low-to-no-power mode, collecting data until triggered by a critical event that activates an emergency mode of operation. Once triggered, the tag\u2019s RFID range is boosted using the BAP RFID device\u2019s onboard power supply. This allows RFID application programmers to sacrifice battery life for reduced latency for high priority sensing applications such as the technology\u2019s original intention to monitor for life-threatening CO2 levels in spacecraft cabins. Range Extension and Priority Handling for Wearable, Ubiquitous RFID enabled Sensing is at technology readiness level (TRL) 4 (component performance has been validated in a lab setting) and is now available for licensing. Please note that NASA does not manufacture products itself for commercial sale.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_130","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-130","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-130","confidence":"high"},"type":"patent","title":"Thin Film Sensor for Ultra High-Temp Measurement","abstract":"Innovators at NASA Johnson Space Center have developed a thin film sensor that measures temperatures up to 1200 F, and whose prototype successor may achieve measurements up to ~3000 F \u2013 which was the surface temperature of the Space Shuttle during its atmospheric reentry. The novel sensor design also quells the deleterious effects of thermal expansion mismatch between the thermal protection system (TPS) material comprised in the spacecraft\u2019s outer shell, and the embedded thin film sensors\u2019 component materials. Current methods that capture temperature data from the surface of a reentering spacecraft typically rely upon the use of low frequency thermocouples embedded in the spacecraft\u2019s TPS and are limited to ~700 F. However, these thermocouples lack the high frequency response required for anything but low frequency temperature or heat flux. This novel thin-film temperature sensor, also embedded as an in-situ device in the through-thickness of a spacecraft\u2019s TPS, is designed to solve these issues by capturing data at an extremely high frequency rate (>1MHz). This technology may prove extremely useful in a burgeoning commercial aerospace industry where the ability to measure temperature from the surface of a reentering spacecraft can be used to enhance performance and safety. The thin film temperature sensor may also have commercial applications in hypersonic aircraft, energy production, metallurgical blast furnaces, and other extreme high enthalpy environments.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_142","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-142","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-142","confidence":"high"},"type":"patent","title":"MiniTOCA Facilitates Automated Water Analysis","abstract":"Seizing upon the success of the Total Organic Carbon Analyzer (TOCA) operating aboard the ISS, innovators working for NASA Johnson Space Center (JSC) have revamped a potable water monitoring technology for long-duration crewed space missions into a smaller, lighter package called \u201cMiniTOCA\u201d. Total Organic Carbon (TOC) concentration can indicate the presence of organic compounds in a water sample such as that from decaying plants and bacteria along with hazardous chemicals. Currently, commercial TOC analyzers fail to meet the requirements set for deep space exploration typically due to gravity dependence, hazardous acid needed for inorganic carbon determination, and hazardous chemical or combustion reactor usage needed for oxidation. Ideally, exploration spacecraft instrumentation, including water monitoring technology, would not need resupply chemicals, would possess a low mass/volume archi-tecture, and would enable reliable online sensors to furnish real-time water quality data. The MiniTOCA reflects success in achieving these goals along with providing additional tunability to fit specific mission requirements including mass, volume, crew time, and resupply needs. The MiniTOCA is at a technology readiness level (TRL) 7 (System prototype demon-stration in an operational environment) and is now available for patent licensing. Please note that NASA does not manufacture products itself for commercial sale.","category":"sensors_instruments","categoryRaw":"Instrumentation","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_143","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-143","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-143","confidence":"high"},"type":"patent","title":"Dust Accumulation Sensor Provides In Situ Monitoring","abstract":"Innovators working at NASA Johnson Space Center have developed a dust sensor for use in space environments that measures surface dust accumulation more effectively and accurately than solar cell-based methods. The Planetary Accumulation of Dust Sensor , or \u201cPADS\u201d for short, comprises a compact, puck-shaped form factor whose key component, a sensor disc, has a tunable optical coating from which dust accumulation is derived through measured changes in coating properties when heat is applied. For planned Moon and other planetary-body missions (Mars, asteroids), there are significant needs to understand the impacts of the dust environ-ment to support design, operations, performance impacts, etc., for scientific and overall mission objectives. NASA believes the PADS device will be useful for ensuring remote equipment operators and astronauts are aware of dust accumulation on mission critical components (e.g., radiators, solar arrays) that could lead to mission complications. The PADS device provides a solution to these needs in a simple, light-weight, low power device for measurement of dust accumulation in a space-based environment having undergone ground calibration and optimization of its key design features for the environment of interest. The Planetary Accumulation of Dust Sensor is at a technology readiness level (TRL) 6 (System/sub-system model or prototype demonstration in an operational environment), and is now available for patent licensing.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_36","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-36","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-36","confidence":"high"},"type":"patent","title":"Passive Smart Container","abstract":"NASA's Johnson Space Center has developed a Passive Smart Container to monitor and track items that are too small to tag individually. Although Radio Frequency Identification (RFID) technology is being used widely for pallet and box level tracking in the commercial sector, significant technology gaps remain for tracking dense quantities at the item level. This system uses RFID circuits to identify the fill level in a container and could be easily converted for use in industries such as individual health care management, pharmaceutical manufacturing and distribution inventory tracking, and retail and supply chain inventory management. Use of this technology enables the manufacturer, distributor supplier or user to easily manage and control an inventory of small items that are difficult to tag such as bulk grain foods, liquids, pills, mechanical parts (nuts, bolts, and washers) and small electronic components. This NASA Technology is available for your company to license and develop into a commercial product. NASA does not manufacture products for commercial sale.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_51","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-51","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-51","confidence":"high"},"type":"patent","title":"RFID Tag for Long Range and Wide Coverage Capabilities","abstract":"Researchers at the NASA Johnson Space Center have created a suite of RFID technologies focused in the areas of inventory management and tracking systems and one of those technologies is the RFID Tag with Long Range and Wide Coverage Capabilities. This technology can be integrated to a RFID Tag with a beamforming network capable of receiving and sending long range signals from different directions. Typical RFID tags offer either wide coverage with limited range or long range with narrow coverage. However, this technology, which can even employ passive RFID tags, is capable of doing both, opening the RFID technology to a new spectrum of applications, including inventory tracking, navigational systems, and predictive analytics. With its dual benefits of long range and broad coverage made available by retroreflection, these RFID tags can easily enhance existing RFID infrastructure to enable new applications in many industries.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_56","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-56","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-56","confidence":"high"},"type":"patent","title":"Pressure Sensor Mechanism","abstract":"The Pressure Sensor Mechanism is designed to measure or monitor tactile pressure. It is based on passive Radio Frequency Identification (RFID) sensor tags and is applicable to a variety of systems. As RFID sensors transmit information wirelessly, they eliminate many challenges associated with traditional wired systems such as bridging joints, reliability, volume, and mass. Innovators at NASA Johnson Space Center are using this technology in robotic systems for pressure sensor monitoring. The RFID Pressure Sensor Mechanism has the potential to be easily integrated in mechanical systems to wirelessly and autonomously communicate pressure changes back to a monitoring system without an external power supply. This NASA Technology is available for your company to license and develop into a commercial product. NASA does not manufacture products for commercial sale.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_79","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-79","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-79","confidence":"high"},"type":"patent","title":"Agile RFID Antenna System","abstract":"Researchers at the NASA Johnson Space Center have developed a suite of RFID-based technologies focused on improving communication of an RFID reader with a greater number of RFID tags in open and enclosed areas. Typically, RFID reader communications with tags are spectrum-regulated to a narrow bandwidth that makes tag localization difficult. Moreover, RFID communications are complicated by polarization mismatches between the reader and tag antennas. The Agile RFID Antenna System is able to expand these boundaries by integrating an inexpensive frequency multiplexer to the RFID reader antennas, which permits new methods of localization, allows greater antenna functionality with fewer reader RF ports, and provides improved read accuracy and/or range. For enclosed areas, such as a large container, the Agile RFID Antenna System can use smaller antennas, consequently reducing the volume required for an RFID system to operate. A wide range of commercial applications can benefit from this technology, including retail inventory management, manufacturing/assembly line tracking, industrial transportation and logistics, sports bio-analysis, and healthcare.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_112","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-112","sourceUrl":"https://technology.nasa.gov/patent/TOP2-112","confidence":"high"},"type":"patent","title":"Gas Sensors Based on Coated and Doped Carbon Nanotubes","abstract":"NASAs Ames Research Center offers the opportunity to license and codevelop electronic, inexpensive, low-power gas sensors based on single-walled carbon nanotubes (SWCNT). Traditional sensors, such as metal oxide devices, have been utilized for several decades for detection of combustible and toxic gases. However, they are power hungry, and their use is limited. There is a strong need for development of next-generation chemical sensors with higher sensitivity in the parts per million (ppm) to parts per billion (ppb) level and low power consumption. Sensors based on emerging nanotechnology, such as SWCNTs, promise to provide improved performance. NASA scientists came up with an innovative method for gas detection by coating or doping the SWCNTs with suitable materials . The purpose of the invention is to incorporate thus-treated SWCNTs into electronic devices that measure their electrical properties, such as resistance.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_323","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-323","sourceUrl":"https://technology.nasa.gov/patent/TOP2-323","confidence":"high"},"type":"patent","title":"Hybrid carbon nanotube-gold nanoparticle composite for Nitric Oxide (NO) detection","abstract":"Nitric Oxide (NO) detection has a wide application from environmental monitoring, industrial process control, combustion studies, oceanographic study to medical diagnoses. NO is a highly unstable, reactive gaseous molecule, making its detection challenging, especially at low concentrations and in high humidity environments. While some commonly used techniques to monitor NO gas are suitable for in vivo detection in solutions, others are bulky and complex despite being sensitive and accurate for in situ monitoring. NASA Ames Research Center has developed a novel, cutting-edge chemiresistive sensor technology that can selectively detect NO in real time, with a small footprint, handheld design, easy operation, and low power consumption. The innovative composite films, crafted from functionalized single-walled carbon nanotubes (SWCNTs) and gold nanoparticles (AuNPs), redefine the landscape of gas sensing.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_328","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-328","sourceUrl":"https://technology.nasa.gov/patent/TOP2-328","confidence":"high"},"type":"patent","title":"Systems and methods employing nanomaterial sensors for detecting conditions impacting a Volatile Organic Compounds (VOCs) profile in breath","abstract":"NASA Ames had previously developed a nanosensor array that uses a sample of patient breath for medical diagnosis. (See TOP2-169.) However, the specific materials that can be used had not been previously identified. NASA Ames has made further developments to enhance the capabilities of the technology to detect a variety of Volatile Organic Compounds (VOCs). A highly sensitive sensor array featuring 64 chemically sensitive nanomaterials can accurately identify various health and biological conditions, such as detection of Covid-19 in humans. The technology can also provide a non-invasive approach for sensing biological conditions in dairy and animal husbandry. 64 distinct sensing nanomaterials, including nanotubes, composite nanotubes, nanoparticle-decorated (doped) nanotubes, and polymer-coated nanotubes, having the greatest sensitivity to VOCs in concentrations as low as 2 to 5 ppb have been identified, and exemplary formulations for each identified nanomaterial have been developed.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top8_91","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"TOP8-91","sourceUrl":"https://technology.nasa.gov/patent/TOP8-91","confidence":"high"},"type":"patent","title":"Optical Mass Sensor for Multi-Phase Flows","abstract":"NASA's Marshall Space Flight Center is offering opportunities for its new fiber optic mass flow sensor system. Capable of measuring multi-phase flows in a pipe, the technology is minimally invasive, cost effective, retrofittable, and compact. MSFCs new technology combines high accuracy, intrinsically safe operation, and low-cost flow sensing for virtually any optically transparent medium, providing a superior product for measuring multi-phase flows.","category":"sensors_instruments","categoryRaw":"Sensors","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_drc_tops_8","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-TOPS-8","sourceUrl":"https://technology.nasa.gov/patent/DRC-TOPS-8","confidence":"high"},"type":"patent","title":"Real-Time, High-Resolution Terrain Information in Computing-Constrained Environments","abstract":"Data adaptive algorithms are the critically enabling technology for automatic collision avoidance system efforts at NASA's Armstrong Flight Research Center. These Armstrong-developed algorithms provide an extensive and highly efficient encoding process for global-scale digital terrain maps (DTMs) along with a real-time decoding process to locally render map data. Available for licensing, these terrain-mapping algorithms are designed to be easily integrated into an aircraft's existing onboard computing environment or into an electronic flight bag (EFB) or mobile device application. In addition to its use within next-generation collision avoidance systems, the software can be adapted for use in a wide variety of applications, including aerospace satellites, automobiles, scientific research, marine charting systems, and medical devices.","category":"software_data","categoryRaw":"information technology and software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_14","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-14","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-14","confidence":"high"},"type":"patent","title":"Hierarchical Image Segmentation (HSEG)","abstract":"Hierarchical Image Segmentation (HSEG) software was originally developed to enhance and analyze images such as those taken of Earth from space by NASAs Landsat and Terra missions. The HSEG software analyzes single band, multispectral, or hyperspectral image data and can process any image with a resolution up to 8,000 x 8,000 pixels, then group the pixels that have similar characteristics to form regions, and ultimately combines regions based on their similarity, whether adjacent or disjointed. This grouping creates spatially disjoint regions. The software is accompanied by HSEGViewer, a companion visualization and segmentation selection tool that can be used to highlight and select data points from particular regions.","category":"software_data","categoryRaw":"information technology and software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_230","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-230","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-230","confidence":"high"},"type":"patent","title":"First Stage Bootloader","abstract":"Software often has two main parts. One part is the main operating system (OS) image, which contains an OS kernel and run-time environment. The other part is the ram filesystem image, which contains application libraries. Both parts must be read from flash memory into the correct locations in DDR memory for the software to be fully operational. The system will store several copies of each file in flash memory, reducing the probability that radiation events will render a given file to be unreadable from flash memory. Previous bootloaders could read the main OS image from flash memory, read redundant copies of images, and synchronize flash memory usage between two processors sharing the same flash memory bank. However, previous bootloaders supported reading only one image from flash memory. They also do not support restarting watchdog timers, meaning the watchdog timer must be off during the boot process. The First Stage Bootloader improves on previous bootloader versions.","category":"software_data","categoryRaw":"information technology and software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_244","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-244","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-244","confidence":"high"},"type":"patent","title":"Update of the Three Dimensional Version of RHSeg and HSeg","abstract":"Image segmentation is the partitioning of an image into related sections or regions. For remotely sensed images of the Earth, an example is a map that divides the image into areas labeled by distinct Earth surface covers such as water, snow, and types of natural vegetation. A key problem encountered with RHSeg is that the image segmentation results often exhibit artifacts caused by the recursive subdivision of the image.","category":"software_data","categoryRaw":"information technology and software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_359","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-359","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-359","confidence":"high"},"type":"patent","title":"SpaceCube Mini Solid State Data Recorder (SSDR)","abstract":"Upcoming SmallSat missions at NASA and in the commercial space sector require highly performant, miniaturized, and radiation tolerant components. One need is for data recorders capable of storing large quantities of data generated by advanced sensors for extended durations. Commercially available SmallSat form factor data recorders generally either have poor reliability in high radiation environments or do not provide the high-speed read/write data rates necessary for high-performance detectors and sensors. This limits data collection ability, which also limits the ability to perform on-board processing. To meet data recording needs for SmallSat missions in harsh radiation orbits and environments (e.g., GEO, polar, lunar, etc.) innovators at NASA\u2019s Goddard Space Flight Center have developed a radiation tolerant single-board solid-state data recorder (SSDR) card. This miniaturized (3.5\u201d x 3.5\u201d) card is configured for use in a 1U CubeSat payload form factor multi-purpose architecture, enabling high density data storage and on-board processing for a variety of data-intensive SmallSat missions.","category":"software_data","categoryRaw":"Information Technology and Software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_390","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-390","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-390","confidence":"high"},"type":"patent","title":"Grid-Oriented Normalization for Analysis of Spherical Areas (GONASA)","abstract":"Accurate measurement and characterization of surface features on spherical objects, such as planets and moons, is a persistent challenge in planetary science, remote sensing, and atmospheric research. When viewed through traditional two-dimensional imaging, these spherical surfaces become distorted, particularly towards the edges, making it difficult to accurately measure important characteristics like area, perimeter, orientation, and spatial distribution. This distortion complicates the precise assessment of phenomena such as cloud coverage, geological features, or other surface events critical for scientific investigation. Thus, there is a need for a method that enables accurate and automated analysis without the distortion limitations inherent in traditional mapping approaches. NASA's innovative Grid-Oriented Normalization for Analysis of Spherical Areas (GONASA) directly addresses these challenges. The GONASA mathematical formula / algorithm provides a practical and accurate means of overcoming distortions through a novel, grid-based system of equal-area cells overlaid onto spherical surfaces. This enables users to reliably quantify and characterize objects on a sphere across entire surface, greatly enhancing the precision of scientific observations and improving the automation potential in processing and analyzing large volumes of data collected from satellite and spacecraft missions.","category":"software_data","categoryRaw":"Information Technology and Software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_394","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-394","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-394","confidence":"high"},"type":"patent","title":"STELLA-1.2","abstract":"STELLA-1.2 is an innovative low-cost, modular, open-source sensor suite designed for environmental and spectral analysis. The platform supports interchangeable sensor cartridges that attach magnetically to a central data-logging base unit, enabling users to collect air quality, spectral, and geospatial data in a flexible and accessible manner. Designed with affordability and accessibility in mind, STELLA-1.2 is built from commercially available components and can be assembled using 3D-printed snap-together parts without fasteners.","category":"software_data","categoryRaw":"Information Technology and Software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_42","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-42","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-42","confidence":"high"},"type":"patent","title":"A Method For Developing And Maintaining Evolving Systems With Software Product Lines","abstract":"Physical manufacturers have been taking advantage of mass manufacturing ideas for a long time, increasing their productivity, cutting their costs, and ensuring the quality and uniformity of their products. Now, this idea is being applied to software production so the same benefits can be reaped in that field.","category":"software_data","categoryRaw":"information technology and software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_53","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-53","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-53","confidence":"high"},"type":"patent","title":"MERRA/AS and Climate Analytics-as-a-Service (CAaaS)","abstract":"The Modern Era-Retrospective Analysis for Research and Applications (MERRA) integrates data from a variety of satellite systems with numerical models to produce a temporally and spatially consistent synthesis of climate variables that are not easily observed. MERRA provides global coverage. The MERRA time period covers the modern era of remotely sensed data, from 1979 to the present. The breadth of MERRA variableswhich include atmosphere, ocean, and land surface productsmakes MERRA ideal for investigating climate variability and for use in an expanding array of applications areas, such as national disasters, civil engineering, ecological forecasting, health and air quality, water resources, and agriculture. However, these data sets are hundreds of terabytes in size, growing to petabytes in size over the coming years. Despite their utility, it is often difficult to use this important information.","category":"software_data","categoryRaw":"information technology and software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_56","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-56","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-56","confidence":"high"},"type":"patent","title":"Otoacoustic Protection In Biologically-Inspired Systems","abstract":"The field of autonomic computing (also known in other parlance as organic computing, biologically inspired computing, self managing systems, etc...) has emerged as a promising means of ensuring reliability, dependability, and survivability in computer based systems, in particular in systems where autonomy is important. Scientists at NASA Goddard Space Flight Center have been looking at various mechanisms inspired by nature, and the human body, to improve dependability and security in such systems. Otoaural emission is used by the mammalian ear to protect from exceptionally loud noises; tailoring it to autonomic systems would enable the system to be protected by spurious signals or signals from rogue agents.","category":"software_data","categoryRaw":"information technology and software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_63","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-63","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-63","confidence":"high"},"type":"patent","title":"The Hilbert-Huang Transform Real-Time Data Processing System","abstract":"One of the main heritage tools used in scientific and engineering data spectrum analysis is the Fourier Integral Transform and its high performance digital equivalent - the Fast Fourier Transform (FFT). The Fourier view of nonlinear mechanics that had existed for a long time and the associated FFT carry strong a-priori assumptions about the source data, such as linearity and being stationary. Natural phenomena measurements are essentially nonlinear and nonstationary. A recent development at the National Aeronautics and Space Administration (NASA) Goddard Space Flight Center (GSFC), known as the Hilbert-Huang Transform (HHT) proposes a novel approach to the solution for the nonlinear class of spectrum analysis problems.","category":"software_data","categoryRaw":"information technology and software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_71","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-71","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-71","confidence":"high"},"type":"patent","title":"Automata Learning in Generation of Scenario-Based Requirements in System Development","abstract":"NASA sensor networks can be highly distributed autonomous systems of systems that must operate with a high degree of reliability. The solar system and planetary exploration networks necessarily experience long communications delays with Earth. The exploration networks are partly and occasionally out of touch with the Earth and mission control for long periods of time, and must operate under extremes of dynamic environmental conditions. Due to the complexity of these systems as well as the distributed and parallel nature of the exploration networks, the exploration networks have an extremely large state space and are impossible to test completely using traditional testing techniques. The more code or instructions that can be generated automatically from a verifiably correct model, the less likely that human developers will introduce errors.","category":"software_data","categoryRaw":"information technology and software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_gsc_tops_72","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-TOPS-72","sourceUrl":"https://technology.nasa.gov/patent/GSC-TOPS-72","confidence":"high"},"type":"patent","title":"Space Link Extension Return Channel Frames (SLE-RCF) Software Library","abstract":"The Lunar Reconnaissance Orbiter (LRO) employs many advanced innovations developed at Goddard and in collaboration with other organizations. The applications and benefits for these technologies are advantageous for many other industries as well. One of those technologies is the Space Link Extension Return Channel Frames (SLE-RCF) software library. This software library enables a mission control center to receive telemetry frames from a ground station. The technology implements the SLE-RCF protocol as defined by the Consultative Committee for Space Data Systems (CCSDS). Software routines can be reused from mission to mission.","category":"software_data","categoryRaw":"information technology and software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_148","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-148","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-148","confidence":"high"},"type":"patent","title":"Traffic Aware Strategic Aircrew Requests (TASAR)","abstract":"NASA Langley is developing Traffic Aware Strategic Aircrew Requests (TASAR). TASAR features a cockpit automation system that monitors for potential flight trajectory improvements and displays them to the pilot. These wind-optimized flight trajectory changes are pre-cleared of potential conflicts with other known airplane traffic, weather hazards, and airspace restrictions. The objective of TASAR is to improve the process in which pilots request flight path and altitude modifications due to changing flight conditions. Changes may be made to reduce flight time, increase fuel efficiency, or improve some other flight attribute desired by the operator. Currently pilots make such requests to ATC with limited awareness of what is happening around them. Consequently, some of these requests will be denied resulting in no flight improvements and an unnecessary workload increase for both pilots and ATC. The TASAR technology provides pilots with recommended flight path and altitude improvements that are more likely to be approved by ATC.","category":"software_data","categoryRaw":"information technology and software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_305","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-305","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-305","confidence":"high"},"type":"patent","title":"Adaptive Algorithm and Software for Recognition of Ground-based, Airborne, Underground, and Underwater Low Frequency Events","abstract":"The innovative approach is to exploit modern signal processing methods. i.e. adaptive filtering, where the computer is trained on-line to recognize features of the low frequency events (on the ground, in air, underground, and underwater) to be detected. Modern instrument development techniques and computational capability has enabled the development of a vastly more powerful algorithm and detection techniques.","category":"software_data","categoryRaw":"information technology and software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_360","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-360","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-360","confidence":"high"},"type":"patent","title":"Statistical Audibility Prediction (SAP) Algorithm","abstract":"Noise is difficult to escape in our daily lives. Such noise is generated by transportation vehicles, industrial equipment, hospital machines, phones, alarms, crowds, and more. Some sounds we want to suppress (e.g., airplane noise vs. conversation) and others we want to enhance (e.g., our ringing phone vs. subway noise). Predicting the extent that one sound is heard over another is difficult, yet could help engineers to better design for sound management. Innovators at the NASA Langley Research Center (LaRC) and the National Institute of Aerospace (NIA) have developed an algorithm for Statistical Audibility Prediction (SAP) of an arbitrary signal in the presence of noise. The SAP algorithm compares the loudness of signal and noise samples at matching time instances to assess audibility versus time. The continued development of this algorithm could allow engineers to suppress how we hear noise relative to sounds of interest. SAP can be implemented either as software or hardware. The algorithm has been tested using subject response data gathered in the Exterior Effects Room (EER) at NASA LaRC.","category":"software_data","categoryRaw":"Information Technology and Software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_368","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-368","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-368","confidence":"high"},"type":"patent","title":"Additive Manufacturing Model-based Process Metrics (AM-PM)","abstract":"Additive manufacturing enables unrivaled design freedom and flexible fabrication of components from a wide range of materials including metals, composites, polymers, and ceramics. The near net shape parts are made by processes like sequential melting or layer-by-layer material deposition with a complex set of processing variables. The sequential nature of the process means that every step can impact the next and thus, tools to evaluate that risk before and during manufacturing are necessary. Inventors at the NASA Langley Research Center have developed a novel method to model and ingest point-wise process data to evaluate an additive manufacturing build and its file for issues by highlighting potential anomalies or other areas where the build may have issues with fusion of the material. The technique was originally developed for use in tandem with powder bed fusion additive manufacturing for aerospace parts and is capable of being used on consumer grade computers.","category":"software_data","categoryRaw":"Information Technology and Software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_376","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-376","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-376","confidence":"high"},"type":"patent","title":"Pervasive Biocybernetic Adaptation","abstract":"Biofeedback training is a technology that enhances cognitive and emotional capabilities, empowering peak performance. What sets it apart is the Biocybernetics adaptation systems, which not only collect biofeedback data but also dynamically adjust your environment based on physiological signals. Imagine surroundings adapting \u2013 changing lighting, sounds, and more \u2013 in response to your biofeedback. Traditionally confined to clinical or training rooms, the real innovation is its integration into daily life. Whether it's pilots aiming for peak performance, individuals managing stress, or gamers seeking focus, this system offers a new level of self-regulation. Users can navigate daily life venues with real-time insights into their physiological signals, providing continuous feedback and motivation for cognitive and emotional control. Efforts yield positive surroundings, fostering well-being and peak performance.","category":"software_data","categoryRaw":"Information Technology and Software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_377","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-377","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-377","confidence":"high"},"type":"patent","title":"Biocybernetic VR/AR Training System for De-Escalating Conflict","abstract":"NASA Langley\u2019s innovative biocybernetic system employs a blend of hardware and software within a virtual/augmented/mixed reality (VR/AR/MR) environment. Its purpose is to provide psychophysiological self-regulation training, specifically geared toward helping individuals de-escalate conflicts in real-world scenarios. In this system, trainees or their avatars engage with simulated social situations involving conflict. The virtual characters they interact with are designed to present varying levels of threat or cooperation. What sets this approach apart is its continuous measurement of the trainee's cognitive and emotional states through biofeedback. The system's feedback mechanism is distinct, and drives the behavior of the virtual characters. Trainees are rewarded when they effectively achieve the desired mental and physiological states, resulting in desirable character responses. Conversely, ineffective states lead to undesirable character behavior, effectively penalizing the trainee. NASA has tailored this technology for de-escalation training, aiming to reduce physical responses in situations such as customer service interactions, flight attendant-passenger interactions, or police encounters. The system adapts the behavior of non-player characters based on the trainee's ability to attain the desired state, providing a dynamic and immersive training experience.","category":"software_data","categoryRaw":"Information Technology and Software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_382","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-382","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-382","confidence":"high"},"type":"patent","title":"Rapid Aero Modeling for Computational Experiments","abstract":"Aerodynamic modeling plays a critical role in the development of new aircraft , particularly for innovative designs aimed at urban air mobility (UAM) applications. This includes electric vertical takeoff and landing (eVTOL) aircraft , which combine features of conventional aircraft and rotorcraft. Such advanced designs offer a host of new capabilities but also introduce significantly increased complexity relative to conventional aircraft , including intricate nonlinear aerodynamic responses as well as interactions between propulsion and aerodynamic control systems. For the flight dynamics and controls disciplines, this added complexity renders detailed computational fluid dynamics (CFD) models unable to produce results fast enough for flight simulations. To address this challenge, NASA developed Rapid Aero Modeling for Computational Experiments (RAM-C), a software-implemented method capable of generating aerodynamic models that capture the important features of complex aircraft in a manner suitable for flight dynamics simulations. RAM-C can be thought of as a \u201cwrapper\u201d around computational (e.g., CFD) software, which it provides specific test inputs to, and receives aerodynamic measurements as outputs from. The input-output data are used to identify mathematical models and evaluate their statistical performance and fidelity. In essence, this NASA invention automates and streamlines the design phase for innovative aircraft while limiting computational requirements.","category":"software_data","categoryRaw":"Information Technology and Software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_61","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-61","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-61","confidence":"high"},"type":"patent","title":"Computational Visual Servo","abstract":"NASA's Langley Research Center researchers have developed an automatic measurement and control method for smart image enhancement. Pilots, doctors, and photographers will benefit from this innovation that offers a new approach to image processing. Initial advantages will be seen in improved medical imaging and nighttime photography. Standard image enhancement software is unable to improve poor quality conditions such as low light, poor clarity, and fog-like conditions. The technology consists of a set of comprehensive methods that perform well across a wide range of conditions encountered in arbitrary images. Conditions include large variations in lighting, scene characteristics, and atmospheric (or underwater) turbidity variations. NASA is seeking market insights on commercialization of this new technology, and welcomes interest from potential producers, users, and licensees.","category":"software_data","categoryRaw":"information technology and software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_lar_tops_88","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-TOPS-88","sourceUrl":"https://technology.nasa.gov/patent/LAR-TOPS-88","confidence":"high"},"type":"patent","title":"Game and Simulation Control","abstract":"NASA's Langley Research Center has developed a technology at the forefront of a new generation of computer and video game environments that train valuable mental skills, beyond eye-hand coordination, for the personal improvement, not just the diversion, of the user. Monitoring and enhancement of operator state is an objective of the current LaRC Intelligent Integrated Flight Deck Technology (IIFDT) program. Prior research by the inventor, Alan Pope, modulate (based on player physiological signals) the manual inputs that a player makes to the buttons or joysticks of a video game hand controller. However, a new type of controller allows a player to make inputs to a video game by moving the entire controller itself, allowing the present inventions entirely new approach to integrating psychophysiological signals into game play.","category":"software_data","categoryRaw":"Information Technology and Software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_114","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-114","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-114","confidence":"high"},"type":"patent","title":"Computer Vision Lends Precision to Robotic Grappling","abstract":"Innovators at NASA Johnson Space Center (JSC) have developed computer vision software that derives target posture determinations quickly and then instructs an operator how to properly align a robotic end-effector with a target that they are trying to grapple. As an added benefit, the software\u2019s object identification capability can also help detect physical defects on targets. This technology was originally created to aid robotic arm operators aboard the International Space Station (ISS) that relied more heavily upon grappling instructional maneuvers derived from flight controllers on the ground at JSC\u2019s Mission Control Center (MCC). Despite the aid of computer-based models to predict the alignment of both robotic arm and target, iterative realignment procedures were often required to correct botched grapple operations, costing valuable time. To solve this problem, NASA\u2019s computer vision software analyzes the live camera feed from the robotic arm\u2019s single borescope camera and provides the operator with the delta commands required for an ideal grasp operation. This process is aided by a machine learning component that monitors the camera feed for any of the ISS\u2019s potential target fixtures. Once a target fixture is identified, proper camera and target parameters are automatically sequenced to prepare for grasping operations.","category":"software_data","categoryRaw":"Information Technology and Software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_msc_tops_121","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-TOPS-121","sourceUrl":"https://technology.nasa.gov/patent/MSC-TOPS-121","confidence":"high"},"type":"patent","title":"Unique Datapath Architecture Yields Real-Time Computing","abstract":"Innovators at NASA Johnson Space Center have developed and successfully flight tested a high-performance computing platform, known as the Descent and Landing Computer (DLC), to suit the demands of safe, autonomous, extraterrestrial spacecraft landings for robotic and human exploration missions. Unique to this platform is a datapath architecture that unencumbers microprocessors by isolating them from input and output interruptions, thus staving off latency and maximizing computational speed for the flight software. To safely land, the DLC must process landing-specific sensor data in real-time and relay this information to the primary flight computer for the spacecraft to avoid environmental hazards like craters and boulders. The datapath architecture presented allows for the DLC\u2019s high-speed computational processing to provide this capability. This technology will be critical for safe access to other surface regions of the solar system in which spacecraft missions could not succeed with current landing capabilities. This datapath architecture technology is at a technology readiness level (TRL) 6 (system/subsystem prototype demonstration in a relevant environment) and is now available for your company to license. Please note that NASA does not manufacture products itself for commercial sale.","category":"software_data","categoryRaw":"Information Technology and Software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_175","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-175","sourceUrl":"https://technology.nasa.gov/patent/TOP2-175","confidence":"high"},"type":"patent","title":"Inductive Monitoring System","abstract":"The Inductive Monitoring System (IMS) software utilizes techniques from the fields of model-based reasoning, machine learning, and data mining to build system monitoring knowledge bases from archived or simulated sensor data. Unlike some other machine learning techniques, IMS does not require examples of anomalous (failure) behavior. IMS automatically analyzes nominal system data to form general classes of expected system sensor values. This process enables the software to inductively learn and model nominal system behavior. The generated data classes are then used to build a monitoring knowledge base. In real-time, IMS performs monitoring functions, determining and displaying the degree of deviation from nominal performance. IMS trend analyses can detect conditions that may indicate a failure or required system maintenance. The development of the IMS was motivated by the difficulty of producing detailed diagnostic models of some system components due to complexity or unavailability of design information. Previous and current IMS applications include the Hybrid Combustion Facility (HCF) advanced rocket fuel test facility, and the RASCAL UH-60 Blackhawk helicopter.","category":"software_data","categoryRaw":"information technology and software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_176","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-176","sourceUrl":"https://technology.nasa.gov/patent/TOP2-176","confidence":"high"},"type":"patent","title":"Context Based Configuration Management System","abstract":"NASA has developed a new technology to track the status of, and changes to, enterprise level programmatic operations. Enterprise decision making and operations rely on management of non-traditional configuration management (CM) components like estimates, agreements, goals, policies, etc. Additionally, enterprise operations have unique and diverse contexts/ environments such as reviews, workshops, fire drills, Office of Management and Budget (OMB) and Congressional actions, procurements, etc. NASA's innovation Context-Based Configuration Management (CBCM) system integrates decision history and decision-map systems to commercial configuration management systems, and adds intelligence and Knowledge Management (KM) to the CM components to improve enterprise-level assessments and forecasting. This web-based interactivity allows significant and unobtrusive communications and context enhancements.","category":"software_data","categoryRaw":"Information Technology and Software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_188","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-188","sourceUrl":"https://technology.nasa.gov/patent/TOP2-188","confidence":"high"},"type":"patent","title":"Selective Access and Editing in a Database","abstract":"NASA has developed a method and system that provides selective access to different portions of a database by different subgroups of database users. In this system two or more members of a given access subgroup can edit simultaneously a document accessible to each member. This database system provides selective access to different portions of the database for different groups of users, where the different groups may have overlapping access group memberships. When N users are involved, up to 2N -1 distinguishable access subgroups in a group space can be formed, and no two access subgroups can have the same members. This system is very flexible and allows for change in definition of the portions of the database accessible by a specified access group. Provisions of selective access to the database allow restriction of user access to the information contained in different portions of the database based upon need to know or another suitable authorization scheme.","category":"software_data","categoryRaw":"information technology and software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_194","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-194","sourceUrl":"https://technology.nasa.gov/patent/TOP2-194","confidence":"high"},"type":"patent","title":"Enhanced Project Management Tool","abstract":"Many organizations face complex, hierarchical program and management structures, each with its own budget, requirements, milestones, and goals. This invention is a system for managing a project that includes multiple tasks and a plurality of workers. Input information includes characterizations based upon a human model, a team model, and a product model. Periodic reports, such as monthly report, a task plan report, a schedule report, a budget report, and a risk management report, are generated and made available for display or further analysis or collection into a customized report template. An extensible database allows searching for information based upon context and content. Seven different types of project risks are addressed, including nonavailability of required skill mix of workers. The system can be configured to exchange data and results with corresponding portions of similar project analyses, and to provide user-specific access to specified information.","category":"software_data","categoryRaw":"information technology and software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_245","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-245","sourceUrl":"https://technology.nasa.gov/patent/TOP2-245","confidence":"high"},"type":"patent","title":"Interactive Diagnostic Modeling Evaluator","abstract":"NASA Ames has developed an interactive diagnostic modeling evaluator (i-DME) tool to aid in modeling for noise and lag in the data and debugging of system models when fault detection, isolation, and recovery results are incorrect. i-DME is designed to dramatically speed up the modeling debugging process. Often what hinders human-led model developments are, 1) the sheer size of playback files, 2) the modeling for noise and lag in the data, and, 3) debugging the fault/test relationships in the model. To alleviate these problems, i-DME can automatically playback very large data sets to find time points of interest where user-set performance criteria for detection and isolation are violated. i-DME modifies the diagnostic model through its abstract representation, diagnostic matrix (D-matrix). The types of modifications are procedures ranging from modifying 0s and 1s in the D-matrix adding/removing the rows/columns, or modifying test/wrapper logic used to determine test results. This software has the capacity to be applied to any complex system for navigation or generation of large amounts of complex data to identify, prioritize, and resolve errors in a self-correcting manner.","category":"software_data","categoryRaw":"Information Technology and Software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_288","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-288","sourceUrl":"https://technology.nasa.gov/patent/TOP2-288","confidence":"high"},"type":"patent","title":"Intelligent Conversational Research Assistant","abstract":"NASA Ames has developed a community-driven, context-aware intelligent research assistant system (MATA - Sanskrit name for the Earth) which is capable of engaging with users in a conversational manner using natural language dialogue, invoking external community-provided web services to obtain information or to perform actions, and vocalizes the responsive action back to the user. This novel, patented technology is an intelligent, virtual, personalized conversational research assistant system. Specifically designed for geospatial queries of Earth science data , this software application provides conversational computing, not just a conversational assistant. It is able to run on a personal computer or a mobile phone that facilitates user interaction with the system. This technology allows users to add new capabilities and new Application Programming Interfaces (APIs) so that it can be applied to a wide variety of applications.","category":"software_data","categoryRaw":"Information Technology and Software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_294","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-294","sourceUrl":"https://technology.nasa.gov/patent/TOP2-294","confidence":"high"},"type":"patent","title":"Space Traffic Management (STM) Architecture","abstract":"Space is becoming increasingly congested due to rising numbers of on-orbit satellites and debris objects. Despite growing awareness of the orbital debris problem, recent developments such as launch ride sharing, growth in availability of small launch vehicles, and particularly large scale satellite constellation deployments, are dramatically increasing on-orbit congestion. Uncontrolled growth will severely affect future space operations. NASA Ames has developed a novel technology known as Space Traffic Management (STM) which provides a robust framework for on-orbit coordination of activities to enhance the safety, stability, and sustainability of operations in the space environment. The STM system is critical for ensuring that the expanding orbital population operates safely and efficiently, avoiding collisions and radio-frequency interference while still facilitating widespread space operations in an increasingly congested space environment. Additionally, it meets the objectives associated with the transition of civil STM from the Department of Defense to a civilian entity.","category":"software_data","categoryRaw":"Information Technology and Software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_305","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-305","sourceUrl":"https://technology.nasa.gov/patent/TOP2-305","confidence":"high"},"type":"patent","title":"Enhancing Fault Isolation and Detection for Electric Powertrains of UAVs","abstract":"NASAs System-Wide Safety (SWS) project is developing innovative data solutions to assure safe, rapid, and repeatable access to a transformed National Airspace System. The increasing number of electric propulsion systems that will enter the airspace will require systems that ensure high safety standards in the low-altitude airspace. One element that can help ensure safety is proper diagnosis of failures via Fault Detection and Isolation (FDI). NASA Ames has developed a fault isolation approach for electric powertrains of unmanned aerial vehicles. It leverages a combination of Failure Mode and Effect Analysis (FMEA) and Bayesian Networks (BN) to create a dependability structure within a diagnostic framework-mapping fault and failure events from the FMEA within a BN. This framework helps the fault isolation process by identifying the probability of occurrence of specific fault or root causes given evidence observed through sensor signals.","category":"software_data","categoryRaw":"information technology and software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_306","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-306","sourceUrl":"https://technology.nasa.gov/patent/TOP2-306","confidence":"high"},"type":"patent","title":"Meta Monitoring System (MMS)","abstract":"Various software approaches exist that determine whether a given instrumented system is experiencing anomalous behavior. Many anomaly detection systems simply generate some type of deviation score, then rely on a subject matter expert to evaluate the data and recommend a course of action. These evaluations are often nontrivial and can lead to false alarms. NASAs Meta Monitoring System (MMS) is an add-on to these types of anomaly detection systems that helps one to better interpret such deviation scores and determine whether detected anomalous behavior is transient or systemic. While MMS was developed as an add-on to NASAs patented Inductive Monitoring System (IMS) anomaly detection software, which could be used alongside this invention to provide a complete anomaly detection solution, it can integrate with any anomaly detection system that generates deviation scores.","category":"software_data","categoryRaw":"information technology and software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_314","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-314","sourceUrl":"https://technology.nasa.gov/patent/TOP2-314","confidence":"high"},"type":"patent","title":"Centralized Data Management Platform","abstract":"Many organizations have data stored in differing formats and various locations throughout the organization and often outside the organization. It is often difficult to access such data and to determine and access interconnected data and data derivatives. Developed at NASA Ames Research Center is a novel data management platform for managing interconnected data and its derivatives. The data management platform is able to receive miscellaneous data assets, analyze and reformat the assets using corresponding data models, link data assets by identifying interconnections between the data , and store the miscellaneous data assets in a database management system. This advance data management and analysis platform that allows the integration of heterogeneous data sets, employs machine learning to effect real-time data discovery, and dynamically associates data assets based on their content to generate data relationships.","category":"software_data","categoryRaw":"Information Technology and Software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_top2_320","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"TOP2-320","sourceUrl":"https://technology.nasa.gov/patent/TOP2-320","confidence":"high"},"type":"patent","title":"Near-Real Time Verification and Validation of Autonomous Flight Operations","abstract":"Autonomous systems necessitates timely technological audits to evaluate their performance, conformance, and compliance. For the aviation industry, such a need has already been recognized by the Federal Aviation Administration (FAA) for the vehicles, sensors, and systems participating in Extensible Traffic Management (xTM) systems. xTM systems include the Unmanned Aircraft Systems (UAS) Traffic Management (UTM), Advanced Air Mobility (AAM), and Upper-Class E Traffic Management, and are complementary to the Air Traffic Management (ATM) system. xTM systems enable new entrants such as UAS and AAM vehicles to safely participate in the national airspace. To facilitate timely technological audits of the xTM participants, NASA Ames developed a novel technology that provides near-real-time verification and validation of autonomous flight operations of an individual vehicle or numerous diverse vehicles being managed by the xTM systems.","category":"software_data","categoryRaw":"Information Technology and Software","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0"},{"forgeId":"forge_nasa_arc_12112_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-12112-1","sourceUrl":"https://software.nasa.gov/software/ARC-12112-1","confidence":"high"},"type":"software","title":"ARC2D (Efficient Two-Dimensional Solution Methods For The Navier-Stokes Equations)","abstract":"ARC2D is a computational fluid dynamics program developed at the NASA Ames Research Center specifically for two-dimensional airfoil and simply connected geometries. The program uses implicit finite-difference techniques to solve two-dimensional Euler equations and Navier-Stokes equations. It is based on the Beam and Warming implicit approximate factorization algorithm in generalized coordinates. The methods are either time accurate or accelerated non-time accurate steady state schemes. The evolution of the solution through time is physically realistic; good solution accuracy is dependent on mesh spacing and boundary conditions.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_14400_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-14400-1","sourceUrl":"https://software.nasa.gov/software/ARC-14400-1","confidence":"high"},"type":"software","title":"PLOT3D, Version 4.1","abstract":"PLOT3D is a computer graphics program designed to visualize the grid and solutions of structured computational fluid dynamics (CFD) datasets. Version 4.1 uses the OpenGL/GLUT graphics library. Several new features have been added to the code. These include: automatic computation of grid coordinate minimum/maximum; an orphan point plotting function; the ability to read double-precision unformatted data ; negative grid index processing; random specification of colors for different walls; and simultaneous specification of walls and subsets for all zones.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_14467_1b","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-14467-1B","sourceUrl":"https://software.nasa.gov/software/ARC-14467-1B","confidence":"high"},"type":"software","title":"CFD Utility Software Library","abstract":"A collection of ~200 software applications build upon two dozen subroutine libraries, mostly for manipulating the grids and flow solutions associated with computational fluid dynamics (CFD). These application programs, Fortran 90 modules, and library subroutines are generalized as far as possible with reuse and portability in mind. They are applicable to all flight regimes - subsonic, transonic, supersonic, and hypersonic. They operate on files in PLOT3D and/or Tecplot format, which represent de facto standards at many sites within academia, NASA, and industry. All such sites should have comparable utilities but typically lack this kind of comprehensive collection of well designed, well implemented and efficient utilities maintained for general use.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/cfdtools","license":null}},{"forgeId":"forge_nasa_arc_15068_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-15068-1","sourceUrl":"https://software.nasa.gov/software/ARC-15068-1","confidence":"high"},"type":"software","title":"Airspace Concepts Evaluation System (ACES)","abstract":"From gate departure to gate arrival, ACES is a dynamic, event-based computer simulation of aircraft operations in the National Airspace System (NAS). The technology's software-agent infrastructure provides flexibility in configuring custom simulations and enables explicit modeling of command and control entities operating within the NAS.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_15117_1a","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-15117-1A","sourceUrl":"https://software.nasa.gov/software/ARC-15117-1A","confidence":"high"},"type":"software","title":"Pegasus 5.2: Software For Automated Pre-Processing of Overset CFD Grids","abstract":"The Pegasus software is used as a pre-processor for overset-grid Computational Fluid Dynamics (CFD) simulations. It provides the hole-cutting and connectivity information between structured overset grids. The main features of the software include automated hole-cutting algorithms, a projection scheme for fixing small discretization errors in overset surface; efficient interpolation search methods; hole-size optimization based on adding additional layers of fringe points; and an automatic restart capability. The code can run in parallel using the Message-Passing Interface (MPI) standard. The parallel performance provides efficient speed-up of the execution time utilizing dozens or even hundreds of processors. The additional capabilities in the new 5.2 version include: support for cell-centered grids; triple-fringe option; automated domain decomposition into multiple hole-cutters; improved parallel execution load-balancing algorithm; and additional minor enhancements.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_15166_1e","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-15166-1E","sourceUrl":"https://software.nasa.gov/software/ARC-15166-1E","confidence":"high"},"type":"software","title":"NASA World Wind Java (WWJ) Software Development Kit (SDK) Version 2.2","abstract":"WorldWind is a free, open source software development kit (SDK) for assisting developers in the creation of geographical information systems (GISs). Aside from educational examples and tutorials, the WorldWind SDK does not provide finished applications. The WorldWind SDK is used by software engineers to build their own applications. Common use cases for the WorldWind SDK are monitoring weather patterns, visualizing cities and terrain, tracking ground vehicles, analyzing geospatial data, flight tracking, satellite tracking and geographical education. WorldWind provides a powerful platform for giving any application the means to express, manipulate, and analyze spatial data.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASAWorldWind/WorldWindJava/releases/","license":null}},{"forgeId":"forge_nasa_arc_15250_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-15250-1","sourceUrl":"https://software.nasa.gov/software/ARC-15250-1","confidence":"high"},"type":"software","title":"Upwind Parabolized Navier-Stokes Solver (UPS) for Supersonic and Hypersonic Flow Simulation , Version 6.1","abstract":"This software provides a means for simulating supersonic and hypersonic flows efficiently and accurately (under certain restrictions). The parabolized Navier-Stokes (PNS) equations are solved using an upwind finite-volume algorithm that is implicit in the marching direction. The solver includes models for turbulent flow and equilibrium- and finite-rate air chemistry.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_15601_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-15601-1","sourceUrl":"https://software.nasa.gov/software/ARC-15601-1","confidence":"high"},"type":"software","title":"Finite-Rate Chemistry, Overset-Grid, Dual-Time Combustion-Reentry Code","abstract":"This technology modifies the OVERFLOW code for finite rate and equilibrium chemistry by substituting the perfect gas model built into the code with a model assuming a gas made up of a mixture of thermally perfect gases. Four extra field variables were added, corresponding to pressure, temperature, coefficient of thermal conductivity, and the new pressure derivative X.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_16025_1c","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16025-1C","sourceUrl":"https://software.nasa.gov/software/ARC-16025-1C","confidence":"high"},"type":"software","title":"Chimera Grid Tools version 3.0","abstract":"The Chimera Grid Tools (CGT) software package is used for performing pre- and post-processing of computational fluid dynamics (CFD) analysis on complex configurations using overset grids. It contains a collection of software tools for performing geometry processing, surface and volume grid generation, grid manipulation and diagnostics, flow solver input preparation, multi-body dynamics input preparation and animation, flow solution visualization , debris trajectory analysis input preparation, strand grid and AMR Cartesian grid visualization , flow solution post-processing analysis including forces and moments computation, and convergence history visualization . New technologies developed under version 3.0 include the EPOGS toolset for automation of over-set structured mesh generation, an improved FFIO Library for general file i/o in the overset CFD process, and the BladeGen tool for meshing rotor blades.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_16063_1a","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16063-1A","sourceUrl":"https://software.nasa.gov/software/ARC-16063-1A","confidence":"high"},"type":"software","title":"Traffic Situation Display (TSD)","abstract":"The Traffic Situation Display (TSD) is an integrated display of air traffic, weather, terrain, and special use airspace. TSD was designed to serve as a primary graphical interface for ground operators/dispatchers supporting research simulation of single pilot and/or reduced crew operations. One key feature is the seamless transitional flow between the ego-referenced and position-referenced frames.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_16260_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16260-1","sourceUrl":"https://software.nasa.gov/software/ARC-16260-1","confidence":"high"},"type":"software","title":"SUPKEM","abstract":"SUMKEM is fully implicit, parabolic, partial-differential equation solver that can be used for the integration of unsteady 3D turbulence kinetic energy and dissipation-rate equations. The technology enables any laminar computational fluid dynamics (CFD) solver to compute a given unsteady turbulent flow of interest.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_16265_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16265-1","sourceUrl":"https://software.nasa.gov/software/ARC-16265-1","confidence":"high"},"type":"software","title":"NASA Design and Analysis of Rotorcraft (NDARC)","abstract":"NDARC software is an aircraft system analysis tool that supports both conceptual design efforts and technology impact assessments of rotorcraft that meet specified requirements. The architecture of the NDARC code accommodates configuration flexibility, a hierarchy of models, and ultimately multidisciplinary design, analysis , and optimization.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_16433_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16433-1","sourceUrl":"https://software.nasa.gov/software/ARC-16433-1","confidence":"high"},"type":"software","title":"Trajectory-Based Route Analysis and Control (TRAC)","abstract":"TRAC is an extensible software platform that supports next-generation air traffic concept investigations. The software enables visualization of current-day airspace elements; graphical creation of new elements; and runway-to-runway agent-based simulation and analysis of air traffic concepts.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_16808_1a","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16808-1A","sourceUrl":"https://software.nasa.gov/software/ARC-16808-1A","confidence":"high"},"type":"software","title":"Surface Operations Simulator and Scheduler (SOSS)","abstract":"A simulation of air traffic movement on an airport surface, SOSS can be used in developing, analyzing, and testing runway schedulers and resolution algorithms.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_16827_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16827-1","sourceUrl":"https://software.nasa.gov/software/ARC-16827-1","confidence":"high"},"type":"software","title":"StormGen Weather Editor","abstract":"The StormGen interactive editor facilitates the design and production of dynamic convective weather scenarios. The software exports weather data in formats compatible with widely used air- and ground-tool simulators.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_16853_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16853-1","sourceUrl":"https://software.nasa.gov/software/ARC-16853-1","confidence":"high"},"type":"software","title":"Sector 33 App","abstract":"Offering a single user interface, Sector 33 is an air traffic control simulator game for Apple and Droid mobile devices. The technology includes introductory videos, an interactive air traffic control simulation of up to five airplanes; problem scoring; and integrated solution hints. The game can be downloaded at: http://www.nasa.gov/connect/apps.html","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://itunes.apple.com/us/app/sector-33-classroom-edition/id977302903?ls=1&mt=8","license":null}},{"forgeId":"forge_nasa_arc_17115_1a","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-17115-1A","sourceUrl":"https://software.nasa.gov/software/ARC-17115-1A","confidence":"high"},"type":"software","title":"Control Allocation Technique to Recover from Pilot Induced Oscillations (CAPIO) through the estimation and minimization of phase lag introduced to the system due to control surface rate saturation","abstract":"The Control Allocation Technique to Recover from Pilot Induced Oscillations (CAPIO) system is designed to operate within an aircraft's flight control system to alleviate Pilot Induced Oscillation tendencies in an aircraft without adversely impacting aircraft efficiency. The main idea behind the concept is to minimize the phase lag introduced to the system due to control surface rate saturation. The CAPIO system is designed specifically for multi-input/multi-output applications and this implementation utilizes 1) on-line estimation of phase lag introduced by control surface rate limiting, 2) on-line adjustment of control allocation weighting terms, and 3) an optimization algorithm (available from MathWorks) that calculates the optimal control solution.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_17185_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-17185-1","sourceUrl":"https://software.nasa.gov/software/ARC-17185-1","confidence":"high"},"type":"software","title":"X-Plane Communication Toolbox (XPC)","abstract":"The X-Plane Connect Toolbox enables users to receive real-time information on one or more simulated vehicles state from the X-Plane flight simulator, and control vehicles running in the X-Plane simulation environment. The toolbox can be used to record simulated flight data, visualize flight profiles, create out-the-window visuals, test autopilots, and test control algorithms. Additionally, the toolbox enables the display of ghost traffic flying predefined flight paths in the simulated airspace, and the visualization of flight plans in the form of waypoints. The toolbox allows custom built or third party autopilot programs to interface with X-Plane through MATLAB, C, C , Java, or Python . Code examples are included in the open source distribution. The toolbox uses a network communication protocol, allowing X-Plane and the client program to run on different computers.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/XPlaneConnect","license":null}},{"forgeId":"forge_nasa_arc_17449_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-17449-1","sourceUrl":"https://software.nasa.gov/software/ARC-17449-1","confidence":"high"},"type":"software","title":"MFSim - Multi-fidelity Simulation","abstract":"MFS (Multi-Fidelity Simulator) is a pluggable framework for creating an air traffic flow simulator at multiple levels of fidelity. The framework is designed to allow low-fidelity simulations of the entire US Airspace to be completed very quickly (on the order of seconds). The framework allows higher-fidelity plugins to be added to allow higher-fidelity simulations to occur in certain regions of the airspace concurrently with the low-fidelity simulation of the full airspace.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://ti.arc.nasa.gov/opensource/projects/","license":null}},{"forgeId":"forge_nasa_arc_17749_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-17749-1","sourceUrl":"https://software.nasa.gov/software/ARC-17749-1","confidence":"high"},"type":"software","title":"RACE - Runtime for Airspace Concept Evaluation","abstract":"RACE is a software architecture and framework for configurable, highly concurrent and distributed message based systems. RACE can be used to rapidly build simulations that span several machines (including synchronized displays), interface existing hardware simulators and other live data feeds, and incorporate sophisticated visualization components such as NASAs WorldWind viewer. RACE is implemented as a distributed actor system that runs within Java virtual machines.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASARace/race","license":null}},{"forgeId":"forge_nasa_arc_17793_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-17793-1","sourceUrl":"https://software.nasa.gov/software/ARC-17793-1","confidence":"high"},"type":"software","title":"Flight Awareness Collaboration Tool (FACT)","abstract":"The Flight Awareness Collaboration Tool (FACT) is designed to assist airline dispatchers and others in managing winter weather events. It gathers all of the necessary weather, air traffic, airport and other information onto one screen. This can be used by airline dispatchers to manage the airline fleet prior to and including the day of the winter weather event. It also has built-in automation tools that can predict the impact of winter weather on airport capacity. FACT is designed to support collaboration between the airline dispatcher, air traffic control tower, airport authority, and de-icing operators.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_17917_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-17917-1","sourceUrl":"https://software.nasa.gov/software/ARC-17917-1","confidence":"high"},"type":"software","title":"SMS/SDSS STBO Data Fuser","abstract":"Develop a mechanism that combines multiple sources of air traffic, airline, and airport data that contain many overlapping or similar types of data and create a unified set of data that can be used for Surface Trajectory Based Operations (STBO) air traffic management systems.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/atd2-fuser","license":null}},{"forgeId":"forge_nasa_arc_18066_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18066-1","sourceUrl":"https://software.nasa.gov/software/ARC-18066-1","confidence":"high"},"type":"software","title":"FRET : Formal Requirements Elicitation Tool","abstract":"FRET is a framework for the elicitation, formalization and understanding of requirements. FRET allows its user to enter hierarchical system requirements in a structured natural language. Requirements written in this language are assigned unambiguous semantics. FRET supports its user in understanding this semantics and reformulating requirements if applicable, by utilizing a variety of forms for each requirement: natural language description, formal mathematical logics, diagrams, and interactive simulation . FRET exports requirements into forms that can be used by a variety of analysis tools, such as Cocosim, Simulink Design Verifier, Kind, and SMV.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-SW-VnV/fret","license":null}},{"forgeId":"forge_nasa_arc_18184_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18184-1","sourceUrl":"https://software.nasa.gov/software/ARC-18184-1","confidence":"high"},"type":"software","title":"RCOTOOLS - Rotorcraft Optimization Tools","abstract":"RCOTOOLS provides utilities and application wrappers for the conceptual design of rotorcraft using an optimization framework. It currently has application wrappers for NDARC (NASA Design and Analysis of RotorCraft), CAMRAD II (Comprehensive Analytical Model of Rotorcraft Aerodynamics and Dynamics II), NPSS (Numerical Propulsion System Simulation ), IXGEN (Intelligent Cross-section Generator) and CHARM (Comprehensive Hierarchical Aeromechanics Rotorcraft Model). These wrappers can be used independently or within an optimization using NASA's OpenMDAO optimization framework.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_18198_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18198-1","sourceUrl":"https://software.nasa.gov/software/ARC-18198-1","confidence":"high"},"type":"software","title":"Automatic Discovery of Precursors in Time Series Data (ADOPT) code release","abstract":"ADOPT (abbr. Automatic Discovery Of Precursors in Time series) is a data mining/ machine learning algorithm that processes large volumes of time series data and identifies precursors to adverse events. An adverse event may refer to any unsafe event ranging from a negligible safety hazard to a catastrophic accident, depending on the scope of the analysis . A precursor is an early indicator of an increasing likelihood of the adverse event. Identifying precursors is important in the context of a proactive safety management because precursors detect the increasing severity of the underlying hazard much earlier, giving sufficient time to identify, analyze and implement corrective actions. ADOPT analyzes large volumes of historical data to find complex trends among several sensory variables simultaneously to find precursors. ADOPT's data mining approach captures real-world effects such as human factors, weather, geographic constraints, operating procedures, airline strategies etc. that are difficult to capture using first-principle models. The following are ADOPT's capabilities - new functionality to discover precursors to events of interest by mining time series data, reduces the time required by subject matter experts to discover and analyze precursors from large volumes of data, detects the likelihood of the adverse event earlier to alert the operator on an impending failure, assists in explaining the event of interest with identified precursors.The ADOPT algorithm is a general methodology that does not make any special assumptions about the system and does not need specialized knowledge on the system states enabling it to operate directly on the observed time series data. Further, it can scale well to multivariate time series and can analyze large number of flights, which may enable a faster turnaround time for subsequent tasks such as hazard identification and safety risk analysis . A subject matter expert may require a few hours to analyze a flight for precursors which is not scalable considering the thousands of flights operated on a daily basis. Also, human experts may not be able to visualize hundreds of time series variables to notice complex variations and trends in the data. ADOPT may be used to speed this process by analyzing the thousands of flights that operate every day to short-list only the significant precursors which may then be analyzed by a subject matter expert, reducing the turnaround time for safety analysis .While the motivation to find precursors came from analyzing safety (negative events), the method is general to be applied to performance issues as well as to understand positive events such as finding precursors to a high throughput operation at an airport.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/ADOPT","license":null}},{"forgeId":"forge_nasa_arc_18753_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18753-1","sourceUrl":"https://software.nasa.gov/software/ARC-18753-1","confidence":"high"},"type":"software","title":"CAPE - Computational Aerosciences Productivity & Execution","abstract":"CAPE is software that provides an end-to-end framework for running large numbers of Computational Fluid Dynamic (CFD) simulations, extracting aerodynamic performance data , and building high-quality, complex aerodynamic databases. Computational Aerosciences Productivity & Execution (CAPE) is thus a software package that aims to dramatically improve the capabilities and productivity of CFD users.CAPE enables more complex run matrices and improved procedures for other CFD or Computational Aerosciences tools. Version 1.0 provides a common interface for Cart3D, FUN3D, and OVERFLOW. CAPE takes a tip-to-tail approach to the computational aerosciences process; its interface supports case set up, running the actual CFD solver in a supercomputing environment, report generation, data extraction, and creating high-quality databases. CAPE does NOT include any of the supported CFD solvers, which must be acquired separately.This tool is distributed as a Python package, which makes it easy to install. Within NASA, the CAPE package has an extensive history with large CFD run matrices and many terabytes of data . Examples in support of the Space Launch System Program include studies separately involving about 25,000 Cart3D cases, 1500 OVERFLOW cases, and 15,000 FUN3D cases.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":"https://github.com/nasa/cape","license":null}},{"forgeId":"forge_nasa_arc_18778_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18778-1","sourceUrl":"https://software.nasa.gov/software/ARC-18778-1","confidence":"high"},"type":"software","title":"Support Libraries for Cart3D I/O Functions and Extensible Design Description Markup","abstract":"This is a collection of software libraries used for various I/O functions of the Cart3D aerodynamic analysis and optimization package. This includes reading and writing surface triangulation files, volume mesh files and files for aerodynamic shape optimization problems.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://data.nas.nasa.gov/cart3d/download_data.php?file=/cart3ddata/c3dlibs_v1.0.159--22.11.11.tgz","license":null}},{"forgeId":"forge_nasa_arc_18884_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18884-1","sourceUrl":"https://software.nasa.gov/software/ARC-18884-1","confidence":"high"},"type":"software","title":"Data & Reasoning Fabric (DRF) Core","abstract":"Operations in dynamic environments require decisions based on diverse and evolving data, including vehicle, airspace, weather, infrastructure, payload, and customer data. The complexity and density of these operations are expected to increase significantly over the next several decades. This will necessitate new strategies and systems that leverage emerging technologies to manage increasingly complex environments, especially in urban areas where rich data streams from smart cities will be crucial for efficient operations. The goal of the Data & Reasoning Fabric (DRF) is to address these challenges by enabling a self-sustaining marketplace where data and reasoning providers can advertise their services, and data and reasoning consumers can discover, vet, purchase, interconnect, and utilize these services to accomplish their missions. DRF is a framework for an ecosystem that encourages commercial industries to exchange information with each other while monetizing their digital assets and maintaining control of their intellectual property. It also allows government entities to enforce policies and regulations. DRF is an open and scalable framework that abstracts the technical complexities of data and AI services while providing interoperability and data protection across the cloud-to-edge continuum using decentralized networks, advanced cryptography methods, distributed interoperability architecture, and support for economic activities.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_19062_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-19062-1","sourceUrl":"https://software.nasa.gov/software/ARC-19062-1","confidence":"high"},"type":"software","title":"Launch Ascent And Vehicle Aerodynamics (LAVA)","abstract":"The Launch, Ascent, and Vehicle Aerodynamics (LAVA) Framework, developed by NASA Ames Computational Aerosciences Branch, is an integrated Computational Fluid Dynamics (CFD) and multiphysics environment with automated pre and postprocessing and grid generation. Evolving since the late 2000s, LAVA uses a modern architecture to deliver advanced methods and high-performance computing efficiency. It minimizes user effort through robust automation across three mesh paradigms: blockstructured curvilinear overset meshes, Cartesian immersed boundary meshes with blockstructured adaptive mesh refinement, and arbitrary polyhedral unstructured meshes. Users can choose fully automated Cartesian meshes, the builtin Voronoi mesh generator, or handcrafted bodyfitted structured grids. LAVA solves compressible NavierStokes equations with finitedifference and finitevolume schemes up to fourthorder space/time accuracy, supporting WMLES with GPU acceleration, as well as hybrid RANS/LES and RANS on CPUs. Multiphysics capabilities include multispecies/multiphase flows, fluidstructure interaction, conjugate heat transfer, sixDOF motion, AMR, and shape optimization, with insitu visualization for large, practical aerospace simulations across research, development, and engineering.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_19207_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-19207-1","sourceUrl":"https://software.nasa.gov/software/ARC-19207-1","confidence":"high"},"type":"software","title":"sBOOM2 - An advanced sonic boom propagation and design tool","abstract":"This innovation presents an approach to not only predict the sonic boom ground signatures by numerically solving the Augmented Burgers' equation but also allows the crucial step of efficiently computing the sensitivities of various sonic boom loudness metrics, both at the ground level and mid-field levels, with respect to the aircraft outer mold line parameters. This unique new functionality represents a major milestone in sonic boom mitigation literature and offers a game-changing design methodology for commercial supersonic aircraft design .","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_19208_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-19208-1","sourceUrl":"https://software.nasa.gov/software/ARC-19208-1","confidence":"high"},"type":"software","title":"sBOOM An advanced sonic boom propagation tool","abstract":"This innovation presents an approach to predict the sonic boom ground signatures accurately by numerically solving the Augmented Burgers' equation. The method is capable of predicting sonic boom signatures with consideration of atmospheric losses to account for the realistic attenuation of the sonic boom waveforms. This software is an enhanced version of the software sBOOM, currently in the software catalog. The updated numerical discretization of the governing equations is fully conservative and duality preserving. As a result of these improvements, there is a significant reduction in the number of points required to convergence of ground loudness metrics. Computation of loudness metrics is performed using digital filters. This improves the loudness calculation particularly at high sampling frequencies. The method is capable of predicting under-track and off-track ground signatures, with or without wind effects, along with consideration for aircraft maneuvers. This method is efficient and accurate, making it a very useful analysis tool in the development of supersonic cruise aircraft.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_drc_014_004","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-014-004","sourceUrl":"https://software.nasa.gov/software/DRC-014-004","confidence":"high"},"type":"software","title":"Quad-Channel Transport Class Model (Quad TCM) Simulation","abstract":"The aerospace industry uses model aircraft simulation systems to demonstrate and evaluate new computer hardware and software components for flight operations. Formal methods--mathematically based techniques--are used for verification and validation of new systems prior to implementation. By integrating and simulating new tools and methods in model flight control and air transportation systems, flight researchers provide the robust validation tools necessary for commercial system development. Developed at NASA's Armstrong Flight Research Center, the Quad TCM Simulation is a non-proprietary, non-sensitive aircraft Simulink&reg; flight-control-system-oriented model in MATLAB&reg; format. Derived from the TCM developed at NASA's Langley Research Center, Armstrong's Quad TCM Simulation components include flight control computers, sensors, actuators, and interconnects. Component models are the original TCM components with modifications to account for their multichannel nature, to allow for replacement with like components, and to enable testing and evaluation. BENEFITS * Non-proprietary and non-sensitive: Imposes no restrictions on reporting results * Ready to use: Fully integrated with flight control laws, redundancy management, multichannel interconnects, and transport class aircraft simulation * Easily modified: Enables flight control laws to be readily modified--including introduction of faults--thanks to the MATLAB Simulink environment * Speeds technology transfer: Accelerates dissemination and commercial acceptance of formal-methods-compliant tools and techniques APPLICATIONS This software is ideal for control research in realistic multichannel flight controls. In addition, it helps with learning about the complex effects of multichannel flight systems, including failure modes and effects, flight control system performance, etc. It is also useful for general simulation projects and flight system testing. MATLAB and Simulink are registered trademarks of The MathWorks, Inc.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_drc_014_036","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-014-036","sourceUrl":"https://software.nasa.gov/software/DRC-014-036","confidence":"high"},"type":"software","title":"EZASE Easy Aeroelasticity: A Tool to Simulate Aircraft Wing Geometry","abstract":"This easy-to-use open source MATLAB&#174;- based software was first developed to give X-56A aircraft engineers a modeling tool to understand aeroservoelasticity. EZASE now introduces students and practicing engineers to aeroservoelastic phenomena in flexible structures. Useful for analysis and control design of flutter or gust-load alleviation, EZASE is applicable to ground vibration, cantilever loading, and wind tunnel testing. This finite element modeling and simulation tool for aeroservoelastic analysis of rectangular wings with trailing-edge control surfaces includes a tutorial on structural finite element modeling (FEM_Tutorial.m). The tutorial uses such elements as 12 degree-of-freedom (DOF) plates and 6 DOF beams. An aero tutorial (DLM_VLM_Tutorial.m) shows how to code doublet lattice and vortex lattice, with symmetry capability. Together, the finite element and aero tutorials can be used to compare to experimental studies, such as ground vibration testing, cantilever beam analysis, and wind tunnel testing. The primary code, EZASE.m, links structures and aero together in a commented way to produce a wing in flutter which can be controlled. The wing may include control surfaces, or they can be excluded. A state space model with control surface inputs and accelerometer outputs can be produced. This model is used to design a proportional-integral-derivative (PID) control system and is tested using margin studies and pole plots. Other visualization methods such as V-g plots (velocity versus g loads) determined using the K-method are also included. The code is commented for graduate and undergraduate students who want to know the basic concepts of medium-fidelity aeroservoelastic modeling. (Not all methods are coded to industry standards, but it is useful for basic understanding.) All of the details of the code are open sourced here and most is referenced at the top of the file to its source paper or book section. Two AIAA publications--one focusing on verification and validation (V&V) with experimental wind tunnel test and ground vibration test data--are also included. FEATURES * Produces models in seconds * Includes tutorial and references * Makes videos for intuitive understanding of gust/flutter dynamics * Enables easy modification of a full range of parameters MATLAB is a registered trademark of The Mathworks, Inc.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_15728_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-15728-1","sourceUrl":"https://software.nasa.gov/software/GSC-15728-1","confidence":"high"},"type":"software","title":"Orbit-Determination Toolbox","abstract":"Based on MATLAB and Java, the flexible Orbit-Determination Toolbox is intended primarily for the advanced mission analysis that might be performed in the concept exploration, proposal, and early design phases. Visit the following URL for more information: http://opensource.gsfc.nasa.gov/projects/ODTBX/","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://sourceforge.net/projects/odtbx/","license":null}},{"forgeId":"forge_nasa_gsc_18128_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18128-1","sourceUrl":"https://software.nasa.gov/software/GSC-18128-1","confidence":"high"},"type":"software","title":"Core Flight Executive Version 6.7","abstract":"The Core Flight Executive (cFE) is a software framework designed for use on embedded systems. The cFE defines an Application Programmer Interface (API) to the following services: Software Bus, Time Services, Event Services, Executive Services, Table Services, and File Services. The cFE defines a portable application runtime environment that allows developers to rebuild the same applications code and run it on many different hardware/operating system platforms. The same application code can be developed and unit tested on a desktop environment then ported to the target-embedded processor for final verification and validation.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/cfs","license":null}},{"forgeId":"forge_nasa_lar_13995_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-13995-1","sourceUrl":"https://software.nasa.gov/software/LAR-13995-1","confidence":"high"},"type":"software","title":"WINGDES2 - Wing Design And Analysis Code (WDES)","abstract":"Wing-design algorithm based on modified linear theory taking into account effects of attainable leading-edge thrust. Provides analysis as well as design capability and applicable to both subsonic and supersonic flow.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_14458_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-14458-1","sourceUrl":"https://software.nasa.gov/software/LAR-14458-1","confidence":"high"},"type":"software","title":"AERO2S - Subsonic Aerodynamic Analysis of Wings With Leading- And Trailing-Edge Flaps In Combination with Canard or Horizontal Tail Surfaces","abstract":"Subsonic modified linear theory method providing estimates of the longitudinal aerodynamic characteristics of conceptual airplane lifting surface arrangements. The method is particularly well suited to configurations which, because of high speed flight requirements, must employ thin wings with highly swept leading edges. The code is applicable to wings with either sharp or rounded leading edges. The code provides theoretical pressure distributions over the wing, the canard or horizontal tail, and the deflected flap surfaces as well as estimates of the wing lift, drag, and pitching moments which account for attainable leading edge thrust and leading edge separation vortex forces.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_15968_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-15968-1","sourceUrl":"https://software.nasa.gov/software/LAR-15968-1","confidence":"high"},"type":"software","title":"Shape Parameterization Algorithm (MASSOUD)","abstract":"The MASSOUD and/or Bandaids software packages are geometry parameterization tools that may be used to perform design optimization with NASA's FUN3D and other CFD codes.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_16260_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-16260-1","sourceUrl":"https://software.nasa.gov/software/LAR-16260-1","confidence":"high"},"type":"software","title":"Langley Stability and Transition Analysis Code (LASTRAC)","abstract":"LASTRAC is a C code that analyzes compressible boundary-layer stability and performs transition prediction using the state-of-the-art Linear Stability Theory (LST) or Parabolized Stability Equations (PSE) methods.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_16666_gs","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-16666-GS","sourceUrl":"https://software.nasa.gov/software/LAR-16666-GS","confidence":"high"},"type":"software","title":"TLNS3D","abstract":"This software was developed to solve Reynolds-averaged Navier-Stokes Equations to simulate turbulent, viscous flows over three-dimensional configurations. A general multiblock grid is used to model complex configurations. A multi-stage Runge-Kutta pseudo-time stepping scheme is coupled with residual smoothing and multigrid acceleration techniques to form an efficient algorithm. TLNS3D-MB was the first CFD code to demonstrate grid independent convergence rate for transonic viscous flows over wing/fuselage configurations.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/TLNS3D","license":null}},{"forgeId":"forge_nasa_lar_16713_gs","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-16713-GS","sourceUrl":"https://software.nasa.gov/software/LAR-16713-GS","confidence":"high"},"type":"software","title":"BL2D- Two-Dimensional And Axisymmetric Boundary Layer Code","abstract":"BL2D: An efficient and fourth-order accurate method to compute two-dimensional and axisymmetric boundary layers on aerospace vehicle wings from low-speed to hypersonic speeds.Aerospace applications include boundary-layer stability analysis , transonic wing design, laminar flow wing design.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_16744_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-16744-1","sourceUrl":"https://software.nasa.gov/software/LAR-16744-1","confidence":"high"},"type":"software","title":"A Two-dimensional/Axisymmetric Nozzle Design Code Using the Irrotational Method of Characteristics (IMOCND)","abstract":"The innovation is a computer program which can be used to design two-dimensional or axisymmetric nozzles having uniform or non-uniform (Mach number and/or flow angle) supersonic inflow. If possible, the computer program generates a nozzle contour which produces supersonic, shock-free, uniform flow at the nozzle exit. (Certain non-uniform inflow conditions may create a shockwave which violates the potential flow assumption, stopping the program.) The program also give the user control over the geometry at inflow and in the expansion region of the nozzle.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_17325_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-17325-1","sourceUrl":"https://software.nasa.gov/software/LAR-17325-1","confidence":"high"},"type":"software","title":"[AEROM] Unsteady Aerodynamic Reduced-Order Models (ROMs) for Efficient Aeroelastic Analysis","abstract":"Unsteady aerodynamic reduced-order models (ROMs) have been developed that significantly improve the computational efficiency of traditional computational methods for aeroelastic analysis . Traditional methods rely on repetitive use of computational fluid dynamics (CFD) codes for predicting the aeroelastic response of flight vehicles. However, the use of CFD codes is time-consuming and computationally expensive. The new ROMs enable the computational aeroelastic analysis of flight vehicles at a fraction of the time and cost of traditional methods. In particular, there are three new innovations: 1). ability to simultaneously excite all the structural modes of a flight vehicle using a single CFD execution; 2). ability to compute matched-point solutions (real world answers) without costly re-execution of the CFD code; and 3). ability to simultaneously compute the static and dynamic aeroelastic solutions using the same ROM. These recent developments result in a unique capability with important applications to real-world problems.from filed patent application--Computational aeroelastic analyses typically use a mathematical model for the structural modes of a flexible structure and a nonlinear aerodynamic model that can generate a plurality of unsteady aerodynamic responses based on the structural modes for conditions defining an aerodynamic condition of the flexible structure. In the present invention, a linear state-space model is generated using a single execution of the nonlinear aerodynamic model for all of the structural modes where a family of orthogonal functions is used as the inputs. Then, static and dynamic aeroelastic solutions are generated using computational interaction between the mathematical model and the linear state-space model for a plurality of periodic points in time.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_17662_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-17662-1","sourceUrl":"https://software.nasa.gov/software/LAR-17662-1","confidence":"high"},"type":"software","title":"Macro for an Apriori Grid NUmerics Metric (MAGNUM)","abstract":"The Macro for an Apriori Grid NUmeric Metric (MAGNUM) software is a Tecplot {TM} macro that computes a grid quality metric, or number, for structured surface and volume grids that identifies how good the grid is for computational science applications. A good measure ranges from 0.7 to 1.0, where 0.7 is acceptable and 1.0 is excellent quality. The macro utilizes grid analysis tools in Tecplot's computational fluid dynamics (CFD) analyzer in conjunction with the analysis presented in AIAA paper 2004-0612.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18203_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18203-1","sourceUrl":"https://software.nasa.gov/software/LAR-18203-1","confidence":"high"},"type":"software","title":"SolFlyte","abstract":"SolFlyte enables the analysis of Solar-Electric (SE) HALE aircraft and airship concepts and missions by uniquely modeling the complex interactions of time-dependent astronomical, geographical, and atmospheric factors on key metrics such as the energy balance, shadowing, performance, on-site persistence, and design size. Separate functional utilities are linked using the PHX ModelCenter v9.0 integration framework to create the SolFlyte-HTA (airplane), SolFlyte-LTA (airship) analysis models, and the SolFlyte-WND wind data processing model. The flexible inputs and rapid execution of the SolFlyte models broadens the analysis scope and permits parametric design feedback.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18567_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18567-1","sourceUrl":"https://software.nasa.gov/software/LAR-18567-1","confidence":"high"},"type":"software","title":"(ANOPP2v1.5.0) Aircraft NOise Prediction Program (ANOPP2)","abstract":"The next generation Aircraft NOise Prediction Program (ANOPP), called ANOPP2, provides the capability and a framework to integrate acoustic approaches for aircraft noise component prediction, propulsion system installation effects, and overall sound propagation to the far-field. The predictions from ANOPP2 include the fidelity and flexibility required to predict outside the current experience base. A focal point of ANOPP2 is a combination of acoustic approaches; that is, to offer several options depending on requested fidelity and execution speed. This allows ANOPP2 to include fast prediction methods for design optimization while including the fidelity required for understanding and provide insight into controlling noise physics. In addition, ANOPP2 facilitates design by including complex differentiated versions of the library and peripheral software and, in some cases, algorithmic differentiation of prediction and derived metric capability. While ANOPP is not required to run ANOPP2, it is strongly recommended. In addition, ANOPP2 is also designed to run on large computing systems, such as clusters, and takes advantage of Message Passing Interface (MPI) in many applications.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18774_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18774-1","sourceUrl":"https://software.nasa.gov/software/LAR-18774-1","confidence":"high"},"type":"software","title":"MVL-15 (Modified Vortex Lattice)","abstract":"MVL-15 is a Modified Vortex-Lattice (MVL) aerodynamics analysis code. The term modified refers to the primary modification of the core vortex-lattice methodology: the incorporation and assignment of viscous aerodynamics data associated with the wing section geometry to the inviscid vortex-lattice solution via iterative computational procedures. The strategy essentially converts an inviscid and purely analytic linearized method to a semi-empirical blend which retains the rapid execution speed of the linearized method while empirically characterizing the viscous aerodynamics at all spanwise lattice points. For the analysis of airplane configurations consisting of more than one wing, the resulting spanwise section aerodynamics can be integrated to determine the aerodynamics of each wing, both separately and combined. As implemented, the methodology inherently provides the capability to determine the non-linear viscous effects on lift and drag at relatively high angles of attack, to identify the maximum lift coefficient, and to characterize the onset of stall. Furthermore, the methodology provides the capability to determine the lift and drag associated with the application of aircraft design strategies for lift augmentation such as the use of flaps or blowing. The MVL-15 code is applicable to the analysis of aircraft in cruise configurations; however, it is most advantageously applied to the analysis of aircraft in various high-lift configurations.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18801_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18801-1","sourceUrl":"https://software.nasa.gov/software/LAR-18801-1","confidence":"high"},"type":"software","title":"Multiphysics Algorithm with Particles (MAP)","abstract":"The Multiphysics Algorithm with Particles (MAP) is a multidimensional adaptive Cartesian implementation of the direct simulation Monte Carlo (DSMC) method with paralellization capabilities using MPI. The DSMC method is widely used for the modeling of gas flows through the computation of the motion and collisions of representative molecules. Computation at the molecular level is necessary for studies in rarefied gas dynamics (RGD) because the transport terms in the Navier-Stokes equations are not valid in this flow regime. The essential characteristic of a \"rarefied\" flow is that the molecular mean free path is not negligible.The software has been designed to be as automated as possible to achieve a quality solution with minimal user input and control by performing dynamic adaptations of the grid, local time step, and surface temperature. The gas model includes internal degrees of freedom (rotational, vibrational, and electronic), gas phase chemical reactions, and surface reactions. MAP uses an N-Level embedded Cartesian grid system and a separate surface geometry that is embedded within the grid that is made up of unstructured triangular elements.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18901_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18901-1","sourceUrl":"https://software.nasa.gov/software/LAR-18901-1","confidence":"high"},"type":"software","title":"Higher-fidelity Conceptual Design and Structural Optimization (HCDstruct) Version 2.0","abstract":"HCDstruct V2.0 represents the second major development of the HCDstruct software tool. In V2.0, HCDstruct now includes an aerostructural modeling and optimization capability for generalized tube and wing aircraft configurations. This tool permits the rapid, parameterized creation of aeroservoelastic finite-element models for general tube and wing aircraft configurations and constructs all files required to perform the subsequent aerostructural optimization using the NASTRAN software. The methods employed offer a novel physics-based sizing capability for unconventional aircraft configurations for conceptual design environments.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18924_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18924-1","sourceUrl":"https://software.nasa.gov/software/LAR-18924-1","confidence":"high"},"type":"software","title":"Inverse Heat Conduction Solver Using MATLAB - IHC Solve","abstract":"This MATLAB software first reads in temperature data measured from two thermocouples embedded in a heat conducting specimen. The software also reads in the thermophysical properties for the heat conducting specimen. After filtering noise from the measured temperature data , the software then uses the filtered data and thermophysical properties to solve both a direct and inverse heat conduction problem to estimate both temperature and heat flux on the external surface of the specimen.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18934_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18934-1","sourceUrl":"https://software.nasa.gov/software/LAR-18934-1","confidence":"high"},"type":"software","title":"Flight Optimization System (FLOPS) Software v.9","abstract":"The Flight Optimization System (FLOPS) is a multidisciplinary system of computer programs for conceptual and preliminary design and evaluation of advanced aircraft concepts. It consists of six primary modules: 1) weights, 2) aerodynamics, 3) propulsion data scaling and interpolation, 4) mission performance, 5) takeoff and landing, and 6) program control.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_19464_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19464-1","sourceUrl":"https://software.nasa.gov/software/LAR-19464-1","confidence":"high"},"type":"software","title":"LAngley Stability and TRansition Analysis Code (LASTRAC) Version 3.0","abstract":"LASTRAC3.0 is the first US release of the LASTRAC series of software for chemically reacting flows. The code is designed to be backward compatible to the original LASTRAC release since 2004. Users of the original release are strongly encouraged to upgrade to LASTRAC3.0 as the new software has improved functionality and new Python utility scripts available for either perfect or reacting gas applications. In short, LASTRAC3.0 can handle boundary layers or shear layers with perfect, equilibrium, chemical nonequilibrium, or thermal nonequilibrium (two-temperature) chemistry effects. Users can choose between the default publicly available widely-used five-species air and any user-defined chemistry compositions/models in a table or dynamically-linked-library format. Solution methods allowed for the user-provided perfect or reacting mean flows include Linear Stability Theory (LST), linear/nonlinear Parabolized Stability Equations (PSE) for 2D/axisymmetric/infinite swept wing or full 3D boundary layers. Nonlinear PSE functionalities in this release is restricted to perfect gases only. Future release will include that for reacting flows.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_19479_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19479-1","sourceUrl":"https://software.nasa.gov/software/LAR-19479-1","confidence":"high"},"type":"software","title":"High-fidelity Unmanned Multirotor Flight Dynamics Simulation for Off-nominal Conditions","abstract":"This innovation is a six degree-of-freedom modeling and simulation architecture and database for predicting the flight dynamics behavior of small/medium sized multirotor vehicles in off-nominal and/or extreme out-of-envelope conditions. The development of this technology was motivated by ongoing efforts to integrate small unmanned aircraft system (sUAS) vehicles into the National Airspace System (NAS). These efforts include development of risk and safety analysis methods that will enable autonomous, beyond-visual-range operations and could include real-time flight monitoring systems, trajectory prediction during off-nominal or failure scenarios, and probabilistic safety analyses. The modeling and simulation architecture comprises aerodynamic and propulsion models that are valid for all-attitude flight conditions such as extreme relative wind angles (e.g. high angle of attack and sideslip angles), very high vehicle angular rates typical of loss-of-control events, vortex ring state conditions, and onboard system or component failures. The aerodynamic and propulsion models are derived using specialized wind tunnel test methods that replicate extreme off-nominal flight conditions.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_19515_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19515-1","sourceUrl":"https://software.nasa.gov/software/LAR-19515-1","confidence":"high"},"type":"software","title":"Multi-Level Monte Carlo with Python (MLMCPy)","abstract":"The Multi-Level Monte Carlo with Python (MLMCPy) software package is code written in Python to solve uncertainty propagation problems. Multi-level Monte Carlo (MLMC) is an efficient alternative to standard Monte Carlo simulation for estimating expectations of outputs to computational models with uncertain input parameters. MLMC greatly reduces computational cost by performing most simulations with low accuracy at a correspondingly low cost, with relatively few simulations being performed at high accuracy and high cost. MLMCPy is a parallel, efficient, and modular implementation of the MLMC method that provides a straightforward means of applying the method to general uncertainty propagation problems.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/MLMCPy/","license":null}},{"forgeId":"forge_nasa_lar_19572_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19572-1","sourceUrl":"https://software.nasa.gov/software/LAR-19572-1","confidence":"high"},"type":"software","title":"Higher-Order Design Environment (HOrDE): A geometry-centric, multi-disciplinary, multi-fidelity process for conceptual aircraft analysis and design","abstract":"The purpose of this software is to facilitate the creation of analysis and design processes for the conceptual-level aircraft configurations. At its core, the software contains a set of Java classes for defining the geometry, handling the analysis data associated with the geometry, executing external analysis methods, and pre- and post-processing analysis results. Users of this software will have the ability to use the library of geometry and data classes, through its API, to create wrappers for performing analysis , or for interfacing with external analysis methods. A pre-defined set of wrappers has been created for several software codes used by NASA. These wrappers have also been integrated into several process models for performing analysis and design of conceptual-level aircraft concepts in preparation for additional analysis using higher-order methods. Users of the software will be able to use the API to create wrappers for their own analysis methods, and to use both built-in and custom wrappers to create their own process models for the conceptual-level analysis and design processes used by their organization.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_19607_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19607-1","sourceUrl":"https://software.nasa.gov/software/LAR-19607-1","confidence":"high"},"type":"software","title":"Mode shape interpolation via radial basis functions (RBF)","abstract":"Preprocessing software to prepare a finite element structural model for use with the modal structural solver within the FUN3D CFD code . Mode shapes are interpolated from a NASTRAN FEM to the FUN3D CFD surface mesh.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/rbf","license":null}},{"forgeId":"forge_nasa_lar_19734_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19734-1","sourceUrl":"https://software.nasa.gov/software/LAR-19734-1","confidence":"high"},"type":"software","title":"LAURA 5.6: Langley Aerothermodynamic Upwind Relaxation Algorithm","abstract":"The Langley Aerothermodynamic Upwind Relaxation Algorithm (LAURA) has been updated to version 5.6. This is a computational fluid dynamics simulation software code. The new technologies regard techniques for modifying the computational grid, for modeling rough walls, and for interpreting simulations that incorporate a shock layer radiation model.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_19739_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19739-1","sourceUrl":"https://software.nasa.gov/software/LAR-19739-1","confidence":"high"},"type":"software","title":"PRECiSA with Instrumented Code Generation","abstract":"PRECiSA (Program Round-off Certifier via Static Analysis ) is a fully automatic static analyzer for floating-point valued functions. It computes an over-approximation of the round-off error of a given floating-point expression, along with a formal certificate that ensures the correctness of the estimated error.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/precisa","license":null}},{"forgeId":"forge_nasa_lar_19767_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19767-1","sourceUrl":"https://software.nasa.gov/software/LAR-19767-1","confidence":"high"},"type":"software","title":"Coordinate systems class library","abstract":"Library of classes representing various coordinate systems and providing the transformations between them. Coordinate systems represented are: East-North-Up (ENU), Downrange-Crossrange-Above (DCA), Latitude-Longitude-Altitude (LLA), Earth -Centered-Fixed (ECF), and Azimuth-Elevation-Range (AER).","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/Coordinate-systems-class-library","license":null}},{"forgeId":"forge_nasa_lar_19841_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19841-1","sourceUrl":"https://software.nasa.gov/software/LAR-19841-1","confidence":"high"},"type":"software","title":"Mixed-element USM3D flow solver for NASA TetrUSS","abstract":"The NASA Tetrahedral Unstructured Software System (TetrUSS) has served as a reliable computational aerodynamic analysis tool for Government and Industry for over 2 decades. TetrUSS has twice won the NASA Software of the Year Award in 1996 and 2004. The legacy Navier-Stokes flow solver within TetrUSS, USM3D, is based on fully tetrahedral cell-centered discretization. The present work extends the solver capability to handle mixed element grids composed of hexahedral, prismatic, pyramidal, and tetrahedral cells. Furthermore, additional algorithmic capabilities have been implemented that significantly improve its robustness and time to solution. These changes were so extensive that an entirely new code has been written.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_19861_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19861-1","sourceUrl":"https://software.nasa.gov/software/LAR-19861-1","confidence":"high"},"type":"software","title":"\u201c(ANOPP2v1.5.0) Aircraft NOise Prediction Program (ANOPP and ANOPP2)\u201d","abstract":"The NASA Aircraft Noise Prediction Program (ANOPP) provides a capability to predict noise from aircraft in flight including sources, propagation, and metrics. Since inception over 40 years ago, it has been maintained and updated including the ongoing development of new methods that are essential to more accurate physics-based prediction of modern and future aircraft noise. ANOPP2 provides a modern prediction environment with a flexible framework particularly necessary for unconventional aircraft noise studies. ANOPP2 is also designed to provide improved understanding of the fundamental physics to support experiments and flight research with the continuing development of new tools. Particularly for fixed wing aircraft prediction, ANOPP continues to provide essential prediction capabilities, therefore, both ANOPP and ANOPP2 together are required for most applications.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_19926_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19926-1","sourceUrl":"https://software.nasa.gov/software/LAR-19926-1","confidence":"high"},"type":"software","title":"PCBoom 7.5.0 Fast PCBoom sonic boom propagation code","abstract":"PCBoom 7.5.0 is a sonic boom propagation suite of programs that applies a full three-dimensional ray tracing based on geometrical acoustics in real atmospheres. It has a very efficient Burgers solver used to predict sonic boom ground waveforms and footprints from supersonic flight vehicles performing arbitrary maneuvers. It also computes loudness metrics and ground signature locations, with algorithms on turbulence effects.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_20078_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-20078-1","sourceUrl":"https://software.nasa.gov/software/LAR-20078-1","confidence":"high"},"type":"software","title":"SUITCASE Structural Analysis and Optimization System","abstract":"SUITCASE is a Fortran computer code that performs static structural analysis , static aeroelastic loads analysis , aircraft trim, dynamic structural analysis , flutter analysis and structural optimization. For structural analysis , SUITCASE calls the external program EPSM (Equivalent Plate Structural Modeling) and for flutter analysis , SUITCASE calls the external program DLFLUT. All other analysis tools are contained within the SUITCASE system. For optimization, SUITCASE uses the KSOPT optimizer and the LPSOLVE optimizer.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_20095_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-20095-1","sourceUrl":"https://software.nasa.gov/software/LAR-20095-1","confidence":"high"},"type":"software","title":"OVERFLOW 2.4D Overset Grid Computational Fluid Dynamics Flow Solver with Moving Body Capability (OVERFLOW)","abstract":"OVERFLOW 2.4D is a computer code for simulating viscous, compressible fluid flow about complex aerodynamic configurations. Thetechnology solves the Reynolds-averaged Navier-Stokes equations using structured, overset computational grids. It includes the capability for simulating multiple moving bodiesacting under prescribed or aerodynamically forced motion. OVERFLOW 2 is a merge of the previously developed OVERFLOW 1.8 and OVERFLOW-D codes.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_20188_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-20188-1","sourceUrl":"https://software.nasa.gov/software/LAR-20188-1","confidence":"high"},"type":"software","title":"FUN3D v14.2","abstract":"FUN3D version 14.2 is a suite of computational fluid dynamics simulation and design tools that uses mixed-element unstructured grids and optional overset topologies to solve the Navier-Stokes equations for static and dynamic applications. Various turbulence treatments are available. A discretely-consistent adjoint solver enables efficient gradient-based design optimization. Mesh adaptation capabilities are also available. Gas models include compressible and incompressible perfect-gas approaches, as well as general finite-rate chemistry for flows in thermochemical nonequilibrium. GPU acceleration is also available for many of the capabilities.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_20284_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-20284-1","sourceUrl":"https://software.nasa.gov/software/LAR-20284-1","confidence":"high"},"type":"software","title":"Integrated Ground Risk Assessment Service Provider for Unmanned Aircraft Systems","abstract":"The Integrated Operational Risk Assessment Service Provider tool is aimed to assess the aircrafts integrated air and ground risk; namely, the mid-air collision risk and the ground casualty risks. Currently, the tool has access to high-resolution population density data, commercially available weather forecasting service, and sets of physical models to compute and visualize ground risks, assisting operators with pre- flight planning. As part of the ongoing work, the tool will leverage published notices to airmen (NOTAMs), Drone NOTAMs (DROTAMs), and an existing GPS availability prediction tool. With these data sources, and the intentional extensibility to add others, the capability will allow operators to develop flight plans that minimize ground casualty risk before an aircraft ever takes flight .","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_20382_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-20382-1","sourceUrl":"https://software.nasa.gov/software/LAR-20382-1","confidence":"high"},"type":"software","title":"OVERFLOW 2.5.1 Overset Grid Computational Fluid Dynamics Flow Solver with Moving Body Capability and GPU Support (OVERFLOW)","abstract":"OVERFLOW 2.5. is a computer code for simulating viscous, compressible fluid flow about complex aerodynamic configurations. The technology solves the Reynolds-averaged Navier- Stokes equations using structured, overset computational grids. It includes the capability for simulating multiple moving bodies acting under prescribed or aerodynamically forced motion. OVERFLOW 2 is a merge of the previously developed OVERFLOW 1.8 and OVERFLOW-D codes.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_20542_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-20542-1","sourceUrl":"https://software.nasa.gov/software/LAR-20542-1","confidence":"high"},"type":"software","title":"HyperSolve Version 1.0.1","abstract":"HyperSolve is an unstructured grid CFD solver, specializing in the simulation of hypersonic flows.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_20570_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-20570-1","sourceUrl":"https://software.nasa.gov/software/LAR-20570-1","confidence":"high"},"type":"software","title":"LAURA v5.7","abstract":"LAURA simulates hypersonic chemically reacting fluid dynamics. In this version, a new grid adaptation allows for multiple grid blocks to be stacked perpendicular to a vehicle. Previously with the LAURA software, only a single grid block could be adapted in the direction perpendicular to a simulated vehicle.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_20572_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-20572-1","sourceUrl":"https://software.nasa.gov/software/LAR-20572-1","confidence":"high"},"type":"software","title":"Generative modeling of wind velocity measurements.","abstract":"The software developed implements generative modeling algorithms for estimating wind velocities in local areas (i.e., microweather). The software implements three established algorithms: 1) Gaussian mixture models, 2) denoising diffusion probabilistic models, and 3) flow matching. The main purpose of the software is to allow for generating realistic samples of (microweather) wind velocity versus altitude for a given macroweather forecast (e.g., winds NNW @ 15MPH). The training data used - sonic detection and ranging (SoDAR) measurements of local wind velocities along with historical weather forecast data over the same time period - will be released along with the software.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/wind-generative-modeling","license":null}},{"forgeId":"forge_nasa_lar_20712_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-20712-1","sourceUrl":"https://software.nasa.gov/software/LAR-20712-1","confidence":"high"},"type":"software","title":"Vulcan-CFD","abstract":"VULCAN-CFD offers a comprehensive set of capabilities to enable the simulation of continuum flowfields from subsonic to hypersonic conditions. The governing equations that are employed include allowances for both chemical and thermal non-equilibrium processes, coupled with a wide variety of turbulence models for both Reynolds-averaged and large eddy simulations.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_17514_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-17514-1","sourceUrl":"https://software.nasa.gov/software/LEW-17514-1","confidence":"high"},"type":"software","title":"TURBO-AE: An Aeroelastic And Multi-stage Aerodynamic Analysis Code Based On Unsteady Three-dimensional Navier-Stokes Equations","abstract":"An aeroelastic and unsteady aerodynamic analysis code has been developed for prediction of flutter, forced response, performance and rotor-stator interaction effects. The analysis provides a high-fidelity modeling of subsonic, transonic and supersonic flow regimes with attached and separated flow fields. The code calculates performance quantities such as efficiency, mass flow, pressure ratio, temperature ratio, distribution of flowfield properties in the entire domain of calculation, aerodynamic damping to assess flutter stabiltiy and unsteady aerodynamic forces arising from rotor-stator interaction for calculation of forced response. This information can be used in high cycle fatigue analysis of blade rows.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_18993_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-18993-1","sourceUrl":"https://software.nasa.gov/software/LEW-18993-1","confidence":"high"},"type":"software","title":"\"NASA Glenn Research Center: The Early Years\" for iPad","abstract":"Photographic gallery type application containing imagery and descriptions from the GRC image archive. Photos and data cover the period from 1941-1979. The software has been compiled and bundled as an iOS app for the iPad and intended for release through the Apple App Store.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://apps.apple.com/si/app/nasa-glenn-research-center-the-early-years/id562903295","license":null}},{"forgeId":"forge_nasa_lew_19177_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19177-1","sourceUrl":"https://software.nasa.gov/software/LEW-19177-1","confidence":"high"},"type":"software","title":"Tool for Turbine Engine Closed-loop Transient Analysis (TTECTrA)","abstract":"Tool for Turbine Engine Closed-loop Transient Analysis (TTECTrA)The Tool for Turbine Engine Closed-loop Transient Analysis (TTECTrA) is a tool, developed in the Mathworks(R) Matlab/Simulink enviornment, intended to extend systems analysis by providing an estimate of the transient performance/capability of a conceptual engine design. The TTECTrA tool is capable of designing a basic turbofan engine controller, with transient protection, based on the user's engine model and constraints. TTECTrA is built in the Mathworks Matlab/Simulink environment and relies on the Matlab Control Systems Toolbox to provide additional functionality and streamline the control design process.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/TTECTrA/releases","license":null}},{"forgeId":"forge_nasa_lew_19703_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19703-1","sourceUrl":"https://software.nasa.gov/software/LEW-19703-1","confidence":"high"},"type":"software","title":"Ozone: ODE and Optimal Control Solver","abstract":"Ozone is a Python software package that facilitates the solution of ordinary differential equations (ODEs) and optimal control problems. It is unique among similar libraries because of its capability to compute derivatives of the ODEs integrated outputs with respect to parameters, initial conditions, and the time interval. This is implemented in a manner that allows Ozone-based ODE models to be integrated in larger, potentially multidisciplinary models while using adjoint-type methods to compute derivatives for the larger model. In terms of the ODE integration, Ozone adopts the general linear methods (GLM) equations, allowing it to easily support a large library of Runge-Kutta and linear multistep methods. Ozone also supports multiple integration formulations, consisting of time-marching, solver-based, and optimizer-based approaches to solving the ODE. Ozone is built on top of NASAs OpenMDAO software framework.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://openmdao.org","license":null}},{"forgeId":"forge_nasa_lew_19709_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19709-1","sourceUrl":"https://software.nasa.gov/software/LEW-19709-1","confidence":"high"},"type":"software","title":"GFR: Glenn Flux Reconstruction","abstract":"GFR is a high-order computational fluid dynamics (CFD) Fortran code for large-eddy simulations. It is based on the simple and efficient flux reconstruction method and accurate to an arbitrary order through an user-supplied input parameter. It is currently capable of using unstructured grids containing quadrilateral or hexahedra elements.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/gfr","license":null}},{"forgeId":"forge_nasa_lew_19717_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19717-1","sourceUrl":"https://software.nasa.gov/software/LEW-19717-1","confidence":"high"},"type":"software","title":"Advanced Geared Turbofan 30,000 (AGTF30)","abstract":"The Advanced Geared Turbofan 30,000 (AGTF30) is a geared turbofan simulation that utilizes the Toolbox for the Modeling and Analysis of Thermodynamic Systems (T-MATS) to create a steady-state and dynamic engine model within MATLAB/Simulink. The engine model is based upon an N+3 geared turbofan concept with a controller that allows dynamic operation throughout the flight envelope.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/AGTF30","license":null}},{"forgeId":"forge_nasa_lew_19994_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19994-1","sourceUrl":"https://software.nasa.gov/software/LEW-19994-1","confidence":"high"},"type":"software","title":"OpenMDAO V2","abstract":"OpenMDAO is an open-source high-performance computing platform for systems analysis and multidisciplinary optimization, written in Python. It enables you to decompose your models, making them easier to build and maintain, while still solving them in a tightly coupled manner with efficient parallel numerical methods.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://openmdao.org","license":null}},{"forgeId":"forge_nasa_lew_20027_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20027-1","sourceUrl":"https://software.nasa.gov/software/LEW-20027-1","confidence":"high"},"type":"software","title":"COMDES-MELT: A Turbofan Engine Icing Risk Analysis Tool","abstract":"The engine icing risk prediction code, COMDES-MELT, is a mean-line compressor analysis code coupled with an ice crystal thermodynamic state code. The COMDES-MELT code computes the velocity, pressure, temperature, and flow angles at the leading edge and trailing edge of each blade row, at the hub, mean, and tip sections. This compressor code includes the ability to calculate the effects of water vapor on the fluid properties of the air water vapor mixture based on the mole fraction of air to water vapor. The relative humidity at the engine inlet is specified, and the local specific humidity (mass of water/mass of air) is computed through each component of the inlet-fan-LPC, taking the sublimation, melting, and evaporation of an ice particle into consideration, as well as the local air temperature. The resulting effect of the humid air on the performance of the compressor is computed. Several key parameters have been identified as early indicators of ice accretion: the local wet-bulb temperature, the melt ratio within each blade row, and the ice water flow rate to air flow rate ratio. The local wet-bulb temperature is calculated at each blade row. The geometry section of the code is defined by simple circular arc rotors and stators including stage axial gaps. As the ice particles passes though the compression rotors, stators, and gaps the ice particle melting and evaporation model computes the local melt ratio, change in enthalpy, and particle temperature and diameter through each compressor component. The ratio of ice water flow rate to the air flow rate is computed at the inlet based on the ice water content in the atmosphere and the mass flow rate of air entering the engine. If the limiting values of these key parameters are met, there is a risk that ice will accrete on the surfaces of the compressor. With these parameters as the precursors to ice accretion, the blade row within the compression system can be identified that is likely to experience ice buildup at a particular engine operating condition in the vehicle flight trajectory.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_20150_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20150-1","sourceUrl":"https://software.nasa.gov/software/LEW-20150-1","confidence":"high"},"type":"software","title":"Zappy - A Load Flow Modeling Tool For Power System Design With Gradient Based Optimization","abstract":"Zappy is a software library build on top of the OpenMDAO framework written in the Python Programming language. It provides a modular software code enabling a user to perform standard power system studies, while also providing analytic derivative (sensitivity) calculations to the end user. These analytic derivatives make Zappy efficient when used by (or incorporated within) external software programs performing broader multidisciplinary optimization of electrical power systems.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/OpenMDAO/zappy","license":null}},{"forgeId":"forge_nasa_lew_20155_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20155-1","sourceUrl":"https://software.nasa.gov/software/LEW-20155-1","confidence":"high"},"type":"software","title":"Glenn Icing Computational Environment (GlennICE)","abstract":"GlennICE is a Computational Fluid Dynamics (CFD) post processor that simulates an encounter with icing related inclement weather. It utilizes a CFD solution provided by the user from third party CFD software and simulates the impingement of supercooled water and the resulting ice accretion on an aerodynamic vehicle. It supports simulation in both stationary and rotating frames of reference.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_20175_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20175-1","sourceUrl":"https://software.nasa.gov/software/LEW-20175-1","confidence":"high"},"type":"software","title":"PyTurbo - A Python Framework for Aero-thermal Gas Turbine Component Design","abstract":"PyTurbo is NASA Turbomachinery design tool capable of going from a 2D Airfoil Design to a 3D design of a blade and a blade row. This design tool can wrap heatpipe paths inside the airfoil. PyTurbo is a turbomachinery design tool focused on the development of 3D blade rows consisting of 3D Airfoils. There is a need inside NASA to develop our own airfoils, this enables fundamental research into transition, tip leakage passive flow control, cavity flows, and nature inspired shapes. PyTurbo serves as a NASA open-sourced fundamental research design code that anyone at NASA can use. PyTurbo is built with the intent that it can be easily incorporated into the python package index (https://pypi.org/).","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_20176_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20176-1","sourceUrl":"https://software.nasa.gov/software/LEW-20176-1","confidence":"high"},"type":"software","title":"GlennOPT","abstract":"GlennOPT is a multi-objective optimization tool for CFD (Computational Fluid Dynamics) Applications. It is specifically designed to handle optimization problems involving multiple objectives.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/GlennOPT","license":null}},{"forgeId":"forge_nasa_lew_20246_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20246-1","sourceUrl":"https://software.nasa.gov/software/LEW-20246-1","confidence":"high"},"type":"software","title":"Mphys: Library for Coupling High Fidelity Codes in OpenMDAO","abstract":"A modular multi-physics coupling library, built on OpenMDAO, for use with design optimization. This software can compute coupled analytic derivatives for multi-physics models built from a series of PDE solvers, for applications such as aeropropulsive, aerothermal, or aerostructural design .","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/openmdao/mphys","license":null}},{"forgeId":"forge_nasa_lew_20281_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20281-1","sourceUrl":"https://software.nasa.gov/software/LEW-20281-1","confidence":"high"},"type":"software","title":"AcousticAnalogies.jl: A Propeller/Rotor Acoustics Code Especially Suitable for Gradient-Based Optimization","abstract":"AcousticAnalogies.jl is an implementation of Farassat's \"formulation 1A\" (F1A), a mathematical technique used to predict the acoustics radiated by a fluid flow. The F1A method, like all acoustic analogies, is a solution to an inhomogeneous wave equation. The wave equation is derived by manipulating the Navier-Stokes equation into a \"propagation\" left-hand side and a \"source\" right-hand side. The wave equation is solved using the free-space Green's function, giving an expression with two surface integrals and one volume integral (typically ignored). The integrands of these integrals represent the acoustic sources in the flow, and computing them requires knowledge of the motion of and forces acting on the integration surfaces. These inputs may come from experiment, but more often are taken from the outputs of an aerodynamics code (e.g., one using blade element momentum theory, vortex lattice methods, or computational fluid dynamics).","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/OpenMDAO/AcousticAnalogies.jl","license":null}},{"forgeId":"forge_nasa_lew_20282_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20282-1","sourceUrl":"https://software.nasa.gov/software/LEW-20282-1","confidence":"high"},"type":"software","title":"Plot3D PreProcessing and PostProcessing Libraries in Julia and Python","abstract":"Plot3D is a widely used format for storing grid data for numerical computation particularly in CFD. This free open source python library enables researchers to have programmatic access to read, write, combine, plot3D files to build a 3D domain. One of the main challenges with simulations using Plot3D is finding the connection of blocks of I,J,K indexing representing X,Y,Z coordinates in space. This tool contains functionality to automatically finds matching faces of each block and exports the results as a human readable dictionary or JSON format.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/Plot3D_utilities","license":null}},{"forgeId":"forge_nasa_lew_20283_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20283-1","sourceUrl":"https://software.nasa.gov/software/LEW-20283-1","confidence":"high"},"type":"software","title":"Airfoil Machine Learning Code and Dataset","abstract":"This is the supplemental code and dataset for a paper titled: Predicting 2D Airfoil Performance Using Graph Neural Networks","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/airfoil-learning","license":null}},{"forgeId":"forge_nasa_lew_20319_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20319-1","sourceUrl":"https://software.nasa.gov/software/LEW-20319-1","confidence":"high"},"type":"software","title":"Hypersonic Aerothermodynamics Particle (HAP) code","abstract":"The Hypersonic Aerothermodynamics Particle (HAP) code is a software tool for numerical simulation of high-speed gas flows, using shared memory parallelization and dynamically adaptive Cartesian grids. HAP is a framework built around the direct simulation Monte Carlo (DSMC) method, which is a stochastic technique for simulation of gas flows involving strong nonequilibrium among translational and/or internal (rotational, vibrational and electronic) energy modes. Unique features of HAP include capabilities for hybrid or multiscale simulation of mixed rarefied/continuum flows, as well as integrated capabilities for design optimization, uncertainty quantification and global sensitivity analysis.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_20371_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20371-1","sourceUrl":"https://software.nasa.gov/software/LEW-20371-1","confidence":"high"},"type":"software","title":"HeaTSSPy (Heat Transport System Simulation for Python)","abstract":"HeaTSSPy is a thermal management system (TMS) concept design package. Written within Python utilizing the OpenMDAO framework, HeaTSSPy seeks to give engineers a useful tool to estimate size, weight, and drag of a liquid and air based TMS. The package is modular and gives access to all the building blocks required of a liquid or specific types of air cooling systems. These components include heat exchangers, heat sinks, tubes, inlets, nozzles, heat loads, and pumps. It also contains a method of populating flow characteristics and utilizes several methods of characterization including using table, and the open source package CoolProp. Because the module is built within OpenMDAO, design optimization can be utilized to determine the dimensions of heat exchangers, tubing diameters, pump sizes, and system architectures.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/HeaTTSPy","license":null}},{"forgeId":"forge_nasa_lew_20403_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20403-1","sourceUrl":"https://software.nasa.gov/software/LEW-20403-1","confidence":"high"},"type":"software","title":"Optimal Trajectories by Implicit Simulation (OTIS) Version 5.0: A General Purpose 3-DOF Aerospace Vehicle Trajectory Simulation and Optimization Computer Program","abstract":"Optimal Trajectories by Implicit Simulation , Version 5.0 (OTIS5) is a reworking of the OTIS trajectory optimization software development. OTIS5 is a general purpose 3-Degree Of Freedom (DOF) trajectory simulation and optimization software package that is focused on the optimization of aerospace vehicle trajectories and associated vehicle design parameters. OTIS5 retains most of the functionality of the previous version but does not contain computer code subject to International Traffic in Arms Regulations (ITAR) restrictions. The authors still intend the software to be limited to domestic USA-only use. In addition, the new software will be distributed without the need for recompilation making for an easier distribution process while also retaining code integrity through this (form of distribution) software control measure.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_20407_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20407-1","sourceUrl":"https://software.nasa.gov/software/LEW-20407-1","confidence":"high"},"type":"software","title":"Real-Time Background Oriented Schlieren Software Package Update, 2022","abstract":"Background Oriented Schlieren (BOS) is an optical technique for measuring density gradients in flow fields, in quiescent air or even liquids. In traditional BOS, images of a speckled target are recorded using an electronic camera first at quiescent conditions (reference image) and then with the flow or density gradient causing phenomena initiated ('wind on' image). Small changes in the image of the speckled target caused by optical aberrations along the line-of-sight can be measured by cross-correlating the reference image with the 'wind on' image, yielding a map of the density gradients along the imaged path. The size of the speckles and their uniformity of illumination are critical to the success and sensitivity of the technique. BOS image data are recorded in real time using electronic CCD type cameras. However, processing and/or analysis of the traditional BOS image data is performed off-line after the test/experiment is completed.Advances in computer processing hardware enables the implementation of real-time processing and display of the BOS image data. Two different approaches to implementing the real-time BOS (RT-BOS) processing capability have been implemented. First, a traditional multicore Central Processing Unit (CPU) based approach using scheduled parallel threads is used to build a RT-BOS processing engine. In the second approach, a Graphical Processing Unit (GPU) approach is used to construct a RT-BOS processing engine. Generally, high-core count CPU processors can provide a useful processing rate for RT-BOS. However, the GPU based approach exceeds the processing capability of the CPU approach, at a fraction of the cost. The GPU approach places no restrictions on the host PC processing capability, except that it be capable of acquiring the BOS image data from the camera in real-time.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_20426_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20426-1","sourceUrl":"https://software.nasa.gov/software/LEW-20426-1","confidence":"high"},"type":"software","title":"Machine Learning Pressure Probe Calibration Tool","abstract":"An open source Machine Learning example code designed to educate the public on how to use Machine Learning to retrieve flow direction from a probe. The framework relies on training a machine learning model on normalized calibration data . A test case is presented with examples to show the user how input pressures can be translated to flow angles.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/multihole-probe-calibration","license":null}},{"forgeId":"forge_nasa_lew_20438_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20438-1","sourceUrl":"https://software.nasa.gov/software/LEW-20438-1","confidence":"high"},"type":"software","title":"Pyturbo - A Python Framework for Aerodynamic Turbine and Compressor Component Design (Public code release)","abstract":"PyTurbo is NASA Turbomachinery design tool capable of going from a 2D Airfoil Design to a 3D design of a blade and a blade row. The intent is to allow users to design 3D turbomachinery passages and export these designs to mesh generators and CFD solvers.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/pyturbo-aero","license":null}},{"forgeId":"forge_nasa_lew_20538_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20538-1","sourceUrl":"https://software.nasa.gov/software/LEW-20538-1","confidence":"high"},"type":"software","title":"Aviary","abstract":"Aviary is an aircraft design, analysis , and optimization code based in OpenMDAO. It includes the propulsion, aerodynamics, weights, and mission computational routines of both the GASP and FLOPS codes, and allows for flexible switching between these routines. It also can incorporate external subsystems in OpenMDAO format, and can perform aircraft and mission optimizations of both conventional and hybrid electric aircraft.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/OpenMDAO/Aviary","license":null}},{"forgeId":"forge_nasa_lew_20578_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20578-1","sourceUrl":"https://software.nasa.gov/software/LEW-20578-1","confidence":"high"},"type":"software","title":"Turbo Design","abstract":"Turbo Design (TD) is a radial equilibrium turbomachinery design tool for computing the blade angles for a given design condition that matches the massflow. This tool can also be used to calculate the performance if blade angles are already known. Turbo Design has been written from scratch solving the governing equations. It is meant to be an education and research tool for incorporating machine learning loss models in turbomachinery design .","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/turbo-design/","license":null}},{"forgeId":"forge_nasa_lew_20688_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20688-1","sourceUrl":"https://software.nasa.gov/software/LEW-20688-1","confidence":"high"},"type":"software","title":"MATLAB Executable Steady-State Solver and Linearization Tool for the AGTF30 Engine Simulation (MEXLIN-AGTF30)","abstract":"MEXLIN-AGTF30 is a MATLAB executable (MEX)-based approach for rapidly simulating and linearizing gas turbine engine models. This is an enhancement to the standard steady-state solver and linearization capability included in the NASA Toolbox for the Modeling and Analysis of Thermodynamic Systems (T-MATS). This software includes an iterative solver and a modified version of the NASA-developed Advanced Geared Turbofan 30,000lbf (AGTF30) engine model coded as a MEX function.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/-AGTF30-mex-solver-","license":null}},{"forgeId":"forge_nasa_msc_26175_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-26175-1","sourceUrl":"https://software.nasa.gov/software/MSC-26175-1","confidence":"high"},"type":"software","title":"Generic Command and Telemetry Applications for the Core Flight Software Framework (CI-TO)","abstract":"This set of applications provides general purpose, configurable, and extensible spacecraft commanding and telemetry functionality supporting a wide variety of communications protocols and transports, and was designed, built, and intended for reuse.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_26648_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-26648-1","sourceUrl":"https://software.nasa.gov/software/MSC-26648-1","confidence":"high"},"type":"software","title":"Mesh_Tools v1.2.0 - Automated Unstructured Grid Shock Fitting Scripts Mesh Extrusion for CFD","abstract":"A collection of tools and scripts that will create shock-fitted unstructured grids in a mostly automatic manner, similar to those created for structured grids. The scripts has been tested with several unstructured grid solvers, LociCHEM, FUN3D, and US3D, and can be made to work with most other unstructured CFD solvers. The script help to improve numerical stability and convergence when solving hypersonic cases with unstructured CFD solvers.This package also contains an advanced mesh extrusion tool which creates high quality prismatic layers using face offsetting method to preserve surface curvature and a mean curvature smoothing algorithm to prevent the cells from self-intersecting in concave regions.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_26652_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-26652-1","sourceUrl":"https://software.nasa.gov/software/MSC-26652-1","confidence":"high"},"type":"software","title":"NASA Internships App","abstract":"The app was created using free app development software from glideapps.com. The information in the app was collected from public domains using google, nasa.gov public sites, wikipedia, and YouTube. It is a repository of information so that students can learn about NASA, it's mission , where the Centers are located, how they can connect NASA internships on social media platforms, and answer frequently asked questions about NASA internships.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://kfn0t.glideapp.io","license":null}},{"forgeId":"forge_nasa_msc_27122_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-27122-1","sourceUrl":"https://software.nasa.gov/software/MSC-27122-1","confidence":"high"},"type":"software","title":"Orion Optical Navigation Image Processing Software Version 1.5","abstract":"The Orion emergency return system utilizing optical navigation has matured in design over the last several years, and this second revision is currently undergoing the final implementation and test phase in preparation for Exploration Mission 2 (EM-2). A key component is this software, which processes the images and produces navigation measurements and attitude measurements. The software development is being worked as a Government Furnished Equipment (GFE) project delivered as an application within the Core Flight Software of the Orion camera controller module.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_27263_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-27263-1","sourceUrl":"https://software.nasa.gov/software/MSC-27263-1","confidence":"high"},"type":"software","title":"view2space - A tool for computing view factors to space for CFD grids","abstract":"The standard radiation equilibrium boundary condition used for computational fluid dynamics (CFD) simulations assumes a perfect view to space. In reality, surfaces within view of each other have a complex radiation interchange that need to be modeled to accurately capture the physics.The reduced view factor to space is simply the view of space visible from each face on the input CFD grid and varies from zero to one. The code models this by rendering a simple black and white image. The reduced view factor to space is computed by determining the percentage of black pixels (space) in the image.The view factors are then exported in a data file so that they can be used by a CFD code.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_49205_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-49205-1","sourceUrl":"https://software.nasa.gov/software/NPO-49205-1","confidence":"high"},"type":"software","title":"PolSARproSimPlus: Coherent Electromagnetic Simulator for Radar Scattering from Forests","abstract":"PolSARproSim features the computation of SAR backscatter images from a region with three types of scattering objects: a bare surface, an isotropic layer of short vegetation and individual trees. The software considers only directly scattered radar returns from the bare surface, while both the trees and short vegetation are assumed to include both the direct and double bounce scattering mechanisms. Trees are represented and stored in parametric form and realized using procedures coded according to chosen tree species dependent upon chosen tree heights through allometric equations. The SAR image calculation phase is broken down into stages. The first of these is the calculation of canopy tree crown and understory permittivities. Crowns are assumed to have the same mean permittivity, and to be statistically isotropic. The next stage is to construct attenuation grids, which supply look-up tables for attenuation by spatial location. The attenuation grids are used when calculating scattering to provide approximate estimates of attenuation. Having determined the attenuation grids the next stage is the calculation of SAR images themselves. To simulate direct ground scattering, the ground surface is divided into numerous facets, and these are assigned complex scattering amplitudes, and focused in the image one after the other, each being scaled by the attenuation estimate for its location in the scene. For both the direct and indirect scattering from trees and short vegetation, each plant element realization is divided into scattering elements, where each scattering element is treated as an oriented cylinder. The scattered field from each cylinder, scaled by an appropriate attenuation estimate, is accumulated into the corresponding SAR image pixel using a system point-spread function.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa-jpl/PolSARproSimPlus","license":null}},{"forgeId":"forge_nasa_npo_51964_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51964-1","sourceUrl":"https://software.nasa.gov/software/NPO-51964-1","confidence":"high"},"type":"software","title":"Open Archival Information System - Interoperability Framework (OAIS-IF) Standard Prototype - OAISInteropFramework","abstract":"The Open Archival Information System Interoperability Framework (OAIS-IF) prototype serves as a test implementation of the OAIS-IF framework. Its goal is to facilitate international and collaborative research by fostering data sharing. Its primary objective is to offer a collection of interoperable protocols and interface specifications, enabling seamless access and reuse of data both within and beyond the digital repositories' operational boundaries. The OAIS-IF is intentionally designed to be versatile, catering to a wide range of small, medium, and large-scale use cases, disciplines, and stakeholders. Furthermore, it complements the overarching OAIS Reference Model (ISO 14721).","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-PDS/oias-if","license":null}},{"forgeId":"forge_nasa_npo_52743_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52743-1","sourceUrl":"https://software.nasa.gov/software/NPO-52743-1","confidence":"high"},"type":"software","title":"CADRE (Cooperative Autonomous Distributed Robotic Exploration), Multi-Agent Autonomy Software Stack","abstract":"CADRE (Cooperative Autonomous Distributed Robotic Exploration) is a technology demonstration on its way to the moon via the Commercial Lunar Payload Service (CLPS) program in 2024. It will be a first of its kind demonstration of multi-agent autonomous rovers, featuring three fully autonomous , shoebox-sized rovers performing a distributed measurement of the lunar surface and sub-surface with stereo cameras and a ground-penetrating radar. In this talk, we will provide an overview of the technology demonstration, as well as, a closer look at how the rovers will work autonomously together to plan and execute a distributed measurement.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/mercury7","license":null}},{"forgeId":"forge_nasa_npo_53348_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53348-1","sourceUrl":"https://software.nasa.gov/software/NPO-53348-1","confidence":"high"},"type":"software","title":"Vision-based Geo-Localization of Future Mars Rotocraft in Challenging Illumination Conditions using Deep Learning","abstract":"This work investigates deep learning-based methods to perform robust Map-based Localization (MbL) in challenging lighting. We proposed a novel multi-modal deep-learning framework that utilizes cross-attention mechanisms to fuse visual and depth data from ortho-projected maps and Digital Terrain Models (DTMs) obtained from orbital assets, effectively leveraging geometric context to learn illumination and scale invariance. To support training and validation, we developed a custom rendering framework to generate a synthetic Mars dataset with HiRISE ortho-images and DTMs, simulating aerial observations under varying lighting and altitude. Comprehensive evaluations show that our multi-modal method improves localization accuracy and robustness to a wide range of lighting offsets between maps and observations compared to single-modality models, including both deep-learning-based and traditional methods. Additionally, the integration of depth information has been shown to provide a degree of scale invariance and enhanced robustness to varying terrain morphology.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa-jpl/martian and https://github.com/nasa-jpl/mbl_mars","license":null}},{"forgeId":"forge_nasa_npo_53376_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53376-1","sourceUrl":"https://software.nasa.gov/software/NPO-53376-1","confidence":"high"},"type":"software","title":"Software for High Order Wavefront Sensing and Control (HOWFSC) with Coronagraphs","abstract":"The High Contrast Imaging Testbed (HCIT) Facility has been a leader in high contrast imaging research for the past two decades. The pairwise probing method for focal plane wavefront estimation and the Electric Field Conjugation (EFC) method for focal plane wavefront control developed and proven in the HCIT have been used across the world for achieving high contrast with coronagraphs. To support the first high contrast imaging instrument in space with active wavefront control , the Roman Space Telescope Coronagraph Instrument, the legacy HCIT software for pairwise probing and EFC was greatly improved with extensive unit testing and documentation. This new software package, named HOWFSC, is available in Python.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_53391_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53391-1","sourceUrl":"https://software.nasa.gov/software/NPO-53391-1","confidence":"high"},"type":"software","title":"Planetary Data System Radio Science Data Viewer","abstract":"The Planetary Data System (PDS) Radio Science Data Viewer (PRSDV) is an interactive application developed using MATLAB App Designer to provide quick-look functions to browse PDS4 TRK-2-34 formatted data. TRK-2-34 data, also known as Tracking and Navigation Files (TNFs), are the primary radiometric data type recorded at NASA's Deep Space Network for many interplanetary missions.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-PDS/RSdataViewer","license":null}},{"forgeId":"forge_nasa_npo_53450_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53450-1","sourceUrl":"https://software.nasa.gov/software/NPO-53450-1","confidence":"high"},"type":"software","title":"Visual Perception Engine: Modular, GPU-Accelerated Framework for Real-Time Visual Inference in Robotics","abstract":"The Visual Perception Engine is a modular, GPU-accelerated framework designed for real-time visual inference tasks in robotic applications. It integrates a vision foundation model (DINOv2) with multiple model heads to perform monocular depth estimation, semantic segmentation, and object detection at 30Hz. The system employs separate processes for the foundation model and each model head, communicating through custom GPU tensor queues to ensure efficient data exchange. Supporting both TensorRT and PyTorch models, the engine offers flexibility in deployment and performance optimization. Its runtime configurability allows users to adjust model parameters and inference rates dynamically. Additionally, the provided ROS2 (Humble) node enables straightforward integration into existing robotic systems, making the Visual Perception Engine a versatile tool for enhancing robotic perception capabilities.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa-jpl/visual-perception-engine","license":null}},{"forgeId":"forge_nasa_npo_53472_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53472-1","sourceUrl":"https://software.nasa.gov/software/NPO-53472-1","confidence":"high"},"type":"software","title":"CROW Timeline chart view","abstract":"Provides highly responsive and scalable visualization of mission activity and staffing timelines. Native solution that runs on iPhone, iPad, Mac and Apple Vision Pro. Reusable framework available to include in numerous apps for Apple platforms.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/OpsLabJPL/CROWTimelineView","license":null}},{"forgeId":"forge_nasa_npo_53490_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53490-1","sourceUrl":"https://software.nasa.gov/software/NPO-53490-1","confidence":"high"},"type":"software","title":"ExoReL : A Bayesian inverse retrieval algorithm to interpret exoplanetary reflected light spectra.","abstract":"The high-contrast imaging technique is meant to provide insight into those planets orbiting several astronomical units from their host star. Space missions such as Nancy Grace Roman Space Telescope and the Habitable World Observatory will measure reflected light spectra of cold gaseous and rocky planets. To interpret these observations, we introduce ExoReL^R (Exoplanetary Reflected Light Retrieval), a Bayesian retrieval framework to retrieve cloud properties and atmospheric structures from exoplanetary refleected light spectra. As a unique feature, it assumes a vertically nonuniform volume mixing ratio (VMR) profile of water and ammonia, and uses it to construct cloud densities. In this way, clouds and molecular mixture ratios are consistent","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/MDamiano/ExoReL","license":null}},{"forgeId":"forge_nasa_npo_53494_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53494-1","sourceUrl":"https://software.nasa.gov/software/NPO-53494-1","confidence":"high"},"type":"software","title":"HyperSTARS","abstract":"HyperSTARS is a multi-sensor, high-dimensional data fusion technology combining methods from functional data analysis and spatiotemporal statistics to produce high-frequency hyperspectral visible to shortwave infrared (VSWIR) reflectance data. Current orbital hyperspectral VSWIR imaging missions (EnMAP, PRISMA, EMIT), and future missions (SBG, CHIME), will not achieve the weekly revisit recommended by the Decadal Survey in the VSWIR to address high-priority science questions on terrestrial ecosystem change and agriculture management, snow and ice dynamics, and inland and coastal ecosystem health. HyperSTARS provides the critical data fusion technology needed to produce high resolution hyperspectral data with quantified uncertainties.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/STARS-Data-Fusion/HyperSTARS.jl","license":null}},{"forgeId":"forge_nasa_npo_53525_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53525-1","sourceUrl":"https://software.nasa.gov/software/NPO-53525-1","confidence":"high"},"type":"software","title":"Testbed Asset Configuration for Operations (TACO)","abstract":"TACO is a full stack web application that provides an interface and life-of- mission database to specify and track the configuration of hardware and software spacecraft components in validation and verification (V&V) and operational venues. It provides current status, snapshots, histories, and administrative interfaces for end user operators and administrators.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-JPL-Spacecraft-Analysis/TACO","license":null}},{"forgeId":"forge_nasa_npo_53526_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53526-1","sourceUrl":"https://software.nasa.gov/software/NPO-53526-1","confidence":"high"},"type":"software","title":"Europa Clipper Flight System Performance Analysis (FSPA) Downlink Software Development","abstract":"The software described (both new tools and upgrades to existing tools) facilitates rapid and robust analysis of the spacecraft via downlinked telemetry of various sorts. General capabilities include:- Management and visualization of data used in analysis, including standard channel and EVR data types, as well as other types including planning predicts and derived trends- Provides contextual awareness of data in relation to rule limits- Tracking of onboard FSW parameters and the onboard Ephemeris Table","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-JPL-Spacecraft-Analysis/state-manager;  https://github.com/NASA-JPL-Spacecraft-Analysis/robot-state-manager;  https://github.com/NASA-JPL-Spacecraft-Analysis/close-the-u-state-data-store;  https://github.com/NASA-JPL-Spacecraft-Analysis/close-the-u-py;  https://github.com/NASA-JPL-Spacecraft-Analysis/downlink-analysis-scripts;  https://github.com/NASA-JPL-Spacecraft-Analysis/dtat-library;  https://github.com/NASA-JPL-Spacecraft-Analysis/downlink-analysis-jupyter-cookbooks","license":null}},{"forgeId":"forge_nasa_npo_53559_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53559-1","sourceUrl":"https://software.nasa.gov/software/NPO-53559-1","confidence":"high"},"type":"software","title":"SIF-ARSET: Introduction to Solar-Induced Fluorescence (SIF) Data","abstract":"This code contains Jupyter notebooks and associated code for a NASA ARSET training course on the use of Solar Induced Fluorescence data from the Orbiting Carbon Observatory missions.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/jackiryan/SIF-ARSET","license":null}},{"forgeId":"forge_nasa_npo_53569_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53569-1","sourceUrl":"https://software.nasa.gov/software/NPO-53569-1","confidence":"high"},"type":"software","title":"Co-SWOT (Coastal Surface Water and Ocean Topography)","abstract":"The Surface Water and Ocean Topography missions surveys global water bodies including oceans, lakes, rivers, reservoirs, and wetlands. Coastal areas, such as estuaries and deltas, present a specific challenge due to the interaction of marine and terrestrial forces and the complex geomorphology. Both LR and HR data products are available over coastal areas, but both require several steps to process and evaluate accuracy of SWOT measurements of water surface elevations. To streamline processing of data within coastal areas (or anywhere that SWOT data are collected), we've built a set of tools to download, filter, and evaluate SWOT products.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/achri19/SWOT_Coasts/","license":null}},{"forgeId":"forge_nasa_npo_53581_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53581-1","sourceUrl":"https://software.nasa.gov/software/NPO-53581-1","confidence":"high"},"type":"software","title":"F Prime platform support package and standard components for Vorago VA416x0 microcontrollers","abstract":"Provide a high-quality foundation for Flight Software that is more reliable and thoughtfully integrated than the off-the shelf HAL and toolchains available from Vorago Technologies and Arm Software. Allow F Prime based Flight Software to run on the VA416x0 microcontrollers without an RTOS layer.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/fprime-community/fprime-vorago","license":null}},{"forgeId":"forge_nasa_npo_53582_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53582-1","sourceUrl":"https://software.nasa.gov/software/NPO-53582-1","confidence":"high"},"type":"software","title":"Spectral Information Distillation for Lightweight Exploration","abstract":"The software addresses two critical problems for planetary science missions. The first is data bandwidth. Modern imaging spectrometers produce huge datasets, roughly 100 times larger than standard images, which may not fit into the communication bandwidth available for transmitting data from deep space. This restricts the amount of scientific data that can be sent back from missions to the Moon and Mars. The second problem is operational agility as it can take days or even weeks for a full hyperspectral observation to be downlinked and processed into a form that scientists can use for mission planning. This software aims to solve that by creating summary products that can be transmitted and understood quickly (via a custom visualizer), allowing mission teams to react to findings as fast as possible.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/JPLMLIA/spindle","license":null}},{"forgeId":"forge_nasa_npo_53592_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53592-1","sourceUrl":"https://software.nasa.gov/software/NPO-53592-1","confidence":"high"},"type":"software","title":"OptoMMP Driver for LabVIEW","abstract":"The OptoMMP Driver for LabVIEW enables LabVIEW programs to communicate with Opto22 devices, such as SNAP-PAC industrial monitoring and control systems, using the Opto22 Memory Mapped Protocol (OptoMMP). The software is a native LabVIEW driver, with no external dependencies other than LabVIEW itself, and is capable of communicating with many Opto22 devices in parallel at polling rates up to 80 Hz. The driver is intended to be used in test facility data acquisition systems to collect sensor measurements, monitor facility status, and/or control test hardware. The OptoMMP Driver for LabVIEW is a LabVIEW library modeled after typical LabVIEW instrument driver libraries, and can be used by LabVIEW developers to communicate with Opto22 devices. It has standard error in and error out behavior, except where noted in the documentation. It requires no dependencies outside of LabVIEW itself.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/e-f-smith/optommp-labview-driver","license":null}},{"forgeId":"forge_nasa_npo_53597_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53597-1","sourceUrl":"https://software.nasa.gov/software/NPO-53597-1","confidence":"high"},"type":"software","title":"MERCAP - Mars Examination For Climate Patterns","abstract":"Martian dust storms are important phenomena to study from both science and mission concept perspectives. Scientifically, Mars possesses a dynamic atmosphere, and during exploration, dust affects ground operations and solar power production. Dust storms can range from local, to regional, to global scales, and they are important to understand given that they affect heating, circulation, and transport of volatiles (e.g., like H2O and CO2).","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/JPLMLIA/mercap","license":null}},{"forgeId":"forge_nasa_npo_53599_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53599-1","sourceUrl":"https://software.nasa.gov/software/NPO-53599-1","confidence":"high"},"type":"software","title":"VERSA: Vortex Event Reactive Sensor Algorithm","abstract":"This software is designed to develop and test ML algorithm prototypes for detecting events in time series data onboard small planetary spacecraft. Specifically, our package aims to autonomously detect previously recorded Martian dust vortices using time-series data from pressure sensors. This is meant to help research how future spacecraft might be able to use low-power monitoring mode to identify events of interest. Once identified, the spacecraft could then switch to a high-power, high-data-volume observation mode and spend more resources when a scientifically interesting event (e.g., a dust devil) is occuring. This approach aims to enable future technology that can enhance the scientific return from a mission while substantially reducing power consumption and data transmission needs.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/JPLMLIA/versa","license":null}},{"forgeId":"forge_nasa_npo_53718_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53718-1","sourceUrl":"https://software.nasa.gov/software/NPO-53718-1","confidence":"high"},"type":"software","title":"Orbiting Carbon Observatory-3 (OCO-3) Snapshot Area Mapping (SAM) Tool","abstract":"The Orbiting Carbon Observatory 3 (OCO-3) is a space instrument that will investigate important questions about the distribution of carbon dioxide on Earth as it relates to growing urban populations and changing patterns of fossil fuel combustion. OCO-3 explores, for the first time, daily variations in the release and uptake of carbon dioxide by plants and trees in the major tropical rain forests of South America, Africa, and South-East Asia, the largest stores of above ground carbon on our planet. Measuring the daily variations in these major carbon systems addresses an important missing component in our knowledge and is crucial for explaining global variations in atmospheric carbon dioxide levels. This OCO-3 SAMs web application creates a centralized location for information on where and when the mission collected SAMs and targeted observations, data maps, and a method to get subsetted data.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-OCO/oco3-sams","license":null}},{"forgeId":"forge_nasa_npo_53765_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53765-1","sourceUrl":"https://software.nasa.gov/software/NPO-53765-1","confidence":"high"},"type":"software","title":"WildOS: Open-Vocabulary Object Search in the Wild","abstract":"This work presents WildOS, a unified system for long-range, open-vocabulary object search that combines safe geometric exploration with semantic visual reasoning. WildOS builds a sparse navigation graph to maintain spatial memory, while utilizing a foundation-model-based vision module, ExploRFM, to score frontier nodes. ExploRFM simultaneously predicts traversability, visual frontiers, and object similarity in image space, enabling real-time, onboard semantic navigation tasks. The resulting vision-scored graph enables the robot to explore semantically meaningful directions while ensuring geometric safety. Furthermore, we introduce a particle-filter-based localization method that estimates coarse target positions beyond the robot's immediate depth horizon, enabling effective planning toward distant goals. Extensive closed-loop field experiments across diverse off-road and urban terrains demonstrate that WildOS enables robust generalization, significantly outperforming purely geometric and purely vision-based baselines in both efficiency and autonomy. Our results highlight the potential of vision foundation models to drive open-world robotic behaviors that are both semantically informed and geometrically grounded.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa-jpl/nebula2-wildos","license":null}},{"forgeId":"forge_nasa_npo_53779_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53779-1","sourceUrl":"https://software.nasa.gov/software/NPO-53779-1","confidence":"high"},"type":"software","title":"Hermes - A Command & Telemetry Framework","abstract":"Hermes is a platform meant to speed up the development of robotics software for spaceflight by providing an integrated tool for development of common JPL mission autonomous paradigms. JPL deep space missions typically utilize sequencing to prescribe the day-to-day autonomy carried out by surface robotics. Sequencing provides robot operators with planning flexibility required when performing various novel tasks. Robot operators also need insight into how the software and hardware is performing over the course of the sequence that may have previously commanded. RSVP Lite provides a system in which various telemetry products can be visualized over time. This includes the kinematic history of the robot as well as various visualizations to show the operator the world through the robots eyes and diagnose issues during development or operations","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/hermes","license":null}},{"forgeId":"forge_nasa_npo_53780_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53780-1","sourceUrl":"https://software.nasa.gov/software/NPO-53780-1","confidence":"high"},"type":"software","title":"Teamtools Studio Suite and DemoSat Adaptation","abstract":"This software is meant to enable spacecraft operators and operators of other complex systems to build last-mile solutions around existing Ground Data System solutions (GDS).It provides a wide range of functionalities across the Planning, Scheduling, Sequencing, Sequence Simulation , Sequence Validation, and Downlink Analysis functions of spacecraft operations. By bridging the gap between rigid, high-complexity Ground Data Systems and the dynamic workflow of the human operator, the software ensures that \"quality of life\" tools do not introduce operational risk. It replaces ad-hoc, untraceable manual scripts with a unified, tested framework, automating routine decision-making while maintaining a enabling users to create a complete audit trail of every operational action taken.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-JPL-Teamtools-Studio and https://github.com/NASA-JPL-TTS-Demosat","license":null}},{"forgeId":"forge_nasa_npo_53788_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53788-1","sourceUrl":"https://software.nasa.gov/software/NPO-53788-1","confidence":"high"},"type":"software","title":"Roman CGI CTC Data Integration Processor (DIP)","abstract":"It acts as the clerk to collate information, delegate tasks to work upon the collated information, then distribute any and all results to an archivist and publisher. It glues existing NASA open source technologies together for a specific purpose of organizing and managing the data flow through the CORGIDRP.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/roman-corgi/ctc-dip","license":null}},{"forgeId":"forge_nasa_npo_53794_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53794-1","sourceUrl":"https://software.nasa.gov/software/NPO-53794-1","confidence":"high"},"type":"software","title":"TaskSAT, a Framework for Analyzing Task nets","abstract":"TaskSAT is a domain-specific language and tool for modeling and verifying task scheduling problems with rich temporal and resource constraints. The system combines a declarative specification language with SMT-based automated reasoning using Z3. TaskSAT supports multiple types of state variables that model discrete states, Boolean flags, and continuous resources with complex dynamics. Tasks specify preconditions, invariants, postconditions, and resource impacts (assignments, deltas, rates) that occur at boundaries or during execution. The verifier encodes specifications into quantifier-free SMT formulas using zone-based time discretization, supporting both satisfiability checking and optimization. Users can express temporal properties using LTL-style operators (always, eventually, until, since) that are verified alongside scheduling constraints. TaskSAT can be applied to scheduling problems in autonomous systems, such as spacecraft and rover operations.","category":"aerospace","categoryRaw":"aeronautics","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa-jpl/tasksat","license":null}},{"forgeId":"forge_nasa_arc_15256_1d","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-15256-1D","sourceUrl":"https://software.nasa.gov/software/ARC-15256-1D","confidence":"high"},"type":"software","title":"Open Mission Control Technologies (Open MCT)","abstract":"Open MCT is an open source and web-based mission control framework for visualization of data on desktop and mobile devices. Open MCT is designed for analysis, visualization , operation, and support of spacecraft missions. Open MCT provides an extensible plugin system allowing it to be integrated with existing ground systems, and adapted to support multiple missions as well as non-space applications.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://nasa.github.io/openmct","license":null}},{"forgeId":"forge_nasa_arc_16721_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16721-1","sourceUrl":"https://software.nasa.gov/software/ARC-16721-1","confidence":"high"},"type":"software","title":"Autonomous eXplorer Control System (AXCS)","abstract":"AXCS enables smartphones and other mobile devices to be utilized as a ground-based test bed for operations in extreme environments. For NASA, the technology is currently being used to evaluate hardware for balloon launches. The software's tool kits provide environmental and situational measurements, command and data handing (CD&H) functions, events timing, data logging, and communications with external devices.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/cboshuizen/AXCS","license":null}},{"forgeId":"forge_nasa_arc_17994_1a","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-17994-1A","sourceUrl":"https://software.nasa.gov/software/ARC-17994-1A","confidence":"high"},"type":"software","title":"Astrobee Control Station","abstract":"The Astrobee Control Station is an extension of the Visual Environment for Remote Virtual Exploration (VERVE) that has been customized to operate the Astrobee robot on the International Space Station (ISS). The Astrobee robot has two purposes: it is a remotely-operated mobile camera and survey instrument for ground controllers, and it is an extensible zero gravity research platform for guest scientists. Ground controllers use the Astrobee Control Station to fly Astrobee, control its instruments, watch live video from its cameras, monitor its position and other telemetry, and download and delete collected data. Guest Scientists use the Astrobee Control Station to start and stop their experiments onboard Astrobee, and to monitor custom data and telemetry from their experiments. Though some Astrobee functions will require other tools, the Astrobee Control Station is the primary way that most users will interact with Astrobee.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/astrobee_gds","license":null}},{"forgeId":"forge_nasa_arc_17994_1b","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-17994-1B","sourceUrl":"https://software.nasa.gov/software/ARC-17994-1B","confidence":"high"},"type":"software","title":"Astrobee Control Station Binary","abstract":"The Astrobee Control Station is an extension of the Visual Environment for Remote Virtual Exploration (VERVE) that has been customized to operate the Astrobee robot on the International Space Station (ISS). The Astrobee robot has two purposes: it is a remotely-operated mobile camera and survey instrument for ground controllers, and it is an extensible zero gravity research platform for guest scientists. Ground controllers use the Astrobee Control Station to fly Astrobee, control its instruments, watch live video from its cameras, monitor its position and other telemetry, and download and delete collected data. Guest Scientists use the Astrobee Control Station to start and stop their experiments onboard Astrobee, and to monitor custom data and telemetry from their experiments. Though some Astrobee functions will require other tools, the Astrobee Control Station is the primary way that most users will interact with Astrobee.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_18520_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18520-1","sourceUrl":"https://software.nasa.gov/software/ARC-18520-1","confidence":"high"},"type":"software","title":"stol-mode","abstract":"An Emacs major mode for Spacecraft Test and Operations Language (STOL), written to be used with Integrated Test and Operations System (ITOS).","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/stol-mode","license":null}},{"forgeId":"forge_nasa_gsc_14308_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-14308-1","sourceUrl":"https://software.nasa.gov/software/GSC-14308-1","confidence":"high"},"type":"software","title":"Interoperable Remote Component (IRC)","abstract":"IRC provides robust interactive and distributed control /monitoring of remote instruments. The IRC architecture combines the processing capabilities of Java with the power of XML to express hierarchical data in a human-readable, platform-independent format. For additional information, please visit: http://opensource.gsfc.nasa.gov/projects/IRC/index.php","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://opensource.gsfc.nasa.gov/projects/IRC/index.php","license":null}},{"forgeId":"forge_nasa_gsc_14687_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-14687-1","sourceUrl":"https://software.nasa.gov/software/GSC-14687-1","confidence":"high"},"type":"software","title":"Goddard Enhanced Onboard Navigation System (GEONS)","abstract":"GEONS processes data from standard GPS receivers, communication equipment, and/or attitude sensors to produce accurate, absolute, relative onboard navigation solutions in real time. Navigation products from GEONS support additional autonomous functions, including onboard maneuver control , science viewing, and relative navigation for formation keeping.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_14912_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-14912-1","sourceUrl":"https://software.nasa.gov/software/GSC-14912-1","confidence":"high"},"type":"software","title":"Java Astrodynamics Toolkit (JAT)","abstract":"The Java Astrodynamics Toolkit (JAT) is a collection of Java components that aid flight dynamics engineers in performing space mission design; trajectory optimization; and spacecraft navigation, attitude-determination, and control systems analysis. Current capabilities include orbit propagation, orbit determination, maneuver planning, spacecraft attitude simulation, and 3D orbit and attitude visualization .","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://jat.sourceforge.net/","license":null}},{"forgeId":"forge_nasa_gsc_14993_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-14993-1","sourceUrl":"https://software.nasa.gov/software/GSC-14993-1","confidence":"high"},"type":"software","title":"Consultative Committee for Space Data Systems (CCSDS) File Delivery Protocol (CFDP) Software Library, Version 3.1","abstract":"This library provides for the reliable transfer of large data blocks to and from spacecrafts. It implements the international standard CFDP protocol, can be used from mission to mission, and supports both ground and flight software.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_16669_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-16669-1","sourceUrl":"https://software.nasa.gov/software/GSC-16669-1","confidence":"high"},"type":"software","title":"Global Precipitation Measurement (GPM) Spacecraft Flight Software (FSW) Version 4.7.2","abstract":"The Global Precipitation Measurement (GPM) spacecraft (S/C) flight software (FSW) controls and coordinates all aspects of the spacecraft's operation in nominal and anomolous conditions. It distributes commands to, and collects data from, all spacecraft subsystems and the science instruments. The FSW controls high gain antenna pointing to TDRSS satellites and manages communications with the ground controllers in real time to receive commands (during SSA contacts) and send housekeeping telemetry data during SSA and MA contacts. It sends science data using the Class-2 CCSDS File Delivery Protocol (CFDP). The GPM FSW monitors the health of most orbiter subsystems and takes corrective actions when necessary. The GPM FSW controls the pointing of the spacecraft/instruments to the earth's surface, the orientation of the solar arrays to collect power, and the pointing of the high gain antenna to communicate with TDRSS. The GPM FSW uses the propulsion system to perform orbit station keeping and re-entry upon mission completion. The GPM FSW also implements a safehold controller and can perform \"yaw maneuvers\" to re-orient the spacecraft velocity vector by 180 degrees.The GPM FSW uses Goddard's Operating System Abstration Layer (OSAL) and the Core Flight Executive (cFE) software. Ten Core Flight System (CFS) applications were co-developed by GPM and Code 582 and are now available in the Code 582 library for future mission use.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_17678_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-17678-1","sourceUrl":"https://software.nasa.gov/software/GSC-17678-1","confidence":"high"},"type":"software","title":"Sensor Coverage Tool","abstract":"Provides historical and predicted sensor tracking opportunities for objects","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_17683_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-17683-1","sourceUrl":"https://software.nasa.gov/software/GSC-17683-1","confidence":"high"},"type":"software","title":"Maneuver Trade Space","abstract":"The Maneuver Trade Space tool is used to assist in the operational decision making of the propulsive needs vs the time frame for a satellite maneuvering to avoid conjunctions with orbital debris and/or other satellites.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_17737_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-17737-1","sourceUrl":"https://software.nasa.gov/software/GSC-17737-1","confidence":"high"},"type":"software","title":"NASA Operational Simulator for Small Satellites (NOS^3)","abstract":"NOS3 is an open source software only test bed for small satellites. It is a collection of Linux executables and libraries. Current simulations are based on commercial off the shelf (COTS) hardware that is being used on the STF-1 CubeSat. It is intended to easily interface with flight software developed using the NASA Core Flight Software (cFS).","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/nos3","license":null}},{"forgeId":"forge_nasa_gsc_18016_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18016-1","sourceUrl":"https://software.nasa.gov/software/GSC-18016-1","confidence":"high"},"type":"software","title":"CARA SDK - Two-Dimension Probability of Collision (Pc) Calculation","abstract":"The two-dimension Probability of collision (Pc) calculation module set is one of the Conjunction Assessment Risk Analysis (CARA) Software Development Kit (SDK). It implements the calculation of the probability of collision of two satellites given the state estimates and covariances, following the methodology of Foster and Estes (1992).","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/CARA_Analysis_Tools/tree/master/two-dimension_Pc","license":null}},{"forgeId":"forge_nasa_gsc_18068_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18068-1","sourceUrl":"https://software.nasa.gov/software/GSC-18068-1","confidence":"high"},"type":"software","title":"Conjunction Consequence Assessment","abstract":"Determines both the likelihood of a catastrophic collision and estimates the amount of debris likely to be produced by a particular satellite conjunction should a collision actually occur. Includes methodologies to produce a PDF of reasonable mass values for the secondary object so that the equations for catastrophic collision determination and debris production estimation can be employed, following the work of Hejduk et al. (2017).","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/CARA_Analysis_Tools/tree/master/conjunction_consequence_assessment","license":null}},{"forgeId":"forge_nasa_gsc_18072_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18072-1","sourceUrl":"https://software.nasa.gov/software/GSC-18072-1","confidence":"high"},"type":"software","title":"Monte Carlo Pc Calculation from TCA (in equinoctial elements)","abstract":"Calculates the probability of collision (Pc) between two conjuncting satellites using a Monte Carlo technique, executing the draws from the propagated states and covariances at the time of closest approach (TCA) between the two satellites. The algorithm begins with the primary and secondary objects states and covariances at TCA, converts the two covariances from Cartesian to equinoctial element representation, samples perturbations from each covariance in element space (presuming Gaussian behavior in this framework), converts each of these perturbations to a Cartesian representation, perturbs the primary and secondary states with these converted perturbations, propagates pair of perturbed states forward until a new TCA is reached, notes the miss distance at TCA, and then determines the Pc empirically from these miss distance data. This technique follows the findings of Sabol (2010) regarding the efficacy of post-propagation transformation to element space to preserve Gaussian error behavior. The algorithm set also includes design -of-experiment aids to determine the number of Monte Carlo trials necessary to achieve a Pc of a desired confidence level.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/CARA_Analysis_Tools/tree/master/monte_carlo_Pc_from_TCA_equinoctial","license":null}},{"forgeId":"forge_nasa_gsc_18591_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18591-1","sourceUrl":"https://software.nasa.gov/software/GSC-18591-1","confidence":"high"},"type":"software","title":"Oversight","abstract":"A Splunk Application solution for aggregated hardware and software asset inventory. The application: identifies all hosts on the network, reports on host compliance status, and tracks for gaps in monitoring tools.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/Oversight","license":null}},{"forgeId":"forge_nasa_gsc_18593_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18593-1","sourceUrl":"https://software.nasa.gov/software/GSC-18593-1","confidence":"high"},"type":"software","title":"3D-Nc: Expected Collision Rates for Tracked Satellites","abstract":"The NASA Conjunction Assessment Risk Analysis (CARA) team has recently developed new algorithms and software to estimate collision rates and probabilities between Earth-orbiting satellites. The formulation entitled Expected Collision Rates for Tracked Satellites provides an innovative method to estimate collision risks based on the expected collision rate and number of collisions, which are both closely related to the collision probability. The new formulation accounts for the non-linear orbital motion of the satellites, and derives expressions that form the basis for Monte Carlo simulations, as well as semi-analytical approximations applicable to single- and multi-encounter interactions.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/CARA_Analysis_Tools/tree/master/ThreeDimensionalPc","license":null}},{"forgeId":"forge_nasa_gsc_18655_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18655-1","sourceUrl":"https://software.nasa.gov/software/GSC-18655-1","confidence":"high"},"type":"software","title":"Satellite State Estimate Covariance Realism Evaluation","abstract":"This software tool ingests position residuals between predicted and as-flown ephemerides, as well as associated covariances, and performs a number of statistical tests to determine whether the predicted covariance is a realistic description of actual state errors.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/CARA_Analysis_Tools/tree/master/CovarianceRealism","license":null}},{"forgeId":"forge_nasa_gsc_18694_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18694-1","sourceUrl":"https://software.nasa.gov/software/GSC-18694-1","confidence":"high"},"type":"software","title":"dorado-scheduling","abstract":"Dorado is a proposed space mission for ultraviolet follow-up of gravitational wave events. This repository contains a simple target of opportunity observation planner for Dorado.Features:* Global: jointly and globally solves the problems of tiling (the set of telescope boresight orientations and roll angles) and the scheduling (which tile is observed at what time), rather than solving each sub-problem one at a time* Optimal: generally solves all the way to optimality, rather than finding merely a \"good enough\" solution* Fast: solve an entire orbit in about 5 minutes* General: does not depend on heuristics of any kind* Flexible: problem is formulated in the versatile framework of mixed integer programming","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/dorado-scheduling","license":null}},{"forgeId":"forge_nasa_gsc_18753_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18753-1","sourceUrl":"https://software.nasa.gov/software/GSC-18753-1","confidence":"high"},"type":"software","title":"Goddard Mission Services Evolution Center (GMSEC) Application Programming Interface (API) 4.8","abstract":"The open-source GMSEC API allow software components to connect to a middleware messaging bus, that in turn, is responsible for message routing and delivery. The API and middleware combine to free the components from having to know where other components exist and what data they need. The API combined with the GMSEC message standards allow a component to be GMSEC-compliant and help it achieve plug and-play capability. Using standard messages for functionality helps the GMSEC environment achieve the goal of application interchangeability, where standardized components can be easily exchanged without affecting other GMSEC components. For a component to be considered GMSEC compliant, it must use the standard set of messages with the GMSEC API. The strength of the GMSEC API is that it allows changing middleware without impacting the GMSEC components or component interfaces. The API standardizes the interface to the middleware for the GMSEC component and normalizes the middleware behavior. The API supports multiple middleware, platforms and languages. The API interface to the middleware ensures similar behavior from a large selection of Commercial Off-the-Shelf (COTS) middleware. API users can switch middleware without changing the components' underlying code. The GMSEC API also provides access to all the standard middleware messaging capabilities including publish/subscribe, and request/reply.This software release contains enhancements to previous releases of the GMSEC API, including greater reliability and enhanced usability. For example, this release includes: Ruby script language binding, support for Python 3.8.5, and support for Apache Artemis. Numerous bug fixes are also included with this release.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/GMSEC_API","license":null}},{"forgeId":"forge_nasa_gsc_19027_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19027-1","sourceUrl":"https://software.nasa.gov/software/GSC-19027-1","confidence":"high"},"type":"software","title":"EventRate: Algorithm and Software to Estimate Serious Conjunction Rates for Earth-orbiting Satellites","abstract":"The EventRate algorithm and software estimates the rates at which proposed Earth-orbiting satellites can expect to experience serious conjunctions. Serious conjunctions are close-approach events with other satellites that have collision probability (Pc) values exceeding a threshold (e.g., Pc > 1e-4) that prompts collision risk remediation maneuvers (RMMs). The software approximates the orbital parameters of the conjunction events by using those archived for one or more current or preceding satellites with a similar orbit, as recorded over the last several years within NASA's Conjunction Assessment Risk Analysis (CARA) database. The software uses the semi-empirical algorithm described by Hall (2019, Determining Appropriate Risk Remediation Thresholds From Empirical Conjunction Data Using Survival Probability Methods, AAS Astrodynamics Specialist Conference, Portland, ME, Paper AAS 19-631, 2019) which allows the user to input the proposed satellite's hard-body radius, the RMM commit and consider times, and total on-orbit mission duration. The primary output of the software is the estimated rate of serious conjunctions in units of events per year, along with an estimated 95% confidence interval. The program also estimates the cumulative Pc values over the on-orbit lifetime of the proposed satellite mission. The software allows pre-launch trade-space analyses of several satellite and mission parameters, including: satellite HBR, on-orbit lifetime, RMM Pc threshold, RMM commit and consider times, RMM type (translational vs rotational), tracked catalog growth factor, and CARA orbital regime.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/CARA_Analysis_Tools","license":null}},{"forgeId":"forge_nasa_gsc_19090_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19090-1","sourceUrl":"https://software.nasa.gov/software/GSC-19090-1","confidence":"high"},"type":"software","title":"Goddard Mission Services Evolution Center (GMSEC) Application Programming Interface (API) 5.2","abstract":"Note 1 for GMSEC API 5.2 This software release contains enhancements to previous releases of the GMSEC API, including the following: a streamlined interface, auto-generation of message subjects, enhanced message validation, and support for Apache Artemis message queuing.Note 2 for GMSEC API 5.0 Previous versions of this software has been available open source for over 10 years and is available on NASA GitHub.The GMSEC API is a software interface to a ground system middleware messaging bus and enforces the use of standard defined messages; the middleware (not part of GMSEC API) is responsible for message routing and delivery. The GMSEC API adheres to the Command and Control Message Specification (C2MS) standard controlled by the international standards organization Object Management Group (OMG (https://www.omg.org/spec/C2MS/About-C2MS/). This allows an application to only send and receive valid C2MS messages, thus enabling plug-and-play. Using standard messages allows a ground system application developer to achieve the goal of application interchangeability, where an application can be replaced without affecting other applications that use the GMSEC API. The GMSEC API standardizes the interface to the middleware for an application. The API supports multiple middleware, hardware platforms, and programming languages. The GMSEC API abstracts the interface to the middleware, ensuring similar behavior from a large selection of Commercial-Off-the-Shelf (COTS) middleware. The GMSEC API normalizes common middleware behavior and provides access to the standard middleware messaging capabilities including publish/subscribe, and request/reply. Applications using the GMSEC API can switch among various middleware products without changing code.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/GMSEC_API","license":null}},{"forgeId":"forge_nasa_gsc_19094_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19094-1","sourceUrl":"https://software.nasa.gov/software/GSC-19094-1","confidence":"high"},"type":"software","title":"Advanced Spacecraft Integration & System Test software (ASIST) 23","abstract":"ASIST is a real-time command and control system that provides an environment for the development, integration, testing, and on-orbit operation of spacecrafts, their component subsystems and instruments, and external control and support equipment. This NTR is an addendum to the NTR filed for ASIST 22.0.ASIST 23.0 is the first ASIST build on Red Hat Enterprise Linux, version 8 and Ubuntu versions 18 & 20.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_19102_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19102-1","sourceUrl":"https://software.nasa.gov/software/GSC-19102-1","confidence":"high"},"type":"software","title":"Goddard Mission Services Evolution Center (GMSEC) Suite \u2013 Fall 2022","abstract":"The Goddard Mission Services Evolution Center (GMSEC) 5.3 software includes the GMSEC Application Programming Interface (API) along with software applications that enable the automation, situational awareness and verification of ground data systems for space flight missions. The GMSEC software leverages the scalable, open and extensible framework that the GMSEC API enforces through its abstraction of message-oriented middleware and adherence to the Command and Control Message Specification (C2MS) standard managed by the international standards organization Object Management Group (OMG) (https://www.omg.org/spec/C2MS/About-C2MS/). This release of the GMSEC software also includes additional features for the GMSEC API that enable secure communication between services and components operating in a ground system.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_19228_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19228-1","sourceUrl":"https://software.nasa.gov/software/GSC-19228-1","confidence":"high"},"type":"software","title":"FEDS 13.4.3","abstract":"The Front End Data System (FEDS) is a gateway between the user and the spacecraft. It decodes and interprets incoming spacecraft telemetry frames, extracting telemetry packets and delivering them to a number of client machines attached via Transmission Control Protocol/Internet Protocol (TCP/IP). It can also encapsulate and encode your command packets or frames and transmit them to your spacecraft.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_19352_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19352-1","sourceUrl":"https://software.nasa.gov/software/GSC-19352-1","confidence":"high"},"type":"software","title":"ITOS 2024.08","abstract":"ITOS is a suite of software applications that allow the user to command and telemeter a satellite. Its main functionality is to process, display, store and monitor telemetry, and to generate telecommands. Its key capabilities include closed-loop Telemetry and a Command Simulator. ITOS is the core element of a spacecraft or space instrument Ground Data System for: flight operations, integration and testing, and development. ITOS is highly user-configurable, and provides a scalable, cost-effective platform.ITOS can easily be utilized in any or all of the following mission phases:Board and Box developmentInstrument and component developmentSpacecraft developmentSpacecraft, instrument, and component simulationFlight software developmentIntegration and testingMission OperationsITOS is part of Goddard's Telemetry and Command (T&C) Capabilities","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_19374_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19374-1","sourceUrl":"https://software.nasa.gov/software/GSC-19374-1","confidence":"high"},"type":"software","title":"Advanced Satellite Conjunction Risk Assessment Methods","abstract":"The two-dimensional probability of collision calculation method is both widely used and computationally efficient. However, Monte Carlo simulations show that this method sometimes fails to provide sufficiently accurate estimates for Earth-orbiting satellites. This software provides a multistep algorithm that calculates collision probabilities for all conjunctions, regardless if affected by curvilinear trajectory or time varying covariance dynamics. The algorithm sequentially applies increasingly accurate estimation methods, but only as required for efficiency. Evaluating usage violations for the two-dimensional probability of collision method represents one of the most important steps. Extensive testing demonstrates the efficiency and reliability of the multistep algorithm.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/CARA_Analysis_Tools","license":null}},{"forgeId":"forge_nasa_gsc_19490_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19490-1","sourceUrl":"https://software.nasa.gov/software/GSC-19490-1","confidence":"high"},"type":"software","title":"Advanced Spacecraft Integration & System Test software (ASIST) 24.0","abstract":"ASIST is a real-time command and control system that provides an environment for the development, integration, testing, and on-orbit operation of spacecrafts, their component subsystems and instruments, and external control and support equipment.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_19625_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19625-1","sourceUrl":"https://software.nasa.gov/software/GSC-19625-1","confidence":"high"},"type":"software","title":"Integrated Test and Operations System (ITOS) 2026.02","abstract":"Integrated Test and Operations System (ITOS) is a comprehensive telemetry and command (T&C) solution for spacecraft, component, and instrument development, integration, test, and mission operations. It is highly user-configurable, and provides a scalable, cost-effective platform for small-budget projects to billion-dollar observatories. ITOS also provides extensive, closed-loop, scripted simulation capabilities.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_ksc_13561","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-13561","sourceUrl":"https://software.nasa.gov/software/KSC-13561","confidence":"high"},"type":"software","title":"Thermal Insulation System Analysis Tool (TISTool)","abstract":"The Thermal Insulation System Analysis Tool has been updated with more test data from the Cryogenics Test Laboratory and has been converted to Fortran 95 to allow for easier distribution.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_ksc_13923","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-13923","sourceUrl":"https://software.nasa.gov/software/KSC-13923","confidence":"high"},"type":"software","title":"Web Application: Ground Hardware Management Tool","abstract":"The Ground Systems Development and Operations (GSDO) Program requires a web-based application to effectively manage and coordinate the various components of ground support equipment (GSE) used at Kennedy Space Center (KSC) throughout the spacecraft and launch vehicle processing and integration flow, as well as for launch pad operations. A considerable amount of GSE is designed by the Launch Vehicle and Spacecraft developers for KSC use during the ground processing flow. Additionally, KSC develops GSE for use during processing, launch preparation, and launch activities. All GSE used at KSC during the processing flow is tracked and identified during ground operations planning activities. The Ground Operations Planning Database (GOPDb) provides the application to coordinate the various aspects of the ground planning phase. Additional rigor and visibility into the GSE component of ground operations planning is critical to a seamless and cost effective planning and design phase. An integrated GSE tracking solution must be developed to provide visibility, accountability, and configuration control of GSE data to all stakeholders while ensuring that the source data remains appropriately controlled and protected. This integrated GSE tracking and management tool the Ground Hardware Management Tool (GHMT) Application - for tracking and managing GSE data used in support of KSC\\GSDO operations planning and launch campaigns. The GHMT will be fully integrated with the GOPDb to provide a complete ground operations planning solution.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_ksc_14644","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-14644","sourceUrl":"https://software.nasa.gov/software/KSC-14644","confidence":"high"},"type":"software","title":"Software for Timeline Evaluation of Launch Logistics with Adaptive Rocket Refueling Requirements (STELLAR)","abstract":"STELLAR is a Matlab application that operates on an algorithm composed of several functions capable of generating launch plans and scrub-turnaround plans for flight vehicles as well as providing crucial information regarding launch capabilities. STELLAR is capable of outputting information for up to 4 resources at once. The inputs account for the current amount of the resource available, storage volume, and contractual limitations for purchasing the resource, among many others. The outputs include a Gantt chart timeline for the refueling or restocking of resource(s) as well as other important information listed below. While the tool was primarily designed for fluids (fuel, oxidizer, pressurants, etc.), it may also be used for other resources or payloads such as satellites, experiments, food, water, etc. Outputs: 1.A custom-made Gantt chart timeline which may be followed for the refueling or restocking of Resource(s). 2. The amount of the Resource(s) required to perform a launch if a launch is currently not possible. 3.The number of launch attempts currently available based on the amount of the Resource(s) of interest. 4.The number of days left until the storage tanks are depleted accounting for the amount of the Resource(s) used for performing a launch attempt. 5. The number of tankers required to transfer a standard amount of the Resource(s) to the storage tank. 6.Cost estimates for the refueling or stocking of Resource(s) based on contractual limitations.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_17264_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-17264-1","sourceUrl":"https://software.nasa.gov/software/LAR-17264-1","confidence":"high"},"type":"software","title":"ROBUS-2 Fault-Tolerant Broadcast Communication System for Modular Avionics","abstract":"ROBUS-2 is a time-division, multiple-access broadcast communication system that uses a time-indexed communication schedule for medium-access control . The technology provides guaranteed fault-tolerant services that include: message broadcast (Byzantine Agreement), dynamic communication schedule update, time reference (clock synchronization), and distributed diagnosis (group membership).","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://ti.arc.nasa.gov/opensource/projects/robus-2/","license":null}},{"forgeId":"forge_nasa_lar_18726_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18726-1","sourceUrl":"https://software.nasa.gov/software/LAR-18726-1","confidence":"high"},"type":"software","title":"Timeline Builder Assistant (TBA)","abstract":"Timeline Builder Assistant is intended to support initial surface operations planning by quickly building mission timelines with the \"Building Blocks\" method. The result produces a possible approach to completing all mission requirements and is intended for basic feasibility analysis . To build a new timeline, the user is prompted to enter the name of each building block and the number of times it is to be used. The program builds an EVA timeline to complete science and exploration objectives while complying with current human spaceflight limits on the number of hours of EVA allowed per day and week. At completion, the program displays the timeline, number of days to complete all requirements, number of rest days, and number of sites visited. The database keeps a record of activities and building blocks used in all surface missions and is easily searchable by the user or the program.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_18493_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-18493-1","sourceUrl":"https://software.nasa.gov/software/LEW-18493-1","confidence":"high"},"type":"software","title":"Command, Control , Communications, and Intelligence (C3I)Delay/Disruption-Tolerant (DTN) Networking Software","abstract":"This code is a DTN implementation of the Constellation Program's C3I software.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_18494_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-18494-1","sourceUrl":"https://software.nasa.gov/software/LEW-18494-1","confidence":"high"},"type":"software","title":"Command, Control , Communications, and Intelligence (C3I) Networking Software","abstract":"This implementation of the Constellation Program's C3I software has provided an environment for the prototype testing of a variety of networking protocols.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_18495_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-18495-1","sourceUrl":"https://software.nasa.gov/software/LEW-18495-1","confidence":"high"},"type":"software","title":"Command, Control , Communications, and Intelligence (C3I) Voice Exchange Software","abstract":"This implementation of the Constellation Program's C3I software has provided an environment for the prototype testing of a variety of voice exchange components.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_19313_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19313-1","sourceUrl":"https://software.nasa.gov/software/LEW-19313-1","confidence":"high"},"type":"software","title":"SCaN Optical Link Assessment Tool Version 2","abstract":"A calculation procedure has been designed and implemented in software that enables the specification and design of a space-based optical communications system. The resulting optical link budget essentially accounts for the communication power flow through the entire optical communications channel from the transmitter to the receiver and yields design specifications for the optical system necessary to assure reliable data transmission with desired operational metrics such as data rate, link margin, etc. The link assessment tool takes into account all the sources of deleterious noise that enters into the communications process such as electronically generated noise in the optical detector and stray optical irradiance from external sources. The link budget has the capability of being interfaced with the orbital element calculations of the Satellite Tool Kit (STK) to allow the dynamic description and evolution of optical link operation from any space-borne satellite within the solar system to and from the earth. The current version implements PPM and DPSK modulation types that can use PIN, APD, or nanowire optical detectors in teh presence of atmospheric turbulence. Coded and un-coded link power margins are provided.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_19620_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19620-1","sourceUrl":"https://software.nasa.gov/software/LEW-19620-1","confidence":"high"},"type":"software","title":"Multipath TCP (MPTCP) Tools, Analytics, and Configurations","abstract":"A collection of tools, scripts, and configurations to allow the use of Multipath Transmission Control Protocol (TCP) across multiple point to point interfaces such as those commonly used for satellite and optical links.This collection includes configurations for Multipath TCP (a new transport protocol) and other networking scripts which were used to benefit NASA's Earth Science Project which uses multiple Iridium satellite links. Also included is a set of tools to analyze MPTCP traffic to better understand the data flow, metrics, and performance of the system. The tool can be used for any MPTCP connections and is not specific to multiple point to point interfaces.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/multipath-tcp-tools","license":null}},{"forgeId":"forge_nasa_lew_19643_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19643-1","sourceUrl":"https://software.nasa.gov/software/LEW-19643-1","confidence":"high"},"type":"software","title":"STRS Flight Computer Interface (FCI) app for Core Flight System","abstract":"This software implements an application that executes within the NASA core flight system (cFS) that provides required STRS operating environment components using cFS and the corresponding Operating System Abstraction Layer (OSAL). This software utilizes the portable C/C++ STRS OE implementation described in a separate software package titled \"Portable C/C++ STRS Operating Environment Library\"as the basis for the fundamental STRS API calls. The combination of this interface application with the underlying library provide a complete STRS operating environment within the NASA core flight system.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_19897_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19897-1","sourceUrl":"https://software.nasa.gov/software/LEW-19897-1","confidence":"high"},"type":"software","title":"A High-Speed Software Implementation of Delay-Tolerant Networking","abstract":"Delay Tolerant Networking (or DTN) has been identified as a key technology to facilitate the development and growth of future space networks.Existing DTN implementations have emphasized operation in constrained environments with relatively limited resources and low data speeds. As various technologies have advanced, however, both the rate and efficiency with which data can be effectively transferred have grown incredibly quickly. This has left existing craft unable to utilize more than a small fraction of available capacity. Further, to date, most known implementations of DTN have been designed to operate on the spacecraft themselves.The innovation, in this case, is a software prototype called High-speed DTN (or HDTN). HDTN takes advantage of modern hardware platforms to offer substantial improvement on latency and throughput with respect to DTN implementations that exist today. Specifically, our implementation maintains compatibility with existing implementations of DTN that conform to IETF RFC 5050, while simultaneously defining a new data format that is better suited to higher-rate operation in many cases. It defines and adopts a massively parallel, pipelined, and message-oriented architecture, which allows the system to scale gracefully as the resources available to the system increase. HDTN's architecture additionally supports hooks for replacing various elements of the processing pipeline with specialized hardware accelerators, which can be used to offer improved Size, Weight, and Power (SWaP) characteristics at the cost of increased development complexity and cost.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/HDTN","license":null}},{"forgeId":"forge_nasa_lew_19897_2","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19897-2","sourceUrl":"https://software.nasa.gov/software/LEW-19897-2","confidence":"high"},"type":"software","title":"High-rate Delay Tolerant Networking (HDTN) Network Operations Release","abstract":"The High-rate Delay Tolerant Networking (HDTN) Network Operations Release is the culmination of multiple years of software development, end-to-end network testing, flight experiment operations, and formal verification and validation per NASA Procedural Requirements 7150.2D to mature early HDTN prototypes into a complete software package ready for space network operations. Delay Tolerant Networking is an architecture and set of protocols meant to support communication links which are characterized by disruption and delay or where a robust end-to-end path is not available. HDTN was specifically developed to meet the requirements of high-rate optical communication links, enterprise ground networks supporting multiple inputs and outputs, and low Size Weight and Power (SWaP) space platforms, including small satellites. The HDTN implementation focuses on efficient message processing, storage, and data transfer while maintaining a modular architecture with modern software dependencies. The HDTN Network Operations Release provides state-of-the-art protocols and full feature DTN support including Bundle Protocol version 7, Bundle Protocol version 6 with custody transfer, Aggregate Custody Signals (ACS), streaming over Real-time Transport Protocol (RTP), Bundle Protocol Security, and a full suite of convergence layers including Licklider Transmission Protocol (LTP), Transmission Control Protocol (TCP) convergence layer version 3 and 4, Simple TCP, and User Datagram Protocol (UDP). This new version of HDTN supports Contact Graph Routing, Contact Multigraph Routing, dynamic contact plan updates, and link state detection via a custom DTN ping capability. A variety of applications have been added including bundle generation, real-time streaming, file transfer, general packet conversion to bundle, ping, and an application programming interface supporting many basic commands. A web-based user interface has been added to display metrics in tabular and plot format, as well as a visual system-level overview. Troubleshooting features including logging metrics to file, logging error and status messages to console and file, and a command line interface have also been included. In addition to providing a wide range of features, the HDTN Network Operations Release has completed successful flight experiments and operations onboard the International Space Station and a CubeSat demonstration, and has completed rigorous testing through static analysis , requirements verification and validation, and has a full set of software documentation available to support space flight and ground operations missions. HDTN Network Operations Release has been used to successfully demonstrate gigabit per second (Gbps) data transfer in a relevant space flight environment, and up to 30 Gbps in a laboratory environment.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/HDTN","license":null}},{"forgeId":"forge_nasa_lew_20210_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20210-1","sourceUrl":"https://software.nasa.gov/software/LEW-20210-1","confidence":"high"},"type":"software","title":"Python Ground Station for a Core Flight System with CCSDS Electronic Data Sheets Support","abstract":"This software package primarily consists of a python based graphical user interface (GUI) which serves as a generic telemetry and telecommand system for any mission that uses core flight systems (cFS) with CCSDS Electronic Data Sheets (EDS) support. The GUI utilizes python bindings to automatically read all of the information contained in the mission's EDS Library and Core Flight Executive (CFE) Mission Library.On the telecommand side this allows instance names, topic names, and subcommand names to be automatically populated in drop-down menus. Command that require a payload will produce text boxes or drop-down menus for user entry. Finally, completed commands are packed and sent to the desired core flight instance.On the telemetry side, the GUI will continuously listen for messages. When messages arrive, they are decoded, the contents are displayed to the screen, sorted by topic, and saved internally. Telemetry messages can be saved to binary files for further processing.Also included are several utility python scripts. Two such scripts perform the command sending and telemetry decoding functionality of the GUI. The third reads in the saved telemetry data files and converts the messages into a CSV format which can be loaded in an Excel type program.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/cFS-EDS-GroundStation","license":null}},{"forgeId":"forge_nasa_lew_20529_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20529-1","sourceUrl":"https://software.nasa.gov/software/LEW-20529-1","confidence":"high"},"type":"software","title":"GRC Lunar Site Analysis Software","abstract":"This set of analysis functions can be used to assess lunar landing site solar illumination and communication availability using lunar terrain masks obtained from the terrain data, obtained from measurements of the Lunar Orbiter Laser Altimeter (LOLA) instrument aboard the Lunar Reconnaissance Orbiter (LRO) spacecraft, to model terrain-based blockage.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_20723_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20723-1","sourceUrl":"https://software.nasa.gov/software/LEW-20723-1","confidence":"high"},"type":"software","title":"GRC Lunar Site Analysis Software Version 2","abstract":"This software involves a set of analysis functions that can be used to assess lunar landing site solar illumination and communication availability using lunar terrain masks of the LOLA-derived terrain data to model terrain-based blockage. It is an update to a 2023 software, adding new interface aspects to simplify and enhance the user experience, and has an updated and run-time optimized algorithm for calculating terrain masks.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_33978_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-33978-1","sourceUrl":"https://software.nasa.gov/software/MFS-33978-1","confidence":"high"},"type":"software","title":"DTN Marshall Enterprise","abstract":"DTN Marshall Enterprise is a fully compliant CCSDS Delay/Disruption Tolerant Network (DTN) router that has been used to conduct International Space Station (ISS) payload operations for many years. Communications in space are characterized by their disrupted, wireless nature. Whether due to occultation, scheduling, cost or solar flares, spacecraft must handle interruptions in connectivity and data losses. Delay/Disruption Tolerant Networking (DTN) using the bundle protocol (BP) can maximize the efficient use of links to and among spacecraft . As part of NASAs efforts to deploy DTN in space, the HOSC developed a general purpose DTN router based on the SourceForge DTN2 version 6 reference code and reinvented a previously develop capability called the External Router. This allows non-network cognizant operators to manage the ground gateway as though it were another piece of the ground system without perturbing its actual specifications. The HOSC has deployed their implementation of the DTN Bundle Protocol (BP) to payloads on the International Space Station (ISS).The current request is to export and make available for technology transfer the current DTNME implementation. It is also desirable for it to reside on github.com/NASA/DTNME. DTNME implemented DTN protocols as primarily defined by RFC 5050 and several other RFCs. This was also used by the HOSC to verify a new CCSDS standard (Bundle Protocol Specification CCSDS 734.2-B-1) that is used in various programs. The standard or the next generation is now being targeted for Gateway. After successfully using it operationally, we have accumulated a new patch set. The combined implementation is what we would like to release as DTNME v0.1. DTN2 software updates were originally released to SourceForge.net under NTR# 1428003694. This was a patch update that incorporated functionality of the CCSDS standard and pre-operational generic features used on the ISS.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/DTNME","license":null}},{"forgeId":"forge_nasa_mfs_33978_2","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-33978-2","sourceUrl":"https://software.nasa.gov/software/MFS-33978-2","confidence":"high"},"type":"software","title":"DTN Marshall Enterprise (DTNME)","abstract":"DTN Marshall Enterprise is a fully compliant CCSDS Delay/Disruption Tolerant Network (DTN) router that has been used to conductInternational Space Station (ISS) payload operations for many years. Communications in space are characterized by their disrupted, wireless nature. Whether due to occultation, scheduling, cost or solar flares, spacecraft must handle interruptions in connectivity and data losses. Delay/Disruption Tolerant Networking (DTN) using the bundle protocol (BP) can maximize the efficient use of links to and among spacecraft . As part of NASA's efforts to deploy DTN in space, the HOSC developed a general purpose DTN router based on the SourceForge DTN2 version 6 reference code and reinvented a previously developed capability called the External Router. This allows non-network cognizant operators to manage the ground gateway as though it were another piece of the ground system without perturbing its actual specifications. The HOSC has deployed their implementation of the DTN Bundle Protocol (BP) to payloads on the International Space Station (ISS). The current request is to export and make available for technology transfer the latest DTNME implementation that includes version 7. The addition of version 7 moves the DTNME baseline to the latest IETF release allowing developers to test with a single implementation that is able to support multiple bundle protocol implementations simultaneously. This implementation resides on github.com/NASA/DTNME.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_25810_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-25810-1","sourceUrl":"https://software.nasa.gov/software/MSC-25810-1","confidence":"high"},"type":"software","title":"Input Device Framework (IDF)","abstract":"Framework for mapping physical input devices (joysticks, gaming controllers, custom control panels, etc) to application-specific virtual controller interfaces. Pattern for writing device-independent code.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/IDF","license":null}},{"forgeId":"forge_nasa_msc_25958_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-25958-1","sourceUrl":"https://software.nasa.gov/software/MSC-25958-1","confidence":"high"},"type":"software","title":"Approximate Cartesian Control for Robotic Tool Usage with Graceful Degradation","abstract":"This is a software toolkit for flexible tool use by robotic manipulators. The suite of state-of-the-art algorithms is focused on extending current pick-and-place planning and control methods to enable robust tool usage by humanoid and other armed robots. The system provides more intuitive tools for the user of the robotic manipulator, including visualization tools for defining tool use scenarios, including Cartesian tolerances along trajectories and expected forces/torques on the tool tip. This allows robots to be more capable and more reliable during long-term autonomous tasks, by significantly improving the ability of remote supervisors to command complex tool-usage tasks, by enabling robots to operate safely alongside humans during shared tasks, and by providing a general tool usage framework that works with novel tools and with any robot configuration.No NASA Software Usage Agreement Needed. Go to https://bitbucket.org/traclabs/craftsman","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://bitbucket.org/traclabs/craftsman","license":null}},{"forgeId":"forge_nasa_msc_26690_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-26690-1","sourceUrl":"https://software.nasa.gov/software/MSC-26690-1","confidence":"high"},"type":"software","title":"Debris Assessment Software (DAS) v. 3.2.7","abstract":"The Debris Assessment Software (DAS) is provided by the NASA Orbital Debris Program Office as a means of assessing, during the planning and design phase, space missions compliance with NASAs requirements for reduction of orbital debris. DAS is designed to assist NASA programs in performing orbital debris assessments (ODA), as described in NASA Technical Standard 8719.14, Process for Limiting Orbital Debris. The software reflects the structure of the Standard and provides the user with tools to assess compliance with the requirements. If non-compliant, DAS may also be used to explore debris mitigation options to bring a program within requirements.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_27734_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-27734-1","sourceUrl":"https://software.nasa.gov/software/MSC-27734-1","confidence":"high"},"type":"software","title":"Electronic Procedure Application Software Suite (EPASS) Library Administration (LibAdmin) 1.1 and Subs (1.XX)","abstract":"The EPASS LibAdmin application allows users to manage Artemis procedures libraries used by ground flight controllers, onboard crew members, and onboard the eProc display on various vehicle avionics system.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_19636_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-19636-1","sourceUrl":"https://software.nasa.gov/software/NPO-19636-1","confidence":"high"},"type":"software","title":"GNSS-Inferred Positioning System and Orbit Analysis Simulation Software (GIPSY-OASIS)","abstract":"GIPSY-OASIS is widely used for geophysical and global positioning system research.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_35238_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-35238-1","sourceUrl":"https://software.nasa.gov/software/NPO-35238-1","confidence":"high"},"type":"software","title":"Mission Display (MDX) System","abstract":"The Mission Display (MDX) System can be used to visualize a wide variety of raster scan data, including IFSAR images and DEM. The technology enables the user to view very large data sets (greater than 2 gigabytes per image) and offers several ways to combine information from different data sets into a single display window.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_45871_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-45871-1","sourceUrl":"https://software.nasa.gov/software/NPO-45871-1","confidence":"high"},"type":"software","title":"Maestro Science Activity Planner for Mars","abstract":"The Maestro Science Activity Planner (Maestro) provides an intuitive interface to the Mars Exploration Rovers Mission, combining cutting-edge visualization with sophisticated planning and simulation capabilities.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_47292_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-47292-1","sourceUrl":"https://software.nasa.gov/software/NPO-47292-1","confidence":"high"},"type":"software","title":"MSLICE Sequencing","abstract":"This tool was developed for the NASA Mars Science Laboratory (MSL) mission . MSLICE Sequencing is a graphical tool for writing sequences and integrating them into RML files, as well as producing SCMF files for uplink. When operated in a testbed environment, it also supports uplinking these SCMF files to the testbed via Chill.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_48235_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-48235-1","sourceUrl":"https://software.nasa.gov/software/NPO-48235-1","confidence":"high"},"type":"software","title":"CalSimHydro","abstract":"This Web-based, Google Earth-enabled interactive interface provides a tool for configuring, running, viewing, and downloading the results of a CalSim 3.0 Hydrology Preprocessor program. The software allows the user to (1) interact with a map of water budget areas (WBAs) and display data for a selected WBA in tabular form or as a time series plot; (2) edit input and run a CalSim 3.0 Hydrology Preprocessor; and (3) compare results with base-run output and download the output file. CalSimHydro will be delivered to the California Department of Water Resource (DWR) and released as a part of the CalSim 3.0 system.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_ssc_00529","source":{"institution":"NASA","subUnit":"Stennis Space Center","subUnitCode":"SSC","nativeId":"SSC-00529","sourceUrl":"https://software.nasa.gov/software/SSC-00529","confidence":"high"},"type":"software","title":"NOSS (NDAS One Stop Shop)","abstract":"NOSS is a web based central configuration interface for NASA Data Acquisition System(NDAS) or can additionally be used as a frontend for other types of data acquisition systems. NOSS is accessed using a web browser and allows for concurrent multi-user access. After configuration is complete, a user can export a xml that can be used in the configuration of a data acquisition system.NOSS is organized around two main building blocks: nodes and measurements. Nodes represent physical and logical components of a test facility. Examples of physical components could be signal conditioner cards, receptacle box connection points, filters, attenuators, digitizer cards, transducers, valves, etc. Logical components could be acquisition system channels, facility redline system channels, or any other software-type endpoint systems. As such, NOSS can be used to track and manage the current state of all data acquisition components on a test facility.Measurements are defined by linking together specific nodes in the system. Measurements represent the full signal path from a signal source (commonly a transducer) to acquisition system endpoint. Additional measurement information can also be defined such as a unique measurement name, description, etc.","category":"operations","categoryRaw":"operations","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_14020_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-14020-1","sourceUrl":"https://software.nasa.gov/software/ARC-14020-1","confidence":"high"},"type":"software","title":"Incompressible Navier-Stokes CFD Solver (INS3D)","abstract":"The INS3D code solves the incompressible Naiver-Stokes equations in three-dimensional generalized coordinates for both steady-state and time varying flow. The equations are formulated using the method of artificial compressibility. The convective terms are differenced using an upwind biased flux-difference splitting. The equations are solved using an implicit line-relaxation scheme. The code is written for single or multiple-zone calculations. It can utilize either pointwise continuous zonal interfaces, or overset zonal interfaces if a PEGASUS interpolation database is supplied. The INS3D code is written in Fortran77 and C. The code only runs in a serial execution mode. This code was developed in the 1990s and is no longer under development at NASA.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_14275_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-14275-1","sourceUrl":"https://software.nasa.gov/software/ARC-14275-1","confidence":"high"},"type":"software","title":"Automated Triangle Geometry Processing for Surface Modeling and Cartesian Grid Generation (Cart3D)","abstract":"Cart3D is a high-fidelity inviscid analysis package for conceptual and preliminary aerodynamic design. It allows users to perform automated computational fluid dynamics (CFD) analysis on complex geometry. The package includes utilities for geometry import, surface modeling and intersection, mesh generation, and flow simulation . Cart3D is highly automated so that geometry acquisition and mesh generation can usually be performed within a matter of minutes on most modern UNIX workstations or PCs.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_14467_1a","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-14467-1A","sourceUrl":"https://software.nasa.gov/software/ARC-14467-1A","confidence":"high"},"type":"software","title":"Computational Fluid Dynamics (CFD) Utility Software Library","abstract":"A collection of utility programs and reusable subroutine libraries supports computational fluid dynamics, particularly on multiblock structured grids. The technology is applicable to all flight regimes-subsonic, transonic, supersonic, and hypersonic.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://sourceforge.net/projects/cfdutilities","license":null}},{"forgeId":"forge_nasa_arc_14487_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-14487-1","sourceUrl":"https://software.nasa.gov/software/ARC-14487-1","confidence":"high"},"type":"software","title":"CAPTools-based Automatic Parallelizer Using OpenMP (CAPO)","abstract":"CAPO analyzes a Fortran program and inserts OpenMP directives into the code to improve its performance on a parallel machine. The tool relies on accurate inter-procedural data -dependence information currently provided by CAPTools, which was developed at the University of Greenwich.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_14529_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-14529-1","sourceUrl":"https://software.nasa.gov/software/ARC-14529-1","confidence":"high"},"type":"software","title":"IND 2.1-Creation and Manipulation of Decision Trees from Data","abstract":"Decision trees are commonly used in artificial intelligence and statistical pattern recognition. A tree is \"grown\" from data using a recursive-partitioning algorithm. IND re-implements parts of existing standard prediction algorithms, offers experimental control suites, and also introduces new, more sophisticated methods for growing decision trees.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://ti.arc.nasa.gov/opensource/projects/ind/","license":null}},{"forgeId":"forge_nasa_arc_14672_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-14672-1","sourceUrl":"https://software.nasa.gov/software/ARC-14672-1","confidence":"high"},"type":"software","title":"CODE-A Software Framework For Control and Observation In Distributed Environments","abstract":"CODE is a framework for the control and observation of resources, services, and applications. The technology supports the secure and scalable transmission of observed information to other programs, and it enables the secure execution of actions on remote computer systems.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://www.nas.nasa.gov/Resources/Software/Open-Source/code.html","license":null}},{"forgeId":"forge_nasa_arc_14932_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-14932-1","sourceUrl":"https://software.nasa.gov/software/ARC-14932-1","confidence":"high"},"type":"software","title":"Mission Simulation Toolkit (MST)","abstract":"MST offers a simulation framework to support research in autonomy for remote exploration. The system allows developers to test models in a high-fidelity simulation and then evaluate system performance against a set of integrated, standardized simulations.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://ti.arc.nasa.gov/opensource/projects/mission-simulation-toolkit/","license":null}},{"forgeId":"forge_nasa_arc_15016_1a","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-15016-1A","sourceUrl":"https://software.nasa.gov/software/ARC-15016-1A","confidence":"high"},"type":"software","title":"TPSSizer (aka TPSSZR) - Vehicle TPS sizing program using FIAT","abstract":"TPSSizer is a Thermal Protection System (TPS) sizing tool developed at ARC for use in conceptual level through detailed design level analysis . TPS sizing methodologies and data exchange interfaces with supporting disciplines were developed for TPSSizer. Additionally, the tool introduced improvement to prior art with the automatic generation of TPS stackups, automatic generation of aerothermal environment files, maintenance of consistent material properties descriptions, the capability to simultaneously evaluate multiple nominal and abort flight trajectories and the development of methodologies for the application of appropriate design margins.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_15103_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-15103-1","sourceUrl":"https://software.nasa.gov/software/ARC-15103-1","confidence":"high"},"type":"software","title":"JavaGenes-Scheduler: Evolutionary Software for Earth Observing Satellite Scheduling","abstract":"JavaGenes-Scheduler is a general purpose evolutionary system designed to compare techniques for scheduling observations. It was originally developed for scheduling observations made by Earth-observing satellites. JavaGenes-Scheduler uses a simple, earliest-first scheduler to insert observations into the timeline in permutation order.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://alglobus.net/NASAwork/JavaGenes","license":null}},{"forgeId":"forge_nasa_arc_15150_1a","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-15150-1A","sourceUrl":"https://software.nasa.gov/software/ARC-15150-1A","confidence":"high"},"type":"software","title":"NASA Task Load Index (TLX) iOS","abstract":"The NASA Task Load Index (TLX) provides multi-dimensional ratings of overall workload based on a weighted average of six subscales: mental demands, physical demands, temporal demands, performance, effort, and frustration.NASA TLX iOS is a full computational version of its predecessor Windows NT, and pencil and paper version. Data collection may be performed through an iPhone, or an iPad.","category":"biomedical_health","categoryRaw":"crew and life support","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://itunes.apple.com/us/app/nasa-tlx/id1168110608","license":null}},{"forgeId":"forge_nasa_arc_15166_1d","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-15166-1D","sourceUrl":"https://software.nasa.gov/software/ARC-15166-1D","confidence":"high"},"type":"software","title":"Web WorldWind 3D Virtual Globe, v0.10","abstract":"NASA World Wind is virtual globe technology provided as an Application Programming Interface-Centeric (API-Centric) Software Development Kit (SDK). It is elemental technology allowing others to see \"their\" spatial data in the native context of Earth or any other planet for which there is data . Any application, proprietary or other, can use NASA World Wind to see their data in a 3D context.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASAWorldWind/WebWorldWind","license":null}},{"forgeId":"forge_nasa_arc_15193_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-15193-1","sourceUrl":"https://software.nasa.gov/software/ARC-15193-1","confidence":"high"},"type":"software","title":"Geometry Manipulation Protocol (GMP) for ComputationalFluid Dynamics (CFD) Applications, Version 1.0","abstract":"GMP serializes datatypes between XML and ANSI C data structures to support CFD applications. The library currently provides a description of geometric configurations, general moving-body scenarios (prescribed and/or 6-DOF), and control surface settings.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://ti.arc.nasa.gov/opensource/projects/gmp/","license":null}},{"forgeId":"forge_nasa_arc_15262_1b","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-15262-1B","sourceUrl":"https://software.nasa.gov/software/ARC-15262-1B","confidence":"high"},"type":"software","title":"NEQAIR v15.x, Nonequilibrium Radiative Transport and Spectra Program","abstract":"NEQAIR is NASAs most long standing radiative heating code for flight predictions and simulating experiments. It is a line-by-line radiation code that computes spontaneous emission, absorption and stimulated emission due to transitions between various energy states of chemical species along a line-of-sight through a non-uniform gas mixture. This allows NEQAIR to calculate the radiative heat flux and detailed spectra at a specified location. NEQAIR v15.3, which includes v0.35 of the GUI, has focused on improving physics, solution robustness for 3D and coupled calculations, and providing more control for running the code.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_15654_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-15654-1","sourceUrl":"https://software.nasa.gov/software/ARC-15654-1","confidence":"high"},"type":"software","title":"Brahms: A Multiagent Simulation /Execution Environment for the Brahms Multiagent Language","abstract":"Brahms is a multiagent programming language for modeling people and systems in a conceptual world. Brahms language gives users the ability to model the behavior of human organization, communication,and teamwork, as well as human-machine interaction.","category":"operations","categoryRaw":"business systems and project management","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_15690_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-15690-1","sourceUrl":"https://software.nasa.gov/software/ARC-15690-1","confidence":"high"},"type":"software","title":"Growler","abstract":"Growler is a component-oriented framework aimed at distributed and collaborative visualization and computational steering. The technology's distributed object and event architecture is suitable for application to high-performance local area network (LAN) environments as well the Internet. Its features include strong integration with C++, selective distributed reference counting, and efficient well-typed event channels for local as well as remote event broadcast.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://ti.arc.nasa.gov/opensource/projects/growler/","license":null}},{"forgeId":"forge_nasa_arc_15761_1a","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-15761-1A","sourceUrl":"https://software.nasa.gov/software/ARC-15761-1A","confidence":"high"},"type":"software","title":"NASA Vision Workbench (VW), Version 3","abstract":"Vision Workbench (VW) is a modular, extensible computer vision framework that supports a range of tasks, including automated science and engineering analysis , large satellite image processing, and 2D/3D environment reconstruction. The framework provides a rapid C development environment as well as a flexible, multi-platform system to deploy computer vision applications. The module interface allows new capabilities to be rapidly integrated, and the dataflow architecture allows image-processing pipelines to be quickly developed and reconfigured.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/visionworkbench/visionworkbench","license":null}},{"forgeId":"forge_nasa_arc_15771_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-15771-1","sourceUrl":"https://software.nasa.gov/software/ARC-15771-1","confidence":"high"},"type":"software","title":"NodeMon-A Visualization Tool For Monitoring System Resource Utilization","abstract":"NodeMon allows distributed resource monitoring via a growler software infrastructure. The tool is tailored to the Altix architecture but is applicable to any Linux system. Individual modules will monitor CPU, memory, and numalink activity. NodeMon will compose large amounts of statistical information and display it through a single graphical window.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://ti.arc.nasa.gov/opensource/projects/nodemon/","license":null}},{"forgeId":"forge_nasa_arc_15779_1a","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-15779-1A","sourceUrl":"https://software.nasa.gov/software/ARC-15779-1A","confidence":"high"},"type":"software","title":"Fully Implicit Ablation and Thermal Analysis Program, Version 3 (FIAT v3) - unrestricted version","abstract":"FIAT v3 simulates one-dimensional thermal energy transport in a multilayer stack of isotropic materials and structures that can ablate from the front surface and decompose in depth. The implicit solution algorithm and general solution technique make the program very stable and robust for application to both robotic and crewed vehicles entering a planetary atmosphere from space. For input, the code reads material property information from a database file.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_15804_1a","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-15804-1A","sourceUrl":"https://software.nasa.gov/software/ARC-15804-1A","confidence":"high"},"type":"software","title":"BALFIT - A Multivariate Regression Analysis Tool","abstract":"BALFIT is designed for the automated regression analysis of wind tunnel strain-gage balance calibration data. Related strain-gage balance data analysis tasks are also supported. In addition, BALFIT performs an automated regression analysis of more general multivariate data sets at a basic level.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_15819_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-15819-1","sourceUrl":"https://software.nasa.gov/software/ARC-15819-1","confidence":"high"},"type":"software","title":"Configuration-Based Aerodynamics (CBAero)","abstract":"CBAero is a software tool for the prediction of the conceptual aero-thermodynamic environments of aerospace configurations. The vehicle geometry is defined using unstructured, triangulated surface meshes. For subsonic Mach numbers a fast, unstructured, multi-pole panel code is coupled with a streamline tracing formulation to define the viscous surface solution. For supersonic and hypersonic Mach numbers, various independent panel methods are coupled with the streamline tracing formulation, attachment line detection methods, and stagnation-attachment line heating models to define the viscous aero- thermal environment.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_16019_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16019-1","sourceUrl":"https://software.nasa.gov/software/ARC-16019-1","confidence":"high"},"type":"software","title":"Viewpoints: Software for Visualization of Multivariate Data","abstract":"A software application that allows the interactive visualization of multivariate data using a variety of standard techniques, Viewpoints can be used with extremely large data sets.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://www.assembla.com/wiki/show/viewpoints/downloads","license":null}},{"forgeId":"forge_nasa_arc_16021_1b","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16021-1B","sourceUrl":"https://software.nasa.gov/software/ARC-16021-1B","confidence":"high"},"type":"software","title":"Data Parallel Line Relaxation Code (DPLR), Version 4.05","abstract":"The DPLR software package is a suite of CFD tools for the computation of supersonic and hypersonic flows in chemical and thermal nonequilibrium. Included in the package are 2D/axisymmetric and 3D structured grid finite volume Navier-Stokes codes, a pre-processor, and a post-processor. The code supports implicit boundary conditions, generalized multi-block topologies, grid alignment to flow features, and generalized chemical kinetics and thermodynamic property databases.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_16053_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16053-1","sourceUrl":"https://software.nasa.gov/software/ARC-16053-1","confidence":"high"},"type":"software","title":"SequenceMiner-Anomaly Detection in Large Sets of High-Dimensional Symbol Sequences","abstract":"SequenceMiner was developed to address the problem of detecting and describing anomalies in large sets of high-dimensional symbol sequences. The technology performs unsupervised clustering (grouping) of sequences using the normalized longest common subsequence (LCS) as a similarity measure, followed by a detailed analysis of outliers to detect anomalies. SequenceMiner utilizes a new hybrid algorithm for computing the LCS that has been shown to outperform existing algorithms by a factor of five.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://ti.arc.nasa.gov/opensource/projects/sequenceminer/","license":null}},{"forgeId":"forge_nasa_arc_16070_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16070-1","sourceUrl":"https://software.nasa.gov/software/ARC-16070-1","confidence":"high"},"type":"software","title":"Mariana: Text Classification System","abstract":"Mariana is an algorithm that efficiently optimizes the hyperparameters for support vector machines for regression and classification. It currently uses simulated annealing for optimization but can be extended to use a variety of stochastic optimization techniques, including Markov Chain Monte Carlo, Sequential Monte Carlo, and genetic algorithms.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://ti.arc.nasa.gov/opensource/projects/mariana/","license":null}},{"forgeId":"forge_nasa_arc_16088_1a","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16088-1A","sourceUrl":"https://software.nasa.gov/software/ARC-16088-1A","confidence":"high"},"type":"software","title":"GeoCam, Version 2","abstract":"GeoCam is a geospatial system for disaster response that consists of (1) low-cost consumer hardware (i.e., a digital camera or cell phone, position/orientation sensors, and an optional embedded controller) and (2) a Web-based workflow that enables images and other geo-referenced data to be shared and viewed in a variety of ways. GeoCam includes software that computes image location and provides for geo-rectification, KML-formatted geospatial data generation, image management, and geo-referenced data sharing.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://github.com/geocam","license":null}},{"forgeId":"forge_nasa_arc_16119_1b","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16119-1B","sourceUrl":"https://software.nasa.gov/software/ARC-16119-1B","confidence":"high"},"type":"software","title":"Netmark eXtensible DataBase, Data Access and Retrieval Composition (XDB3-DARC)","abstract":"This innovation will query using a suite of operators in the Netmark/XDB query language to retrieve elements based on the absolute value of tags in the XML source. In an earlier version of the software, element retrieval was based solely on \"full-text\" term searches of the tags and their values.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://sourceforge.net/projects/darcxdb3/","license":null}},{"forgeId":"forge_nasa_arc_16186_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16186-1","sourceUrl":"https://software.nasa.gov/software/ARC-16186-1","confidence":"high"},"type":"software","title":"Savors: A Scalable Aural-Visual Environment for Security Event Monitoring, Analysis , And Response","abstract":"Savors is a tool for security event monitoring, analysis , and response. The technology scales to real-world environments and uses high-end computing resources on-demand to compile behavior profiles that point to anomalous behavior. Auralization allows both monitoring and analysis to be performed in parallel and draws attention to critical events in one tool when utilizing another. Remote data access and response capabilities across distributed resources are enabled using grid computing that provides a secure, single sign-on environment.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://pkolano.github.io/projects/savors.html","license":null}},{"forgeId":"forge_nasa_arc_16197_1a","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16197-1A","sourceUrl":"https://software.nasa.gov/software/ARC-16197-1A","confidence":"high"},"type":"software","title":"Terrestrial Observation and Prediction System (TOPS) Biogeochemical cycle (BGC) model","abstract":"The Terrestrial Observation and Prediction System (TOPS) is a modeling software that integrates data from satellites, weather stations, climate models with ecosystem models to produce nowcasts and forecasts of ecological conditions. The key tools used in producing the nowcasts and forecasts are simulation models including biogeochemical and ecosystem models that estimate the states (vegetation leaf area, biomass, soil moisture, snow, etc.) and functions (evapotranspiration, photosynthesis, etc.) of various kinds of plant canopies (forests, crops, grass, shrubs). These ecological nowcasts and forecasts are akin to current and forecast weather conditions. Upon further refinement and testing, the ecological nowcasts and forecasts are useful for making a variety of management decisions such as irrigation scheduling, timing of field operations, preparing for floods/droughts, vector-borne diseases, crop phenology and production.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_16276_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16276-1","sourceUrl":"https://software.nasa.gov/software/ARC-16276-1","confidence":"high"},"type":"software","title":"AutoBayes: Automatic Design of Customized Analysis Algorithms and Programs","abstract":"AutoBayes uses extended Bayesian networks, a powerful symbolic system, and algorithm schemas to automatically generate efficient and customized programs for data analysis . It generates a standardized design document containing a graphical representation of the Bayesian network and of the details regarding the code's generation.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://ti.arc.nasa.gov/opensource/projects/autobayes","license":null}},{"forgeId":"forge_nasa_arc_16295_1a","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16295-1A","sourceUrl":"https://software.nasa.gov/software/ARC-16295-1A","confidence":"high"},"type":"software","title":"Portable Environment for Quick Image Processing (QuIP)","abstract":"The QuIP interpreter, a software environment for QUick image processing, uses an interactive scripting language designed to facilitate use by non-expert users, through features such as context-sensitive automatic response completion and integrated documentation. The package includes a number of script packages that implement high-, medium-, and low-level functions (e.g., analysis of eye images for human gaze tracking, feature tracking, and image filtering). The environment also includes facilities for displaying images on screen, drawing and overlaying graphics, and constructing graphical user interfaces using the scripting language. Currently supported platforms are *NIX (tested on Mac OS X and Linux), and Apple iOS.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/QuIP","license":null}},{"forgeId":"forge_nasa_arc_16332_1a","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16332-1A","sourceUrl":"https://software.nasa.gov/software/ARC-16332-1A","confidence":"high"},"type":"software","title":"Kepler Science Data Processing Pipeline","abstract":"The Data Processing Pipeline is a central element of the Kepler Ground Data System. The Science Processing Pipeline is used to analyze stellar photometric data from the Kepler spacecraft and report results to search for planets within the Kepler photometric dataset. The software data release is to allow the scientific community access to the details of the software algorithms within the Science Processing Pipeline. The pipeline performs pixel-level calibration, photometric analysis , systematic error correction, transiting planet detection, modeling and diagnostic testing of potential transit signatures, attitude determination, stellar target management, and monitoring of instrument health and performance.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/kepler-pipeline","license":null}},{"forgeId":"forge_nasa_arc_16332_1b","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16332-1B","sourceUrl":"https://software.nasa.gov/software/ARC-16332-1B","confidence":"high"},"type":"software","title":"Ziggy, a Pipeline Management System for Data Analysis Pipelines","abstract":"Ziggy is a software tool that manages complex data analysis pipelines for science missions. It provides marshaling and persisting services for each algorithm step, sequencing for algorithm steps, monitoring, logging, resource management, and exception handling for all stages of data processing. Ziggy provides the ability to select either local processing or processing on the NASA Advanced Supercomputer (NAS); pipelines can contain a mix of algorithms that run locally and others that run on NAS. Data accountability is provided at all stages of processing: for any given data product produced at any stage, a permanent record is saved regarding which software version was used, what parameters and inputs were provided to the algorithm, and much more. Ziggy can run on computers running macOS or Linux. It supports algorithms written in Python, C++, MATLAB, or Java, and additional language support can be added with just a few lines of code.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/ziggy","license":null}},{"forgeId":"forge_nasa_arc_16341_1a","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16341-1A","sourceUrl":"https://software.nasa.gov/software/ARC-16341-1A","confidence":"high"},"type":"software","title":"Neo-Geography Toolkit (NGT), Version 2","abstract":"NGT is a collection of automated processing tools that can transform raw geospatial raster data from remote sensing instruments into useful cartographic products, including visible image base maps and topographic models.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/neogeographytoolkit/stereopipeline","license":null}},{"forgeId":"forge_nasa_arc_16368_1a","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16368-1A","sourceUrl":"https://software.nasa.gov/software/ARC-16368-1A","confidence":"high"},"type":"software","title":"Robot Application Programming Interface Delegate (RAPID), Version 2","abstract":"RAPID is a software reference implementation framework for remote operations. The technology promotes interoperability between robot software modules and includes a standard programming interface and data distribution middleware. RAPID facilitates integration of experimental robot software modules created by a distributed development team; improves the compatibility and reusability of robotic functions; and offers speed prototype robot development in a wide range of configurations and environments.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://sourceforge.net/projects/robotapi/","license":null}},{"forgeId":"forge_nasa_arc_16443_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16443-1","sourceUrl":"https://software.nasa.gov/software/ARC-16443-1","confidence":"high"},"type":"software","title":"Ballast: Balancing Load Across Systems","abstract":"Ballast is a tool for balancing user load across Secure Shell Handler (SSH) servers. The system includes a load-balancing client, a lightweight data server, scripts for collecting system load, and scripts for analyzing user behavior. Because Ballast is invoked as part of the SSH login process, it has access to user names. This capability, which is not available in traditional approaches, enables Ballast to perform user-specific load balancing. In addition, Ballast is easy to install, induces near-zero overhead, and has fault-tolerant features in its architectures that will eliminate single points of failure.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://pkolano.github.io/projects/ballast.html","license":null}},{"forgeId":"forge_nasa_arc_16445_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16445-1","sourceUrl":"https://software.nasa.gov/software/ARC-16445-1","confidence":"high"},"type":"software","title":"Synchronization, Archival, Validation, and IP Exchange (Save)","abstract":"Save is a high-availability framework that manages IP addresses shared between multiple servers. It also monitors the health of those servers to determine which one should be actively servicing requests at any given time. Synchronization mechanisms allow configuration files to be kept consistent between systems and also allow commands to be executed across all servers of a particular type. Archival mechanisms provide automatic version control of configuration files to aid in recovery in case of errant configuration.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://pkolano.github.io/projects/save.html","license":null}},{"forgeId":"forge_nasa_arc_16457_1a","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16457-1A","sourceUrl":"https://software.nasa.gov/software/ARC-16457-1A","confidence":"high"},"type":"software","title":"Visual Environment for Remote Virtual Exploration (VERVE), Version 2","abstract":"VERVE is a 3D visualization system that provides situational awareness, science analysis tools, and data understanding capabilities for robotics researchers and exploration science operations. The technology is highly modular and extensible and includes a 3D scene-graph database, an interactive 3D viewer, and associated graphical user interfaces to OSGI plugin-based applications.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://sourceforge.net/projects/irg-verve","license":null}},{"forgeId":"forge_nasa_arc_16462_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16462-1","sourceUrl":"https://software.nasa.gov/software/ARC-16462-1","confidence":"high"},"type":"software","title":"Multiple Kernel Anomaly Detection (MKAD) Algorithm","abstract":"In offline mode, MKAD performs automated anomaly detection on large heterogeneous data sets that contain both discrete symbols and continuous data streams.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://ti.arc.nasa.gov/opensource/projects/mkad/","license":null}},{"forgeId":"forge_nasa_arc_16561_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16561-1","sourceUrl":"https://software.nasa.gov/software/ARC-16561-1","confidence":"high"},"type":"software","title":"Optimal Alarm System Design and Implementation","abstract":"The innovation described herein is an alarm system that can robustly predict a level-crossing event that is specified over a fixed prediction horizon. Given a specific modeling paradigm that can be learned using appropriate data-driven or machine learning techniques, an optimal alarm system can be designed to elicit the fewest false alarms for a fixed detection probability. When the modeling paradigm is a simple stationary linear dynamic system driven by white Gaussian noise, it is easy to use the well-known Kalman filter to enable value prediction of future process values. During implementation, these value predictions can subsequently be used to enable the prediction of associated level-crossing events that may occur in the future, using a parameter that was selected to achieve robustly optimal performance during the alarm system design stage.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://ti.arc.nasa.gov/opensource/projects/optimalalarm/","license":null}},{"forgeId":"forge_nasa_arc_16680_1a","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16680-1A","sourceUrl":"https://software.nasa.gov/software/ARC-16680-1A","confidence":"high"},"type":"software","title":"Porous material Analysis Toolbox based on OpenFoam (PATO)","abstract":"The Porous material Analysis Toolbox (PATO) is a modular analysis platform for multiphase porous reactive materials. It can be run as a simple Fourier heat transfer code or include more advanced features as internal decomposition (pyrolysis, vaporization), gas-gas and gas-solid chemical interactions (combustion, cracking, coking), gas species transport (convection, diffusion), and solid morphology evolutions (internal density changes, surface ablation).PATO is implemented as a C top level module of the open source (GNU GPL) computational fluid dynamics software program OpenFOAM. This offering is not approved or endorsed by OpenCFD Limited, the producer of the OpenFOAM software and owner of the OPENFOAM and OpenCFD trademarks. PATO also uses the open source (GNU LGPL) thermodynamics, transport, and chemistry library Mutation produced by the von Karman Institute for Fluid Dynamics.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://www.pato.ac","license":null}},{"forgeId":"forge_nasa_arc_16680_1c","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16680-1C","sourceUrl":"https://software.nasa.gov/software/ARC-16680-1C","confidence":"high"},"type":"software","title":"Porous material Analysis Toolbox based on OpenFOAM (PATO)","abstract":"PATO (Porous material Analysis Toolbox based on OpenFOAM) is a modular research and development platform for multiphase porous reactive materials submitted to high-temperature environments or other unusual conditions. It can be run as a simple Fourier heat transfer code or include more advanced features such as internal decomposition (pyrolysis, vaporization), gas-gas and gas-solid chemical interactions (combustion, cracking, coking), gas species transport (convection, diffusion), and solid morphology evolutions (internal density changes, surface ablation). PATO is implemented as a C++ top-level module of the open-source (GNU GPL) Computational Fluid Dynamics software OpenFOAM. This offering is not approved or endorsed by OpenCFD Limited, the producer of the OpenFOAM software and owner of the OPENFOAM and OpenCFD trademarks. PATO also uses the open-source (GNU LGPL) thermodynamics, transport, and chemistry library Mutation++ produced by the von Karman Institute for Fluid Dynamics.","category":"materials_coatings","categoryRaw":"materials and processes","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://pato.ac/","license":null}},{"forgeId":"forge_nasa_arc_16764_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16764-1","sourceUrl":"https://software.nasa.gov/software/ARC-16764-1","confidence":"high"},"type":"software","title":"Network-Form Game Software Library (libnfg)","abstract":"The libnfg software library describes how humans interact with their environment and with other humans. The tool provides a Monte Carlo analysis of user-specified \"network-form games,\" which are flexible modeling methodologies that combine Bayes nets and game theory to model complex systems.","category":"biomedical_health","categoryRaw":"crew and life support","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://ritchielee.net/wp-content/uploads/2015/11/libnfg-snap-1.0.zip","license":null}},{"forgeId":"forge_nasa_arc_16778_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16778-1","sourceUrl":"https://software.nasa.gov/software/ARC-16778-1","confidence":"high"},"type":"software","title":"NetworKing: Space Communications and Navigation (SCaN) App","abstract":"The NetworKing Game is an educational, interactive 3D game in which the player develops a space communication network. As he builds his network infrastructure, client spacecraft are attracted to the network, generating income and allowing the player to build further. As the player expands his robust communication network, fortunate and unfortunate events occur. The game can be downloaded at: http://www.nasa.gov/multimedia/3d_resources/scan.html","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://www.nasa.gov/multimedia/3d_resources/scan.html","license":null}},{"forgeId":"forge_nasa_arc_16789_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16789-1","sourceUrl":"https://software.nasa.gov/software/ARC-16789-1","confidence":"high"},"type":"software","title":"Inference Kernel for Open Static (IKOS) Analyzers: A High-Performance Static Analysis Engine to Build Automated Code Analysis Tools for the Formal Verification of Critical Software Properties","abstract":"IKOS is a kernel for the construction of open-static analyzers based on Patrick Cousot and Radhia Cousot's theory of abstract interpretation, which states that computations can be abstracted and reduced to a generalized set of objects and still exhibit the same critical properties of the parent program. By reducing the set of objects through abstraction, IKOS is scalable to large complex computer programs and presents a sound approach to verification of such programs.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-SW-VnV/ikos","license":null}},{"forgeId":"forge_nasa_arc_16805_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16805-1","sourceUrl":"https://software.nasa.gov/software/ARC-16805-1","confidence":"high"},"type":"software","title":"Kepler Community Data Analysis Tools","abstract":"The Kepler archive contains time-series data calibrated and reduced from detector pixels. The pipelined reduction includes the removal of time-series trends systematic to a spacecraft and its environment.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://keplergo.arc.nasa.gov/PyKE.shtml","license":null}},{"forgeId":"forge_nasa_arc_16839_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16839-1","sourceUrl":"https://software.nasa.gov/software/ARC-16839-1","confidence":"high"},"type":"software","title":"ACCEPT (Adverse Condition & Critical Event Prediction Toolbox)","abstract":"This MATLAB-based source code consists of an overall software infrastructure framework and two main software components. The software infrastructure framework consists of code written to pre-process data , pass information between the two main software components, learn models that will be shared by nearly all of the elements in one of the two software components (which will require calling third party open source software modules), and select which element/method should be used in each one of the two main software components. The two main software components can use interchangeable software elements that enable the regression and detection functionality.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://ti.arc.nasa.gov/opensource/projects/accept/","license":null}},{"forgeId":"forge_nasa_arc_16864_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-16864-1","sourceUrl":"https://software.nasa.gov/software/ARC-16864-1","confidence":"high"},"type":"software","title":"Scalable Gaussian Process Regression","abstract":"Block GP is a Gaussian Process regression framework for multimodal data , that can be an order of magnitude more scalable than existing state-of-the-art nonlinear regression algorithms. The framework builds local Gaussian Processes on semantically meaningful partitions of the data and provides higher prediction accuracy than a single global model with very high confidence. The method relies on approximating the covariance matrix of the entire input space by smaller covariance matrices that can be modeled independently, andcan therefore be parallelized for faster execution.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_17093_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-17093-1","sourceUrl":"https://software.nasa.gov/software/ARC-17093-1","confidence":"high"},"type":"software","title":"NASA Tensegrity Robotics Toolkit (NTRT) v1","abstract":"The NASA Tensegrity Robotics Toolkit (NTRT) is a collection of C++ and MATLAB software modules for the modeling, simulation , and control of Tensegrity Robots. Tensegrity Robots are a biologically inspired approach to building robots based on the tension networks of tensegrity structures, which have no rigid connections between elements. The NTRT was created to enable: the rapid co-exploration of structures and controls in a physics based simulation environment; the development of tensegrity robotics algorithms such as structural analysis, kinematics, and motion planning; and the validation of the algorithms and controls on hardware prototypes of the tensegrity robots.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-Tensegrity-Robotics-Toolkit","license":null}},{"forgeId":"forge_nasa_arc_17174_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-17174-1","sourceUrl":"https://software.nasa.gov/software/ARC-17174-1","confidence":"high"},"type":"software","title":"Exploration Ground Data Systems (xGDS) v1","abstract":"Software to support science operations, including tools for planning, monitoring, visualization , documentation, analysis, and search.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/xgds","license":null}},{"forgeId":"forge_nasa_arc_17451_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-17451-1","sourceUrl":"https://software.nasa.gov/software/ARC-17451-1","confidence":"high"},"type":"software","title":"Inverse Reinforcement Learning (IRL) Augmentation for PyMDPToolbox","abstract":"The software is a augmentation for PyMDPToolbox containing implementations of some new IRL algorithms.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/pymdptoolbox","license":null}},{"forgeId":"forge_nasa_arc_17472_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-17472-1","sourceUrl":"https://software.nasa.gov/software/ARC-17472-1","confidence":"high"},"type":"software","title":"Crisis Mapping Toolkit (CMT) v1","abstract":"The Crisis Mapping Toolkit (CMT) is a collection of tools for processing geospatial data (images, satellite data, etc.) into cartographic products that improve understanding of large-scale crises, such as natural disasters. The cartographic products produced by CMT include flood inundation maps, maps of damaged or destroyed structures, forest fire maps, population density estimates, etc. CMT is designed to rapidly process large-scale data using Google Earth Engine and other geospatial data systems.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/bcoltin/CrisisMappingToolkit","license":null}},{"forgeId":"forge_nasa_arc_17529_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-17529-1","sourceUrl":"https://software.nasa.gov/software/ARC-17529-1","confidence":"high"},"type":"software","title":"ROC (Receiver Operating Characteristic) curve Code Augmentation","abstract":"This release extends existing open source software's capabilities and functionality by bookeeping more detailed information on internal data structures, as well as enhanced error and special condition checking. Additional performance criteria have also been included, such as computing the AUC (Area under the ROC curve), pAUC (partial AUC), and other relevant statistics such as accuracy, confusion matrices, precision, recall, etc.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://ti.arc.nasa.gov/opensource/projects/roc","license":null}},{"forgeId":"forge_nasa_arc_17621_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-17621-1","sourceUrl":"https://software.nasa.gov/software/ARC-17621-1","confidence":"high"},"type":"software","title":"VESsel GENeration Analysis (VESGEN) 2D Software","abstract":"VESGEN maps and quantifies key parameters in black/white images of vascular trees and networks that are important for astronaut and terrestrial pathologies such as inflammation and angiogenesis in diabetes and tumors.","category":"biomedical_health","categoryRaw":"crew and life support","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_17644_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-17644-1","sourceUrl":"https://software.nasa.gov/software/ARC-17644-1","confidence":"high"},"type":"software","title":"PSYCO: A Predicate-based Symbolic Compositional Reasoning environment","abstract":"PSYCO: Predicate-based Symbolic Compositional Reasoning (PSYCO), is a software environment that generates precise Java component interfaces in an automated fashion. These interfaces are state machines that describe legal sequences of method invocations of a component. Guards on method parameters are included in the automata transitions in order to capture more precisely the interface behavior of the component. The novelty of PSYCO is that it is the first software environment to combine symbolic approaches with automata learning. In particular, it uses a technique named concolic execution to compute guards and active automata learning to compute legal sequences of invocations. Concolic execution is a static analysis that executes a program concretely, while computing symbolic constraints and using them to automatically trigger different program behaviors in order to exhaustively explore the input space of a component. Existing concolic test case generation tools handle only very few data types (especially no float types) and no native calls (e.g., native implementation of trigonometric functions) and thus do not scale to industrial (and in particular aerospace) applications. The concolic execution engine in PSYCO (named JDART) overcomes many of these shortcomings. Active automata learning has been used as a dynamic analysis for generating control models of software components. A learning algorithm triggers a variety of executions on a target system, and based on the outcomes, produces models of the component. These models are automatically refined based on counterexamples that demonstrate imprecisions of each proposed model. Concolic execution and active automata learning target two different types of component invariants: data invariants and control invariants. The combination of both allows the formulation of precise interfaces, integrating control and data aspects of components. Existing interface generation tools usually focus on one of these two aspects and do not combine constraints on inputs and outputs with control models.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/psycopaths/psyco","license":null}},{"forgeId":"forge_nasa_arc_17647_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-17647-1","sourceUrl":"https://software.nasa.gov/software/ARC-17647-1","confidence":"high"},"type":"software","title":"Desktop Exploration of Remote Terrain (DERT)","abstract":"Desktop Exploration of Remote Terrain (DERT) is a software tool for exploring large Digital Terrain Models (DTMs) in 3D. It aids in understanding topography and spatial relationships of terrain features, as well as performing simple analysis tasks relevant to the planetary science community.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/DERT","license":null}},{"forgeId":"forge_nasa_arc_17736_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-17736-1","sourceUrl":"https://software.nasa.gov/software/ARC-17736-1","confidence":"high"},"type":"software","title":"Prognostics Model Library","abstract":"The Prognostics Model Library is a modeling framework focused on defining and building models for prognostics (computation of remaining useful life) of engineering systems, and provides a set of prognostics models for select components developed within this framework, suitable for use in prognostics applications for these components. The library currently includes models for valves, pumps, and batteries. The Prognostics Model Library is implemented in MATLAB. The implementation consists of a set of utilities for defining a model (specifying variables, parameters, and equations), simulating the model, and embedding it within common model-based prognostics algorithms. A user can use existing models within the library or construct new models with the provided framework.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/PrognosticsModelLibrary","license":null}},{"forgeId":"forge_nasa_arc_17748_1a","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-17748-1A","sourceUrl":"https://software.nasa.gov/software/ARC-17748-1A","confidence":"high"},"type":"software","title":"Generic Software Architecture for Prognostics (GSAP)","abstract":"The Generic Software Architecture for Prognostics (GSAP) is a generic, extendable, flexible, modular framework for applying prognostics technologies. GSAP manages top-level control , communications, logging, configuration, integration, and other general activities. A simple, standard interface is provided for integrating prognostics algorithms and models, minimizing the work required to deploy prognostics technologies. The standard interface allows for prognosers developed for GSAP to be reused anywhere GSAP is used.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/gsap","license":null}},{"forgeId":"forge_nasa_arc_17874_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-17874-1","sourceUrl":"https://software.nasa.gov/software/ARC-17874-1","confidence":"high"},"type":"software","title":"MAV - Modeling, analysis and visualization of ATM concepts","abstract":"A modeling and analysis framework that provides the ability to model humans, automation, the interactions between humans and between humans and automation for air traffic management and airspace design concepts.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/MAV","license":null}},{"forgeId":"forge_nasa_arc_17900_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-17900-1","sourceUrl":"https://software.nasa.gov/software/ARC-17900-1","confidence":"high"},"type":"software","title":"Simulation of Cryogenic Tank with Temperature Stratification","abstract":"\" Simulation of Cryogenic Tank with Temperature Stratification\" is a MATLAB-based simulation of temperature stratification effects for cryogenic fluid in a tank. It is a reduced dynamical model describing temperature stratification effects driven by natural convection in a liquid hydrogen cryogenic tank. It accounts for storage, loading, and unloading of cryogenic fluid.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/LH2Sim","license":null}},{"forgeId":"forge_nasa_arc_17920_1a","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-17920-1A","sourceUrl":"https://software.nasa.gov/software/ARC-17920-1A","confidence":"high"},"type":"software","title":"Porous Microstructure Analysis (PuMA)","abstract":"The Porous Microstructure Analysis (PuMA) software has been developed in order to compute effective material properties and perform material response simulations on digitized microstructures of porous media. PuMA is able to import digital three-dimensional images obtained from X-ray microtomography or to generate artificial microstructures that mimic real materials. PuMA also provides a module for interactive 3D visualizations. Version 3 includes modules to compute simple morphological properties such as porosity, volume fractions, pore diameter, and specific surface area. Additional capabilities include the determination of effective thermal and electrical conductivity (including the ability to simulate local anisotropy), effective diffusivity and tortuosity from the continuum to the rarefied regime, and techniques to determine local material orientation.","category":"materials_coatings","categoryRaw":"materials and processes","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/puma","license":null}},{"forgeId":"forge_nasa_arc_17943_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-17943-1","sourceUrl":"https://software.nasa.gov/software/ARC-17943-1","confidence":"high"},"type":"software","title":"GeoRef v1","abstract":"GeoRef is a Web-based software application designed to increase the efficiency and precision in geo-locating photographs taken by astronauts from the International Space Station. GeoRef provides highly automated processes for: (1) calculating the latitude and longitude coordinates of the center point of the image , and (2) producing geo-referenced map overlays for the image . The georeferenced images produced by GeoRef are designed to support the needs of educational, Earth science, and disaster response users.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/georef","license":null}},{"forgeId":"forge_nasa_arc_17979_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-17979-1","sourceUrl":"https://software.nasa.gov/software/ARC-17979-1","confidence":"high"},"type":"software","title":"KeplerPORTs (Kepler Planet Occurrence Rate Tools)","abstract":"KeplerPORTS (Kepler Planet Occurrence Rate Tools ) is a software tool that illustrates the use of Kepler's planet occurrence rate data products by generating contour plots for s elected s ample files .NASA acknowledges the SETI Institutes primary role in authoring and producing the KeplerPORTs (Kepler Planet Occurrence Rate Tools) under Cooperative Agreement Number NNX13AD01A.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/KeplerPORTs","license":null}},{"forgeId":"forge_nasa_arc_17980_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-17980-1","sourceUrl":"https://software.nasa.gov/software/ARC-17980-1","confidence":"high"},"type":"software","title":"Plotting Program for Kepler Planet Detection Efficiency Products","abstract":"The Kepler Plotting Program was developed as an aid to understanding the publicly available data files that have been released by the Kepler project. This tool allows end users to reproduce plots used in project documentation, facilitates the user's scientific understanding and promotes the utilization of the Kepler science data products .NASA acknowledges the SETI Institutes primary role in authoring and producing the Plotting Program for Kepler Planet Detection Efficiency Products under Cooperative Agreement Number NNX13AD01A","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/Kepler-FLT","license":null}},{"forgeId":"forge_nasa_arc_17981_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-17981-1","sourceUrl":"https://software.nasa.gov/software/ARC-17981-1","confidence":"high"},"type":"software","title":"Kepler Robovetter","abstract":"The Kepler mission observed approximately 200,000 stars for four years and identified over 34,000 transit-like events. The Kepler Robovetter translates the logic used to discriminate between \"likely planet candidates\" and \"false positives\" and automates the evaluation of large Kepler data sets which are available at the public archive. The expected audience is active astronomers in the scientific community.NASA acknowledges the SETI Institutes primary role in authoring and producing the Kepler Robovetter under Cooperative Agreement Number NNX13AD01A.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/kepler-robovetter","license":null}},{"forgeId":"forge_nasa_arc_17994_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-17994-1","sourceUrl":"https://software.nasa.gov/software/ARC-17994-1","confidence":"high"},"type":"software","title":"Astrobee Robot Software (ARS) v1","abstract":"Astrobee is a free-flying robot that is designed to operate as a payload inside the International Space Station (ISS). The Astrobee Robot Software (ARS) consists of the embedded (on-board) software and simulator. ARS operates on Astrobees three internal computers and uses the open-source Robot Operating System (ROS) framework to link multiple software modules. ARS performs localization and navigation of Astrobee, supports autonomous docking and perching, manages various sensors and actuators, and supports user interaction (via screen-based displays, light signaling, and sound). ARS enables Astrobee to operated in multiple modes: plan-based task execution (command sequencing), teleoperation, or guest science. The simulator allows software simulation of Astrobee mobility without requiring any robot hardware.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/astrobee","license":null}},{"forgeId":"forge_nasa_arc_18001_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18001-1","sourceUrl":"https://software.nasa.gov/software/ARC-18001-1","confidence":"high"},"type":"software","title":"Virtual ADAPT","abstract":"Virtual ADAPT is a MATLAB/Simulink simulation of the Advanced Diagnostics and Prognostics Testbed (ADAPT) located at NASA Ames Research Center. ADAPT is an electrical power system testbed that emulates the power distribution systems on spacecraft. It allows users to inject faults, in order to study how faults affect the operation of the electrical power system, and to evaluate automated diagnostics technologies. Virtual ADAPT provides a high-fidelity simulation of this capability. It includes dynamic models of all the components of ADAPT and enables all faults that can be injected into the actual testbed to be injected into the simulation , including some that would be difficult or unsafe to do in the actual hardware. In this way, simulated fault scenarios can be quickly generated under many possible conditions, generating simulated data that closely matches what the behavior of the actual testbed would be. This simulated data can then be used for diagnostics algorithm development and testing, before testing on the actual hardware or deploying to a real application.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/VirtualADAPT","license":null}},{"forgeId":"forge_nasa_arc_18051_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18051-1","sourceUrl":"https://software.nasa.gov/software/ARC-18051-1","confidence":"high"},"type":"software","title":"Autonomous Operating System - Diagnostic Reasoner","abstract":"Diagnostic Reasoner (DR) is a research tool which uses a dependency matrix (D-matrix) approach to perform diagnosis on a target system. It is a app designed to run with NASA's Core Flight Software (cFS) system. DR uses a model-based approach to diagnosis, and will provide runtime fault detection and fault identification of systems.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/aos-dr","license":null}},{"forgeId":"forge_nasa_arc_18117_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18117-1","sourceUrl":"https://software.nasa.gov/software/ARC-18117-1","confidence":"high"},"type":"software","title":"Fep Extensible Proxy (FEP)","abstract":"The Fep Extensible Proxy (FEP) is a communication framework that provides abstract message conversion from multiple plug-in micro-services. FEP implements both a publish-subscribe and streaming data flow models to support real-time data visualization and validation as well as to facilitate post-processing and data analysis. Web interfaces are also provided through FEP to control, configure, and monitor the status of micro-services and clients. The FEP provides flexibility and scalability through the ability to daisy-chain multiple instances together or link via warehouse storage.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/gflarc/fep","license":null}},{"forgeId":"forge_nasa_arc_18132_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18132-1","sourceUrl":"https://software.nasa.gov/software/ARC-18132-1","confidence":"high"},"type":"software","title":"Wikimoji - the Internet of Management Things (IoMT)","abstract":"Wikimoji - The Internet of Management Things (IoMT) are enhancements to the NASA ARC Context Based Configuration Management System (CBCMS) invention, Patent Grant US7672969 B1. IoMT fills the gap between the Industrial Internet of Things (IIoT) and the consumer Internet of Things (IoT), by covering the critical human elements and organizational gaps that help manage, navigate and control systems of systems. It expands the CBCMS objects by dynamically giving them wiki-page like features as theyre shared in E-mails, or PowerPoint briefings, or Excel Worksheets, or Microsoft Word documents or linked to other entities. Furthermore, these Wikimojis: Wiki + Emoji (configuration and management icons of standard business operations -> Emoji portion plus the automatic communications, configuration, management tracking blog/link type entries for any Microsoft .Net API based interactions or links to other Wikimojis -> Wiki portion) allow for efficient tracking, from informal to formal configuration management levels, of key organizational and management activities in regards to business operations and integration of systems of systems (including IIoT and IoT). Wikimojis can be grouped into channels that have a common association points or topics. Lastly Wikimojis can be set to autonomously conduct data mining/information crawling on targeted information systems (the Internet, corporate clouds, organizational e-mail systems, etc.) searching for related events, discussions, and/or data points, making links as appropriate and become a living data entity reaching its full potential as an Internet of Management Thing. IoMT covers a crucial aspect of daily complex system operations by capturing the human and organizational elements, decisions, intent and feedback that today are haphazardly captured in non-systematic ways or not captured at all.Additionally, the quality and range of icons have been expanded substantially forming an ontology of management functions packaged into an online drag and drop library for ease of use.","category":"operations","categoryRaw":"business systems and project management","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_18212_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18212-1","sourceUrl":"https://software.nasa.gov/software/ARC-18212-1","confidence":"high"},"type":"software","title":"Physical Scalars and Plotting Tools in Scala","abstract":"An open-source scalar package and associated software tools have been developed in the Scala programming language, including plotting tools based on the free GRACE plotting package. The scalar package represents physical scalars and can help to prevent errorsinvolving physical units in engineering and scientific computation. The scalar package includes a complete implementation of the standard SI metric system of units and many common non-metric units. The design also allows users to easily define a specialized or reduced set of physical units for any particular application or domain. The scalar package can be used in two different modes: one mode provides unit compatibility checking but is slower, and the other mode bypasses the compatibility checks but is much faster and still prevents the most common type of unit error. Switching between the two modes requires no changes in the user's code, making it convenient and usable with no significant performance penalty for even the most computationally intensive applications.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/RussP/scalars","license":null}},{"forgeId":"forge_nasa_arc_18229_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18229-1","sourceUrl":"https://software.nasa.gov/software/ARC-18229-1","confidence":"high"},"type":"software","title":"MESA: Message-Based System Analysis","abstract":"MESA, which stands for MEssage-based System Analysis , is a framework that provides runtime verification of large distributed systems in a nonintrusive manner. It checks a trace of the system under test against properties of interest, and if a property is violated, it issues an error along with a counter example. A trace is a sequence of messages entailing information about a run of the system. MESA leverages RACE, which is a platform for instantiating and running highly concurrent and distributed systems, to provide connectivity to and retrieve information from the system under test. Using existing domain specific languages, TraceContrance and Daut, It allows for formal specification of properties in state machines and linear temporal logic formulas. MESA is written in Scala, and employs the actor programming model, as implemented in the Akka framework. Finally, using asynchronous communicating actors to capture properties of interest, it allows for decentralized monitoring of the system.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-SW-VnV/mesa","license":null}},{"forgeId":"forge_nasa_arc_18270_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18270-1","sourceUrl":"https://software.nasa.gov/software/ARC-18270-1","confidence":"high"},"type":"software","title":"MiniWall - Data Visualization Web Browser Application","abstract":"The MiniWall software is browser based software that is used to analyze and understand large and small computationally and experimentally generated data sets. The MiniWall software presents a matrix view of plots and other visualization images and provides a responsive and productive way to investigate the data and extract knowledge and understanding from it. Since it is browser based, it runs on any computer or device that can display a web page. It can also be used remotely and securely by using web server software such as the Apache HTTP Server.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/MiniWall","license":null}},{"forgeId":"forge_nasa_arc_18277_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18277-1","sourceUrl":"https://software.nasa.gov/software/ARC-18277-1","confidence":"high"},"type":"software","title":"CoCoSim: Simulink Verification Framework","abstract":"CoCoSim is a framework that integrates analysis technologies for verifying and validating Simulink and Stateflow models. CoCoSim can be used to automatically perform test case generation and to evaluate the validity of user-supplied safety requirements. CoCoSim can also be used to generate C and/or Rust code from Simulink or Stateflow models. The main use of CoCoSim is to provide verification and validation of Simulink or Stateflow programs. CoCoSim is structured to operate much like a compiler, sequencing a series of translation steps leading, eventually to either the production of source code, or to the call of a verification tool. CoCoSim allows users to express safety properties as synchronous observers within the Simulink model or StateFlow Diagram. Synchronous observers are code segments that implement assume-guarantee reasoning by taking state variables as inputs and then producing one or more Boolean outputs indicating if the observer agrees with the behavior of the model.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-SW-VnV/CoCoSim","license":null}},{"forgeId":"forge_nasa_arc_18415_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18415-1","sourceUrl":"https://software.nasa.gov/software/ARC-18415-1","confidence":"high"},"type":"software","title":"Kepler/K2 Cadence Events (K2CE)","abstract":"Kepler K2 Cadence Events (K2CE) is a data visualization / manipulation Python application which runs on publicly available data from the NASA Kepler, K2, and TESS missions to produce annotated light curve plots and, optionally, filtered versions of the input data files.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/K2CE","license":null}},{"forgeId":"forge_nasa_arc_18446_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18446-1","sourceUrl":"https://software.nasa.gov/software/ARC-18446-1","confidence":"high"},"type":"software","title":"DELTA (Deep Earth Learning, Tools, and Analysis )","abstract":"DELTA is a toolkit for applying deep learning to satellite imagery. Scientists label training imagery on a supported satellite, and the toolkit learns a deep neural network to address the problem. DELTA makes use of pre-trained autoencoders on supported satellites to jump-start training through a learned compressed representation of the data source. DELTA will be applied initially to flood mapping, as a component of the open source Crisis Mapping Toolkit.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/delta","license":null}},{"forgeId":"forge_nasa_arc_18500_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18500-1","sourceUrl":"https://software.nasa.gov/software/ARC-18500-1","confidence":"high"},"type":"software","title":"NASA NeMO-Net, the Neural Multi-Modal Observation & Training Network","abstract":"NeMO-Net is a convolutional neural network (CNN) designed for marine ecosystem classification. The CNN takes as input 2D satellite and drone images as well as 3D reconstructions of underwater environments and generates classification maps for those environments as output. These classification maps can be used to better understand and protect coral reefs globally.One component of NeMO-Net is a citizen science game for mobile devices and personal computers. Through playing this game, players help NASA classify coral reefs and other aquatic ecosystems by painting on 2D and 3D images of coral. Players can rate the classifications of other players and level up in the food chain as they explore and classify coral reefs, other shallow marine environments, and creatures from locations all over the world. The application educates players on how to identify the different types of coral and player classifications are used to train the CNN to classify aquatic ecosystems autonomously.More Info can be found at www.nemonet.info","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"http://nemonet.info/","license":null}},{"forgeId":"forge_nasa_arc_18547_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18547-1","sourceUrl":"https://software.nasa.gov/software/ARC-18547-1","confidence":"high"},"type":"software","title":"NASA Ames Legacy Mars Global Climate Model","abstract":"We present the NASA Ames Legacy Mars Global Climate Model for public release. This model uses a modified version of the ARIES/GEOS dynamical core coupled with a set of Mars physics packages to simulate the martian climate. The physics packages include the treatment of surface properties, a ground temperature model, a planetary boundary layer scheme, water and carbon dioxide sublimation/condensation physics, a water ice cloud microphysical scheme, the use of a moment method for tracer transport, a semi-interactive dust tracking scheme, and a two-stream radiative transfer code based on correlated-ks.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/legacy-mars-global-climate-model","license":null}},{"forgeId":"forge_nasa_arc_18548_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18548-1","sourceUrl":"https://software.nasa.gov/software/ARC-18548-1","confidence":"high"},"type":"software","title":"Ocean Worlds Autonomy Testbed for Exploration Research and Simulation","abstract":"The OceanWATERS software is a simulation environment for research and development of on-board autonomy software for scientific lander missions to the \"ocean worlds\" of our solar system: the moons harboring large quantities of liquids, such as Europa, Enceladus, and Titan. The proposed \"Europa Lander\" mission was chosen as a reference design to inform the development of the simulator.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/ow_simulator","license":null}},{"forgeId":"forge_nasa_arc_18618_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18618-1","sourceUrl":"https://software.nasa.gov/software/ARC-18618-1","confidence":"high"},"type":"software","title":"SimuPy Flight Vehicle Toolkit","abstract":"This software library leverages open source scientific computing tools to implement an efficient simulation framework for flight vehicles in Python. Equations of motion are composed in blocks using the SimuPy library, an open source Python alternative to Simulink, and integrated using SciPys wrappers for standard Fortran implementations of ordinary differential equation solvers. Dynamics equations of the inertial state variables for the position, orientation, and their corresponding rates for integration are developed using the SymPy symbolic library and implemented using code generation. Kinematics equations are implemented through symbolic definition and code generation as well as leveraging other open source software that implements useful functions, such as the solutions to the inverse geodesy problem.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_18634_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18634-1","sourceUrl":"https://software.nasa.gov/software/ARC-18634-1","confidence":"high"},"type":"software","title":"Python Prognostics Model Package","abstract":"The Prognostic Model Package is a python modeling framework focused on defining and building models for prognostics (computation of remaining useful life) of engineering systems, and provides a set of prognostics models for select components developed within this framework.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/prog_models","license":null}},{"forgeId":"forge_nasa_arc_18677_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18677-1","sourceUrl":"https://software.nasa.gov/software/ARC-18677-1","confidence":"high"},"type":"software","title":"GeneLab Amplicon and Metagenomics Data Processing Pipelines","abstract":"This technology details each step in GeneLab's standard pipelines for processing Amplicon and Metagenomics sequence data . These processing protocols have been wrapped into Snakemake workflows that utilize Conda environments. Instructions for installing and implementing these Snakemake workflows are included along with example processed datasets.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/GeneLab_Data_Processing","license":null}},{"forgeId":"forge_nasa_arc_18710_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18710-1","sourceUrl":"https://software.nasa.gov/software/ARC-18710-1","confidence":"high"},"type":"software","title":"NASA Ames Mars Global Climate Model","abstract":"We present the NASA Ames Mars Global Climate Model (NASA Ames MGCM) physics submodule for public release. This submodule is intended to work with the Finite-Volume dynamical core and cubed-sphere grid (FV3) developed by NOAA/GFDL and includes several of the Mars physics packages employed by the NASA Ames Legacy Mars Global Climate Model to simulate the Martian climate. The physics packages include: model surface properties such as thermal inertia and albedo; a ground and subsurface temperature scheme; a planetary boundary layer (PBL) scheme; water and carbon dioxide sublimation/condensation physics; a 2-moment dust and water-ice cloud microphysical scheme; several methods for the treatment of dust including an analytically prescribed dust field, dust lifting matched to a prescribed map, and fully-interactive lifting; and a two-stream radiative transfer code based on correlated-Ks.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/AmesGCM","license":null}},{"forgeId":"forge_nasa_arc_18739_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18739-1","sourceUrl":"https://software.nasa.gov/software/ARC-18739-1","confidence":"high"},"type":"software","title":"Agent-Based Model for Microbial Populations Exposed to Radiation (AMMPER)","abstract":"Agent-Based Model for Microbial Populations Exposed to Radiation (AMMPER) simulates the effects of proton-based galactic cosmic radiation (GCR) on Saccharomyces cerevisiae population growth. Through the implementation of data generated from Relativistic Ion Tracks (RITRACKS), a radiation traversal track structure simulator, the amount and severity of radiation-induced damage can be calculated and used to determine the continued viability of individual cells. Through the implementation of this model, the effects of deep-space radiation on entire microbial populations can be predicted and used to assist in designing biological missions for the deep-space environment.","category":"biomedical_health","categoryRaw":"crew and life support","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/AMMPER","license":null}},{"forgeId":"forge_nasa_arc_18750_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18750-1","sourceUrl":"https://software.nasa.gov/software/ARC-18750-1","confidence":"high"},"type":"software","title":"fmdtools","abstract":"Fmdtools is a Python toolkit for simulating the dynamic effects of hazardous scenarios in complex engineered systems and analyzing the associated resilience of the system. To support early design work, fmdtools uses a function-based representation which can evolve as the concept increases in fidelity, enabling network-based, static, and dynamic behavioral representations of the system. This function-based representation additionally enables conduction early functional hazard assessment (FHA) processes in simulation , thus enabling an iterative design process that can explore and systematically compare the resilience of a wide range of designs.ere are three main components of the fmdtools package: (1) Model definition constructs which enable systematic early specification of the high level structure and behaviors of a system with concise syntax. (2) Simulation methods which enable the quantification of system performance and propagation of hazards over a wide range of operational scenarios over a wide range of model types. (3) Analysis methods for quantifying resilience and summarizing and visualizing behaviors and properties of interest. Put together, these components comprise a design, simulation , and analysis environment which can be used consider the resilience of a system of interest in the design process.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/fmdtools","license":null}},{"forgeId":"forge_nasa_arc_18750_1a","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18750-1A","sourceUrl":"https://software.nasa.gov/software/ARC-18750-1A","confidence":"high"},"type":"software","title":"Fault Model Design tools - fmdtools version 2","abstract":"Fmdtools is a Python toolkit for simulating the dynamic effects of hazardous scenarios in complex engineered systems and analyzing the associated resilience of the system. To support early design work, fmdtools uses a high-level representation of the system which can evolve as the concept increases in fidelity. This high-level representation additionally enables the iterative support of early design hazard analysis, along with an iterative design process that can explore and systematically compare the resilience of a wide range of designs. There are three main components of the fmdtools package: (1) Model definition constructs which enable systematic early specification of the high level structure and behaviors of a system with concise syntax. (2) Simulation methods which enable the quantification of system performance and propagation of hazards over a wide range of operational scenarios over a wide range of model types. (3) Analysis methods for quantifying resilience and summarizing and visualizing behaviors and properties of interest. Put together, these components comprise a design, simulation , and analysis environment which can be used consider the resilience of a system of interest in the design process. The 2.0 version of fmdtools brings the following new features:(1)Modelling constructs which enable the representation of complex engineered systems, including human operators, environmental dynamics, systems-of-systems interactions, communications and distributed situation awareness. (2)The development of flexible modelling, simulation , and analysis constructs which enable the simulation of hazards at an individual function/component level and at the system level for the purpose of unit and integration tests/analyses.(3)Ability to modify and search model parameters and states (before and within the simulation ) which may increase system resilience or drive the system to failure.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/fmdtools","license":null}},{"forgeId":"forge_nasa_arc_18808_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18808-1","sourceUrl":"https://software.nasa.gov/software/ARC-18808-1","confidence":"high"},"type":"software","title":"DNN-Prophecy","abstract":"DNN-Prophecy: A Tool-set for ensuring that autonomous systems that use Deep Neural Networks (DNN) are safe, robust and interpretable.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/safednn-nasa/DNN-Prophecy","license":null}},{"forgeId":"forge_nasa_arc_18837_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18837-1","sourceUrl":"https://software.nasa.gov/software/ARC-18837-1","confidence":"high"},"type":"software","title":"arcjetCV","abstract":"arcjetCV is a software application developed in Python which processes arc jet test videos to extract time-resolved 2D recession measurements. The application employs convolutional neural net models (Tensorflow/Keras/OpenCV) to provide a generalized edge detection/extraction algorithm. The software provides a basic graphical user interface (PyQt) for viewing the edge detection and plotting the time-dependent recession. The application streamlines and automates the many steps needed to extract recession data from video, enabling extraction of time-resolved recession to be standardized.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/magnus-haw/arcjetCV/","license":null}},{"forgeId":"forge_nasa_arc_18843_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18843-1","sourceUrl":"https://software.nasa.gov/software/ARC-18843-1","confidence":"high"},"type":"software","title":"vipersci","abstract":"This VIPER Science package is software to support the activities of the Volatiles Investigating Polar Exploration Rover (VIPER) Science Team. This software will implement scientific models to convert instrument raw data to useful derived data (but not including any proprietary instrument details). This includes functionality for running the models \"in reverse\" in order to simulate instrument data for tests and mission simulations. This software will enable and support the creation of various geospatial data sets (maps) to help visualize and understand data from the spacecraft. It will also support the creation of PDS4 archive labels and structures for eventual data delivery to the Planetary Data System (PDS).","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NeoGeographyToolkit/vipersci","license":null}},{"forgeId":"forge_nasa_arc_18862_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18862-1","sourceUrl":"https://software.nasa.gov/software/ARC-18862-1","confidence":"high"},"type":"software","title":"GeneLab RNA Sequencing Processing Pipeline and Workflow","abstract":"This technology details each step in GeneLab's standard pipeline for processing RNA sequence (RNAseq) data . This processing pipeline has been wrapped into a Nextflow workflow that utilizes Singularity containers. Instructions for installing and implementing the Nextflow workflow are included.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/GeneLab_Data_Processing/tree/master/RNAseq","license":null}},{"forgeId":"forge_nasa_arc_18869_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18869-1","sourceUrl":"https://software.nasa.gov/software/ARC-18869-1","confidence":"high"},"type":"software","title":"Activity Planning with Resources for the Exploration of Space (APRES)","abstract":"Activity Planning with Resources for the Exploration of Space (APRES) is a mixed-initiative mission planning system for ground operations. APRES has a web-based user interface that is integrated with the Open-source Mission Control Technologies (OpenMCT) system and includes a plan editor, a timeline plan display, a temporal constraint editor, display of the state and numeric chronicles, and a mixed-initiative violation resolution manager. Automation support is supplied by the APRES Service, which includes components that provide the following capabilities:(1) plan simulation , which determines the state and numeric chronicles (values of the model variables over time) and determines when \"processes\" are triggered and terminated based on world states in the execution trace, (2) violation detection of constraints and flight rules encoded in the domain model, as well as of user-created temporal constraints, (3) violation resolution suggestions as to how to fix the plan's violations. The user controls when and how to utilize the automation support.The APRES Service components are based on the Action Notation Modeling Language (ANML) which is a highly expressive, powerful language for specification of domain models. ANML enables the specification of an extensive variety of flight rules and resource usage (e.g., one can represent continuous effects). In addition to action definitions, ANML models can include definitions of \"processes\", which are not under the control of the agent or human planner, e.g., the operation of a survival heater that is powered on and off based on the current temperature. Integrated with the APRES system is a web-based ANML Editor for creating, editing, and debugging domain models. The ANML Editor interacts with the ANML Parser to detect errors and interacts with the APRES Data Store for file management.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_arc_18893_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18893-1","sourceUrl":"https://software.nasa.gov/software/ARC-18893-1","confidence":"high"},"type":"software","title":"PySA, a powerful tool for solving optimization problems","abstract":"PySA is a powerful tool for solving optimization problems. It uses different numerical techniques (including, for example, parallel-tempering, annealed importance sampling and path-integral monte carlo) and it has been specifically designed to run on HPC clusters. It also offers a user-friendly interface to allowing users with any background to use PySA, without any prior knowledge of high-performance computing.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/pysa","license":null}},{"forgeId":"forge_nasa_arc_18948_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18948-1","sourceUrl":"https://software.nasa.gov/software/ARC-18948-1","confidence":"high"},"type":"software","title":"GeneLab Methylation Sequencing Processing Pipeline and Workflows","abstract":"This technology details each step in GeneLab's standard pipeline for processing Methylation Sequencing (Methyl-Seq) data . These processing pipelines are currently being wrapped into Nextflow workflows that utilize Singularity containers. Instructions for installing and implementing the Nextflow workflows will be added as the workflow is being developed.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/GeneLab_Data_Processing/tree/master/Methyl-Seq","license":null}},{"forgeId":"forge_nasa_arc_18949_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18949-1","sourceUrl":"https://software.nasa.gov/software/ARC-18949-1","confidence":"high"},"type":"software","title":"GeneLab Microarray Processing Pipelines and Workflows","abstract":"This technology details each step in GeneLab's standard pipeline for processing Microarray data derived from different platform types. These processing pipelines have been wrapped into Nextflow workflows that utilize Singularity containers. Instructions for installing and implementing the Nextflow workflows are included.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/GeneLab_Data_Processing/tree/master/Microarray","license":null}},{"forgeId":"forge_nasa_arc_18988_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18988-1","sourceUrl":"https://software.nasa.gov/software/ARC-18988-1","confidence":"high"},"type":"software","title":"Large File Control (LFC)","abstract":"Large File Control (LFC) is an extension to the popular revision control software Git that enables it to work better with large and binary (non-text) files. It works by allowing the user to declare certain files as \"large,\" and then Git only lacks the metadata of that file while LFC handles the actual data in the large file. As a result, users are able to maintain the benefits of modern version control software, such as revision history, reproducibility, asynchronous collaboration, and ease of file transfer without having to download all historical versions of each binary file in the repository. This alleviates one of the major barriers to using Git for more applications outside of software development and especially helps to improve reproducibility in data science, computational aerosciences, or any other field with large data sets.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/lfc  (documentation:  https://nasa.github.io/lfc-doc)","license":null}},{"forgeId":"forge_nasa_arc_18996_1","source":{"institution":"NASA","subUnit":"Ames Research Center","subUnitCode":"ARC","nativeId":"ARC-18996-1","sourceUrl":"https://software.nasa.gov/software/ARC-18996-1","confidence":"high"},"type":"software","title":"Condor","abstract":"Condor is a mathematical modeling framework for engineers with a deadline. Condor provides a modular framework for creating and numerically evaluating engineering models. Model equations are defined using an expressive mathematical domain-specific language implemented using Pythons metaprogramming and an external symbolic backend. When evaluating models, the process of transforming the model equations, creating numerical functions, calling solvers, and extracting the values is fully automated, allowing engineers to focus on engineering rather than coding. Condor includes a variety of built-in model templates, from simple explicit systems and table lookups to more sophisticated algebraic systems, trajectory analyses, and optimization problems. An emphasis was placed on flexibility and modularity, so external tools and solvers can be easily incorporated.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/condor","license":null}},{"forgeId":"forge_nasa_drc_010_044","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-010-044","sourceUrl":"https://software.nasa.gov/software/DRC-010-044","confidence":"high"},"type":"software","title":"Half-Cycle Crack Growth Predicts Operational Flight Life of Critical Aerostructural Components","abstract":"This software program offers a reliable method for calculating theoretical fatigue crack growths that could lead to catastrophic structural component failures. The program builds upon and integrates Armstrong's proven half-cycle and closed-form aging theories and is especially accurate because it considers every half-cycle of loading spectra for specific structural components. This innovation is an improvement on traditional prediction software (and in particular on visual inspections) because it considers mini-amplitude stress loading and half-cycles based on the duty cycle of a particular component or structure. Developed to calculate the number of operational life flights for B-52B pylon hooks, the program and underlying theories can be applied to estimate the service life of any critical structural component. BENEFITS * Reliable: Predicts operational flight life of critical aerostructural components * Accurate: Considers a comprehensive suite of test data by counting every half-cycle of each random loading spectrum, including secondary mini-amplitude half-cycles that do not cross mean stress lines * Customized: Identifies potential structural problem areas and calculates the number of safe flights an aerostructure can make based on its particular duty cycle * Economical: Saves monetary costs associated with loss of expensive equipment due to component failures * Adaptable: Offers applicability to other industries, with modifications to the input model POTENTIAL APPLICATIONS * Spacecraft * Aircraft * Ships * Oil rigs * Windmills * Bridges * Oscillating industrial equipment used in mines and quarries HOW IT WORKS The Half-Cycle Crack Growth Computer Program is a powerful and practical tool for visualizing crack growth curves associated with critical stress points. It was designed to determine the number of safe operational flights an aircraft can make without structural component failures due to fatigue crack growth. The computer program was developed after two rear B-52B pylon hooks failed simultaneously during an Armstrong test operation. Subsequent examinations revealed that hook failure was caused by rapid crack propagation from existing micro cracks that had been masked by chrome-plated surfaces and thus were undetected during visual inspections. To obtain baseline data for use in the program, the critical structural components must be proof-load tested to determine the initial theoretical crack size based on fracture mechanics. Next, strain gauges are installed in the vicinity of stress concentration points and are calibrated to record the applied loads. After the failure-critical components are identified, stress analysis is performed for each component to establish the functional relationship between the applied load and the induced tangential stress at the critical stress point. The program reads the data and selects the maximum and minimum loads of each half-cycle of the random flight loading spectra. Program outputs are used to generate and display crack growth curves, providing a visual warning for preventing catastrophic structural failures. For the B-52B pylon hooks discussed above, crack growth curves were produced for each hook, allowing visual observation of the crack growth behavior during the entire air-launching or captive flight. The crack growth curves provided the visual knowledge that taxiing, takeoff, drop/landing, and sometimes gusts induced a major portion of the total crack growth per operation. Written in the C programming language, the program can be adapted for use in other industries by modifying the input model (i.e., data format load spectrum files) for the most expensive and mission critical components. WHY IT IS BETTER The program examines test data in a much more detailed fashion than other fatigue crack growth modeling software, counting every half-cycle of each random loading spectrum, so it is able to make better predictions about component life. By improving fatigue and failure predictions, the software provides safer flights and lower maintenance costs. Additionally, these predictions allow engineers to determine the critical points during operation that the majority of stress is placed on a particular component, which could allow for better component design that takes those specific forces into account.","category":"mechanical_systems","categoryRaw":"structures and mechanisms","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_drc_011_003","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-011-003","sourceUrl":"https://software.nasa.gov/software/DRC-011-003","confidence":"high"},"type":"software","title":"Increasing Engineering Efficiency with STARS: Structural Analysis Routines","abstract":"Structural Analysis Routines (STARS) is an efficient, cost-effective, and unique computer program that analyzes a variety of practical engineering problems. The software is a fully integrated, multidisciplinary, finite-element-based, graphic-oriented analysis tool that combines individual modules to solve complex engineering problems. STARS can be used for a range of applications, including structural analysis , heat transfer, linear aerodynamics, and computational fluid dynamics (CFD) as well as coupled linear and CFD-based (aeroelastic, aeroacoustic, and aerothermoelastic) acoustics and aeroservoelastic analysis . Because of the tool's highly integrated nature, it has broad application across many engineering disciplines. BENEFITS * Efficient: Integrates general-purpose analysis modules for a range of multidisciplinary applications * Easy to implement: Utilizes standard FORTRAN language to run on a variety of computational platforms * Powerful: Processes large amounts of data for a finite-element-based, graphic-oriented linear and nonlinear analysis POTENTIAL APPLICATIONS * Aerospace engineering * Mechanical and civil engineering * Automotive design","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_drc_012_022","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-012-022","sourceUrl":"https://software.nasa.gov/software/DRC-012-022","confidence":"high"},"type":"software","title":"QuickPlot General-Purpose Plotting Tool","abstract":"Processing and plotting large amounts of data can be time consuming and expensive, particularly for data that specify time-varying values, so-called time history data. QuickPlot--along with DthDiff and DthData--helps manage several key operations for time history data, enable comparison of the time history files, and efficiently plot gigabytes to terabytes of data. QuickPlot is a general-purpose tool developed to read and plot time-history data files generated during flight testing and simulation projects. Programmed in C, this utility offers a flexible data interface that enables users to read data files in a variety of formats, including those developed using the MATLAB&reg; format. The graphical user interface allows commands to be scripted and read from an input script file. Users can plot data from multiple runs and multiple input files and manipulate data signals with algebraic expressions. (MATLAB is a registered trademark of The MathWorks, Inc.) BENEFITS The QuickPlot-DthDiff-DthData suite of software tools offers several benefits: * Powerful: Processes large amounts of data from multiple sources and allows users to convert data files from one format to another * Efficient: Time-tags data files, enabling time-range processing of a selected parameter or set of parameters * Fast: Reads and plots data in a fraction of the time required for conventional data-plotting utilities * Simple: Offers a graphical user interface for command input and data plotting * Economical: Works without back-end processing systems, databases, or networks APPLICATIONS The QuickPlot-DthDiff-DthData suite of software tools can be used for: * Flight testing and simulation projects * Manufacturing processes * Scientific research * Earth climate modeling and simulation * Retail transaction and delivery analysis * Economic market modeling","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_drc_012_024","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-012-024","sourceUrl":"https://software.nasa.gov/software/DRC-012-024","confidence":"high"},"type":"software","title":"DthData Armstrong Time-History Software Utility","abstract":"Processing and plotting large amounts of data can be time consuming and expensive, particularly for data that specify time-varying values, so-called time history data. DthData--along with QuickPlot and DthDiff--helps manage several key operations for time history data, enable comparison of the time history files, and efficiently plot gigabytes to terabytes of data. A standalone command-line-driven utility program written in ANSI-C, DthData is designed to extract selected signals and time segments from input files and write the selected data to output files. Other capabilities include converting file formats, merging data from multiple input files, time skewing, interpolating to common output frame times, renaming signals, and generating calculated output signals as functions of the input signals. The utility also converts time history files from a compressed format to any format suitable for displaying or plotting, including MATLAB&reg; or Microsoft Excel&reg; formats. (MATLAB is a registered trademark of The MathWorks, Inc. Microsoft and Excel are registered trademarks of Microsoft Corporation in the United States and/or other countries.) BENEFITS The QuickPlot-DthDiff-DthData suite of software tools offers several benefits: * Powerful: Processes large amounts of data from multiple sources and allows users to convert data files from one format to another * Efficient: Time-tags data files, enabling time-range processing of a selected parameter or set of parameters * Fast: Reads and plots data in a fraction of the time required for conventional data-plotting utilities * Simple: Offers a graphical user interface for command input and data plotting * Economical: Works without back-end processing systems, databases, or networks APPLICATIONS The QuickPlot-DthDiff-DthData suite of software tools can be used for: * Flight testing and simulation projects * Manufacturing processes * Scientific research * Earth climate modeling and simulation * Retail transaction and delivery analysis * Economic market modeling","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_drc_012_025","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-012-025","sourceUrl":"https://software.nasa.gov/software/DRC-012-025","confidence":"high"},"type":"software","title":"DthDiff Time-History Difference Software Utility","abstract":"Processing and plotting large amounts of data can be time consuming and expensive, particularly for data that specify time-varying values, so-called time history data. DthDiff--along with QuickPlot and DthData--helps manage several key operations for time history data, enable comparison of the time history files, and efficiently plot gigabytes to terabytes of data. A standalone command-line-driven utility program written in C, DthDiff compares time history files. In addition to configuring the nature of comparisons, users can specify a precision tolerance and perform a check for a specified number of significant digits. Alternatively, they can use absolute, relative, and percent tolerances to perform the comparison. Summary output also indicates the number of samples that fail specified tolerance tests. BENEFITS The QuickPlot-DthDiff-DthData suite of software tools offers several benefits: * Powerful: Processes large amounts of data from multiple sources and allows users to convert data files from one format to another * Efficient: Time-tags data files, enabling time-range processing of a selected parameter or set of parameters * Fast: Reads and plots data in a fraction of the time required for conventional data-plotting utilities * Simple: Offers a graphical user interface for command input and data plotting * Economical: Works without back-end processing systems, databases, or networks APPLICATIONS The QuickPlot-DthDiff-DthData suite of software tools can be used for: * Flight testing and simulation projects * Manufacturing processes * Scientific research * Earth climate modeling and simulation * Retail transaction and delivery analysis * Economic market modeling","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_drc_013_035","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-013-035","sourceUrl":"https://software.nasa.gov/software/DRC-013-035","confidence":"high"},"type":"software","title":"Structure Deformation Calculation Program based on Ko Displacement Transfer Functions","abstract":"The Structure Deformation Calculation Program is a computer program that will calculate slopes, deflections, and cross-sectional twist angles if applicable at strain-sensing stations on any structures based on the Ko Displacement Transfer Functions. By using this method, only a small number of strain sensors are required along strain-sensing line(s) on a structure. The program uses measured surface bending strains obtained at strain-sensing stations and structure geometrical properties as its inputs. Depending on structure type, the program will use the appropriate Ko Displacement Transfer Function. All structure types mentioned in the publications listed in the Technology Readiness / Software tab are covered in this program. The figures of different structure types will be included in the Additional Documentation in the General Information tab. The Displacement Theory is purely geometrical in nature, containing no material properties.The program will output time history slopes, deflections, maximum deflections, and cross-sectional twist angles if applicable, and depth factors if calculated. Users can use the time history deflections for plotting: deformed shapes of the structure at a certain time slice, three dimensional deformed shapes at multiple time slices, and deflections of each individual strain-sensing station. The calculated deflections of a structure can be studied and analyzed for monitoring the health of a structure to prevent catastrophic events.","category":"mechanical_systems","categoryRaw":"structures and mechanisms","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_drc_014_009","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-014-009","sourceUrl":"https://software.nasa.gov/software/DRC-014-009","confidence":"high"},"type":"software","title":"Chapter 10 Tools: Solving the Challenges of Varying Implementations of the IRIG Standard","abstract":"Developers at NASA's Armstrong Flight Research Center have developed a software toolkit--dubbed Chapter 10 Tools--that is capable of reading data files originating from various onboard digital recorders that follow the Range Commanders Council Inter-Range Instrumentation Group (IRIG) 106 Chapter 10 Digital Recording Standard but use differing interpretations of that standard. The toolkit reads data files regardless of the vendor implementation of the source recorder, displays the data, and even identifies and corrects errors. Ultimately, it produces a data file that can be successfully processed post- flight . Chapter 10 Tools was developed in response to ongoing challenges researchers at Armstrong's Dryden Aeronautical Test Range faced when attempting to process data files originating from various vendors' digital recorders. As Chapter 10 experienced rapid growth as a technology standard for data recording, many digital recorder vendors began interpreting the standard differently--resulting in errors and variations (sometimes even between one vendor's different firmware versions of the same recorder). While some errors could be identified with Chapter 10 validation software, the type of error was not always apparent, making fixes problematic. These errors and variations can prevent software from reading and processing the data file, thereby effectively making the data unavailable. Chapter 10 Tools eliminates these challenges with a flexible software toolkit that gives users visibility into the data file's individual data packets, allowing for both manual and automatic correction of errors. An additional Telemetry Attributes Transfer Standard (TMATS) editor offers the ability to modify and add details to the TMATS file. Because aircraft personnel typically only include enough information in the TMATS portion of the Chapter 10 data file to allow for data recording, this leaves a gap in ground personnel's ability to process that data. So, the TMATS editor enables error correction and provides the ability to add the additional information needed to process the data. Chapter 10 Tools is now in widespread use at Armstrong's Dryden Aeronautical Test Range. BENEFITS * Diagnostic: Accurately identifies errors and variations in various Chapter 10 data files, as well as the error type * Flexible: Offers a flexible architecture enabling visibility into individual data packets * Easy to use: Autocorrects most errors, and makes manual error identification and correction simple and streamlined APPLICATIONS Chapter 10 Tools is ideal for: * NASA flight data processors needing to reconcile data between varying flight data recorders * Software developers looking to integrate error identification and correction capabilities into their Chapter 10 toolkits","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_drc_014_024","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-014-024","sourceUrl":"https://software.nasa.gov/software/DRC-014-024","confidence":"high"},"type":"software","title":"Automate Optimization and Design Tasks Across Disciplines with Object-Oriented Optimization Tool 2.0","abstract":"This multidisciplinary design analysis and optimization (MDAO) solution automates optimization tasks early in the design process according to a range of user-defined parameters, including factors such as cost, safety, and environmental impact. The tool provides a framework that enables several engineers to use multiple programs to globally optimize a model. This tool quickly streamlines optimization and design tasks by integrating disparate software packages--NASTRAN&#174;, ZAERO&#174;, Cart3D, FUN3D, MOMAT, etc.--in a cross-platform network environment. Designers can convert design variables to structural parameters and generate objective functions using either the built-in pre/post-processor or their own analyzer. FEATURES * Central executive module allows designers to choose input/output files and solution modules, determine the status of tasks, and select modules for output viewing and filtering. * Object-oriented framework integrates the analysis codes for multiple disciplines, rather than relying on one code to perform the analysis for all disciplines. * Modules calculate structural weight, stress, deflection, buckling, and more. * Graphical user interface can provide a single point of control for applications that run on a user's PC or for code that may reside on remote workstations or a computational cluster. * Use of existing tools and practices saves development time and resources. * With most of the code written in standard Fortran, it is easy to upgrade and incorporate new optimization technologies while integrating/adopting new state-of-the-art software. POTENTIAL APPLICATIONS Originally developed for preliminary design of subsonic, transonic, supersonic, and hypersonic aircraft, this innovative MDAO tool can be applied to other engineering fields, including: * Shipbuilding * Automotive * Engineering services * Packaging * Sporting equipment NASTRAN is a registered trademark of the National Aeronautics and Space Administration. ZAERO is a registered trademark of ZONA Technology, Inc.","category":"mechanical_systems","categoryRaw":"structures and mechanisms","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_drc_015_017","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-015-017","sourceUrl":"https://software.nasa.gov/software/DRC-015-017","confidence":"high"},"type":"software","title":"Predict the Behavior of Blackbody Heated Surfaces","abstract":"Many areas of science and engineering require an understanding of the radiation that emits from a heated surface. Specifically, there is a need to calculate the radiation's intensity and spectral distribution for thermal radiation heat transfer, infrared signature analysis , and radiation thermometry. Furthermore, being able to predict the heat transfer rate and the spectral distribution of the emitted energy for the blackbody is particularly helpful. The need for these capabilities led researchers at NASA's Armstrong Flight Research Center to develop a set of computer functions that can be used in predicting the behavior of heated surfaces. In addition, the routines enable engineers to use information regarding spectral intensities to determine surface temperatures. They can also calculate the sensitivity of these temperature measurements to unknowns in the input parameters. NASA wrote these routines in Microsoft&#174; Visual Basic&#174; for Applications (VBA) software and incorporated functions specific to Microsoft Excel&#174; software. BENEFITS * Full spectrum: Enables calculation of important function derivatives and integration of the blackbody function over a range of wavelengths * Portable: Can be integrated with other engineering software * Easy to use: Based on widely available computer software tools from the Microsoft suite POTENTIAL APPLICATIONS In addition to aerospace applications, this software is useful for researchers developing new materials and other technologies to be used in a wide range of applications: * Thermal management: Integrated circuits, computer chassis, remote sensors * Heat shields: Automotive, appliances, safety equipment * Insulation: Architecture, textiles/clothing * Energy storage: Collecting/Storing thermal energy * Monitoring: Infrared-based surveillance * Earth/Planetary science: Understanding the composition of clouds, volcanoes, etc. Microsoft, Visual Basic, and Excel are registered trademarks of Microsoft Corporation in the United States and/or other countries.","category":"materials_coatings","categoryRaw":"materials and processes","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_drc_021_024","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-021-024","sourceUrl":"https://software.nasa.gov/software/DRC-021-024","confidence":"high"},"type":"software","title":"1998 NIST-JANAF (National Institute of Standards and Technology-Joint Army Navy Air Force) Database Scanning and Plotting Program","abstract":"The 1998 NIST-JANAF (National Institute of Standards and Technology-Joint Army Navy Air Force) Database Scanning and Plotting Program is an interactive software application that contains fits of thermodynamic data contained in the Fourth Edition of the NIST-JANAF Thermochemical Tables. Fits for 1,068 common elemental and molecular species are contained within the database. The fitting coefficients provide predictive values covering a wide range of temperatures (in many cases for gas state species from 298.15 to 6,000 K). A total of 1,760 fits are included covering gas, solid, and liquid phases. Thermochemical properties that can conveniently be computed from the data fits include specific heat, entropy, enthalpy, free energy, and reduced free energy. The software is a Microsoft Excel-based application and allows extracted data to be used as inputs to other thermochemistry codes or used to compute thermochemical properties within Excel using supplied macros. Data fits can be extracted based on elemental composition or the fits for specific chemical species can be selected. Additionally, the program allows the user to plot both the original JANAF data and the associated fits of the thermochemical properties versus temperature. This can be helpful in visualizing the behavior of the thermodynamic properties.","category":"materials_coatings","categoryRaw":"materials and processes","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_drc_025_012","source":{"institution":"NASA","subUnit":"Armstrong Flight Research Center","subUnitCode":"DFRC","nativeId":"DRC-025-012","sourceUrl":"https://software.nasa.gov/software/DRC-025-012","confidence":"high"},"type":"software","title":"EQDE computer program version 3","abstract":"FORTRAN computer program which derives strain gage loads equation coefficients from data collected during a strain gage load calibration test","category":"mechanical_systems","categoryRaw":"structures and mechanisms","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_14292_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-14292-1","sourceUrl":"https://software.nasa.gov/software/GSC-14292-1","confidence":"high"},"type":"software","title":"Coordinated Data Analysis Workshop Web (CDAWeb)","abstract":"The CDAWeb software and the CDAWeb service built on this software have been developed and continue to be enhanced and maintained by the Space Physics Data Facility. The technology has supported NASA/Office of Space Science programs dealing with the connections between the Sun and the Earth. CDAWeb software is essentially a set of Interactive Data Language (IDL) scripts that act as the engine of the system. Please visit: http://cdaweb.gsfc.nasa.gov/cdaweb/istp_public/","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://cdaweb.gsfc.nasa.gov/cdaweb/istp_public/","license":null}},{"forgeId":"forge_nasa_gsc_14730_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-14730-1","sourceUrl":"https://software.nasa.gov/software/GSC-14730-1","confidence":"high"},"type":"software","title":"Space Physics Data Facility (SPDF) Web Services","abstract":"These Web services provide a distributed programming interface to a portion of the Space Physics Data Facility (SPDF) software. The technology conforms to all applicable Web service specifications of the World Wide Web Consortium. Please visit the following URL for additional information: http://spdf.gsfc.nasa.gov/","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://spdf.gsfc.nasa.gov/","license":null}},{"forgeId":"forge_nasa_gsc_14732_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-14732-1","sourceUrl":"https://software.nasa.gov/software/GSC-14732-1","confidence":"high"},"type":"software","title":"Tool For Interactive Plotting, Sonification, and 3D Orbit Display (TIPSOD)","abstract":"TIPSOD is a software application designed for interactive, animated, 4D (space and time) visualization of satellite orbits. The technology is implemented in Java 3D and is an extension to the existing Satellite Situation Center Web (SSCWeb) 2D static orbit graphics. Please visit the following URL for additional information: http://opensource.gsfc.nasa.gov/projects/tipsod/index.php","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://opensource.gsfc.nasa.gov/projects/tipsod/index.php","license":null}},{"forgeId":"forge_nasa_gsc_14841_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-14841-1","sourceUrl":"https://software.nasa.gov/software/GSC-14841-1","confidence":"high"},"type":"software","title":"Simple, Scalable, Script-Based Science Processor for Missions (S4PM)","abstract":"S4PM is a set of Perl scripts that implement a data-driven processing system that executes science algorithms automatically as new data arrive. S4PM includes a graphical user interface for monitoring algorithms and the overall system for failures. The Perl scripts can currently process data from the Moderate Resolution Imaging Spectroradiometer and the Atmospheric Infrared Sounder, but the technology can be extended to process data from other missions if desired. Please visit the following URL for more information: http://opensource.gsfc.nasa.gov/projects/s4pm/","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://opensource.gsfc.nasa.gov/projects/s4pm/","license":null}},{"forgeId":"forge_nasa_gsc_14905_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-14905-1","sourceUrl":"https://software.nasa.gov/software/GSC-14905-1","confidence":"high"},"type":"software","title":"Data Service Provider Cost Estimation Tool and Comparables Database","abstract":"The Data Service Provider Cost Estimation Tool (CET) and Comparables Database (CDB) package provides NASA's Earth Science Enterprise (ESE) the ability to make lifecycle cost estimates for the implementation and operation of the data service providers that are required to support its science and applications programs. The Data Service Provider CET and CDB package employs a cost-estimation-by-analogy approach. For more information on the package, please visit: http://opensource.gsfc.nasa.gov/projects/CET/index.php","category":"operations","categoryRaw":"business systems and project management","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://opensource.gsfc.nasa.gov/projects/CET/index.php","license":null}},{"forgeId":"forge_nasa_gsc_14938_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-14938-1","sourceUrl":"https://software.nasa.gov/software/GSC-14938-1","confidence":"high"},"type":"software","title":"Earth Observing System (EOS) Data Gateway (EDG)","abstract":"The Earth Observing System Data Gateway (EDG) provides the earth science community with a single interface that will search for data granules from distributed data archives. The innovation enables users to explore, discover, and order available data from geographically distributed providers. For more information, please visit: http://opensource.gsfc.nasa.gov/projects/edg/index.php#software","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://opensource.gsfc.nasa.gov/projects/edg/index.php","license":null}},{"forgeId":"forge_nasa_gsc_14948_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-14948-1","sourceUrl":"https://software.nasa.gov/software/GSC-14948-1","confidence":"high"},"type":"software","title":"HDFView Plugin","abstract":"This Java-language software plug-in to HDFView provides an interface for two versions of hierarchical data formats (HDF 4 and HDF 5). Please visit the following URL for more information: http://opensource.gsfc.nasa.gov/projects/HDF/index.php","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://opensource.gsfc.nasa.gov/projects/HDF/index.php","license":null}},{"forgeId":"forge_nasa_gsc_15006_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-15006-1","sourceUrl":"https://software.nasa.gov/software/GSC-15006-1","confidence":"high"},"type":"software","title":"XML to ODL Convertor","abstract":"This program translates an XML representation of Hierarchical Data Format-Earth Observing System (HDF-EOS) ODL metadata back to the ODL format. Please visit the following URL for additional information: http://opensource.gsfc.nasa.gov/projects/xml2odl/index.php","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://opensource.gsfc.nasa.gov/projects/xml2odl/index.php","license":null}},{"forgeId":"forge_nasa_gsc_15007_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-15007-1","sourceUrl":"https://software.nasa.gov/software/GSC-15007-1","confidence":"high"},"type":"software","title":"Hierarchical Data Format-Earth Observing System (HDF-EOS) to NetCDF Converter","abstract":"This C-language computer program accepts a set of scientific data/metadata from an Earth Observing System (EOS) satellite and converts it from the format in which it was created and delivered into another format for data processing and exchange on Earth. The converter can be downloaded at: http://www.hdfeos.org/software/convert_hdfeos5.php","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://www.hdfeos.org/software/convert_hdfeos5.php","license":null}},{"forgeId":"forge_nasa_gsc_15009_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-15009-1","sourceUrl":"https://software.nasa.gov/software/GSC-15009-1","confidence":"high"},"type":"software","title":"Hierarchical Data Format Earth Observing System (HDF-EOS) Data Extractor (HEEX)","abstract":"The Hierarchical Data Format Earth Observing System (HDF-EOS) Data Extractor (HEEX) is a tool that enables users to extract HDF-EOS data to binary or ASCII data formats in HTML or XML index. The software can be used for both HDF-EOS2 and HDF-EOS5, and it automatically recognizes the two formats.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://hdfeos.net/software/heex/","license":null}},{"forgeId":"forge_nasa_gsc_15010_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-15010-1","sourceUrl":"https://software.nasa.gov/software/GSC-15010-1","confidence":"high"},"type":"software","title":"Hierarchical Data Format Earth Observing System (HDF-EOS) Metadata Updater (HEMU)","abstract":"HDF-EOS Metadata Updater (HEMU) enables users to modify metadata inside an HDF-EOS file (either HDF-EOS2 and HDF-EOS5). The tool can be used to extract metadata from a dataset to a text file that can then be modified with any text editor; replace metadata with text from an external file; or update metadata with text from an external file. For more information, please visit: http://opensource.gsfc.nasa.gov/projects/hemu/index.php","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://opensource.gsfc.nasa.gov/projects/hemu/index.php","license":null}},{"forgeId":"forge_nasa_gsc_15011_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-15011-1","sourceUrl":"https://software.nasa.gov/software/GSC-15011-1","confidence":"high"},"type":"software","title":"Hierarchical Data Format Earth Observing System (HDF-EOS) Web Server","abstract":"This shell script chains together existing data usability group tools to: extract ODL metadata from an HDF-EOS file; convert the metadata to XML; reformat the XML into HTML; publish the HTML and the original HDF-EOS file to a Web server and an OPeNDAP server; and reformat the XML and submit it to the Earth Observing System Clearing House (ECHO). For more information, please visit: http://opensource.gsfc.nasa.gov/projects/heserve/index.php","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://opensource.gsfc.nasa.gov/projects/heserve/index.php","license":null}},{"forgeId":"forge_nasa_gsc_15012_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-15012-1","sourceUrl":"https://software.nasa.gov/software/GSC-15012-1","confidence":"high"},"type":"software","title":"Metadata Check","abstract":"Metadata Check is a command-line tool to check Earth Observing System (EOS) metadata with a metadata descriptor. For more information, please visit: http://opensource.gsfc.nasa.gov/projects/metacheck/index.php","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://opensource.gsfc.nasa.gov/projects/metacheck/index.php","license":null}},{"forgeId":"forge_nasa_gsc_15013_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-15013-1","sourceUrl":"https://software.nasa.gov/software/GSC-15013-1","confidence":"high"},"type":"software","title":"ODL-to-XML Converter","abstract":"This command-line Java-based utility converts ODL Hierarchical Data Format-Earth Observing Satellite (HDFEOS) metadata file to an HDFEOS XML file. The tool utilizes an all-Java ODL library that includes a syntax and grammar parser. The software can be downloaded at: http://opensource.gsfc.nasa.gov/projects/ODL_XML/index.php","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://opensource.gsfc.nasa.gov/projects/ODL_XML/index.php","license":null}},{"forgeId":"forge_nasa_gsc_15015_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-15015-1","sourceUrl":"https://software.nasa.gov/software/GSC-15015-1","confidence":"high"},"type":"software","title":"HDF-EOS5 Validator","abstract":"This software allows generators of HDF-EOS data products to encode product requirement specifications in XML. The tool will then mechanically check product files against those requirements. For more information, please visit: http://opensource.gsfc.nasa.gov/projects/Validator/index.php","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://opensource.gsfc.nasa.gov/projects/Validator/index.php","license":null}},{"forgeId":"forge_nasa_gsc_15016_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-15016-1","sourceUrl":"https://software.nasa.gov/software/GSC-15016-1","confidence":"high"},"type":"software","title":"Hierarchical Data Format Earth Observing System (HDF-EOS) XML Document-Type Definitions and Schemas","abstract":"An XML standard has been developed for the HDF-EOS5 file format using document-type definitions and schemas. Users can transform HDF5 files into XML format and vice versa. For more information, please visit: http://opensource.gsfc.nasa.gov/projects/XML_DTD_Schemas/index.php","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://opensource.gsfc.nasa.gov/projects/XML_DTD_Schemas/index.php","license":null}},{"forgeId":"forge_nasa_gsc_15017_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-15017-1","sourceUrl":"https://software.nasa.gov/software/GSC-15017-1","confidence":"high"},"type":"software","title":"XML to HDF-EOS Convertor","abstract":"This software program takes an XML representation of the contents of a Hierarchical Data Format-Earth Observing System (HDF-EOS) file and recreates the file from that description. Please visit the following URL for additional information: http://opensource.gsfc.nasa.gov/projects/xml2he/index.php","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://opensource.gsfc.nasa.gov/projects/xml2he/index.php","license":null}},{"forgeId":"forge_nasa_gsc_15138_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-15138-1","sourceUrl":"https://software.nasa.gov/software/GSC-15138-1","confidence":"high"},"type":"software","title":"MATLAB-Oslo Toolkit","abstract":"This toolkit is a set of MATLAB scripts and functions that enable rapid transfer of optical system and performance data from Oslo optical software into the MATLAB environment. Typical applications include: extracting prescription data into MATLAB to confirm consistency of various delivered models; perturbing the models and performing various analyses in support of integrated modeling activities; and enabling a MATLAB-driven optical model for integrated system-level modeling of wavefront sensing and control . The toolkit can be downloaded at http://opensource.gsfc.nasa.gov/projects/Matlab/index.php","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://opensource.gsfc.nasa.gov/projects/Matlab/index.php","license":null}},{"forgeId":"forge_nasa_gsc_15140_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-15140-1","sourceUrl":"https://software.nasa.gov/software/GSC-15140-1","confidence":"high"},"type":"software","title":"MATLAB-Code V Toolkit","abstract":"This toolkit is a set of MATLAB scripts and functions that enable rapid transfer of optical system and performance data from Code V optical software into the MATLAB environment. Typical applications include: extracting prescription data into MATLAB to confirm consistency of various delivered models; perturbing the models and performing various analyses such as ray tracing or generation of point-spread functions in support of integrated modeling activities; and enabling a MATLAB-driven optical model for integrated system-level modeling of wavefront sensing and control . The toolkit can be downloaded at: http://opensource.gsfc.nasa.gov/projects/Matlab_Code_V/index.php","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://opensource.gsfc.nasa.gov/projects/Matlab_Code_V/index.php","license":null}},{"forgeId":"forge_nasa_gsc_15151_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-15151-1","sourceUrl":"https://software.nasa.gov/software/GSC-15151-1","confidence":"high"},"type":"software","title":"MATLAB-Zemax Toolkit","abstract":"The MATLAB-Zemax toolkit is a set of MATLAB scripts and functions that enable rapid transfer of optical system and performance data from Zemax optical software into the MATLAB environment. Typical applications include: extracting prescription data into MATLAB to confirm consistency of various delivered models; perturbing the models and performing various analyses in support of integrated modeling activities; and enabling a MATLAB-driven optical model for integrated system-level modeling of wavefront sensing and control . The toolkit can be downloaded at: http://opensource.gsfc.nasa.gov/projects/Matlab_Zemax/index.php","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://opensource.gsfc.nasa.gov/projects/Matlab_Zemax/index.php","license":null}},{"forgeId":"forge_nasa_gsc_15276_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-15276-1","sourceUrl":"https://software.nasa.gov/software/GSC-15276-1","confidence":"high"},"type":"software","title":"NASA Forecast Model Web (NFMW) Map Service","abstract":"NFMW reads weather forecast models outputs; subsets the data to the region of interest; interpolates the data to the specified size; generates a visualization of the data using colors, contour lines, or arrows; and sends the visualization to the client. More information can be found at: http://opensource.gsfc.nasa.gov/projects/NFMW/","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://opensource.gsfc.nasa.gov/projects/NFMW/","license":null}},{"forgeId":"forge_nasa_gsc_15363_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-15363-1","sourceUrl":"https://software.nasa.gov/software/GSC-15363-1","confidence":"high"},"type":"software","title":"Global Modeling Initiative (GMI) Software","abstract":"The Global Modeling Initiative (GMI) is a state-of-the-art, modular 3D chemistry and transport model (CTM) that can be used for assessment of the impact of various natural and anthropogenic perturbations on atmospheric composition and chemistry, including, but not exclusively, the effect of aircraft.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_15469_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-15469-1","sourceUrl":"https://software.nasa.gov/software/GSC-15469-1","confidence":"high"},"type":"software","title":"Global Precipitation Space and Ground Radar Comparison Software","abstract":"Designed to support a prototype validation network for the Global Precipitation Measurement (GPM) spaceflight mission , this space and ground radar comparison software collects data from the Precipitation Radar instrument flying on the Tropical Rainfall Measuring Mission (TRMM) spacecraft. Please visit the following URL for additional information: http://opensource.gsfc.nasa.gov/projects/GPM/","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://opensource.gsfc.nasa.gov/projects/GPM/","license":null}},{"forgeId":"forge_nasa_gsc_15594_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-15594-1","sourceUrl":"https://software.nasa.gov/software/GSC-15594-1","confidence":"high"},"type":"software","title":"Range Safety Algorithm Software Module for an Autonomous Flight Safety System","abstract":"This software library was developed to mitigate the public safety risks of hazards associated with the flight of expendable launch vehicles and other unmanned flight vehicles. The software encapsulates the various constructs and algorithms required to accomplish Time Space Position Information (TSPI) data management from multiple tracking sources. At its core, the technology evaluates various user-configurable rule sets that govern the qualification of TSPI data sources; provides a pre-launch autonomous hold-launch function; performs flight- monitoring /flight-termination functions; and provides end-of-mission safing.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_15618_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-15618-1","sourceUrl":"https://software.nasa.gov/software/GSC-15618-1","confidence":"high"},"type":"software","title":"Automation Framework Designed for Flight Dynamics Products Generation (XFDS)","abstract":"This software framework automates the generation of flight dynamics products by providing a unified and consistent graphical interface to various tools. The technology coordinates the execution of applications such as Satellite ToolKit, FreeFlyer, and MATLAB; allows for the embedding of Perl code; provides a mechanism for passing messages between a collection of XFDS processes; and allows GMSEC messages to be sent and received. Automation configuration is stored in text files and can be edited directly or by using graphical editors implemented for each tool.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_15744_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-15744-1","sourceUrl":"https://software.nasa.gov/software/GSC-15744-1","confidence":"high"},"type":"software","title":"Visual System for Browsing, Analysis , and Retrieval of Data (ViSBARD)","abstract":"ViSBARD provides a way of visualizing multiple vector and scalar quantities as measured by many spacecraft at once. The data are displayed three-dimensionally; may be displayed either as connected lines or as points; and allow the rapid determination of vector configurations, correlations between many measurements at multiple points, and global relationships. Please visit the following URL for additional information: http://opensource.gsfc.nasa.gov/projects/visbard/index.php","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://opensource.gsfc.nasa.gov/projects/visbard/index.php","license":null}},{"forgeId":"forge_nasa_gsc_15874_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-15874-1","sourceUrl":"https://software.nasa.gov/software/GSC-15874-1","confidence":"high"},"type":"software","title":"Goddard Satellite Data Simulation Unit","abstract":"The Goddard Satellite Data Simulation Unit (SDSU) is a comprehensive unified system of multi-sensor satellite instrumental simulators. Skill of weather forecasting models can be evaluated in terms of satellite-observed multi-sensor radiance levels. Alternatively, the remote sensing community can more readily utilize atmospheric model simulations to develop and test their retrieval algorithms for application of Earth science.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://opensource.gsfc.nasa.gov/projects/G-SDSU/","license":null}},{"forgeId":"forge_nasa_gsc_15877_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-15877-1","sourceUrl":"https://software.nasa.gov/software/GSC-15877-1","confidence":"high"},"type":"software","title":"Simple, Scalable, Script-based Science Processing Archive (S4PA)","abstract":"Simple, Scalable, Script-based, Science Processing (S4P) Archive (S4PA) is a disk-based archiving system for remote sensing data. The tool can be used for new data transfer, data preprocessing, metadata generation, and data archival. Services provided include data access control , data subscription, metadata publication, and data recovery. All data are archived on readily available disk drives, with FTP and HTTP being the primary modes of data access. S4PA includes a graphical user interface for monitoring and re-configuring system operation. Please visit: https://github.com/nasa/S4PA","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/S4PA","license":null}},{"forgeId":"forge_nasa_gsc_15992_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-15992-1","sourceUrl":"https://software.nasa.gov/software/GSC-15992-1","confidence":"high"},"type":"software","title":"Lossless Hyper-/Multi-Spectral Data Compression Software","abstract":"This software performs lossless hyper-spectral and multi-spectral data compression. It can be downloaded at: http://opensource.gsfc.nasa.gov/projects/LHD/","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://opensource.gsfc.nasa.gov/projects/LHD/","license":null}},{"forgeId":"forge_nasa_gsc_15996_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-15996-1","sourceUrl":"https://software.nasa.gov/software/GSC-15996-1","confidence":"high"},"type":"software","title":"Core Flight System (CFS) Checksum Application Version 2","abstract":"Checksum (CS) is one of the reusable applications that make up the Core Flight System (CFS). The technology performs memory integrity management by verifying the contents of critical flight memory regions. Unexpected changes in memory (i.e., due to an SEU) are reported to ground operators.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/cs","license":null}},{"forgeId":"forge_nasa_gsc_16007_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-16007-1","sourceUrl":"https://software.nasa.gov/software/GSC-16007-1","confidence":"high"},"type":"software","title":"Core Flight System (CFS) File Manager (FM) Application Version 2","abstract":"FM provides the user commands to perform the following operations: copy file, move file, rename file, delete file(s), close file, concatenate file, decompress file, delete directory contents, create directory, remove directory, obtain file information, obtain open file listing, and obtain directory listings.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://sourceforge.net/projects/cfs-fm/","license":null}},{"forgeId":"forge_nasa_gsc_16009_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-16009-1","sourceUrl":"https://software.nasa.gov/software/GSC-16009-1","confidence":"high"},"type":"software","title":"Core Flight System (CFS) Stored Command (SC) Application Version 2","abstract":"The CFS SC application provides the ability to execute onboard absolute-time and relative-time command sequences. The technology offers a generic implementation that can be configured by a user to fit the needs of a specific mission.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://sourceforge.net/projects/cfs-sc/","license":null}},{"forgeId":"forge_nasa_gsc_16010_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-16010-1","sourceUrl":"https://software.nasa.gov/software/GSC-16010-1","confidence":"high"},"type":"software","title":"Core Flight System (CFS) Limit Checker (LC) Application Version 2","abstract":"The Limit Checker (LC) application is responsible for monitoring telemetry values.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/lc","license":null}},{"forgeId":"forge_nasa_gsc_16011_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-16011-1","sourceUrl":"https://software.nasa.gov/software/GSC-16011-1","confidence":"high"},"type":"software","title":"Core Flight System (CFS) Memory Manager Application Version 2","abstract":"The Memory Manager application processes commands, generally from the ground, in order to dump the contents of a memory location, dump the contents of a range of memory locations, load a memory location with specified data, load a range of memory with specified data, or fill an area of memory with the specified fill pattern. Operations can be performed on non-volatile, volatile, and memory mapped I/O.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://sourceforge.net/projects/cfs-mm","license":null}},{"forgeId":"forge_nasa_gsc_16012_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-16012-1","sourceUrl":"https://software.nasa.gov/software/GSC-16012-1","confidence":"high"},"type":"software","title":"Core Flight System (CFS) Memory Dwell Application Version 2","abstract":"The Memory Dwell application telemeters the contents of table-defined addresses at a table-defined dwell rate. Addresses can be processed using symbols if the target processor/operating system includes symbols.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://sourceforge.net/projects/cfs-md","license":null}},{"forgeId":"forge_nasa_gsc_16013_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-16013-1","sourceUrl":"https://software.nasa.gov/software/GSC-16013-1","confidence":"high"},"type":"software","title":"Total Verification System and C Based Verification Test Bench","abstract":"This technology verifies complex space flight digital designs in a more thorough manner than was previously possible while offering cost savings and reduced schedule time. The software combines a custom-designed GSE unit, the Total Verification System, along with a powerful test bench environment that uses C . Together, these elements allow a high level of code reuse between all the phases of the design and test cycle.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_16050_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-16050-1","sourceUrl":"https://software.nasa.gov/software/GSC-16050-1","confidence":"high"},"type":"software","title":"SAIC Algorithm Test Bed for Asteroid Detection (SALTAD), Version 1.5","abstract":"Composed of a series of C-language models, the SALTAD software package processes multi-frame image data to detect moving asteroids in a star-cluttered background. The software is highly modularized for interfacing with existing near-Earth asteroid search facility software.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":"https://github.com/NASA-Planetary-Science/SALTAD","license":null}},{"forgeId":"forge_nasa_gsc_16123_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-16123-1","sourceUrl":"https://software.nasa.gov/software/GSC-16123-1","confidence":"high"},"type":"software","title":"Core Flight System (CFS) Scheduler Application Version 2","abstract":"The Scheduler application uses a one-second major timeframe, which is divided into a designer-determined collection of equally divided minor timeframes. The technology is configurable and table-driven to provide greater flexibility.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/sch","license":null}},{"forgeId":"forge_nasa_gsc_16125_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-16125-1","sourceUrl":"https://software.nasa.gov/software/GSC-16125-1","confidence":"high"},"type":"software","title":"Core Flight System (CFS) CFDP Version 2","abstract":"The CFDP application provides the capability to transmit and receive files to/from the ground. Tables are used to allow flexibility in specifying directory priorities and configurations.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://sourceforge.net/projects/cfs-cfdp/ ","license":null}},{"forgeId":"forge_nasa_gsc_16126_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-16126-1","sourceUrl":"https://software.nasa.gov/software/GSC-16126-1","confidence":"high"},"type":"software","title":"Core Flight System (CFS) Data Storage (DS) Application Version 2","abstract":"The DS application provides the ability to store data (i.e., messages) into files. Tables are used to provide the flexibility for specifying messages.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://sourceforge.net/projects/cfs-ds","license":null}},{"forgeId":"forge_nasa_gsc_16127_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-16127-1","sourceUrl":"https://software.nasa.gov/software/GSC-16127-1","confidence":"high"},"type":"software","title":"Core Flight System (CFS) Housekeeping (HK) Application Version 2","abstract":"The CFS Housekeeping application provides the ability to organize data from various packets into new packets in order to best utilize the telemetry bandwidth available for a mission.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://sourceforge.net/projects/cfs-hk","license":null}},{"forgeId":"forge_nasa_gsc_16151_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-16151-1","sourceUrl":"https://software.nasa.gov/software/GSC-16151-1","confidence":"high"},"type":"software","title":"Core Flight System (CFS) Health and Safety Application Version 2","abstract":"The plug-and-play CFS Health and Safety application is compatible with the Core Flight Executive (cFE) and uses the Operating System Abstraction Layer (OSAL), both of which were developed by Goddard Space Flight Center in order to provide a reusable, platform-independent, mission-independent, layered architecture for hosting applications. The technology can be used for any government or commercial spacecraft. Please visit the following URL for additional information: http://sourceforge.net/projects/coreflightexec/files/cFE-6.1.1/","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/hs","license":null}},{"forgeId":"forge_nasa_gsc_16228_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-16228-1","sourceUrl":"https://software.nasa.gov/software/GSC-16228-1","confidence":"high"},"type":"software","title":"General Mission Analysis Tool (GMAT), Version 2011A","abstract":"GMAT is a software system for trajectory optimization, mission analysis , trajectory estimation, and prediction. Analysts use GMAT to design spacecraft trajectories, optimize maneuvers, perform orbit determination, visualize and communicate mission parameters, and understand a mission&apos;s trade space. GMAT contains models of real-world objects such as spacecraft and thrusters, as well as analysis \"objects\" such as plots and reports. These objects are used in the mission sequence wherein the user employs commands supported by the system to model missions and perform estimation. Please visit the following URL for additional information: http://opensource.gsfc.nasa.gov/projects/GMAT/index.php","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://opensource.gsfc.nasa.gov/projects/GMAT/index.php","license":null}},{"forgeId":"forge_nasa_gsc_16232_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-16232-1","sourceUrl":"https://software.nasa.gov/software/GSC-16232-1","confidence":"high"},"type":"software","title":"Core Flight Executive (cFE)","abstract":"The Core Flight Executive (cFE) provides software bus, time, event, executive, table, and file services, and it defines the application programming interface (API) for each set function. Applications subscribe to cFE services at runtime, making system modifications easy. Facilitating rapid prototyping, new applications can be compiled, linked, loaded, and started without requiring the entire system to be rebuilt.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://opensource.gsfc.nasa.gov/projects/cfe/index.php","license":null}},{"forgeId":"forge_nasa_gsc_16375_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-16375-1","sourceUrl":"https://software.nasa.gov/software/GSC-16375-1","confidence":"high"},"type":"software","title":"Simple Subset Wizard","abstract":"The Simple Subset Wizard (SSW) makes searching for granules easier. The tool unites the search function with various subsetters to deliver a single, simple, seamless process. SSW uses OpenSearch to query the Earth Observing System Clearing House (ECHO) for granules and then employs individual subset agents to submit requests. The SSW currently has 11 agents to interface with different subsetters, which support the subsetting of 217 EOSDIS data sets. The SSW provides the capability to subset by either temporal range or spatial region, although not all subsetters have both of these capabilities.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://disc.sci.gsfc.nasa.gov/gesNews/new-simple-subset-wizard-makes-subsetting-simple","license":null}},{"forgeId":"forge_nasa_gsc_16467_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-16467-1","sourceUrl":"https://software.nasa.gov/software/GSC-16467-1","confidence":"high"},"type":"software","title":"Remote Memory Access Protocol Target Node","abstract":"This NASA technology provides SpaceWire design users with support for executing remote memory access protocol (RMAP) read and write commands. The target IP core is a VHDL description suitable for implementation in a field-programmable gate array (FPGA) or an application-specific integrated circuit (ASIC).","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_16471_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-16471-1","sourceUrl":"https://software.nasa.gov/software/GSC-16471-1","confidence":"high"},"type":"software","title":"Magnetosphere Multi-Scale (MMS) Spacecraft Flight Software","abstract":"This spacecraft flight software was developed to support unique multi-satellite MMS mission requirements. The technology interfaces to a sensor/actuator complement that includes a star sensor and Digital Sun Sensor, Accelerometer, and Thruster hardware to implement the functionality for determining and controlling spacecraft attitude and orbit.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_16586_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-16586-1","sourceUrl":"https://software.nasa.gov/software/GSC-16586-1","confidence":"high"},"type":"software","title":"Packet to Electrical Ground Support Equipment (EGSE) Interface Converter, Version 4.0","abstract":"Developed using platform-independent language, this interface converter packet allows already-existing EGSE equipment to be supported on Windows and UNIX operating systems. The software is set up and controlled using XML-formatted files that define interface connections and data content.","category":"electronics","categoryRaw":"electronics and electrical power","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_16720_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-16720-1","sourceUrl":"https://software.nasa.gov/software/GSC-16720-1","confidence":"high"},"type":"software","title":"42: A Comprehensive General-Purpose Simulation of Attitude and Trajectory Dynamics and Control of Multiple Spacecraft Composed of Multiple Rigid or Flexible Bodies","abstract":"Simulator of spacecraft attitude, orbit dynamics, and environmental models. Spacecraft models composed of multiple bodies are supported. The environment models include ephemerides for all planets and major moons in the solar system. Supports geometrical visualization through an OpenGL interface. The simulator is opensource and portable across computing platforms, making it customizable and extensible. It is written to support the entire GNC design cycle, from rapid prototyping and design analysis, to high-fidelity flight code verification.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://sourceforge.net/projects/fortytwospacecraftsimulation/","license":null}},{"forgeId":"forge_nasa_gsc_16846_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-16846-1","sourceUrl":"https://software.nasa.gov/software/GSC-16846-1","confidence":"high"},"type":"software","title":"Hazards Analysis Management Tool (HAMT)","abstract":"HAMT uses a single software tool to increase the efficiency and effectiveness of hazard analyses. Composed of a Microsoft Access front-end (that contains the user interface) paired with a Microsoft Access back-end (that stores analysis data), the software can be used to enter, edit, and report information throughout the hazard analysis lifecycle.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_16848_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-16848-1","sourceUrl":"https://software.nasa.gov/software/GSC-16848-1","confidence":"high"},"type":"software","title":"Obs4MIPS","abstract":"This technology is a front end to the Climate Model Output Rewriter (CMOR2) software package. The technology converts a variety of standard data formats (e.g., netcdf3, netcdf4, Grads control files, and MATLAB data files) to allow publication on the Earth System Grid Federation (ESGF) data node.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://opensource.gsfc.nasa.gov/projects/obs4mips/index.php","license":null}},{"forgeId":"forge_nasa_gsc_16852_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-16852-1","sourceUrl":"https://software.nasa.gov/software/GSC-16852-1","confidence":"high"},"type":"software","title":"EEPROM File System","abstract":"The EEPROM File System (EEFS) is a simple, reliable file system for embedded systems. The primary purpose of the EEFS is to provide a file system abstraction for EEPROM or PROM memories that is simple, efficient, and can be proven to be reliable. The EEFS can be used on embedded systems where a file system is needed to access data from EEPROM, PROM, or RAM memory, but otherwise might not have the resources to deploy a full file system such as the MSDOS file system. The EEPROM file system can also be used in systems where the ability to dump, patch, and diagnose files is required.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://opensource.gsfc.nasa.gov/projects/eefs/index.php","license":null}},{"forgeId":"forge_nasa_gsc_16917_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-16917-1","sourceUrl":"https://software.nasa.gov/software/GSC-16917-1","confidence":"high"},"type":"software","title":"Core Flight System (CFS) Software Bus Network (SBN) Application, Version 1.0","abstract":"The SBN serves as a plug-in to the cFE framework to transfer messages across process/processor interfaces. The technology has three primary functions: to establish and maintain a connection to each peer over available process/processor interfaces; to distribute and maintain a subscription message database for each peer; and to distribute messages to peers that have subscribed to message identifiers.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/sbn","license":null}},{"forgeId":"forge_nasa_gsc_17111_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-17111-1","sourceUrl":"https://software.nasa.gov/software/GSC-17111-1","confidence":"high"},"type":"software","title":"\"Worldview\" satellite imagery browsing and downloading tool","abstract":"Worldview is a software tool designed for interactively browsing and downloading imagery from NASA's Earth observing satellites. Building upon a set of open source mapping and user interface libraries, it provides an environment to visually discover interesting phenomena as observed by NASA satellites, then download the data for further analysis . It was originally designed to address the needs of the near real time applications community to provide relevant information for time-critical scenarios such as wildfire and flood management. As such, satellite imagery is available to be viewed in Worldview within four hours of observation, the imagery can be viewed in its highest, or native, resolution, and the imagery can be panned and zoomed rapidly through space and time to find the most relevant/cloud-free/etc information available.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa-gibs/worldview","license":null}},{"forgeId":"forge_nasa_gsc_17162_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-17162-1","sourceUrl":"https://software.nasa.gov/software/GSC-17162-1","confidence":"high"},"type":"software","title":"Open GeoSocial Consumer Application","abstract":"This software interface provides a social and collaborative environment to allow end-users such as GEOSS users to discover, visualize, and access Earth Science information on demand from simple browsers and allow them to share the resulting products with their friends and/or Community of Interest through social networks.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://opensource.gsfc.nasa.gov/projects/gsca/index.php","license":null}},{"forgeId":"forge_nasa_gsc_17169_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-17169-1","sourceUrl":"https://software.nasa.gov/software/GSC-17169-1","confidence":"high"},"type":"software","title":"Vectorization of Global Flood Monitoring System using Topojson","abstract":"This capability allows for the generation of vectors by reading the Global Flood Monitoring data, processing the data and generating aTopoJSON encoded file for visualization on the web.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://opensource.gsfc.nasa.gov/projects/vgfms/index.php","license":null}},{"forgeId":"forge_nasa_gsc_17173_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-17173-1","sourceUrl":"https://software.nasa.gov/software/GSC-17173-1","confidence":"high"},"type":"software","title":"MYSTRAN","abstract":"MYSTRAN is a Finite Element Analysis (FEA) processor. MYSTRAN takes NASTRAN data decks as input and processes them to generate results files based on the inputs. NASTRAN was originally developed at NASA GSFC in the 1960's. The input files describe the mechanical nature of some piece of hardware and the loads or driving inputs that cause some reaction. With this input MYSTRAN computes the responses to the driving inputs. The theory and research for FEA analysis has been developed over decades.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/dr-bill-c/MYSTRAN","license":null}},{"forgeId":"forge_nasa_gsc_17177_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-17177-1","sourceUrl":"https://software.nasa.gov/software/GSC-17177-1","confidence":"high"},"type":"software","title":"General Mission Analysis Tool (GMAT) v.R2016a","abstract":"The General Mission Analysis Tool (GMAT) is the worlds only enterprise, multi-mission, open source software system for space mission design, optimization, and navigation. The system supports missions in flight regimes ranging from low Earth orbit to lunar, libration point, and deep space missions. GMAT is developed by a team of NASA, private industry, public, and private contributors and is used for real-world mission support, engineering studies, as a tool for education, and public engagement.GMAT contains models of real world objects such as spacecraft and thrusters, and analysis \"objects\" such as propagators, plots, and reports. These objects are used in a mission sequence in which the user employs commands supported by the system to model mission events and perform estimation.For a complete list of new features, compatibility changes, and bug fixes, see the Release Notes. Below are just some of the new capabilities contained in this release. Production quality orbit determination (Operational Certification expected in November, 2016)Code 500 ephemeris propagatorSTK ephemeris file outputWrite command to save GMAT configurations during executionInclude macro to load GMAT configurations from external sources during executionMany new built in math functions and parameters130 pages of new user documentation","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://sourceforge.net/projects/gmat/files/GMAT/GMAT-R2016a/","license":null}},{"forgeId":"forge_nasa_gsc_17201_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-17201-1","sourceUrl":"https://software.nasa.gov/software/GSC-17201-1","confidence":"high"},"type":"software","title":"SpaceWire 2014","abstract":"SpaceWire is a spacecraft communication network based in part on the IEEE 1355 standard of communications. SpaceWire 2014, is an update to fix \"bugs\", improve performance, change the back-end user interface for different embedded applications to the original SpaceWire Link and Switch.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_17389_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-17389-1","sourceUrl":"https://software.nasa.gov/software/GSC-17389-1","confidence":"high"},"type":"software","title":"GLOBE Program's Data Entry App for iOS","abstract":"The Global Learning and Observations to Benefit the Environment (GLOBE) program is a worldwide hands-on, primary and secondary school-based science and education program. The GLOBE Program's Data Entry App for iOS, enables members to enter data to via their iOS devices and when in the field, where they may not have internet connection. Their data will be stored locally on their iOS devices and sent to the GLOBE database once their devices get connected to internet. This project also facilitates data entry by leveraging mobile capabilities including GPS, photography and date/time.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://itunes.apple.com/us/app/globe-data-entry/id980592274?ls=1&mt=8","license":null}},{"forgeId":"forge_nasa_gsc_17390_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-17390-1","sourceUrl":"https://software.nasa.gov/software/GSC-17390-1","confidence":"high"},"type":"software","title":"GLOBE Program's Data Entry App for Android","abstract":"The Global Learning and Observations to Benefit the Environment (GLOBE) program is a worldwide hands-on, primary and secondary school-based science and education program. The GLOBE Program's Data Entry App for Android, enables members to enter data to via their Android devices and when in the field, where they may not have internet connection. Their data will be stored locally on their Android devices and sent to the GLOBE database once their devices get connected to internet. This project also facilitates data entry by leveraging mobile capabilities including GPS, photography and date/time.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://play.google.com/store/apps/details?id=gov.nasa.globe.deapp&hl=en","license":null}},{"forgeId":"forge_nasa_gsc_17391_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-17391-1","sourceUrl":"https://software.nasa.gov/software/GSC-17391-1","confidence":"high"},"type":"software","title":"GLOBE Program's Citizen Science Cloud App for iOS","abstract":"GLOBE members currently enter their scientific data using a Data Entry tool on GLOBEs site. The GLOBE Cloud Data Entry App will allow non-GLOBE members and GLOBE members to enter cloud observations into their mobile device and send their observations to the GLOBE database. Users will be able to enter the data while the mobile device is not connected to the Internet, with data sent to GLOBE on user command when the device is on the Internet.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://itunes.apple.com/us/app/globe-observer/id1090456751?mt=8","license":null}},{"forgeId":"forge_nasa_gsc_17399_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-17399-1","sourceUrl":"https://software.nasa.gov/software/GSC-17399-1","confidence":"high"},"type":"software","title":"Earthdata Search Web Application","abstract":"Earthdata Search is a web application enabling users to quickly and intuitively discover, search, visualize, and access Earth Science data in a highly visual manner. It interfaces with and demonstrates current state-of-the-art services provided by NASA EOSDIS such as the Common Metadata Repository (CMR) for sub-second search results, the Global Imagery Browse Services (GIBS) for fast tiled imagery visualizations of data , and OPeNDAP for data access, transformation, and subsetting.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://search.earthdata.nasa.gov/","license":null}},{"forgeId":"forge_nasa_gsc_17537_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-17537-1","sourceUrl":"https://software.nasa.gov/software/GSC-17537-1","confidence":"high"},"type":"software","title":"core Flight Software (cFS) Stored Command Absolute (SCA) Application","abstract":"This software is a core Flight System (cFS) application that allows a system to be autonomously commanded via files that contain sequences of commands. Each command has a time tag associated with it, permitting the command to be released for distribution over the cFS core Flight Executive (cFE) Software Bus at predetermined times. The application allows up to 5 absolute-time sequences to be run simultaneously.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/SCA","license":null}},{"forgeId":"forge_nasa_gsc_17596_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-17596-1","sourceUrl":"https://software.nasa.gov/software/GSC-17596-1","confidence":"high"},"type":"software","title":"Network Management and Monitoring System for Delay- and Disruption-Tolerant Networks","abstract":"The Innovation is a software product that allows a user to manage and monitor a challenged network of remote nodes. The software provides users with information regarding the status of nodes, and users are able to send requests to the nodes and receive data back in response. The software provides Application Programming Interfaces (APIs) to allow creation of a Graphical User Interface (GUI) to provide a user with graphical views of incoming data as well as commanding functionality.Please contact opensource@gsfc.nasa.gov to obtain a copy of this code.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_17605_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-17605-1","sourceUrl":"https://software.nasa.gov/software/GSC-17605-1","confidence":"high"},"type":"software","title":"Hazards and Population Mapper (HazPop) Mobile Application for iOS Platform","abstract":"Hazards and Population Mapper (HazPop) is a free app Developed by the NASA Socioeconomic Data and Applications Center (SEDAC). The App enables users to easily display recent natural hazard data in relationship to population, major infrastructure, and satellite imagery. Hazards data include the location of active fires over the past 48 hours; earthquake alerts over the past seven days; and yesterdays air pollution data measured from space. The app shows the location of major dams and nuclear power plants and provides more detailed information and imagery for these facilities where available. By drawing a circle around a point or area of interest on the map, users can obtain an estimate of the total population and land area enclosed within.Available for download at: https://itunes.apple.com/us/app/hazards-population-mapper/id1092168898?mt=8","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://itunes.apple.com/us/app/hazards-population-mapper/id1092168898?mt=8","license":null}},{"forgeId":"forge_nasa_gsc_17610_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-17610-1","sourceUrl":"https://software.nasa.gov/software/GSC-17610-1","confidence":"high"},"type":"software","title":"Common Metadata Repository","abstract":"The Common Metadata Repository (CMR) is a spatial and temporal metadata registry that enables the science community to more easily discover, use, and exchange NASA's data and services. The CMR's main objective is to enable broader use of NASA's Earth observing systems' (EOSDIS) data . It allows users to more efficiently and reliably search and access data and services and increases the potential for interoperability with new tools and services. The CMR stores metadata from a variety of science disciplines and domains, including Climate Variability and Change, Carbon Cycle and Ecosystems, Earth Surface and Interior, Atmospheric Composition, Weather, and Water and Energy Cycle. To ensure the quality of the metadata, the CMR system contains a tool called the Metadata Management Tool (MMT) which enables metadata providers to develop standards-compliant, high-quality metadata and have that metadata scored against quality standards as well as providing a means to manage access to that metadata. CMR is designed to:- Serve as a middleware replacement for the EOS Clearing House (ECHO) and Global Change Master Directory (GCMD)s backend. - Handle metadata at the Concept level including: Collections, Granules, Visualizations, Parameters, Documentation, Services, and more.manage hundreds of millions of metadata records; making them available through high performance, standards compliant, temporal, spatial, and faceted search.- Incorporate both human and machine metadata assessment features that work to ensure the highest quality metadata possible.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://earthdata.nasa.gov/about/science-system-description/eosdis-components/common-metadata-repository","license":null}},{"forgeId":"forge_nasa_gsc_17628_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-17628-1","sourceUrl":"https://software.nasa.gov/software/GSC-17628-1","confidence":"high"},"type":"software","title":"NASA Visualization Explorer (NASA Viz) for Android","abstract":"NASA Visualization Explorer (NASA Viz) is an intuitive interactive Android application and an extension of the NASAViz iPad and iPhone versions*. The application delivers science stories with multimedia content linking high-quality explorable images, descriptive text, visualizations, videos and interviews with a fresh look and feel. App features include: credit information for each story, ability to share stories with social media and to create lists of stories that can be shared with other users, explore stories by keywords and search.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://play.google.com/store/apps/details?id=gov.nasa.gsfc.nasavizprod","license":null}},{"forgeId":"forge_nasa_gsc_17667_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-17667-1","sourceUrl":"https://software.nasa.gov/software/GSC-17667-1","confidence":"high"},"type":"software","title":"Analysis Software for Cosmic Microwave Background Research","abstract":"This is a suite of analysis tools for cosmic microwave background research. It currently consists of an implementation of the pure C_\\ell cosmic microwave background power spectrum estimator. It also includes an implementation of the mode-mixing matrix calculation as described in which allows the pure C_\\ell measurements to be compared to theoretical calculations.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa-lambda/cmb_analysis","license":null}},{"forgeId":"forge_nasa_gsc_17742_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-17742-1","sourceUrl":"https://software.nasa.gov/software/GSC-17742-1","confidence":"high"},"type":"software","title":"Fortran Template Library (gFTL) for managing collections of objects via software containers.","abstract":"This innovation creates the capability for Fortran software developers to routinely declare and use specialized software containers for arbitrary types of data . The capability is somewhat analogous to that of the C Standard Template Library but with important differences. Although the number of containers are expected to grow, the current supported cases are Vector, Map, and Set. Contained items can be of any intrinsic type or user-defined derived type. The user can also indicate that the contained objects are polymorphic and/or pointers with corresponding implications for the semantics of using those containers.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_17778_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-17778-1","sourceUrl":"https://software.nasa.gov/software/GSC-17778-1","confidence":"high"},"type":"software","title":"General Mission Analysis Tool (V. R2016a)","abstract":"The GMAT development team is pleased to announce the release of GMAT version R2016a. The General Mission Analysis Tool (GMAT) is the worlds only enterprise, multi-mission, open source software system for space mission design, optimization, and navigation. The system supports missions in flight regimes ranging from low Earth orbit to lunar, libration point, and deep space missions. GMAT is developed by a team of NASA, private industry, public, and private contributors and is used for real-world mission support, engineering studies, as a tool for education, and public engagement.For a complete list of new features, compatibility changes, and bug fixes, see the Release Notes. Below are just some of the new capabilities contained in this release. Production quality orbit determination (Operational Certification expected in November, 2016)Code 500 ephemeris propagatorSTK ephemeris file outputWrite command to save GMAT configurations during executionInclude macro to load GMAT configurations from external sources during executionMany new built in math functions and parameters130 pages of new user documentation","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://sourceforge.net/projects/gmat/files/GMAT/GMAT-R2016a/","license":null}},{"forgeId":"forge_nasa_gsc_17780_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-17780-1","sourceUrl":"https://software.nasa.gov/software/GSC-17780-1","confidence":"high"},"type":"software","title":"ICESat-2 Standard Data Products Subsetter","abstract":"This software was designed to subset ICESat-2 Standard Data Products. That is, it reads in a single HDF5 ICESat-2 data granule, and uses rules in a control file to reduce the set of prameters according to the rules in the control file, and writes out the resulting file. The purpose of the software is to (a) reduce the size of ICESat-2 Standard Data Product Granules and (b) reduce the number of parameters in an ICESat-2 Standard Data Product granule to those required by a data user. As each user's requirements will be different, the software can subset the granule in a variety of ways, using almost any parameter in the data file as a basis for subsetting.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://icesat-2.gsfc.nasa.gov/","license":null}},{"forgeId":"forge_nasa_gsc_17917_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-17917-1","sourceUrl":"https://software.nasa.gov/software/GSC-17917-1","confidence":"high"},"type":"software","title":"Constellation Visualization Tool","abstract":"The Constellation Visualization Tool (CVT) is a touchscreen interactive software tool, designed to model automated analyses of the Earth Observing System (EOS) Morning and Afternoon Constellations. These displays present data in a meaningful way through interactive visual displays that are intended to tell an interesting story, educate and inform users and the public about the missions NASA supports. Combining data presentation with user experience, user selected stories are brought to life, promoting awareness for NASA's mission of space exploration and scientific discovery.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_18012_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18012-1","sourceUrl":"https://software.nasa.gov/software/GSC-18012-1","confidence":"high"},"type":"software","title":"The Parallel Fortran Logger (pFlogger)","abstract":"The innovation is a software logging facility that is tailored to the needs of parallel Fortran software. The facility greatly simplifies the process of logging routine messages within a scientific simulation across multiple processes in a manner that is configurable at run time. Messages can be annotated with different severity levels such that low-level diagnostic information can be generally suppressed except when desired.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/Goddard-Fortran-Ecosystem/pFlogger","license":null}},{"forgeId":"forge_nasa_gsc_18031_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18031-1","sourceUrl":"https://software.nasa.gov/software/GSC-18031-1","confidence":"high"},"type":"software","title":"Perl 6 DBPg PostgreSQL module","abstract":"PostgreSQL (https://www.postgresql.org) is an Open Source Relational Database Management System (RDBMS). It includes a C library (libpq) for interacting with the server over the network (https://www.postgresql.org/docs/10/static/libpq.html).This module provides a rich interface to the PostgreSQL libpq library for Perl 6. It includes capabilities for prepared query caching, database connection caching, exception handling, flexible type conversion (including Boolean, Date, DateTime, Byte Arrays, etc. as well as custom types), bulk data copy in and out, listen/notify, transactions, and cursors for large query processing.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/CurtTilmes/perl6-dbpg","license":null}},{"forgeId":"forge_nasa_gsc_18094_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18094-1","sourceUrl":"https://software.nasa.gov/software/GSC-18094-1","confidence":"high"},"type":"software","title":"General Mission Analysis Tool (GMAT) Version R2018a","abstract":"The General Mission Analysis Tool (GMAT) is the world's only enterprise, multi-mission, open source software system for space mission design, optimization, and navigation. The system supports missions in flight regimes ranging from low Earth orbit to lunar, libration point, and deep spacemissions. GMAT is developed by a team of NASA, private industry, public, and private contributors and is used for real-world mission support, engineering studies, as a tool for education, and public engagement.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://sourceforge.net/projects/gmat/?source=navbar","license":null}},{"forgeId":"forge_nasa_gsc_18095_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18095-1","sourceUrl":"https://software.nasa.gov/software/GSC-18095-1","confidence":"high"},"type":"software","title":"Downloading and reformatting tool for NASA Earth observation data products","abstract":"This R software package (nasaaccess), is expandable.The 'nasaaccess' software package current version processes remote sensing data products (i.e., TRIMM, IMERG, and GLDAS) and creates weather input definition tables as well as stations data files in a format readable by earth science model. The package can be expanded to include other remote sensing products needed in future. For the time being (nasaaccess version 1.2) generates daily rainfall and minimum and maximum air temperatures gridded data and gridded data definition files needed to serve as a setup for any basic earth science hydrological model run. The climate time seriesoutputs are either at a pseudo grid located at the centeroid of the watershed provided or at grids within the specified watershed provided. The core functionality of the package is accessing GSFC servers to: download climate data, clip needed grids based on a user study watershed shapefile and DEM grid, handle temporal issues and then to generate daily climate gridded data files and definition files compatible with various hydrological models. The functions within the package ask the user for inputs which are: start and end dates for his climate data simulation , a shapefile for his studywatershed, and a DEM for his study watershed. The functions then output the gridded data ascii files and the definition files right at his desired working folder. The package has examples and detail explanation of the process being done (metadata is included).","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/NASAaccess","license":null}},{"forgeId":"forge_nasa_gsc_18115_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18115-1","sourceUrl":"https://software.nasa.gov/software/GSC-18115-1","confidence":"high"},"type":"software","title":"Core Flight System Simulink Interface Layer","abstract":"The Simulink Interface Layer (SIL) is a software abstraction layer which allows the interfacing of task/mission-specific code generated from Simulink (or other sources) to the Core Flight System (cFS) via a generic set of wrapper code. The SIL enables direct integration of code from the Simulink autocoding pipeline into the cFS without the need for interface code and allows access to cFS API's including table services, time services, the software bus, event services, and fault reporting. The SIL accomplishes this by extending Simulink's code generation pipeline to produce a description of the model's interfaces which is utilized by generic wrapper code to initialize the model and the appropriate cFS interfaces. The SIL simplifies the integration of code as a CFS application and eliminates the need for hand edits to generated code, allowing quicker integration of code and reducing the probability of human error in the integration process.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/SIL","license":null}},{"forgeId":"forge_nasa_gsc_18159_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18159-1","sourceUrl":"https://software.nasa.gov/software/GSC-18159-1","confidence":"high"},"type":"software","title":"Fortran Argument Parser","abstract":"The Fortran Argument Parser is a software package to simplify handling of command line arguments from within Fortran programs. The design is largely based upon a similar package in Python called argParser. These tools allow developers to specify expected command line arguments and associate each argument with a specific behavior. The package is extensible allowing developers to define new behaviors for their options.This package emerged from development of NASA's pFUnit framework for unit testing. The functionality would be valuable within other Fortran projects and therefore it is desired to pull the Fortran Argument Parser out as a software project of its own. The parser can then be used in a variety of projects in a light-weight manner.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/Goddard-Fortran-Ecosystem/fArgParse","license":null}},{"forgeId":"forge_nasa_gsc_18169_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18169-1","sourceUrl":"https://software.nasa.gov/software/GSC-18169-1","confidence":"high"},"type":"software","title":"Mixed Reality Engineering Toolkit (MRET)","abstract":"Create Augmented Reality (AR)/Virtual Reality (VR) tools for integrating spacecraft designs and real-time mission telemetry for multiple domains over a mission lifecycle:Pre-phase A concept design Hardware integration & test planning and executionTele-robotic operations","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_18208_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18208-1","sourceUrl":"https://software.nasa.gov/software/GSC-18208-1","confidence":"high"},"type":"software","title":"PointClouds VR","abstract":"Visualizes and manipulates point clouds from multiple scientific domains in virtual reality, including time-dependent point clouds. Point clouds can be colored by reflectance, natural color, elevation, or even mapping hyperspectral data to color channels. It can animate points forwards and backwards in time from calculations or by loading separate point cloud datasets as frames. It is able to visualize locations captured from LIDAR data , such as lava tubes scanned by planetary scientists, to allow revisiting field sites.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/PointCloudsVR","license":null}},{"forgeId":"forge_nasa_gsc_18318_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18318-1","sourceUrl":"https://software.nasa.gov/software/GSC-18318-1","confidence":"high"},"type":"software","title":"The Bundle Protocol Library","abstract":"The Bundle Protocol Library (bplib) implements a subset of the RFC5050 Bundle Protocol necessary for embedded space flight applications. The library uses the concept of a bundle channel to manage the process of encapsulating application data in bundles, and extracting application data out of bundles. A channel specifies how the bundles are created (e.g. primary block fields), and how bundles are processed. Bplib contains no threads and relies entirely on the calling application for its execution context, and implements a thread-safe synchronous I/O model where no call-backs are necessary and requested operations will either block according to the provided timeout, or return an error code immediately if the operation cannot be performed.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://www.github.com/nasa/bplib","license":null}},{"forgeId":"forge_nasa_gsc_18322_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18322-1","sourceUrl":"https://software.nasa.gov/software/GSC-18322-1","confidence":"high"},"type":"software","title":"Heat Analysis Manager (HAM), a Thermal Desktop API Based Heat Map Generation Software","abstract":"Thermal engineers often create custom heat maps to analyze their thermal models. However, generating a heat map is difficult because thermal simulations only readily provide certain attributes of simulated nodes, such as temperature, capacitance, and heat generation, along with a network of conductances. Heat flow values are quantities derived from these nodal attributes, and the difficulty in data processing and management of heat flow between nodes quickly grows as node count increases for large models. Deriving a network of heat flow values requires a vast amount of calculations and data handling, and the heat map generation process generally suffers from processing speed, loss of accuracy, and/or presentation of data in a clear and concise format. Heat Analysis Manager (HAM) is a Thermal Desktop (TD) based free multi-purpose tool developed to aid thermal engineers in analyzing thermal models which includes a heat map generation utility. HAMs heat map generator retains accuracy and fast processing speed by utilizing TDs application programming interface (API) and TDs built-in post-processor routine Qflow from Results. Furthermore, HAMs heat map output is presented in an easily customizable format in Excel, allowing users to create various custom visual heat maps. A full description of how HAM utilizes TDs API to create a customizable heat map is provided. A simple model demonstration is included along with step-by-step procedures for creating custom heat maps. HAMs heat map output has been verified against TD and other heat map generation software, and the verification methods used are shown.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_18331_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18331-1","sourceUrl":"https://software.nasa.gov/software/GSC-18331-1","confidence":"high"},"type":"software","title":"The Bundle Protocol Core Flight System Application (BP)","abstract":"The BP cFS application uses the Bundle Protocol Library (bplib) to implement Delay Tolerant Networking. The applicationtargets the cFE 6.5 release and provides out of the box integration with the cFS CFDP application (CF), and a POSIXcompliant file system when provided. The implementation conforms to the CCSDS Blue Book recommendation 734.2-B-1issued September 2015, which is based on RFC 5050.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":"https://aetd-git.gsfc.nasa.gov/RTAP/bpcfs","license":null}},{"forgeId":"forge_nasa_gsc_18375_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18375-1","sourceUrl":"https://software.nasa.gov/software/GSC-18375-1","confidence":"high"},"type":"software","title":"Second Generation Beacon Performance Analysis Test Tools","abstract":"NASA is building Spread Spectrum Second Generation Beacons (SGB) intended to comply with all Cospas-Sarsat T.018 requirements. NASA has built a set of test tools to evaluate the performance of the SGB. The tools use Digital Signal Processing (DSP) to analyze the transmit characteristics and demodulate the message.The test tools are written in MATLAB scripts.","category":"biomedical_health","categoryRaw":"crew and life support","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/Second-Generation-Beacon-Performance-Analysis-Test-Tools","license":null}},{"forgeId":"forge_nasa_gsc_18396_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18396-1","sourceUrl":"https://software.nasa.gov/software/GSC-18396-1","confidence":"high"},"type":"software","title":"core Flight Software (cFS) Software Bus Network Client","abstract":"The Software Bus Network Client communicates with the core Flight System (cFS) Software Bus Network (SBN) application. Its main purpose it to facilitate two-way communication from the cFS Software Bus service to an external application (i.e. an application that is not a child task of cFS). It implements the SBN communication protocol. The Software Bus Network Client provides the external application with all of the relevant Software Bus functionality without a separate cFS core. This is implemented as a C library and wrappers are provided so that existing cFS applications may use the library in place of the standard cFS Software Bus service.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/SBN-Client/","license":null}},{"forgeId":"forge_nasa_gsc_18399_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18399-1","sourceUrl":"https://software.nasa.gov/software/GSC-18399-1","confidence":"high"},"type":"software","title":"Trade-space Analysis Tool for designing Constellations (TAT-C) - Version 2.0","abstract":"Trade-space Analysis Tool for designing Constellations (TAT-C) - Version 2.0","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_18408_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18408-1","sourceUrl":"https://software.nasa.gov/software/GSC-18408-1","confidence":"high"},"type":"software","title":"Goddard Enhanced Onboard Navigation System (GEONS) V3.0","abstract":"The National Aeronautics and Space Administration (NASA) Goddard Space Flight Center (GSFC) has developed the capability to provide high-accuracy orbit and time autonomously onboard NASA spacecraft. The GSFC Mission Engineering and Systems Analysis Division has implemented NASA-developed navigation algorithms for high-accuracy real-time onboard orbit determination in the Goddard Enhanced Onboard Navigation System (GEONS) flight software. The GEONS flight software is flight proven, currently providing onboard orbit determination (OD) for the Global Precipitation Mission (GPM) and the Magnetospheric Multiscale Mission (MMS). GEONS processes many measurement types to estimate the orbital states of one of or more satellites using an extended Kalman filter orbit determination algorithm.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_18448_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18448-1","sourceUrl":"https://software.nasa.gov/software/GSC-18448-1","confidence":"high"},"type":"software","title":"cFS Data Storage (DS) application version 2.5.2","abstract":"The Data Storage (DS) application is one of the reusable applications that is used with the Core Flight System (cFS) framework. DS manages the storing of data on-board a spacecraft for later transmission to the ground.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/DS","license":null}},{"forgeId":"forge_nasa_gsc_18449_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18449-1","sourceUrl":"https://software.nasa.gov/software/GSC-18449-1","confidence":"high"},"type":"software","title":"Core Flight System (cFS) Housekeeping (HK) Application version 2.4.2","abstract":"The Housekeeping (HK) application is one of the reusable applications that can be used with the Core Flight System (cFS) framework. HK provides the capability to take pieces of data from multiple messages and create a new message. This is very important for bandwidth constrained missions.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/HK","license":null}},{"forgeId":"forge_nasa_gsc_18450_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18450-1","sourceUrl":"https://software.nasa.gov/software/GSC-18450-1","confidence":"high"},"type":"software","title":"Core Flight Software System (CFS) Memory Dwell Application Version 2.3.2","abstract":"The Memory Dwell application (MD) is a core Flight System (cFS) application that is a plug in to the Core Flight Executive (cFE) component of the cFS. The MD application monitors memory addresses accessed by the CPU.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/MD/","license":null}},{"forgeId":"forge_nasa_gsc_18459_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18459-1","sourceUrl":"https://software.nasa.gov/software/GSC-18459-1","confidence":"high"},"type":"software","title":"Evolutionary Mission Trajectory Generator (EMTG) v9","abstract":"The Evolutionary Mission Trajectory Generator (EMTG) version 9 is a scalable-fidelity optimization package for spacetrajectory design. EMTGv9 is suitable for trade studies, sensitivity analysis , and serves as an initial guess generator for aflight fidelity tool. EMTGv9 can design missions using high-thrust chemical propulsion or low-thrust electric propulsion.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/EMTG","license":null}},{"forgeId":"forge_nasa_gsc_18475_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18475-1","sourceUrl":"https://software.nasa.gov/software/GSC-18475-1","confidence":"high"},"type":"software","title":"Core Flight Software System (CFS) File Manager Application Version 2.5.3","abstract":"The File Manager application (FM) is a core Flight System (cFS) application that is a plug in to the Core Flight Executive (cFE) component of the cFS. The FM application provides onboard file system management services by processing ground commands for copying, moving, and renaming files, decompressing files, creating directories, deleting files and directories, providing file and directory informational telemetry messages, and providing open file and directory listings.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/FM/","license":null}},{"forgeId":"forge_nasa_gsc_18476_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18476-1","sourceUrl":"https://software.nasa.gov/software/GSC-18476-1","confidence":"high"},"type":"software","title":"Core Flight System (cFS) Health & Safety (HS) Application version 2.3.2","abstract":"The Health and Safety application (HS) is a core Flight System (cFS) application that is a plug in to the Core Flight Executive (cFE) component of the cFS. The HS application provides functionality for Application Monitoring , Event Monitoring , Hardware Watchdog Servicing, Execution Counter Reporting (optional), and CPU Aliveness Indication (via UART).","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/HS","license":null}},{"forgeId":"forge_nasa_gsc_18546_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18546-1","sourceUrl":"https://software.nasa.gov/software/GSC-18546-1","confidence":"high"},"type":"software","title":"SWPC CAT Web Tool","abstract":"The SWPC CME Analysis Tool Web (SWPC-CAT-Web) tool is an online version of the original SWPC CME Analysis (SWPC-CAT) Tool that was written in IDL. The SWPC CAT Web tool is developed by the Community Coordinated Modeling Center (CCMC) at GSFC. The original SWPC CAT tool is developed by the NOAA Space Weather Prediction Center (SWPC). It is the primary tool being used by NOAA SWPC in measuring key parameters of a Coronal Mass Ejection (CME) as it emerges from the solar corona. At CCMC, we have re-written the backend IDL version of SWPC_CAT in python. We have also implemented a front-end interface all in python and made it into a web application. Now, any user who is interested in using the tool can do so with an internet connection and a web browser.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/ccmc-swpc-cat-web","license":null}},{"forgeId":"forge_nasa_gsc_18595_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18595-1","sourceUrl":"https://software.nasa.gov/software/GSC-18595-1","confidence":"high"},"type":"software","title":"Landslide Hazard Assessment for Situational Awareness (LHASA) version 2.0","abstract":"In order to advance LHASAs capabilities to characterize landslide hazards and impactsdynamically, we have implemented a new approach that leverages machine learning , newparameters, and new inventories. LHASA 2.0 uses the XGBoost machine learning model to bring indynamic variables as well as additional static variables to better represent landslide hazardglobally. Global rainfall forecasts are also being evaluated to provide a 1-3 day forecast of potentiallandslide activity. Additional factors such as recent seismicity and burned areas are also beingconsidered to represent the preconditioning or changing interactions with subsequent rainfallover affected areas.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/lhasa","license":null}},{"forgeId":"forge_nasa_gsc_18602_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18602-1","sourceUrl":"https://software.nasa.gov/software/GSC-18602-1","confidence":"high"},"type":"software","title":"Mixed Reality Exploration Toolkit (MRET) v2.0","abstract":"The Mixed Reality Exploration Toolkit (MRET) framework/platform advances NASA engineering and scientific efforts byleveraging industry advances in virtual reality (VR) and augmented reality (AR) technology to use NASA data and tools in new and innovative ways. MRET provides cross-domain, mission lifecycle support by integrating NASA models (both scientific models and engineering CAD-based models) with a common tool set available in AR/VR (e.g., measurement tools and lunar and planetary lighting models) and access to NASA data sources. MRET leverages the GSFC developed GMSEC tools to integrate real-time and recorded engineering (telemetry) data from multiple engineering sources to stimulate visualizations as well as provide collaboration within the NASA networks. Integration with other scientific data formats and sources is planned to serve the GSFC and NASA scientific community.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/Mixed-Reality-Exploration-Toolkit","license":null}},{"forgeId":"forge_nasa_gsc_18662_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18662-1","sourceUrl":"https://software.nasa.gov/software/GSC-18662-1","confidence":"high"},"type":"software","title":"Memory Manager Application version 2.4.2","abstract":"The Memory Manager (MM) application is one of the reusable applications that make up the Core Flight System (cFS). MM is responsible for the loading and dumping of flight system memory which can be a very useful tool when trying to diagnose a failure. Memory manager provides the ability to load and dump memory via commands as well as from files. If the underlying operating system supports symbolic addressing, Memory Manager supports specifying the memory address using a symbolic address.MM version 2.4.2 provides fixes to bugs in the previous version of the app and compatibility with cFE version 6.8.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/mm","license":null}},{"forgeId":"forge_nasa_gsc_18702_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18702-1","sourceUrl":"https://software.nasa.gov/software/GSC-18702-1","confidence":"high"},"type":"software","title":"Stored Command Application version 3.0","abstract":"The Stored Command (SC) application is one of the reusable applications that make up the Core Flight System (cFS). SC provides an onboard scripting feature. SC version 3.0 is modification of the existing application, but includes a breaking change that will prevent existing tables from being used with the new version of the application.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/sc","license":null}},{"forgeId":"forge_nasa_gsc_18703_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18703-1","sourceUrl":"https://software.nasa.gov/software/GSC-18703-1","confidence":"high"},"type":"software","title":"dorado-sensitivity","abstract":"Dorado is a proposed space mission for ultraviolet follow-up of gravitational wave events. This repository contains a simple sensitivity and exposure time calculator for Dorado.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/dorado-sensitivity","license":null}},{"forgeId":"forge_nasa_gsc_18719_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18719-1","sourceUrl":"https://software.nasa.gov/software/GSC-18719-1","confidence":"high"},"type":"software","title":"cFS Framework","abstract":"The core Flight System (cFS) is the first and only community-developed, reusable, platform-independent embedded software framework. cFS enables embedded software engineers to innovate and quickly transition from concept to implementation through a carefully designed layered architecture that isolates software applications from the operating system and hardware platform.The Bootes release of the cFS framework is composed of the following layers, example implementations and tools:### Layers1. core Flight Executive (cFE), Version 6.82. Operating system abstraction layer (OSAL), Version 5.13. Platform support package, Version 1.5### Example Implementations1. Telemetry Output Lab (to_lab), Version 2.42. Command Ingest Lab (ci_lab), Version 2.43. Scheduler Lab (sch_lab), Version 2.44. Sample App, Version 1.25. Sample Lib, Version 1.2### Tools1. cFS-GroundSystem, Version 2.22. ELF to cFE Table Converter (elf2cfetbl), Version 3.2.03. Table CRC Generator, (tblCRCTool), Version 1.1.0","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/cfs","license":null}},{"forgeId":"forge_nasa_gsc_18758_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18758-1","sourceUrl":"https://software.nasa.gov/software/GSC-18758-1","confidence":"high"},"type":"software","title":"Goddard Image Analysis and Navigation Tool (GIANT)","abstract":"The Goddard Image Analysis and Navigation Tool (GIANT) is an API for performing various kinds of optical navigation (OpNav) through python scripts. It provides the necessary tools for the most common OpNav tasks, including geometric camera calibration, camera attitude estimation, target center finding, surface feature navigation, and more and makes it easy to add new capabilities through the modular components it exposes. GIANT is mature and flight proven, having been used throughout the OSIRIS-REx mission in an independent verification and validation (IV&V) role with great success.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/giant","license":null}},{"forgeId":"forge_nasa_gsc_18784_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18784-1","sourceUrl":"https://software.nasa.gov/software/GSC-18784-1","confidence":"high"},"type":"software","title":"Orbit Determination Toolbox R2020a (v8.1)","abstract":"The Orbit Determination Toolbox (ODTBX) R2020a (v8.1) is an advanced mission simulation and analysis tool used for concept exploration, proposal, early design phase, or rapid design center environments; the emphasis is on flexibility but it has enough fidelity to produce credible results. ODTBX v8.1 includes multiple feature additions, enhancements, and bug fixes from the prior release. The primary user interface and supporting functions are written in Matlab and Java.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://sourceforge.net/projects/odtbx/","license":null}},{"forgeId":"forge_nasa_gsc_18815_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18815-1","sourceUrl":"https://software.nasa.gov/software/GSC-18815-1","confidence":"high"},"type":"software","title":"dorado-streamlit","abstract":"This repository contains observer web tools for the Dorado mission , including an interactive exposure time calculator. It is built using Streamlit, a framework for easily turning Python code into interactive data-driven web apps.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/dorado-streamlit","license":null}},{"forgeId":"forge_nasa_gsc_18847_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18847-1","sourceUrl":"https://software.nasa.gov/software/GSC-18847-1","confidence":"high"},"type":"software","title":"Mixed Reality Exploration Toolkit (MRET) 2021","abstract":"The Mixed Reality Exploration Toolkit (MRET) framework/platform advances NASA engineering and scientific efforts by leveraging industry advances in virtual reality (VR) and augmented reality (AR) technology to use NASA data and tools in new and innovative ways. MRET provides cross-domain, mission lifecycle support by integrating NASA models (both scientific models and engineering CAD-based models) with a common tool set available in AR/VR (e.g., measurement tools and lunar and planetary lighting models) and access to NASA data sources. MRET leverages the GSFC developed GMSEC tools to integrate real-time and recorded engineering (telemetry) data from multiple engineering sources to stimulate visualizations as well as provide collaboration within the NASA networks. Integration with other scientific data formats and sources is planned to serve the GSFC and NASA scientific community.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/Mixed-Reality-Exploration-Toolkit","license":null}},{"forgeId":"forge_nasa_gsc_18900_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18900-1","sourceUrl":"https://software.nasa.gov/software/GSC-18900-1","confidence":"high"},"type":"software","title":"A convenient and flexible satellite data spatial-temporal collocation system","abstract":"Data collocation is often a critical initial step in many remote sensing applications to fuse data from multiple instruments. Here we are intent on providing users a convenient and flexible approach to collocate data from arbitrary sensors and/or platforms based on their own requirements.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/AI-4-atmosphere-remote-sensing/satellite_collocation/","license":null}},{"forgeId":"forge_nasa_gsc_18907_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18907-1","sourceUrl":"https://software.nasa.gov/software/GSC-18907-1","confidence":"high"},"type":"software","title":"Mixed Reality Exploration Toolkit (MRET) 2021.3","abstract":"The Mixed Reality Exploration Toolkit (MRET) framework/platform advances NASA engineering and scientific efforts by leveraging industry advances in virtual reality (VR) and augmented reality (AR) technology to use NASA data and tools in new and innovative ways. MRET provides cross-domain, mission lifecycle support by integrating NASA models (both scientific models and engineering CAD-based models) with a common tool set available in AR/VR (e.g., measurement tools and lunar and planetary lighting models) and access to NASA data sources. MRET leverages the GSFC developed GMSEC tools to integrate real-time and recorded engineering (telemetry) data from multiple engineering sources to stimulate visualizations as well as provide collaboration within the NASA networks. Integration with other scientific data formats and sources is planned to serve the GSFC and NASA scientific community.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/Mixed-Reality-Exploration-Toolkit","license":null}},{"forgeId":"forge_nasa_gsc_18917_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18917-1","sourceUrl":"https://software.nasa.gov/software/GSC-18917-1","confidence":"high"},"type":"software","title":"cFS Data Storage (DS) application version 2.6.0","abstract":"The Data Storage (DS) application is one of the reusable applications that is used with the Core Flight System (cFS) framework. DS manages the storing of data on-board a spacecraft for later transmission to the ground.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/ds","license":null}},{"forgeId":"forge_nasa_gsc_18918_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18918-1","sourceUrl":"https://software.nasa.gov/software/GSC-18918-1","confidence":"high"},"type":"software","title":"Core Flight Software System (CFS) File Manager Application Version 2.6.0","abstract":"The File Manager (FM) application is one of the reusable applications that make up the Core Flight System (cFS). FM provides the user interface to the on-board file system.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/fm","license":null}},{"forgeId":"forge_nasa_gsc_18919_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18919-1","sourceUrl":"https://software.nasa.gov/software/GSC-18919-1","confidence":"high"},"type":"software","title":"Core Flight System (cFS) Housekeeping (HK) Application version 2.5.0","abstract":"The Housekeeping (HK) application is one of the reusable applications that can be used with the Core Flight System (cFS) framework. HK provides the capability to take pieces of data from multiple messages and create a new message. This is very important for bandwidth constrained missions.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/hk","license":null}},{"forgeId":"forge_nasa_gsc_18920_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18920-1","sourceUrl":"https://software.nasa.gov/software/GSC-18920-1","confidence":"high"},"type":"software","title":"Core Flight System (cFS) Health & Safety (HS) Application version 2.4.0","abstract":"The Health and Safety (HS)application is one of the reusable applications that make up the Core Flight Software System (cFS). HS monitors the health of the flight software system.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/hs","license":null}},{"forgeId":"forge_nasa_gsc_18921_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18921-1","sourceUrl":"https://software.nasa.gov/software/GSC-18921-1","confidence":"high"},"type":"software","title":"cFS Limit Checker Application version 2.2.0","abstract":"The Limit Checker application is one of the reusable applications that make up the Core Flight System(CFS). Limit Checker monitors telemetry data points in the flight system and compares the values against predefined or computed threshold limits. When a threshold condition is encountered, an event message is issued and a command script may be initiated to respond to the threshold violation.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/lc","license":null}},{"forgeId":"forge_nasa_gsc_18922_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18922-1","sourceUrl":"https://software.nasa.gov/software/GSC-18922-1","confidence":"high"},"type":"software","title":"Core Flight System (cFS) Memory Dwell Application Version 2.4.0","abstract":"The Memory Dwell (MD) application is one of the reusable applications that make up the Core Flight System (cFS). MD provides the capability of dwelling on an address or range of addresses on a flight system which can be very useful tool when trying to diagnose a failure. If the Operating system supports symbolic addressing, Memory Dwell supports specifying the memory address using a symbolic address.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/md","license":null}},{"forgeId":"forge_nasa_gsc_18923_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18923-1","sourceUrl":"https://software.nasa.gov/software/GSC-18923-1","confidence":"high"},"type":"software","title":"Core Flight System (cFS) Memory Manager Application version 2.5.0","abstract":"The Memory Manager (MM) application is one of the reusable applications that make up the Core Flight System (cFS). MM is responsible for the loading and dumping of flight system memory which can be a very useful tool when trying to diagnose a failure. Memory manager provides the ability to load and dump memory via commands as well as from files. If the underlying operating system supports symbolic addressing, Memory Manager supports specifying the memory address using a symbolic address.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/mm","license":null}},{"forgeId":"forge_nasa_gsc_18924_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18924-1","sourceUrl":"https://software.nasa.gov/software/GSC-18924-1","confidence":"high"},"type":"software","title":"Core Flight System (cFS) Stored Command Application version 3.1.0","abstract":"The Stored Command (SC) application is one of the reusable applications that make up the Core Flight System (cFS). SC provides an onboard scripting feature.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/sc","license":null}},{"forgeId":"forge_nasa_gsc_18985_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-18985-1","sourceUrl":"https://software.nasa.gov/software/GSC-18985-1","confidence":"high"},"type":"software","title":"Pan Galactic Engineering Framework, 3.0","abstract":"The Pan Galactic Engineering Framework provides a desktop client with a network interface and a network-accessible repository service that together implement a collaborative Model-Based Engineering (MBE) capability. Its initial implementation goal is to support a concurrent conceptual design process for engineering and science teams developing early phase space mission designs.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/waterbug/pangalactic.core","license":null}},{"forgeId":"forge_nasa_gsc_19020_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19020-1","sourceUrl":"https://software.nasa.gov/software/GSC-19020-1","confidence":"high"},"type":"software","title":"A deep learning software package for cloud and aerosol classification from multi- satellite data","abstract":"Classifying cloud and aerosol types from passive sensors is an important application in satellite remote sensing due to its wide spatial coverage. Here, we provide an end-to-end deep learning based domain adaptation approach to learn domain/sensor-invariant feature representation to classify cloud and aerosol types from passive sensors by learning from active and passive satellite remote sensing data.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/AI-4-atmosphere-remote-sensing/cloud-phase-prediction","license":null}},{"forgeId":"forge_nasa_gsc_19097_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19097-1","sourceUrl":"https://software.nasa.gov/software/GSC-19097-1","confidence":"high"},"type":"software","title":"General Mission Analysis Tool (GMAT) Version R2022a","abstract":"The General Mission Analysis Tool (GMAT) is the world's only enterprise, multi-mission, open source software system for space mission design, optimization, and navigation. The system supports missions in flight regimes ranging from low Earth orbit to lunar, libration point, and deep space missions. GMAT is developed by a team of NASA, private industry, public, and private contributors and is used for real-world mission support, engineering studies, as a tool for education, and public engagement.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://sourceforge.net/projects/gmat","license":null}},{"forgeId":"forge_nasa_gsc_19106_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19106-1","sourceUrl":"https://software.nasa.gov/software/GSC-19106-1","confidence":"high"},"type":"software","title":"Mixed Reality Exploration Toolkit (MRET) 2022","abstract":"The Mixed Reality Exploration Toolkit (MRET) framework/platform advances NASA engineering and scientific efforts by leveraging industry advances in virtual reality (VR) and augmented reality (AR) technology to use NASA data and tools in new and innovative ways. MRET provides cross-domain, mission lifecycle support by integrating NASA models (both scientific models and engineering CAD-based models) with a common tool set available in AR/VR (e.g., measurement tools and lunar and planetary lighting models) and access to NASA data sources. MRET leverages the GSFC developed GMSEC tools to integrate real-time and recorded engineering (telemetry) data from multiple engineering sources to stimulate visualizations as well as provide collaboration within the NASA networks. Integration with other scientific data formats and sources is planned to serve the GSFC and NASA scientific community.This version includes Project Overview Refactoring, Autosave, User Controlled Explode View, Avatar System, NASA IoT Integration, UMD Bug Fix and Improvement, and XML Improvements","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/Mixed-Reality-Exploration-Toolkit","license":null}},{"forgeId":"forge_nasa_gsc_19108_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19108-1","sourceUrl":"https://software.nasa.gov/software/GSC-19108-1","confidence":"high"},"type":"software","title":"A deep learning software package for 3-D cloud microphysical and optical property retrieval","abstract":"Retrieving cloud microphysics or optical properties from cloud reflectance is an important problem. We develop a deep learning based approaches to solve this problem.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/AI-4-atmosphere-remote-sensing/DL_3d_cloud_retrieval","license":null}},{"forgeId":"forge_nasa_gsc_19110_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19110-1","sourceUrl":"https://software.nasa.gov/software/GSC-19110-1","confidence":"high"},"type":"software","title":"gigatraj - an atmospheric trajectory model","abstract":"Gigatraj is software that implements an atmospheric trajectory model. Gigatraj is intended for use by atmospheric scientists studying the upper troposphere and lower stratosphere.It is written in C++, with a set of classes that allow for users to select data sources, interpolation methods, integration methods,etc. It can be run in serial mode on a single processor, or it can be run in a multiprocessing environment.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/gigatraj","license":null}},{"forgeId":"forge_nasa_gsc_19143_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19143-1","sourceUrl":"https://software.nasa.gov/software/GSC-19143-1","confidence":"high"},"type":"software","title":"CCMC CAMEL Validation Skill Scores Library","abstract":"CCMC Validation Skill Scores Library is part of the overall CAMEL framework. The library of skill score calculation is used for calcuting various types of skill scores with the purpose of comparing observation data with model output within the heliophysics community.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/camel","license":null}},{"forgeId":"forge_nasa_gsc_19152_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19152-1","sourceUrl":"https://software.nasa.gov/software/GSC-19152-1","confidence":"high"},"type":"software","title":"Metadata Extract and Access Database (MEAD)","abstract":"Defines a protocol for inserting and querying metadata from multiple database sources to aide in data discovery when performing data processing. It also defines an application programming interface (API) for interacting with a simple reference implementation of the protocol to demonstrate its usage.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://gitlab.modaps.eosdis.nasa.gov/infrastructure/APS/mead","license":null}},{"forgeId":"forge_nasa_gsc_19159_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19159-1","sourceUrl":"https://software.nasa.gov/software/GSC-19159-1","confidence":"high"},"type":"software","title":"Pinpoint","abstract":"Pinpoint is a utility to generalize the location of data . This allows for the storage infrastructure to morph over time and utilize new technologies while data access for users remains consistent.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://gitlab.modaps.eosdis.nasa.gov/infrastructure/peta-pebibyte/pinpoint","license":null}},{"forgeId":"forge_nasa_gsc_19165_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19165-1","sourceUrl":"https://software.nasa.gov/software/GSC-19165-1","confidence":"high"},"type":"software","title":"The On-Board Artificial Intelligence Research (OnAIR) Platform","abstract":"The On-board Artificial Intelligence Research (OnAIR) Platform is a software framework that enables researchers to experiment with artificial intelligence algorithms in a simulated flight software environment. OnAIR integrates with NASA's open source core Flight System (cFS): OnAIR is launched as a cFS application and is able to send and receive software bus messages. The OnAIR platform supports Python, which allows access to leading Artificial Intelligence research tools and libraries. The OnAIR Platform is intended to be used by Artificial Intelligence researchers that are exploring applying Artificial Intelligence research to the flight software domain in a simulated environment. For example, a researcher may use the OnAIR Platform to develop a proof of concept demonstrating that a specialized technique can diagnose satellite faults in a simulated environment. OnAIR does not provide real satellite telemetry, algorithms for spacecraft control , or command and telemetry processing. The interface with and control of the simulated spacecraft is handled by NASA's cFS.NOTE: OnAIR does not include any Artificial Intelligence algorithms. It is a platform that strings together existing functionality; it is unable to diagnose faults or test satellite functionality.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/OnAIR","license":null}},{"forgeId":"forge_nasa_gsc_19237_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19237-1","sourceUrl":"https://software.nasa.gov/software/GSC-19237-1","confidence":"high"},"type":"software","title":"Software Reader for the Copernicus Global 90m Digital Elevation Model (DEM)","abstract":"The software uses command line input of the latitude and longitude geographic coordinates, accesses the Copernicus Global (GLO) 90 m digital elevation model (DEM) cloud optimized GeoTIFF data available within the AWS Cloud, processes these files to geolocate the pixel closest to the provided coordinates and returns the surface elevation in meters. This code was developed in Python and it could be used for algorithm development and production applications.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://gitlab.aps.smce.nasa.gov/aos/utilities/aos-dem-api","license":null}},{"forgeId":"forge_nasa_gsc_19299_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19299-1","sourceUrl":"https://software.nasa.gov/software/GSC-19299-1","confidence":"high"},"type":"software","title":"exoVista: Planetary System Generator for Exoplanet Studies","abstract":"exoVista is scientific software that allows users to generate fictitious planetary systems around nearby stars. These modeled systems contain the stellar spectra as a function of time, planetary spectra and positions as a function of time, and synthetic images of modeled exozodiacal disks as a function of wavelength.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/alexrhowe/ExoVista","license":null}},{"forgeId":"forge_nasa_gsc_19327_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19327-1","sourceUrl":"https://software.nasa.gov/software/GSC-19327-1","confidence":"high"},"type":"software","title":"Space geodesy data analysis software suite","abstract":"Space geodesy data analysis software suite (SGDASS) is a collectionof software programs with the primary goal of analysis of verylong baseline interferometry (VLBI) observations.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://gcc02.safelinks.protection.outlook.com/?url=https%3A%2F%2Fgithub.com%2Fnasa%2Fsgdass&data=05%7C02%7Cstaci.l.steward%40nasa.gov%7Cadef202ed5f14348448008dd4557b9bf%7C7005d45845be48ae8140d43da96dd17b%7C0%7C0%7C638742965251283400%7CUnknown%7CTWFpbGZsb3d8eyJFbXB0eU1hcGkiOnRydWUsIlYiOiIwLjAuMDAwMCIsIlAiOiJXaW4zMiIsIkFOIjoiTWFpbCIsIldUIjoyfQ%3D%3D%7C0%7C%7C%7C&sdata=sHYGH%2FmD9F60b3viaMtKcsHsP%2BaNrcZSt94YJDSbP3s%3D&reserved=0","license":null}},{"forgeId":"forge_nasa_gsc_19332_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19332-1","sourceUrl":"https://software.nasa.gov/software/GSC-19332-1","confidence":"high"},"type":"software","title":"Satellite Precipitation Estimate Error Detector (SPEEDe)","abstract":"SPEEDe is an anomaly detection scheme for quality control of satellite precipitation data. It can identify precipitation fields with unphysical data outside the expected range of performance because of instrument malfunction, incorrect data handling, and/or algorithm issues. SPEEDe is a machine learningbased command line code written in Python.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/JacksonTanBS/SPEEDe","license":null}},{"forgeId":"forge_nasa_gsc_19380_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19380-1","sourceUrl":"https://software.nasa.gov/software/GSC-19380-1","confidence":"high"},"type":"software","title":"Evolutionary Mission Trajectory Generator (EMTG) v9.02","abstract":"The Evolutionary Mission Trajectory Generator (EMTG) version 9.02 is a scalable-fidelity optimization package for space trajectory design. EMTGv9 is suitable for trade studies, sensitivity analysis , and serves as an initial guess generator for a flight fidelity tool. EMTG can design missions using high-thrust chemical propulsion or low-thrust electric propulsion. Included in this release is the Python EMTG Automated Trade Study Application (PEATSA) for trade analysis .","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/EMTG","license":null}},{"forgeId":"forge_nasa_gsc_19381_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19381-1","sourceUrl":"https://software.nasa.gov/software/GSC-19381-1","confidence":"high"},"type":"software","title":"Goddard Image Analysis and Navigation Tool","abstract":"The Goddard Image Analysis and Navigation Tool (GIANT) is an optical navigation (OpNav) tool suite for generating precision navigation products from images for use in orbit determination (OD) tools. Optical Navigation measurements provide highly accurate relative information between a spacecraft and a celestial body that enables science and engineering tasks which are unattainable using traditional radiometric tracking techniques alone. As mission concepts become more advanced, optical navigation will continue to become a necessary component of the navigation toolbox. GIANT is being developed and maintained to provide a single simple interface for generating these products that is OD software and mission agnostic. It has been successfully used throughout OSIRIS-REx proximity operations as well as for mission planning for OSIRIS-APEx and other mission concepts. GIANT was designed from the ground up to make precision OpNav easy and fast. It provides efficient implementations of the current state-of-the-art OpNav techniques while maintaining extensibility to allow easy addition of future techniques. In addition, GIANT is written in the Python interpreted language, making the code accessible and the routines easy to understand. GIANT can perform numerous types of OpNav, including optical camera calibration, attitude estimation, relative navigation with respect to an unresolved body, relative navigation with respect to a resolved body, opportunistic feature matching between images, surface feature navigation, surface coverage analysis , and autonomous detection and tracking of particles in monocular images. It is capable of observing multiple bodies in a single image and makes use of an efficient and flexible ray tracer. GIANT is being continuously developed to maintain the ability to utilize the state-of-the-art OpNav techniques. Version 2.0 of GIANT adds novel capabilities to the GIANT software library, including a redesigned ray tracer able to make use of certain GPU hardware, a new visual odometry measurement capability, novel TRN measurement techniques, improved coverage analysis tools, and improved documentation and tutorials.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_19382_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19382-1","sourceUrl":"https://software.nasa.gov/software/GSC-19382-1","confidence":"high"},"type":"software","title":"cFS Goddard Image Analysis and Navigation Tool (cGIANT)","abstract":"Optical navigation (OpNav) is a technique whereby cameras (both monocular and 3D) are used to generate relative navigation measurements between an observed object and the camera. These relative measurements are very powerful for navigation purposes, especially when navigating with respect to the object observed. The Core Flight System (cFS) Goddard Image Analysis and Navigation Tool (cGIANT) is an onboard library for use with cFS applications that provides the ability to perform various types of optical navigation, including terrain relative navigation, limb-based navigation, unresolved center finding, and resolved center finding. cGIANT builds upon the algorithms developed in the python based GIANT, keeping the same design decisions making it both capable for common tasks and easily extensible for new methods. cGIANT serves as the OpNav capabilities for the autonomous navigation, guidance, and control (autoNGC) suite of cFS applications.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_19383_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19383-1","sourceUrl":"https://software.nasa.gov/software/GSC-19383-1","confidence":"high"},"type":"software","title":"ngc_trn (autoNGC Terrain Relative Navigation Application)","abstract":"Terrain relative navigation is a technique where observations of natural terrain using a camera is used to help navigate a spacecraft with respect to the observed terrain. In the autonomous navigation, guidance, and control system (autoNGC), this process is performed using ngc_trn, a core Flight System (cFS) application which uses cGIANT to perform surface feature based terrain relative navigation. ngc_trn acts as both an interface and command layer, by formatting and receiving/transmitting incoming and outgoing data, by setting up cGIANT, and by making the appropriate cGIANT calls.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_19385_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19385-1","sourceUrl":"https://software.nasa.gov/software/GSC-19385-1","confidence":"high"},"type":"software","title":"Ephemeris Library (autoNGC library for managing ephemerides, covariance information, and attitude information)","abstract":"The ephemeris library provides functionality for storing and querying historical, current, and future ephemeris, covariance, and attitude information. It is implemented as a flight software library capable of running within the core flight system (cFS) as part of the autonomous guidance, navigation and control (autoNGC) suite of applications and libraries.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_19390_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19390-1","sourceUrl":"https://software.nasa.gov/software/GSC-19390-1","confidence":"high"},"type":"software","title":"SI_Cam (autoNGC Camera Sensor Ingest Application)","abstract":"The autoNGC Sensor Ingest - Camera (SI_Cam) application is an app for the cFS flight software framework that enables autoNGC to interface with either a hardware or software-simulated camera.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_19392_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19392-1","sourceUrl":"https://software.nasa.gov/software/GSC-19392-1","confidence":"high"},"type":"software","title":"SI_GPS (autoNGC GPS Sensor Ingest Application)","abstract":"The autoNGC Sensor Ingest - GPS (SI_GPS) application is an app for the cFS flight software framework that enables autoNGC to interface with either a hardware or software-simulated GPS receiver.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_19398_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19398-1","sourceUrl":"https://software.nasa.gov/software/GSC-19398-1","confidence":"high"},"type":"software","title":"autoNGC/cFS Interface for the GEONS Navigation Filter (ngc_geons)","abstract":"The autoNGC/cFS Interface for GEONS (ngc_geons) allows the Goddard Enhanced Onboard Navigation System (GEONS) software library to be used with the autonomous Navigation, Guidance and Control (autoNGC) flight software system through an app for the core Flight System (cFS).","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_19406_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19406-1","sourceUrl":"https://software.nasa.gov/software/GSC-19406-1","confidence":"high"},"type":"software","title":"Oceandata Jupyter Notebook Tutorials","abstract":"The Ocean Ecology Lab (NASA/GSFC/OEL) develops computational notebooks that demonstrate the access and use of data products from the Ocean Biology Distributed Active Archive Center (OB.DAAC). Notebooks are files containing code and computational results (including data visualizations) saved in the Jupyter format and distributed as downloads from and also rendered on the OB.DAAC website at https://oceandata.sci.gsfc.nasa.gov. The oceandata notebook collection demonstrates efficient data access patterns and processing codes, current with the latest provisioning and processing services offered by the OB.DAAC and relevant Earth Science Data Systems (ESDS) projects, for the benefit of a broad community of ocean and atmospheric research and monitoring programs. In turn, and exemplifying NASA's commitments to open source science, this external community is invited to contribute improvements to the oceandata notebook collection through the source code repository. The notebook collection is a product of the Plankton, Aerosol, Cloud, and ocean Ecosystem (PACE) mission and has no intentional commercial applications.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/oceandata-notebooks","license":null}},{"forgeId":"forge_nasa_gsc_19409_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19409-1","sourceUrl":"https://software.nasa.gov/software/GSC-19409-1","confidence":"high"},"type":"software","title":"autoNGC Ephemeris Prediction Application (ngc_predict)","abstract":"The autoNGC Ephemeris Prediction app provides the capability to propagate the current state and covariance of a spacecraft to predict the future state of the spacecraft .","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_19420_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19420-1","sourceUrl":"https://software.nasa.gov/software/GSC-19420-1","confidence":"high"},"type":"software","title":"AGATE Simulation Framework","abstract":"AGATE is a finite-volume scheme framework capable of solving the Hall and CGL (with pressure anisotropy) magnetohydrodynamics equations on multiple distributed processors compatible with both CPUs and Graphics Processing Units (GPUs). The code itself is written in Python and utilizes several open-source libraries to accelerate required calculations. AGATE is being developed as part of the MARBLE project to investigate and model the connection between magnetospheric dynamics and the aurora.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_19432_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19432-1","sourceUrl":"https://software.nasa.gov/software/GSC-19432-1","confidence":"high"},"type":"software","title":"Baboon","abstract":"Billions And Billions of Objects Organized Neatly (Baboon) is a POSIX compatible file system layer for accessing data in object storage such as S3 or RADOS.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://gitlab.modaps.eosdis.nasa.gov/infrastructure/baboon","license":null}},{"forgeId":"forge_nasa_gsc_19433_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19433-1","sourceUrl":"https://software.nasa.gov/software/GSC-19433-1","confidence":"high"},"type":"software","title":"autoNGC Safe GEONS Library","abstract":"The autoNGC Safe GEONS Library resolves thread safety conditions in flight software that leverages the Goddard Enhanced Onboard Navigation System (GEONS).","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_19461_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19461-1","sourceUrl":"https://software.nasa.gov/software/GSC-19461-1","confidence":"high"},"type":"software","title":"The Polar Wind Outflow Model","abstract":"The Polar Wind Outflow Model (PWOM), solves for the transport of plasma from the ionosphere to the magnetosphere for a planetary system. It can be configured to solve for the gyrotropic fluid equations at all altitudes, or to switch to a kinetic particle-in-cell approach at high altitudes. It can solve along a single field line, or reconstruct the outflow solution in 3D by solving along multiple field lines.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/PWOM","license":null}},{"forgeId":"forge_nasa_gsc_19468_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19468-1","sourceUrl":"https://software.nasa.gov/software/GSC-19468-1","confidence":"high"},"type":"software","title":"General Mission Analysis Tool (GMAT) Version R2025a","abstract":"The General Mission Analysis Tool (GMAT) is the world's only enterprise, multi-mission, open source software system for space mission design, optimization, and navigation. The system supports missions in flight regimes ranging from low Earth orbit to lunar, libration point, and deep space missions. GMAT is developed by a team of NASA, private industry, public, and private contributors and is used for real-world mission support, engineering studies, as a tool for education, and public engagement.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://sourceforge.net/projects/gmat/","license":null}},{"forgeId":"forge_nasa_gsc_19469_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19469-1","sourceUrl":"https://software.nasa.gov/software/GSC-19469-1","confidence":"high"},"type":"software","title":"Astrophysics Cross-Observatory Science Support (ACROSS) System","abstract":"The Astrophysics Cross-Observatory Science Support (ACROSS) system facilitates coordination among multiple astrophysics observatories. The system ingests, normalizes and provides a single point of access to publicly available but siloed NASA mission state and status information (e.g. mission observation plans, orbit parameters, etc.). Using this information, the system provides value-added features, such as multi- mission observing feasibility calculators, decision support functions, target of opportunity (ToO) and generalized mission tasking request forms, enabling users to discover, evaluate and implement coordinated responses to unfolding scientific events. The capabilities of the ACROSS system will be deployed as documented, open-source Application Programming Interface (API) endpoints, and as a software toolkit to facilitate adoption and innovation among NASA missions, general observers, and other science teams. The deployment strategy will allow integrations with third-party APIs (i.e. mission and community users) and facilitate development of custom user-defined applications. The system will also implement a set of user-interface (UI) dashboards hosted on the NASA ACROSS web portal.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-ACROSS","license":null}},{"forgeId":"forge_nasa_gsc_19475_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19475-1","sourceUrl":"https://software.nasa.gov/software/GSC-19475-1","confidence":"high"},"type":"software","title":"Mixed Reality Exploration Toolkit (MRET) 2024","abstract":"This is an update to a previously released open source version of MRET (GSC-18907-1)Desktop/Augmented Reality (AR)/Virtual Reality (VR) Software to rapidly build XR environments for NASA domain problems, e.g., pulling in CAD models of thermal vac chamber and Roman Space Telescope to do fit checks- Collaborative, cross-domain, mission lifecycle support tool for Science and Engineering- Integrates NASA models (scientific models, point clouds and LIDAR data, and engineering, CAD-based models)- Common tool set available in AR/VR/Desktop (e.g., measurement tools, voice commands, notes, animations, lunar and planetary lighting models, etc) - Access to NASA data sources. Easy to use and powerful secure communications infrastructure for all VR NASA applications using the Goddard Mission Services Evolution Center (GMSEC) architectureThis version includes Lunar and Earth Science features, including the VALIXR Holographic Table","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_19476_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19476-1","sourceUrl":"https://software.nasa.gov/software/GSC-19476-1","confidence":"high"},"type":"software","title":"Goddard Enhanced Onboard Navigation System (GEONS) V3.1","abstract":"Goddard Enhanced Onboard Navigation System (GEONS) is an enterprise, multi-mission, flight software library with associated tools that provides high-accuracy solutions for spacecraft position, velocity, and time. GEONS can be used for onboard autonomous navigation, ground-based operational navigation, and ground-based simulation and analysis of navigation systems. For flight applications, the GEONS flight software can be integrated either within a Global Positioning System (GPS) receiver, a communications receiver, or a spacecraft onboard computer. GEONS processes data from GPS receivers, ground stations, spacecraft crosslinks, cameras, LiDAR, accelerometers, and attitude sensors to produceaccurate absolute and relative navigation solutions in real time. GEONS is written in ANSI standard C, uses a UD-factorized Extended Kalman Filter (EKF) architecture, and includes fault detection capabilities. The software includes high-fidelity dynamics models, including non-spherical gravity, third body gravitational perturbations, solar radiation pressure, atmospheric drag, process noise models, and clock error models. The user must configure GEONS for their specific application. The configurability of GEONS allows it to support a wide variety of missions and enables the user to optimally balance GEONS computation time, memory, and navigation accuracy for the considered application.GEONS has over 20 years of flight heritage from previous versions of the software that have flown on multiple missions. GEONS has been baselined to provide onboard, autonomous navigation for multiple upcoming missions. Although GEONS has only flown for Earth orbiting missions to date, it can support a wide range of orbit regimes including cislunar/lunar space and beyond.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_gsc_19559_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19559-1","sourceUrl":"https://software.nasa.gov/software/GSC-19559-1","confidence":"high"},"type":"software","title":"Delay/Disruption Tolerant Networking (DTN) Bundle Protocol (BP) v7 Core Flight System (cFS) Application Build 7.0.5.","abstract":"The BP Core Flight System (cFS) application uses the Bundle Protocol Library (bplib) to implement Delay/Disruption Tolerant Networking Bundle Protocol (BP) version 7. The application runs on the Core Flight Executive (cFE) and provides out of the box integration with the cFS CFDP application (CF). The implementation conforms to the CCSDS BPv7 Orange Book draft and RFC 9171. The software includes test tools used to verify and validate the BPv7 cFS application.The software is divided into three repositories:https://github.com/nasa/bplibhttps://github.com/nasa/bphttps://github.com/nasa/dtn-tools/","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/bp","license":null}},{"forgeId":"forge_nasa_gsc_19640_1","source":{"institution":"NASA","subUnit":"Goddard Space Flight Center","subUnitCode":"GSFC","nativeId":"GSC-19640-1","sourceUrl":"https://software.nasa.gov/software/GSC-19640-1","confidence":"high"},"type":"software","title":"General Mission Analysis Tool (GMAT) Version R2026","abstract":"The General Mission Analysis Tool (GMAT) is the world's only enterprise, multi-mission, open source software system for space missiondesign, optimization, and navigation. The system supports missions in flight regimes ranging from low Earth orbit to lunar, libration point, and deep space missions. GMAT can be operated from an interactive Graphical User Interface (GUI), from a custom script language, or from Python or Java programming environments. The GMAT development team consists of NASA, private industry, public, and private contributors and is used for real-world mission support, engineering studies, education applications, and public engagement.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://sourceforge.net/projects/gmat/","license":null}},{"forgeId":"forge_nasa_hqn_11886_1","source":{"institution":"NASA","subUnit":"HDQS","subUnitCode":"HDQS","nativeId":"HQN-11886-1","sourceUrl":"https://software.nasa.gov/software/HQN-11886-1","confidence":"high"},"type":"software","title":"NASA Instrument Cost Model (NICM) Version 10","abstract":"NICM is a probabilistic cost and schedule estimating tool. NICM has proven instrument cost and schedule modeling capabilities that provide probabilistic estimates at both the system and subsystem level for many different instrument types. NICM is used by all NASA centers to support agency-wide proposal activities and program-directed missions.","category":"operations","categoryRaw":"business systems and project management","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_ksc_12544","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-12544","sourceUrl":"https://software.nasa.gov/software/KSC-12544","confidence":"high"},"type":"software","title":"MATLAB-Based Solar System Ephemeris Toolbox","abstract":"This set of MATLAB functions has been used to generate state data (position and velocity) for the Sun, the Earth's moon, and all of the other planets in the solar system. Provided by the Jet Propulsion Laboratory's Solar System Dynamics Group, the technology uses Chebychev polynomial fits of numerical integration results for solar system motion. Essentially, the toolbox functions as the MATLAB equivalent of JPL Fortran routines used to construct binary ephemeris files, verify correct installation, and generate state data .","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_ksc_12952","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-12952","sourceUrl":"https://software.nasa.gov/software/KSC-12952","confidence":"high"},"type":"software","title":"3D-Mapping Software for High Resolution Display of Hail and Rain Data From NWS Radar","abstract":"A three-dimensional high resolution mapping of hail, as well as rain, is desirable in many instances. For example, hail mapping in the vicinity of a vehicle on the launch pad would help determine whether or not damage may have occurred due to a hail event. In addition to quantifying the size and quantity of hail, it is desirable to know where on the vehicle hail impacts may have occurred. High resolution display of weather radar data using the software described in this report can be used to generate a 3D hail/rain map around a large structure, such as the launch pad or a power plant.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_ksc_13203","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-13203","sourceUrl":"https://software.nasa.gov/software/KSC-13203","confidence":"high"},"type":"software","title":"Analog Input Data Acquisition Software","abstract":"With the easy-to-use Analog Input Data Acquisition Software, a user can set up a system for monitoring up to five analog input channels. The software requires LabVIEW runtime engine 8.0 (a free download from ni.com) to run the executable.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_ksc_13752","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-13752","sourceUrl":"https://software.nasa.gov/software/KSC-13752","confidence":"high"},"type":"software","title":"An LED Lighting Panel Software Simulation Tool","abstract":"The software tool was originally designed and implemented for use with the Advanced Biological Research System (ABRS) lighting panel upgrade. The upgrade was required since the LEDs used in the original design are no longer available in small quantity, and newer LEDs have a much higher efficiency. Even though the software tool is currently written for a flat panel containing LEDs pointing normal to the panel, the equations used are fundamental to the physics of the problem and therefore can be applied to any geometrical configuration by implementing a modified user interface.","category":"biomedical_health","categoryRaw":"crew and life support","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_ksc_13775","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-13775","sourceUrl":"https://software.nasa.gov/software/KSC-13775","confidence":"high"},"type":"software","title":"DON 3.1 - The Distributed Observer Network 3.1","abstract":"Distributed Observer Network 3 (DON3) is the innovation combination of NASA simulation technologies, NASA information technologies and commercial video game technology to provide a unique system that leverages the strengths of all three. A key component of the innovation is a standardized data interface for simulation related information that is coupled with custom software integrated into the game environment.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_ksc_13925","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-13925","sourceUrl":"https://software.nasa.gov/software/KSC-13925","confidence":"high"},"type":"software","title":"Design Patterns and Methods to Rapidly Develop Web and Mobile Applications Integrated with Systems Utilizing the Object Management Group's (OMG) Data Distribution Service (DDS)","abstract":"This software gives Node.js application developers the ability to integrate with a DDS-enabled software system without having to write the extension software that would otherwise be required without this product. Such a product is not currently available in the market. In addition, no publications exist where this method or approach is contemplated as a possible solution. The solution achieves this feature by processing the system's already-existing (or otherwise necessary on a new system) IDL files and generating the appropriate C++ code based on the IDL file contents. In doing so, the solution includes a novel way of using C++ templates and advanced generic programming techniques to produce data transcoders between JavaScript and C++ that preserve all data characteristics as described in the system's IDL files with no need for application developers to expend work implementing or customizing this transcoding.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/DdsJs","license":null}},{"forgeId":"forge_nasa_ksc_13968","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-13968","sourceUrl":"https://software.nasa.gov/software/KSC-13968","confidence":"high"},"type":"software","title":"Kennedy Action Tracking System (KATS)","abstract":"In the KATS application, a method of abstraction was used to in a foundational website platform that liberated the developers from the concern of having to manually generate Entity Framework calls to interact with the data layer of the application. This abstraction method/layer provided the ground work from which was developed a \"Project Foundation\" that has now become the basic starting block for all of our web-based solution development. This foundation drastically reduces project \"spin up\" time and standardizes data layer and other service interactions to ensure consistently high performing transactional solutions.","category":"operations","categoryRaw":"business systems and project management","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_ksc_14027","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-14027","sourceUrl":"https://software.nasa.gov/software/KSC-14027","confidence":"high"},"type":"software","title":"Photogrammetry Pyramid","abstract":"The Photogrammetry Pyramid software is a 3D photogrammetry Windows application intended to support the use of a stand-alone reference target system. The software requires images from two or more camera views. For static scenes, a single camera can be used by taking pictures from different viewpoints (two or more). The reference target is composed of seven spheres connected by equal length rods. A sphere is located at each of the four vertices of the pyramid. Three additional spheres are located at the midpoint of the three vertical rods. The distance between any set of vertices-spheres defines the characteristic pyramid length. This length is the only value needed by the user during reference target generation. The pyramid replaces the photogrammetry cube (see: http://ntrs.nasa.gov/search.jsp?R=20120007627). The original photogrammetry cube software has been modified to incorporate the photogrammetry pyramid. An application and mathematical theory utilized by the software is described in an article by Metzger et al., \"Photogrammetry and ballistic analysis of a high-flying projectile in the STS-124 space shuttle launch.\" Acta Astronautica 67, no. 1 (2010): 217-229.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_ksc_14109","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-14109","sourceUrl":"https://software.nasa.gov/software/KSC-14109","confidence":"high"},"type":"software","title":"HLA2MPC 3.0, A software bridge between the IEEE 1516 (High Level Architecture) to the NASA MPC (Model Process Control) 3.0 telemetry language.","abstract":"HLA2MPC provides the link between HLA (High Level Architecture, IEEE 1516) Simulation Federation data and any MPC 3 compliant simulation or visualization tool. One such tool is DON, the Distributed Observer Network, now in version 3.1. DON 3.1 is available in the Software catalog at https://software.nasa.gov/software/KSC-13775.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/DON-Federate-HLA2MPC","license":null}},{"forgeId":"forge_nasa_ksc_14131","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-14131","sourceUrl":"https://software.nasa.gov/software/KSC-14131","confidence":"high"},"type":"software","title":"Mars In-Situ Resource Utilization (ISRU) Propellant Production Discrete Event Simulation (DES)- MIPP-D.","abstract":"Mars In-Situ Resource Utilization (ISRU) Propellant Production Discrete Event Simulation (DES)- MIPP-DMIPP-D is a Simio based Discrete Event Simulation modeling Mars surface propellant production. The focus is on the actual chemical plant and processes, including incoming and outgoing materials, associated with the production of rocket fuel on Mars. The fuel will be for the Mars Ascent Vehicle used to carry humans into space from the surface of Mars. The Simulation utilizes NASA ground rules and assumptions as well as data from prototype chemical plants, NASA experts and literature. The Simulation is designed to grow in capability and complexity as needed or as additional information becomes available. The simulation does not attempt to model the complexities of surface elements acquiring feed stock or disposing of spent resources, although it does acknowledge those functions exist and uses informed assumptions where necessary.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_ksc_14272","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-14272","sourceUrl":"https://software.nasa.gov/software/KSC-14272","confidence":"high"},"type":"software","title":"Virtual Environment Computational Training Resource (VECTR): OSIRIS-REx","abstract":"VECTR (Virtual Environment Computational Training Resource): OSIRIS-REx is the latest application under the VECTR product line. VECTR is a virtual reality platform, built with commercial off-the-shelf hardware, designed to augment the training process for various operations at KSC. VECTR is a flexible, scalable platform that allows for model updates if engineering designs change, and scenario updates if a procedure changes. All aspects of the VECTR virtual environment can be changed and updated within the software by a developer even if the hardware hasn't yet been built in the real world. This version highlights operations in the Payload Hazardous Safety Facility (PHSF) of the OSIRIS-REx spacecraft before it gets launched and also demonstrates the touchdown on Bennu for sample collection and return.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_ksc_14470","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-14470","sourceUrl":"https://software.nasa.gov/software/KSC-14470","confidence":"high"},"type":"software","title":"Rapid Model Import Tool (RMIT) Version 2.0","abstract":"The Rapid Model Import Tool (RMIT) version 2 is an enhancement to the original RMIT software. It is software designed import 3D models from Computer Aided Design (CAD) software tools such as 3DS Max, Catia, or Creo, and perform several modifications to the model's underlying format. Some of the modifications include flattening the hierarchical tree structure of the model's objects, translating the model to world coordinates origin, polygon simplification, and object merging, all designed to reduce the size of the model's file structure, while retaining fidelity to the original model. This new version expands file formats to most CAD file types. A support form has also been added for user feedback as well as MRET(Mixed Reality Exploration Toolkit) support. There is also expanded model manipulation tools such as linking of materials to reduce material definition bloat and finer control over model decimation.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_ksc_14485","source":{"institution":"NASA","subUnit":"Kennedy Space Center","subUnitCode":"KSC","nativeId":"KSC-14485","sourceUrl":"https://software.nasa.gov/software/KSC-14485","confidence":"high"},"type":"software","title":"Calysto: Risk Management","abstract":"The Calysto: Risk Management software application is used by organizations and programs across the NASA Agency. The application was written as a SharePoint Add-in in JavaScript, HTML, CSS, and CAML. It is written in a way where it can be deployed to a SharePoint on-premises environment or SharePoint Online. The application can be easily updated without user impact by using the SharePoint App Store. Calysto is available to any SharePoint site with the KSC Institutional SharePoint farm. The application is developed on top of Microsoft SharePoint as a SharePoint add-in that uses a SQL database to store content. It allows users to input risk data to their project or organization and ranks the risks by highest product of likelihood times highest consequence, as defined by Likelihood and Consequence criteria. Risks can be configured to require approval for them to be visible to general users, and to roll up to a parent organization. Other features include: keep the history of a risk; automatic or manual trending to track the progress of a risk; export of risk data to Microsoft PowerPoint and Excel; tracking of risk mitigation tasks; automatic risk ID calculation based on where in the organizational hierarchy the risk resides, with the ability to manually override it; multiple views and reports of the risk data .","category":"operations","categoryRaw":"business systems and project management","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_15241","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-15241","sourceUrl":"https://software.nasa.gov/software/LAR-15241","confidence":"high"},"type":"software","title":"System/Observer/Controller Identification Toolbox (SOCIT)","abstract":"SOCIT is a collection of functions, written in MATLAB language and expressed in M-files, that implements a variety of modern system identification techniques. For an open-loop system, it features functions for identification of a system model and corresponding forward and backward observers directly from input and output data . For a closed-loop system, SOCIT identifies an open-loop model, an observer, and corresponding controller gain directly from input and output data .","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_16059_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-16059-1","sourceUrl":"https://software.nasa.gov/software/LAR-16059-1","confidence":"high"},"type":"software","title":"Windows Semi-Markov Range Evaluator (WinSURE)","abstract":"This package is used by aerospace flight software developers to predict the reliability of flight -critical computer processes.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/WinSURE","license":null}},{"forgeId":"forge_nasa_lar_16060_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-16060-1","sourceUrl":"https://software.nasa.gov/software/LAR-16060-1","confidence":"high"},"type":"software","title":"WinASSIST: (Windows Abstract Semi-Markov Specification Interface To The SURE Tool)","abstract":"The WinASSIST program uses a rule-oriented language to automatically generate input files for the SURE/WinSURE program. The user describes the failure behavior and recovery behavior of a fault-tolerant computer system in an abstract language. The WinASSIST program then automatically generates a corresponding semi-Markov model. The abstract language allows efficient description of large, complex systems. A one-page WinASSIST-language description may result in a semi-Markov model with thousands of states and transitions. The WinASSIST program also provides model-reduction techniques to facilitate efficient modeling of large systems.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/WinASSIST","license":null}},{"forgeId":"forge_nasa_lar_16100_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-16100-1","sourceUrl":"https://software.nasa.gov/software/LAR-16100-1","confidence":"high"},"type":"software","title":"System IDentification Programs for AirCraft (SIDPAC)","abstract":"Written in MATLAB, SIDPAC is a collection of over 300 programs that perform a wide variety of tasks related to system identification applied to aircraft. SIDPAC includes tools for experiment design, data analysis, kinematic consistency checking, static and dynamic modeling, simulation , numerical integration and differentiation, smoothing, filtering, finite Fourier transformation, statistical modeling and evaluation, optimization, parameter estimation, model accuracy quantification, model validation, and more.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_16371_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-16371-1","sourceUrl":"https://software.nasa.gov/software/LAR-16371-1","confidence":"high"},"type":"software","title":"Data Transfer Between Dissimilar Meshes (DTBDM, 2.0)","abstract":"Designed to automate an otherwise labor-intensive process, DTBDM puts the aerodynamic loads output of a computational fluid dynamics (CFD) package into the structural model of an aircraft to allow for deflection calculations.","category":"mechanical_systems","categoryRaw":"structures and mechanisms","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_16804_gs","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-16804-GS","sourceUrl":"https://software.nasa.gov/software/LAR-16804-GS","confidence":"high"},"type":"software","title":"NASA STRuctrual ANalysis (NASTRAN)","abstract":"NASTRAN is a finite element analysis program that was originally developed for NASA in the late 1960s under U.S. government funding for the aerospace industry. The software suite provides engineers a comprehensive simulation solution for insight into structural behavior. NASTRAN source code is integrated in a number of different software packages, which are distributed by a range of companies.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/NASTRAN-95","license":null}},{"forgeId":"forge_nasa_lar_16882_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-16882-1","sourceUrl":"https://software.nasa.gov/software/LAR-16882-1","confidence":"high"},"type":"software","title":"TetrUSS Computational Fluid Dynamics Software (TetrUSS)","abstract":"The most awarded software in the history of NASA, TetrUSS is a suite of computer programs used for fluid dynamics and aerodynamics analysis and design. The software is widely used in other government organizations, the aerospace industry, academia, and non-aerospace industries such as automotive, bio-medical, and civil engineering.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_17227_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-17227-1","sourceUrl":"https://software.nasa.gov/software/LAR-17227-1","confidence":"high"},"type":"software","title":"CFACS: Constrained Fitting for Airfoil Curvature Smoothing","abstract":"Airfoil smoothing in design environments is largely based on heuristic methods and it is an art to generate an unbiased smooth fit of the airfoil's curvature profile by modifying its geometry. The software CFACS (Constrained Fitting for Airfoil Curvature Smoothing) uses a spline-based airfoil smoothing method with the sum of squares of the third derivative jumps as a curvature smoothness measure. CFACS can take out dramatic curvature oscillations with extremely small geometry changes and smooth an airfoil segment without creating curvature oscillations near the endpoints. Visually, CFACS generates an unbiased smooth fit of the curvature profile. CFACS can smooth airfoils to either promote desirable performance characteristics or remove undesirable pressure field oscillations in computational fluid dynamics solutions.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_17262_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-17262-1","sourceUrl":"https://software.nasa.gov/software/LAR-17262-1","confidence":"high"},"type":"software","title":"RANSTEP - Reduced order Analysis using a Nonlinear STiffness Evaluation Procedure","abstract":"A new implementation of reduced order finite-element-based analysis for solving geometrically nonlinear random vibration problems of complex structures has been developed. The implementation is given the acronym RANSTEP for Reduced order Analysis using a Nonlinear STiffness Evaluation Procedure. The nonlinear stiffness evaluation procedure allows computation of otherwise inaccessible modal nonlinear stiffness terms from commercial finite element programs. Some operations are performed outside the commercial codes and utilize in-house developed FORTRAN codes. Additionally Direct Matrix Abstraction Program (DMAP) alters and PYTHON scripts are used to facilitate implementations written about MSC.NASTRAN and ABAQUS, respectively. Two solutions procedures of different fidelity and computational cost are offered in each implementation. They are equivalent linearization and time numerical simulation . Aerospace uses include aircraft and spacecraft structural analysis.","category":"mechanical_systems","categoryRaw":"structures and mechanisms","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_17460_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-17460-1","sourceUrl":"https://software.nasa.gov/software/LAR-17460-1","confidence":"high"},"type":"software","title":"Java-Based Software Tool for Dynamic Aerospace Vehicle Exchange Markup Files","abstract":"An update to software originally named DAVEtools 0.5, this software-based technology is used for manipulating standard Dynamic Aerospace Vehicle Exchange Markup Language (DAVE-ML) models. The improved technology embeds the necessary initialization data into a data structure to keep the MATLAB workspace uncluttered and creates Simulink models from a generated MATLAB script.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/DAVEtools","license":null}},{"forgeId":"forge_nasa_lar_17463_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-17463-1","sourceUrl":"https://software.nasa.gov/software/LAR-17463-1","confidence":"high"},"type":"software","title":"A Collection of Nonlinear Aircraft Simulations in MATLAB","abstract":"Nonlinear six degree-of-freedom simulations for a variety of aircraft were created using MATLAB. Data for aircraft geometry, aerodynamic characteristics, mass / inertia properties, and engine characteristics were obtained from open literature publications documenting wind tunnel experiments and flight tests. Each nonlinear simulation was implemented within a common framework in MATLAB, and includes an interface with another commercially-available program to read pilot inputs and produce a three-dimensional (3-D) display of the simulated airplane motion. Aircraft simulations include the General Dynamics F-16 Fighting Falcon, Convair F-106B Delta Dart, Grumman F-14 Tomcat, McDonnell Douglas F-4 Phantom, NASA Langley Free-Flying Aircraft for Sub-scale Experimental Research (FASER), NASA HL 20 Lifting Body, NASA / DARPA X-31 Enhanced Fighter Maneuverability Demonstrator, and the Vought A-7 Corsair II. All nonlinear simulations and 3-D displays run in real time in response to pilot inputs, using contemporary desktop personal computer hardware. The simulations can also be run in batch mode. Each nonlinear simulation includes the full nonlinear dynamics of the bare airframe, with a scaled direct connection from pilot inputs to control surface deflections to provide adequate pilot control.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_17491_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-17491-1","sourceUrl":"https://software.nasa.gov/software/LAR-17491-1","confidence":"high"},"type":"software","title":"Vehicle Sketch Pad (VSP)","abstract":"The Vehicle Sketch Pad (VSP) is an aircraft geometry tool for rapid evaluation of advanced design concepts. Fast and accurate geometry modeling allows the designer to use more complex analysis methods earlier in the design process and reduces reliance on empiricism in conceptual design. VSP includes tools to model and export the internal structural layout.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://openvsp.org/download.php","license":null}},{"forgeId":"forge_nasa_lar_17498_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-17498-1","sourceUrl":"https://software.nasa.gov/software/LAR-17498-1","confidence":"high"},"type":"software","title":"Orbit Lifetime Monte Carlo (OLMC)","abstract":"Given the dynamic environment in which spacecraft exist, a better methodology for performing orbital lifetime analyses over the current practice of point analyses was desired. The approach chosen was to utilize Monte Carlo based predictions, which provides the ability to gauge the probability of meeting mission lifetime goals, as well as identifying driving factors. The Monte Carlo analysis , called Orbital Lifetime Monte Carlo (OLMC), is based on the NASA Langley Research Center long term orbit propagator Orbital Lifetime. OLMC incorporates the ability to model variations in predictions of solar flux levels and timing of associated peaks, the variation in launch vehicle orbit insertion accuracy (altitude, velocity, and flight path angles), spacecraft ballistic coefficients, and launch delays. Desired repeatability, distribution smoothness and code runtime are considered for the purposes of establishing values for code specific parameters and number of Monte Carlo runs. Results demonstrate that solar flux predictions are the primary driver for variations in lifetime; of which, due to their variability, multiple prediction sets should be utilized to fully characterize the lifetime range of a spacecraft.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_17590_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-17590-1","sourceUrl":"https://software.nasa.gov/software/LAR-17590-1","confidence":"high"},"type":"software","title":"Advanced Subsonic and Supersonic Propeller Induced Noise (ASSPIN) prediction program","abstract":"ASSPIN is a computer program that predicts the noise generated by propellers operating at subsonic, transonic, or supersonic helical tip speeds in either single-rotation or counter-rotation mode. The format of blade surface pressure data obtained from aerodynamic codes for ASSPIN input is generally not compatible with that required by ASSPIN. The ASP_Tools suite provides the capability to manipulate blade geometry and surface pressure data to produce proper ASSPIN input. In addition, the ability to parse ASSPIN output files and obtain specific output variables is provided.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_17595_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-17595-1","sourceUrl":"https://software.nasa.gov/software/LAR-17595-1","confidence":"high"},"type":"software","title":"GTM_Polysim-Nonlinear GTM Aircraft Polynomial Simulation in MATLAB, Version 2.0","abstract":"The GTM_POLYSIM is a nonlinear simulation of the Generic Transport Model (GTM) aircraft at a 5.5-percent scale. The simulation software is a collection of scripts and programs written and executed in the MATLAB computing environment.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_17625_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-17625-1","sourceUrl":"https://software.nasa.gov/software/LAR-17625-1","confidence":"high"},"type":"software","title":"Flight Dynamics Simulation of a Generic Transport Model","abstract":"This software is a flight dynamics simulation of a transport aircraft. It implements general rigid body equations of motion for the vehicle dynamics and draws aerodynamic forces from a standard coefficient expansion implemented as table lookups. Dynamics of actuator servos and bandwidth of sensors are also included. The simulation is coded in Simulink, a model-based environment using a commercial simulation package from Mathworks, Inc. The software is not stand-alone; it must be run from inside this commercial environment, making use of numerical libraries for basic operations as well as the overall time-stepping and numerical integration routines.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/GTM_DesignSim","license":null}},{"forgeId":"forge_nasa_lar_17635_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-17635-1","sourceUrl":"https://software.nasa.gov/software/LAR-17635-1","confidence":"high"},"type":"software","title":"Java Program to Promote an Open-Source \"E Standard\" for Mass Properties Engineering","abstract":"This open-source Java software helps develop electronic standards (E-Standards) for mass properties engineering. An E-Standard is a highly descriptive dataset that includes standardizing functions for data manipulation, interrogation, and formatting. With this tool, any number of users can interface with the proposed E-Standard datasets and still seamlessly utilize their own software methods.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://ti.arc.nasa.gov/opensource/projects/e-standards-mass-properties-engineering/","license":null}},{"forgeId":"forge_nasa_lar_17678_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-17678-1","sourceUrl":"https://software.nasa.gov/software/LAR-17678-1","confidence":"high"},"type":"software","title":"PLOT3D Export Tool for Tecplot","abstract":"The PLOT3D Export Tecplot addon is a runtime library linked into Tecplot at the time of startup of the Tecplot software. It enables Tecplot users the ability to output PLOT3D style files from Tecplot as a grid, grid and solution, or grid and function file for use by another computer code. Existing functionality of Tecplot only offers input of PLOT3D data and output of image data or Tecplot proprietary formatted data . The PLOT3D Exporter addon thus enables the use of Tecplot as a generation and manipulation of grid and solution data for output to flow solvers. In this capacity, Tecplot can be used to interpolate old solutions onto new grids imported into Tecplot or created within the Tecplot software. The output of PLOT3D data also enables use of Tecplot to convert solutions from other flow solvers into a standard PLOT3D data set. Thus, the PLOT3D Export addon significantly enhances Tecplot capabilities for use by computational science applications.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_17753_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-17753-1","sourceUrl":"https://software.nasa.gov/software/LAR-17753-1","confidence":"high"},"type":"software","title":"Rotorcraft Noise Model (RNM), Version 7","abstract":"The RNM simulation model calculates community noise, computing time histories of noise for arbitrary vehicle flight operations. The technology accommodates multiple noise sources (e.g., rotors and engines), each represented by a sphere of spectral data at a reference distance. Propagation to the ground accounts for spherical spreading, atmospheric absorption, ground impedance effects, and limited weather effects.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_17758_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-17758-1","sourceUrl":"https://software.nasa.gov/software/LAR-17758-1","confidence":"high"},"type":"software","title":"3DGRAPE/AL v3: Three-Dimensional Grids About Anything By Poisson Equations","abstract":"The new version (3.0) suite of the 3DGRAPE/AL software advances the state-of-the art in structured volume grid generation through the implementation of a new matching point block-to block boundary condition on adjacent faces of two blocks that no other volume grid generator has. This new version also has two preprocessors that enable rapid development of the input data to run 3DGRAPE/AL. Finally, the new 3DGRAPE/AL has both serial and parallel programming versions that enable the generation of volume grids nearly 5 times faster than the previous 3DGRAPE/AL code.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_17761_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-17761-1","sourceUrl":"https://software.nasa.gov/software/LAR-17761-1","confidence":"high"},"type":"software","title":"Acoustic Propagation and Emulation Toolset (APET)","abstract":"The Acoustic Propagation and Emulation Toolset (APET) is a framework code uniting several acoustic methodologies for the propagation and measurement of source noise audibility at farfield observers, accounting for the effects of the atmosphere, weather , terrain, and spherical spreading. Currently, APET consists of a modified version of the Rotorcraft Noise Model (RNM, Version 7) coupled with the newly developed Spectral Attenuation Method (SAM) that contains the Ray Tracing Program (RTP) and two versions of a Greens Function Parabolic Equation (GFPE) code. A third component of APET is an audibility prediction scheme based on the work of Abrahamson, initially called ICHIN (I Can Hear It Now) and further developed by Wyle Labs as AUDIB.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_17835_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-17835-1","sourceUrl":"https://software.nasa.gov/software/LAR-17835-1","confidence":"high"},"type":"software","title":"Multi-Attribute Task Battery (MATB-II)","abstract":"MATB-II is a computer-based task battery designed to facilitate research in human multiple task performance with consideration for the effects of automation. The tool includes five component tasks: system monitoring , tracking, communications monitoring , and resource management. A scheduling window provides preview of anticipated workload, and component tasks can be automated or manual. Coded in C&#43;&#43;, MATB-II has been tested on the Windows XP Service Pack 3, Windows Vista, and Windows 7 operating systems.","category":"biomedical_health","categoryRaw":"crew and life support","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18313_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18313-1","sourceUrl":"https://software.nasa.gov/software/LAR-18313-1","confidence":"high"},"type":"software","title":"HCDstruct","abstract":"This MATLAB routine generates a scalable finite element model suitable for hybrid wing-body (HWB) structural analysis and optimization. HWB geometry structure is based on a vehicle sketch-pad (VSP) surface model of an aircraft and a FLOPS-compatible parameterization of the center body and wing structure. Optimization and weight calculation are based on a Nastran finite element analysis of the primary structural components.","category":"mechanical_systems","categoryRaw":"structures and mechanisms","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18314_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18314-1","sourceUrl":"https://software.nasa.gov/software/LAR-18314-1","confidence":"high"},"type":"software","title":"FilePlottingTools","abstract":"This Excel plugin written in VB.net allows rapid post-processing of thermal analysis data from text files or from SINDA-formatted SAV files. The software can be adapted to other data formats as well.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://fileplottingtools.larc.nasa.gov/","license":null}},{"forgeId":"forge_nasa_lar_18322_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18322-1","sourceUrl":"https://software.nasa.gov/software/LAR-18322-1","confidence":"high"},"type":"software","title":"Transport Class Model (TCM) Aircraft Simulation Software","abstract":"This six-degree-of-freedom, flat-earth dynamics, non-linear, and non-proprietary aircraft simulation is a representation of a generic mid-sized twin-jet transport aircraft.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18488_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18488-1","sourceUrl":"https://software.nasa.gov/software/LAR-18488-1","confidence":"high"},"type":"software","title":"KSOPT - An Indirect Method for Numerical Optimization using the Kreisselmeier-Steinhauser Function - Version 3.1","abstract":"This is a technique for converting a constrained optimization problem into an unconstrained problem. The technique transforms one or more objective functions into reduced objective functions analogous to goal constraints used in the goal programming method. The reduced objectivefunctions are appended to the set of constraints and an envelope of the entire function set is computed using the Kreisselmeier-Steinhauser function. This envelope function is then searched for an unconstrained minimum. The technique may be categorized as a SUMT algorithm. Version 3.1 is written in the FORTRAN 90/95 standard and improves upon the robustness of the code by preventing potential memory allocation errors.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18538_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18538-1","sourceUrl":"https://software.nasa.gov/software/LAR-18538-1","confidence":"high"},"type":"software","title":"Versatile ImpulSive Interplanetary Trajectory OptimizeR (VISITOR)","abstract":"The design of trajectories for interplanetary missions represents one of the most complex and important problems to solve during conceptual space mission design. To facilitate conceptual interplanetary mission sizing activities, it is essential to obtain sufficiently accurate trajectories in a fast and repeatable manner. To this end, the VISITOR software tool was developed. This tool modularly augments a patched conic, multiple gravity-assist with one deep space manuever (MGA-1DSM) trajectory model with a mass model, launch window analysis , and the capability to simulate realistic arrival and departure operations. The tool was validated against seven flown missions: the average total mission delta-V offset from the nominal trajectory was 9.1%, and was reduced to 7.3% when using the genetic algorithm at the cost of an increase in computation time by a factor 5.7. VISITOR is well-suited for the conceptual design of interplanetary trajectories and facilitates future improvements due to its modular structure.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18583_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18583-1","sourceUrl":"https://software.nasa.gov/software/LAR-18583-1","confidence":"high"},"type":"software","title":"DEVELOP National Program Python Package (dnppy)","abstract":"The DEVELOP National Program Python Package creates a python programming environment for simple processing of large NASA data sets to prepare them for further analysis in an ESRI ArcMap environment. It includes an instructional framework to guide users who are new to performing GIS tasks in a heavily code based python environment.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/dnppy","license":null}},{"forgeId":"forge_nasa_lar_18602_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18602-1","sourceUrl":"https://software.nasa.gov/software/LAR-18602-1","confidence":"high"},"type":"software","title":"Modified Snowmelt Runoff Model For Forecasting Water Availability in Chile","abstract":"Modified Snowmelt Runoff Model for Forecasting Water Availability in Chile (M-SRM) models daily stream flow of snowmelt runoff as a function of temperature, elevation, snow-covered area, precipitation rate, and experimentally determined coefficients. Using MODIS and TRMM data , the software provides tools for synthesizing daily fractional snow cover and daily precipitation measurements. M-SRM provides daily stream flow estimates for three months beyond the start of the growing season.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/M-SRM","license":null}},{"forgeId":"forge_nasa_lar_18665_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18665-1","sourceUrl":"https://software.nasa.gov/software/LAR-18665-1","confidence":"high"},"type":"software","title":"Coastal Mid-Atlantic METRIC Model","abstract":"METRIC model software can be used to calculate evapotranspiration (ET) rates of agricultural fields by executing the Measuring Evapotranspiration at High Resolution with Internalized Calibration (METRIC) model in an ArcGIS Python script. The model requires input data from Landsat 8 OLI/TIRS and local weather stations. The creation of this software was motivated by the need to reduce irrigation costs for farmers and provide a means of drought monitoring for the agricultural industry. This software has the potential to reduce the economic stress on the agricultural industry by enhancing crop productivity and irrigation efficiency.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/METRIC","license":null}},{"forgeId":"forge_nasa_lar_18693_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18693-1","sourceUrl":"https://software.nasa.gov/software/LAR-18693-1","confidence":"high"},"type":"software","title":"Constrained Direct Iterative Surface Curvature (CDISC) Aerodynamic Design Software","abstract":"CDISC is a system of software codes which, when coupled with computational fluid Dynamics flow solvers, provides a method for aerodynamic design. The core design algorithm uses prescribed flow/geometry sensitivity derivatives to make geometry changes based on the difference between target and analysis pressures on the surface of the configuration being designed. The target pressures can be directly specified or may be generated using the flow constraint options in CDISC that modify the current analysis pressures to meet common engineering quantities such as lift and pitching moment. Geometry constraints, such as wing thickness or curvature, are also included to meet requirements from other disciplines such as structures and manufacturing.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18704_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18704-1","sourceUrl":"https://software.nasa.gov/software/LAR-18704-1","confidence":"high"},"type":"software","title":"Loft: An Automated Mesh Generator for Stiffened Shell Aerospace Vehicles","abstract":"Loft is an automated mesh generation code that is designed for aerospace vehicle structures. From user input, Loft generates meshes for wings, noses, tanks, fuselage sections, thrust structures, and so on. As a mesh is generated, each element is assigned properties to mark the part of the vehicle with which it is associated. This property assignment is an extremely powerful feature that enables detailed analysis tasks, such as load application and structural sizing.","category":"mechanical_systems","categoryRaw":"structures and mechanisms","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18710_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18710-1","sourceUrl":"https://software.nasa.gov/software/LAR-18710-1","confidence":"high"},"type":"software","title":"VOCAL - Visualization of CALIPSO","abstract":"VOCAL Is a visualization software tool designed for the CALIPSO satellite. VOCAL offers an easy to use GUI interface that allows users to open CALIPSO data, and visualize that data on a plot for the user. Users can then use a number of tools to select area's of the plot by drawing 'shapes' around those areas, and label shapes with attributes and notes. Shapes can be exported to a backend database which can serve as a centralized point for researchers to share data and help track and identify aerosols in the atmosphere","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/VOCAL","license":null}},{"forgeId":"forge_nasa_lar_18720_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18720-1","sourceUrl":"https://software.nasa.gov/software/LAR-18720-1","confidence":"high"},"type":"software","title":"Scalable Implementation of Finite Elements by NASA (ScIFEN)","abstract":"The Scalable Implementation of Finite Elements by NASA (ScIFEN) package is a parallel finite element analysis code written in C&#43;&#43;. It is designed to enable scalable solutions to computational mechanics problems by leveraging several open-source high performance computing libraries for numerical linear algebra routines and parallel input/output. ScIFEN supports several different finite element types, nonlinear material models, and boundary conditions and contains both implicit and explicit time integration procedures called ScIFEi and ScIFEx, respectively.","category":"materials_coatings","categoryRaw":"materials and processes","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18731_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18731-1","sourceUrl":"https://software.nasa.gov/software/LAR-18731-1","confidence":"high"},"type":"software","title":"Drought Severity Assessment - Decision Support Tool (DSAT)","abstract":"The Drought Severity Assessment - Decision Support Tool allows a user to calculate Standardized Precipitation Index (SPI) values for each cell of a set of monthly precipitation rasters that span at least thirty years. Additionally the tool calculates basic SPI statistics within a user specified boundary, and allows for visualization of calculated SPI rasters over time.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/DSAT","license":null}},{"forgeId":"forge_nasa_lar_18733_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18733-1","sourceUrl":"https://software.nasa.gov/software/LAR-18733-1","confidence":"high"},"type":"software","title":"Low Fidelity Space Systems Analysis Tools-Multiburn/Large Vehicle Sizing Tool","abstract":"This tool will design a large vehicle and do inert mass fraction sizing to scale a vehicle for multiple impulsive maneuvers and different payloads.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18734_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18734-1","sourceUrl":"https://software.nasa.gov/software/LAR-18734-1","confidence":"high"},"type":"software","title":"Low Fidelity Space Systems Analysis Tools-ISRU Demo Plant Sizing Tool","abstract":"The Agile ISRU Demo Plant Sizing Tool will provide a rough parametric estimate of ISRU plant mass and power requirements based on fitting data to a heritage curve. NEO, Phobos, Lunar Surface, and Martian Surface are included at a notional level within this system that allows architecture designers to roughly scale ISRU plants before talking to specialists.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18735_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18735-1","sourceUrl":"https://software.nasa.gov/software/LAR-18735-1","confidence":"high"},"type":"software","title":"Low Fidelity Space Systems Analysis Tools-Rover Sizing Tool","abstract":"This tool is intended to be used to science scientific rover missions based on a heritage catalogue of scientific components as well as relationships between scientific tool mass and total rover body mass.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18736_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18736-1","sourceUrl":"https://software.nasa.gov/software/LAR-18736-1","confidence":"high"},"type":"software","title":"Low Fidelity Space Systems Analysis Tools-Orbiter Sizing Tool","abstract":"This tool sizes rough orbiter buses that include avionics, science payloads (user choice) and a scientific mass fraction and produces a baseball card for presentation.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18737_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18737-1","sourceUrl":"https://software.nasa.gov/software/LAR-18737-1","confidence":"high"},"type":"software","title":"Low Fidelity Space Systems Analysis Tools-Long Duration Habitat Sizing Tool","abstract":"This tool does parametric sizing of long term human habitats based on duration and crew size up to ten members","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18738_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18738-1","sourceUrl":"https://software.nasa.gov/software/LAR-18738-1","confidence":"high"},"type":"software","title":"Low Fidelity Space Systems Analysis Tools-Short Duration Habitat Sizing Tool","abstract":"This tool sizes short duration human habitats for short missions less than 20 days based on identified human operations requirements.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18739_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18739-1","sourceUrl":"https://software.nasa.gov/software/LAR-18739-1","confidence":"high"},"type":"software","title":"Low Fidelity Space Systems Analysis Tools-One-Way/Small Vehicle Sizing Tool","abstract":"This tool sizes small or one-way/one time use vehicles for propulsive manuvers both in and out of atmosphere. The system will provide rough Figure of Merit (FOM) estimates of mass, power, volume, and ephemeris/trajectory change capacity, and provide a rough breakdown of the intert masses, propulsive masses and payload masses. Additionally, the system provides context for the mass breakdown and is intended for small vehicles doing one or two manuvers. Small Vehicle Sizing Tool uses Microsoft Excel.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18740_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18740-1","sourceUrl":"https://software.nasa.gov/software/LAR-18740-1","confidence":"high"},"type":"software","title":"Low Fidelity Space Systems Analysis Tools-Solar Cell/Fuel Cell/Battery Sizing Tool","abstract":"This tool sizes solar power systems utilizing batteries, fuel cells and solar cells and calculates the mass, power and potential volume requirements of the system. It will provide a rough estimate of the sizes of the cells, the tank volumes and masses for the fuel cells and determining decay rates and BOL/EOL power generation demands.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18741_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18741-1","sourceUrl":"https://software.nasa.gov/software/LAR-18741-1","confidence":"high"},"type":"software","title":"Low Fidelity Space Systems Analysis Tools-Body Centric Insertion Tool","abstract":"This tool is intended to support mission architecture designers design simple orbits for vehicles entering into sphere of influence of a planet from heliocentric space. It allows architects to put in information about the dV or C3 energy state and provide information about the desired parking orbit. From either C3 or dV, it calculates the remainder dV required to take the vehicle and place it in the desired orbit based on the planet and its sphere of influence.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18742_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18742-1","sourceUrl":"https://software.nasa.gov/software/LAR-18742-1","confidence":"high"},"type":"software","title":"Low Fidelity Space Systems Analysis Tools-Thermal Protection System Sizing Tool","abstract":"This system sizes Thermal Protection Systems based on simple flight path angle assessments and mass properties of the vehicle. It provides estimates of heat loads and relevant materials.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18743_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18743-1","sourceUrl":"https://software.nasa.gov/software/LAR-18743-1","confidence":"high"},"type":"software","title":"Low Fidelity Space Systems Analysis Tools-Planetary Ascent/Descent dV Tool","abstract":"This tool is designed to provide rough estimates for a landing on the surface of a planet with no atmosphere. Data from this tool is used to drive sizing calculations later.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18744_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18744-1","sourceUrl":"https://software.nasa.gov/software/LAR-18744-1","confidence":"high"},"type":"software","title":"Low Fidelity Space Systems Analysis Tools-Heliocentric Trajectory Tool","abstract":"This tool is produced is take advantage of pre-existing resources of known lambert trajectory solutions to various bodies, NEA's and more. This database is created and maintained by Ames Research Center and provides a two significant figure estimate of the injection deltaV to get to the desired orbit and the insertion dV to stop at the location. Additionally, it does calculate flyby maneuver effects.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18745_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18745-1","sourceUrl":"https://software.nasa.gov/software/LAR-18745-1","confidence":"high"},"type":"software","title":"Low Fidelity Space Systems Analysis Tools-Fission Power Sizing Tool","abstract":"The system uses lifetime, chosen archetype and EOL power demand to determine the mass and power characteristics of a fission power system.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18746_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18746-1","sourceUrl":"https://software.nasa.gov/software/LAR-18746-1","confidence":"high"},"type":"software","title":"Low Fidelity Space Systems Analysis Tools- Body-Centric Orbit Change Tool","abstract":"This tool provides dV requirements for orbit changes in inclination, periapsis and apoapsis.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18752_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18752-1","sourceUrl":"https://software.nasa.gov/software/LAR-18752-1","confidence":"high"},"type":"software","title":"Low Fidelity Space Systems Analysis Tools-Destination Campaign Tools","abstract":"This tool provides a rough mass estimate of ground campaign equipment.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18789_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18789-1","sourceUrl":"https://software.nasa.gov/software/LAR-18789-1","confidence":"high"},"type":"software","title":"DEVELOP DRIP and SLIP Landslide Detection Package (DRIP-SLIP)","abstract":"The DRIP-SLIP model automatically analyzes red band spectral information and soil moisture information derived from Landsat 8 and ASTER and SRTM data , at a fine to moderate resolutions, to determine areas that might be new landslides. This is important to help increase the temporal latency for landslide products that emergency managers, planners, and scientists are able to use in their work.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/DRIP-SLIP","license":null}},{"forgeId":"forge_nasa_lar_18794_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18794-1","sourceUrl":"https://software.nasa.gov/software/LAR-18794-1","confidence":"high"},"type":"software","title":"Chesapeake Bay Chlorophyll Hotspot Identifier (CBCHI)","abstract":"The Chesapeake Bay Chlorophyll Hotspot Identifier takes in raw Landsat 8 surface reflectance product and produces two maps to be opened in ArcMap that can be used to identify chlorophyll hotspots. It also creates a true color image .","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/CBCHI","license":null}},{"forgeId":"forge_nasa_lar_18798_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18798-1","sourceUrl":"https://software.nasa.gov/software/LAR-18798-1","confidence":"high"},"type":"software","title":"PolyCARP: Algorithms and Software for Computations with Polygons","abstract":"PolyCARP is a package of algorithms, including both their formal models and software implementations, for computing containment, collision, resolution, and recovery information for polygons. The intended applications of PolyCARP are related, but not limited, to safety critical systems in air traffic management. One application is weather avoidance. A weather cell can be approximated by a polygon, and PolyCARP provides algorithms to detect whether a trajectory will intersect such a polygon in the near future and will provide maneuver guidance to avoid the polygon. If the trajectory is inside the polygon at the current time, PolyCARP provides algorithms for maneuver guidance to exit the polygon. Another application is ensuring that an aircraft stays inside a predetermined safety region, also known as assured containment, and PolyCARP provides algorithms that ensure that a point is inside or outside a particular polygonal region. Another application is obstacle avoidance by an aircraft. There are several functionalities provided by PolyCARP. There are algorithms to insure that a point is contained in or excluded from a polygon. There are also collision detection algorithms that determine if a moving point intersects a polygon, including the case where the polygon is moving or even warping over time, as well as where the polygon and the point are following piecewise linear trajectories. There are algorithms that resolve potential collisions between and point and a polygon by providing collision-free trajectories, and there are algorithms that compute new trajectories to regain separation from a polygon.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/polycarp","license":null}},{"forgeId":"forge_nasa_lar_18832_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18832-1","sourceUrl":"https://software.nasa.gov/software/LAR-18832-1","confidence":"high"},"type":"software","title":"Composite Damage (CompDam) Progressive Damage Analysis Software","abstract":"The Composite Damage (CompDam) Progressive Damage Analysis software is developed for the prediction of damage onset, damage progression and structural collapse of structures manufactured of fiber-reinforced plastic laminates. The emphasis has been on development of an analysis capability for application at the structural level. Hence, modeling of damage progression is undertaken at the meso-scale, where each ply of a laminate is represented as a homogenous orthotropic continuum. All of the composite damage mechanisms (matrix cracking, fiber breaking and kinking, and delamination) and their interactions are represented. The CompDam software is implemented as user written subroutines for use with the Abaqus commercial finite element code. Input for CompDam includes ply-level material properties, and interface properties obtained from standard material characterization tests. The output from CompDam includes damage variables associated with each damage mode. These damage variables describe the evolution of damage and are used to generate updated structural constitutive matrices and load redistribution as damage evolves.","category":"materials_coatings","categoryRaw":"materials and processes","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/CompDam_DGD","license":null}},{"forgeId":"forge_nasa_lar_18862_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18862-1","sourceUrl":"https://software.nasa.gov/software/LAR-18862-1","confidence":"high"},"type":"software","title":"Palm Oil Plantation Predictor (POPP)","abstract":"This software is designed to simplify the process of manipulating and converting both satellite and ancillary data so that it can be used within the Maxent modeling software. This tool can convert vector or raster data into the correct format and process all files in order to have identical rows, columns, resolution, and extent.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/POPP","license":null}},{"forgeId":"forge_nasa_lar_18877_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18877-1","sourceUrl":"https://software.nasa.gov/software/LAR-18877-1","confidence":"high"},"type":"software","title":"Land Surface Temperature MODIS Visualization (LaSTMoV)","abstract":"Extreme heat causes and exacerbates a number of health problems, leading to hospitalization and death in some cases. The problem of severe heat is notably felt in Maricopa County, Arizona, where the socially disadvantaged and physically vulnerable are especially susceptible to the effects of extreme heat. Several organizations, including the Arizona Department of Health Services and the Phoenix Heat Relief Network, are working to create more effectively placed cooling centers and heat warning systems to aid those with the highest risk of exposure. This project created a Python tool using Aqua Moderate Resolution Imaging Spectrometer (MODIS) land surface temperature parameters to generate heat maps that reference demographics data on extreme heat days.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/LaSTMoV","license":null}},{"forgeId":"forge_nasa_lar_18894_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18894-1","sourceUrl":"https://software.nasa.gov/software/LAR-18894-1","confidence":"high"},"type":"software","title":"Mission Operations Cost Estimation Tool (MOCET)","abstract":"The Mission Operations Cost Estimation Tool (MOCET) is a model developed by the Aerospace Corporation in partnership with NASAs Science Office for Mission Assessment (SOMA). MOCET provides a new capability to generate cost estimates for the operational, or Phase E, portion of NASA science missions. The model implements new Cost Estimating Relationships (CERs) that were derived from historical data for various mission operation stages as applicable to the Planetary Science, Earth Science, and Astrophysics/Heliophysics Explorer missions.","category":"operations","categoryRaw":"business systems and project management","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_18928_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18928-1","sourceUrl":"https://software.nasa.gov/software/LAR-18928-1","confidence":"high"},"type":"software","title":"CEOS Data Cube Platform v.2 (CEOS2)","abstract":"The Committee on Earth Observation Satellites (CEOS) has long recognized a need for data processing infrastructure to support Earth science objectives in developing countries. Forest preservation initiatives, carbon measurement initiatives, water management and agricultural monitoring are just few examples of causes that can benefit greatly from remote sensing data. Currently, however, many developing nations lack the in-country expertise and computational infrastructure to utilize remote sensing data.The CEOS Data Cube Platform provides a flexible model to address these needs. The CEOS Data Cube Platform is a data processing platform for Earth science data, with a focus on remote-sensing data. The platform provides a data ingestion framework that includes support for automated ingestion of a wide variety of remote sensing data products. The data products are ingested into an N-dimensional data array that abstracts away management of distinct acquisitions. The platform has a tiered API for data processing and a data/application platform layer for higher-level access.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/ceos-seo/Data_Cube_v2","license":null}},{"forgeId":"forge_nasa_lar_18945_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-18945-1","sourceUrl":"https://software.nasa.gov/software/LAR-18945-1","confidence":"high"},"type":"software","title":"Precipitation Interface for the Middle East (PrIME)","abstract":"The Precipitation Interface for the Middle East (PrIME) is a tool which allows users to visualize data from several sources and to extract data at points of interest. There are seven types of data loaded into the interface (SRTM, MOD16, GRACE, TRMM, GPM, school location points, and a study area polygon). When the user clicks on a point within the study area extent (where there is data present), the interface returns three graphs, each of which shows the historical amount of an climatological variable (precipitation, groundwater, and evapotranspiration). The interface automatically loads all data and centers the map around the study area, though layers can be turned on and off as the user desires.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/PrIME","license":null}},{"forgeId":"forge_nasa_lar_19000_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19000-1","sourceUrl":"https://software.nasa.gov/software/LAR-19000-1","confidence":"high"},"type":"software","title":"Floating Node Method Composites Simulation Toolbox [FNMCST]","abstract":"FNMCST Floating Node Method Composites Simulation Toolbox, is a research code used to investigate and develop an high-fidelity numerical approach, using the floating node method, and advanced physical models, to simulate damage progression in composite materials with high fidelity and in 3D.","category":"materials_coatings","categoryRaw":"materials and processes","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_19004_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19004-1","sourceUrl":"https://software.nasa.gov/software/LAR-19004-1","confidence":"high"},"type":"software","title":"Advanced Acoustic Model v2 (AAM2)","abstract":"AAM is a computer program that calculates community noise from aircraft flight operations. It is a simulation model, computing time histories of noise for arbitrary vehicle flight operations. The model can accommodate multiple noise sources (Rotors, engines, airframe (flaps, landing gear, slats, etc.), each represented by a sphere of spectral data at a reference distance. Propagation to the ground accounts for spherical spreading, atmospheric absorption, ground impedance effects, and weather effects. Spectral levels and a variety of community noise metrics are computed and can be plotted on a flat ground or non-flat terrain.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_19012_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19012-1","sourceUrl":"https://software.nasa.gov/software/LAR-19012-1","confidence":"high"},"type":"software","title":"Elkhorn Slough Vegetation Imagery Assessment (ESVIA)","abstract":"The intention of this script is to conduct marsh vegetation health analyses using remotely sensed imagery sources. The script analyzes vegetation change in a historical time-series using Landsat imagery, as well as current day vegetation productivity using Sentinel 2A imagery. Included in the script are operations such as image acquisition, image processing, and applications of vegetation indices with band combinations highlighting vegetation.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/ESVIA","license":null}},{"forgeId":"forge_nasa_lar_19015_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19015-1","sourceUrl":"https://software.nasa.gov/software/LAR-19015-1","confidence":"high"},"type":"software","title":"Pixelwise Correlation-Based Landscape Classification (PiCo)","abstract":"PiCo was written in attempt to automate and regionalize the Climate Landscape Response (CLaRe) metrics developed by Wallace et al 2016. The CLaRe metric system was created to map invasive buffelgrass in the southwestern United States. This grass both propagates and benefits from increased wildfire events, and is a threat to the local ecosystems within the Sonoran Desert. Buffelgrass responds to precipitation quicker than native vegetation. This behavior is what CLaRe captures. Correlation values derived from regression analysis between Normalized Difference Vegetation Index (NDVI) and precipitation values are used to separate pixels invaded by buffelgrass from those that are not. PiCo, written in R, performs a pixelwise regression analysis to produce rasters whose correlation values can be evaluated to target buffelgrass.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/PiCo","license":null}},{"forgeId":"forge_nasa_lar_19032_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19032-1","sourceUrl":"https://software.nasa.gov/software/LAR-19032-1","confidence":"high"},"type":"software","title":"Move Away Superfluous Clouds (MASC)","abstract":"Source code for removal of clouds, cloud shadow, water, and snow pixels from Landsat scenes using the cloud mask layer that is provided withLandsat data .","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/MASC","license":null}},{"forgeId":"forge_nasa_lar_19113_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19113-1","sourceUrl":"https://software.nasa.gov/software/LAR-19113-1","confidence":"high"},"type":"software","title":"CCROP (Cover Crop Remotely Observed Performance)","abstract":"The source code extracts NDVI values from Landsat 5, Landsat 8, and Sentinel-2 images. NDVI values are averaged within field boundaries for each image and exported as a table with field ID and average NDVI value (with image date as the column header) for each date in a given range.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/CCROP","license":null}},{"forgeId":"forge_nasa_lar_19121_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19121-1","sourceUrl":"https://software.nasa.gov/software/LAR-19121-1","confidence":"high"},"type":"software","title":"Scalable Implementation of Finite Elements by NASA (ScIFEN) v.2","abstract":"Scalable Implementation of Finite Elements by NASA (ScIFEN) is a three-dimensional solid mechanics code that provides a parallel implementation of the finite element method (FEM). Generally speaking, the FEM is a numerical technique for finding approximate solutions to partial differential equations (PDEs). In particular, ScIFEN uses the FEM to solve the PDEs that govern the motion and deformation of solid materials under the action of external loads. Thus, ScIFEN uses input information describing a solid's geometry, material properties, applied forces, etc. to compute and return the resulting mechanical response (e.g. displacements, stresses, etc.). ScIFEN is a parallel code written in C++ and designed to scale to large problems that can be run on supercomputers across many processors. This scalability and efficiency is enabled through the utilization of several open-source high performance computing libraries. The most heavily used libraries include: 1) Portable Extensible Toolkit for Scientific Computation (PETSc) for the parallel solution of linear/non-linear systems of equations, 2) Hierarchical Data Format (HDF5) for general parallel input/output, and 3) Mesh Orientated Database (MOAB) for storage and managing finite element mesh data in parallel. ScIFEN includes several standard linear and non-linear material models including linear elastic isotropic, linear hardening plasticity, and crystal plasticity models. It supports various applied loadings including prescribed displacements and forces, surface tractions and pressures, and body forces. ScIFEN supports both implicit time integration (ScIFEi driver) and explicit time integration (ScIFEx driver).","category":"materials_coatings","categoryRaw":"materials and processes","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_19127_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19127-1","sourceUrl":"https://software.nasa.gov/software/LAR-19127-1","confidence":"high"},"type":"software","title":"FAULT (Flood Analysis Utilizing Landsat and ArcMap Tools)","abstract":"During this project, an automated script was generated that performs high-level flood analysis to relieve work load for end-users. The script incorporated Landsat 8 Operational Land Imager (OLI) tiles and utilized computer-learning techniques to generate accurate water extent maps. The script referenced the Moderate Resolution Imaging Spectroradiometer (MODIS) land-water mask, to isolate areas of flood induced waters. These areas were overlaid onto the National Land Cover Databases (NLCD) land cover data, the Oak Ridge National Laboratorys LandScan data, and Homeland Infrastructure Foundation-Level Data (HIFLD) to determine the classification of areas impacted and the population density affected by flooding.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/FAULT","license":null}},{"forgeId":"forge_nasa_lar_19128_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19128-1","sourceUrl":"https://software.nasa.gov/software/LAR-19128-1","confidence":"high"},"type":"software","title":"Automated Snow Index Tool (ASIT)","abstract":"The software will load in image collections from Google Earth Engine from different sensors (Landsat 5, 7, and 8, Sentinel 2a, 2b) and the code will identify pixels meeting certain criteria as snow using two snow indices (Normalized Difference Snow Index (NDSI) and the Saito S3 Snow Index. Then the area of snow can be calculated for a region or for an individual watershed. Then a chart can be generated which would create a visual that shows the change in area covered by snow across images as a percentage of the whole area. As the sky islands stretch across much of Southeastern Arizona, the software also eliminates the need to download multiple images from differing rows/paths.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/ASIT","license":null}},{"forgeId":"forge_nasa_lar_19151_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19151-1","sourceUrl":"https://software.nasa.gov/software/LAR-19151-1","confidence":"high"},"type":"software","title":"Hydrological Anomaly Engine (HAE)","abstract":"Using the cloud-based computing power of Google Earth Engine (GEE), the Hydrologic Anomaly Index (HAE) is capable of uploading and analyzing large amounts of Earth observation climate data for the purpose of hydrologic analysis and monitoring. The end-user will be able to pull from and modify a library of scripts that are stored in Earth Engine, as well as upload and access data stored on a private data catalog. The final stage of development of the tool will include a more user-friendly application built using Googles App Engine, in which users will be able to display data products and interactive maps.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/HAE","license":null}},{"forgeId":"forge_nasa_lar_19156_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19156-1","sourceUrl":"https://software.nasa.gov/software/LAR-19156-1","confidence":"high"},"type":"software","title":"Regional Incendiary Fuel Risk Assessment Framework (RIFRAF)","abstract":"Climate data from the Google Earth Engine library was leveraged in a script to calculate the fire potential in the Missouri River Basin. Variables instrumental to fire potential were drought conditions, temperature, relative humidity, precipitation, wind speed, and fuel moisture.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/RIFRAF","license":null}},{"forgeId":"forge_nasa_lar_19181_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19181-1","sourceUrl":"https://software.nasa.gov/software/LAR-19181-1","confidence":"high"},"type":"software","title":"COVER (Calibrate Observed Vegetation Estimates Remotely)","abstract":"The source code provided develops calibration models using linear regression models with in-situ field data . The calibration models are then used to predict biomass (log), nitrogen percent, and nitrogen content for Landsat images from 2006-2016. Model results and data tables are output as separate files for each field season (i.e. winter and spring seasons).","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/COVER","license":null}},{"forgeId":"forge_nasa_lar_19183_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19183-1","sourceUrl":"https://software.nasa.gov/software/LAR-19183-1","confidence":"high"},"type":"software","title":"LaRC MarsGIS Human Landing Site & Exploration Zone Viewer and Collaboration Tool","abstract":"The innovation includes a GIS (Geographical Information System) layer and a web-based GIS service. The GIS layer includes the geospatial location and spatial extent of the Exploration Zones(EZs), regions of interest (ROIs), and data characterizing the science and resources purported to be available. These data were extracted from publicly-available abstracts and presentations to the HLS2 EZ Workshop in October 2015 as proposals for the first human landing site on Mars. The web-based service allows users to view and analyze this layer; verify, alter, and annotate the layers data , add/edit/delete new EZs, and will support users collaboration on these data . The layer was developed under the auspices of a SACD investment fund opportunity, through the labors of five students. The NASA civil servant defined requirements for, and students used ESRI ArcGIS to draw the EZs and ROIs; and associated each EZ and ROI with tabulated data from authors papers. The GIS tool was developed by the inventors listed in this disclosure, and coded by students and the STARSS III contractor (under auspices of SACD investment fund and Atmospheric Science Data Center (ASDC)) based on the ESRI ArcGIS platform and available widgets and tools, through NASAs enterprise agreement with ESRI.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_19191_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19191-1","sourceUrl":"https://software.nasa.gov/software/LAR-19191-1","confidence":"high"},"type":"software","title":"Water Resources Integration Toolbox (WRIT)","abstract":"For the AcoFixDual_Tool: Geolocates and rescales ACOLITE output to make it useful in ArcMap.Batch netCDF to Raster Tool: Batch converts a netCDF file (output from ACOLITE) into a raster layer.Batch Project Rasters Tool: Specific to MBWR, Converts the projection of the data from WGS UTM Zone 17N meters, to NAD_1983_StatePlane_Florida_East_FIPS_0901_Feet using the WGS_1984_(ITRF00)_To_NAD_1983 transformation.Rename Filenames Tool: Truncates all rasters in folder by the desired character stringTXT File for Landsat and ACOLITE images Tools: Created txt files of folder paths for all Landsat or ACOLTIE Images in a folder.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/WRIT","license":null}},{"forgeId":"forge_nasa_lar_19195_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19195-1","sourceUrl":"https://software.nasa.gov/software/LAR-19195-1","confidence":"high"},"type":"software","title":"Simple Analysis of Vegetative Trends in Earth Engine (SAVeTrEE)","abstract":"SAVeTrEE is a script within Google Earth Engine for classifying areas of vegetation mortality. It prompts the user for a year, duration, and spectral index for which a mortality map should be produced, then fits a trend line to an imagery time sequence of vegetative spectral index values calculated from Landsat multispectral data. The slope of the trend line, as well as the spectral index values, are used in determining the final classification of each pixel within the study area. Classification categories are: 1) Growing 2) Mortality (declining) 3) Stable Vegetation and 4) Stable Barren.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/SAVeTrEE","license":null}},{"forgeId":"forge_nasa_lar_19197_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19197-1","sourceUrl":"https://software.nasa.gov/software/LAR-19197-1","confidence":"high"},"type":"software","title":"Land Use Classification Tool (LUCT)","abstract":"We used the Google Earth Engine Code interface to create a classification of land use on the United States Virgin Islands (USVI). We used six classes: water, low density residential, high-density residential, forest/shrub, agriculture and barren. We included DEM, classification points, and landsat imagery bands to analyze the imagery. Our final product is at a 30 meter spatial scale.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/LUCT","license":null}},{"forgeId":"forge_nasa_lar_19205_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19205-1","sourceUrl":"https://software.nasa.gov/software/LAR-19205-1","confidence":"high"},"type":"software","title":"RAIn - Rainfall Analysis Integration","abstract":"This software analyzes Tropical Rainfall Measuring Mission (TRMM), Global Precipitation Measurement (GPM), and Climate Hazards Group InfraRed Precipitation with Station (CHIRPS) precipitation data. It also analyzes Terra Moderate Resolution Imaging Spectrometer (MODIS) Normalized Difference Vegetation Index (NDVI), Normalized Difference Drought Index (NDDI) and Land Surface Temperature (LST) data. Areas are mapped on the screen and corresponding trend charts are produced. The software also provides a visual comparison with social and economic variables including human population density, demographic, and conflict data to better understand the dynamics within these stressed areas.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/RAiN","license":null}},{"forgeId":"forge_nasa_lar_19211_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19211-1","sourceUrl":"https://software.nasa.gov/software/LAR-19211-1","confidence":"high"},"type":"software","title":"MaRSHE- Marsh Remote Sensing Health Evaluation","abstract":"This tool includes three general types of scripts. The first one extracts average NDVI values from Landsat 5 and Landsat 8 image collections for specified reference dates (typically a period of 10-15 years). Anomalies in NDVI values are then derived from Landsat 5 & 8 reference image collections from later dates (typically the year after the reference period to present). Various graphs and charts are produced showing positive and negative NDVI changes for specified points. The results are also visualized on the map as either areas of NDVI gain (displayed in green) or NDVI loss (displayed in red).The second types of scripts included scripts that perform unsupervised classifications to determine marsh extent for a variety of years and were made by applying a mask over the specified study area that incorporates elevation data to exclude regions over a specified height above average sea-level. These scripts require the user to choose classified pixel clusters that represent marsh land cover by using the Google Earth Inspector tab and then entering those values into the script to generate the marsh extent maps. Results of these scripts include classification maps for various years (2000, 2005, 2010, 2015, etc.). The user can then decide to export those results into either their Assets or their Drive, or both.A third type of script is used for statistics regarding the classified maps generated in the classification scripts. These statistics include total pixel number and total marsh area calculated into square meters after the marsh extent pixels are clipped to our study area (the State of Maryland).","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/MARSHe","license":null}},{"forgeId":"forge_nasa_lar_19222_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19222-1","sourceUrl":"https://software.nasa.gov/software/LAR-19222-1","confidence":"high"},"type":"software","title":"Kodiak's Boolean Checker Software Module","abstract":"Kodiak is a software implementation of a branch-and-bound algorithm for rigorous approximations of expressions involving nonlinear real arithmetic. It includes an optimizer for nonlinear real functions, a solver for nonlinear inequalities, and an Application Programming Interface (API) to integrate directly with other software verification tools. Kodiak's Boolean Checker Software Module is an implementation of a general mixed boolean/real expression checker that is integrated into Kodiak's global optimization solver.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/kodiak","license":null}},{"forgeId":"forge_nasa_lar_19227_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19227-1","sourceUrl":"https://software.nasa.gov/software/LAR-19227-1","confidence":"high"},"type":"software","title":"Program Round-Off Certifier via Static Analysis (PRECiSA) with Kodiak Integration","abstract":"PRECiSA, which in the current invention disclosure stands for Program Round-off Certifier via Static Analysis , is a fully automatic static analyzer for floating-point valued functions. It computes an over-approximation of the round-off error of a given floating-point expression, along with a formal certificate that ensures the correctness of the estimated error. The current invention extends PRECiSA in three ways:* it enables the use of external tools such as the global optimization tool Kodiak to compute numerical bounds in an efficient way,* it adds input language support for loops and recursion, and * it implements a more efficient analysis of nested conditionals.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/precisa","license":null}},{"forgeId":"forge_nasa_lar_19235_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19235-1","sourceUrl":"https://software.nasa.gov/software/LAR-19235-1","confidence":"high"},"type":"software","title":"Land Cover Change Detection Tool (LCD)","abstract":"The goal of this project was to create a script within Google Earth Engine (GEE) that is able to analyze study areas for significant vegetation change and to incorporate ancillary datasets that allow the user to evaluate possible causation of this loss or gain. The Normalized Difference Vegetation Index (NDVI) for the study time period is calculated and then compared to the maximum and minimum NDVI from a baseline range of years in order to calculate Relative Greenness (RG). The change in RG from the previous year is found, and this allows the user to identify abrupt change in vegetation. Normalized Burn Ratio (NBR) and USDA Croplands Dataset have been added as additional datasets that can help establish if the change was caused by a fire or by a change in crop type. Recent available NAIP imagery for the study area is also included, as an example of what is available for high resolution imagery within GEE. Based on a date input by the user, the map viewer displays the RG, the change in RG, the percent change in RG, and the NBR, along with the Cropland layer from that year and NAIP imagery taken closest in time to the requested display date.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/LCD","license":null}},{"forgeId":"forge_nasa_lar_19281_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19281-1","sourceUrl":"https://software.nasa.gov/software/LAR-19281-1","confidence":"high"},"type":"software","title":"Independent Configurable Architecture for Reliable Operations of Unmanned Systems with Distributed On-board Services (ICAROUS-2)","abstract":"Independent Configurable Architecture for Reliable Operations of Unmanned Systems with Distributed On-board Services (ICAROUS-2) is the next generation of the ICAROUS software architecture. As its predecessor, ICAROUS-2 enables the robust integration of mission specific software modules and highly-assured core software modules for building autonomous unmanned aircraft applications. In this new architecture, the core software modules are implemented as distributed on-board services that communicate using a publisher/subscriber communication layer. ICAROUS-2 independent architecture provides support for integration with standard and open source communication and computation layers such as Core Flight Systems (CFS), Data Distribution Service (DDS), MAVLink, and Plan Execution Interchange Language (PLEXIL).","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/icarous","license":null}},{"forgeId":"forge_nasa_lar_19339_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19339-1","sourceUrl":"https://software.nasa.gov/software/LAR-19339-1","confidence":"high"},"type":"software","title":"Formal Interactive Verification Environment for the Plan Execution Interchange Language (PLEXIL5)","abstract":"The Plan Execution Interchange Language (PLEXIL) is an open source synchronous language developed by NASA for commanding and monitoring autonomous systems. PLEXIL Formal Interactive Verification Environment (PLEXIL5) is a tool that implements a formal executable semantics of PLEXIL. PLEXIL5 includes a graphical interface that enable access to formal verification techniques such as model-checking, symbolic execution, theorem proving, and static analysis of plans. The graphical environment supports formula editing and visualization of counterexamples, interactive simulation of plans at different granularity levels, and random initialization of external environment variables.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/PLEXIL5","license":null}},{"forgeId":"forge_nasa_lar_19345_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19345-1","sourceUrl":"https://software.nasa.gov/software/LAR-19345-1","confidence":"high"},"type":"software","title":"New Statistical Trajectory Estimation Program (NewSTEP)","abstract":"NewSTEP is a matlab-based iterative extended Kalman filter/smoother designed for solving trajectory reconstruction problems for flight test experiments. The Kalman filter is formulated to blend various types of measurement data to obtain the best estimate of the vehicle trajectory. The code also produces uncertainty estimates based on the state covariance matrix. The equations of motion are formulated in order to include the eects of several systematic error sources, whose values may also be estimated by the fltering routines. The measurement models include Inertial Measurement Units (IMU), Global Positioning System (GPS), ground-based tracking radar, magnetometers, air data sensors, and meteorological measurements. The code can also produce estimates of the as-flown vehicle aerodynamic force and moment coefficients.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_19359_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19359-1","sourceUrl":"https://software.nasa.gov/software/LAR-19359-1","confidence":"high"},"type":"software","title":"Stochastic Reduced Order Models with Python (SROMPy)","abstract":"The Stochastic Reduced Order Models with Python (SROMPy) software package is code written in Python to help solve uncertainty quantification and propagation problems. Stochastic Reduced Order Models (SROMs) are low-dimensional, discrete representations of a given random vector being modeled that facilitate efficient stochastic calculations. SROMs can be viewed as a smart Monte Carlo method - using the concept for uncertainty propagation is similarly straightforward, but can significantly reduce computation time. An SROM is formed for a given target random vector by solving an optimization problem that determines it's parameters by minimizing the error between the statistics of the SROM and the target. Once the SROM is formed, it can be use to efficiently perform a probabilistic analysis . The SROMPy software package is a tool to solve the optimization problem efficiently to generate an SROM that can be used to propagate uncertainty through a given model.","category":"mechanical_systems","categoryRaw":"structures and mechanisms","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/SROMPy","license":null}},{"forgeId":"forge_nasa_lar_19386_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19386-1","sourceUrl":"https://software.nasa.gov/software/LAR-19386-1","confidence":"high"},"type":"software","title":"iMMOD (Interactive Model of Mosquito Distribution)","abstract":"This software visualizes NASA Earth observations, citizen science and public health data relevant to mosquito habitat suitability by season. This software also implements a seasonal model to predict habitat suitability for mosquitoes in Western Europe.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/iMMOD","license":null}},{"forgeId":"forge_nasa_lar_19472_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19472-1","sourceUrl":"https://software.nasa.gov/software/LAR-19472-1","confidence":"high"},"type":"software","title":"SDCI (Scaled Drought Condition Index)","abstract":"This innovation processes Normalized Difference Vegetation Index, land surface temperature, and precipitation data . It then scales each component based on regional maxima and minima. Each scaled value is then inserted into the Scaled Drought Condition Index equation in order to produce a monthly drought index value for each pixel in the study area.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/SDCI","license":null}},{"forgeId":"forge_nasa_lar_19474_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19474-1","sourceUrl":"https://software.nasa.gov/software/LAR-19474-1","confidence":"high"},"type":"software","title":"FiSSH (Find Suitable Spawning Habitat)","abstract":"This software utilizes Earth observation and citizen science data collected by the Grunion Greeters project to analyze ocean conditions and how they may relate to movement of the California grunion. The grunion is famous for beach spawning, and this tool will allow the user to get an idea of how large a spawning event is expected to be. This output is based on past spawning events and ocean conditions at those times. Moreover, interactive maps will allow the user to visualize spatially what was happening in the surrounding coastal region during a particular time frame.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/FiSSH","license":null}},{"forgeId":"forge_nasa_lar_19517_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19517-1","sourceUrl":"https://software.nasa.gov/software/LAR-19517-1","confidence":"high"},"type":"software","title":"Sequential Monte Carlo Sampling with Python (SMCPy)","abstract":"Uncertainty quantification (UQ) is essential to provide meaningful and reliable predictions of real-world system performance. One major obstacle for the implementation of statistical methods for UQ is the use of expensive computational models. Classical UQ methods such as Markov chain Monte Carlo (MCMC) generally require thousands to millions of model evaluations, and, when coupled with an expensive model, result in excessive solve times that can render the analysis intractable. These methods are also inherently serial, which prohibits speedup by high performance computing. Recently, Sequential Monte Carlo (SMC) has emerged as a powerful alternative to MCMC. In contrast, this method allows for parallel model evaluations, realizing significant speedup. This software is an implementation of SMC that uses the Message Passing Interface (MPI) to provide users general access to parallel UQ methods in Python 2.7.To operate the code, the user supplies a computational model built in Python 2.7, defines prior distributions for each of the model parameters to be estimated, and provides data to be used for calibration. SMC sampling can then be conducted with ease through instantiation of the SMC class and a call to the sample() method. The output of this process is an approximation of the parameter posterior probability distribution conditioned on the data provided.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/SMCPy","license":null}},{"forgeId":"forge_nasa_lar_19547_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19547-1","sourceUrl":"https://software.nasa.gov/software/LAR-19547-1","confidence":"high"},"type":"software","title":"CORAL-TT (Calculating Oscillations in Regional Aquatic Locations - Temperature and Turbidity)","abstract":"The JavaScript code intended for Google Earth Engine (GEE) allows easy access to all data available on this free platform, calculates Normalized Difference Turbidity Index (NDTI) median over years and seasons, and calculates fluctuations between seasons. The code combines Surface Reflectance Tier 1 data from Landsat 5 Thematic Mapper (TM), Landsat 7 Enhanced Thematic Mapper Plus (ETM+), and Landsat 8 Operational Land Imager (OLI) data from 1991 to 2018, and Level 2 Sentinel-2 Multispectral Instrument (MSI) data from 2015 to 2018. Furthermore, the software maps SST using Level 3 Aqua Moderate Resolution Imaging Spectroradiometer (MODIS) processed by Earth Observing System Data and Information System (EOSDIS). The GEE user interface presents a graph that allows users to see fluctuations in SST at any given selected point of interest over time. The user can also specify dates, image collections, and a study area to display and export a map of interest.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-DEVELOP/CORAL-TT","license":null}},{"forgeId":"forge_nasa_lar_19641_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19641-1","sourceUrl":"https://software.nasa.gov/software/LAR-19641-1","confidence":"high"},"type":"software","title":"WebGS: A Web-based Platform for Multi-UAV Flight Visualization and Simulation","abstract":"As UAV traffic management development and testing has become more complicated, the need has arisen for tools that can control and visualize multi-vehicle interactions. WebGS is a tool for test design and automated simulation execution (repeatable and adjustable flight planning). It provides a platform for multi-aircraft interaction and visualization , and allows for live flights to interact with simulated vehicles. It is compatible with other flight control software and multiple aircraft simulators. Also, WebGS allows for remote monitoring and multi-user interactions. WebGS provides a platform to handle an increasingly complex and dynamic simulation and operational environments, while simplifying the user experience, and providing an easy to understand visual overview of a complex airspace environment.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/webgs","license":null}},{"forgeId":"forge_nasa_lar_19727_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19727-1","sourceUrl":"https://software.nasa.gov/software/LAR-19727-1","confidence":"high"},"type":"software","title":"AladynPi \u2013 Adaptive Neural Network Molecular Dynamics Simulation Code with Physically Informed Potential: Computational Materials Mini-Application","abstract":"AladynPi is a basic molecular dynamics codes written in FORTRAN 2008, which is designed to demonstrate the use of artificial neural networks (ANNs) in atomistic simulations. The role of ANNs is to efficiently reproduce the very complex energy landscape resulting from the atomic interactions in materials with the accuracy of the more expensive quantum mechanics-based calculations. An input for the ANN is a set of structure coefficients, characterizing the local atomic environment of each atom, for which the atomic energy is obtained in the ANN inference process. The ANN gives optimized parameters for a predefined empirical function, known as bond-order-potential (BOP). Thus parameterized BOP function is then used to calculate the energy of an atom. AladynPi code is being released to serve as a training testbed for students and professors in academia to explore possible optimization algorithms for parallel computing on multiprocessor computers or computers equipped with graphic processing units (GPUs).","category":"materials_coatings","categoryRaw":"materials and processes","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/aladynpi","license":null}},{"forgeId":"forge_nasa_lar_19800_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19800-1","sourceUrl":"https://software.nasa.gov/software/LAR-19800-1","confidence":"high"},"type":"software","title":"PanNDE","abstract":"This disclosure describes software and its framework for physics-based simulation of nondestructive evaluation (NDE). The software is comprised of core plugin interfaces for mesh formats, simulation metadata, and simulation results. This is paired with an implementation of an ultrasound inspection model as a demonstration case. The plugin software architecture allows for independent developability and testing of sub-modules for improved reliability and improved software validation & verification. The aim is to open-source the code to provide a vehicle for collaborative development by the Computational NDE community. The current software is a new implementation of the Ultrasound Simulation Code for 3D Curved Fiber Reinforced Composite Laminates LAR-19578-1","category":"mechanical_systems","categoryRaw":"structures and mechanisms","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/PanNDE","license":null}},{"forgeId":"forge_nasa_lar_19859_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19859-1","sourceUrl":"https://software.nasa.gov/software/LAR-19859-1","confidence":"high"},"type":"software","title":"Exploration Visualization Environment Version 2.15","abstract":"The Exploration Visualization Environment (EVE) is a simulation, visualization , and analysis system designed to integrate engineering data with a virtual environment in support of the design and planning of space based missions. Through the integration of time dependent data with detailed graphical models within a full scale three dimensional solar system or independent reference frame, the analyst can gain valuable insight into the correlation of data with simulation events. EVE provides a rich set of navigation tools, in both time and space, to enable the user to analyze the data. Version 2.15 of EVE has built upon previously released versions, enhancing analysis capabilities, greater usability, and enhanced input and output features. EVE has been developed to run cross platform under Linux, Windows and Mac.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_19979_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-19979-1","sourceUrl":"https://software.nasa.gov/software/LAR-19979-1","confidence":"high"},"type":"software","title":"HZETRN2020","abstract":"HZETRN2020 is the latest evolution of the HZETRN space radiation transport code. It is a deterministic radiation transport code capable of calculating the transport of the large variety and broad energy spectra of particles found in the space environment through shielding materials. HZETRN2020 contains updated algorithms for calculating three dimensional transport in user-defined combinatorial or ray-traced geometry, or users can opt to create an interpolation database for various thicknesses of one to three user defined materials using a \"straight ahead\" (1D) transport algorithm. Pions and muons are explicitly coupled to the neutron and light ion solutions in HZETRN2020. HZETRN2020 supports calculations for Galactic Cosmic Ray (GCR), Solar Particle Event (SPE), and Low Earth Orbit (LEO) environments. HZETRN2020 also allows the input of user-defined environment boundary conditions, and SPE environment options include fits to historic events and spectra defined by the user with commonly used fitting functions.","category":"biomedical_health","categoryRaw":"crew and life support","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_20075_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-20075-1","sourceUrl":"https://software.nasa.gov/software/LAR-20075-1","confidence":"high"},"type":"software","title":"Equivalent Plate Structural Modeling (EPSM) computer program.","abstract":"The Equivalent Plate Structural Modeling (EPSM) computer program analyzes wing-like structures using high-order Legendre polynomials to define displacement systems. A wing, tail or fin component of a structure model is defined by any number of quadrilateral elements each with an upper and lower skin, camber and depth specified. The wing, tail and fin components are attached to each other, or to ground, using stiff springs or rigid links. Static and vibration analyses may be performed, and stress, static displacement, vibration frequencies and vibration modes may be written to files or exported for plotting. Constraints and their sensitivity derivatives may also be computed for subsequent use in structural optimization .","category":"mechanical_systems","categoryRaw":"structures and mechanisms","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_20094_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-20094-1","sourceUrl":"https://software.nasa.gov/software/LAR-20094-1","confidence":"high"},"type":"software","title":"Principle Component Analysis (PCA) for Thermography NDE Data","abstract":"Software that reads thermography data and performs principal component analysis (well known technique used on many data types) on the data over a specified number of image frames","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_20224_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-20224-1","sourceUrl":"https://software.nasa.gov/software/LAR-20224-1","confidence":"high"},"type":"software","title":"TRAVIST - Tensegrity Rover Analysis and Visualization Toolkit","abstract":"The Tensegrity Rover Analysis and Visualization Toolkit (TRAVIST) is a software package for the design, analysis, and visualization of TANDEM-class tensegrity rovers. The Tension Adjustable Network for Deploying Entry Membrane (TANDEM) is a multifunctional rover concept which combines tensegrity robotics with deployable heatshield technology to create a comprehensive entry, descent, landing, and locomotion (EDL-L) vehicle for planetary exploration.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_20229_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-20229-1","sourceUrl":"https://software.nasa.gov/software/LAR-20229-1","confidence":"high"},"type":"software","title":"Generic Urban Air Mobility (GUAM) Simulation","abstract":"The generic Urban Air Mobility (GUAM) is a NASA created Matlab/Simulink simulation whose focus is to provide access for the Urban Air Mobility (UAM) and Advanced Air Mobility (AAM) research community to a complete six degree-of-freedom, non-linear, single rigid-body simulation architecture to facilitate perception, control and machine learning research focused on novel aircraft configurations. This architecture is modular (e.g., readily accepts new vehicles, sensor models, perception models, mission-managers, controllers etc..), yet uses a bus structure that will enable research groups to drop-in research algorithms/controllers within an existing framework and data bus structure. This initial software release includes an initial UAM vehicle model (the NASA Advanced Air Vehicle program concept vehicle Lift+Cruise), two aero-propulsive models, a unified controller, basic contingency management capability, and various other simulation needs (e.g., simple effector models). The two choices of aero-propulsive models are user selectable and consist of: a medium fidelity strip theory s-function model, and a blended polynomial based model. Both models are currently configured for the Lift+Cruise vehicle. The medium fidelity strip theory model is readily customizable by the user to create a model of any arbitrary eVTOL configuration (tilt wing, tilt rotors, arbitrary number of propellers/rotors, designate airfoil, aerodynamic effectors). The existing polynomial model is a blended data fit model generated from the strip theory s-function model but should be readily adaptable for other polynomial models. It is intended that the GUAM simulation will be updated periodically with multiple follow-on releases with new capabilities (e.g., new vehicle models, multi-body dynamics modeling, etc..). The stated goal for the release of this simulation framework is to facilitate collaboration and exchange within the eVTOL and UAM research communities.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/Generic-Urban-Air-Mobility-GUAM","license":null}},{"forgeId":"forge_nasa_lar_20263_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-20263-1","sourceUrl":"https://software.nasa.gov/software/LAR-20263-1","confidence":"high"},"type":"software","title":"Image Motion Optical Transfer Function and Pointing Performance Analysis Toolbox (IMOTF-PPA Toolbox)","abstract":"The Image Motion Optical Transfer Function and Pointing Performance Analysis (IMOTF-PPA) Toolbox is a set of MATLAB (and Octave) functions to evaluate image motion effects on image quality for optical systems subject to mechanical disturbances. Image motion includes displacement (shift), smear, jitter, broadband noise, tonal and multi-tonal motion, and exponential deceleration. The toolbox functions support optical performance analysis and pointing performance analysis . Example scripts demonstrate each function and reduce the learning curve, and the scripts can be incorporated into the users design and analysis software. Each function and example is documented in the User's Manual and in command-line help. The User's Manual includes technical background and recommendations to use the Toolbox correctly, and it cites important and pertinent publications.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_20437_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-20437-1","sourceUrl":"https://software.nasa.gov/software/LAR-20437-1","confidence":"high"},"type":"software","title":"Materialite: A Python library for developing and linking material processing, structure, property, and performance simulations","abstract":"Materialite is a Python library developed for research in integrated computational materials engineering. The library facilitates the integration of computational materials models across the process, structure, property, and performance spaces. Interfaces between the models are handled by a common data structure that tracks pointwise information about a material on a regular three-dimensional grid. State-of-the-art simulation methods are also implemented in the library, with a specific focus on additively manufactured materials and using high-performance computing tools like GPU acceleration. The library is intended to be extensible, such that users can easily implement their own simulation methods and import experimental data.","category":"materials_coatings","categoryRaw":"materials and processes","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/materialite","license":null}},{"forgeId":"forge_nasa_lar_20449_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-20449-1","sourceUrl":"https://software.nasa.gov/software/LAR-20449-1","confidence":"high"},"type":"software","title":"FilePlottingTools","abstract":"FilePlottingTools (FPT) is an add-in for the spreadsheet software product Excel, provided by Microsoft Corporation, which was developed in VB.net and that simplifies the process of making plots from transient thermal text file data and comparing this data across different files. The software was developed to handle delimited text files containing time vs. temperature data from thermal analysis , or thermal testing. It assumes that the first column in a file is Time, and the remaining columns are Temperature data from nodes or test sensors. The software could be extended to read in other types of time vs. DATA files by changing the conversions on the Formatted worksheet. In addition to reading text files, FilePlottingTools also reads in data in the .SAV files format from the heat transfer and fluid flow analysis software product C&R THERMAL DESKTOP, provided by Cullimore and Ring Technologies, Inc. FilePlottingTools was developed at NASA LaRC in the Structural and Thermal Systems Branch (STSB / D206) and has been classified as Class E software (per NPR 7150.2). Trade names and trademarks are used in this document for identification only. Their usage does not constitute an official endorsement, either expressed or implied, by the National Aeronautics and Space Administration.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/FilePlottingTools","license":null}},{"forgeId":"forge_nasa_lar_20457_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-20457-1","sourceUrl":"https://software.nasa.gov/software/LAR-20457-1","confidence":"high"},"type":"software","title":"Parallel Grand Canonical Monte Carlo Simulation Code (ParaGrandMC) v.3.0","abstract":"This is version 3.0 of the previously reported Parallel Grand Canonical Monte Carlo simulation code - ParaGrandMC V.2.0 (LAR-19893-1). ParaGrandMC is a highly parallelized code in FORTRAN for simulating the thermodynamic evolution of metal alloy systems at atomic level, and predicting their thermodynamic state, phase diagram, chemical composition and mechanical properties. The approach taken is based on evolving an initially given atomic system (defined through a list of atomic coordinates of all participating atoms) using Monte Carlo and Molecular Dynamics algorithms. Atomic configurations, in terms of coordinates of all atoms, are stored periodically for a post-processing analysis, such as phase identification, lattice parameter estimates, free energy integration, etc. The numerical implementation is highly parallelized allowing simulations of multi-million atom systems. The new version 3.0 has several additional capabilities such as: (i) constant enthalpy ensemble for simulating phase equilibrium states to find phase transition temperatures; (ii) nudged elastic band method to evaluate activation energies in thermally activated processes; (iii) energy minimization to find minimum energy states; (iv) multicell Monte Carlo for simulating several systems in equilibrium with each other for finding phase coexistent regions in the phase diagram of a multicomponent system.","category":"materials_coatings","categoryRaw":"materials and processes","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_20469_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-20469-1","sourceUrl":"https://software.nasa.gov/software/LAR-20469-1","confidence":"high"},"type":"software","title":"NASATrussOpt: Software for truss structure optimization considering member and joint strength, buckling, and nested truss configurations","abstract":"TrussOpt23 is a research code that is used to develop and test augmentations to existing 2D truss structure optimization algorithms to add consideration for stability, joint strength, and dynamic load cases. The end goal are manufacturable truss designs relevant to spacecraft and lunar infrastructure applications. The following paragraphs describe some more about the technical approach. The code was developed primarily by Matthew Yates during his Fall 2023 NIFS internship and is being released to enable continued collaboration with Matthew and his research group at Georgia Tech leading to research publications demonstrating the approach weve developed. We do not anticipate any other external users or engineering applications.In general the approach is an iterative solution to the convex truss optimization problem defined in [1]. The iterations are used to address nonconvex problem aspects. The approach is mostly a unique combination of previously published approaches. The member-adding algorithm described in [2] is used, since it significantly reduces computational expense. Stability is addressed following Tyas [3] and Poulsen [4], where nominal lateral forces and linearized Euler buckling are included.Joint sizing is usually not addressed in truss layout and sizing routines. A uniform arbitrary joint penalty has been introduced to penalize short members, which has the effect of reducing the number of members in the final design, enhancing manufacturability. We adopt a variable joint penalty, based on the loads at the joint. We assume a lap joint configuration and evaluate the length of the overlap using a closed-form solution based on fracture mechanics analysis from Papini [5]. An additional input is added: the fracture toughness of the joint. The fracture mechanics solution leads to an overlap length, which in turns leads to a volume (mass) penalty. The joint volume penalty has a similar influence as previous implementations of joint costs: it tends to rationalize the truss design. In cases where the joint load exceeds the joint capacity for long overlaps, a penalty function is used to prevent infeasible designs. The joint overlaps are updated iteratively until converged.For applications where dynamic loads are important, the mass characteristics of the structure influence the loads. As a result, as the design is updated while searching for a solution, the loads are also changing. We address this scenario for the particular case of a cantilever beam type structure with an end mass subject to base excitation. A lumped mass idealization is used wherein the beam (truss) mass is considered at the tip but with a scaling factor representative of the distribution of mass along the length of the structure. For a uniform cross section, the scaling factor is 0.23. We calculate this factor from the truss layout and sizing using the derivation originally developed by Timoshenko [6]. The scaling factor is updated iteratively until the solution converges.1. M. Gilbert and A. Tyas, Layout optimization of large-scale pin-jointed frames, Engineering Computations, vol. 20, no. 8, pp. 10441064, 2003, doi: 10.1108/02644400310503017.2. L. He, M. Gilbert, and X. Song, A Python script for adaptive layout optimization of trusses, Structural Multidisciplinary Optimization, vol. 60, no. 2, pp. 835847, Aug. 2019, doi: 10.1007/s00158-019-02226-6.3. A. Tyas, M. Gilbert, and T. Pritchard, Practical plastic layout optimization of trusses incorporating stability considerations, Computers & Structures, vol. 84, no. 3, pp. 115126, Jan. 2006, doi: 10.1016/j.compstruc.2005.09.032.4. P. N. Poulsen, J. F. Olesen, and M. Baandrup, Truss optimization applying finite element limit analysis including global and local stability, Structural Multidisciplinary Optimization, vol. 62, no. 1, pp. 4154, Jul. 2020, doi: 10.1007/s00158-019-02468-4.5. M. Papini, G. Fernlund, and J. K. Spelt, The effect of geometry on the fracture of adhesive joints, International Journal of Adhesion and Adhesives, vol. 14, no. 1, Art. no. 1, Jan. 1994, doi: 10.1016/0143-7496(94)90015-9.6. Timoshenko, S. and Young, D.H. (1961) Vibration Problems in Engineering. 3rd Edition, Van Nostrand, New York.","category":"mechanical_systems","categoryRaw":"structures and mechanisms","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_20504_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-20504-1","sourceUrl":"https://software.nasa.gov/software/LAR-20504-1","confidence":"high"},"type":"software","title":"Real-Time Wildfire Localization on the NASA Autonomous Modular Sensor (AMS)","abstract":"This work presents the use of a state-of-the-art segmentation model that performs real-time wildfire localization that can be integrated into the framework of current national wildfire observation missions. This software is companion to the Real-Time Wildfire Localization on the NASA Autonomous Modular Sensor using Deep Learning .","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_20514_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-20514-1","sourceUrl":"https://software.nasa.gov/software/LAR-20514-1","confidence":"high"},"type":"software","title":"Uncertainty Quantification with Polynomial Chaos Expansion (UQPCE)","abstract":"Uncertainty Quantification with Polynomial Chaos Expansion (UQPCE) is a python based open source software package that generates uncertainty quantification (UQ) models to estimate uncertainty in a process, simulation , or experiment. Generally speaking, UQ encompasses the study of the impact of uncertainties in input parameters and modeling simplifications on the output or response of a process or simulation . UQ can vary in scope by including only a single model or multiple models of varying fidelity as well as experimental data. The overarching objective of UQ is to create a more robust design or evaluation process by identifying sensitivities and mitigating the potential impact of uncertainties through informed, targeted resource investments. UQPCE enables users to generate polynomial chaos expansion surrogate models in an intuitive, non-intrusive application with extensive diagnostic capabilities. The software allows the user to perform an automated uncertainty analysis for any given computational code without requiring modification to the source. UQPCE estimates sensitivities, confidence intervals, and other model statistics, which can be useful in the conceptual design and analysis of flight vehicles. UQPCE now has analytic gradients to efficiently perform design under uncertainty, processes that can reduce model overfitting, and a programming interface.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/UQPCE/tree/main","license":null}},{"forgeId":"forge_nasa_lar_20549_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-20549-1","sourceUrl":"https://software.nasa.gov/software/LAR-20549-1","confidence":"high"},"type":"software","title":"Program to Optimize Simulated Trajectories II (POST2) v5.0, Government Edition","abstract":"The Program to Optimize Simulated Trajectories II (POST2) is a generalized point mass, discrete parameter targeting and optimization trajectory simulation program. POST2 provides the capability to target and optimize point mass trajectories for multiple powered or unpowered vehicles near an arbitrary rotating, oblate planet. POST2 has been used successfully to solve a wide variety of atmospheric ascent and reentry problems, as well as exo-atmospheric orbital transfer problems. This flexible simulation capability is augmented by an efficient discrete parameter optimization capability that includes equality and inequality constraints. This version of the software has been overhauled to be thread-safe, enabling usage of multiple compute threads when running optimization problems. A variety of production and development code modules are included that facilitate integration with user-defined terrain and atmosphere. Additionally, an application programming interface (API) provides the ability to call POST2 from other codebases as a library, enabling more applications and use cases. The Government Edition includes several feature modules, such as NPSOL, not included in the Commercial Edition.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_20644_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-20644-1","sourceUrl":"https://software.nasa.gov/software/LAR-20644-1","confidence":"high"},"type":"software","title":"Sequential Monte Carlo-based Symbolic Regression (SMC-SR)","abstract":"Sequential Monte Carlo-based Symbolic Regression (SMC-SR) is a software that performs symbolic regression, a prevalent interpretable machine learning technique, to estimate mathematical equations from data . The software requires labeled numerical data , representing inputs and their corresponding outputs, to learn a symbolic relationship between them. This data can be provided in common formats like CSV files or arrays. The software outputs a family of strings, each representing a symbolic expression, which together form a probability distribution over models conditioned on the data . The software is intended for research use only.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_20673_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-20673-1","sourceUrl":"https://software.nasa.gov/software/LAR-20673-1","confidence":"high"},"type":"software","title":"Loft: An Automated Mesh Generator for Stiffened Shell Aerospace Vehicles","abstract":"Loft is an automated parametric mesh generation code that is designed for aerospace vehicle structures. From user input, Loft generates meshes for wings, noses, tanks, fuselage sections, thrust structures, and so on. As a mesh is generated, each element is assigned properties to mark the part of the vehicle with which it is associated. This property assignment is an extremely powerful feature that enables detailed analysis tasks, such as load application and structural sizing. New, version 4, features include additional object types, airfoil shapes, automated stitching, program flow control, and non-mesh analysis support.This is an update to NTR 1434139697 for software LAR-18704-1 released in 2023 describing new features.","category":"mechanical_systems","categoryRaw":"structures and mechanisms","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lar_20691_1","source":{"institution":"NASA","subUnit":"Langley Research Center","subUnitCode":"LARC","nativeId":"LAR-20691-1","sourceUrl":"https://software.nasa.gov/software/LAR-20691-1","confidence":"high"},"type":"software","title":"Baseball Avoidance Multirotor (BAM) Simulation V1.1","abstract":"The baseball avoidance multirotor (BAM) simulation is an open-source release of a nonlinear, rigid body, realistic visualization , sixdegree-of-freedom simulation intended to foster collaboration and comparison between researchers studying the areas of perception, prediction, and planning for autonomous operations of urban air mobility (UAM) vehicles. This simulation emulates a multi-rotor model in Simulink, and interfaces with Unreal Engine 4 and Microsoft AirSim or Unreal Engine5 and CodexLabsLLC Colosseum, and the Robot Operating System II (ROS2). Additionally, large high fidelity visual datasets are available, and a collision avoidance \"ChallengeProblem\" is posed. BAM V1.1 is an update which contains example ROS2 nodes that show users how to incorporate external algorithms with BAM.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/Baseball-Avoidance-Multirotor-BAM","license":null}},{"forgeId":"forge_nasa_lew_11029_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-11029-1","sourceUrl":"https://software.nasa.gov/software/LEW-11029-1","confidence":"high"},"type":"software","title":"TD2 Axial Turbine Design and Performance Code","abstract":"TD2 performs a streamline analysis that can use meridional velocity gradients to control the radial distribution of work and flow for multistage, multishaft, cooled/uncooled axial-flow turbines. The effects of streamline slope and curvature are included in the radial equilibrium. Hub and tip radii are specified at inlet, at exit, and between each blade row, and velocity diagrams for each stage can be individually controlled. An internal loss correction determines blade-row total-pressure-loss coefficients along the streamlines.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_14060_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-14060-1","sourceUrl":"https://software.nasa.gov/software/LEW-14060-1","confidence":"high"},"type":"software","title":"Radial Turbine Off- Design (RTOD) Performance Code","abstract":"The RTOD code predicts the performance of a single-stage radial-inflow turbine (with either radial or swept rotor blades) as a function of pressure ratio, speed, and stator setting.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_15625_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-15625-1","sourceUrl":"https://software.nasa.gov/software/LEW-15625-1","confidence":"high"},"type":"software","title":"NASA Lewis Steady-State Heat Pipe Code","abstract":"The NASA Lewis Research Center Heat Pipe (LERCHP) code was developed to predict the performance of heat pipes in the steady state. LERCHP can be used as a design tool on a personal computer or, with a suitable calling routine, as a subroutine for a mainframe radiator code. For accurate heat pipe modeling, a variety of wick structures are available to the user, including a user wick input option. Several working fluids can be chosen as well, including potassium, sodium, and lithium, for which the monomer-dimer equilibrium is considered. A vapor flow algorithm is incorporated that treats compressibility and axially varying heat input. LERCHP also facilitates the determination of heat pipe operating temperatures and heat pipe limits that may be encountered at the specified heat input and environment temperature.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_16325_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-16325-1","sourceUrl":"https://software.nasa.gov/software/LEW-16325-1","confidence":"high"},"type":"software","title":"PCSTAGE","abstract":"PCSTAGE is simple computational simulation of multi-stage turbo-machinery blade-to-blade flows on a surface of revolution.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_16330_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-16330-1","sourceUrl":"https://software.nasa.gov/software/LEW-16330-1","confidence":"high"},"type":"software","title":"SCISEAL","abstract":"This computer program has been used to study the fluid dynamic forces in SEALS.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_16851_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-16851-1","sourceUrl":"https://software.nasa.gov/software/LEW-16851-1","confidence":"high"},"type":"software","title":"GRAPE.107","abstract":"GRAPE is a two-dimensional elliptic grid generation code to be used with isolated airfoils. This modified version of the software (with application for turbomachinery blades) can generate grids for the RVCQ3D turbo-machinery analysis code.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_16851_2","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-16851-2","sourceUrl":"https://software.nasa.gov/software/LEW-16851-2","confidence":"high"},"type":"software","title":"RVCQ3D.406","abstract":"RVCQ3D is a two-dimensional computational fluid dynamics (CFD) analysis code for turbo-machinery (e.g., compressors, turbines, and mixed-flow machines). The technology solves Navier-Stokes equations on a blade-to-blade surface of revolution using explicit finite-difference techniques. Three differencing schemes are available: central differences, AUSM , and H-CUSP. Three turbulence models are also available: Baldwin-Lomax, Cebeci-Smith, and Wilcox 2006 K-Omega.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_16851_3","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-16851-3","sourceUrl":"https://software.nasa.gov/software/LEW-16851-3","confidence":"high"},"type":"software","title":"TSONIC","abstract":"The TSONIC Fortran program calculates the transonic velocity on the blade-to-blade stream surface of a turbo- machine .","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_17051_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-17051-1","sourceUrl":"https://software.nasa.gov/software/LEW-17051-1","confidence":"high"},"type":"software","title":"NPSS Numerical Propulsion System Simulation","abstract":"NASA Glenn Research Center is developing a common collaborative full engine simulation tool for the U.S. Government, aerospace industry, and academia called the Numerical Propulsion System Simulation (NPSS). NPSS provides an environment for the analysis and design of propulsion systems for thermodynamic systems. The NPSS focuses on the potential integration of multiple disciplines such as aerodynamics, structures, and heat transfer, along with the concept of numerical zooming between 0-Dimensional to 1-, 2-, and 3- Dimensional component engine codes.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_17052_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-17052-1","sourceUrl":"https://software.nasa.gov/software/LEW-17052-1","confidence":"high"},"type":"software","title":"Coupled Structural, Thermal, Acoustic, Electromagnetic (CSTEM) Analysis","abstract":"CSTEM is a UNIX executable for coupled structural, thermal, acoustic, and electromagnetic analysis and optimization.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_17063_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-17063-1","sourceUrl":"https://software.nasa.gov/software/LEW-17063-1","confidence":"high"},"type":"software","title":"Tone Fan Noise Design /Prediction System (TFaNS 1.4)","abstract":"TFaNS predicts tone noise emanating from a fan stage, including the effects of reflection and transmission by the rotor and stator and by the duct inlet and nozzle.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_17063_2","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-17063-2","sourceUrl":"https://software.nasa.gov/software/LEW-17063-2","confidence":"high"},"type":"software","title":"Tone Fan Noise Design /Prediction System (TFaNS 1.5)","abstract":"TFaNS predicts tone noise emanating from a fan stage, including the effects of reflection and transmission by the rotor and stator and by the duct inlet and nozzle. Version 1.5 upgrades include: the SOURCE3D subprogram's ability to perform transmission-loss calculation for modes scattering into themselves; the inlet and aft radiation codes' use of infinite envelope elements in the far-field; and the AWAKEN subprogram's use of a new Acoustic Wake/Turbulence File format.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_17228_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-17228-1","sourceUrl":"https://software.nasa.gov/software/LEW-17228-1","confidence":"high"},"type":"software","title":"AirShow 1.1.1","abstract":"The AirShow software package enables 3D visualization of computational meshes and computed flow-field data associated with computational fluid dynamics (CFD). The program displays structured grid blocks and computational grid planes.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_17247_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-17247-1","sourceUrl":"https://software.nasa.gov/software/LEW-17247-1","confidence":"high"},"type":"software","title":"Integrated Composite Analyzer In JAVA (ICAN/JAVA)","abstract":"ICAN/JAVA, the Integrated Composite Analyzer written in Java, was primarily designed to analyze the hygrothermomechanical response and properties of fiber- or particulate-reinforced, resin-matrix layered composite materials, given the local membrane loads and bending moments. ICAN/JAVA was coded in the Java computer language combining features from earlier versions for both fibers and particulates as well as adding impact modeling . The multi-factor interaction model allows factors to interact to allow for property changes due to operating conditions after fabrication. ICAN/JAVA has both a batch version and an interactive version that can also plot selected outputs.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_17293_2","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-17293-2","sourceUrl":"https://software.nasa.gov/software/LEW-17293-2","confidence":"high"},"type":"software","title":"Software For System For Controlling A Magnetically Levitated Rotor","abstract":"FATMaCC (Five-Axis, Three-Magnetic-Bearing Control Code), is a versatile control code that possesses many desirable features that were not available in previous in-house controllers. The ultimate goal in designing this code was to achieve full rotor levitation and control at a loop time of 50 s. Using a 1-GHz processor the code will control a five-axis system in either a decentralized or a more elegant centralized (model control ) mode at loop time of 56 s. In addition, it will levitate and control (with only minor modification to the input-output wiring) a two-axis and / or a four-axis system. Stable rotor levitation and control of any of the system mentioned above are accomplished through appropriate key presses to modify parameters, such as stiffness, damping, and bias. A signal generation block provides 11 excitation signals. An excitation signal is then superimposed on the radial bearing x- and y- control signals, thus producing a resultant force vector. By modulating the signals on the bearing x0 and y- axes with a cosine and sine function, respectively, a radial excitation force vector is made to rotate 360 about the bearing geometric center. The rotation of the force vector is achieved manually by using key press or automatically by engaging the \" one-per-revolution\" feature. Rotor rigid body modes can be excited by using the excitation module. Depending on the polarities of the excitation signal in each radial bearing, the bounce or tilt mode will be excited.magnetic bearings are an enabling technology for rotating devices with extremely high rotational speeds, such as flywheel energy storage systems being proposed for the International Space Station. In addition these bearings have great potential for conventional gas turbine engines especially because the control algorithms can compensate for an event such as loss of a blade that causes rotor imbalance.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_17346_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-17346-1","sourceUrl":"https://software.nasa.gov/software/LEW-17346-1","confidence":"high"},"type":"software","title":"LINFLUX, 3D Linearized Unsteady Aerodynamic Analysis","abstract":"LINFLUX is a three-dimensional, linearized, unsteady aerodynamic analysis (and code) that can be used to predict the aero-acoustic/aero-elastic responses of axial-flow turbo-machinery blade rows to aerodynamic/structural excitations.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_17386_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-17386-1","sourceUrl":"https://software.nasa.gov/software/LEW-17386-1","confidence":"high"},"type":"software","title":"Multiple Pure Tone (MPT) Noise Code","abstract":"The MPT noise prediction procedure is based on uniform-rotor computational fluid dynamics (CFD) analysis of BPF tonal content in conjunction with engineering (statistical) correlation information of blade-to-blade non-uniformity effects.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_17399_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-17399-1","sourceUrl":"https://software.nasa.gov/software/LEW-17399-1","confidence":"high"},"type":"software","title":"SmaggIce Windows, Version 2.0","abstract":"The SmaggIce software toolkit can be used to create structured grids for single- or multi-element 2D iced airfoils in preparation for computational fluid dynamics (CFD) analysis . Software tools will measure ice shape characteristics, add artificial ice shapes, prepare an ice surface for gridding, perform domain decomposition, create and modify grids, analyze grid quality, and output grids for subsequent input into flow solvers.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_17399_2","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-17399-2","sourceUrl":"https://software.nasa.gov/software/LEW-17399-2","confidence":"high"},"type":"software","title":"SmaggIce UNIX, Version 2.0","abstract":"The SmaggIce software toolkit can be used to create structured grids for single- or multi-element 2D iced airfoils in preparation for computational fluid dynamics (CFD) analysis . Software tools will measure ice shape characteristics, add artificial ice shapes, prepare an ice surface for gridding, perform domain decomposition, create and modify grids, analyze grid quality, and output grids for subsequent input into flow solvers.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_17452_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-17452-1","sourceUrl":"https://software.nasa.gov/software/LEW-17452-1","confidence":"high"},"type":"software","title":"Centrifugal Compressor Design (CCD) code","abstract":"This NASA-developed technology provides a rapid preliminary assessment of the design geometry and the design-point performance of centrifugal compressors. The analysis is based on a one-dimensional flow model with correlations for the following losses: inlet guide vane, rotor inlet shock, incidence, clearance, blade loading, skin friction, disk friction, recirculation, vaneless diffuser skin friction, and vaned diffuser. With input performance, the code can operate in design mode; with input geometry, the code can operate in analysis mode.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_17453_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-17453-1","sourceUrl":"https://software.nasa.gov/software/LEW-17453-1","confidence":"high"},"type":"software","title":"RTD Radial-Inflow Turbine Conceptual Design Code","abstract":"The RTD code executes a conceptual design for a single-stage radial-inflow turbine. A mean-line analysis is performed for the locations having constant radius over the blade span. Constant span-fraction sectors are used at the rotor exit. The analysis can account for stator end-wall clearance flow and swept rotor blades. The loss model includes stator and rotor passage losses, trailing-edge losses, vaneless space loss, disk-friction loss, and rotor-exit clearance loss.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_17635_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-17635-1","sourceUrl":"https://software.nasa.gov/software/LEW-17635-1","confidence":"high"},"type":"software","title":"TCGRID v.400","abstract":"TCGRID is a three-dimensional grid-generation code for turbo-machinery blades. The software can generate single- or multi-block grids that are compatible with several computational fluid dynamics (CFD) analysis codes, including SWIFT and ADPAC.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_17635_2","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-17635-2","sourceUrl":"https://software.nasa.gov/software/LEW-17635-2","confidence":"high"},"type":"software","title":"SWIFT, v.400","abstract":"SWIFT is a multi-block computational fluid dynamics (CFD) analysis code for turbo-machinery. The software, which solves Navier-Stokes equations using explicit finite-difference techniques, can be used for linear cascades, isolated blade rows, or multistage machines. Three differencing schemes are available: central differences, AUSM , and H-CUSP. Three turbulence models are also available: Baldwin-Lomax, Cebeci-Smith, and Wilcox 2006 K-Omega.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_17677_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-17677-1","sourceUrl":"https://software.nasa.gov/software/LEW-17677-1","confidence":"high"},"type":"software","title":"Time-Accurate, Sectored, One-Dimensional Reactive Code for Simulation , Prediction, and Control of Combustion Instabilities","abstract":"This sectored one-dimensional model utilizes a simplified computational fluid dynamics (CFD) algorithm to simulate combustion and acoustic processes (including instabilities) in combustors with complex shapes. Utilizing modest computational resources, the code produces realistic results and is well suited for controls development.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_17681_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-17681-1","sourceUrl":"https://software.nasa.gov/software/LEW-17681-1","confidence":"high"},"type":"software","title":"Solar Array Verification and Analysis Tool (SAVANT)","abstract":"The powerful, yet easy-to-use SAVANT quick-engineering code calculates the expected radiation damage to solar cells in Earth orbit. The tool contains ten types of solar cells and four types of cover glass. Radiation damage calculations are based on the Displacement Damage Dose method developed at the Naval Research Laboratories.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_18229_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-18229-1","sourceUrl":"https://software.nasa.gov/software/LEW-18229-1","confidence":"high"},"type":"software","title":"NESSUS 6.2C","abstract":"The NESSUS 6.2c computer program is a set of separate but related modules for solving a wide range of component and system probabilistic and reliability problems, including finite element analysis , heat transfer analysis , geometry generation, and ceramic material property generation.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_18321_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-18321-1","sourceUrl":"https://software.nasa.gov/software/LEW-18321-1","confidence":"high"},"type":"software","title":"RAT-EDA","abstract":"This NASA-developed technology is a MATLAB-language computer program for exploratory data analysis . Through the fast post-processing of measured time-series Raman spectral data, RAT-EDA reveals thermo-chemical properties and turbulent-chemistry interactions in combustion. The computer program deduces probability density functions of combustion temperatures using user-selected super-pixel regions for each major species (e.g., O2, N2, CH4, CO2, or H20).","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_18343_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-18343-1","sourceUrl":"https://software.nasa.gov/software/LEW-18343-1","confidence":"high"},"type":"software","title":"IceVal DatAssistant","abstract":"This NASA-developed technology provides an improved mechanism for managing the large volume of data generated and utilized in performing icing research.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_18402_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-18402-1","sourceUrl":"https://software.nasa.gov/software/LEW-18402-1","confidence":"high"},"type":"software","title":"PMESH","abstract":"The PMESH grid-generation program produces three-dimensional blade-passage meshes for the computational fluid dynamics (CFD) modeling of advanced single- or counter-rotation turboprops and propfans.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_18550_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-18550-1","sourceUrl":"https://software.nasa.gov/software/LEW-18550-1","confidence":"high"},"type":"software","title":"Open MDAO: The Next Generation Multidisciplinary Design Analysis and Optimization (MDAO) Open Source Framework","abstract":"OpenMDAO is the initial version of the next generation Multidisciplinary Design Analysis and Optimization (MDAO) open source framework. OpenMDAO is the open source framework developed by NASA that will be accessible via an open source website to reach the entire broad based MDAO community to facilitate advancing the science of MDAO. MDAO covers a vast set of capabilities, including a flexible framework and state of the art discipline codes. This innovation relates specifically to the framework. OpenMDAO provides the core software infrastructure to integrate multidisciplinary variable fidelity tools and enable design, analysis, and optimization of complex systems. Currently, OpenMDAO functionalities include component linking, data passing, driver interface, and lazy evaluation. This initial basic capability of the framework is sufficient for users to run and optimize their analysis after they integrate their specific component codes. As OpenMDAO evolves, the following capabilities will be included in the framework: interprocess communications, error handling, user interfaces, geometry application program interfaces (APIs), plug-in interfaces, utilities to wrap tools, versioning, and parallel processing support. To be clear, the framework will enable the integration of, but will not include: optimizers, solvers, visualization tools, custom data types, script components, and discipline codes. AEROSPACE: To meet the present and future economic and environmental challenges facing air transportation, aviation design must expand its focus from today's conventional \"wing-body-tail\" aircraft to more advanced vehicles. The ability to design revolutionary aircraft to improve mobility and air transport efficiency is of paramount importance to the national economy, along with reducing our environmental impact and supporting national defense. Technologies such as the one disclosed here incorporate progressively more sophisticated computational models and methods, enabling future aircraft designs today.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://openmdao.org/","license":null}},{"forgeId":"forge_nasa_lew_18573_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-18573-1","sourceUrl":"https://software.nasa.gov/software/LEW-18573-1","confidence":"high"},"type":"software","title":"LEWICE 3.2.3 Ice Accretion Software","abstract":"LEWICE contains an analytical ice accretion model that evaluates the freezing process thermodynamics that occur when super-cooled droplets impinge on a body. Both atmospheric parameters (i.e., temperature, pressure, and velocity) and meteorological parameters (i.e., liquid water content, droplet diameter, and relative humidity) are used to determine the shape of the ice accretion.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_18640_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-18640-1","sourceUrl":"https://software.nasa.gov/software/LEW-18640-1","confidence":"high"},"type":"software","title":"NDE Wave & Image Processor (NDEWIP V3.0)","abstract":"The NDE Wave & Image Processor software application has been created to provide a state-of-the-art, comprehensive, integrated science-based tool for the advanced visualization , processing, and analysis of NDE and health-monitoring waveform- and image-based data. With NDEWIP, the user has access to a complete post-processing capability in a single tool. Although the software has been developed for the NDE professional, the technology could be used for any other RF signal or image processing and analysis application.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_18815_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-18815-1","sourceUrl":"https://software.nasa.gov/software/LEW-18815-1","confidence":"high"},"type":"software","title":"Systematic Sensor Selection Strategy (S4) Software","abstract":"The Systematic Sensor Selection Strategy (S4) optimally selects a sensor suite from a larger pool of candidate sensors based on their performance in a diagnostic system. S4's user-defined fault-diagnostic approach considers conflicting objectives including cost, weight, and reliability.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_19032_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19032-1","sourceUrl":"https://software.nasa.gov/software/LEW-19032-1","confidence":"high"},"type":"software","title":"Acoustic Emission Analysis Applet (AEAA) Software","abstract":"Post-processing software has been developed at NASA that is tailored for novel analysis of composite pressure vessels acoustic emission (AE) data. The software can be used with data acquired from Digital Wave, Inc. and Mistras Group (Physical Acoustics, Inc.) hardware","category":"materials_coatings","categoryRaw":"materials and processes","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_19225_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19225-1","sourceUrl":"https://software.nasa.gov/software/LEW-19225-1","confidence":"high"},"type":"software","title":"SCaN Optical Link Budget Tool","abstract":"A calculational procedure has been designed and implemented in software that enables the specification and design of a space-based optical communications system. The resulting optical link budget essentially accounts for the communication power flow through the entire optical communications channel from the transmitter to the receiver and yields design specifications for the optical system necessary to assure reliable data transmission with desired operational metrics such as data rate, link margin, etc. The link budget takes into account all the sources of deleterious noise that enters into the communications process such as electronically generated noise in the optical detector and stray optical irradiance from external sources. The link budget has the capability of being interfaced with the orbital element calculations of the Satellite Tool Kit (STK) to allow the dynamic description and evolution of optical link operation from any space-borne satellite within the solar system to and from the earth.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_19241_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19241-1","sourceUrl":"https://software.nasa.gov/software/LEW-19241-1","confidence":"high"},"type":"software","title":"Extended Testability Analysis (ETA) Tool V8.0","abstract":"This technology disclosure is for the Enhanced Testability Analysis (ETA) Tool V8.0. The version of the ETA Tool is an upgrade of the previous reported ETA Tool (LEW-18795-1). This technology is a NASA Glenn-developed software application that supports fault management (FM) by performing testability analyses on the fault propagation model of a given system. The Extended Testability Analysis (ETA) Tool processes a diagnostic model developed from a commercial software package called TEAMS Designer using a defined set of modeling conventiuons and practices. ETA Tool can provide an assessment of the modeled system based on diagnostic metrics of detectability and failure isolation. The program can provide assessment of a system's detection coverage, test utilization, failure isolation at the root cause or at the component levels, generate a FMEA Report, perform sensor sensitivity studies and provide a trace-mapping of failure modes to higher level system effects. ETA Tool generates reports from each selected analysis option in both an HTML and XML format to enable user access in either standard web browsers or loadable into an Microsoft Excel workbook for review/editing.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_19286_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19286-1","sourceUrl":"https://software.nasa.gov/software/LEW-19286-1","confidence":"high"},"type":"software","title":"Capture Test Waveform for the SCaN Testbed STRS Harris SDR","abstract":"The Capture Test Waveform is a software application designed for space-based reconfigurable radios. The innovation allows snapshots of a radio's receiver environment for any number of objectives, such as interference mitigation or radio frequency mapping. Digital samples are acquired and stored in the radio's memory for processing, be that on-board the spacecraft or after download to the ground. The application is labeled \"Test waveform\" because it does not perform any standard communication link functions, such as carrier recovery or demodulation. Depending on the radio's resources and architecture, this application could be run in parallel with a standard communications link waveform application. (STRS)","category":"electronics","categoryRaw":"electronics and electrical power","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_19288_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19288-1","sourceUrl":"https://software.nasa.gov/software/LEW-19288-1","confidence":"high"},"type":"software","title":"PyCycle - An Cycle Modeling Tool For Design With Gradient Based Optimization","abstract":"PyCycle is a novel software library written in the Python Programming language. It allows a user to perform standard engine cycle analysis, while also providing analytic derivative (sensitivity) calculations to the end user. This allows Pycycle to be very efficiently used by (or incorporated within) external software programs performing broader simulation , analysis, and optimization.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/OpenMDAO/pyCycle","license":null}},{"forgeId":"forge_nasa_lew_19307_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19307-1","sourceUrl":"https://software.nasa.gov/software/LEW-19307-1","confidence":"high"},"type":"software","title":"Reconfigurable Bandwidth-Efficient Transmit Waveform for High-Rate Telemetry - STRS","abstract":"The Reconfigurable Bandwidth-Efficient Transmit Waveform for High-rate Telemetry supports gigabit-per-second data rates and continuously-tunable modulated symbol rates into the hundreds of Msymbols/second on most devices. The supported modulations include GMSK, BPSK, QPSK, OQPSK, 8-PSK, 16-APSK, 16-PSK, 16-QAM, and 32-APSK. Various pulse-shape filtering options are available, using Root-Raised Cosine and Raised Cosine filters, with excess bandwidths between 0.1 and 1.0. The support forward error correction includes Convolutional Coding and Low Density Parity Check (LDPC) codes, specifically the AR4JA and C2 families of LDPC codes. From the AR4JA family, the waveform supports rates 1/2, 2/3, and 4/5. From the C2 family of codes, the waveform supports the rate 7/8 code. The waveform supports up to eight 1/2-rate (k = 7) convolutional coders in parallel, which has been demonstrated to achieve the maximum 150Mbps coded data rate supported by NASAs Tracking and Data Relay Satellite System (TDRSS). Additional data processing includes Consultative Committee for Space Data Systems (CCSDS) - compliant randomization (131.0-B-2) and Advanced Orbiting Systems (AOS) data framing (732.0-B-2). In any communication system, there are linear and non-linear channel impairments which limit the performance. This waveform includes a digital pre-distortion module, which is designed to invert the non-linear distortions of a power amplifier, such as a Traveling Wave Tube Amplifier (TWTA). A re-programmable finite-impulse response (FIR) filter is also included to pre-compensate for linear channel impairments. Finally, the waveform includes in-situ channel characterization capabilities such as a continuous wave (CW) two-tone generator. A programmable digital drive level allows the output power of the waveform to be varied continuously.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_19351_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19351-1","sourceUrl":"https://software.nasa.gov/software/LEW-19351-1","confidence":"high"},"type":"software","title":"Channel Emulator","abstract":"The Channel Emulator (CE) is a software-based network testing tool. Its primary functions are providing data framing services, acting as a flexible protocol gateway, and providing network emulation capabilities. The software caneasily accept one protocol, optionally extract the payload, send out as different protocol, or encapsulate one in another. It can also introduce delays up to deep space levels, and introduce bit errors and other link degradations.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/channel-emulator","license":null}},{"forgeId":"forge_nasa_lew_19389_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19389-1","sourceUrl":"https://software.nasa.gov/software/LEW-19389-1","confidence":"high"},"type":"software","title":"FPGA Code Development for the iPAS STRS Radio","abstract":"The innovation is FPGA VHDL code written as part of the iPAS STRS Radio development. The purpose of the FPGA design is the implementation of the signal processing functions of the STRS radio architecture in the IPAS RAICs platform. The FPGA design will consist of two parts the FPGA wrapper and the test waveform. The FPGA wrapper implements each platform interface: Ethernet communication to the embedded processor for commanding and data streamingDigital-to Analog Converter (DAC) and Analog-to-digital converter (ADC) interface to the RF boardRF Board Control and ConfigurationFPGA ClockingThe test waveform does not fully implement all the signal processing functionality for a radio, but it exercises and demonstrates each interface in the FPGA wrapper. A future user of the platform for an STRS radio, would use the FPGA wrapper and replace the test waveform with their own radio signal processing functions.The FPGA design receives and processes commands and provides command control and data to the test waveform. It also receives and transmits streaming data from/to the embedded processor. The test waveform demonstrates each FPGA wrapper interface. To test transmit-side streaming, it can perform bit error rate testing on transmit-side PRBS streaming data. It can also generate PRBS streaming data packets for a receive-side streaming data source. The test waveform generates sine waves for the in-phase (I) and quadrature (Q) inputs to the RF transceiver. A BPSK modulator is included to modulate PRBS data from with the PRBS generator or from transmit-side streaming data. Captured I and Q samples from the RF transceiver can be streamed to the embedded processor where it can be plotted (if a sine wave) or bit error rate checked (if PRBS data) to demonstrate proper functionality of the RF board and its interfaces.","category":"electronics","categoryRaw":"electronics and electrical power","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_19433_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19433-1","sourceUrl":"https://software.nasa.gov/software/LEW-19433-1","confidence":"high"},"type":"software","title":"LEWICE3D, Version 3.63","abstract":"LEWICE3D is a software system capable of predicting the accumulation of ice on three-dimensional aircraft surfaces given the flight and meteorological conditions representative of an icing cloud. The software utilizes input information of the airflow surrounding the body of interest and then calculates trajectories of approaching water droplets, the mass and energy transfer processes at the surface of the body, and the resulting ice mass and the shape it will take on the body. This version of the software includes coverage of the full range of icing conditions from the standard envelope encompassed by FAA CFR 14, Part 25, Appendix C, up through super-cooled large droplet (SLD) icing conditions. The computational results have been compared to an extensive database of ice shape profiles obtained from experimental measurements and the software has shown a very good ability to reproduce such profiles under most conditions of interest to the aviation community. This validation effort has made the LEWICE3D software one of the most extensively tested ice accretion prediction tools available.The LEWICE3D software is made up of several modules or processes. The first step is calculation of the flow field around the aircraft or aircraft component of interest. This calculation is performed prior to use of the LEWICE3D software and serves as input information for LEWICE3D. The results of this calculation are used to calculate the water droplet trajectories which impinge on the aircraft surface. The droplet trajectory analysis also produces the impingement limits and the local collection efficiency, which in turn are used to determine the mass of water that will impact a surface and the distribution of that water on the surface. The mass flux information is used for subsequent ice growth calculations and is also useful for ice protection system design. The final module or process predicts the ice shape by modeling the freezing process in small finite control volumes. Supercooled large droplet (SLD) modeling is incorporated through the computation of large droplet impact dynamics.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_19463_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19463-1","sourceUrl":"https://software.nasa.gov/software/LEW-19463-1","confidence":"high"},"type":"software","title":"SCaN Optical Link Assessment Tool Version 3","abstract":"A calculation procedure has been designed and implemented in software that enables the specification and design of a space-based optical communications system. The resulting optical link budget essentially accounts for the communication power flow through the entire optical communications channel from the transmitter to the receiver and yields design specifications for the optical system necessary to assure reliable data transmission with desired operational metrics such as data rate, link margin, etc. The link assessment tool takes into account all the sources of deleterious noise that enters into the communications process such as electronically generated noise in the optical detector and stray optical irradiance from external sources. The link budget has the capability of being interfaced with the orbital element calculations of the Satellite Tool Kit (STK) to allow the dynamic description and evolution of optical link operation from any space-borne satellite within the solar system to and from the earth. The current version implements PPM and DPSK modulation types that can use PIN, APD, or nanowire optical detectors in the presence of atmospheric turbulence. Coded and un-coded link power margins are provided. This version of the tool also has the ability 1) to solve for prevailing potential data rates given a desired optical power link margin and 2) treat the spatial separations of optical link transmitter and receiver within thefirst Fresnel zone.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_19478_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19478-1","sourceUrl":"https://software.nasa.gov/software/LEW-19478-1","confidence":"high"},"type":"software","title":"STRS Adaptive Coding and Modulation Waveform for Space Communication","abstract":"An Adaptive Coding and Modulation Waveform for Space Communication has been developed and demonstrated on a space-qualified software defined radio (SDR). The waveform utilizes the commercial Digital Video Broadcasting- Second Generation (DVB-S2) standard to provide a suite of modulation and encoding schemes, which allows the communication link to be dynamically adjusted to optimize performance. The waveform utilizes the Space Data Link Protocol (Consultative Committee for Space Data Systems (CCSDS) standard) to control the transmitter's mode of operation, using a BPSK/QPSK receiver. The waveform includes the ability to automatically compensate for non-linear channel impairments to improve the performance of high-order modulations.","category":"electronics","categoryRaw":"electronics and electrical power","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_19522_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19522-1","sourceUrl":"https://software.nasa.gov/software/LEW-19522-1","confidence":"high"},"type":"software","title":"Tool for Generation of MAC/GMC Representative Unit Cell for CMC/PMC Analysis","abstract":"This is a Graphics user interface (GUI) based tool that generates a number of different user-defined repeating unit cells (RUCs) interactively that can be used in conjunction with the composite micromechanics based analysis tool MAC GMC and HF GMC.In addition, the code has provisions for generation of a MAC/GMC-compatible input text file that can be merged with any MAC/GMC input file tailored to analyze composite materials. Although the primary intention was to address the three different constituents and phases that are usually present in CMCsnamely, fibers, matrix, and interphaseit can be easily modified to address two-phase polymer matrix composite (PMC) materials where an interphase is absent. Currently, the tool capability includes generation of RUCs for square packing, hexagonal packing, and random fiber packing as well as RUCs based on actual composite micrographs. All these options have the fibers modeled as having a circular cross-sectional area. In addition, a simplified version of RUC is provided where the fibers are treated as having a square cross section and are distributed randomly.","category":"mechanical_systems","categoryRaw":"structures and mechanisms","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_19686_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19686-1","sourceUrl":"https://software.nasa.gov/software/LEW-19686-1","confidence":"high"},"type":"software","title":"CMPGEN: A Modeling Tool Used to Compute Off-Design Performance Of Fans, Boosters, And Compressors","abstract":"CMPGEN is a modeling tool used to compute off-design performance of axial fans, boosters, and compressors. Users can obtain rapid and consistent off-design performance characteristics from simple design point inputs. Component performance maps suitable for use in the Numerical Propulsion System Simulation (NPSS) gas turbine engine cycle analysis code output.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_19687_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19687-1","sourceUrl":"https://software.nasa.gov/software/LEW-19687-1","confidence":"high"},"type":"software","title":"Weight Analysis of Turbine Engine - an Object-Oriented Version (WATE++)","abstract":"WATE++ is an object-oriented computer code for gas turbine engine weight estimation; it calculates the weight and dimension of each major gas turbine engine component. It is used to create engine architecture that could achieve an engine thermodynamic cycle produced by a thermodynamic cycle code. The thermodynamic cycle data, the material properties, and design rules for geometric, stress, and turbo-machinery stage-loading limits were used to determine an acceptable engine flowpath and weight.The code was converted from the structured FORTRAN version of the code, originally developed by Boeing Aircraft for NASA, to improve its maintainability and extensibility. The conversion was done within the NASAs NPSS (Numerical Propulsion System Simulation ) framework. This enables WATE to interact seamlessly with the thermodynamic cycle model which provides component flow data such as airflows, temperatures, and pressures, etc. that are also required for sizing the components and weight calculations. The tight integration between the NPSS and WATE++ greatly enhances system-level analysis and optimization capabilities.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_19702_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19702-1","sourceUrl":"https://software.nasa.gov/software/LEW-19702-1","confidence":"high"},"type":"software","title":"SGNDI (Separable Grid N-Dimensional Interpolator)","abstract":"This is a software library for multidimensional numerical data interpolation, in an arbitrary number of dimensions. Analytical gradients are supported.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/SGNDI","license":null}},{"forgeId":"forge_nasa_lew_19710_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19710-1","sourceUrl":"https://software.nasa.gov/software/LEW-19710-1","confidence":"high"},"type":"software","title":"CCSDS SOIS Electronic Data Sheet Implementation for Core Flight System","abstract":"A set of tools that implement the Electronic Data Sheets specification from the CCSDS SOIS working group, compliant with book CCSDS book 876.0. Integrates with the NASA Core Flight System (CFS) to provide a robust EDS-based command, telemetry, and configuration solution.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/edslib","license":null}},{"forgeId":"forge_nasa_lew_19723_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19723-1","sourceUrl":"https://software.nasa.gov/software/LEW-19723-1","confidence":"high"},"type":"software","title":"STRS Modular and Portable QPSK Transceiver Waveform for Software-Defined Radios","abstract":"A QPSK transceiver waveform has been developed and implemented on a commercially-available ground-based software defined radio platform. The waveform utilizes legacy NASA forward error correction codes and Consultative Committee for Space Data Systems (CCSDS) data framing standards. It's controlled via web interface, and allows the user to multiplex between test (pseudo-random) and network-sourced data.From a specification standpoint, the waveform supports the following functionalities in both transmit/receive directions: QPSK modulation, continuously tunable data-rates up-to 6.144Mbps for RX and 24.576Mbps for TX, convolutional coding/decoding (rate 1/2, constraint length of 7), CCSDS-compliant randomization (131.0-B-2) and Advanced Orbiting Systems (AOS) data framing (732.0-B-2).The product consists of two main components: (1) the digital logic (VHDL) implementation for the Field Programmable Gate Array (FPGA) that does the required signal processing functionalities and (2) the command-and- control software portion that leverages the open-source Core Flight Executive (cFE) software suite and provides a graphical user interface to the waveform.","category":"electronics","categoryRaw":"electronics and electrical power","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_19737_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19737-1","sourceUrl":"https://software.nasa.gov/software/LEW-19737-1","confidence":"high"},"type":"software","title":"NASA Root Cause Analysis Tool (RCAT)","abstract":"The NASA Root Cause Analysis Tool (RCAT) has been designed to facilitate the analysis of anomalies, close calls, and accidents and also identify the appropriate corrective actions to prevent recurrence. The software provides an analyst with a quick, easy-to-use, accurate, and repeatable method to perform and document root cause analysis , identify corrective actions, perform trending analysis , and generate usable data for probabilistic risk assessment. All possible causes of accidents-hardware, software, the environment, weather, natural phenomena, external events, human error-can be incorporated into the timeline and fault/causal factor trees. The software features an intuitive logic diagramming capability and uses standard terminology, definitions, and symbols.","category":"operations","categoryRaw":"business systems and project management","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_19857_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19857-1","sourceUrl":"https://software.nasa.gov/software/LEW-19857-1","confidence":"high"},"type":"software","title":"NPSS Electrical Power System Analysis Toolbox","abstract":"An electrical power system analysis tool that can integrate with traditional combustion based propulsion models to analyze the potential benefits of aircraft electrification in the NPSS environment. This toolbox basic (text book based) electrical power system component models and an electrical port which connects these component models together to ensure the correct data is available to each model. The toolbox sizes the electrical power system based on required load demand at the design point and determines the power available to the loads in off-design.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/NPSS-Power-System-Library","license":null}},{"forgeId":"forge_nasa_lew_19874_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19874-1","sourceUrl":"https://software.nasa.gov/software/LEW-19874-1","confidence":"high"},"type":"software","title":"Thermodynamically Coupled Air-Droplet Icing Wind Tunnel Model (TADICE)","abstract":"This one dimensional (1D) numerical model (software) simulates icing wind tunnels by modeling the thermodynamic interactions between the water/ice particles of an icing cloud and the flowing air. The model attempts to explain the observed changes in test conditions at the tunnel test section, such as air temperature and humidity, when an icing cloud is activated. The ultimate goal of the model is to better understand the complex interactions between the known test parameters at the tunnel inlet and have greater confidence in the conditions at the test section of the tunnel. The model provides simulated results at the tunnel test section which includes air temperature, vapor content (humidity), air velocity, cloud liquid and ice water content, cloud particle size distribution, cloud particle velocities, and cloud particle temperatures. The model can simulate supercooled liquid clouds (water that freezes below 0 degrees Celsius) as well as standard water clouds (water that freezes at 0 degrees Celsius). Model inputs include initial air temperature, air pressure, air humidity, cloud water content, cloud ice content, cloud ice/water temperature, cloud water type (regular water or deionized water that can supercool), cloud ice/water speed, cloud particle size distribution, and expected exit air velocity. There is also an input for the tunnel geometry","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_19879_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19879-1","sourceUrl":"https://software.nasa.gov/software/LEW-19879-1","confidence":"high"},"type":"software","title":"Periodic Table of Life","abstract":"The Periodic Table of Life (PeTaL) is a tool and open source framework that uses artificial intelligence to aid in the systematic inquiry of biology for its application to human systems. This paper defines the PeTaL concept and workflow. Biomimicry, biophysics, biomimetics, bionics and numerous other terms refer to the use of biology and biological principles to inform practices in other disciplines. For the most part, the domain of inquiry in these fields have been confined to extant biological models with the proponents of biomimicry often citing the evolutionary success of extant organisms relative to extinct ones. The primary objective of this paper is to expand the domain of inquiry for human processes that seek to model those that are, were or could be found in nature with examples that relate to the field of aerospace and to spur development of tools that can work together to accelerate the use of artificial intelligence in problem solving. Specifically specialized fields such as paleomimesis, anthropomimesis and physioteleology are proposed in conjunction with artificial evolution. Blockchain technology may be vital in allowing open source design tools such as PeTaL to democratize design and yet protect intellectual property. The overarching philosophy outlined here can be thought of as physiomimetics, a holistic and systematic way of learning from natural history. The backbone of PeTaL integrates an unstructured database with an ontological model consisting of function, morphology, environment, state of matter and ecosystem. Tools include text classification, thesaurus, data visualization , and analysis. Applications of PeTaL include guiding human space exploration, understanding human and geological history, and discovering new or extinct life.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa-petal/PeTaL","license":null}},{"forgeId":"forge_nasa_lew_20017_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20017-1","sourceUrl":"https://software.nasa.gov/software/LEW-20017-1","confidence":"high"},"type":"software","title":"Electrical Power System - Sizing and Analysis Tool (EPS-SAT)","abstract":"The Electrical Power System - Sizing and Analysis Tool (EPS-SAT) is a tool whose purpose is to analyze electrical power system architectures in order to better direct investment dollars and to expose the strengths and weaknesses of various designs. The software uses on- and off-design modes to complete this analysis . In on-design, the electrical power system components are sized (to estimate system mass, loss, and efficiency). In off-design, the system's performance (such as loss, and efficiency) is calculated at points in the power system's operating range. EPS-SAT includes a Newton-Raphson solver, basic and detailed electrical power system components, and a library of study tools. By using these elements of EPS-SAT, a user can size an electrical power system, perform system trade studies, and examine system response at off-nominal design points.","category":"electronics","categoryRaw":"electronics and electrical power","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_20090_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20090-1","sourceUrl":"https://software.nasa.gov/software/LEW-20090-1","confidence":"high"},"type":"software","title":"CCSDS Optical Communications High Photon Efficiency Telemetry Signaling Transmit Waveform VHDL/Verilog","abstract":"This technology is a VHDL and Verilog implementation of the Consultative Committee for Space Data Systems (CCSDS) Optical Communications High Photon Efficiency Telemetry Signaling waveform. The CCSDS 142.0-B-1 Blue Book from August 2019 is implemented. The implementation includes a data source, transfer frame synchronization marker attachment, slicer, randomizer, cyclic redundancy check, termination bit attachment, convolutional encoder, code interleaver, accumulator, pulse position modulation (PPM) symbol mapper, channel interleaver, codeword sync marker attachment, symbol repeater, slot mapper, and guard slot insertion.","category":"electronics","categoryRaw":"electronics and electrical power","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_20096_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20096-1","sourceUrl":"https://software.nasa.gov/software/LEW-20096-1","confidence":"high"},"type":"software","title":"STRS GPS and Galileo Receiver for the ISS (GARISS)","abstract":"The GARISS waveform implements a GNSS receiver that performs position determination using the L5/E5a band of the GPS/Galileo satellite constellations. It was operated in a space environment on the SCaN Testbed platform aboard the ISS. The waveform takes L-band input as one bit samples at 38 MHz and uses FPGA and CPU processing to implement acquisition, tracking, navigation message decoding, and position-velocity-time (PVT) generation. Signals from both constellations are combined when generating PVT, which often leads to better visibility than using a single constellation alone. The computed PVT and other receiver metrics are output as telemetry logs.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_20097_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20097-1","sourceUrl":"https://software.nasa.gov/software/LEW-20097-1","confidence":"high"},"type":"software","title":"Electrical Modeling and Thermal Analysis Toolbox (EMTAT)","abstract":"The Electrical Modeling and Thermal Analysis Toolbox (EMTAT) is a MATLAB/Simulink based building block graphical tool used to create simulations of electrical/power systems. EMTAT is specifically designed to simulate electric/electrified propulsion systems at the level of fidelity (time scale) appropriate to capture the interaction with turbomachinery. EMTAT contains blocks that represent electrical components (batteries, motors/generators, inverters, etc.) modeled using either power flow or physics based representations. EMTAT is compatible with the Toolbox for the Modeling and Analysis of Thermodynamic Systems (T-MATS) for simulations that require mechanical components (turbomachinery, shafts, propellers, etc.). For such mixed simulations (i.e., those containing both electrical components and turbomachinery), the EMTAT blocks can use the T-MATS solver, allowing the relevant electrical and mechanical variables to be solved simultaneously.","category":"electronics","categoryRaw":"electronics and electrical power","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/EMTAT","license":null}},{"forgeId":"forge_nasa_lew_20181_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20181-1","sourceUrl":"https://software.nasa.gov/software/LEW-20181-1","confidence":"high"},"type":"software","title":"MATLAB Software Associated with \"Practical Micromechanics of Composite Materials\" Book, Elsevier Publishing","abstract":"This MATLAB software toolset was developed for use in solving the example and exercises provided in the book entitled \"Practical Micromechanics of Composite Materials\" , authored by Prof. J Aboudi, S. M. Arnold and B.A. Bednarcyk. The MATLAB scripts and functions calculate composite effective properties, margins of safety, and progressive damage of unidirectional and/or composite laminates using classical ply-based lamination theory, stand-alone micromechanics theories (such as Mori-Tanka, MOC,GMC, HFGMC along with failure theories and margin of safety calculations) or micromechanics-based classical lamination theory to illustrate their utility for the design and analysis of advanced composites.","category":"materials_coatings","categoryRaw":"materials and processes","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/Practical-Micromechanics","license":null}},{"forgeId":"forge_nasa_lew_20190_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20190-1","sourceUrl":"https://software.nasa.gov/software/LEW-20190-1","confidence":"high"},"type":"software","title":"Power Autonomy Research and Development Environment (PARDE)","abstract":"The Power Autonomy Research and Development Environment (PARDE) software package is a version of NASA's Autonomous Power Control (APC) software that can be used to evaluate fault management and automatic power system reconfiguration algorithms in a relevant system without having to fully develop all the supporting software. Software items included are a set of C++ class source files representing simplified fault management and reconfiguration logic, a power system simulation representing a notional architecture for NASA's Gateway vehicle, a web-based graphical user interface for running and testing the simulation and APC, a Docker-based automatic setup script for a development environment, and a user's guide.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_20249_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20249-1","sourceUrl":"https://software.nasa.gov/software/LEW-20249-1","confidence":"high"},"type":"software","title":"Microscopy Segmentation Models","abstract":"A new technique was developed for creating highly accurate microscopy image segmentation models with less training data . This technique uses transfer learning from classification models that were pretrained on the massive microscopy image database from the NASA ASG lab. Experiments show that transferring the features learned from pretraining on large microscopy datasets to segmentation tasks leads to accurate segmentation models with significantly less training data and the models generalize to unseen data better. This is significant because training data for segmentation tasks is expensive and in limited availability and this technique reduces the required training data . In addition, the labeled training data cannot account for all possible imaging and sample conditions that the model should be expected to perform accurately on, and experiments showed that this technique improves model accuracy on data outside the training distribution. Developing accurate segmentation models is significant because it is the first and hardest step in automatically quantifying microstructure features which is critical to linking the processing-structure-property relationships of materials. By quantitatively understanding these relationships, one may discover and develop new materials through traditional or data -driven methods.","category":"materials_coatings","categoryRaw":"materials and processes","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/pretrained-microscopy-models","license":null}},{"forgeId":"forge_nasa_lew_20278_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20278-1","sourceUrl":"https://software.nasa.gov/software/LEW-20278-1","confidence":"high"},"type":"software","title":"SMAnalytics - Software for the Automated Analysis , Summary, and Reporting of Shape Memory Alloy Tests","abstract":"This software describes a new program for automated analysis , summarizing, and reporting of shape memory alloy (SMA) test data. The current version allows automated and standardized analysis of data from standardized test methods pertinent to shape memory alloys: ASTM E3097 Uniaxial Constant Force Thermal Cycling (UCFTC), ASTM E3098 Uniaxial Pre-Strain and Thermal Free Recovery (UPFR), and ASTM F2004 Differential Scanning Calorimetry (DSC). The software allows analysis of variants of these methods, such as multi-cycle, multi-stress UCFTC and UPFR. The program allows for extraction of multiple properties including transformation temperatures, transformation and residual strains, strain recovery, and other related properties. It allows automated and uniform generation of specified material property reports which could be used by material suppliers or test labs for certification documents. In addition, it allows exporting of the complete summarized material test data which can then be imported into the NASA Shape Memory Material Database.","category":"materials_coatings","categoryRaw":"materials and processes","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_20309_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20309-1","sourceUrl":"https://software.nasa.gov/software/LEW-20309-1","confidence":"high"},"type":"software","title":"NASMAT PrePost: A Visualization and Analysis Tool for the NASA Multiscale Analysis Tool","abstract":"NASMAT PrePost is an open-source python-based visualization and analysis tool that performs pre-processing of inputs and post-processing of results for the NASA Multiscale Analysis Tool (NASMAT). Users can use the tool to generate or open NASMAT input files, run a NASMAT analysis, and visualize multiscale analysis results through a user interface. Limited support is included for visualizing results obtained via the Abaqus finite element software/NASMAT interface. NASMAT-specific functions are decoupled from the user interface so that a user can generate models independently if desired.NASMAT PrePost is intended to be used alongside with the separately-provided NASMAT software. While most functions of NASMAT PrePost can be utilized without having NASMAT, NASMAT is required if a user wants to generate their own results. NASMAT is also distributed via the NASA Software Catalog.","category":"materials_coatings","categoryRaw":"materials and processes","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/nasmat-prepost","license":null}},{"forgeId":"forge_nasa_lew_20316_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20316-1","sourceUrl":"https://software.nasa.gov/software/LEW-20316-1","confidence":"high"},"type":"software","title":"Optimal Experimental Design With Fast Neural Network Surrogate Models","abstract":"Designing optimal experiments minimizes the uncertainty of results and maximizes the efficient use of resources. This technology uses machine learning surrogate models and the approximate coordinate exchange (ACE) algorithm are used to determine optimal experimental designs (OEDs) over large or arbitrarily restrictive design spaces. OED is particularly salient in materials science, where experiments are expensive and material properties must often be inferred indirectly. The framework is demonstrated by finding optimal experiments with which the hidden constituent properties of composite materials can be most efficiently inferred from observable experimental outcomes. The OED is given by an information theoretic criterion that maximizes the conditional mutual information between the hidden properties and the expected experimental outcomes. To perform tractable optimization, a neural network is trained as a surrogate model to mimic a physics-based simulation , which can calculate the expected experimental outcome based on a candidate experimental design and sampled constituent properties. The ACE algorithm is used to optimize over large design spaces with many tests and controlled parameters where an exhaustive search would be intractable even with the surrogate model. Using this approach, OEDs that are consistent with those produced by heuristic knowledge and established best practices are found; then optimal designs in larger design spaces where heuristic knowledge is unavailable are examined.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/OED-with-NN-surrogates","license":null}},{"forgeId":"forge_nasa_lew_20332_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20332-1","sourceUrl":"https://software.nasa.gov/software/LEW-20332-1","confidence":"high"},"type":"software","title":"Earth Surface Bistatic Scattering Coefficient Prediction Model","abstract":"This MATLAB code package provides tools for predicting the bistatic scattering coefficients and coherent reflection coefficients for the water surfaces and land surfaces. These models can be applied at any elevation angle, except grazing incidence, and they work for frequencies between 1 and 100 GHz. For frequencies less than 1 GHz, the coherent component may be the dominant source of any interference effects, greatly simplifying the required modelling of Earth surface reflections.This MATLAB code implements internationally recognized standard Recommendation ITU-R P.2146-0. This code also conforms to established validation examples developed and approved by the International Telecommunications Union (ITU-R).Moreover, the following three analytic models which are widely used in academic literature for modelling bistatic scattering coefficients, are leveraged in the MATLAB code package:Small perturbation model (SPM);Kirchhoff approximation model (KA), andThe two scale scattering model (TSSM).","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/bistatic","license":null}},{"forgeId":"forge_nasa_lew_20350_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20350-1","sourceUrl":"https://software.nasa.gov/software/LEW-20350-1","confidence":"high"},"type":"software","title":"Optimal Feature Selection Tool with Machine Learning","abstract":"The design tool was developed to choose the optimum set of critical features of data that should be controlled to achieve desired target variable for a given acceptable uncertainty. The tool can conduct data science approaches such as exploratory data analysis , low variance threshold, filter, wrapper, and embedded feature selection technique. The integrated techniques can be applied to determine the critical features that should be controlled to achieve target properties for material systems.","category":"materials_coatings","categoryRaw":"materials and processes","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/feature_selection_tool","license":null}},{"forgeId":"forge_nasa_lew_20430_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20430-1","sourceUrl":"https://software.nasa.gov/software/LEW-20430-1","confidence":"high"},"type":"software","title":"Lightweight Onboard Doppler Compensation for Satellite Communications","abstract":"This VHDL module runs on a spacecraft's software-defined radio to reduce the effects of Doppler on wireless commnuications. The module implements a linear frequency sweep in the opposite direction of predicted Doppler shift to null out its effects on transmitted or received signals. Designed with resource-constrained transceivers in mind, minimal FPGA resources (e.g. less than 1% of Virtex 7 resources) are used.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_20475_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20475-1","sourceUrl":"https://software.nasa.gov/software/LEW-20475-1","confidence":"high"},"type":"software","title":"Software Defined Networking Implementation of a Delay Tolerant Networking Bundle Protocol Version 6 and 7 Translator","abstract":"The proposed software has the Programming Protocol-Independent Packet Processors (P4) logic to translate between Bundle Protocol (BP) version 6 and version 7 on an Aurora 710 networking switch containing an Intel Tofino integrated circuit (IC) through data plan programming.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/SDN-HDTN","license":null}},{"forgeId":"forge_nasa_lew_20480_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20480-1","sourceUrl":"https://software.nasa.gov/software/LEW-20480-1","confidence":"high"},"type":"software","title":"Radio Frequency Mass Gauge Analysis Software (RFMG-AS)","abstract":"The Radio Frequency Mass Gauge (RFMG) is a propellant gauging technique developed for gauging cryogenic propellants in low gravity and normal settled environments. This New Technology Report is for the RFMG-AS, a MATLAB-based software suite with a graphical user interface (GUI) that allows processing of swept-frequency antenna responses to accurately predict propellant tank fuel levels. It is comprised of three main functional components: peak detection, mass gauging, and analysis . Mass gauging is performed by matching experimental peak spectra against simulated peak spectra (eigenmodes) for different tank fluid configurations and fill levels. The RFMG technology was previously disclosed under LEW-18373-1","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_20492_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20492-1","sourceUrl":"https://software.nasa.gov/software/LEW-20492-1","confidence":"high"},"type":"software","title":"Automatic Image Analysis of Environmental Barrier Coating Thermally Grown Oxide Layers using Machine Learning and Computer Vision","abstract":"Uses machine learning and computer vision to automatically measure microstructure features from images of environmental barrier coatings. Quantifying microstructure is critical to designing better materials by establishing processing-structure-property relationships. Previous measurement techniques relied on manual human measurements which is extremely time consuming, prone to bias, and requires expertise. This software can automatically and accurately measure oxide thickness, roughness, porosity, and crack spacing in a matter of seconds and the results are repeatable and comparable between research groups. The open source GUI and algorithms can be adapted to perform other types of image analysis and have been applied to analyze many other material microstructures.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/AQUAMI-TGO","license":null}},{"forgeId":"forge_nasa_lew_20511_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20511-1","sourceUrl":"https://software.nasa.gov/software/LEW-20511-1","confidence":"high"},"type":"software","title":"CCSDS Optical Communications High Photon Efficiency Transmit Downlink Waveform Matlab Model","abstract":"This technology is a Matlab model of the Consultative Committee for Space Data Systems (CCSDS) Optical Communications High Photon Efficiency downlink transmit waveform. The model implements the CCSDS 142.0-B-1 Blue Book from August 2019. This includes a data source, transfer frame synchronization marker attachment, slicer, randomizer, cyclic redundancy check, termination bit attachment, convolutional encoder, code interleaver, accumulator, pulse position modulation (PPM) symbol mapper, channel interleaver, codeword sync marker attachment, symbol repeater, slot mapper, and guard slot insertion. The model can be used to verify FPGA implementations of the CCSDS standard.","category":"electronics","categoryRaw":"electronics and electrical power","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_20593_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20593-1","sourceUrl":"https://software.nasa.gov/software/LEW-20593-1","confidence":"high"},"type":"software","title":"TFExec - A FORTRAN bridge for TensorFlow models","abstract":"TFExec is an interface between FORTRAN and TensorFlow that allows physics simulation software to make a high volume of calls to a neural network model.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/tfexec","license":null}},{"forgeId":"forge_nasa_lew_20650_2","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20650-2","sourceUrl":"https://software.nasa.gov/software/LEW-20650-2","confidence":"high"},"type":"software","title":"NASA Multiscale Analysis Tool (NASMAT) version 5.0","abstract":"The NASA Multiscale Analysis Tool (NASMAT) serves as a state-of-the-art, plug and play, software package which utilizes multiscale recursive micromechanics as a platform for massively multiscale modeling of hierarchical materials and structures subjected to thermomechanical loads on high performance computing systems. Version 5.0 includes new features and improvements from previous versions including fatigue, interfacial debonding, non-periodic boundary conditions, coupled multi-physics, state dependent microstructure and property evolution, improvements to dry fabric module, and finite element method based micromechanics.","category":"materials_coatings","categoryRaw":"materials and processes","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_20760_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20760-1","sourceUrl":"https://software.nasa.gov/software/LEW-20760-1","confidence":"high"},"type":"software","title":"Manufactured Ecosystems Virtual Reality (VR) Mars Habitat Visualization","abstract":"The Manufactured Ecosystems virtual reality (VR) visualization depicts a Mars habitat based on research from the Manufactured Ecosystems project. This project researches how ecosystem services provided to us on Earth could be replaced or supported by technology and what is needed to achieve this technology. This type of research is valuable to helping us live on and explore other planets and could also be applied to Earth if something prevented the ecosystem from completing these services.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_20786_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20786-1","sourceUrl":"https://software.nasa.gov/software/LEW-20786-1","confidence":"high"},"type":"software","title":"Prologix GPIB-Ethernet Controller Configuration Utility","abstract":"The Prologix GPIB-Ethernet Controller Configuration Utility is a piece of software designed to interface with and configure a Prologix GPIB-Ethernet Controller. These controllers are used to communicate between an ethernet and a GPIB interface, and they are often used to connect a data acquisition system to a piece of instrumentation. This software is used to configure the multitude of settings, both network settings and GPIB settings, that exist on these controllers. This tool is a command line interface (CLI) utility that operates as single-use commands (that can be scripted for automation) run from any standard command line to interact with and configure the Prologix hardware on Windows system.","category":"electronics","categoryRaw":"electronics and electrical power","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_20832_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20832-1","sourceUrl":"https://software.nasa.gov/software/LEW-20832-1","confidence":"high"},"type":"software","title":"Electrical Power System - Sizing and Analysis Tool (EPS-SAT)","abstract":"The Electrical Power System - Sizing and Analysis Tool (EPS-SAT) is a tool whose purpose is to analyze electrical power system architectures in order to better direct investment dollars and to expose the strengths and weaknesses of various designs. The software uses on- and off-design modes to complete this analysis . In on-design, the electrical power system components are sized (to estimate system mass, loss, and efficiency). In off-design, the system's performance (such as loss, and efficiency) is calculated at points in the power system's operating range. EPS-SAT includes a Newton-Raphson solver, basic and detailed electrical power system components, and a library of study tools. By using these elements of EPS-SAT, a user can size an electrical power system, perform system trade studies, and examine system response at off-nominal design points.","category":"electronics","categoryRaw":"electronics and electrical power","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_27332_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-27332-1","sourceUrl":"https://software.nasa.gov/software/MFS-27332-1","confidence":"high"},"type":"software","title":"VLOADS V1.4 Launch Vehicle Loads Analysis For Preliminary Design","abstract":"The VLOADS program calculates launch vehicles' in-flight structural loads for preliminary design. The program may also be used to calculate structural loads for upper stages and planetary transfer vehicles. Launch vehicle information and input data such as aerodynamic coefficients, mass properties, propellants, engine thrusts, and performance data are compiled and analyzed by VLOADS to produce distributed shear loads, bending moments, axial forces, and vehicle line loads as a function of X-station along the vehicle's length. Translational accelerations and interface loads, if the launch vehicle has booseters or wings, are also computed.","category":"mechanical_systems","categoryRaw":"structures and mechanisms","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_31223_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-31223-1","sourceUrl":"https://software.nasa.gov/software/MFS-31223-1","confidence":"high"},"type":"software","title":"Monocoque Tank Analysis Spreadsheet System (MonTASS), Version 2.0","abstract":"The Monocoque Tank Analysis Spreadsheet System (MonTASS) computer program enables rapid analysis and preliminary design of structural domes and truncated sections of cones. MonTASS performs both design and analysis functions and can be used to analyze nonpressurized conical structures.","category":"mechanical_systems","categoryRaw":"structures and mechanisms","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_31243_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-31243-1","sourceUrl":"https://software.nasa.gov/software/MFS-31243-1","confidence":"high"},"type":"software","title":"Video Image Stabilization and Registration (VISAR)","abstract":"Video Image Stabilization and Registration (VISAR) is a software program that will stabilize video images distorted as a result of video camera motion. There are multiple applications for this software including stabilization of images from mobile platforms, crime scenes, robotic systems, spacecraft and home video.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_31309_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-31309-1","sourceUrl":"https://software.nasa.gov/software/MFS-31309-1","confidence":"high"},"type":"software","title":"Low-Altitute Trapped Radiation Model, Version 1","abstract":"Accurate models of the Earth's trapped energetic proton environment are required for both piloted and robotic space missions. As astronomical and remote sensing detectors become more sensitive, proton flux can induce unwanted backgrounds in the instrumentation. The Low-Altitute Trapped Radiation Model, based on nearly 20 years of data from the TIRO/NOAA weather satellites, predicts the integral omindirectional proton flux in three energy ranges: >16, >36, and >80 MeV. The model contains a true solar cycle variation and accounts for the secular variation in the Earth's magnetic field.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_31319_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-31319-1","sourceUrl":"https://software.nasa.gov/software/MFS-31319-1","confidence":"high"},"type":"software","title":"Trapped Radiation Models - Uncertainties For Spacecraft Design","abstract":"The focus of Trapped Radiation Models software development effort was to help spacecraft and payload designers to account for uncertainties in predictive models of the Earth's trapped radiation environment. A tool was needed for more accurately determining radiation requirements and risks -- essential elements for producing less expensive, more reliable spacecraft.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_31328_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-31328-1","sourceUrl":"https://software.nasa.gov/software/MFS-31328-1","confidence":"high"},"type":"software","title":"Spacecraft Materials Selector (SMS) Expert System","abstract":"The SMS knowledge base is a preliminary design tool that provides estimates of environmental exposures and/or materials performance. Inputs may launch date, altitude, inclination, mission duration, and certain characteristics of satellite motion.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_31329_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-31329-1","sourceUrl":"https://software.nasa.gov/software/MFS-31329-1","confidence":"high"},"type":"software","title":"Trapped Proton Model (TPM)","abstract":"TPM determines the differential omnidirectional proton flux from 1 to 100 MeV. At high altitudes, the model is based on CRRESPRO developed by AFRL; at low altitudes, the model is based on data from the TIROS/NOAA (POES) low-altitude polar-orbiting satellites. The model contains a true solar cycle variation and also contains sub-models for quiet and active magnetospheric states.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_31383_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-31383-1","sourceUrl":"https://software.nasa.gov/software/MFS-31383-1","confidence":"high"},"type":"software","title":"Payloads and Components Real-Time Automated Test System (PACRATS)","abstract":"The PACRATS data acquisition program allows test engineers to acquire, display, store, and retrieve test data .","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_31620_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-31620-1","sourceUrl":"https://software.nasa.gov/software/MFS-31620-1","confidence":"high"},"type":"software","title":"Cosmic Ray Effects On Microelectronics (CREME96)","abstract":"This software is an improved model of the ionizing radiaiton environment in space and its effects on satellites and is a computational tool used by aerospace engineers. This software is used to estimate single event effects (SEE) rates: 1) as a guide to parts selection for spacecraft, 2) to demonstrate compliance of a proposed spacecraft design with engineering requirements on reliability and operability, and 3) as a guide in determining the cause of observed spacecraft anomalies.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_31664_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-31664-1","sourceUrl":"https://software.nasa.gov/software/MFS-31664-1","confidence":"high"},"type":"software","title":"WinPlot Graphical Display System","abstract":"WinPlot is a powerful desktop graphical analysis tool that allows the user to generate displays of unrestrictive amounts of data. It was developed to fulfill the need for fast and easily managed graphical displays of NASA test articles and facilities. WinPlot features include seamless displays of realtime and post-test data with time and event-time synchronization of data from multiple sources.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_31675_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-31675-1","sourceUrl":"https://software.nasa.gov/software/MFS-31675-1","confidence":"high"},"type":"software","title":"Interactive Spacecraft Charging Handbook With Integrated, Updated Spacecraft Charging Models (ISCCH ), Version 3.1","abstract":"The ISCCH is an interactive, Web-based multimedia product that offers updated and integrated spacecraft charging models. The software guides the non-expert using the power of sophisticated analysis tools.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_31700_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-31700-1","sourceUrl":"https://software.nasa.gov/software/MFS-31700-1","confidence":"high"},"type":"software","title":"High-Speed Data Viewer","abstract":"The High-Speed Data Viewer computer software was developed for viewing high-frequency data recorded in the East and West Test Areas at Marshall Space Flight Center (MSFC).Features include: Amplitude vs. Time Plots with full zoom capabilities; Frequency Component Plot at specified time interval; Waterfall Plots/Frequency Intensity Plots display changing frequency components over a duration of time; print options for plots; export functions save plot data as text files for importing into other applications. This software allows the user to plot data in time domain and view frequency components in multiple ways.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_31728_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-31728-1","sourceUrl":"https://software.nasa.gov/software/MFS-31728-1","confidence":"high"},"type":"software","title":"Simple Thermal Environment Model (STEM) User's Guide","abstract":"Helpful in the thermal analysis of near-Earth spacecraft, the STEM User's Guide is a Fortran-based program that provides engineering estimates of top-of-atmosphere albedo and outgoing longwave radiation.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_31864_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-31864-1","sourceUrl":"https://software.nasa.gov/software/MFS-31864-1","confidence":"high"},"type":"software","title":"Bearing Analysis Tool (BAT)","abstract":"The Bearing Analysis Tool (BAT) allows detailed design of rolling element bearings rocket engine turbopumps and other applications. It includes a graphical user interface that greatly reduces the effort required to define analytical models for simulation and design.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_32001_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-32001-1","sourceUrl":"https://software.nasa.gov/software/MFS-32001-1","confidence":"high"},"type":"software","title":"Radiation Environment Array Charge Transport (REACT)","abstract":"The REACT detector array charge collection model is useful in the design of optical sensor missions.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_32011_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-32011-1","sourceUrl":"https://software.nasa.gov/software/MFS-32011-1","confidence":"high"},"type":"software","title":"ElectroStatic Return of Contaminants Tool (Updated)","abstract":"The ElectroStatic Return of Contaminants (ESR) tool is a first-generation computational code created for the purpose of computing the return characteristics of spacecraft -generated contaminants. The code computes the Debye sheath (if necessary), the returned contaminant mass rate, returned mass flux, returned mass ratio, return velocity, and surface sputter (where applicable). To help the user, default values have been supplied for all program inputs.This software code is provided \"as is\".","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_32019_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-32019-1","sourceUrl":"https://software.nasa.gov/software/MFS-32019-1","confidence":"high"},"type":"software","title":"The Charge Collector (TCC), Version 2.1","abstract":"TCC is a compilation of spacecraft charging tools including design guidelines and a variety of information from government/industry/academic databases and reports.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_32056_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-32056-1","sourceUrl":"https://software.nasa.gov/software/MFS-32056-1","confidence":"high"},"type":"software","title":"NASA/Air Force Spacecraft Charging Analyzer Program (NASCAP-2K), Version 4.5","abstract":"NASCAP-2K is the next-generation spacecraft charging analysis code. The technology is a comprehensive update to the original NASCAP spacecraft charging codes written twenty years ago. A collaboration of NASA and the U.S. Air Force Research Lab (AFRL), the software builds upon the Air Force's DynaPAC charging algorithms and will replace 3D spacecraft charging codes for all environments.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_32165_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-32165-1","sourceUrl":"https://software.nasa.gov/software/MFS-32165-1","confidence":"high"},"type":"software","title":"Electric Propulsion Interactions Code (EPIC)","abstract":"EPIC is an interactive computer toolset that enables the construction of a 3D spacecraft model and the assessment of a variety of interactions between the model's subsystems and the plume from an electric thruster. EPIC unites different computer tools to address the many complexities associated with spacecraft /plume interaction processes.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_32205_2","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-32205-2","sourceUrl":"https://software.nasa.gov/software/MFS-32205-2","confidence":"high"},"type":"software","title":"Meteoroid Engineering Model (MEM) version 3","abstract":"MEM 3 is NASA's most current and accurate model of the meteoroid environment. It describes potentially hazardous meteoroids in the inner solar system and provides the flux, directionality, speed, and bulk density of meteoroids encountered along a user-specified spacecraft trajectory.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_32296_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-32296-1","sourceUrl":"https://software.nasa.gov/software/MFS-32296-1","confidence":"high"},"type":"software","title":"Neptune Global Reference Atmospheric Model (Neptune-GRAM), Version 1.0","abstract":"From surface to orbital altitudes, this Fortran-based program provides engineering estimates of density, temperature, pressure, and winds for the Neptune atmosphere.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_32297_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-32297-1","sourceUrl":"https://software.nasa.gov/software/MFS-32297-1","confidence":"high"},"type":"software","title":"Titan Global Reference Atmospheric Model (Titan-GRAM), Version 1.0","abstract":"Titan-GRAM is a Fortran-based program that provides engineering estimates of density, temperature, pressure, and winds for the Titan atmosphere. More information on the Space Environments & Effects (SEE) Program can be found at http://see.msfc.nasa.gov/.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_32314_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-32314-1","sourceUrl":"https://software.nasa.gov/software/MFS-32314-1","confidence":"high"},"type":"software","title":"Venus Global Reference Atmospheric Model (Venus-GRAM) 2005, Version 1.0","abstract":"Venus-GRAM 2005 is a Fortran-based program that provides engineering estimates of density, temperature, pressure, and winds for the Venus atmosphere.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_32397_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-32397-1","sourceUrl":"https://software.nasa.gov/software/MFS-32397-1","confidence":"high"},"type":"software","title":"Sun Format Database (SunAcc) File Read/Write Library","abstract":"The Sun Format Database (SunAcc) was developed to fulfill a need for local native storage of Space Shuttle Main Engine (SSME) test data . While the file format itself is native to the Sun UNIX platform, the read/write library was developed to be a cross-platform tool and is compatible with a variety of UNIX and Windows platforms.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_32780_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-32780-1","sourceUrl":"https://software.nasa.gov/software/MFS-32780-1","confidence":"high"},"type":"software","title":"Earth Global Reference Atmospheric Model 2010 ( Earth GRAM 2010)","abstract":"Earth Gram 2010 is an open-source Fortran computer code that can run on a variety of platforms including PCs and UNIX stations. The model provides values for atmospheric parameters such as density, temperature, winds, and constituents for any month and at any altitude and location within the Earth 's atmosphere. Versions from 1999 and 2007 are also available.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_32780_2","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-32780-2","sourceUrl":"https://software.nasa.gov/software/MFS-32780-2","confidence":"high"},"type":"software","title":"Earth Global Reference Atmospheric Model 2016 ( Earth GRAM 2016)","abstract":"Earth GRAM 2016 is a computer code that can run on a variety of platforms including PCs and Linux stations. The model provides values for atmospheric parameters such as density, temperature, winds, and constituents for any month and at any altitude and location within the Earth 's atmosphere. Earth -GRAM 2010 is available in FORTRAN.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_32802_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-32802-1","sourceUrl":"https://software.nasa.gov/software/MFS-32802-1","confidence":"high"},"type":"software","title":"Magnetogram Forecast (Mag4) 2018","abstract":"Forecasting from a magnetogram of a sunspot active region, this algorithm predicts solar eruptions anticipated within the next 24 to 48 hours. The technology essentially transforms available solar scientific data into forecasting tools for severe space weather conditions.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_32925_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-32925-1","sourceUrl":"https://software.nasa.gov/software/MFS-32925-1","confidence":"high"},"type":"software","title":"AutoPost","abstract":"AutoPost can process any configuration of test data as needed. The tool can combine a series of data parameters into a single parameter.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_33014_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-33014-1","sourceUrl":"https://software.nasa.gov/software/MFS-33014-1","confidence":"high"},"type":"software","title":"Smartphone Video Guidance Sensor (SVGS)","abstract":"The Smartphone Video Guidance Sensor (SVGS) allows for calculation of the distance and orientation of an object relative to the SVGS. A known retroreflective target pattern is mounted on the target object. These retroreflectors are then illuminated by the camera flash on the smartphone and imaged by the smartphone camera. The resulting image is processed using photogrammetry algorithms running on the smartphone to extract the relative X, Y, and Z distance and relative orientation, expressed as a roll, pitch, yaw angle sequence.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_33082_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-33082-1","sourceUrl":"https://software.nasa.gov/software/MFS-33082-1","confidence":"high"},"type":"software","title":"Tool for Analysis of Surface Cracks (TASC)","abstract":"Created using the commercial math analysis software MATLAB, TASC enables the easy computation of nonlinear J-integral solutions for surface-cracked plates in tension by accessing and interpolating between the 600 nonlinear surface crack solutions documented in NASA/TP-2011-217480. The only required inputs to the program are the surface crack dimensions, plate cross-section dimensions, and material properties. TASC provides a convenient and easy-to-use interface for the solution set that allows a novice user to obtain a fast and reliable fracture toughness solution.","category":"materials_coatings","categoryRaw":"materials and processes","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://sourceforge.net/projects/tascnasa/ ","license":null}},{"forgeId":"forge_nasa_mfs_33158_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-33158-1","sourceUrl":"https://software.nasa.gov/software/MFS-33158-1","confidence":"high"},"type":"software","title":"Mars Global Reference Atmospheric Model 2010 (Mars GRAM 2010)","abstract":"Mars GRAM is an engineering-level atmospheric model widely used for diverse mission applications, including systems design, performance analysis , and operations planning for aerobraking, entry descent and landing, and aerocapture.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_33187_2","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-33187-2","sourceUrl":"https://software.nasa.gov/software/MFS-33187-2","confidence":"high"},"type":"software","title":"Project Cost Estimating Capability (PCEC)","abstract":"The Project Cost Estimating Capability (PCEC) is a parametric tool for estimating the cost of unmanned spacecraft, landers, launch vehicles, crewed systems, and in-space transportation systems. It is an Excel add-in with a simple, robust, and transparent collection of cost-estimating relationships (CERs), their associated statistics, work breakdown structures, estimating templates, and other cost estimating artifacts. PCEC facilitates the investigation, selection, and use of these artifacts towards the creation of a parametric estimate for a space flight hardware system in an Excel workbook.For more information regarding PCEC, please visit: https://www.nasa.gov/ocfo/ppc-corner/pcec-project-cost-estimating-capability/","category":"operations","categoryRaw":"business systems and project management","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_33209_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-33209-1","sourceUrl":"https://software.nasa.gov/software/MFS-33209-1","confidence":"high"},"type":"software","title":"Autonomous Real Time Requirements Tracing (ART)","abstract":"This NASA software offers the ability to directly trace the real-time execution of software to specific requirements, a unique capability that can only be performed with a Timeliner-TLX system, as no other computer languages directly report this data during execution. The tracing feature does not impose input/output requirements (e.g., print/write statements) on the targeted software because the tracing is performed by an outside program executing separately. The Timeliner-TLX language is currently used for auto-procedures on the International Space Station (ISS) and the Autonomous Mission Operations (AMO) project, and future manned deep-space missions will require the use of extensive auto-procedures to assist in remote intelligent operations.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_33219_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-33219-1","sourceUrl":"https://software.nasa.gov/software/MFS-33219-1","confidence":"high"},"type":"software","title":"Python Advanced Microwave Precipitation Radiometer Data Toolkit (PyAMPR)","abstract":"This toolkit will read geolocated brightness temperature data (in ASCII format) from any flight of the AMPR airborne instrument. A python script will pull out timing, brightness temperatures, and other information from each channel/geolocation and store them as attributes using the appropriate type of numpy array. The approach consists of ingesting the entire file as a text string and then parsing and converting as necessary. The file is read and the data are populated when the class is instantiated with the full path and name of an AMPR file. Numerous visualization methods are provided, including track plots, strip charts, and Google Earth KMZs. In addition, polarization deconvolution is available.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/tjlang/PyAMPR","license":null}},{"forgeId":"forge_nasa_mfs_33231_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-33231-1","sourceUrl":"https://software.nasa.gov/software/MFS-33231-1","confidence":"high"},"type":"software","title":"libSPRITE","abstract":"A set of libraries used in the development of software applications. libSPRITE was specifically designed for real-time systems that operate on a single computational node (but may be multi-core) to systematically address common coding errors, provide for multi-threaded programming to produce the exact same results regardless of the number of cores on the host compute node, and offer support for in-operation reconfigurability (parameter and control flow modifications). Components include engineering unit encoders, math functions, a task scheduler built on top of pthreads, a publish/subscribe data distribution system, and a Lua scripting language interface.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/libSPRITE","license":null}},{"forgeId":"forge_nasa_mfs_33236_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-33236-1","sourceUrl":"https://software.nasa.gov/software/MFS-33236-1","confidence":"high"},"type":"software","title":"Marshall MRMS Mosaic Python Toolkit (MMM-Py)","abstract":"MMM-Py reads, analyzes, and displays three-dimensional national mosaicked reflectivity data produced by NOAA's National Severe Storms Laboratory (NSSL). MMM-Py can read MRMS mosaics from either their unique binary format or their converted NetCDF format; it can also read and properly interpret the current mosaic design (4 regional tiles) as well as mosaics produced prior to late July 2013 (8 tiles). The technology can easily stitch multiple tiles together to provide a larger regional or national picture of precipitating weather systems. Composites, horizontal/vertical cross-sections, and combinations thereof are easily displayed using as little as one line of code.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/tjlang/MMM-Py","license":null}},{"forgeId":"forge_nasa_mfs_33237_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-33237-1","sourceUrl":"https://software.nasa.gov/software/MFS-33237-1","confidence":"high"},"type":"software","title":"Python Turbulence Detection Algorithm (PyTDA)","abstract":"PyTDA, an MSFC-based implementation of the National Center for Atmospheric Research (NCAR) Turbulence Detection Algorithm (NTDA), can be used for convective-scale analysis , situational awareness, and forensic meteorology. The software provides Python functions that will estimate turbulence from Doppler radar data. It is written in the Python programming language.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/tjlang/PyTDA","license":null}},{"forgeId":"forge_nasa_mfs_33272_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-33272-1","sourceUrl":"https://software.nasa.gov/software/MFS-33272-1","confidence":"high"},"type":"software","title":"Single Doppler Retrieval Toolkit (SingleDop)","abstract":"SingleDop is a software module, written in the Python programming language, that will retrieve two-dimensional low-level winds from either real or simulated Doppler radar data. It mimics the functionality of the algorithm described in the following reference:Xu et al., 2006: Background error covariance functions for vector wind analyses using Doppler-radar radial-velocity observations. Q. J. R. Meteorol. Soc., 132, 2887-2904.The interface is simplified to a single line of code in the end user's Python scripts, making implementation of the algorithm in their research analyses very easy. The software package also interfaces well with other open source radar packages, such as the Python ARM Radar Toolkit (Py-ART; https://github.com/ARM-DOE/pyart). Simple visualization (including vector and contour plots) and save/load routines (to preserve analysis results) are also provided.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/SingleDop ","license":null}},{"forgeId":"forge_nasa_mfs_33273_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-33273-1","sourceUrl":"https://software.nasa.gov/software/MFS-33273-1","confidence":"high"},"type":"software","title":"Python Interface to Cyclone Global Navigation Satellite System (CYGNSS) Wind Dataset","abstract":"The Cyclone Global Navigation Satellite System (CYGNSS) is a NASA Earth Science Mission that launched in December 2016. Currently, however, synthetic wind data in the format that will be used post-launch can be produced from current observations or model output via the CYGNSS End-to-End Simulator (E2ES). The present software, which is written in the Python language, was developed to facilitate the ingest, analysis , and display of CYGNSS data.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/PyGNSS","license":null}},{"forgeId":"forge_nasa_mfs_33274_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-33274-1","sourceUrl":"https://software.nasa.gov/software/MFS-33274-1","confidence":"high"},"type":"software","title":"Python Interface to Dual-Pol Radar Algorithms (DualPol)","abstract":"This is an object-oriented Python module that facilitates precipitation retrievals (e.g., hydrometeor type, precipitation rate, precipitation mass, particle size distribution information) from polarimetric radar data . It leverages existing open source radar software packages to perform all-in-one retrievals that are then easily visualized or saved using existing software.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/DualPol","license":null}},{"forgeId":"forge_nasa_mfs_33284_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-33284-1","sourceUrl":"https://software.nasa.gov/software/MFS-33284-1","confidence":"high"},"type":"software","title":"Python Polarimetric Radar Beam Blockage Calculation (PyBlock)","abstract":"This Python package will calculate beam blockage in polarimetric weather radar data using the specific differential phase (KDP) and fully self-consistent (FSC) methods of Timothy J. Lang et al. (2009; J. Atmos. Oceanic Technol.). This information can be used to correct the radar data when the radar beams intersect objects like trees, buildings, and mountains.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/PyBlock","license":null}},{"forgeId":"forge_nasa_mfs_33362_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-33362-1","sourceUrl":"https://software.nasa.gov/software/MFS-33362-1","confidence":"high"},"type":"software","title":"Schedule Test and Assessment Tool (STAT) 5.0","abstract":"The Schedule Test and Assessment Tool (STAT) 5.0 is a schedule management software add-in developed to work specifically within the Microsoft Project scheduling application. The STAT 5.0 software provides the automated capability to quickly identify, quantify, and report numerous types of critical schedule assessment data for management use. This software provides clear and objective reporting of key schedule assessment information such as; logic network integrity indicators, performance and trend metrics, schedule driver identification, data comparisons, margin and milestone tracking, and various other analysis data that can be used by project teams to assist in management decision making.","category":"operations","categoryRaw":"business systems and project management","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_33391_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-33391-1","sourceUrl":"https://software.nasa.gov/software/MFS-33391-1","confidence":"high"},"type":"software","title":"Mesh Network Communication System","abstract":"The system provides a framework for exchange of information between multiple network nodes to facilitate cooperation using a distributed mesh network communication architecture. A node is any entity, such as a vehicle, ground control station, etc., that is connected to the mesh network. Data exchanged can include such things as telemetry from vehicle-based nodes, commands from ground control nodes, science data, etc. By exchanging pertinent data, multiple nodes can act together to perform a task without requiring direct control from a central control node. The system was generically designed so that it would be applicable to any node type and many different vehicle types including UAVs and satellites. The mesh network architecture allows the system to adapt to individual node failures because by design the system has no master controlling the operation of the entire network.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/meshNetwork","license":null}},{"forgeId":"forge_nasa_mfs_33436_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-33436-1","sourceUrl":"https://software.nasa.gov/software/MFS-33436-1","confidence":"high"},"type":"software","title":"Multiple-Doppler Radar Analysis Toolkit (MultiDop)","abstract":"MultiDop merges three-dimensional variational analysis (3DVAR) software code developed by the University of Oklahoma with the Department of Energy's Python Atmospheric Radiation Measurement Radar Toolkit (Py-ART) software framework. This enables end users to ingest, correct, and grid their weather radar data using Py-ART, and then pass the radar volumes to MultiDop to synthesize, analyze, and display the 3D winds. An entire science analysis project can thus be done using a shareable Jupyter notebook.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/tjlang/MultiDop","license":null}},{"forgeId":"forge_nasa_mfs_33558_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-33558-1","sourceUrl":"https://software.nasa.gov/software/MFS-33558-1","confidence":"high"},"type":"software","title":"ISS_Camera_Geolocate","abstract":"This is a Python software library that facilitates the geolocation of photographs and video frames from the International Space Station (ISS). The library provides functions that take camera and pointing information along with publicly available ISS position information, and then will geolocate every pixel of the photograph in latitude and longitude. This enables geospatial analysis of astronaut photography from Earth, including pictures of clouds, lightning, coastlines, city lights, etc. Many images are available from https://earth.jsc.nasa.gov/ and can be fully geolocated using this software.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/ISS_Camera_Geolocate","license":null}},{"forgeId":"forge_nasa_mfs_33566_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-33566-1","sourceUrl":"https://software.nasa.gov/software/MFS-33566-1","confidence":"high"},"type":"software","title":"TREETOPS","abstract":"TREETOPS is a time history simulation of the motion of a complex multi-body flexible structures with active control elements. The name TREETOPS refers to the class of structures which may be simulated by the program, i.e., those having a tree topology (where loop closures are handled with a cut graph technique). TREETOPS offers the user an advanced capability for analyzing the dynamics and control-related issues of such structures.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_33648_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-33648-1","sourceUrl":"https://software.nasa.gov/software/MFS-33648-1","confidence":"high"},"type":"software","title":"AprilNav: Indoor Real-time Landmark Navigation System","abstract":"AprilNav uses printable 2D fiduciary markers, a HD camera, and software running on a single board computer (SBC) to create a scalable, and accurate system for vehicular autonomous navigation and localization.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/AprilNav","license":null}},{"forgeId":"forge_nasa_mfs_33829_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-33829-1","sourceUrl":"https://software.nasa.gov/software/MFS-33829-1","confidence":"high"},"type":"software","title":"T0TEM - T0 Test Evaluation Module","abstract":"The T0TEM (T0 Test Evaluation Module) is an analysis software for transition temperature tests performed under ASTM E1921 - Standard Test Method for Determination of Reference Temperature, To, for Ferritic Steels in the Transition Range. T0 is the temperature at which a ferritic steel transitions from mostly ductile tearing to unstable cleavage failure mode. This software analyzes test results to determine T0, the master curve, confidence bounds, validity, margin adjustment and inhomogeneity by simple, bi-modal, and multi-modal methods. T0TEM also allows for batch analysis , raw data output and plot creation.","category":"materials_coatings","categoryRaw":"materials and processes","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_33888_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-33888-1","sourceUrl":"https://software.nasa.gov/software/MFS-33888-1","confidence":"high"},"type":"software","title":"Global Reference Atmospheric Model (GRAM) Suite","abstract":"The Global Reference Atmospheric Model (GRAM) Suite is an engineering-oriented atmospheric model that estimates mean values and statistical variations of atmospheric properties for planetary destinations. GRAM outputs include atmospheric density, temperature, pressure, winds, and chemical composition along a user-defined path. The GRAMs have been rearchitected from Fortran to a common object-oriented C++ framework. This new architecture creates a common GRAM library of data models and utilities. The GRAM ephemeris has been upgraded to the NASA Navigation and Ancillary Information Facility (NAIF) Spacecraft Planet Instrument C-matrix Events (SPICE) toolkit. The GRAM Suite also contains improved methodology that computes the ratio of specific heats in run-time for the current constituent combination, resulting in more accurate speed of sound calculations. The GRAM Suite consists of Earth-GRAM, Mars-GRAM, Venus-GRAM, Neptune-GRAM, Titan-GRAM, Uranus-GRAM and Jupiter-GRAM.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_33977_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-33977-1","sourceUrl":"https://software.nasa.gov/software/MFS-33977-1","confidence":"high"},"type":"software","title":"Field Campaign eXplorer (FCX)","abstract":"Field Campaign eXplorer (FCX) is a cloud native web based 3D data visualization platform that can incorporate science data collected from instruments onboard aircraft, ground sensors, and satellites. The instrument data are displayed within an interactive map viewer along flight tracks. This advanced tool reduces the effort involved in discovering data, is designed for event-based research, allows for seamless movement between data visualization , discovery and acquisition, and enhances the user experience by improving the usability of heterogeneous data.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://code.nasa.gov/?q=GHRC-FieldCampaign-eXplorer-UI","license":null}},{"forgeId":"forge_nasa_mfs_34033_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-34033-1","sourceUrl":"https://software.nasa.gov/software/MFS-34033-1","confidence":"high"},"type":"software","title":"Web-based Space Mission Visualization","abstract":"This software suite consists of demonstration web-apps for orbital trajectories around the Earth and planets around the Sun. Files include single page applications implemented in HyperText Markup Language (HTML), JavaScript, functional calls to 3D graphics code libraries including X3Dom and ThreeJS, supporting data files, and some documentation. One of the demonstration web-apps is model of the inner solar system model that uses JavaScript Object Notation (JSON) data file containing orbital parameters. Another demonstration web-app is the inner solar system and potentially hazardous asteroids. Tutorial examples include an Earth globe with orbital trajectories in JavaScript, R code for simulating an elliptical orbit, and converting orbital trajectory data from a fixed column table to JSON.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://nasa.github.io/mission-viz/","license":null}},{"forgeId":"forge_nasa_mfs_34056_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-34056-1","sourceUrl":"https://software.nasa.gov/software/MFS-34056-1","confidence":"high"},"type":"software","title":"Applied Learning Project","abstract":"The amount of Earth science datasets are increasing at a rapid pace. To manage the large volume of Earth science data , data driven approaches are critical technology. This software utilizes machine learning approaches to better search, discover, and utilize Earth science data from large archives.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-IMPACT/bps-imagery-radiation-classification;  https://github.com/NASA-IMPACT/bps-numerical","license":null}},{"forgeId":"forge_nasa_mfs_34076_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-34076-1","sourceUrl":"https://software.nasa.gov/software/MFS-34076-1","confidence":"high"},"type":"software","title":"Tree3D Dynamics Visualization Tool","abstract":"Tree3D is a 3D animation and visualization platform that converts trajectory simulation data into dynamic visual representations. The software supports multiple data formats and features built-in 3D geometries, 36+ celestial bodies, user-provided meshes, and specialized components like springs and exhaust plumes with time-varying visual properties. Key capabilities include vector displays for force/velocity analysis, multi-camera systems, integrated plotting and heads-up displays, and high-quality image/video recording. Applications include launch vehicle trajectory analysis, spacecraft separation visualization , clearance analysis, technical communication materials, and simulation debugging across aerospace, automotive, robotics, and engineering disciplines.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_34247_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-34247-1","sourceUrl":"https://software.nasa.gov/software/MFS-34247-1","confidence":"high"},"type":"software","title":"Bundle Restaging Daemon (BRD), a Delay Tolerant Network Marshall Enterprise (DTNME) Feature for Increased Protection against Bundle Overload","abstract":"Delay Tolerant Network Marshall Enterprise (DTNME) is a NASA supported software for payload operations to support reliable space communications. It is fully CCSDS compliant. This software is continuously updated with new technologies to further support and enhance its operational usage.The Bundle Restaging Daemon (BRD) is a new DTNME technology feature that allows operations to have better control over different data streams within a DTN system. Additionally, BRD provides safeguards to lessen the potential impact of any particular data stream against another.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_34306_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-34306-1","sourceUrl":"https://software.nasa.gov/software/MFS-34306-1","confidence":"high"},"type":"software","title":"Visualization Exploration and Data Analysis (VEDA)","abstract":"VEDA is an ecosystem of tools and services to address the need for open cyberinfrastructure for processing, analyzing, and visualizing Earth observation data.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/orgs/NASA-IMPACT/repositories?q=veda","license":null}},{"forgeId":"forge_nasa_mfs_34375_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-34375-1","sourceUrl":"https://software.nasa.gov/software/MFS-34375-1","confidence":"high"},"type":"software","title":"TASC CMOD and Force Test Data Pre-Processor","abstract":"This software imports load frame test records for crack mouth opening displacement mechanical tests and offers the user the ability toperform data processing operations and convert the data into a format readable by the Tool for Analysis of Surface Cracks (TASC - NASA Technology MFS-33082-1). The core operations performed by this data pre-processing tool are related to data clean-up to correct for extensometer slips and alignment of the data with the origin to ensure proper test evaluation within TASC.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_34433_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-34433-1","sourceUrl":"https://software.nasa.gov/software/MFS-34433-1","confidence":"high"},"type":"software","title":"Large Scale Data Transfer Study","abstract":"To facilitate petabyte scale data transfer between NASA and ESA, we have developed a framework for transferring 6 petabytes of data from ESA to NASA to support the Harmonized Landsat Sentinel-2 data products. With increases in collaboration between the agencies and increased data volumes, this framework is designed such that it can be applied for future data exchanges between the agencies.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-IMPACT/Blaze-Framework/tree/v1.0.0","license":null}},{"forgeId":"forge_nasa_mfs_34537_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-34537-1","sourceUrl":"https://software.nasa.gov/software/MFS-34537-1","confidence":"high"},"type":"software","title":"Sigma (WinPlot Statistical Calculator)","abstract":"Generates a WinPlot data file using Sun/WinPlot input data sources and text files which specify the data sets used for input and parameters to be processed. Output data includes a min, max, average and sigma value for each parameter throughout the time slice processed.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_34596_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-34596-1","sourceUrl":"https://software.nasa.gov/software/MFS-34596-1","confidence":"high"},"type":"software","title":"Simulation of the Four Bed CO2 Scrubber","abstract":"The Four Bed CO2 (FBCO2) scrubber simulator is a 1-D mathematical model containing partial differential equations representing mass, heat, and momentum balances within a sorbent bed loaded with zeolite or silica gel sorbent beads. The overall simulation is written in MATLAB, which calls the phenomenological simulation executed in COSMOL for each of the four sorbent beds. Data for each sorbent bed execution is retrieved from COMSOL within Matlab and stored in text files for access by the subsequent COMSOL sorbent bed simulation . The MATLAB code iterates the entire FBCO2 cycle until cyclic steady state conditions are achieved, then outputs plots of the relevent parameters, such as temperatures, partial pressures, and absolute pressures. For validation runs, the plots of simulation data are overlaid with experimental data for similar boundary and initial conditions.","category":"biomedical_health","categoryRaw":"crew and life support","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_34790_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-34790-1","sourceUrl":"https://software.nasa.gov/software/MFS-34790-1","confidence":"high"},"type":"software","title":"Dyreqt v2","abstract":"Dyreqt is developed to provide a general capability for synthesis of space transportation architectures in the pre-conceptual and conceptual phases of design . Rather than focusing on sizing, the primary aim of Dyreqt is enabling flexible synthesis of any arbitrary architecture element models that may be described within Dyreqts ontology. In doing this, Dyreqt enables the rapid exploration and optimization of architecture concepts subject to parametric requirements regardless of the high-/low-/mixed-/multi-fidelity nature of the models used.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_23586_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-23586-1","sourceUrl":"https://software.nasa.gov/software/MSC-23586-1","confidence":"high"},"type":"software","title":"Dynamic Onboard Ubiquitous Graphics (DOUG) Software Application","abstract":"DOUG is used to support simulation , training and planning for EVA and Robotic activities, including situational awareness and just-in-time training onboard ISS.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_24663_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-24663-1","sourceUrl":"https://software.nasa.gov/software/MSC-24663-1","confidence":"high"},"type":"software","title":"Engineering DOUG Graphics for Exploration (EDGE)","abstract":"EDGE is a real-time 3d graphics rendering package based on the Dynamic On-board Ubiquitous Graphics (DOUG) graphics engine. It combines key elements from graphics software tools developed for Space Shuttle and International Space Station (ISS) programs and adapts them for integration with other engineering simulations and facilities. The tool allows drop-in integration with the NASA Trick Simulation Environment and provides a fusion of 3D graphics and simulation outputs.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_24723_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-24723-1","sourceUrl":"https://software.nasa.gov/software/MSC-24723-1","confidence":"high"},"type":"software","title":"NASA Aircraft Management Information System (NAMIS)","abstract":"The NASA Aircraft Management Information System (NAMIS) is an enterprise resource planning/mission support software suite designed from the ground up to meet both the mission support requirements and the business management requirements of JSC's Aircraft Operations Division (AOD). The system features tools and processes that: 1) eliminate the risk of conducting flight operations in aircraft with overdue inspections, in aircraft with grounding discrepancies, and in aircraft not properly configured for the mission; 2) provide continuous and positive control of all assets including materials, parts, and equipment that exceed a customer-defined value; and 3) reduce material costs and labor hours. NAMIS includes the data, information, and metrics required to support flight operations management and business decisions, as well as the data required by other systems and external components to support consistent and accurate financial reporting and asset accounting.","category":"operations","categoryRaw":"business systems and project management","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_24760_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-24760-1","sourceUrl":"https://software.nasa.gov/software/MSC-24760-1","confidence":"high"},"type":"software","title":"GCR Event-Based Risk Model (GERMCode) Code","abstract":"The GERMCode provides scientists data interpretation of experiments; modeling of beam line, shielding of target samples and sample holders; and estimation of basic physical and biological outputs of their experiments.For mono-energetic ion beams, basic physical and biological properties are calculated for a selected ion type, such as kinetic energy, mass, charge number, absorbed dose, or fluence. Evaluated quantities are linear energy transfer (LET), range (R), absorption and fragmentation cross sections, and the probability of nuclear interactions after 1 or 5 cm of water equivalent material. In addition, a set of biophysical properties are evaluated, such as, the Poisson distribution for a specified cellular area, cell survival curves, and DNA damage yields per cell. Also, the GERM code calculates the radiation transport of the beam line for either a fixed number of user specified depths or at multiple positions along the Bragg curve of the particle in a selected material.","category":"biomedical_health","categoryRaw":"crew and life support","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_25352_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-25352-1","sourceUrl":"https://software.nasa.gov/software/MSC-25352-1","confidence":"high"},"type":"software","title":"NASA Space Radiation Cancer Risk (NSCR) Model 2012","abstract":"NASA Space Cancer Risk Model (NSCR-2012) is an integration of various components of the cancer risk projection model for assessment of radiation induced Cancer risks for humans in space. Exposure to the solar particle events (SPE) and galactic cosmic ray (GCR) present cancer risks to astronauts. The NASA Johnson Space Center Space Radiation Program (JSC-SRP) has developed the NASA Space Radiation Cancer Risk (NSCR) model to estimate cancer risks and overall uncertainties due to various factors that enter into risk estimates. NSCR utilizes the latest analysis of human radio-epidemiology for low linear energy transfer (LET) radiation and cancer and survival rates in the U.S. population and a population of never-smokers. NASA specific radiation quality factors based on particle track structure are defined. Models of space environments and radiation transport are used to determine organ exposures behind spacecraft shielding. NSCR makes projections for never-smokers which are shown to lead to reduced radiation cancer risk compared to others. NSCR uses Monte-Carlo propopagation of errors in various factors that enter into risk projections to determine overall uncertainties in radiation cancer projections. The NSCR Graphical User Interface (GUI) provides seamless integration of input and output manipulations, which are required for operations of the sub-modules: HZETRN, BRYNTRN, SUMSHIELD, and the Cancer probabilistic response models. The main applications envisioned are International Space Station (ISS) Missions, and planning for future exploration missions to the moon, Near Earth Objects (NEO) or Mars. Tissues specific probabilities for cancer incidence or death are evaluated for various criteria including: 1) adults at different ages of exposures, 2) males or females, and 3) population of never-smokers or the US average population. Probability distribution functions (PDFs) are used to describe factor uncertainties, and 95% confidence levels estimated.","category":"biomedical_health","categoryRaw":"crew and life support","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_25379_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-25379-1","sourceUrl":"https://software.nasa.gov/software/MSC-25379-1","confidence":"high"},"type":"software","title":"Failure Modes and Effects Analysis Tool (FMEA)","abstract":"The scope of this project is to develop a prototype failure analysis software tool. The tool models a system's components, their connective relationships, and functions in order to assist in Failure Modes and Effect analysis (FMEA) early in the design lifecycle.The purpose of the tool is to semi-automatically generate a model with functions and failure modes to support FMEA. This will be accomplished by:A graphical component-connection model is created by arranging and connecting components selected from the Master Equipment list.For each component, a pick-list user interface asks a few questions to narrow down potential failure modes. This uses a failure mode library in MS Excel based on standard failure modes and associated component functions and features.Pick-lists for types failure mode causes and immediate effects help the analyst complete initial draft FMEA worksheets, which link to the components in the model.The graphical model, which is marked with redundant components and paths, shows upstream/downstream dependencies, to help the analyst add further effects and criticality to the FMEA worksheets.This tool is innovative because it saves analysis time and provides a standardized and systematic approach in failure analysis , thereby enabling risk mitigation early in system design. There are also potential benefits of tool use during the operations phase to identify the cause(s) of a fault or failure.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_25380_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-25380-1","sourceUrl":"https://software.nasa.gov/software/MSC-25380-1","confidence":"high"},"type":"software","title":"ISS Systems Integration Lab (ISIL) Operations Framework (RIM 10)","abstract":"The Software Development and Integration Laboratory (SDIL) in Sonny Carter supports ISS Flight Software development, integration and verification. The complexity of the ISS requires efficient and reliable test reconfiguration, flexible resource scheduling, effective workflow and at the same time effective configuration management. An electronic workflow system was conceived, dubbed Rig Information Management (RIM). The SDIL was then transitioned from standalone, manual systems to the RIM system with database-centric, web-based solutions enabling significant efficiencies and paperless operations. It also created productivity improvements in flight software development and sustaining. This innovation has been recognized with a JSC 2007 Exceptional Software Award.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_25457_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-25457-1","sourceUrl":"https://software.nasa.gov/software/MSC-25457-1","confidence":"high"},"type":"software","title":"Orbital Debris Engineering Model (ORDEM), Version 3.2.0","abstract":"ORDEM offers flux as a function of debris size and year. The technology can be operated in spacecraft mode or telescope mode. An upgraded user interface uses project-oriented organization and provides graphical representations of numerous output data products.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_25505_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-25505-1","sourceUrl":"https://software.nasa.gov/software/MSC-25505-1","confidence":"high"},"type":"software","title":"Beyond Low-Earth Orbit (LEO) Architecture Sizing Tool (BLAST)","abstract":"A user-friendly, configurable spacecraft sizing tool, BLAST provides a shareable, re-creatable and rigorous end-to-end multi-element architecture framework that has been used to generate mass data for in-space, beyond low-Earth orbit (LEO) transportation vehicles and architectures. Offering a novel approach to modeling, BLAST couples extensive MER research with the ability to assess mission changes instantaneously by analyzing sensitivity sweeps of several parameters at once.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_25515_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-25515-1","sourceUrl":"https://software.nasa.gov/software/MSC-25515-1","confidence":"high"},"type":"software","title":"Shipping Foam Designer Software","abstract":"The Shipping Foam Designer Software is an easy-to-use design tool that allows the user to select the proper type and dimensions of shock-attenuating packing foam. A simple graphical user interface is provided. The software was developed in response to a large number of documented cases of critical hardware failures that resulted from drops during shipment.","category":"operations","categoryRaw":"business systems and project management","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_25599_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-25599-1","sourceUrl":"https://software.nasa.gov/software/MSC-25599-1","confidence":"high"},"type":"software","title":"Charring Ablator Response (CHAR) Code","abstract":"The CHarring Ablator Response (CHAR) Code is a 1D, 2D, and 3D ablation, thermal analysis and porous flow solver primarily used to predict the response of ablative thermal protection systems during atmospheric entry and ground testing. Using the finite-element method, it solves the governing partial differential equations for charring ablators in addition to being a general thermal analysis code. It solves both direct and inverse heat transfer and ablation problems. The software can be executed on serial and parallel computing platforms.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_25608_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-25608-1","sourceUrl":"https://software.nasa.gov/software/MSC-25608-1","confidence":"high"},"type":"software","title":"Information Sharing Protocol VCR (ISPVCR)","abstract":"The Information Sharing Protocol (ISP) VCR (ISPVCR) is a software program written in Tcl/Tk that provides a capability to record and playback ISP data via a Source Independent Telemetry Format (SITF) files. The ISPVCR provides a Graphical User Interface (GUI) that allows for start/stop of the crcording capability, specify output file names and start/stop of the playback of the SITF data file.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_25665_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-25665-1","sourceUrl":"https://software.nasa.gov/software/MSC-25665-1","confidence":"high"},"type":"software","title":"Trick 13 Simulation Environment","abstract":"The Trick Simulation environment is a generic simulation toolkit used for constructing and running simulations. The Trick 13 Interface Code Generator (ICG), a utility that provides math model class and structure layout data, has been rewritten and is based off of the open source clang/llvm project. The Trick numerical integrators have been replaced with a common set of integrators. Several core components are enhanced from previous Trick versions. Trick 13 is now Open Source software and can be downloaded at http://code.nasa.gov/#/","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://code.nasa.gov/#/","license":null}},{"forgeId":"forge_nasa_msc_25694_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-25694-1","sourceUrl":"https://software.nasa.gov/software/MSC-25694-1","confidence":"high"},"type":"software","title":"NASA HMS (Hazard Management System)","abstract":"The Web-based, access-controlled NASA Hazard Management System (HMS) provides a centralized repository for hazards regardless of origin and offers the ability to report and manage real-time hazards and controls. The primary mechanism for identifying and documenting hazardous conditions within HMS lies in the creation and management of two types of analysis documents: Hazard Analyses (HAs) and Job Hazard Analyses (JHAs). While these two document types offer different approaches for hazard identification and classification, they both offer controls for mitigating hazards. HMS provides a framework within which HA and JHA documents are created, reviewed, and approved. Once approved, the hazardous conditions identified within a document are considered active. More important, the controls associated with the hazards are then also considered active. HMS includes the mechanisms required to evaluate hazards using standard Risk Assessment Code (RAC) scoring.","category":"operations","categoryRaw":"business systems and project management","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_25732_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-25732-1","sourceUrl":"https://software.nasa.gov/software/MSC-25732-1","confidence":"high"},"type":"software","title":"MBJEOD: An Integrated Multibody and Orbital Dynamics Simulation Module","abstract":"MBJEOD is a multi-body dynamics (MBDyn) software interface layer that allows transfer of forces between muti-body articulating objects and the JEOD orbital dynamics package.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_25937_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-25937-1","sourceUrl":"https://software.nasa.gov/software/MSC-25937-1","confidence":"high"},"type":"software","title":"RITRACKS: A software for simulation of stochastic radiation track structure, micro- and nano-dosimetry, radiation chemistry and DNA damage by heavy ions","abstract":"The code RITRACKS (Relativistic Ion Tracks) has been developed over the last years at the NASA Johnson Space Center to simulate the effects of ionizing radiations at the microscopic scale and to understand the effects of space radiation at the biological level. The fundamental part of this code is the stochastic simulation of radiation track structure of heavy ions, an important component of space radiations. The code can calculate many relevant quantities such as the radial dose, voxel dose, and may also be used to calculate the dose in spherical and cylindrical targets of various sizes. Recently, we have incorporated DNA structure and damage simulations at the molecular scale in RITRACKS. The direct effect of radiations is simulated by introducing a slight modification of the existing particle transport algorithms, using the Binary-Encounter-Bethe model of ionization cross sections for each molecular orbitals of DNA. The simulation of radiation chemistry is done by a step-by-step diffusion-reaction program based on the Greens functions of the diffusion equation. This approach is also used to simulate the indirect effect of ionizing radiation on DNA. The software can be installed independently on PC and tablets using the Windows operating system and does not require any coding from the user. It includes a Graphic User Interface (GUI) and a 3D OpenGL visualization interface. The calculations are executed simultaneously (in parallel) on multiple CPUs.","category":"biomedical_health","categoryRaw":"crew and life support","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_26032_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-26032-1","sourceUrl":"https://software.nasa.gov/software/MSC-26032-1","confidence":"high"},"type":"software","title":"Fine Motor Skills (FMS) Software Application","abstract":"The Fine Motor Skills (FMS) software test battery is designed to collect data from multiple tasks that are indicative of fine motor performance. It was developed to evaluate the effect of microgravity on the sensorimotor system during 6 month and 1 year missions on the International Space Station (ISS). The application runs on an iOS platform, and is intended for use on an iPad. The data recorded on the iPad can be sent to a server or retrieved from iTunes directly from the device. The FMS app can be accessed at the Apple app store, with more details and instructions available at: https://www.nasa.gov/content/spaceflight-human-factors","category":"biomedical_health","categoryRaw":"crew and life support","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://itunes.apple.com/us/app/fine-motor-skills-fms/id1453045999","license":null}},{"forgeId":"forge_nasa_msc_26214_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-26214-1","sourceUrl":"https://software.nasa.gov/software/MSC-26214-1","confidence":"high"},"type":"software","title":"Space Station Research Explorer (SSRE) v 5.0","abstract":"The Space Station Research Explorer provides current information on ISS experiments, facilities and research results. The Space Station Research Explorer consists of five different sections: Experiments, Facilities, Benefits, Interactive Media, and Links. The Experiments section provides access to the six main experiment categories and their subcategories. Experiments are depicted as dots within the category system and the stems connecting the dots to the system depict the length of time the experiment has been on orbit. Users can explore further by selecting a category which reveals the subcategories. They can then select a category and explore individual experiments. Experiment descriptions consist of in depth information, links, images, and publications if available. The Experiments section can be furthered narrowed by selecting a specific expedition and sponsor by using the dials at the top right of the screen. The experiments can also be searched for keywords using the search option. The Facilities section provides an interior view of three of the station modules; Columbus, Kibo, and Destiny. Once the module is selected, the interior image can be navigated by dragging up and down to see different sides of the module and left and right to view any racks not shown on the screen. Tapping a rack gives a brief description of the rack and an experiment description if available. The facilities section also contains exterior views of external platforms. Selecting the platform shows the experiments being run on the platforms and associated data.The Benefits section provides information on Human Health, Earth Benefits and Global education. Selecting a section allows the benefits to be investigated further. The Media section provides access to three tabs: Podcasts, Games, and Videos. The Games section contains a game that introduces players to the differences in gravity when tossing a ball. Podcasts contains links to NASA ScienceCasts and Videos contains links to Science related videos.The last section contains links to other Space station research sites and NASA applications.No Software Usage Agreement is needed to complete. Please go to the iTunes Store or Google Store.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://itunes.apple.com/us/app/space-station-research-xplorer/id934070569?mt=8","license":null}},{"forgeId":"forge_nasa_msc_26281_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-26281-1","sourceUrl":"https://software.nasa.gov/software/MSC-26281-1","confidence":"high"},"type":"software","title":"TaskForce: A Software Task Design and Execution Framework","abstract":"The mission of TaskForce is to provide a rapid prototyping framework for a component-based programming model. Users of the framework will develop processing elements (called Tasks) in Python. These Tasks can then be composed together with other Tasks to form Blocks. Each Block can have not only Tasks, but other Blocks as well. Using this composition pattern allows a developer to create a hierarchical application structured from these re-usable elements. Tasks and Blocks can be connected together and pass Events. In this fashion, a series of Tasks could be \"chained\" together to execute in serial fashion, or even create a more complex web of interaction.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://gitlab.com/nasa-jsc-robotics/tf/taskforce.git","license":null}},{"forgeId":"forge_nasa_msc_26323_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-26323-1","sourceUrl":"https://software.nasa.gov/software/MSC-26323-1","confidence":"high"},"type":"software","title":"CFS-101 Training","abstract":"This is a training tool for individuals to learn how to develop software with NASA-developed Core Flight software (CFS) framework. No agreement is necessary through this catalog. Software is available at open source site.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/CFS-101","license":null}},{"forgeId":"forge_nasa_msc_26402_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-26402-1","sourceUrl":"https://software.nasa.gov/software/MSC-26402-1","confidence":"high"},"type":"software","title":"Software Toolkit for Engineering and Aeroscience Models","abstract":"The Software Toolkit for Engineering and Aeroscience Models (STEAM) enables rapid development and deployment of integrated databases for analysis products. It is written in Python and C++ to provide an API to database and tool developers. The software depends on several open source libraries. It can read and write common file formats used for computational fluid dynamics and aeroscience analysis . No geometry or solution data is included in STEAM. Products created using STEAM can combine tabulated data, surface maps of dependent quantities, and engineering models. STEAM can perform geometric manipulation and spatial interpolation using unstructured meshes and flight space interpolation to relevant design conditions. Data manipulation can be performed during flight space interpolation. STEAM facilities the creation of databases and bespoke tools to interpret them.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/steam","license":null}},{"forgeId":"forge_nasa_msc_26456_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-26456-1","sourceUrl":"https://software.nasa.gov/software/MSC-26456-1","confidence":"high"},"type":"software","title":"Orion Optical Navigation Image Processing Software (OpNAV)","abstract":"The Orion emergency return system utilizing optical navigation has matured in design over the last several years, and is currently undergoing the final implementation and test phase in preparation for Exploration Mission 1 (EM-1) in 2019. A key component is this software, which processes the images and produces navigation measurements. The software development is being worked as a Government Furnished Equipment (GFE) project delivered as an application within the Core Flight Software of the Orion camera controller module.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_26476_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-26476-1","sourceUrl":"https://software.nasa.gov/software/MSC-26476-1","confidence":"high"},"type":"software","title":"dcapp - Displays and Controls Application","abstract":"dcapp is a displays and controls software package designed for UNIX platforms, specifically MacOS and Linux. It is built upon standard UNIX technologies like OpenGL for graphics, libxml2 for input file parsing, and FreeType2 for font handling. For window management and event handling, it uses Cocoa on MacOS machines and X11 for Linux-based machines. It has built-in communication libraries to communicate with external Trick-based simulations (via trick_comm) and EDGE graphics (via EDGEs remote commanding server (RCS)).dcapp provides a simple interface for building and running displays and controls on a desktop or laptop computer. It processes user inputs, typically mouse clicks and keyboard entries, and renders displays to the computer screen based upon the data fed to it.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_26621_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-26621-1","sourceUrl":"https://software.nasa.gov/software/MSC-26621-1","confidence":"high"},"type":"software","title":"Koviz - A Simulation Data Analysis, Visualization And Mining Tool","abstract":"Koviz is a simulation data visualization tool designed for analyzing Trick simulation data - specialized for handling large monte carlo data sets and doing real-time analyses of Trick simulations.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/koviz","license":null}},{"forgeId":"forge_nasa_msc_26673_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-26673-1","sourceUrl":"https://software.nasa.gov/software/MSC-26673-1","confidence":"high"},"type":"software","title":"Copernicus Trajectory Design and Optimization System (Version 5.x)","abstract":"The 5.4 release of the Copernicus spacecraft trajectory design and optimization program is a significant update and includes numerous new features, enhancements, and bug fixes, including:This is the first release with native support for Macs with Apple Silicon processors. The old x86_64 Mac version is now end-of-life.New altitude and eclipse ramping/buffer engine model options.New propagation model to simulate a finite burn segment with a series of Kepler arcs & impulses.New circular restricted three-body problem (CR3BP) parameterization and propagation mode.New shadowing/eclipse model upgrades.New two-body rotating frame definition options.Many new GUI enhancements, usability upgrades, improvements, etc.Many enhancements and upgrades to the Copernicus Python API.Bug fixes.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_26718_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-26718-1","sourceUrl":"https://software.nasa.gov/software/MSC-26718-1","confidence":"high"},"type":"software","title":"TrickHLA: An IEEE 1516 High Level Architecture (HLA) Simulation Interoperability Standard Implementation for Trick Base Simulations","abstract":"The Trick High Level Architecture (TrickHLA) software supports IEEE-1516: High Level Architecture (HLA) based simulation interoperability with Trick based simulations. The TrickHLA software abstracts away the details of using the HLA, allowing the user to concentrate on the simulation and not worry about having to be an HLA and/or distributed simulation expert. The TrickHLA software is data driven and provides a simple Application Programming Interface (API) making it relatively easy to take an existing Trick simulation and make it HLA aware (i.e. a distributed simulation ).This new version of TrickHLA has been rewritten and rearchitected to support the current IEEE-1516.2010 HLA and Space Reference Federation Object Model (Space FOM) standards. In the process, the size and complexity of the code base has been significantly reduced. The code base was also refactored to support new version of the Trick simulation development environment that better support object oriented programming constructs. The new code architecture also provides for better extensibility of the principal API classes to support future initialization schemes.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/TrickHLA","license":null}},{"forgeId":"forge_nasa_msc_26727_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-26727-1","sourceUrl":"https://software.nasa.gov/software/MSC-26727-1","confidence":"high"},"type":"software","title":"General-Use Nodal Network Solver (GUNNS), Version 19.X","abstract":"GUNNS combines standard nodal circuit analysis algorithms with the hydraulic-thermal-electric analogy to allow modeling of flow circuits (fluid, thermal, electrical) with a concise set of generic code. Circuits are drawn up with a Draw.io drawing, from which run-time C++ code is auto-generated that can be built into sims. The GUNNS software includes custom Draw.io shapes for generic physical components like pumps, valves, resistors, & capacitors. These can be connected to each other in the drawing and configured with their characteristic values.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/gunns/wiki/Release_Notes#v193","license":null}},{"forgeId":"forge_nasa_msc_26735_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-26735-1","sourceUrl":"https://software.nasa.gov/software/MSC-26735-1","confidence":"high"},"type":"software","title":"COTS Camera and Computer-Based Star Tracker (CBST)","abstract":"The COTS camera and computer-based star tracker (CBST) software package is a collection of algorithms that take pictures of stars and then output the inertial attitude of the camera. The algorithms' have demonstrated accuracy better than 0.25 degrees when processing imagery taken on-orbit. The algorithms have been developed to be easily and rapidly deployed on a variety of common low-cost and SWaP single board computers and used with COTS cameras. This enables high quality attitude information to be gathered from small, low-cost components that already exist on many spacecraft, which can improve navigation performance and/or redundancy for minimal additional cost and lead time.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/COTS-Star-Tracker","license":null}},{"forgeId":"forge_nasa_msc_26821_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-26821-1","sourceUrl":"https://software.nasa.gov/software/MSC-26821-1","confidence":"high"},"type":"software","title":"To the Moon and Beyond, an educational game teaching how International Space Station research is helping us on Earth and getting us to the Moon and beyond","abstract":"The International Space Station is a state-of-the-art microgravity laboratory that is unlocking discoveries not possible on Earth, and is helping us push farther into deep space. Microgravity turns almost everything we know upside down. Liquids behave completely differently, fire burns in new ways. Biological systems reveal surprises. Were learning how human bodies react to life in space, and how to keep crew members safe and strong on long-duration exploration missions. The station enables us to develop new ways to grow food in microgravity and test technologies that could hold the key to better, safer space travel. Microgravity is allowing us to find new ways to combat disease back on Earth. Our research is contributing to medical and social benefits on our home planet, as well as stimulating a growing space economy. The vantage point of 240 miles up gives us spectacular opportunities for studying our planet. Were inspiring future generations from a platform that is one of the largest international collaborations of our time.This is your space program. You determine what research to fund on the ISS and what projects you want to fund back on Earth. Conducting research on the ISS can reduce the cost of some projects or give you the ability to do others. Results from the projects you fund determine you budget for the next year. Everything you do affects the outcome of your eight part program. But beware, events can happen that can influence that outcome. Will you be able to complete all of your eight mission objectives in four short years?","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://apps.apple.com/us/app/to-the-moon-and-beyond/id1514784612","license":null}},{"forgeId":"forge_nasa_msc_26835_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-26835-1","sourceUrl":"https://software.nasa.gov/software/MSC-26835-1","confidence":"high"},"type":"software","title":"Badhwar-O'Neill 2020 Galactic Cosmic Ray Model (BON2020) v2.3","abstract":"The BadhwarO'Neill (BON) model has been used for some time to describe the galactic cosmic ray (GCR) environment encountered in deep space by astronauts and sensitive electronics. This package contains the BON2020 model. The previous version of the model, BON2014, was calibrated to available measurements to reduce model errors for particles and energies of significance to astronaut exposure. Although subsequent studies showed the model to be reasonably accurate for such applications, modifications to the sunspot number (SSN) classification system and a large number of new highprecision measurements suggested the need to develop an improved and more capable model. The new BON2020 model relies on daily integral flux from the Advanced Composition Explorer Cosmic Ray Isotope Spectrometer (ACE/CRIS) to describe solar activity. For time periods not covered by ACE/CRIS, the updated international SSN database is used. Parameters in the new model are calibrated to available data , which include the new Alpha Magnetic Spectrometer (AMS02) and Payload for Antimatter Matter Exploration and Lightnuclei Astrophysics (PAMELA) highprecision measurements. It is found that the BON2020 model is a significant improvement over BON2014. Systematic bias associated with BON2014 has been removed. The average relative error of the BON2020 model compared to all available measurements is found to be <1%, and BON2020 is found to be within 15% of a large fraction of the available measurements (26,269 of 27,646 95%).","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_26872_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-26872-1","sourceUrl":"https://software.nasa.gov/software/MSC-26872-1","confidence":"high"},"type":"software","title":"Modified OpenSim Rajagopal Full Body Model","abstract":"This modified human skeletal model, for use with the open-source biomechanics software, OpenSim, enables enhanced representation of data collected from human test subjects performing upper body tasks and aids simulation in spaceflight project areas such as exercise system development.","category":"biomedical_health","categoryRaw":"crew and life support","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://simtk.org/projects/das_full_body","license":null}},{"forgeId":"forge_nasa_msc_26882_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-26882-1","sourceUrl":"https://software.nasa.gov/software/MSC-26882-1","confidence":"high"},"type":"software","title":"NASA COVID-19 Contact Tracing and Tracking (CTT) Application","abstract":"The NASA Office of the Chief Health and Medical Officer and the Office of the Chief Information Officer have developed a contact tracing application to help control the spread of Coronavirus (COVID-19). NASA Contact Tracing is used to identify employees who may have been in contact with a COVID-19 case at a NASA installation. Trained NASA Clinic employees interview the index case to trace back who they may have had recent contact with while at work. Subsequently, people who may have been exposed are contacted, interviewed about their symptomatic status, and encouraged to self-quarantine to prevent further spread. Of those contacts tested, if there is a new confirmed case of the virus, the process of contact tracing continues. Based on the recommendations established by the Presidents Guidelines for Opening Up America Again, and for the protection of NASA employees and mission, NASA clinics are using this central tracking tool to manage contact tracin","category":"operations","categoryRaw":"business systems and project management","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":"https://github.com/nasa/CTT","license":null}},{"forgeId":"forge_nasa_msc_26984_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-26984-1","sourceUrl":"https://software.nasa.gov/software/MSC-26984-1","confidence":"high"},"type":"software","title":"Single Board Computer System Monitoring Software for Radiation Testing","abstract":"This software package uses simple Python scripts to assess computer performance. This is specifically intended to be used on Single Board Computers for monitoring system parameters during radiation testing. This is hoped to provide a powerful, flexible framework that can be rapidly deployed on a variety of systems (Windows/Linux, Intel/ARM) and can serve as a common community benchmark for a radiation testing Single Board Computers.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/System_Monitor_for_Radiation_Testing","license":null}},{"forgeId":"forge_nasa_msc_27059_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-27059-1","sourceUrl":"https://software.nasa.gov/software/MSC-27059-1","confidence":"high"},"type":"software","title":"Astromaterials 3D Website and Explorer Application","abstract":"This is the first virtual library of NASAs collections of Apollo Lunar and Antarctic meteorite samples. This web-based custom visualization tool presents each extraterrestrial rock in a visually stunning.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://ares.jsc.nasa.gov/astromaterials3d/","license":null}},{"forgeId":"forge_nasa_msc_27061_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-27061-1","sourceUrl":"https://software.nasa.gov/software/MSC-27061-1","confidence":"high"},"type":"software","title":"Genesis Flight Mechanics Simulation and Trajectory Design Tool v0.4.1","abstract":"Genesis is a generic, multi-vehicle, variable-degree-of-freedom flight mechanics simulation for trajectory design. It is capable of modeling ascent, aerocapture, entry, descent, and landing trajectories around a single planetary body. It is designed to be flexible and easily reconfigured for new vehicles. Genesis provides generic models for atmospheric properties, winds, aerodynamics, and propulsion. It can easily be extended with new environment, vehicle, or flight software models. Genesis can be used for a wide variety of analyses, ranging from optimizing a single trajectory to running a large Monte Carlo analysis in a High-Performance Computing (HPC) environment. It consolidates and replaces a suite of legacy flight mechanics simulations. It is implemented in the Julia programming language.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_27108_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-27108-1","sourceUrl":"https://software.nasa.gov/software/MSC-27108-1","confidence":"high"},"type":"software","title":"Seeker 1 Simulation","abstract":"The Seeker 1 Simulation is a Trick-based, high-fidelity, 6 DoF simulation that models a 3U CubeSat, including sensors and effectors, and a target spacecraft for inspection.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_27334_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-27334-1","sourceUrl":"https://software.nasa.gov/software/MSC-27334-1","confidence":"high"},"type":"software","title":"Advanced Graphics for Engineering Analysis (AGEA) version 5.7.3","abstract":"AGEA is a three-dimensional visualization and analysis application that provides modeling and animation tools for real-time and pre-rendered simulations. It is a front-end application that relies on a collection of functions known as the IGOAL Graphics Library (IGL).","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_27335_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-27335-1","sourceUrl":"https://software.nasa.gov/software/MSC-27335-1","confidence":"high"},"type":"software","title":"Manipulator Analysis \u2013 Graphic, Interactive, Kinematic (MAGIK) Robotic Simulation Version 8.1","abstract":"MAGIK is a robotic simulation used primarily to conduct interactive kinematic analysis of International Space Station robotic operations. MAGIK can be used to model, specify, simulate, analyze, and modify n-jointed manipulators using built-in control algorithms while displaying interactive, high-fidelity 3-dimensional graphic scenes of the robotic system and its environment. The graphics are provided by the companion package Advanced Graphics for Engineering Analysis (AGEA) also developed at JSC.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_27338_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-27338-1","sourceUrl":"https://software.nasa.gov/software/MSC-27338-1","confidence":"high"},"type":"software","title":"CODA: Collaborative Operations Data Activation","abstract":"CODA allows replay of every moment of missions, training, and testing by pulling data from existing sources such as video, audio and imagery servers, GPS position, and timestamped text databases and displays them in context with each other. Consolidate the context of missions, training, and testing into an easy to use platform to relive and revisit each moment. CODA aims to aggregate data records ranging from video, audio, telemetry, still imagery, anomaly reporting, and more. Heavily inspired by Apollo in Real Time (https://apolloinrealtime.org/), which was created by the primary CODA developer, Ben Feist.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/coda","license":null}},{"forgeId":"forge_nasa_msc_27522_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-27522-1","sourceUrl":"https://software.nasa.gov/software/MSC-27522-1","confidence":"high"},"type":"software","title":"Digital Lunar Exploration Sites Unreal Simulation Tool (DUST) Products","abstract":"The Digital Lunar Exploration Sites Unreal Simulation Tool (DUST) is a 3D visualization application of the Lunar South Pole. The DLES terrain is generated from LRO digital elevation model data, SPICE kernel ephemerides, synthetic surface textures, and representative crater and rock distributions. Its intended use is for early mission traverse and lunar landing simulation capability assessments for HLS, EHP, M2M, and SAO. This 3D visualization tool can be used as an early reference to enable candidate vendors to perform initial studies of the lunar terrain and lighting conditions. DUST uses Digital Elevation Model (DEM) data from Goddards PGDA website (https://pgda.gsfc.nasa.gov/products/view/66) as its lunar heightmap data source. Additional lunar surface characteristics can be found in ACD-50044, Lunar Surface Data Book.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_msc_27639_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-27639-1","sourceUrl":"https://software.nasa.gov/software/MSC-27639-1","confidence":"high"},"type":"software","title":"Surface Robotics Mockups Description","abstract":"This NTR is a software package containing the descriptions and simulation files for mock-ups for testing robotic capabilities for future lunar missions. The mock-ups include a 'task trainer' (the interior), a 40in-by-40in hatch, and a 40in-by-60in hatch for a pressurized rover.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-JSC-Robotics","license":null}},{"forgeId":"forge_nasa_msc_27640_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-27640-1","sourceUrl":"https://software.nasa.gov/software/MSC-27640-1","confidence":"high"},"type":"software","title":"MERLIN Freezer Description","abstract":"This is a software package containing the assembly, geometry, description, and simulation files for an ISS freezer mock-up for testing robotic capabilities for future Gateway and lunar missions. The mock-up is a MERLIN style freezer, including a high-fidelity latch and a sealing ring.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-JSC-Robotics","license":null}},{"forgeId":"forge_nasa_msc_27692_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-27692-1","sourceUrl":"https://software.nasa.gov/software/MSC-27692-1","confidence":"high"},"type":"software","title":"iMETRO Robot Operating System Packages","abstract":"This NTR is a set of software packages to integrate COTS hardware systems with Robot Operating System (ROS) software packages. These interfaces will allow the study and adaptation of terrestrial robotics technologies and the development of new technologies for non-terrestrial robotics . These systems include a horizontal rail, vertical lift, collaborative robotic arms, robotic grippers, sensors, and mounting hardware.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-JSC-Robotics/iMETRO","license":null}},{"forgeId":"forge_nasa_msc_27730_1","source":{"institution":"NASA","subUnit":"Johnson Space Center","subUnitCode":"JSC","nativeId":"MSC-27730-1","sourceUrl":"https://software.nasa.gov/software/MSC-27730-1","confidence":"high"},"type":"software","title":"TrickCFS v3.1","abstract":"TrickCFS is a software package that provides the C structs, C++ classes and pertinent code required to synchronize a core Flight System (cFS) mission with the Trick simulation executive. Time is modeled by the simulation and the Trick Memory Manager provides a method to peek, poke, and data record cFS application data without modifying any FSW code.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_20999_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-20999-1","sourceUrl":"https://software.nasa.gov/software/NPO-20999-1","confidence":"high"},"type":"software","title":"MISR GEOMETRIC CALIBRATION SOFTWARE","abstract":"This software is part of NASA's Earth Science Enterprise (Code Y). MISR is part of the EOS Terra mission. Terra is one of several EOS missions. EOS is the centerpiece of Code Y work. A more thorough description of this software can be found in the MISR Science Data Processing Functional Design Document (D-12941A) which is available at http://www-misr.jpl.nasa.gov/project/links/fdd.pdf","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/Cartography-jpl/geocal and https://github.com/Cartography-jpl/pynitf","license":null}},{"forgeId":"forge_nasa_npo_21220_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-21220-1","sourceUrl":"https://software.nasa.gov/software/NPO-21220-1","confidence":"high"},"type":"software","title":"Autonomous Landing Hazard-Avoidance Technology (ALHAT) Scanning Lidar-Based Simulation for Mars Landing","abstract":"The ALHAT simulation tool provides an efficient software model and a set of algorithms in C code for performing scanning lidar-based hazard detection and avoidance.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_30596_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-30596-1","sourceUrl":"https://software.nasa.gov/software/NPO-30596-1","confidence":"high"},"type":"software","title":"GPS Occultation Analysis System (GOAS)","abstract":"GOAS processes atmospheric and ionospheric occultation data obtained from low-Earth-orbiting global positioning systems transmission receivers. The technology obtains input from a variety of receiver types and satellites and outputs full atmospheric and ionospheric retrievals.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_30722_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-30722-1","sourceUrl":"https://software.nasa.gov/software/NPO-30722-1","confidence":"high"},"type":"software","title":"ROAMS Rover Analysis and Modeling Software","abstract":"ROAMS is a planetary rover simulation software package. The technology consists of mechanical models of a rover, instrument arms, actuators and sensors, power resources, terrain interactions, and onboard software.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_41133_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-41133-1","sourceUrl":"https://software.nasa.gov/software/NPO-41133-1","confidence":"high"},"type":"software","title":"Rock Identification Toolkit (RockIT)","abstract":"RockIT is an interactive tool used by mission scientists to identify and characterize rocks and rock distributions.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_41312_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-41312-1","sourceUrl":"https://software.nasa.gov/software/NPO-41312-1","confidence":"high"},"type":"software","title":"Automated Camera Calibration Software (ACCS)","abstract":"Using collected metrology data , the ACCS system significantly increases the efficiency of the entire camera calibration process, resulting in reduced costs and turnaround time. Even in extreme conditions, the tool performs calibrations with minimal user input.","category":"operations","categoryRaw":"system testing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_41647_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-41647-1","sourceUrl":"https://software.nasa.gov/software/NPO-41647-1","confidence":"high"},"type":"software","title":"Small Body Navigation and Topography (SBN&T)","abstract":"SBN&T provides an integrated program for the spacecraft navigation and determination of small-body dynamics, shape, and high-resolution topography. Multiple-image stereography and photoclinometry are used to construct high-resolution topographic and albedo maps centers treated as control points. These landmark maps are re-illuminated and correlated with images to act as body-fixed navigation tie-points.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_41986_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-41986-1","sourceUrl":"https://software.nasa.gov/software/NPO-41986-1","confidence":"high"},"type":"software","title":"Automated Planning and Scheduling Environment (ASPEN)","abstract":"ASPEN automates space mission planning and other tasks that involve the reasoning of time, states, resources, and actions.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_42082_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-42082-1","sourceUrl":"https://software.nasa.gov/software/NPO-42082-1","confidence":"high"},"type":"software","title":"PixelLearn","abstract":"PixelLearn is a tool for classifying the pixels in scientific image data sets. Based on one or more images on the same grid, the tool uses cutting-edge clustering algorithms to automatically find structures in the image, or to label individual classes and use supervised classification methods to extend the labels to the rest of the image.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_43129_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-43129-1","sourceUrl":"https://software.nasa.gov/software/NPO-43129-1","confidence":"high"},"type":"software","title":"Spectral Analysis Tool (SAT), Version 6.2","abstract":"The SAT computer program calculates signal spectra, bandwidths, and interference effects for several families of modulation schemes found commonly in radio, satellites, and space communications. It is primarily used for spectrum management purposes to examine the effects of radio frequency interference on a satellite communication system.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_43504_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-43504-1","sourceUrl":"https://software.nasa.gov/software/NPO-43504-1","confidence":"high"},"type":"software","title":"Ionospheric Slant TEC Analysis Using GPS-Based Estimation (IonoSTAGE)","abstract":"The Ionospheric Slant TEC Analysis using GNSS-based Estimation (IonoSTAGE) software package is a Matlab platform for performing analysis and visualization of ionospheric slant total electron content (TEC) using measurements of global navigation satellite systems (GNSS).","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_43625_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-43625-1","sourceUrl":"https://software.nasa.gov/software/NPO-43625-1","confidence":"high"},"type":"software","title":"Mission Analysis Low-Thrust Optimizer (MALTO)","abstract":"MALTO is a software tool for preliminary design and optimization of low-thrust interplanetary trajectories. The tool is easy to use, has robust convergence, and can handle many intermediate encounters.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_43666_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-43666-1","sourceUrl":"https://software.nasa.gov/software/NPO-43666-1","confidence":"high"},"type":"software","title":"Mystic Low-Thrust Trajectory Design and Visualization Software","abstract":"Mystic provides very high-fidelity optimization of low-thrust spacecraft trajectories for mission design. The software can be used for general body-centered trajectories, interplanetary trajectories, and trajectories that combine body-centered and interplanetary trajectory legs. Mystic will also provide navigational/operational support for low-thrust spacecraft.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_44194_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-44194-1","sourceUrl":"https://software.nasa.gov/software/NPO-44194-1","confidence":"high"},"type":"software","title":"Gas Fitting Spectral Analysis software","abstract":"Software will be used by foreign collaborators on the OCO project. They will use it for quality control of their ground-based infrared spectra that will be used for the validation OCO.A suite of FORTRAN 77 programs has been developed to analyze solar absorption spectra and thereby determine the conventrations of various gases in the Earth's atmosphere.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/TCCON/GGG","license":null}},{"forgeId":"forge_nasa_npo_45030_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-45030-1","sourceUrl":"https://software.nasa.gov/software/NPO-45030-1","confidence":"high"},"type":"software","title":"MACOS Program Release, Version 3.31","abstract":"The Modeling and Analysis of Controlled Optical System (MAOOS) Program is a JPL developed major optical systems modeling and analysis software tool pacakge. It enables a wide range of system-level engineering modeling and analysis for large aperture, segmented space telescope systems including the James Webb Space Telescope (JWST), TPF, AMT, AMD, as well as advanced space interferometry systems (SIM). MACOS Version 3.31 are: a powerful system optimization facility with a set of optimization algorithms implemented for linear and nonlinear, unconstrained and constrained optical system optimizations under a variety of settings, enhanced ability to perturb optical system components individually and on subsystem level, a variety of new optical aperture types have been added, the ability to add multi-layer thin-film coatings to element surfaces in polarized ray-tracing. Major software engineering work were also performed on the MACOS program to make it more reliable, flexible and more manageable from the maintenance and development point of view.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/nasa-jpl/macos","license":null}},{"forgeId":"forge_nasa_npo_45213_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-45213-1","sourceUrl":"https://software.nasa.gov/software/NPO-45213-1","confidence":"high"},"type":"software","title":"STAMiNA","abstract":"Utilizing STAMiNA, a simulation tool for the Advanced Sensors Collaborative Technology Alliance Microsensor Network Architecture, users can define: (1) mission environment, including terrain features; (2) a sensed object set, including multiple threat objects; (3) sensor placements, their modalities, and their abilities to sense different object types; (4) threat object trajectories; (5) sensing and sensed data dissemination for information fusion; and (6) various network configurations and formations between sensors to examine the coupling of sensing and communication. With these features, STAMiNA provides an overall system-level performance of different sensor network architectures under different parametric conditions.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_45418_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-45418-1","sourceUrl":"https://software.nasa.gov/software/NPO-45418-1","confidence":"high"},"type":"software","title":"Planetary Observer Planning Software (POPS)","abstract":"The POPS application suite performs mission design analysis of a spacecraft orbiting a terrestrial planet. POPS is not intended for the study of hyperbolic or interplanetary orbits, although some limited hyperbolic capabilities exist.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_45423_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-45423-1","sourceUrl":"https://software.nasa.gov/software/NPO-45423-1","confidence":"high"},"type":"software","title":"Deep Space Network (DSN) config converter","abstract":"This tool is used in opperations by the MRO and Phoenix missions. The tool provides both time savings and risk reduction in the periodic updating of the dsn_config modeling adaptation. The dsn config converter tool is used for converting the dsn_config.cvs file into a multi- mission AAF file for use by the multi-mssion autogen/apgen sequence generation tool.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_45583_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-45583-1","sourceUrl":"https://software.nasa.gov/software/NPO-45583-1","confidence":"high"},"type":"software","title":"Autonomous Data Reduction for NASA Earth Science Data","abstract":"NASA atmospheric and Earth science missions generate vast amounts of data every day. Clustering algorithms are used in various applications including pattern recognition, classification, data compression, regression, and related optimization problems. The design implements a computational solution for an autonomous data-reduction/clustering process to produce a representative distribution and joint relationships of the data without assuming a specific type of distribution and relationship nor resorting to domain-specific knowledge about the data.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_45908_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-45908-1","sourceUrl":"https://software.nasa.gov/software/NPO-45908-1","confidence":"high"},"type":"software","title":"MSLICE - Science Activity Planner for MSL","abstract":"MSLICE has been tasked to fulfill a challenging set of requirements. To meet these requirements, MSLICE delivers a rich feature set which includes but is not limited to:1) Simple, intuitive, and powerful search capability. For any given mission there is a huge amount of data and associated metadata that is generated. Quickly and easily sifting through all the data to find the interesting products requires a powerful tool with an intuitive interface. MSLICE provides such an interface in much the same way that the major Internet search engines provide a tool for searching the internet.2) Visualization of the rover's traverse in a HiRISE image. This view is basically a map of the mission, and it allows scientists to easily gauge where the rover has been and where they would like it to go. The map also provides the ability to correct or adjust the known position of the rover through the technique of overlaying images acquired from the rover on top of the HiRISE image. A user can then correct the rover's position by collocating the visible features in the overlays with the same features in the underlying HiRISE image.3) Visualization of data products and the ability to view mosaics.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_45962_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-45962-1","sourceUrl":"https://software.nasa.gov/software/NPO-45962-1","confidence":"high"},"type":"software","title":"Source Lines Counter (SLiC) version 4.0","abstract":"SLiC has been used in a variety of projects and missions at JPL, with over 75 active users at JPL alone. It is the official code counter endorsed by the Software Quality Improvement Project for its metrics collections effort across JPL and SQIs most requested software product. SLiC provides data for cost models used during all major JPL pre-Phase A software estimation activities as well as cost validation activities throughout project lifecycles. SLiC is used to gather metrics for the JPL State of Software report to measure process trends in flight projects and multimission ground system services.","category":"operations","categoryRaw":"business systems and project management","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_47115_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-47115-1","sourceUrl":"https://software.nasa.gov/software/NPO-47115-1","confidence":"high"},"type":"software","title":"Lidar Based Hazard Relative Navigation Algorithm for Safe Lunar Landing","abstract":"The purpose of HRN is to provide measurements to the Navigation Filter so that it can limit errors on the position estimate after hazards have been detected. The hazards are detected by processing a hazard digital elevation map (HDEM). The HRN process takes lidar images as the spacecraft descends to the surface and matches these to the HDEM to compute relative position measurements.This work is directly applicable to manned lunar landing. It is also directly applicable to robotics landers on the moon, other planets and small bodies. It could be used as a sensor approach for navigation of autonomous air vehicles for military and surveillance purposes.","category":"robotics_automation","categoryRaw":"autonomous systems","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_47237_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-47237-1","sourceUrl":"https://software.nasa.gov/software/NPO-47237-1","confidence":"high"},"type":"software","title":"MPS Editor","abstract":"The MPS Editor is written in Java using the Eclipse Rich Client Platform. The editor allows users to start in the early phases of development and continue on through the operations phases. It is currently built with four perspectives: the Activity Dictionary Perspective, the Project Adaptation Perspective, the Sequence Building Perspective and the Sequence Modeling Perspective. Each perspective performs a given task.The MPS editor uses the Eclipse Rich Client Platform to provide an environment that can be tailored to specific missions easily. It give them the capability to create/edit and Activity Dictionary, to build the simulation spacecraft models, to build and edit sequences of commands and to model the effect of those commands on the spacecraft.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_47703_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-47703-1","sourceUrl":"https://software.nasa.gov/software/NPO-47703-1","confidence":"high"},"type":"software","title":"Ndarts","abstract":"Ndarts is designed as a general purpose dynamics library that can be used for the modeling of robotic platforms, space vehicles, molecular dynamics and such applications. All NASA space vehicles use such capabilities.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_47725_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-47725-1","sourceUrl":"https://software.nasa.gov/software/NPO-47725-1","confidence":"high"},"type":"software","title":"Earth Science Datacasting v2.0","abstract":"Based on the popular concept of podcasting, which gives listeners the capability to download only those mp3 files that match their preference, earth science datacasting will give users control to download only the earth science data files that are required for a particular application. In essence, earth science datacasting is a simple, yet powerful informed pull and visualization mechanism. Earth science datacasting will be modeled on the server-client architecture used in podcasting and will leverage existing NASA capabilities. On the server side, the latest data granule is placed in an on-line store and an XML feed is created for the granule. The XML feed is based on the RSS 2.0 and GeoRSS 1.0 standard, with additional namespaces for describing earth science data (dataset and granule level descriptions).","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_47768_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-47768-1","sourceUrl":"https://software.nasa.gov/software/NPO-47768-1","confidence":"high"},"type":"software","title":"A Multi-Scale Three-Dimensional Variational Data Assimilation System for Coastal Ocean Prediction","abstract":"A multi-scale three-dimensional variational data assimilation scheme (MS-3DVAR) has been formulated and the associated software has been developed for high resolution coastal ocean models, aiming to assimilate simultaneously and effectively sparse vertical profiles and high resolution surface measurements, as well as to constrain forward-model biases. In this system, the cost function is decomposed into two separate units for the large and small scale components, respectively.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://zenodo.org/record/5787332","license":null}},{"forgeId":"forge_nasa_npo_47810_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-47810-1","sourceUrl":"https://software.nasa.gov/software/NPO-47810-1","confidence":"high"},"type":"software","title":"State Chart Autocoder","abstract":"This NASA technology automatically generates code from UML/SysML state-machine models specified in the MagicDraw modeling tool. Input is saved as XML data files, and output is provided by the state-machine implementation code in C, C , Python, or Promela. A test suite validates output products, and a test harness allows a developer to execute and animate a model with a graphical state-machine monitor. This monitor can run as either a standalone tool or as an Eclipse plug-in to MagicDraw.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_47832_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-47832-1","sourceUrl":"https://software.nasa.gov/software/NPO-47832-1","confidence":"high"},"type":"software","title":"A Model-Driven, Science Data Product Registration Service","abstract":"The Planetary Data System (PDS) has undertaken an effort to overhaul the PDS data architecture (e.g., data model, data structures, data dictionary, etc.) and deploy a software system (online data services, distributed data catalog, etc.) that fully embraces the PDS federation as an integrated system while leveraging modern information technology. The CCSDS Reference Model in turn relies heavily on the Electronic Business using eXtensible Markup Language (ebXML) standards for registry services and the registry information model, managed by the OASIS consortium.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-PDS/registry","license":null}},{"forgeId":"forge_nasa_npo_47934_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-47934-1","sourceUrl":"https://software.nasa.gov/software/NPO-47934-1","confidence":"high"},"type":"software","title":"Oceanographic Data Management And Archive System","abstract":"The Physical Oceanography Distributed Active Archive Center (PO.DAAC) is the center for oceanographic data for the NASA Earth Science Data and Information System (ESDIS). The primary function of PO.DAAC is to ingest, validate, archive, and distribute oceanographic artifacts.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/dataplumber/dmas","license":null}},{"forgeId":"forge_nasa_npo_48009_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-48009-1","sourceUrl":"https://software.nasa.gov/software/NPO-48009-1","confidence":"high"},"type":"software","title":"General MACOS Interface (GMI) for Modeling and Analysis for Controlled Optical Systems (MACOS)","abstract":"The General MACOS Interface (GMI) enables the use of MATLAB as a front-end for JPLs critical optical modeling package MACOS. MACOS is JPL's in-house optical modeling software, which has proven to be a superb tool for advanced systems engineering of optical systems. GMI, coupled with MACOS, allows for seamless interfacing with modeling tools from other disciplines to make possible integration of dynamics, structures, and thermal models with the addition of control systems for deformable optics and other actuated optics. GMI is a significant enhancement for MACOS as it provides a simple but effective framework to interface with MACOS using MATLAB as computational development platform, which, for instance, allows one to quickly develop and analyze the performance of the control algorithms, the influence of surface imperfections due to fabrication tolerances and polishing abilities, the thermal impact upon the optical system and/or the ability to align the optical system. GMI was originally developed for the James Webb Space Telescope (JWST) project, as part of the Wavefront Sensing & Control and alignment aspect during the I&T phase at Johnson Space Center (JSC).","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/nasa-jpl/gmi","license":null}},{"forgeId":"forge_nasa_npo_48199_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-48199-1","sourceUrl":"https://software.nasa.gov/software/NPO-48199-1","confidence":"high"},"type":"software","title":"Dartslab dtest testing software","abstract":"The dtest tool is a utility program (written in Python), that scans through a directory (and its subdirectories) and finds all directories that match a certain pattern (directory name starts with test_ or test-) and then executes any tests in that directory as described simple configuration files. The tests are completely arbitrary and are not tied to any specific programming language. A variety of tests are available to support comparing test output files with pre-validated versions. Dtest can be used in an automated testing environment or by individual software developer to manually create or maintain individual tests. Dtest accumulates tests results in data files that can be used for reporting tests results by email or on a website.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/nasa-jpl/dtest","license":null}},{"forgeId":"forge_nasa_npo_48344_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-48344-1","sourceUrl":"https://software.nasa.gov/software/NPO-48344-1","confidence":"high"},"type":"software","title":"InSAR Scientific Computing Environment version 2","abstract":"ISCE version 2 provides an integrated processing and visualization computing environment that allows users of interferometric synthetic aperture radar data from a variety of space-borne sensors to process from Level-0 to Level-4 products.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/isce-framework/isce2","license":null}},{"forgeId":"forge_nasa_npo_48378_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-48378-1","sourceUrl":"https://software.nasa.gov/software/NPO-48378-1","confidence":"high"},"type":"software","title":"Juneberry Web Service Software","abstract":"Implements the open webification API and provides ReSTful web services for planetary image data in commonly-used formats. Exposes content of planetary image data through meaningful URLs and enables creation of applications on diverse platforms.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_48644_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-48644-1","sourceUrl":"https://software.nasa.gov/software/NPO-48644-1","confidence":"high"},"type":"software","title":"The EDRN Knowledge Environment","abstract":"JPL has provided the underlying infrastructure to share data increasing the study power associated with capturing and comparing information. The infrastructure provides software services including data processing and management (eCAS), biomarker data management (BMDB), specimen data management (ERNE), and a portal to link the system together and provide access. These are software built on top of the Apache OODT software services.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/EDRN","license":null}},{"forgeId":"forge_nasa_npo_48712_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-48712-1","sourceUrl":"https://software.nasa.gov/software/NPO-48712-1","confidence":"high"},"type":"software","title":"GNEIMO Advanced Techniques for Constrained Internal Coordinate Molecular Dynamics","abstract":"The GNEIMO methods and algorithms build up on the Spatial Operator Algebra (SOA) multibody dynamics framework. The specific problems addressed in this work are velocity intialization techniques that are consistent with the CICMD equipartition priniciple, techniques for nulling momentum drift, analysis and solutions for the flying ice-cube effect, and performance of integration schemes.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_48877_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-48877-1","sourceUrl":"https://software.nasa.gov/software/NPO-48877-1","confidence":"high"},"type":"software","title":"DEMUD: Discovery through Eigenbasis Modeling of Uninteresting Data","abstract":"We have developed a machine learning solution called DEMUD (Discovery through Eigenbasis Modeling of Uninteresting Data ). DEMUD works by building a model U of the uninteresting class and then identifying items that are maximally anomalous (and therefore likely to be interesting) with respect to that model.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/wkiri/DEMUD","license":null}},{"forgeId":"forge_nasa_npo_49044_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-49044-1","sourceUrl":"https://software.nasa.gov/software/NPO-49044-1","confidence":"high"},"type":"software","title":"The OCO-2 Level 2 Retrieval Algorithm","abstract":"The primary purpose of the Level 2 retrieval software is to derive estimates of the column averaged atmospheric CO2 dry air mole fraction, XCO2, and other Level 2 data products from the spectra returned by the OCO-2 mission . Where XCO2 is defined as the ratio of the column abundances of CO2 and the column abundance of dry air.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA/RtRetrievalFramework","license":null}},{"forgeId":"forge_nasa_npo_49145_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-49145-1","sourceUrl":"https://software.nasa.gov/software/NPO-49145-1","confidence":"high"},"type":"software","title":"EarthKit","abstract":"EarthKit provides a framework for collaboration among researchers in Earth science. It provides a set of software tools for sharing any user's research environment via the web and managing workflows that run in the cloud. By leveraging cloud computing services in this novel way, EarthKit can instantly replicate a reesarch computing environment (software, data , operating system environment and hardware).","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/OpsLabJPL/earthkit-cli and https://github.com/OpsLabJPL/earthkit-workshop","license":null}},{"forgeId":"forge_nasa_npo_49413_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-49413-1","sourceUrl":"https://software.nasa.gov/software/NPO-49413-1","confidence":"high"},"type":"software","title":"DTKA, a Prototype Implementation of Delay-Tolerant Security Key Distribution","abstract":"Unlike all Internet mechanisms for security distribution (e.g., certificate authorities), DTKA operates over the extremely long signal propagation times and interrupted links that characterize communication with interplanetary spacecraft . It has no single point of failure and cannot be \"spoofed\" by an attacker's subversion of any single key authority machine (or even two key authority machines, in most configurations.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://sourceforge.net/projects/ion-dtn/","license":null}},{"forgeId":"forge_nasa_npo_49540_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-49540-1","sourceUrl":"https://software.nasa.gov/software/NPO-49540-1","confidence":"high"},"type":"software","title":"HORIZON 5 - Framework for distributed data management and product generation workflow","abstract":"HORIZON 5 is an extensible framework for data management systems. It is packaged with the following components SIP/AIP: The Open Archival Information System (OAIS) specification defines the framework for information capturing to information distribution.","category":"operations","categoryRaw":"business systems and project management","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/dataplumber/horizon","license":null}},{"forgeId":"forge_nasa_npo_49732_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-49732-1","sourceUrl":"https://software.nasa.gov/software/NPO-49732-1","confidence":"high"},"type":"software","title":"Space Mission Architecture and Risk Analysys Tool (SMART)","abstract":"SMART supports a high-level system trade study on a complex mission , such as a potential Mars Sample Return (MSR) mission , in an intuitive and quantitative manner. SMART offers a unique capability of handling correlated redundancies and accurately evaluate the probability of mission success as well as its sensitivity to the reliability of mission components.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa-jpl/spoc_lite","license":null}},{"forgeId":"forge_nasa_npo_49756_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-49756-1","sourceUrl":"https://software.nasa.gov/software/NPO-49756-1","confidence":"high"},"type":"software","title":"IMCE Ontological Modeling Framework","abstract":"JPL's Integrated Model-Centric Engineering (IMCE) initiative developed ontologies for Model-Based Systems Engineering (MBSE) to support JPL's MBSE practices and methodologies. The IMCE ontologies have been carefully engineered to provide support for scalable query and reasoning according to the semantics of the Ontology Web Language (OWL) standard in such a way that these ontologies can be mapped as extensions of the Unified Modeling Language (UML) & Systems Modeling Language (SysML) standards.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://opencaesar.github.io/","license":null}},{"forgeId":"forge_nasa_npo_49757_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-49757-1","sourceUrl":"https://software.nasa.gov/software/NPO-49757-1","confidence":"high"},"type":"software","title":"OMG Tool Infrastructure Working Group Workflow Automation & Modeling Tool Extensions","abstract":"JPL led the production of official machine-readable artifacts for several cycles of the official task forces that develop the Unified Modeling Language (UML) and Systems Modeling Language (SysML) specification standards published by the Object Management Group (OMG). The technology in this NTR focuses on capturing JPL's experience into extensions of various tools for replacing labor-intensive manual workflows typically involved in standards development at the OMG with automated workflow processes.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_49821_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-49821-1","sourceUrl":"https://software.nasa.gov/software/NPO-49821-1","confidence":"high"},"type":"software","title":"Regional Hydrologic Extremes Assessment System (RHEAS) software framework","abstract":"Automates the deployment of nowcasting and forecasting hydrologic simulations and ingests satellite observations (through data assimilation). Allows coupling of other environmental models. Also facilitates delivery of data products to users via a GIS-enabled database. users of project outputs through CCAFS network of partners. Our project objectives, and approach are integral with the goals of SERVIR.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/SERVIR/RHEAS","license":null}},{"forgeId":"forge_nasa_npo_49845_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-49845-1","sourceUrl":"https://software.nasa.gov/software/NPO-49845-1","confidence":"high"},"type":"software","title":"VICAR - Video Image Communication And Retrieval","abstract":"VICAR, which stands for Video Image Communication And Retrieval, is a general purpose image processing software system that has been developed since 1966 to digitally process multi-dimensional imaging data. VICAR was developed primarily to process images from the Jet Propulsion Laboratory's unmanned planetary spacecraft . It is now used for a variety of other applications including biomedical image processing, cartography, earth resources, astronomy, and geological exploration.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://www-mipl.jpl.nasa.gov/vicar_open.html","license":null}},{"forgeId":"forge_nasa_npo_49868_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-49868-1","sourceUrl":"https://software.nasa.gov/software/NPO-49868-1","confidence":"high"},"type":"software","title":"Juneplum - ReSTful Web Access of OPeNDAP Hyrax Back End Server","abstract":"Juneplum is implemented as a Java servlet webapp and can be directly deployed into the same servlet engine that Hyrax frontend lives in. With Juneplum, any data product served by OPeNDAP is made simultaneously accessible in a fully ReSTful way.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_49883_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-49883-1","sourceUrl":"https://software.nasa.gov/software/NPO-49883-1","confidence":"high"},"type":"software","title":"TIE 0.4 - The Imagery Exchange for the NASA Global Imagery Browse Services (GIBS) Project","abstract":"The software known as the The Imagery Exchange (TIE) 0.4 is an extension of the HORIZON 5 framework. It delivers horizontal scaling solutions for image capturing to automate the generation of the Meta Raster Format (MRF) imagery products.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa-gibs/tie","license":null}},{"forgeId":"forge_nasa_npo_49884_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-49884-1","sourceUrl":"https://software.nasa.gov/software/NPO-49884-1","confidence":"high"},"type":"software","title":"EDGE - The Extensible Data Gateway Environment","abstract":"EDGE uses Apache Solr for fast indexed search backend. Inventory data stored in PO.DAAC's Oracle server is being incrementally indexed avery 15 minutes. Apache Solr provides optimal search solution to all data it managements. By offloading data from Oracle, this eliminates Denial of Service (DoS) attacks against the core data management backend. To further ensure reliable serving of data , EDGE's Apache Solr uses Master and Slave model. The Master instance is for data indexing.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/apache/incubator-sdap-edge","license":null}},{"forgeId":"forge_nasa_npo_50050_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50050-1","sourceUrl":"https://software.nasa.gov/software/NPO-50050-1","confidence":"high"},"type":"software","title":"Cobra: A Code Browser and Analyzer -- an extendable, interactive tool for the analysis of C code","abstract":"Provides software developers, peer reviewers, testers, and quality assurance personnel with an interactive tool that facilitates searching for patterns, confirm compliance or non-compliance with coding guidelines and coding standards, identify suspicious code fragments, etc. Cobra uses a lexical analyzer for C to scan in source code.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_50126_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50126-1","sourceUrl":"https://software.nasa.gov/software/NPO-50126-1","confidence":"high"},"type":"software","title":"SysML System Model for the Thirty Meter Telescope (TMT)","abstract":"SysML is a standard, visual, and general-purpose system modeling language developed by the Object Management Group (OMG). MagicDraw from NoMagic is used as a modelling tool.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/Open-MBEE/TMT-SysML-Model","license":null}},{"forgeId":"forge_nasa_npo_50136_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50136-1","sourceUrl":"https://software.nasa.gov/software/NPO-50136-1","confidence":"high"},"type":"software","title":"OMINAS (OPEN-SOURCE MODULAR IMAGE NAVIGATION AND ANALYSIS SYSTEM) astronomical data processing software","abstract":"The primary motivation for the development of this software was to separate the analysis part of the problem from the data-specific part. This allows the exact same software to be used for multiple missions as needed; the only requirement for new mission input is the creation of a translator specific to that data source. Provides an API and for developing tools for astronomical data analysis .","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/ominas","license":null}},{"forgeId":"forge_nasa_npo_50138_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50138-1","sourceUrl":"https://software.nasa.gov/software/NPO-50138-1","confidence":"high"},"type":"software","title":"RiverObs","abstract":"RiverObs is a set of Python modules designed to ingest raster or point data , project them to a river centerline, modify the centerline, if desired, and calculate quantities, such as width, slope or stage that apply to a river reach.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/SWOTAlgorithms/RiverObs","license":null}},{"forgeId":"forge_nasa_npo_50157_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50157-1","sourceUrl":"https://software.nasa.gov/software/NPO-50157-1","confidence":"high"},"type":"software","title":"NEXUS: Deep Data Platform","abstract":"NEXUS provides a bridge between science data and horizontal-scaling data analysis . It provides a workflow to divide science artifacts into small data tiles to store in a cloud-scaled database where they can be quickly retrieved through a high performance spatial search registry. Through spatial index, NEXUS provides fast access to all relevant data tiles where each tile fits into RAM for fast in-memory computation.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/apache/incubator-sdap-nexus","license":null}},{"forgeId":"forge_nasa_npo_50185_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50185-1","sourceUrl":"https://software.nasa.gov/software/NPO-50185-1","confidence":"high"},"type":"software","title":"Real Time Spectroscopic Survey and Analysis","abstract":"This software has been developed specifically for NASA sun-synchronous Earth orbiting science spacecraft and has little commercial potential. No commercial market foreseen. This software is copyright protected.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/dsmbgu8/srcfinder","license":null}},{"forgeId":"forge_nasa_npo_50269_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50269-1","sourceUrl":"https://software.nasa.gov/software/NPO-50269-1","confidence":"high"},"type":"software","title":"DAta to Image SYstem (DAISY)","abstract":"Level 2 data can be visualized with accurate geometry through the use of the DAISY software and the GIBS web services. L2 data geolocation is indexed and instrument viewing geometry is used to generate accurate data footprints per data point in the form of an index image. An index image contains index values in its pixels to associate the corresponding data to the pixel. The index image is used as input to the MRF generation software that is part of GIBS and served out as tiles to clients. Clients that receive the index tiles must also access the source data via a technology such as webification in order to pull out the data at the indices that are in the tile image. This allows science data to be transferred into a client as an \"image\".","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa-gibs/daisy","license":null}},{"forgeId":"forge_nasa_npo_50389_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50389-1","sourceUrl":"https://software.nasa.gov/software/NPO-50389-1","confidence":"high"},"type":"software","title":"Multi-Mission Geographic Information System: a Spatial Data Infrastructure for Planetary Missions","abstract":"Our goal is to develop a multi-mission geographic information system (MMGIS) to create a planetary mission spatial data infrastructure (SDI) with geospatial data standards, tools, and interfaces for accessing science instrument data on a map in near-real time. This will be achieved by automating the localization/georeferencing of science data products and providing a unified mapping interface to visualization and querying spatial and quantitative data from multiple sources.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-AMMOS/MMGIS","license":null}},{"forgeId":"forge_nasa_npo_50406_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50406-1","sourceUrl":"https://software.nasa.gov/software/NPO-50406-1","confidence":"high"},"type":"software","title":"nfer: A Notation and System for Inferring Event Stream Abstractions","abstract":"The NFER software provides a rule-based notation and system for labeling event streams. The result of a labeling is a set of intervals: named sections of the event stream, each including a start time, and end time, and a map holding data selected from the events and sub-intervals making up the interval. Typically intervals are built on top of intervals, forming a hierarchy of abstractions. The result can for example be visualized, and can generally help engineers to better comprehend the structure of an event stream.The NFER system is implemented as an internal Scala DSL.Each interval-generating rule spawns an actor,that subscribes to events and/or sub-intervals, and publishes new intervals in the publish/subscribe architecture.The software can process events online, as theycome down to ground from the spacecraft , as well as eventsproduced at an earlier point in time, and stored in a database.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/rv-tools/nfer","license":null}},{"forgeId":"forge_nasa_npo_50468_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50468-1","sourceUrl":"https://software.nasa.gov/software/NPO-50468-1","confidence":"high"},"type":"software","title":"Connection of Cameo Simulation Toolkit with RabbitMQ Messaging Service","abstract":"This NTR covers a small but specific portion of the task. It is used to utilize MagicDraw as a \"ground station\" for testbed operations. It is only an application of off-the-shelf software. Communication from MagicDraw's Cameo Simulation Toolkit to Rabbit MQ Messaging Service.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/Open-MBEE/md-cst-rabbitmq","license":null}},{"forgeId":"forge_nasa_npo_50487_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50487-1","sourceUrl":"https://software.nasa.gov/software/NPO-50487-1","confidence":"high"},"type":"software","title":"Onboard Coaddition of Multiple Image Frames to Increase Signal to Noise Ratio and Facilitate Target Tracking","abstract":"This software is part of the agile science framework and the Near Earth Asteroid Scout (NEAScout) CubeSat flight software. The purpose of this software is to automatically increase the signal to noise ratio of image data, acquired by a spacecraft, without the need for data downlink. This is accomplished by taking multiple images, in rapid succession, and merging the data between these frames together, while accounting for instrument jitter and other intermediate effects. Increasing the signal to noise ratio also eliminates single image artifacts, like cosmic rays, which results in a higher fidelity product for subsequent processing. This process creates a single data product, representing the data from multiple image frames. This product can then be downlinked with a fraction of the bandwidth of the original, or further processed onboard the spacecraft.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/JPLMLIA/NEAScout-Science","license":null}},{"forgeId":"forge_nasa_npo_50498_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50498-1","sourceUrl":"https://software.nasa.gov/software/NPO-50498-1","confidence":"high"},"type":"software","title":"Mars Target Encyclopedia","abstract":"The Mars Target Encyclopedia (MTE) contains compositional information about Mars surface targets. The information was automatically extracted from scientific publications. Users can search for all targets that contain an element (e.g., \"calcium\") or mineral (e.g., \"hematite\") and see a map view of their spatial locations. They can also look up information about a specific target of interest (e.g., \"Dillinger\") to browse previous findings about its composition. All information in the MTE is linked to the source publication from which it was extracted, so users can easily browse the full context in the original document.We used two existing technologies to extract information for the MTE. First, we trained a Named Entity Recognition classifier using Stanford's CoreNLP system. We hand-labeled 63 documents from the 2015 Lunar and Planetary Science Conference (LPSC) to indicate Elements, Minerals, and Targets. We trained a classifier on this data set and evaluated it on a set of 30 hand-labeled documents from LPSC 2016, achieving a performance of 0.83.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/wkiri/MTE","license":null}},{"forgeId":"forge_nasa_npo_50576_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50576-1","sourceUrl":"https://software.nasa.gov/software/NPO-50576-1","confidence":"high"},"type":"software","title":"EVRTH : Virtual Reality Earth Data Visualization using streaming tiled GIBS data","abstract":"This project offers users a real-time globe textured with the latest imagery received from NASA spacecraft. Users areable to manipulate the globe and access scientific data.. Features include:Real and Up to Date Image AccessAccess the latest daily imagery from NASAs Global Imagery Browse Services (GIBS)Automatically fetch imagery at the correct level of detail based on globe scale and head distanceAccess imagery acquired at different times in the pastSpin the globe on two axesPosition and scale the globeScrub and animate through imagery over timeVisualize a 3D iso-surface of scientific data (e.g., gravity or water vapor)Visualize scientific data that varies by altitude","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/OpsLabJPL/EVRTH","license":null}},{"forgeId":"forge_nasa_npo_50581_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50581-1","sourceUrl":"https://software.nasa.gov/software/NPO-50581-1","confidence":"high"},"type":"software","title":"Traceable Robotic Activity Composer and Executive (TRACE)","abstract":"TRACE provides users with the ability to graphically model event/data-driven missions that can then be execute by one or more robotic systems. It includes tools to verify these missions both for correctness and for achieving specified requirements. It also includes a composer for designing missions specifically for robotic assets by providing overloaded BPMN elements. These elements provide the information to the connect to correctly specify to the system below (e.g. ROS or CARACaS) to correctly control the robotic system.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/nasa/trace-executive; https://github.com/nasa/trace-ros-connector; https://github.com/nasa/trace-ros-executive; https://github.com/nasa/trace-ros-actions-autocoder","license":null}},{"forgeId":"forge_nasa_npo_50601_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50601-1","sourceUrl":"https://software.nasa.gov/software/NPO-50601-1","confidence":"high"},"type":"software","title":"Kontest: A tool for scenario-based software testing","abstract":"Kontest is a new tool for automated software testing. It provides convenient syntax allowing a developer to write test scenarios that can describe broad classes of tests. Scenarios can be as simple as an ordinary unit test with added parameters that can take a range of values, but can also include nondeterministic sequences of actions with temporal or other constraints (the notation is still under development). Given a scenario, Kontest automatically refines it into thousands of concrete tests, using dynamic program analysis to find realizations of the scenario that will trigger different execution paths through the program under test.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/rjvjshjpl/kontest","license":null}},{"forgeId":"forge_nasa_npo_50616_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50616-1","sourceUrl":"https://software.nasa.gov/software/NPO-50616-1","confidence":"high"},"type":"software","title":"InSAR processor for ALOS-2 multi-mode SAR data and ionospheric correction","abstract":"This software implements the InSAR processing of ALOS-2 multi-mode SAR data and InSAR ionospheric correction based on the JPLs ISCE software. Like ISCE, the parameters are mainly handled by python programs, while image processing are mainly done by C or Fortran programs. When available, the basic modules of ISCE are called to do the processing and therefore the high processing efficiency of ISCE is inherited. ALOS-2 has many acquisition modes and different wavelengths. The unique feature of one app to support all can facilitate both the users and the maintenance of the software.The software continues to contribute to the numerous applications of the InSAR technology originally developed at JPL. In particular, the L-band ScanSAR-ScanSAR interferometry helps geophysicists to look at the large-scale and long-term deformation rates of many tectonically active areas. Many of these areas have dense vegetation and high reliefs, and C-band InSAR data does not work very well, while historical InSAR data usually have much smaller swath coverage. In addition, large-scale deformation of large earthquakes can also be measured with higher quality with L-band ScanSAR-ScanSAR interferometry. The support of multi-mode InSAR processing helps to get denser InSAR time series, which is helpful to look at the temporal evolution of the geophysical phenomena.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/isce-framework/isce2","license":null}},{"forgeId":"forge_nasa_npo_50634_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50634-1","sourceUrl":"https://software.nasa.gov/software/NPO-50634-1","confidence":"high"},"type":"software","title":"HELM: Hologram Examination for Life-like Motility","abstract":"We seek to develop algorithms to detect moving objects directly in the holograms produced by a Digital Holographic Microscope (DHM), eliminating the majority of computation required for spatial reconstruction. We further will construct a functional prototype system that tracks these particles, analyzes their motion, and trains a machine learning classifier to distinguish life-like motility from non-living organic or inorganic particles. We will demonstrate sufficient speed (limited compute) and memory efficiency (limited memory footprint) to enable laptop-based, in-field, real-time processing of the streaming instrument output leading directly to proposals for an on-board DHM instrument on Europa or Mars.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/JPLMLIA/OWLS-Autonomy","license":null}},{"forgeId":"forge_nasa_npo_50647_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50647-1","sourceUrl":"https://software.nasa.gov/software/NPO-50647-1","confidence":"high"},"type":"software","title":"SPOC-Lite: On-board, lightweight terrain classifier for planetary rovers","abstract":"The SPOC-Lite software is intended for on-board rover software to enhance safety of autonomous driving. By remotely detecting sandy surface, the rover can safely avoid slips/wheel embedding caused by sandy terrains.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa-jpl/spoc_lite","license":null}},{"forgeId":"forge_nasa_npo_50675_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50675-1","sourceUrl":"https://software.nasa.gov/software/NPO-50675-1","confidence":"high"},"type":"software","title":"Neural Network Emulation of VSWIR Atmospheric Radiative Transfer Models","abstract":"Conventional Visible Shortwave Infrared (VSWIR) imaging spectrometer atmospheric correction evolved from multi-band approaches and generally does not exploit the full spectral measurement. We hypothesize that a pure spectroscopic approach can improve atmospheric inversion accuracy to minimize regional biases in global-scale investigations. Such techniques are pervasive in atmospheric remote sounding disciplines, where Optimal Estimation (OE) retrieval theory (Rodgers et al., 2000) inverts a radiance spectrum to recover a consistent physical model incorporating, for example, aerosol and H2O, the interactions between scattering, absorption, and the coupling between surface reflectance and atmosphere. This enables a statistically rigorous treatment of uncertainty with the potential to recover information on spectrally-broad signals. Our software demonstrates a proof of concept that overcomes the primary computational roadblock of these methods: fast execution of line-by-line Radiative Transfer (RT) models. Neural Network (NN) emulation can replicate the results of the MODTRAN 6.0 line-by-line A-band model to high accuracy and a five order of magnitude improvement in execution time. This demonstrates potential for OE to provide significant advances in the accuracy and modeling power of VSWIR atmospheric correction.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/pgbrodrick/sRTMnet","license":null}},{"forgeId":"forge_nasa_npo_50696_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50696-1","sourceUrl":"https://software.nasa.gov/software/NPO-50696-1","confidence":"high"},"type":"software","title":"AMMOS Instrument Toolkit","abstract":"The AMMOS Instrument Toolkit is a lightweight operations and data processing toolkit for instruments and small satellites. It provides traditional uplink and downlink capabilities across all phases of the project lifecycle from early development and prototyping, through to integration and test, and ultimately operations.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-AMMOS/AIT-Core and https://github.com/NASA-AMMOS/AIT-GUI  and https://github.com/NASA-AMMOS/AIT-DSN","license":null}},{"forgeId":"forge_nasa_npo_50704_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50704-1","sourceUrl":"https://software.nasa.gov/software/NPO-50704-1","confidence":"high"},"type":"software","title":"Probabilistic iterative inversion of combined surface/atmosphere models for atmospheric correction of imaging spectrometer data","abstract":"We have developed a software package that permits inversion of imaging spectrometer data using a Bayesian probabilistic formalism and least squares optimization with a \"forward model\" of photon transport to match an estimate of atmosphere and surface properties to the measured spectrum. It is instantiated as a python package and can take advantage of externally-available radiative transfer packages such as MODTRAN. It runs on data formats such as ASCII text files and binary files similar to those used by NASA instruments such as AVIRIS-NG.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/isofit/isofit","license":null}},{"forgeId":"forge_nasa_npo_50715_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50715-1","sourceUrl":"https://software.nasa.gov/software/NPO-50715-1","confidence":"high"},"type":"software","title":"Fast Linearized Coronagraph Optimizer (FALCO)","abstract":"The Fast Linearized Coronagraph Optimizer (FALCO) is a free toolbox of routines for coronagraphic focal plane wavefront correction. The goal of FALCO is to provide a modular, open-source framework for the simulation and/or testbed operation of several common types of coronagraphs. FALCO includes routines for pair-wise probing estimation of the complex electric field and Electric Field Conjugation (EFC) control, and we ask the community to contribute other wavefront correction algorithms. FALCO utilizes and builds upon PROPER, an established optical propagation library. The key innovation in FALCO is the rapid computation of the linearized response matrix for each deformable mirror (DM), which facilitates re-linearization after each control step for faster DM-integrated coronagraph design and wavefront correction experiments. FALCO will be available on Github as source code in MATLAB and Python.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/ajeldorado/falco-matlab or https://github.com/ajeldorado/falco-python","license":null}},{"forgeId":"forge_nasa_npo_50759_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50759-1","sourceUrl":"https://software.nasa.gov/software/NPO-50759-1","confidence":"high"},"type":"software","title":"3D Ground Control Station for Aerial Vehicles","abstract":"With the growing use of autonomous quadrotors for research and deployment in a range of fields, there is a growing need for effective trajectory optimisation. To have effective trajectory optimisation, it is important to be able to assess the suitability of a planned trajectory prior to sending it to a hardware system, and to have the ability to edit and update a trajectory as needed. This software provides a 3D graphical user interface for intuitive generation, assessment, and modification of optimal trajectories for quadrotors through obstacle rich environments. Implemented in the software are three state-of-the-art algorithms that plan trajectories through a pre-mapped obstacle field. The software is designed to be integrated with a hardware system to: record a flown trajectory to repeat, send trajectories to a quadrotor to fly, and get live feedback during a flight. Use cases of the software include assessment of existing or new trajectory optimization algorithms, assessing feasibility of operations in a given environment, and the operational planning and flying of a quadrotor. The operational application is for flying in a pre-mapped environment, and requires other software tools for the complete system (map generation, and hardware system).","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/genemerewether/torq","license":null}},{"forgeId":"forge_nasa_npo_50770_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50770-1","sourceUrl":"https://software.nasa.gov/software/NPO-50770-1","confidence":"high"},"type":"software","title":"CERBERUS: a Bayesian retrieval scheme for efficiently applying high dimensionality model spaces to the study of exoplanet atmospheres","abstract":"CERBERUS is a scientific software code developed for estimating properties of exoplanet atmospheres - planets that orbit nearby stars - based on spectroscopic observations from astronomical observatories. The code implements a Bayesian approach coupled with a novel branch-pruning method which allows the efficient evaluation of a complex model space that incorporates both thermo chemical equilibrium (TCE) and non-TCE models for atmospheric chemistry. The forward models used in the retrieval process include a detailed radiative transfer equations and support for both gaseous and aerosol opacity sources. Vertical dependence for both opacity sources and the atmospheric temperature profile are supported. The model selection capability of CERBERUS is a significant advancement over the current state of the art and allows CERBERUS to efficiently evaluate the statistical evidence a much broader range of models than other codes; when combined with the new high spectral resolution observations that are now becoming available, CERBERUS allows new insights in the conditions and composition of exoplanet atmospheres and allows rapid processing of large data sets.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/al-niessner/esp","license":null}},{"forgeId":"forge_nasa_npo_50785_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50785-1","sourceUrl":"https://software.nasa.gov/software/NPO-50785-1","confidence":"high"},"type":"software","title":"PDSC: Planetary Data System Coincidences","abstract":"The PDSC library allows for quickly querying coincident observations by constructing a set of special databases and index structures during the ingestion process. The first database constructed is simply a SQL version of the PDS cumulative index. The second set of index structures holds geometric information used for coincidence queries","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://pypi.org/project/pdsc/","license":null}},{"forgeId":"forge_nasa_npo_50793_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50793-1","sourceUrl":"https://software.nasa.gov/software/NPO-50793-1","confidence":"high"},"type":"software","title":"SpiceyJS - Time conversion library based on NAIF's CSPICE","abstract":"Spicey is a time conversion library based on NAIF's CSPICE. In order to accomplish this, we automatically converted the C source code into Javascript via Emscripten. In order for them to work in a much more user friendly and Javascript-like way, we have created wrapper functions that interact with the resulting simulated C program, allocating and deallocating memory as necessary. This project only includes wrappers for the functions relevant to time conversion and some light time calculations. If you are looking to use CSPICE's extensive telemetry, etc. functionality, instead look at spice.js. This project is an offshoot of spice.js. A great deal below deals with the loading and furnishing of kernels. If you do not wish to do any time conversions involving specific spacecraft or planets, the default included kernels are sufficient and you may ignore these sections. The default kernels are enough to refer to most NAIF ID's, a planetary constants kernel, and a leap seconds kernel. See spicey_example.html for a simple demo of spicey working.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://naif.jpl.nasa.gov/naif/  or http://kripken.github.io/emscripten-site/index.html","license":null}},{"forgeId":"forge_nasa_npo_50805_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50805-1","sourceUrl":"https://software.nasa.gov/software/NPO-50805-1","confidence":"high"},"type":"software","title":"OpenSCRUB","abstract":"OpenSCRUB is an orchestration framework that is used to run and aggregate results from multiple static code analysis tools. OpenSCRUB is customizable to the needs of the project, allowing teams to tailor execution to meet their needs. OpenSCRUB also allows users to export static analysis results to Collaborator in order to perform peer reviews.The end goal of OpenSCRUB is to incorporate static analysis results into peer reviews to ensure that all the static analysis findings are addressed and discussed. The internal OpenSCRUB GUI can also be used by developers strictly as a viewer for browsing static analysis results from multiple sources.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/scrub","license":null}},{"forgeId":"forge_nasa_npo_50821_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50821-1","sourceUrl":"https://software.nasa.gov/software/NPO-50821-1","confidence":"high"},"type":"software","title":"TilePredictor: Image and Pixelwise Classification with Tile-based Convolutional Neural Networks (CNNs)","abstract":"TilePredictor is a python library designed to rapidly construct and evaluate CNN-based image classifiers for image and pixelwise classification problems. In particular, TilePredictor is designed to generate pixelwise predictions using image-based CNN classifiers which generate a single prediction per image for large images such as those typically encountered in remote sensing and astronomy. TilePredictor generates pixelwise predictions by efficiently spatially aggregating predictions generated by convolving an image-based CNN over tiles extracted from a target image. Additionally, TilePredictor wraps essential CNN training and validation functions to enable rapid construction, evaluation and deployment of both pre-trained and newly-instantiated image-based CNN models to new image data with minimal effort.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/dsmbgu8/tilepredictor","license":null}},{"forgeId":"forge_nasa_npo_50825_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50825-1","sourceUrl":"https://software.nasa.gov/software/NPO-50825-1","confidence":"high"},"type":"software","title":"Asteroid Survey Simulation Tool","abstract":"Modeling of candidate asteroid search programs by producing files of individual image pointing for the observatory. Hypothetical asteroid populations are checked to see which of the objects are in each field and lists of candidate detections are developed. Post-processing leads to an estimate of the programs search performance.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/asteroidsurveysimulator","license":null}},{"forgeId":"forge_nasa_npo_50830_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50830-1","sourceUrl":"https://software.nasa.gov/software/NPO-50830-1","confidence":"high"},"type":"software","title":"OnSight: Multi-platform terrain visualization for science, engineering, and public outreach","abstract":"OnSight allow scientists and engineers to immerse themselves within a reconstruction of the terrain around the Curiosity rover. Prior to OnSight, scientists worked primarily by viewing 2D images or panoramas sent back by the Curiosity rover. However, it is extremely difficult to get a sense of three dimensional relationships by viewing 2D images. Three-dimensional visualization on traditional computer screens has been available to a subset of Mars mission operations teams since the late 1990s. However, these interfaces have not been available to the full mission science team and do not offer the intuitive understanding that is gained when one explores the environment in the same ways that they explore an environment on Earth.Using an immersive display, OnSight can render a reconstruction of Mars at full scale, and allow users to navigate the model by simply walking and looking around. This interaction model requires little to no training, because it takes advantage of motor skills and spatial reasoning abilities that humans develop instinctively. It also enables field scientists to access the skills and intuition that they have developed while exploring environments on Earth. OnSight provides the closest experience to working on Mars without physically being there. By enabling users to utilize all their spatial reasoning ability, users gain improved spatial comprehension of the environment, which enables them to efficiently plan safe rover operations and make new scientific discoveries.OnSight was developed for the context of Mars exploration, but the system provides general capability for visualization and virtual presence in a remote environment. There are many potential applications of technology, including Earth based terrain visualization (e.g. caves, lava fields, remote field sites), as well as other planetary and asteroid surfaces.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_50838_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50838-1","sourceUrl":"https://software.nasa.gov/software/NPO-50838-1","confidence":"high"},"type":"software","title":"LSTM-based Anomaly Detection System for Spacecraft Telemetry","abstract":"Detecting anomalies in spacecraft telemetry using fully-automated machine learning-based approaches.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/khundman/telemanom","license":null}},{"forgeId":"forge_nasa_npo_50859_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50859-1","sourceUrl":"https://software.nasa.gov/software/NPO-50859-1","confidence":"high"},"type":"software","title":"Programmatic Cost Tool (PCT)--A Spreadsheet Tool for Systematically Generating Sand Charts for Human Spaceflight Architectures.","abstract":"Multi-system, multi-decade human spaceflight architectures can be very complex. Using a system architecting approach, the Programmatic Cost Tool (PCT) transforms user-provided data artifacts (e.g., systems, flight types, flight schedules) on human spaceflight architectures into a table of year-by-year programmatic costs consisting of development, production, and sustainment costs for each system/program. From this table, the software automatically generates a standard programmatic view called a 'sand chart.One anticipated use of the PCT, then, is to filter out those architectures in an analysis of alternatives (AoA) that clearly do not meet the affordability test. Another is to show the comparative programmatic costs over time for multiple specific architectures. These kinds of analyses are especially helpful when applied early in the architecture definition process. Fortunately, the PCT can be used in early studies, since the input data requirements are at a relatively high level.","category":"operations","categoryRaw":"business systems and project management","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_50864_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50864-1","sourceUrl":"https://software.nasa.gov/software/NPO-50864-1","confidence":"high"},"type":"software","title":"DejaVu","abstract":"The objective of DejaVu is to verify the execution of a running system against a requirement formalized in a formal logic. The system will typically be a software system that has been instrumented to generate events as it executes. The event stream is then consumed by the DejaVu monitor, and checked against a formal specification. If the event stream violates the specification, an error message is generated. This technology can be used in two ways: online and offline. In the online case, it runs on board for example a rover as it operates, checking that what is happening on the rover is according to expectations formalized in the formal logic. If the expectations are not met, the DejaVu monitor will inform the software that it needs to correct behavior. Alternatively, DejaVu can be used to analyze log files produced by the monitored system. Such log files can be analyzed after the system has executed.Software program for analyzing execution traces generated by a running system, typically another program, here referred to as the Monitored System (MS). The MS must be instrumented to emit events as it executes. The emitted trace is consumed by the DejaVu monitor, which verifies it against a property (requirement) formalized in first-order past time temporal logic. The system is innovative in using BDDs (Binary Decision Diagrams) for storing data from the execution trace.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/havelund/dejavu","license":null}},{"forgeId":"forge_nasa_npo_50887_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50887-1","sourceUrl":"https://software.nasa.gov/software/NPO-50887-1","confidence":"high"},"type":"software","title":"PIQUANT X-ray Fluorescence Quantification Software","abstract":"Calibration work is underway to enhance the elemental quantification capabilities of the prototype Planetary Instrument for X-ray Lithochemistry (PIXL) on Mars 2020. This work is intended ultimately to benefit scientists analyzing PIXL data derived from the eventual flight instrument. Quantification of X-ray data is made possible using PIQUANT, the in-house fundamental parameters (FP) approach software constructed for this application.Several of the X-ray FP databases, utilized by PIQUANT, will be discussed. Emphasis will be placed on the accuracy of parameters found in mass attenuation coefficient, fluorescence yield and line intensity databases used in quantifying geological elemental constituents. The choice of databases and values used derive from both recent experimental work and initiatives defined by fundamental parameter groups. These considerations have influenced recent upgrades made to PIQUANT. The quantification and fitting capabilities of PIQUANT in light of the upgrades will be presented. In this we display PIQUANTs ability to reproduce certificate values of glass and powder silicate standards.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://zenodo.org/record/6959126#.YvrZpnbMJPY","license":null}},{"forgeId":"forge_nasa_npo_50897_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50897-1","sourceUrl":"https://software.nasa.gov/software/NPO-50897-1","confidence":"high"},"type":"software","title":"OIIP Data Viewer","abstract":"The Oceanographic In-Situ Interoperability Project aims to integrate diverse in-situ datasets with related remote sensing products from NASA. The data viewer is the web application through which users can explore and interrogate the range of data available within this project. The application will reveal the multi-dimensional facets of in-situ data at full data resolution. It provides an coherent search interface that accommodates the heterogeneity of in-situ products and sophisticated charting options that provide granular control over data displays.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/oiip/oiip-data-viewer","license":null}},{"forgeId":"forge_nasa_npo_50934_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50934-1","sourceUrl":"https://software.nasa.gov/software/NPO-50934-1","confidence":"high"},"type":"software","title":"Data driven solutions for general satellite maneuvers.","abstract":"Satellite swarms will be an integral tool for many future space-based scientific endeavors, including space-based interferometry. These endeavors will require the ability to precisely reconfigure satellites swarms to specifications generated on the fly according to scientific priorities. Crucial to reconfiguring swarms is the ability to maneuver individual satellites between prespecified start and end positions in a fixed amount of time.However, there is no consensus solution on how to do these single satellite maneuvers fuel-efficiently in the general case. Consider the position of a single satellite in the swarms Local Vertical/Local Horizontal (LVLH) reference frame relative to the swarms reference orbit. For specific single satellite transition scenarios, such as transferring the satellite between LVLH passive reference orbits (PROs) with minimal thrust expenditure in the Clohessy-Wiltshire (CW) linearized orbit dynamics system, provably optimal algorithms have been developed. But these provably optimal algorithms fail to generalize in a multitude of ways. They fail to generalize to arbitrary start and end states in the LVLH frame, they fail to generalize to more complex dynamical models such as those including J2 and drag terms, they cannot handle more detailed models of thrusters and satellite pose, and cannot account for more complex optimization criteria which balance the needs of scientific instruments with fuel efficiency and timeliness.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/marsai2/swarm-spacecraft-formation-flying","license":null}},{"forgeId":"forge_nasa_npo_50960_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50960-1","sourceUrl":"https://software.nasa.gov/software/NPO-50960-1","confidence":"high"},"type":"software","title":"PIXELATE, an Astrobiology visualization tool","abstract":"The Planetary Instrument for X-ray Lithochemistry is called PIXL. PIXL has a tool called an X-ray spectrometer. It identifies chemical elements at a tiny scale. PIXL also has a camera that takes super close-up pictures of rock and soil textures. It can see features as small as a grain of salt! Together, this information helps scientists look for signs of past microbial life on Mars.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/pixlise","license":null}},{"forgeId":"forge_nasa_npo_50982_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-50982-1","sourceUrl":"https://software.nasa.gov/software/NPO-50982-1","confidence":"high"},"type":"software","title":"The Multi-mission Algorithm and Analytics Platform (MAAP)","abstract":"The purpose of the joint NASA/ESA Multi-Mission Algorithm and Analysis Platform (MAAP) is to maximize the use of earth observational data in an open and collaborative environment. Initially, the project will use data from the BIOMASS, GEDI, and NISAR missions, which represent a highly complementary set of measurements to determine Earths aboveground woody biomass with the goal of expanding as a general purpose platform for analyzing earth science data. The capabilities envisioned for the MAAP will enable for the first time efficient and tailorable comparisons, cross calibration, and fusion of data from these missions for a broad community of scientists and other users.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/maap-project/","license":null}},{"forgeId":"forge_nasa_npo_51089_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51089-1","sourceUrl":"https://software.nasa.gov/software/NPO-51089-1","confidence":"high"},"type":"software","title":"GIBS Machine Learning for Data Validation and Natural Event Detection","abstract":"NASA Global Imagery Browse Services (GIBS) provides a full-resolution image archive of over 70 million images and access to services for over 700 NASA Earth science data products covering every part of the world. Most imagery is available within 3-5 hours after satellite overpass and some products span almost 30 years. While the GIBS satellite data remains highly accessible, it remains largely underexploited and analyzed due to its scale. The development of algorithms to ensure the consistency of data is critical for near-real time (NRT) applications. We identify two machine learning tasks: (1) data validation and (2) natural event detection. For data validation we will apply machine learning techniques to validate images for missing data patterns and miscoloration. For natural event detection we illustrate the promise of deep learning to leverage the scale of GIBS imagery to learn state-of-the-art algorithms. Lastly, we implement an operational machine learning system to process new images and notify GIBS operators.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa-gibs/gibs-ml","license":null}},{"forgeId":"forge_nasa_npo_51093_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51093-1","sourceUrl":"https://software.nasa.gov/software/NPO-51093-1","confidence":"high"},"type":"software","title":"Methane Source Finder web application (user-interface and server)","abstract":"We will combine our collective expertise in atmospheric chemistry, carbon cycle science, spectroscopy, data assimilation, machine learning software engineering, and science systems engineering to develop CEDAS to meet the following objectives: 1.Detect and characterize localized methane and CO2 anomalies that manifest in an intermittent and stochastic but with net high magnitude fluxes.2.Apply machine learning techniques to provide more autonomous and lower latency source detection, attribution and process understanding. 3.Automate and optimize methane and CO2 analysis workflows to reduce data product latency and improve on-demand services including quality control and validation. 4.Develop a regional-scale scale analysis framework that can assimilate surface and satellite atmospheric observations and high-resolution weather reanalysis products for any region globally. 5.Demonstrate a common data system that facilitates anomaly notification/response, data search, discovery, fusion and on-demand analytics.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_51099_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51099-1","sourceUrl":"https://software.nasa.gov/software/NPO-51099-1","confidence":"high"},"type":"software","title":"Planetary Data System Inspect Tool","abstract":"The Inspect Tool is a component of the Preparation Tools suite of tools providing functionality for preparing data for ingestion into PDS. It is intended to provide a capability for opening and inspecting the contents (e.g. label, objects, groups) of any PDS compliant archival product, and a method to visualize selected archival products.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-PDS/pds-view","license":null}},{"forgeId":"forge_nasa_npo_51110_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51110-1","sourceUrl":"https://software.nasa.gov/software/NPO-51110-1","confidence":"high"},"type":"software","title":"Cloud Vertical Structure Reconstruction using Generative Adversarial Networks","abstract":"We demonstrate the feasibility of solving atmospheric remote sensing problems with machine learning using conditional generative adversarial networks (CGANs), implemented using convolutional neural networks (CNNs). We apply the CGAN to generating two-dimensional cloud vertical structures observed the by CloudSat satellite -based radar, using only the collocated Moderate-Resolution Imaging Spectrometer (MODIS) measurements as input. The CGAN is usually able to generate accurate guesses of the cloud structure, and can infer complex structures such as multilayer clouds from the MODIS data. This network, which is formulated probabilistically, also estimates the uncertainty of its own predictions. Furthermore, we examine the statistics of the generated data, and analyze the response of the network to each input parameter. The success of the CGAN in solving this problem suggests that generative adversarial networks are applicable to a wide range of problems in atmospheric science, a field characterized by complex spatial structures and observational uncertainties.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/jleinonen/cloudsat-gan","license":null}},{"forgeId":"forge_nasa_npo_51130_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51130-1","sourceUrl":"https://software.nasa.gov/software/NPO-51130-1","confidence":"high"},"type":"software","title":"PDS4 Java Library and Tools","abstract":"Software for accessing PDS4 data objects including selected transformations to common formats. This software is packaged as a Java library with an example driver program and is called by the Validate Tool to assist in validation and by the Transform Tool to transform PDS4 products into common formats. The PDS4 Tools software was developed using Java and will run on any platform with a supported Java Runtime Environment (JRE).","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-PDS/pds4-jparser","license":null}},{"forgeId":"forge_nasa_npo_51132_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51132-1","sourceUrl":"https://software.nasa.gov/software/NPO-51132-1","confidence":"high"},"type":"software","title":"PDS Archive Inventory and Monitoring System (AIMS)","abstract":"For PDS Cartography and Imaging Science Node, it is critical that we know what data we have, where it is on the file system, ensure data integrity is maintained, and the data is available through the Atlas. Currently we have a loose understanding of the data we have, but we need to enable a more detailed picture of the data we actually have in the archive versus the data we make available to users through the Atlas. Once we have this picture, we can then move to the next stage of fixing any discrepancies. This software tool should be runnable via the command-line (and also a web browser if possible but not required), and have a documented API for the CLI (command-line interface).","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/archive-manager-and-processor","license":null}},{"forgeId":"forge_nasa_npo_51147_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51147-1","sourceUrl":"https://software.nasa.gov/software/NPO-51147-1","confidence":"high"},"type":"software","title":"Interactive Data Analyzer and Reviewer for Machine Learning Systems","abstract":"The framework we provide is extremely light-weight and flexible to be expanded to adapt for almost any data related interactions in machine learning systems. The tools included in the framework not only aim to provide deeper insights into the system to machine learning experts, but also are key components for the goal to operationalize machine learning systems.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/stevenlujpl/IDAR","license":null}},{"forgeId":"forge_nasa_npo_51204_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51204-1","sourceUrl":"https://software.nasa.gov/software/NPO-51204-1","confidence":"high"},"type":"software","title":"Radio Astronomy Software Tools","abstract":"Radio Astronomy Software Tools} is a collection of softwarepackages that have proven useful in doing radio astronomy with NASA's Deep Space Network. It includes a monitor and control system that is overlaid on the operational monitor and control to provide features necessary or useful for conducting radio astronomy research. The collection may provide a quick way to start a small single dish radio astronomy ab initio. It is also able to manage a telescope system in which all subsystems have their own, network-accessible controllers.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://sdrast.github.io/  and https://github.com/SDRAST/","license":null}},{"forgeId":"forge_nasa_npo_51240_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51240-1","sourceUrl":"https://software.nasa.gov/software/NPO-51240-1","confidence":"high"},"type":"software","title":"PDS Transform Tool","abstract":"The PDS Transform Tool project contains software for transforming PDS3 and PDS4 product labels and product data into common formats more applicable for user applications and scientific research.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-PDS/transform","license":null}},{"forgeId":"forge_nasa_npo_51247_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51247-1","sourceUrl":"https://software.nasa.gov/software/NPO-51247-1","confidence":"high"},"type":"software","title":"Open CAESAR Server","abstract":"Open CAESAR Server has been developed at JPL in the Integrated Model-Centric Engineering (IMCE) initiative as part of a foundation and ecosystem for experimenting and tackling an increasingly complex set of challenges and opportunities in the modern practice of systems engineering characterized by the adoption of powerful but specialized engineering modeling tools. The Open CAESAR Server addresses this objective via a combination of the following techniques:- GIT as a comprehensive content-based configuration management system as the authoritative source of truth and provenance about systems engineering information managed in Open CAESAR Server.- A micro-services design based on the open-source Lagom framework for the agile development of resilient, elastic, reliable and asynchronous services.- Automated cloud deployment via the vendor-neutral Kubernetes standard from the open source Cloud Native Computing Foundation (CNCF) and Kubernetes operators synchronizing the state of an Open CAESAR Server deployment against a GIT repository specifying the desired configuration of such deployment.- Using the Ontological Modeling Framework (OMF), NTR 49756, as a foundation for representing integrated systems engineering information.The scope of Open CAESAR Server pertains to the functionality related to CAESAR integration workflows: directed acyclic graphs of processes operating on systems engineering information.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_51295_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51295-1","sourceUrl":"https://software.nasa.gov/software/NPO-51295-1","confidence":"high"},"type":"software","title":"VegMapper","abstract":"VegMapper is an open-source package build in the R language, that employ Bayesian algorithms to generate the presence probability for a user-defined class. It automates and streamlines all GIS operations to integrate remote sensing imagery with in-situ data . The package is flexible and can accept a variable number of predictor variables and in-situ points.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NaiaraSPinto/VegMapper","license":null}},{"forgeId":"forge_nasa_npo_51299_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51299-1","sourceUrl":"https://software.nasa.gov/software/NPO-51299-1","confidence":"high"},"type":"software","title":"SciHound","abstract":"SciHound is an Android app that allows users to survey areas and help with calibration and validation of land cover maps from remote sensing. It streamlines the interfacing between remote sensing scientists and researchers from the broader environmental sciences community.Minimalistic interface allowing users to record coordinates and pictures Facilitates the data transfer process, eliminating the need for users to clean up and email data to JPL Allows administrators at JPL to interact with the app and create new projects every time a new land cover map needs to be validated","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.jpl.nasa.gov/nspinto/SciHound","license":null}},{"forgeId":"forge_nasa_npo_51314_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51314-1","sourceUrl":"https://software.nasa.gov/software/NPO-51314-1","confidence":"high"},"type":"software","title":"Deep Reinforcement Learning Model for High Level Science Planning using Formation Flying","abstract":"The software trains algorithms to optimize science return for Earth orbiting missions that use formation flight . The usage of deep learning techniques is uncommon for ground planning systems and has never been used before for onboard systems. The software has been designed with future onboard usage in mind. The software creates a plan for each satellite in the formation to maximize science data return and minimize fuel consumption.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/marsai2/spacecraft-PRO-DeepRL-Trajectory-Planning","license":null}},{"forgeId":"forge_nasa_npo_51334_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51334-1","sourceUrl":"https://software.nasa.gov/software/NPO-51334-1","confidence":"high"},"type":"software","title":"Convolutional Neural Networks for Spacecraft Pose Estimation","abstract":"The software trains and tests convolutional neural networks to determine spacecraft pose estimation. It also contains functionality to perform image preprocessing, data augmentation and tensorflow model compression.The software takes a unique approach that incorporates more image data than other approaches while retaining the original spatial dimensions. Other approaches will down sample images significantly which makes the neural network lose a lot of spatial information retarding robustness.The software is designed to estimate the pose of a spacecraft based on an image of that spacecraft . This includes the relative position and attitude of the target satellite with respect to a chasing satellite. Application of this technology aids function such as active debris removal and formation flying among other applications.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/marsai2/spacecraft-pose-estimation","license":null}},{"forgeId":"forge_nasa_npo_51335_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51335-1","sourceUrl":"https://software.nasa.gov/software/NPO-51335-1","confidence":"high"},"type":"software","title":"Webification of Earth Science Guidance Documentation","abstract":"The goal of this technology is to provide a full stack web application to convert legacy PODAAC user guide documentation from DOCX to HTML, create standardized structure and intelligently manipulate the content of the documents. The web app is to be used as an internal tool for PODAAC Data Engineers. The web application builds upon an open source Python 3 library called Mammoth, which converts DOCX to simple and clean HTML. After conversion to HTML, the application parses the HTML using Beautiful Soup 4, adds Bootstrap CSS styling, wraps all img and table tags in responsive CSS classes, converts any unsupported images to PNGs, converts all FTP links to HTTPS PODAAC Drive links and dynamically creates a hyperlinked table of contents. The HTML output is responsive, mobile friendly and fully self contained in one file. The application is containerized using Docker and orchestrated via Docker Compose. The application uses React for the frontend, Flask for the backend and Nginx as a reverse proxy server.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/podaac/docx-to-html","license":null}},{"forgeId":"forge_nasa_npo_51336_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51336-1","sourceUrl":"https://software.nasa.gov/software/NPO-51336-1","confidence":"high"},"type":"software","title":"Deep Learning and Anomaly Detection in Mars Rover Data","abstract":"The included software is for the data processing and machine learning analysis used inthe project Deep Learning and Anomaly Detection in Mars Rover Data Transmission. The filescontained the signal_processing directory contain Python scripts to organize and clean a datasetbefore passing it into the various machine learning and deep learning models. Themachine_learning directory contains an implementation of an Adversarial Autoencoder, a deeplearning model used in reconstructing data, and a file for a One-Class SVM, which is used indetecting anomalies in the dataset. It also contains a deep neural network implementation, whichis used in classifying the success of different Mars downlink successes.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.jpl.nasa.gov/Audrey/gdsa-machine-learning","license":null}},{"forgeId":"forge_nasa_npo_51337_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51337-1","sourceUrl":"https://software.nasa.gov/software/NPO-51337-1","confidence":"high"},"type":"software","title":"Random Forest Classifier for Real-Time Operations","abstract":"Our team is trying to improve the ground data systems that are used to analyze if data sent from space is received by JPL completely and correctly. There are several points along the journey from space to JPL where data can get lost. Our job is to first determine whether data was lost and, if so, then determine where it was lost. To accomplish this, we first shadowed human GDSA experts to learn their techniques for determining whether a pass sent from space is complete or incomplete. We programmed some of their checks in order to reduce the number of data samples we needed to hand label. Once we had a data set with complete ground truth labels, we employed several machine learning techniques, from random forests to neural networks, in order to analyze and predict the classifications.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.jpl.nasa.gov/Audrey/gdsa-machine-learning","license":null}},{"forgeId":"forge_nasa_npo_51367_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51367-1","sourceUrl":"https://software.nasa.gov/software/NPO-51367-1","confidence":"high"},"type":"software","title":"Probabilistic assessment of surface composition by remote imaging spectroscopy","abstract":"The algorithm is being used primarily as a research tool. We ran experiments demonstrating this strategy with end-to-end accounting and propagation of uncertainty across calibration, reflectance, and mineral detection with closure of error budgets and residuals consistent with uncertainty predictions. To our knowledge, this is the first time statistical validation of second-order uncertainty predictions has been demonstrated in the do- main of remote mineralogy mapping. The approach applies to surface composition measurement in other planetary and Earth science domains.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/davidraythompson/tikorder","license":null}},{"forgeId":"forge_nasa_npo_51390_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51390-1","sourceUrl":"https://software.nasa.gov/software/NPO-51390-1","confidence":"high"},"type":"software","title":"Campaign Analysis Mapping and Planning Tool (CAMP)","abstract":"The Campaign Analysis Mapping and Planning tool (CAMP) provides an advanced web-based geospatial data creation tool for a distributed user base. This tool is designed for science operations to create strategic 'targets' for mission guidance as well as a collaborative tool to make, edit, and share geospatial data.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-AMMOS/MMGIS/tree/master/src/essence/Tools/Draw","license":null}},{"forgeId":"forge_nasa_npo_51406_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51406-1","sourceUrl":"https://software.nasa.gov/software/NPO-51406-1","confidence":"high"},"type":"software","title":"Cloud-based Data Processing System for ECCO","abstract":"The Estimating the Circulation and Climate of the Ocean (ECCO) global ocean state estimation system (https://ecco.jpl.nasa.gov) is the premier tool for synthesizing NASA's diverse Earth system observations into a complete physical description of Earth's time-evolving full-depth ocean and sea ice system. ECCO state estimates are of particular significance to NASA because on their own, all satellite observations, although global in coverage, remain sparse in space and time relative to the inherent scales of ocean variability, and are blind to the oceans interior. With increased streams of data at better spatial resolution the scientific utility of the product is increasingly limited by 1) the inability to automate observing network ingestion and update in a rapid, robust manner, and 2) the lack of capabilities to search, and perform efficient online data analysis . ECCO-Cloud is a NASA Advancing Collaborative Connections for Earth System Science (ACCESS) project. Its goals are to tackle the two limitations by leveraging serverless cloud-based solution to automate product generation and to establish a cloud-based analytics center for the ECCO community for fast access and interactive analysis using prior NASA AIST-funded technology, the Apache Science Data Analytics Platform (https://sdap.apache.org).","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/ECCO-GROUP/ECCO-ACCESS","license":null}},{"forgeId":"forge_nasa_npo_51433_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51433-1","sourceUrl":"https://software.nasa.gov/software/NPO-51433-1","confidence":"high"},"type":"software","title":"Raytracing Atmospheric Delay Estimation for RADAR - RAiDER","abstract":"RAiDER is a Python package that contains tools to calculate tropospheric radar slant delays for both airborne and space borne sensors. It estimates delays by calculating the index of refractivity at the native weather model grid nodes and then integrating along the ray path of the signal, from the ground pixel to the sensor location (up to a reference height).","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/dbekaert/RAiDER","license":null}},{"forgeId":"forge_nasa_npo_51451_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51451-1","sourceUrl":"https://software.nasa.gov/software/NPO-51451-1","confidence":"high"},"type":"software","title":"LAMP: Large-scale Autonomous Mapping and Positioning","abstract":"The software, Large-scale Autonomous Mapping and Positioning (LAMP) is a complete package for Simultaneous Localization and Mapping (SLAM) that is adaptable to a large range of robotic systems for exploration of unknown indoor and underground environments. LAMP will process sensor inputs, such as lidar scans, IMU, and odometry estimates, and produce an accurate global location, global map and global pose-graph. This capability is also extended to multi-robots systems, through a centralized fusion of pose-graphs, with low data -rate communications of sparse pose-graph information.The lidar-odometry front-end can be leveraged as part of LAMP, or separately, to produce an accurate odometry estimate, by processing lidar scans, along with IMU and other, less accurate, odometry estimates. LAMP is designed to be a modular architecture and can have modules adapted to include different information into the global pose-graph, to leverage what sensing information is available for maximum localization accuracy. LAMP runs in the ROS ecosystem and expects sensor inputs as ROS messages, and outputs information as ROS messages.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NeBula-Autonomy/LAMP and https://github.com/NeBula-Autonomy/LOCUS","license":null}},{"forgeId":"forge_nasa_npo_51454_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51454-1","sourceUrl":"https://software.nasa.gov/software/NPO-51454-1","confidence":"high"},"type":"software","title":"FRINGE - Fine Resolution InSAR using Generalized Eigenvectors","abstract":"We present FRInGE, our newly developed InSAR time-series analysis toolbox which implements the state-of-the-art methods to efficiently explore the full capability of modern SAR observations to produce ground displacement time-series at full resolution of SAR images at pixels dominated by Permanent Scatterers (PS) or Distributed Scatterers (DS). For DS pixels, FRInGE uses all possible interferometric pairs. Starting from a coregistered stack of SAR images, FRInGE evaluates the temporal distribution of the backscatter of SAR images at each pixel to identify statistically self-similar neighbors in a pre-defined window. The neighborhood map also helps to identify PS pixels. FRInGE forms a full covariance matrix of interferometric pairs for each DS pixel over its neighborhood. The wrapped phase time-series of the DS pixels is estimated as the phase of the generalized eigen vector corresponding to the largest eigen values of the covariance matrix. The phase series of the PS pixels are also extracted and together with the estimated phase series of DS pixels can be unwrapped through a minimum span tree network using two-dimensional available unwrappers. The estimated unwrapped phase time-series of DS and PS pixels inclusive of all components (e.g., ground displacement, geometrical residuals, propagation delay) can be post-processed through already available tools to estimate displacement time-series. FRInGE enables efficient generation of a full coherence matrix (all possible pairs) which can be used for Damage Proxy Mapping and change detection.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/isce-framework/fringe","license":null}},{"forgeId":"forge_nasa_npo_51495_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51495-1","sourceUrl":"https://software.nasa.gov/software/NPO-51495-1","confidence":"high"},"type":"software","title":"Operational Cloud Store (OCS)","abstract":"The Mars 2020 Mission's primary objective is to collect 20 geographically unique samples during its prime mission of one and a quarter Martian years, or just over 2 Earth years. Mission planners determined the project needed to develop a system that would enable the operations team to analyze engineering and science data, make science decisions, select viable rover targets at a millimeter resolution and validate an uplink bundle for a car sized rover with more complex science instruments than any previous Mars surface mission. All this had to be done within a five hour time frame. Doing this with a small team would be a challenge, but this had to be accomplished by a large team of engineers and scientists located across North America and Europe. Achieving this level of operational efficiency was unheard of in the prime mission. In addition, the mission had another set of requirements that had nothing to do with surface operations; the Mars 2020 Ground Data System (GDS) was also expected to comply with a new set of security requirements to keep up with the ever changing cybersecurity landscape. The Mars 2020 Ground Data System (GDS) is a re-architected version of the Mars Science Laboratory GDS. The primary goal was to integrate the lessons learned from previous Mars surface missions, accommodate a set of new requirements and capabilities required to ensure mission success, and comply with a new set of cybersecurity controls. The new architecture includes several unique qualities including a data lake, language-agnostic system-wide event-based operations, containerization, automated deployment, network segmentation, infrastructure-as-code, API-driven interfaces, and the first Mars surface GDS to operate primarily in the cloud. The new architecture enabled greater access to the systems data, tighter integration with the operations team, and a higher level of traceability. The availability of the data also enabled a new set of capabilities previously not possible on surface missions. These new capabilities include an autonomous data to information, pipeline for downlink analysis , horizontal scaling of science data processing capabilities, autonomous round trip data tracking of science and engineering data, integration of flight system state into the tactical planning cycle, high fidelity targeting utilizing kinematic data, and hierarchical image and 3d meshes data representations. This paper will introduce the requirements for the Mars 2020 Mission, the heritage architecture, and the rationale for the changes to achieve the new architecture. The paper will continue to describe the fundamental changes made to the GDS architecture, how these changes enabled a more tightly integrated GDS, and the new capabilities","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.jpl.nasa.gov/M2020-CS3/ocs-python-client;  https://github.jpl.nasa.gov/M2020-CS3/ocs-js-client; and https://github.jpl.nasa.gov/M2020-CS3/m2020-data-lake","license":null}},{"forgeId":"forge_nasa_npo_51496_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51496-1","sourceUrl":"https://software.nasa.gov/software/NPO-51496-1","confidence":"high"},"type":"software","title":"NASA PDS - NSSDCA Delivery Software","abstract":"NSSDCA Delivery Tool is responsible for the generation of two information packages for ensuring the integrity of the archive with respect to the NSSDCA and Open Archival Information System (OAIS) reference model [6]. The packages are intended to be generated by Discipline Node staff any time new data is released into the PDS, but can also be executed retroactively for data that has not previously been submitted. Once generated, the Archive Information Package and Submission package are both validated by the PDS Engineering Node, and the Submission package is delivered to the NSSDCA. The two packages are the Archive Information Package and Submission Information Package.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-PDS/deep-archive","license":null}},{"forgeId":"forge_nasa_npo_51508_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51508-1","sourceUrl":"https://software.nasa.gov/software/NPO-51508-1","confidence":"high"},"type":"software","title":"Methods for Detecting Novel Geology in Mastcam Multispectral Observations","abstract":"Our novelty detection work is implemented in Python using the Keras and TensorFlow machine learning libraries. We created a dataset of Mastcam multispectral images and selected known examples of novel observations to evaluate the novelty detection performance of the compared methods.This is the first work that proposes to train autoencoders using a loss function that explicitly captures spatial properties in the input (e.g., structural similarity index). Additionally, this is the first work to characterize the influence of the autoencoder loss function on the type of novel features that can be detected.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/JPLMLIA/mastcam-noveltydet","license":null}},{"forgeId":"forge_nasa_npo_51511_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51511-1","sourceUrl":"https://software.nasa.gov/software/NPO-51511-1","confidence":"high"},"type":"software","title":"Simulation -based uncertainty quantification for atmospheric sounding","abstract":"Complex retrieval algorithms for converting satellite-observed spectral radiances into estimates of geophysical quantities are common and important parts of the remote sensing data processing pipeline. The scientific utility of retrieval data products is bolstered by a thorough understanding of the retrieval system's operating characteristics. Each retrieval strategy presents unique challenges and requirements, but a common approach involves a physical and/or statistical model with a computational inverse method. Variability in atmospheric and surface processes, as well as in the satellite measurements themselves, contribute to the statistical properties of retrieval algorithms. Specific algorithm implementation choices can also impact the algorithm's accuracy and precision. This probabilistic and computational pipeline can be studied in depth with Monte Carlo simulation experiments of the satellite observing system using ensembles of realistic true states. This work develops methodology, software, and practices that facilitate design and post-processing of these simulation experiments.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/L2UQ","license":null}},{"forgeId":"forge_nasa_npo_51530_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51530-1","sourceUrl":"https://software.nasa.gov/software/NPO-51530-1","confidence":"high"},"type":"software","title":"BodyDataReader","abstract":"BodyDataReader is an ephemeris and physical constants reader that makes it easy to retrieve data on any body in the solar system.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/kaelamartin/BodyDataReader","license":null}},{"forgeId":"forge_nasa_npo_51540_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51540-1","sourceUrl":"https://software.nasa.gov/software/NPO-51540-1","confidence":"high"},"type":"software","title":"Comprehensive Analysis of Time Series Forecasting Using Neural Networks","abstract":"The objective was to develop advanced machine learning methods to predict future gas production in tight rock unconventional reservoirs. A particular focus was early prediction, over a range of horizons, only from data first weeks to months. The developed techniques are important for the objective.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/manitadayon/MTSCNeuralForecast","license":null}},{"forgeId":"forge_nasa_npo_51572_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51572-1","sourceUrl":"https://software.nasa.gov/software/NPO-51572-1","confidence":"high"},"type":"software","title":"PDS DOI Service","abstract":"The PDS Data Object Identifier (DOI) service is responsible for the management of DOIs for the Planetary Data System. Currently, the PDS is attempting to acquire DOIs for any new data sets entering the system. This software will help automate the management of those DOIs.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-PDS/doi-service","license":null}},{"forgeId":"forge_nasa_npo_51578_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51578-1","sourceUrl":"https://software.nasa.gov/software/NPO-51578-1","confidence":"high"},"type":"software","title":"Machine Learning Test and Evaluation for Learning with Less Labels (LwLL)","abstract":"The software automatically generates an environment to test, graph, and collect metrics about machine learning software. The purpose is to quantitatively assess a performer (institution) and their machine learning code to evaluate whether they are using orders of magnitude less data for machine learning while not sacrificing accuracy.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/jpl-lwll/lwll-api","license":null}},{"forgeId":"forge_nasa_npo_51593_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51593-1","sourceUrl":"https://software.nasa.gov/software/NPO-51593-1","confidence":"high"},"type":"software","title":"A simulation package for underwater hydrothermal vents","abstract":"This software simulates the shape, appearance and composition of hydrothermal vents, and the structure of an instrument package designed to study vents","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://gitlab.com/invader-mission/vision-group/invader_ros","license":null}},{"forgeId":"forge_nasa_npo_51600_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51600-1","sourceUrl":"https://software.nasa.gov/software/NPO-51600-1","confidence":"high"},"type":"software","title":"mrcal - a toolkit to precisely solve calibration and structure-from-motion problems","abstract":"Mrcal contains a C library for 3D geometry operations and lens projection/unprojection operations, supporting many camera models, including JPL-specific ones that nobody else supports. Functions report the values and the gradients in respect to the input variables. The C library has higher-level functions that wrap the core in a nonlinear optimization to be able to fit models and geometries to data . This is a core for camera calibration and SFM problems. The optimization is thorough. It solves for the geometry of the world and/or of the cameras and/or for the lens parameters of the cameras and/or for the shape of the object being observed. The optimization propagates all the uncertainties, and returns the uncertainties of the solution.There's a Python library to read/write camera models from/to disk, and to manipulate them invarious ways. There's a Python wrapper for the main components of the C library. These wrappers provide lots and lots of feedback to allow the user to quantify the uncertainty of the solution. Lots of tools are available to produce all sorts of visualizations about calibrations, camera models, their differences, and so on.There are lots of command line tools that generally exercise the Python library. These allow the user to quickly process their data .","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"http://mrcal.secretsauce.net","license":null}},{"forgeId":"forge_nasa_npo_51796_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51796-1","sourceUrl":"https://software.nasa.gov/software/NPO-51796-1","confidence":"high"},"type":"software","title":"Viewshed Tool (a CAMP/MMGIS plugin)","abstract":"This software performs real-time viewshed analysis from a tiled digital elevation model in a web-based mapping system.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-AMMOS/MMGIS or https://github.com/NASA-AMMOS/MMGIS/tree/master/src/essence/Tools/Viewshed","license":null}},{"forgeId":"forge_nasa_npo_51913_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51913-1","sourceUrl":"https://software.nasa.gov/software/NPO-51913-1","confidence":"high"},"type":"software","title":"A NASA Assurance Standards Workflow Assistant (ANASWA)","abstract":"The purpose of this software is to show, by means of an operational (albeit incomplete) prototype, the feasibility of software that would help missions develop a Safety and Mission Assurance Plan that complies with NASA standards (and others, if relevant, e.g., OSHA).As a side-effect of its creation, it brings to bear considerations of clarity, consistency and completeness upon the NASA documentation from which it draws its information.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://sourceforge.net/projects/nasa-mbma-template-tool/","license":null}},{"forgeId":"forge_nasa_npo_51916_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51916-1","sourceUrl":"https://software.nasa.gov/software/NPO-51916-1","confidence":"high"},"type":"software","title":"Flood event monitoring from in-situ and satellite data using deep learning","abstract":"The automated flood monitoring can be performed using deep neural network models that are trained on historical, known flood events.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://gitlab.com/esdt/jpl/models","license":null}},{"forgeId":"forge_nasa_npo_51921_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51921-1","sourceUrl":"https://software.nasa.gov/software/NPO-51921-1","confidence":"high"},"type":"software","title":"ION Network Model and Browser-based Configuration Tools","abstract":"This package consists of a set of tools that allow a mission planner (without detailed protocol knowledge) to lay out the topology and basic link characteristics of a mission , create a json file describing that network, and then pass that to a protocol engineer for importing into the ION Configuration Tool for the detailed development of ION configuration files for all the nodes in the network. The tools are the DTN Network Model tool, and the ION Configuration Tool (detailed in NTR-50751)","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/nasa-jpl/ion-config-tool  and https://github.com/nasa-jpl/ion-network-model","license":null}},{"forgeId":"forge_nasa_npo_51929_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51929-1","sourceUrl":"https://software.nasa.gov/software/NPO-51929-1","confidence":"high"},"type":"software","title":"Tuning Optimizing Genetic Algorithm (TOGA)","abstract":"Tuning Optimizing Genetic Algorithm (TOGA) is a lightweight software package for distributed GA optimization of black-box models and algorithms. It can be used when rapid optimization of algorithms with a large number of parameters is necessary, and massively parallel compute is available.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/JPLMLIA/TOGA","license":null}},{"forgeId":"forge_nasa_npo_51944_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51944-1","sourceUrl":"https://software.nasa.gov/software/NPO-51944-1","confidence":"high"},"type":"software","title":"ViewCubeHelper (ProtoSpace System v2.0.1)","abstract":"For engineers and non-engineers who work with CAD models, ProtoSpace is a multi-platform tool that allows users to collectively view and manipulate models to save cost and time in the design and assembly processes. Unlike existing CAD tools that cannot support collaborative, persistent sessions in augmented reality (AR) and on the web, ProtoSpace collectively sees and solves problems before they happen. The ProtoSpace system not only accommodates engineers working with CAD, but also consists of a procedural training system, PICARD, that allows for users to train and execute procedures using the ProtoSpace system, both in augmented reality (AR) and on a web-training platform.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa-jpl/ViewCubeHelper","license":null}},{"forgeId":"forge_nasa_npo_51949_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51949-1","sourceUrl":"https://software.nasa.gov/software/NPO-51949-1","confidence":"high"},"type":"software","title":"TROPESS Open Source Utility tools","abstract":"Each Earth science missions standard products differ from each other. There are no common utility tools that can be used from one project to another. So, in order to help end user / scientist to fully utilize the TROPESS standard products we realized that we must also provide the community some utility tools.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/NASA-TROPESS","license":null}},{"forgeId":"forge_nasa_npo_51956_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51956-1","sourceUrl":"https://software.nasa.gov/software/NPO-51956-1","confidence":"high"},"type":"software","title":"NISAR Science Notebooks","abstract":"The NISAR Science Team has been developing algorithms described in the Algorithm Theoretical Basis Documents (ATBD) and implemented as Jupyter Notebooks. Prior to NISAR launch, Jupyter Notebooks will be tested with representative NISAR data (e.g., UAVSAR-NISAR simulated data or Sentinel-1 data ). Notebooks will be shared with the JPL NISAR Project.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://gitlab.com/nisar-science-algorithms","license":null}},{"forgeId":"forge_nasa_npo_51960_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51960-1","sourceUrl":"https://software.nasa.gov/software/NPO-51960-1","confidence":"high"},"type":"software","title":"Cassini RADAR SAR Processor, Preprocessor, and Topography from SAR (SARTopo) Processor.","abstract":"The Cassini RADAR instrument onboard the Cassini Orbiter is currently collecting SAR Imagery of the surface of Saturn's largest moon, Titan. This paper describes the ground processing of Cassini SAR data. We focus upon the unusual features of the data and how these features impact the processing. We exhibit a data dependent mechanism we have implemented for eliminating artifacts due to attitude and ephemeris knowledge error. Finally we describe how we trade-off SAR performance vs. area of coverage when we design our spacecraft pointing profiles.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa-jpl/Cassini_RADAR_Software","license":null}},{"forgeId":"forge_nasa_npo_51963_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51963-1","sourceUrl":"https://software.nasa.gov/software/NPO-51963-1","confidence":"high"},"type":"software","title":"Waveport Scattering Library","abstract":"The Waveport Scattering Library is a collection of equations, derivations, and Matlab codes on selected topics in electromagnetic scattering. While this field is rich with problems that have been solved ana- lytically and numerically, coding these solutions from papers and textbooks can be quite difficult. As a result, many useful methods and tools are out of reach to all but the most practiced investigators. This work started with a personal collection of notes and codes with the idea of creating a consistent library with which analysis and new routines could be completed and checked more quickly.The topics of the library follow closely the textbooks of Chew, Tsang, Kong, and Ulaby: - Green's functions- Spherical wave functions- Spherical wave function rotation and translation- S-matrix and T-matrix scattering- Facet scattering under the Kirchhoff approximation - Fast Multipole Method operators- Generation of rough surfaces and random objects- Geometric (ray-tracing) scattering solutions- Coordinate transforms and special functions.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa-jpl/Waveport","license":null}},{"forgeId":"forge_nasa_npo_51981_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51981-1","sourceUrl":"https://software.nasa.gov/software/NPO-51981-1","confidence":"high"},"type":"software","title":"VISTA - Visualization for Telemetry Analysis","abstract":"VISTA is a modern web-based application for telemetry visualization and inspection. VISTA supports real-time and historical telemetry access for both on-site and remote users via a simple web GUI. It allows exploration and comparison of telemetry data from multiple sources, and allows teams to create, persist, and share informational displays for use among geographically distributed teams.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/NASA-AMMOS/openmct-mcws","license":null}},{"forgeId":"forge_nasa_npo_51992_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-51992-1","sourceUrl":"https://software.nasa.gov/software/NPO-51992-1","confidence":"high"},"type":"software","title":"PODAAC Level 2 Subsetter","abstract":"This software is capable of spatial, temporal, and variable subsetting of NetCDF Level 2 data products. Provides an adapter for the EOSDIS Harmony API https://harmony.earthdata.nasa.gov/","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/podaac/l2ss-py","license":null}},{"forgeId":"forge_nasa_npo_52010_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52010-1","sourceUrl":"https://software.nasa.gov/software/NPO-52010-1","confidence":"high"},"type":"software","title":"LithoSphere - A tiled, 3D planetary web-based GIS library","abstract":"Lithosphere is a web-based 3D visualization tool capable of rendering raster and vector open source planetary datasets.The software supports viewing any spherical planetary body (Earth, Mars, Europa, etc.) in three dimensions (3D) including both raster and vector datasets. It is a standalone web-based viewer that supports open source formats like Tile Map Service (TMS), 3D tiles, meshes, and GeoJSON formats. It supports mapping 2D vectors to the 3D surface or rendering vectors using their own 3D coordinates. This software does not rely on commercial data providers.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-AMMOS/LithoSphere","license":null}},{"forgeId":"forge_nasa_npo_52029_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52029-1","sourceUrl":"https://software.nasa.gov/software/NPO-52029-1","confidence":"high"},"type":"software","title":"Kawin: A Kampmann-Wagner Numerical (KWN) phase precipitation and coarsening modeling code","abstract":"Kawin is an open-source Python library for simulating precipitation behavior in alloys using the Kampmann-Wagner Numerical (KWN) model coupled with Calphad-based thermodynamics. The Calphad coupling is done through the open-source PyCalphad software, which allows for the usage of .TDB databases for thermodynamic and mobility parameters; however, this package also allows the user the define their own thermodynamic calculations. Methods for creating surrogate models on top of the thermodynamic calculations are also introduced in this package, which can greatly reduce computational time. The usage of surrogate models expands the applications of the KWN model by allowing for quicker exploration and/or calibration of model parameters and incorporation into larger scale simulations.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/materialsgenomefoundation/kawin","license":null}},{"forgeId":"forge_nasa_npo_52045_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52045-1","sourceUrl":"https://software.nasa.gov/software/NPO-52045-1","confidence":"high"},"type":"software","title":"Planetary Data System Image Atlas IV","abstract":"- Metadata-driven search of IMG's ~2PB of planetary image data- Bulk downloading capability following the \"shopping cart\" paradigm- File explorer for easy navigation of IMG's archives- Geospatial search- Machine learning-driven feature classification- Interactive label viewer","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/NASA-PDS/atlas4","license":null}},{"forgeId":"forge_nasa_npo_52048_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52048-1","sourceUrl":"https://software.nasa.gov/software/NPO-52048-1","confidence":"high"},"type":"software","title":"Event-Based Visual-Inertial Odometry","abstract":"Estimating the position of a robot (localization) is an important precursor to enabling a robot to navigate autonomously. Traditional camera-based localization methods fail when the robot is moving fast (motion blur) or when the robot is in very dark or bright environments (over/undersaturated pixels). An event camera is a new type of imaging sensor that reports changes in pixel brightness per pixel independently and asynchronously with microsecond resolution and overcomes both of these problems. However, the asynchronous nature of the data is a challenge for traditional \"synchronous\" pipelines that receive a full image at a time. This software offers a couple of approaches to processing this asynchronous event stream to estimate the position of an event camera.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/jpl-x/x_events and  https://github.com/jpl-x/x_evaluate","license":null}},{"forgeId":"forge_nasa_npo_52050_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52050-1","sourceUrl":"https://software.nasa.gov/software/NPO-52050-1","confidence":"high"},"type":"software","title":"SAR Exploration Notebooks","abstract":"The notebooks enable quick visualization and interpretation of false-color SAR RGB images, and InSAR correlation images. Notebooks are run in Google Colab and the first cells will set up the python environment. Users are asked to upload image samples into their Google Drive for easy access from Google Colab.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/anniepeacock/DANSAR","license":null}},{"forgeId":"forge_nasa_npo_52061_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52061-1","sourceUrl":"https://software.nasa.gov/software/NPO-52061-1","confidence":"high"},"type":"software","title":"AIT (AMMOS Instrument Toolkit) Sequence Editor","abstract":"The AMMOS Instrument Toolkit (AIT) is a Python-based software suite developed to handle Ground Data System (GDS), Electronic Ground Support Equipment (EGSE), commanding, telemetry uplink/downlink, and sequencing for JPL International Space Station and CubeSat Missions. It is a generalization and expansion of tools developed for a number of JPL ISS missions. The AIT Toolkit is currently using a generic editor to edit the sequence files and users have to manually verify and validate each command entered against the AIT command dictionary. AIT Editor provides sequence editing capabilities for AMMOS Instrument Toolkit software toolset. The editor is using AIT command dictionary to provide command validation and completion capability to assist users while working with AIT sequences. The editor will also provide a loading and saving of seq.json capability for the generated sequences.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://dev.azure.com/NASA-AMMOS/_git/AIT-Editor","license":null}},{"forgeId":"forge_nasa_npo_52065_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52065-1","sourceUrl":"https://software.nasa.gov/software/NPO-52065-1","confidence":"high"},"type":"software","title":"PO.DAAC Open Software Development","abstract":"PO.DAAC Software accomplishes the ingest, archive, and management of data at PO.DAAC on premise and i the earthdata cloud","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/podaac","license":null}},{"forgeId":"forge_nasa_npo_52071_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52071-1","sourceUrl":"https://software.nasa.gov/software/NPO-52071-1","confidence":"high"},"type":"software","title":"Cloud-based Data Match-Up Service (CDMS) In Situ Data Services","abstract":"The CDMS In Situ Data Services will be utilized by in situ data providers to provide a standardized interface to in situ data that will then be used for satellite -to-in situ data match up.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/apache/incubator-sdap-in-situ-data-services","license":null}},{"forgeId":"forge_nasa_npo_52074_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52074-1","sourceUrl":"https://software.nasa.gov/software/NPO-52074-1","confidence":"high"},"type":"software","title":"MRSDS: Methane Research Science Data System","abstract":"While methane observing systems are proliferating there remain serious gaps in terms of data systems and analytic frameworks that can fully exploit them. Through our collective exposure to remote-sensing based methane research and applied science we assess that currently there is no information system technology that can address the improvements in data analysis latency, discoverability, data fusion and on-demand analytics required by the research community and public and private sector decision makers. We propose to develop a Multi-scale Methane Analytic Framework (M2AF) that can help address one of the more persistent challenges in Earth System Science: understanding the causes for the changing atmospheric growth rate of methane. M2AF will lay the foundation for extending existing methane analysis systems beyond their current experimental states, reduce latency and cost of methane data analysis and improve accessibility by researchers and decision makers. To meet these needs M2AF will advance and uniquely bring together multiple observational data sets, models and analysis methods to estimate methane fluxes across three key, overlapping spatial scales in order to disentangle confounding processes: 1) global to regional scale, 2) regional to local scale, and 3) facility (point source scale). M2AF will offer workflow optimization and management tools to improve automation, data search and discovery tools for improved access to intermediate and final products, as well as on-demand analytics and web- based tools for interacting with diverse data sets. MRSDS is the output of the M2AF project.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/mrsds","license":null}},{"forgeId":"forge_nasa_npo_52083_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52083-1","sourceUrl":"https://software.nasa.gov/software/NPO-52083-1","confidence":"high"},"type":"software","title":"lowfssim: integrated model of the LOWFS system on the Roman Coronagraph Instrument","abstract":"lowfssim is the official model of the LOWFS/C system on the Roman Coronagraph Instrument. It is a model of the system including sensor and actuators in the system. The model is used to form CBEs on mission requirements and validate testbed experiments. Ad-hoc questions about the system and more generally integrated modeling inquiries are answered using the model.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa-jpl/lowfssim","license":null}},{"forgeId":"forge_nasa_npo_52101_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52101-1","sourceUrl":"https://software.nasa.gov/software/NPO-52101-1","confidence":"high"},"type":"software","title":"OPERA SDS (Observational Products for End-Users from Remote Sensing Analysis Science Data System) software","abstract":"The OPERA project was funded by NASA in direct response to recommendations issued by the Satellite Needs Working Group (SNWG), which every two years issues a report to NASA and other federal agencies listing new desirable products that should be produced to better monitor and forecast the state of the Earth system. The last survey, conducted in 2018-2019, proposed nine new activities, three of which are covered by the OPERA scope (Surface Water Extent, Land Surface Disturbance and Displacement). One of the funding requirements issued by SNWG is that all OPERA software be made available to the community as Open Source.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/?q=opera-sds","license":null}},{"forgeId":"forge_nasa_npo_52110_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52110-1","sourceUrl":"https://software.nasa.gov/software/NPO-52110-1","confidence":"high"},"type":"software","title":"In-situ Data Transformation and Ingestion Software Tool","abstract":"A generalized tool that would let the user to scan through the in-situ netCDF data , select the variables of interest together with associated coordinate data and transform/export them into a columnar format (such as CSV file format) that can then easily be assimilated in other COVERAGE software tools and services. The tool also allows for and undertakes necessary standardization and reconciliation of data variable names consistent with CF-standard names as necessary for output.The generalized in-situ data transformation and ingestion tool is currently used to extract SPURS data (which is in the netCDF format) via the PODAAC api (https://podaac.jpl.nasa.gov/api/cmr/) and is loaded as python data frame and then exported to a CSV file.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/ceos-coverage/in-situ-converter","license":null}},{"forgeId":"forge_nasa_npo_52123_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52123-1","sourceUrl":"https://software.nasa.gov/software/NPO-52123-1","confidence":"high"},"type":"software","title":"Embedded software GCC/gcov lines of code coverage data extraction from the actual embedded system, without requiring a file system, or an operating system, or standard C libraries.","abstract":"Measuring test effectiveness includes measuring lines of code coverage. This is historically difficult in embedded systems under realistic conditions. Sometimes it is measured partially or not at all. This software allows gcov lines of code coverage data to be extracted from software compiled with GCC and running on embedded systems, without requiring a file system, operating system, or even standard C libraries. This software provides the ability to select data output via serial port or memory dump or single output file, and provides other configuration options for adaptation to the user's specific environment. And it provides a complete, encapsulated, flexible, portable, and documented method.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa-jpl/embedded-gcov","license":null}},{"forgeId":"forge_nasa_npo_52134_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52134-1","sourceUrl":"https://software.nasa.gov/software/NPO-52134-1","confidence":"high"},"type":"software","title":"CryoFab: Harmonic Analysis of Isotropic Fields on the Sphere with Arbitrary Masks","abstract":"CryoFaB, derives a harmonic basis adapted to the survey geometry of a galaxy survey. It does this in 2Don the sphere and 3D similar to a spherical Fourier-Bessel decomposition. CryoFaB can also be used to calculate the pixel window and effect of the geometry on the power spectrum. The power spectrum covariance matrix can also be calculated.CryoFaB aims to handle wide-angle effects in the power spectrum measurement of galaxy surveys such as SPHEREx, Euclid, and Roman","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/hsgg/CryoFaBs.jl/","license":null}},{"forgeId":"forge_nasa_npo_52154_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52154-1","sourceUrl":"https://software.nasa.gov/software/NPO-52154-1","confidence":"high"},"type":"software","title":"An Implementation of the JPEG Image Compression Software with improved Safety","abstract":"Performs lossy compression and decompression of images with increased safety compared to previous software.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/abcouwer-jpl/jsc","license":null}},{"forgeId":"forge_nasa_npo_52159_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52159-1","sourceUrl":"https://software.nasa.gov/software/NPO-52159-1","confidence":"high"},"type":"software","title":"Unity - Multi-tenant, managed product development, generation, and analysis platform","abstract":"The software brings together 2 key mission activities: Algorithm Development, Data Processing and Storage, and Data use and analysis . The software creates a platform for algorithm developers to 'login' and develop production quality algorithms through the use of standard tools, interfaces, and packaging that is automated on behalf of the user. The packages seamlessly fit into production quality processing systems (think: run at scale on thousands of nodes) with little effort from the algorithm developers. the same algorithm developed is used in the production of 'standard data products' by a mission, fit for science usage and archival. Lastly, the same platform used to create the algorithms and data products is used to analyze and validate the products as well. The cohesive ecosystem for development, generation, and validation is designed to speed up the development effort and enable evolution of back end components over time.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/unity-sds","license":null}},{"forgeId":"forge_nasa_npo_52169_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52169-1","sourceUrl":"https://software.nasa.gov/software/NPO-52169-1","confidence":"high"},"type":"software","title":"Topographical Landmarks for Ground-Level Terrain Relative Navigation on Mars","abstract":"We have developed an automated approach to localization in which the rover makes bearing-only measurements to geographic features in its surroundings (hills, boulders, peaked ridge-lines, etc.). When the location of these landmarks can be cross-referenced with a map of Mars, the resulting solution will be globally registered and will help correct any drift during visual-odometry-aided drives.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/rschwa6308/Landmark-Based-TRN","license":null}},{"forgeId":"forge_nasa_npo_52170_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52170-1","sourceUrl":"https://software.nasa.gov/software/NPO-52170-1","confidence":"high"},"type":"software","title":"gpsGUI: EFIS-style GPS and IMU Visualization , Logging and Log-Playback Software","abstract":"The gpsGUI software provides real-time Electronic Flight Instrument System (\"EFIS\") style visualization of GPS and IMU data coming over a binary TCP/IP stream. gpsGUI can be used as a stand-alone graphical program, or, various pieces can be incorporated into existing codebases using standard c++ interfaces. The software is written with an emphasis on thread-safe real-time operation, and is designed for critical operations where corrupted or missed data would not be tolerable.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa-jpl/gpsGUI","license":null}},{"forgeId":"forge_nasa_npo_52175_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52175-1","sourceUrl":"https://software.nasa.gov/software/NPO-52175-1","confidence":"high"},"type":"software","title":"AFIDS Automated Fusion of Image Data System","abstract":"AFIDS Open Source AbstractAFIDS (Automated Fusion of Image Data System) is a library subset of the JPL VICAR (Video Image Communication and Retrieval) image processing system. VICAR began development in the 1960s in support of NASA/JPL's mission to explore the solar system. AFIDS forked in 2000 to focus on Earth orbital image co-registration in support of the NASA Earth Sciences program. Today, the effort is to re-integrate AFIDS back into VICAR and release it through the VICAR Open Source program. -AFIDS brings the concept of \"georeferenced map images\" to VICAR through the AFIDS \"VicarGT\" format (a compatible version of the industry standard \"GeoTIFF\" format). - AFIDS provides the ability to Ortho-Rectify and Co-Register orbital satellite imagery (using automated and customizable software).- AFIDS provides the image processing tools to perform scientific analysis and research of co-registered imagery (for example: Precision Change Detection).- AFIDS is rooted in Earth Science (supporting MISR, MAIA, CloudSat, EMIT, ECOSTRESS, OCO2, more), but also provides mapping support for Mars and Planetary orbital datasets (e.g., Mars Nest; AFIDS Mosaicking).AFIDS is a library collection of 200+ vicar-based programs and scripts, but also relies upon JPL and external 3rd party libraries including GDAL, GeoTIFF, Python, JPL GEOCAL, NASA NAIF/SPICE, and a variety of global databases.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/NASA-AMMOS/VICAR/","license":null}},{"forgeId":"forge_nasa_npo_52198_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52198-1","sourceUrl":"https://software.nasa.gov/software/NPO-52198-1","confidence":"high"},"type":"software","title":"Introduction of Collaborative State Estimation for Multiple Agents into a Thermal/Visual-Inertial State Estimation Framework","abstract":"This software is a modification to the X framework that enable multi robot collaboration.It adds a communication class that make the program able to exchange messages with other agents in the network. It extends the MSCKF update class to work with collaborative MSCKF updates, by using the new Covariance Intersection class. It implements a multi SLAM class to handle collaborative SLAM updates. Moreover, to use the data coming from the other robots the program implement a place recognition class that creates the messages needed by the collaborative update methods.The software also includes a third party code, that we slightly modified to perform photometric calibration of thermal images.To use this software, use the same settings as the original version of X, example configuration files for setting the parameters are included in the repository. Note that to run a multi drone system using the ROS wrapper, the vio_multi.launch file must be used. The number of UAVs the program have to run can be specified by using \"vio_multi.launch nr:=#ofUAVs\"","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/jpl-x/x_multi_agent","license":null}},{"forgeId":"forge_nasa_npo_52219_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52219-1","sourceUrl":"https://software.nasa.gov/software/NPO-52219-1","confidence":"high"},"type":"software","title":"EMIT Science Data System","abstract":"This software suite facilitates the mapping of Earth surface mineralogy from remote imaging spectroscopy data , along with aggregation and interpretation of the use of these data in Earth System Models.Facilitates the analyses of the EMIT objectives:1. The net contribution of mineral dust to regional and global radiative forcing is to warm the atmosphere (positive forcing)2. The impact of mineral dust on regional precipitation and radiative forcing will promote the expansion of dust source regions.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/emit-sds","license":null}},{"forgeId":"forge_nasa_npo_52220_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52220-1","sourceUrl":"https://software.nasa.gov/software/NPO-52220-1","confidence":"high"},"type":"software","title":"Stellar: A Web-based Design System for Information Dense Applications in Spacecraft Operations","abstract":"Modern web applications use a variety of popular libraries for user-interface design . The most common today include Material by Google, and Bootstrap by Twitter. These libraries expose common elements of a standardized design that can be used across applications (e.g. button, input field, etc.). When building applications for spacecraft operations the main problem that arises with these libraries is they are optimized for mobile, and their elements take up more screen space than necessary. The Stellar software aims to solve this problem by providing design and implementation of elements that are more efficient with screen space so more information can be displayed in smaller screen areas. This increases overall usability, as more data is available without having to scroll or increase the screen size.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa-jpl/stellar or https://github.com/nasa-jpl/react-stellar","license":null}},{"forgeId":"forge_nasa_npo_52250_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52250-1","sourceUrl":"https://software.nasa.gov/software/NPO-52250-1","confidence":"high"},"type":"software","title":"Cross-Institutional Open-source Collaborative for NASA's Multi-Mission Algorithm and Analysis Platform (MAAP) High-End Computing (HEC) and Amazon Web Services (AWS) Development, Integration and Deployment","abstract":"The MAAP development team will develop extensions to the MAAP to enable deployment of analysis requests across both AWS and NASA HECC systems (such as Pleiades). The development team will then leverage existing NASA efforts that have already begun enabling these capabilities and adapt them for MAAP use. These include investments in connecting on-premise HECC to AWS infrastructure and existing AIST efforts that are developing AWS and Pleiades interoperability for MAAP-like approaches with Jupyer-based notebook front ends. The development team will also demonstrate how biomass analysis can be optimized by exploiting the rapid agility of analysis in AWS while dispatching less time-sensitive bulk analysis to run on lower-cost NASA HECC platforms. Without this capability, users would have to understand the complex nuances of porting science analysis onto NASA HECC vs running in AWS cloud. This capability would enable users to run on both systems via their Jupyter science notebook interface without the need to become experts in AWS and NASA HECC. The development team will also continue the open science approach of enabling algorithm development and analysis to run across cloud and HECC platforms to foster broader exploitation of NASA compute capabilities and investments. This effort will continue MAAP's vision of development collaboration, currently utilizing teams at JPL, MSFC, and UMD and now with key staff at ARC under the NAS Division. The development team will also work with the MAAP UWG to extend the analysis use cases to those that naturally fit well with processing on NASA HECC. Unlike existing efforts on NASA HECC that are native to HPC platforms, we will extend the MAAP cloud-native approach of Jupyter science notebooks running in AWS to also run seamlessly across to NASA HECC.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/MAAP-Project/maap-hec-aws","license":null}},{"forgeId":"forge_nasa_npo_52251_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52251-1","sourceUrl":"https://software.nasa.gov/software/NPO-52251-1","confidence":"high"},"type":"software","title":"Library for Leader Election and Spanning Tree Distributed Construction","abstract":"NASA's Cooperative Autonomous Distributed Robotic Explorers (CADRE) project is developing a network of shoe-box-sized mobile robots that could enable future autonomous robotic exploration of the Moon, Mars, and beyond. Each robot contains an onboard computer with a wireless radio for communication and a stereo camera which has multiple lenses and image sensors for sensing the environment in front of it and capturing 3D imagery. NASA's JPL is developing the robotic scouts, designing them to explore as a group and collect data in hard-to-reach places such as craters and caves on the Moon. Multiple small, autonomous robots could cover more ground, potentially helping us map unexplored regions on the Moon.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/jodavaho/distributed-leader-election/","license":null}},{"forgeId":"forge_nasa_npo_52266_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52266-1","sourceUrl":"https://software.nasa.gov/software/NPO-52266-1","confidence":"high"},"type":"software","title":"Software Lifecycle Improvement and Modernization (SLIM)","abstract":"The Software Lifecycle Improvement and Modernization (SLIM) project seeks to provide sample scripts, configuration, documentation, and recommendations for best practices in software lifecycle modernization, software governance improvements and standards, as well as software information sharing consistency and standards. Through both software and documentation, the SLIM effort seeks to improve overall software lifecycle standards for multi- mission Multi- mission Ground Software Systems (MGSS) Instrument Data Systems (IDS) participant teams and software projects.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-AMMOS/slim","license":null}},{"forgeId":"forge_nasa_npo_52286_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52286-1","sourceUrl":"https://software.nasa.gov/software/NPO-52286-1","confidence":"high"},"type":"software","title":"Forward Ocean Atmosphere Microwave Radiative Transfer Model","abstract":"The software allows users to perform end-to-end simulations of satellite remote sensing of ocean state with microwave radiometers, particularly sea surface salinity.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/jpl-microwave-instrument-science/foam","license":null}},{"forgeId":"forge_nasa_npo_52290_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52290-1","sourceUrl":"https://software.nasa.gov/software/NPO-52290-1","confidence":"high"},"type":"software","title":"Harvester of remote time-stamped data products","abstract":"Ocean science and decision support applications increasingly rely on the synergistic, interdisciplinary use of multivariate/multi-parameter data from multiple distributed agency repositories. While more available, the growing variety and volume of ocean observing data combined with the heterogeneous modalities of access continue to pose a challenge to broad-scale uptake and usage. This limits the effective utilization of costly investments in sustained ocean observation by an increasing diversity of user communities with a need for such environmental information on the oceans for the assessment of climate change and other ecosystem impacts. Leveraging an advanced cloud technology stack and ongoing multi-agency pilot efforts being spearheaded by NASA, the Committee for Earth Observations (CEOS) Ocean Variables Enabling Research and Applications for GEO (Group for Earth Observations) (COVERAGE) initiative seeks to collaboratively develop the next generation data service infrastructure for a more digitally integrated ocean observing system in support of marine science and ecosystem-based management as well as furthering the use of remote sensing data in multidisciplinary science. In particular, we envision the implementation of a data services layer a top of existing agency repositories to provide more harmonized access to satellite, in-situ, and model data across a fragmented ocean data landscape with a set of value-added services that include integrated data search, visualization and analytics.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/jjacob7734/harvester_ts","license":null}},{"forgeId":"forge_nasa_npo_52333_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52333-1","sourceUrl":"https://software.nasa.gov/software/NPO-52333-1","confidence":"high"},"type":"software","title":"[V]ectorized [s]imulated [m]easurements of the [a]tmosphere using [r]adiative [t]ransfer based on the [M]atrix [O]perator [M]ethod (vSmartMOM)","abstract":"A full end-to-end modular software suite for radiative transfer and related atmospheric analysis . Develop a fast and accurate mechanism to simulate measurements (satellite, airborne, ground-based) of the Earth's atmosphere. This capability will represent the state of the art in our ability to: 1. estimate green house gas (mainly CO2) concentrations,2. their sinks by remotely sensing the health of forest canopies in terms of their vertical moisture distribution.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/RemoteSensingTools/vSmartMOM.jl","license":null}},{"forgeId":"forge_nasa_npo_52379_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52379-1","sourceUrl":"https://software.nasa.gov/software/NPO-52379-1","confidence":"high"},"type":"software","title":"Spectrometer Masks","abstract":"The spectrometer mask software identifies instances within remote sensing data of clouds, flares from oil and has manufacturing, and specular reflection, used for bright targets that may indicate false positive gas plume detection. Subsequent imagery is generated and used as a mask for the remote sensing imagery.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/johnchapman2/spectrometer_masks","license":null}},{"forgeId":"forge_nasa_npo_52383_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52383-1","sourceUrl":"https://software.nasa.gov/software/NPO-52383-1","confidence":"high"},"type":"software","title":"A Multidecadal Satellite Record of Water Vapor, Temperature, Clouds and Atmospheric Moist Processes","abstract":"The MEaSUREs projects are focused on product generation, availability, and utility of Earth System Data Records (ESDRs). An ESDR is defined as a unified and coherent set of observations of a given parameter of the Earth system, which is optimized to meet specific requirements in addressing science questions. These data records are critical to understanding Earth System processes and in assessing variability, long-term trends, and change in the Earth System as well as providing means for input and validation to modeling efforts. Emphasis is placed on linking together multiple satellites into a constellation, developing the means of utilizing a multitude of data sources to form coherent time series, and facilitating the use of extensive data in the development of comprehensive Earth system models.To best meet these goals, NASA's Earth Science Data Systems (ESDS) program promotes the full and open sharing of all data, metadata, documentation, models, images and research results, and the source code used to generate, manipulate, and analyze them.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/JPL-WVCC/measures","license":null}},{"forgeId":"forge_nasa_npo_52394_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52394-1","sourceUrl":"https://software.nasa.gov/software/NPO-52394-1","confidence":"high"},"type":"software","title":"ECCO Interactive Solution Evaluator","abstract":"The Estimating the Circulation and Climate of the Ocean (ECCO) consortium estimates ocean circulation and its role in climate - combining state-of-the-art ocean circulation models with global ocean data sets. Data visualizations of ECCO help scientists better understand these models and provide comparisons with other data sets. The ECCO Interactive Solution Evaluator is a web application that allows users to compare data visualizations of ECCO data fields with those from other data sources side-by-side. The application includes a map interface to select a region of interest and a charting tool to plot data for comparisons.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/ecco-interactive-solution-evaluator","license":null}},{"forgeId":"forge_nasa_npo_52413_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52413-1","sourceUrl":"https://software.nasa.gov/software/NPO-52413-1","confidence":"high"},"type":"software","title":"DDSA - Data Driven Science Architecture","abstract":"The DDSA software provides for collaborative data science analysis , management, and capture of complex bio-science data sets.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/Labcas-NIST","license":null}},{"forgeId":"forge_nasa_npo_52459_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52459-1","sourceUrl":"https://software.nasa.gov/software/NPO-52459-1","confidence":"high"},"type":"software","title":"Javascript implementation of CAHVORE Camera and Image Transformation Utilities","abstract":"Series of packages for visualizing and rendering images and frustum shapes based on CAHVORE camera models as well as loading SGI and PGM images in three.js.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/NASA-AMMOS/CameraModelUtilsJS","license":null}},{"forgeId":"forge_nasa_npo_52465_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52465-1","sourceUrl":"https://software.nasa.gov/software/NPO-52465-1","confidence":"high"},"type":"software","title":"Trace gas profile generation software (GINPUT)","abstract":"Generates vertical profiles of greenhouse gases and other trace gases. It primarily generates these profiles using only long term trends from NOAA observatories and correlations with meteorological variables. This allows the profiles to be independent of models, which in turn means satellite retrievals that use this software's profiles as prior information are a better independent comparison for said models.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/TCCON/py-ginput","license":null}},{"forgeId":"forge_nasa_npo_52467_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52467-1","sourceUrl":"https://software.nasa.gov/software/NPO-52467-1","confidence":"high"},"type":"software","title":"Embedded power controller with safety e-stop and led indicators","abstract":"The software runs on an embedded system which is controlling the power to computers and sensors within a robot. The software monitors voltages and currents and enables or disables the voltage regulators and load switches to power the various loads. The software also has control over an e-stop and lights to indicate the estop is enabled or disabled. The software can control the brightness of high brightness LEDs.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/tpaileva/Embedded-Power-Controller","license":null}},{"forgeId":"forge_nasa_npo_52472_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52472-1","sourceUrl":"https://software.nasa.gov/software/NPO-52472-1","confidence":"high"},"type":"software","title":"Open-Sourcing the Odysea Mission Simulator","abstract":"This software simulates scientific measurements from Odysea, a proposed JPL spaceborne mission that measures ocean winds and currents. These simulated measurements include the errors associated with the instrument, but not specific details of how these errors are produced or any proprietary/controlled/ITAR design details. All proprietary design or instrument information is completely separate and will not be released.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/awineteer/odysea-science-simulator/","license":null}},{"forgeId":"forge_nasa_npo_52498_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52498-1","sourceUrl":"https://software.nasa.gov/software/NPO-52498-1","confidence":"high"},"type":"software","title":"VIPRE: A TOOL FOR VISUALIZATION OF THE IMPACT OF PROBE ENTRY CONDITIONS","abstract":"It builds a trade space of planetary arrival trajectories and provides a user interface to visualize and filter the data. Traditional approaches to planetary arrival trajectory design are typically limited to single design points by a mission designer with initially little input from technologists and scientists. We seek a way to quickly and comprehensively build a total trade space of arrival trajectories. Our visualization approach is tailored for use by scientists, technologists, and engineers to facilitate concurrent design","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/jpl-vipre","license":null}},{"forgeId":"forge_nasa_npo_52508_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52508-1","sourceUrl":"https://software.nasa.gov/software/NPO-52508-1","confidence":"high"},"type":"software","title":"SISTER: SBG Space-based Imaging Spectroscopy and Thermal pathfinder","abstract":"The SISTER system is composed of an on-demand algorithm development environment and science data processing system. The system includes prototype workflows, algorithms, and datasets that are proxies for NASA's upcoming Surface Biology and Geology (SBG) mission .","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/sister-sbg/","license":null}},{"forgeId":"forge_nasa_npo_52526_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52526-1","sourceUrl":"https://software.nasa.gov/software/NPO-52526-1","confidence":"high"},"type":"software","title":"Machine Learning Key Utilities (MLky)","abstract":"MLky is a Python configuration software package for data scientists. It is designed to be highly configurable and flexible to be able to adapt to the evolving needs of data scientists. This facilitates research and pipeline development as well as provides a framework for software packages to step up its configuration from a flexible prototype to a rigid release candidate","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/jammont/mlky","license":null}},{"forgeId":"forge_nasa_npo_52537_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52537-1","sourceUrl":"https://software.nasa.gov/software/NPO-52537-1","confidence":"high"},"type":"software","title":"Cloudspotting on Mars Analysis Tools","abstract":"Enables reading, processing, and plotting Mars Climate Sounder (MCS) data (available on the Planetary Data System).","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/Cloudspotting-on-Mars/mcstools","license":null}},{"forgeId":"forge_nasa_npo_52538_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52538-1","sourceUrl":"https://software.nasa.gov/software/NPO-52538-1","confidence":"high"},"type":"software","title":"SIT-FUSE - Segmentation, Instance Tracking, and data Fusion Using multi-SEnsor imagery","abstract":"Previously, we developed an unsupervised machine learning method that uses level 1 (L1) radiances from various satellite and airborne imagers, as well as the fusion of datasets, where applicable, as input. This method was tested on data collected during the Fire Influence on Regional to Global Environments and Air Quality (FIREX-AQ) campaign,as well as other data fusion and segmentation datasets. The clustered output of the unsupervised models accurately identifies objects wild fires, smoke plumes, and burn scars, and establishes the basis for future automated tracking capabilities.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/nlahaye/SIT-FUSE/","license":null}},{"forgeId":"forge_nasa_npo_52559_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52559-1","sourceUrl":"https://software.nasa.gov/software/NPO-52559-1","confidence":"high"},"type":"software","title":"py-sonde-comparison","abstract":"The program is three core elements, described below: 1) read_product: This method reads satellite data products, which will be modified as new groups are included in the analysis . Key elements extracted are lat/lon, ozone profiles and aprioris and averaging kernels. 2) colocate: This methods takes the data from read_product, and uses the WOUDC ozonesonde extraction tool pywoudc to extract ozonesonde data within the same timeframe as the satellite data. The lat/lon and timestamps of satellite data are compared with those of the ozonesondes, if matches are found within a certain tolerance, these locations are saved, and output as a separate datafile. 3) plot_results: This method takes the files saved in colocate and performs statistical analysis and plots the results for further analysis and discussion. The code will evolve as additional satellite retrieval groups are added, and additional analysis tools are required.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/NASA-TROPESS/py-sonde-comparison","license":null}},{"forgeId":"forge_nasa_npo_52574_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52574-1","sourceUrl":"https://software.nasa.gov/software/NPO-52574-1","confidence":"high"},"type":"software","title":"Sequence JSON - A JSON Schema for specifying spacecraft command sequences","abstract":"Provides a JSON Schema (https://json-schema.org/) that specifies the properties and datatypes to specify a spacecraft command sequence in JSON (https://www.json.org/json-en.html).","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/NASA-AMMOS/seq-json-schema","license":null}},{"forgeId":"forge_nasa_npo_52576_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52576-1","sourceUrl":"https://software.nasa.gov/software/NPO-52576-1","confidence":"high"},"type":"software","title":"SciXR","abstract":"The Science Collaboration and data Interaction eXtended Reality tool or SciXR is the combination of the SciVR (NTR 50913) virtual reality tool and SciAR (NTR 51857) augmented reality tool for immersive science data exploration and analysis. SciXR provides a rich, real-time science data visualization engine in an interactive extended reality (XR) environment for use by scientists.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/EarthDigitalTwin/SciXR","license":null}},{"forgeId":"forge_nasa_npo_52577_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52577-1","sourceUrl":"https://software.nasa.gov/software/NPO-52577-1","confidence":"high"},"type":"software","title":"COVERAGE Visualization Generation Pipeline","abstract":"The COVERAGE Visualization Generation Pipeline (coverage-vizgen) is a software package containing a comprehensive set of utility tools for generating tiled map imagery in the Meta Raster Format (MRF) from NetCDF data files. It is packaged as a Docker container that may be configured to automatically produce imagery from a forward data stream of NetCDF files. This software was developed for the CEOS Ocean Variables Enabling Research and Applications for GEO (COVERAGE) initiative.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/ceos-coverage/coverage-vizgen","license":null}},{"forgeId":"forge_nasa_npo_52587_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52587-1","sourceUrl":"https://software.nasa.gov/software/NPO-52587-1","confidence":"high"},"type":"software","title":"Calibration of the High Resolution Volatiles and Minerals Mapper for the Moon (HVM3)","abstract":"This software is used in the analysis of data from the High Resolution Volatiles and Minerals Mapper for the Moon (HVM3). This instrument is an imaging spectrometer measuring from 600-3600 nm, which will be deployed on the Lunar Trailblazer mission to measure lunar volatiles. The software performs spectral and radiometric calibration of raw instrument science data.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/lunartrailblazr/HVM3","license":null}},{"forgeId":"forge_nasa_npo_52595_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52595-1","sourceUrl":"https://software.nasa.gov/software/NPO-52595-1","confidence":"high"},"type":"software","title":"Automated Colorization of M2020 SHERLOC Context Images","abstract":"This technology is a script, written in Python, that uses functions from the OpenCV library to automatically detect keypoints within images from two subsystems of SHERLOC, the ACI and WATSON imagers. These keypoints are then matched and used to warp the WATSON image to the ACI, resulting in a \"colorized\" ACI. This ACI is co-boresighted with the SHERLOC spectrometer, and the resulting image product can allow for analysis of spectral, textural, and color information of observed rock surfaces. It can be used as a standalone script and the resulting colorized ACIs can be integrated into the Loupe software (created by K. Uckert) for SHERLOC data analysis .","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/nasa-jpl/ACI-colorization","license":null}},{"forgeId":"forge_nasa_npo_52599_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52599-1","sourceUrl":"https://software.nasa.gov/software/NPO-52599-1","confidence":"high"},"type":"software","title":"MoonDiff: A Web Application Enabling Crowdsourced Comparisons Between Old and New Lunar Imagery","abstract":"This software harnesses the online community to find changes on the lunar surface, including new impact craters and spacecraft hardware. Citizen scientists are presented with pairs of old and new lunar orbital imagery in the form of web maps. The interface allows them to mark changes they observe and submit those to a database for review by experts, which is also done within the same web application","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/nasa-jpl/MoonDiff","license":null}},{"forgeId":"forge_nasa_npo_52605_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52605-1","sourceUrl":"https://software.nasa.gov/software/NPO-52605-1","confidence":"high"},"type":"software","title":"Building Open-Source Hydrodynamic Models Using ANUGA Software","abstract":"This software uses an automated approach to build hydrodynamic models of coastal areas. The software is Python based and downloads and incorporates publicly available data to populate model parameters. The software utilizes several common packages as well as an open-source modeling software, ANUGA. ANUGA is available on Github and solves the shallow water equations using a finite volume method over an unstructured mesh. Our software allows the user to build the input files needed for ANUGA, set up and run an ANUGA simulation, and process the output files for visualization and interpretation.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/achri19/BAM","license":null}},{"forgeId":"forge_nasa_npo_52608_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52608-1","sourceUrl":"https://software.nasa.gov/software/NPO-52608-1","confidence":"high"},"type":"software","title":"POMM Planetary Orbital Mosaicking and Mapping Software Toolset","abstract":"POMM is a set of software tools (with User Interface) supporting the automation of Earth and Planetary orbital image mosaicking and mapping, including 1) The ability of co-register (stack) multiple orbital map images over the same location for time series analysis ; 2) Mosaic mulitiple adjacent overlapping orbital images to create large-area basemap coverages and regional overviews; and 3) Create map-projected orbital satellite images from selected sensors and bands provided in PDS (Planetary Data System) format. As a subset of the AFIDS software environment (NTR 52175), POMM also provides a large variety of general purpose image processing tools for performing change detection, time series, and related satellite scene analyses.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/NASA-AMMOS/AFIDS-POMM","license":null}},{"forgeId":"forge_nasa_npo_52612_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52612-1","sourceUrl":"https://software.nasa.gov/software/NPO-52612-1","confidence":"high"},"type":"software","title":"Data Analysis using Imagery Layers (DAG)","abstract":"The DAG software implements a generalized, cloud-enabled web service for the extraction of converted geophysical values from satellite imagery layers being served out via Tiled-WMS imagery servers and the computation of geo spatial analytics on the data returned. Analyses supported at present focus on spatial and temporal summary statistics for user selected bounding box regions, time ranges and variables of interest. The DAG service can be invoked both directly programmatically via calls to the API and via the Flask Open-API interface implemented by DAG. Outputs can be consumed by various client applications, including visualization and other tools.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/ceos-coverage/coverage-dag","license":null}},{"forgeId":"forge_nasa_npo_52648_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52648-1","sourceUrl":"https://software.nasa.gov/software/NPO-52648-1","confidence":"high"},"type":"software","title":"VECTOR, Visual Analytics Application for Bundle Adjustment Error Detection","abstract":"VECTOR ( Visualization and Editing of Camera Tiepoints, Orientations, and Residuals), introduces a novel approach to visualize camera poses before and after bundle adjustment, as well as the resulting 3D point cloud (map) allowing researchers and operators to visually inspect and interpret the output of a single bundle adjustment optimization.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/NASA-AMMOS/VECTOR","license":null}},{"forgeId":"forge_nasa_npo_52659_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52659-1","sourceUrl":"https://software.nasa.gov/software/NPO-52659-1","confidence":"high"},"type":"software","title":"Multi-sensor Simultaneous Localization and Mapping (SLAM) with principled ICP covariance modelling.","abstract":"To overcome these degeneracy, we developed a SLAM solution called State Estimation through Robust Perception in Extreme and Novel Terrains (SERPENT). SERPENT estimates the robot trajectory and maintains a map database, from which dense global or local maps can be obtained on demand for downstream planning algorithms. The design of this system adopts the approach that incorporating measurements from many sensor modalities (laser scans, images, IMU, altimeter, etc.) into a joint optimisation, with the contribution of each carefully modeled through their uncertainties, is essential to robust state estimation in challenging, perceptually degraded environments.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/jpl-eels/serpent","license":null}},{"forgeId":"forge_nasa_npo_52667_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52667-1","sourceUrl":"https://software.nasa.gov/software/NPO-52667-1","confidence":"high"},"type":"software","title":"Poke: Integrating Ray and Diffraction Models","abstract":"Poke is a package to interface with industry-standard raytracing engines to do physical optics calculations based on ray data. The development was inspired by the need to add more propagation physics modules for Coronagraphs to expand the design space, but Poke has been used to characterize existing observatories as well.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/Jashcraf/poke","license":null}},{"forgeId":"forge_nasa_npo_52671_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52671-1","sourceUrl":"https://software.nasa.gov/software/NPO-52671-1","confidence":"high"},"type":"software","title":"Earth System Digital Twin Software Framework","abstract":"A software system was developed that enables generalized orchestration and interoperability of scientific models. In combination with continuous onboarding of near real time satellite and insitu observations, this enables forecasting and prediction of scenarios such as flooding.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/EarthDigitalTwin/ideas-api/tree/main","license":null}},{"forgeId":"forge_nasa_npo_52696_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52696-1","sourceUrl":"https://software.nasa.gov/software/NPO-52696-1","confidence":"high"},"type":"software","title":"The Landform Contextual Mesh: Fusing Surface and Orbital Terrain Data","abstract":"The Landform contextual mesh system combines terrain image and 3D data taken from a surface vehicle with terrain data from orbital observations into a combined 3D scene for visualization . The contextual mesh helps users understand the context (situational awareness) of the surface vehicle in relation to local and distant terrain features.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/NASA-AMMOS/Landform","license":null}},{"forgeId":"forge_nasa_npo_52748_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52748-1","sourceUrl":"https://software.nasa.gov/software/NPO-52748-1","confidence":"high"},"type":"software","title":"STARS: Spatial Timeseries for Automated high-Resolution multi-Sensor data fusion","abstract":"Implements a novel, statistical data fusion methodology called STARS (Spatial Timeseries for Automated high Resolution multi-Sensor data fusion) to provide daily, high spatial resolution estimates of remotely-sensed imagery by combining data from multiple spectrometers (e.g. Landsat/Sentinel/MODIS/VIIRS).","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/STARS-Data-Fusion/STARS.jl","license":null}},{"forgeId":"forge_nasa_npo_52809_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52809-1","sourceUrl":"https://software.nasa.gov/software/NPO-52809-1","confidence":"high"},"type":"software","title":"airPy","abstract":"The airPy package was developed to extract high-resolution satellite data from Google Earth Engine (GEE) and calculate Machine Learning-ready features for air pollution studies. This software prepares raw data from GEE into ML-ready NetCDF files. Extra capabilities such as grid-matching is provided. No other software offers these features, so airPy was developed in-house to enable future researchers easier access to GEE datasets.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/kelsdoerksen/airPy","license":null}},{"forgeId":"forge_nasa_npo_52833_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52833-1","sourceUrl":"https://software.nasa.gov/software/NPO-52833-1","confidence":"high"},"type":"software","title":"ArcGIS toolbox for utility enhancement of OPERA products","abstract":"The OPERA ArcGIS toolbox is software that works with the ArcGIS Desktop Pro software package. The toolbox streamlines the user workflow. This toolbox is designed to seamlessly integrate with existing ArcGIS Pro software, allowing users to easily access, process, and visualize the OPERA products. The toolbox is user-friendly, intuitive, and efficient, providing a range of functionalities to enhance the analysis and interpretation of OPERA's Products.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/OPERA-Cal-Val/OPERA-ArcGIS-Toolbox","license":null}},{"forgeId":"forge_nasa_npo_52835_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52835-1","sourceUrl":"https://software.nasa.gov/software/NPO-52835-1","confidence":"high"},"type":"software","title":"Thematic Observation Search, Segmentation, Collation and Analysis (TOS2CA)","abstract":"TOS2CA is a user-driven, data-centric system that can identify, collate, statistically characterize and serve Earth system data relevant to a given phenomenon. Designed as a multi-discipline analytic collaborative framework (ACF), TOS2CA will not only facilitate the collation and analysis of data from disparate sources, it will also make it possible for scientists to establish science traceability requirements, quantify detection thresholds, define uncertainty requirements and establish data sufficiency to formulate truly innovative missions.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_npo_52858_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52858-1","sourceUrl":"https://software.nasa.gov/software/NPO-52858-1","confidence":"high"},"type":"software","title":"OCO-3 Snapshot Area Map Global Level 3 Zarr Product Generation","abstract":"NASA-JPL's OCO-3 is an instrument onboard the International Space Station that measures carbon dioxide in the Earth's atmosphere. OCO-3 is similar in design to its predecessor, OCO-2, with the addition of the Pointing Mirror Assembly (PMA) which essentially allows the instrument to focus its observations on the area surrounding a given location of interest on a single overflight. This is called a Snapshot Area Map, or SAM, and is the focus of this software. This software takes daily OCO-3 CO2 input, isolates SAM captures, and fits the data to a global, fixed grid for a level 3 output product.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/EarthDigitalTwin/OCO3-data-transformer","license":null}},{"forgeId":"forge_nasa_npo_52864_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52864-1","sourceUrl":"https://software.nasa.gov/software/NPO-52864-1","confidence":"high"},"type":"software","title":"Multi-Spacecraft Concept and Autonomy Tool (MuSCAT): A Low-Fidelity Simulator to Develop and Test Spacecraft Autonomy","abstract":"MuSCAT easily simulate a single-spacecraft or multi-spacecraft mission (to Small Body). It provides a modeling framework bridge between the Foundry and Project implementation. MuSCAT can prove the mission needs Autonomous functions, or can be carried out from the ground. It facilitates autonomy infusion at an architectural level.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/nasa/muscat","license":null}},{"forgeId":"forge_nasa_npo_52886_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52886-1","sourceUrl":"https://software.nasa.gov/software/NPO-52886-1","confidence":"high"},"type":"software","title":"pyDownLinkParser: multi- mission CCSDS packet parser","abstract":"This library parses binary files containing CCSDS packets of various structures (APID) and distribute them in pandas dataframes. It is modular and configurable for multiple missions.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/nasa/pydownlinkparser","license":null}},{"forgeId":"forge_nasa_npo_52896_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52896-1","sourceUrl":"https://software.nasa.gov/software/NPO-52896-1","confidence":"high"},"type":"software","title":"Retrospective Analysis Toolbox for Ionospheric Total Electron Content Maps","abstract":"This is a retroptrospective analysis toolbox for ionospheric total electron content (TEC) maps. The toolbox consists of two parts, a feature extraction program and a transfer entropy calculator. The feature extraction program is capable of extracting characteristics of local TEC intensifications from global ionospheric TEC maps. The transfer entropy calculator is capable of quantifying solar and interplanetary driving of the extracted TEC intensifications.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/xingmengx/TECMapToolbox.git","license":null}},{"forgeId":"forge_nasa_npo_52911_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52911-1","sourceUrl":"https://software.nasa.gov/software/NPO-52911-1","confidence":"high"},"type":"software","title":"Graphical Utility for Icy moon Surface Simulations (GUISS)","abstract":"The software is a simulation framework that generates photo-realistic imagery of terrain from icy moons such as Enceladus and Europa. The simulation is versatile and can provide imagery over a wide range of visual hypotheses of the terrains of these moons with respect to terrain roughness, texture variation, photometric properties, and illumination. The simulation was developed with information from existing scientific literature about the terrains of these icy moons.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/nasa-jpl/guiss","license":null}},{"forgeId":"forge_nasa_npo_52921_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52921-1","sourceUrl":"https://software.nasa.gov/software/NPO-52921-1","confidence":"high"},"type":"software","title":"PlanetMag GitHub Repository Software for Planetary Magnetic Field Modeling","abstract":"Firstly, planetary magnetic field simulation software is not publicly available for all the planets, and neither are all the various models. This unified software package includes all the giant planets in widely used languages, making it accessible by anyone in the community. To our knowledge, no other publicly available software provides features for inversion of the frequency spectrum of magnetic oscillations experienced along an arbitrary trajectory.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/coreyjcochrane/PlanetMag","license":null}},{"forgeId":"forge_nasa_npo_52932_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52932-1","sourceUrl":"https://software.nasa.gov/software/NPO-52932-1","confidence":"high"},"type":"software","title":"Roman Coronagraph EXCAM image processing software","abstract":"This software cleans and calibrates images produced by the Nancy Grace Roman Space Telescope Coronagraph Instrument's Exoplanetary Systems Camera (EXCAM). Roman is an upcoming NASA astrophysics observatory, and EXCAM is the \"science\" camera for the Coronagraph Instrument onboard Roman. EXCAM uses a visible-light CCD sensor (not ITAR-controlled).","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/roman-corgi/cgi_iit_drp","license":null}},{"forgeId":"forge_nasa_npo_52944_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52944-1","sourceUrl":"https://software.nasa.gov/software/NPO-52944-1","confidence":"high"},"type":"software","title":"DataDrive Command-Line Interface","abstract":"DataDrive provides data access and distribution for a mission's data products in the Amazon Web Services (AWS) cloud utilizing the Operational Cloud Store (OCS). The CS3 Single Sign On (CSSO) or MGSS CAM provides authentication and authorization to DataDrive.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/NASA-AMMOS/DataDrive-CommandLine","license":null}},{"forgeId":"forge_nasa_npo_52954_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52954-1","sourceUrl":"https://software.nasa.gov/software/NPO-52954-1","confidence":"high"},"type":"software","title":"Rock Shadow Counter (ROSCO)","abstract":"Rock Shadow Counter (ROSCO) is a suite of software tools developed at JPL for the purpose of characterizing the rockiness of the planetary surfaces in high resolution aerial/orbital images such as HiRISE images from MRO. The software has tools and workflow for sharpening input images, detecting rocks in the sharpened images, visualizing outputs, registering output data to a coordinate system, and creating raster maps derived from the detected rocks.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/nasa-jpl/ROSCO","license":null}},{"forgeId":"forge_nasa_npo_52974_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52974-1","sourceUrl":"https://software.nasa.gov/software/NPO-52974-1","confidence":"high"},"type":"software","title":"EcoPro","abstract":"The overall goal of the project is to build an analytic collaborative framework to support multidisciplinary teams to conduct ecological projection studies, collaborations, applications, and new observation strategy developments. The proposed framework will contain (1) an analytic toolkit to perform the multidisciplinary analyses, (2) a data gateway to organize, store, and access the key input and output datasets, and (3) a web portal to publish and visualize the results of the studies and to provide a virtual collaborative work space.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/EcoPro-Systems","license":null}},{"forgeId":"forge_nasa_npo_52987_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52987-1","sourceUrl":"https://software.nasa.gov/software/NPO-52987-1","confidence":"high"},"type":"software","title":"CORTEX: Continuous Optimization in Robotics via Test and Exploration","abstract":"CORTEX is a sophisticated framework developed to revolutionize robotics engineering. It accelerates the development cycle by enabling quick prototyping in simulated environments and efficient deployment on real robots. CORTEX offers an extensive suite of tools for conducting experiments with precise control and repeatability. Its data management system, integrated with test automation capabilities, provides insightful analysis , aiding in the refinement of robotics algorithms. The framework's modular design ensures compatibility with a broad spectrum of robotic systems, facilitating customization and extension according to specific project needs. These features provide a holistic view of robotics systems, and enable streamlined knowledge transfer, enhanced decision making, and greater alignment amongst all stakeholders in robotics projects.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/nasa-jpl/cortex","license":null}},{"forgeId":"forge_nasa_npo_52991_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-52991-1","sourceUrl":"https://software.nasa.gov/software/NPO-52991-1","confidence":"high"},"type":"software","title":"Monitoring and ANalysis for Gravity Operations (MANGO) Tool","abstract":"MANGO is intended to make it easier to monitor and analyze data collected from GRACE-FO/GRACE-C and produced by science data system.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/nasa-jpl/mango-ingest;  https://github.com/nasa-jpl/mango-ui; https://github.com/nasa-jpl/mango-docs","license":null}},{"forgeId":"forge_nasa_npo_53015_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53015-1","sourceUrl":"https://software.nasa.gov/software/NPO-53015-1","confidence":"high"},"type":"software","title":"Segmented Aperture Wavefront Sensing and Control Software for Space-Based Coronagraphs","abstract":"This software package performs Electric Field Conjugation (EFC) and Wavefront Control (WFC) for space-based, large aperture segmented internal coronagraph observatories. Then computes contrast ratios for detecting exoplanets and other phenomenon orbiting distant stars. It was developed primarily for ATLAST, HabEX, and HWO.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/nasa-jpl/SAWSCS-SBC","license":null}},{"forgeId":"forge_nasa_npo_53016_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53016-1","sourceUrl":"https://software.nasa.gov/software/NPO-53016-1","confidence":"high"},"type":"software","title":"rasters","abstract":"This Python software package provides a comprehensive solution for handling gridded and swath raster data. It offers an object-oriented interface for ease of use, treating rasters, raster geometries, and vector geometries as objects. This allows for seamless map visualization in Jupyter notebooks and efficient resampling between swath and grid geometries.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/python-rasters/rasters","license":null}},{"forgeId":"forge_nasa_npo_53026_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53026-1","sourceUrl":"https://software.nasa.gov/software/NPO-53026-1","confidence":"high"},"type":"software","title":"AutoNav Monte Carlo Visualizer","abstract":"Mars Rover Planners are studying the potential for AutoNav Monte Carlo simulations to help them assess the risks of extended automatic navigation over challenging topography. GRIT summarizes thousands of simulated AutoNav runs for Rover Planners to investigate and understand potential failure cases","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/matthhong/grit","license":null}},{"forgeId":"forge_nasa_npo_53031_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53031-1","sourceUrl":"https://software.nasa.gov/software/NPO-53031-1","confidence":"high"},"type":"software","title":"Use Cases for Flight Mechanics Analysis Tools Interoperability and Component Sharing","abstract":"Several NASA centers have developed independent flight mechanics tools to meet the science needs of missions. A NASA Engineering and Safety Center (NESC) assessment was performed to increase the interoperability of three specific tools: Copernicus from Johnson Space Center (JSC), the General Mission Analysis Tool (GMAT) from Goddard Spaceflight Flight Center (GSFC), and the Mission- Analysis Operations Navigation Toolkit Environment (MONTE) from the Jet Propulsion Laboratory (JPL). All of these tools are utilized in various spaceflight regimes and mission lifecycles (e.g., design, analysis , operations) to generate a variety of products (e.g., maneuver planning, orbit determination, error analysis , trade study, flight products). Each tool was built over the years with specific goals unique to each center, which were based on the science missions they supported, and naturally lead to variations in their capabilities. Before this assessment, these tools were not integrated and could not easily share data, models, or components. The results of the NESC assessment improved the interoperability and component sharing of these flight mechanic tools to increase Agency efficiency and reduce cost.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/nasa-jpl/MonteCop","license":null}},{"forgeId":"forge_nasa_npo_53032_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53032-1","sourceUrl":"https://software.nasa.gov/software/NPO-53032-1","confidence":"high"},"type":"software","title":"TetherCAD: a Python library to aid in systems engineering for tether designs.","abstract":"TetherCAD is a set of analysis tools to aid in the design of electromechanical tethers. These tethers can be used for robotics, space systems and more! The tool set is presented as a python library to promote ease-of-use and allow compatibility with a number of different systems. This library aims to help the user quickly and concisely answer the high-level questions involved in a tether's or tethered-system's design.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/nasa-jpl/TetherCAD","license":null}},{"forgeId":"forge_nasa_npo_53040_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53040-1","sourceUrl":"https://software.nasa.gov/software/NPO-53040-1","confidence":"high"},"type":"software","title":"Priestley-Taylor Jet Propulsion Laboratory Evapotranspiration Model Python Package","abstract":"This software package is a Python implementation of the Priestley-Taylor Jet Propulsion Laboratory (PT-JPL) model of evapotranspiration. The PT-JPL model was designed for processing remote sensing data . It has the ability to partition latent heat flux into canopy transpiration, interception, and soil evaporation.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/JPL-Evapotranspiration-Algorithms/PT-JPL","license":null}},{"forgeId":"forge_nasa_npo_53070_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53070-1","sourceUrl":"https://software.nasa.gov/software/NPO-53070-1","confidence":"high"},"type":"software","title":"Student Wildfire Classification Jupyter Notebooks","abstract":"These are 4 Jupyter notebooks that prepare airborne radar data for wildfire classification products. The notebooks use a super pixel segmentation method to generate fire perimeters and a simple k-means clustering method to classify burn severity for SAR data . These notebooks automate the data pre-processing for polarimetric radar remote sensing data , and generate preliminary fire perimeter and burn severity maps, which are usually manually generated and from sources other than radar.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/nasa-jpl/uavsar-wildfire and https://github.com/nasa-jpl/uavsar-wildfire-rtc","license":null}},{"forgeId":"forge_nasa_npo_53079_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53079-1","sourceUrl":"https://software.nasa.gov/software/NPO-53079-1","confidence":"high"},"type":"software","title":"Software for monitoring the phenology, distribution, and mortality of selected tropical trees from space","abstract":"This software comprises a set of tools to fetch imagery from commercial satellite imaging company Planet, perform labeling of the imagery using the Labelbox platform, and train, evaluate, and deploy a machine learning model for detecting flowering tree species within the images.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/garydoranjr/tree-monitoring","license":null}},{"forgeId":"forge_nasa_npo_53083_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53083-1","sourceUrl":"https://software.nasa.gov/software/NPO-53083-1","confidence":"high"},"type":"software","title":"Thermal correction of HVM3 imaging spectrometer data","abstract":"We apply a Bayesian model inversion approach to disentangle the temperature-dependent thermal emission signal and the solar-reflected portion, enabling thermally-corrected surface reflectance maps for instruments like JPL's High Resolution Volatiles and Minerals Mapper for the Moon (HVM3). The Bayesian strategy makes the ill-posed problem tractable by introducing background information about \"legal\" surface reflectance values in the form of a loose statistical prior developed from library spectra.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/LunarTrailblazr/HVM3-Thermal-Correction","license":null}},{"forgeId":"forge_nasa_npo_53092_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53092-1","sourceUrl":"https://software.nasa.gov/software/NPO-53092-1","confidence":"high"},"type":"software","title":"Calculation of the Ocean Contrast from Synthetic Aperture Radar Images","abstract":"In remote sensing of the ocean, contrast in the measured intensity between clean water and other features is used to identify different objects on the ocean surface either directly or indirectly via alteration of the ocean wave spectrum. The damping ratio, a measure of contrast, is increasingly used for operational oil spill monitoring as an aid or alternative to visual inspections by trained personnel, and can in some cases identify thicker oil in a slick. This software implements an algorithm that has been proposed for automatically calculating the contrast based upon the statistical properties of the measured intensity signals from the ocean surface, and shown to work well even for complex slick geometries. It works with multi-frequency and medium-to-high resolution data. The algorithm's flexibility and computational simplicity makes it suitable for real-time processing to support oil spill response.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/nasa-jpl/auto_SAR_Ocean_Contrast","license":null}},{"forgeId":"forge_nasa_npo_53097_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53097-1","sourceUrl":"https://software.nasa.gov/software/NPO-53097-1","confidence":"high"},"type":"software","title":"Machine learning approach to derive diurnal cycles of XCO2","abstract":"Train a machine learning model to predict a full diurnal cycle of XCO2 and daily drawdown from measurements at 2 to 3 times of day","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/joshua-laughner/ml-xco2-diurnal-cycles","license":null}},{"forgeId":"forge_nasa_npo_53101_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53101-1","sourceUrl":"https://software.nasa.gov/software/NPO-53101-1","confidence":"high"},"type":"software","title":"UnitcellHub","abstract":"UnitcellHub provides the user tools to design application-specific lattice structures. These tools span the whole design life cycle, including preliminary design space exploration, CAD geometry creation, and prediction of mechanical and thermal characterization for point designs.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/orgs/unitcellhub/repositories","license":null}},{"forgeId":"forge_nasa_npo_53108_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53108-1","sourceUrl":"https://software.nasa.gov/software/NPO-53108-1","confidence":"high"},"type":"software","title":"Information System for Agricultural Yield Modeling","abstract":"This software developing is designed to estimate crop yields in agricultural regions using Ukraine as a high-impact test case. It is meant to generate yield estimates in a more efficient, accurate, and scalable operation. It aims to streamline an existing data processing pipeline called VERCYE in partnership with NASA Harvest, which currently relies on manual efforts, and turn it into an automated system that integrates various data source. The primary accomplishments will include an operationalized crop yield software that's capable of delivering multiple yield estimates for each of Ukraine's 25 Oblasts during the grow season. Additionally, it will prototype an ML model capable of estimating crop yield from SAR data (a sensing technique which can penetrate cloud cover). The software will enable fast/more yield estimates to aid decisions in food security and agricultural planning.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/JPLMLIA/vercye_ops","license":null}},{"forgeId":"forge_nasa_npo_53113_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53113-1","sourceUrl":"https://software.nasa.gov/software/NPO-53113-1","confidence":"high"},"type":"software","title":"Priestley-Taylor Jet Propulsion Laboratory Soil Mositure (PT-JPL-SM) Evapotranspiration Model Python Implementation","abstract":"This software package is a Python implementation of the Priestley-Taylor Jet Propulsion Laboratory Soil Moisture (PT-JP-SM) model of evapotranspiration. The PT-JPL model was designed for processing remote sensing data . It has the ability to partition latent heat flux into canopy transpiration, interception, and soil evaporation.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/JPL-Evapotranspiration-Algorithms/PT-JPL-SM","license":null}},{"forgeId":"forge_nasa_npo_53120_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53120-1","sourceUrl":"https://software.nasa.gov/software/NPO-53120-1","confidence":"high"},"type":"software","title":"ROSA: Robot Operating System Agent","abstract":"ROSA, the Robot Operating System Agent, is designed to address key challenges in modern robotics by simplifying interactions and improving communication across multidisciplinary teams. It achieves this through its innovative use of large language models (LLMs) which enable it to understand and process complex natural language queries about robotic systems. This functionality allows team members without specialized knowledge of ROS commands or the underlying technical structure to effectively interact with and manage robotic systems. ROSA's ability to break down technical barriers and democratize access to sophisticated robotics technology enhances operational efficiency and reduces training requirements, thereby making robotics more accessible and easier to manage across various sectors.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/nasa-jpl/rosa","license":null}},{"forgeId":"forge_nasa_npo_53121_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53121-1","sourceUrl":"https://software.nasa.gov/software/NPO-53121-1","confidence":"high"},"type":"software","title":"Breathing Earth System Simulator (BESS) Model Python Implementation","abstract":"This software package is the python implementation of the Breathing Earth System Simulator (BESS) model of gross primary production (GPP) and evapotranspiration (ET). This software makes the BESS model accessible for remote sensing researchers as part of the evapotranspiration modeling capabilities being developed for the ECOSTRESS and SBG missions.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/JPL-Evapotranspiration-Algorithms/BESS","license":null}},{"forgeId":"forge_nasa_npo_53145_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53145-1","sourceUrl":"https://software.nasa.gov/software/NPO-53145-1","confidence":"high"},"type":"software","title":"SUDS Air Quality","abstract":"Science Understanding Data Science: Air Quality is a research project from the Machine Learning and Instrument Autonomy group at the Jet Propulsion Laboratory. This project investigates driving features of pollution on scales finer than physical models operate on. By discovering and understanding these features, scientists may use this information to further improve the performance of physical models to better predict pollution.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/JPLMLIA/SUDSAQ","license":null}},{"forgeId":"forge_nasa_npo_53147_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53147-1","sourceUrl":"https://software.nasa.gov/software/NPO-53147-1","confidence":"high"},"type":"software","title":"Sorting and PDS4 Labeling of DSN TRK-2-34 Data","abstract":"All deep space missions performing radio science must archive raw data within the Planetary Data System (PDS). The Tracking and Navigation File (TRK-2-34) is the current standard format for radiometric data acquired at the Deep Space Network (DSN). This software allows users to quickly create the necessary label compliant with the current PDS4 standards for archiving within the PDS.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/NASA-PDS/PyTrk234;  https://github.com/NASA-PDS/radiosci-pds4","license":null}},{"forgeId":"forge_nasa_npo_53156_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53156-1","sourceUrl":"https://software.nasa.gov/software/NPO-53156-1","confidence":"high"},"type":"software","title":"Surface Temperature Initiated Closure Model (STIC)","abstract":"This software package is a Python implementation of the Surface Temperature Initiated Closure (STIC) version 1.3 model designed to implement LST to solve the aerodynamic temperature, which is critical for ET modeling. The original STIC model produced by Kaniska Mallick (Mallick et al. 2015; 2018; 2022) was re-implemented from MATLAB code to Python by Gregory Halverson and Madeleine Pascolini-Campbell. It is intended for use by the Hyperspectral Thermal Emission Spectrometer (HyTES), MODIS/ASTER (MASTER) Airborne Simulator, Ecosystem Spaceborne Thermal Radiometer Experiment on Space Station (ECOSTRESS) mission and as a precursor for the Surface Biology and Geology (SBG) mission .","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/JPL-Evapotranspiration-Algorithms/STIC","license":null}},{"forgeId":"forge_nasa_npo_53157_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53157-1","sourceUrl":"https://software.nasa.gov/software/NPO-53157-1","confidence":"high"},"type":"software","title":"Thermally Sensitive ECOSTRESS Evapotranspiration Model Ensemble Evaluation and Development","abstract":"This software is able to measure the error propagation of remotely sensed input variables to all major variables estimated in evapotranspiration modeling , including net radiation and soil heat flux. The software aims to address the critical need for evapotranspiration models that can accurately respond to changes in surface temperature observed at fine spatial resolution and frequent temporal resolution.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/JPL-Evapotranspiration-Algorithms/ET-Sensitivity","license":null}},{"forgeId":"forge_nasa_npo_53158_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53158-1","sourceUrl":"https://software.nasa.gov/software/NPO-53158-1","confidence":"high"},"type":"software","title":"VNP43 BRDF Julia Implementation","abstract":"The VNP43 BRDF (Bidirectional Reflectance Distribution Function) algorithm is a part of the Visible Infrared Imaging Radiometer Suite (VIIRS) onboard on the Suomi-National Polar-orbiting Partnership (NPP) satellite . This algorithm is used to continue the long-term remote sensing environmental data records (EDR) begun by the MODerate Resolution Imaging Spectroradiometer (MODIS) sensors.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/STARS-Data-Fusion/VNP43NRT.jl","license":null}},{"forgeId":"forge_nasa_npo_53190_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53190-1","sourceUrl":"https://software.nasa.gov/software/NPO-53190-1","confidence":"high"},"type":"software","title":"MLUQ","abstract":"The software provides a systematic machine learning Uncertainty Quantification (UQ) approach based on decision theory. Decision Theoretic Bootstrapping provides a rigorous UQ in a cross-validation setting and produces Machine Learning algorithms that are more stable with respect to the differences between the sample set and the true distribution. The software can show its best performance when there is significant epistemic uncertainty","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/JPLMLIA/DTB","license":null}},{"forgeId":"forge_nasa_npo_53213_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53213-1","sourceUrl":"https://software.nasa.gov/software/NPO-53213-1","confidence":"high"},"type":"software","title":"Roman Coronagraph image simulator wrapper","abstract":"This software package includes routines and example scripts for simulating observations with the Roman Coronagraph using two open-source packages. The goal of this software package is to provide a more user-friendly, modular, accessible way of using these open-source tools.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/jorgellop/corosims","license":null}},{"forgeId":"forge_nasa_npo_53216_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53216-1","sourceUrl":"https://software.nasa.gov/software/NPO-53216-1","confidence":"high"},"type":"software","title":"Plant Trait Estimation from Radiance for Fire Risk Estimation","abstract":"Existing plant traits estimation techniques rely on empirical models so they are sensitive to the training data . Here we use a physical model that estimate reflectance, and we use that reflectance within a radiance model to invert radiance measurements directly to plant traits.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/NimrodCarmon/RadPROSAIL","license":null}},{"forgeId":"forge_nasa_npo_53225_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53225-1","sourceUrl":"https://software.nasa.gov/software/NPO-53225-1","confidence":"high"},"type":"software","title":"NISAR Quality Assurance","abstract":"The NISAR Quality Assurance (QA) software provides detailed validation and verification of the science data products for the NASA-ISRO Synthetic Aperture Radar (NISAR) mission . It is designed for use by scientists, the NISAR algorithm development team, the NISAR mission Science Data System, and other users in the NISAR community. With the QA software, these communities can take input NISAR science data products and quickly generate plots, reports, quality metrics, quick-look images, verification check outcomes, and more on those input science products. The QA outputs are in human- and machine-readable formats, such as PNG, PDF, CSV, and HDF5.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/isce-framework/nisarqa","license":null}},{"forgeId":"forge_nasa_npo_53240_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53240-1","sourceUrl":"https://software.nasa.gov/software/NPO-53240-1","confidence":"high"},"type":"software","title":"ECOSTRESS Collection 2 Jet Propulsion Laboratory Evapotranspiration (JET) ensemble","abstract":"This software package incldues the glue code and algorithms used for producing the gridded and tiled ECOSTRESS collection 2 data products. This software package produces gridded (HDF5) and tiled (GeoTIFF) outputs for the following data products:- L2 LSTE: Land Surface Temperature & Emissivity (LSTE)- L2 STARS: Normalized Difference Vegetation Index (NDVI) & Albedo - L3 JET: Evapotranspiration (ET) & Evapotranspiration Auxiliary products (ET_AUX: MET, SM, SEB) - L4 JET: Evaporative Stress Index (ESI) & Water Use Efficiency (WUE)","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/ECOSTRESS-Collection-2/ECOSTRESS-Collection-2","license":null}},{"forgeId":"forge_nasa_npo_53246_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53246-1","sourceUrl":"https://software.nasa.gov/software/NPO-53246-1","confidence":"high"},"type":"software","title":"Carbon-I radiometric model","abstract":"This python notebook calculates instrument radiometric performance for the Carbon-I mission . It is adapted from code developed for similar calculations for the EMIT and SBG-VSWIR instruments. The Carbon-I instrument is a Dyson-layout imaging spectrometer that measures spectra in the 2-2.4 micron range. We first create top-of-atmosphere radiances for a predefined \"reference scene\" and then assess instrument performance in terms of noise sources, signal levels, and total SNR. The code below uses the functions in instrument.py for radiometric calculations.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/davidraythompson/CarbonIRadiometry","license":null}},{"forgeId":"forge_nasa_npo_53269_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53269-1","sourceUrl":"https://software.nasa.gov/software/NPO-53269-1","confidence":"high"},"type":"software","title":"TROPOMI carbon monoxide data preprocessing","abstract":"The software download TROPOMI carbon monoxide retrievals, aggregated individual retrievals to 2x2.5 \"super-obs\", then writes these data so that they can be assimilated by the CMS-Flux inversion system.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/bkabyrne/TROPOMI_inversion_preprocessing/tree/main","license":null}},{"forgeId":"forge_nasa_npo_53283_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53283-1","sourceUrl":"https://software.nasa.gov/software/NPO-53283-1","confidence":"high"},"type":"software","title":"Space Balls simulation environment: Python code to run MONTE and generate accelerations observed by a spacecraft along orbit based on user-defined inputs and force models (aka MONTE Spacecraft Tool - MST)","abstract":"- Python code to run MONTE based on User Input. This code simulates the orbital dynamics in real time given a desired set of force models, and spacecraft specifications, such as size, mass, and surface properties. Forces can be toggled on and off to examine individual effects on the acceleration and the orbital trajectory.- Python code to read publicly available climate data (CERES) and pass as input to MONTE in the form of spherical harmonic coefficients. This allows for a more realistic and accurate simulation of the albedo pressure force in near-real time.- Python code that analyzes and prints MONTE data output into text files and produces plots for the time period of interest.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/nasa-jpl/Space-Balls-MST","license":null}},{"forgeId":"forge_nasa_npo_53286_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53286-1","sourceUrl":"https://software.nasa.gov/software/NPO-53286-1","confidence":"high"},"type":"software","title":"mrcam - a toolkit for camera preview, logging and replay using aravis","abstract":"mrcam allows users to read images from genicam cameras, to control the various camera parameters, to log the data produced by the camera and to replay those logs. mrcam provides both prebuilt tools AND libraries that could be utilized to build new applications. The prebuilt tools shipped in th edistribution are the preview/log/replay tool and a \"focus\" tool, to get live feedback about image sharpness to let the user focus a camera with immediate feedback.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/dkogan/mrcam","license":null}},{"forgeId":"forge_nasa_npo_53317_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53317-1","sourceUrl":"https://software.nasa.gov/software/NPO-53317-1","confidence":"high"},"type":"software","title":"PlanetProfile, Software framework for constructing interior structure models based on planetary properties.","abstract":"Software framework for constructing 1D interior structure models based on planetary properties. Self-consistent thermodynamics are used for fluid, rock, and mineral phases. Sound speeds, attenuation, and electrical conductivities are computed as outputs. The main code is called from an input file containing all the planetary data .","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/vancesteven/PlanetProfile","license":null}},{"forgeId":"forge_nasa_npo_53324_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53324-1","sourceUrl":"https://software.nasa.gov/software/NPO-53324-1","confidence":"high"},"type":"software","title":"ROSA Extension for Nvidia IsaacSim","abstract":"The ROSA Extension for Nvidia IsaacSim integrates the ROSA framework into the IsaacSim simulation environment, providing users with a more intuitive way to control robotic simulations. By enabling natural language interaction directly within IsaacSim, this extension simplifies robot control and simulation management, bypassing the complexity of IsaacSim's extensive set of controls and configurations. Users can now not only direct robot movements but also manage simulation workflows by starting, pausing, or stopping the simulation timeline via natural language commands. This integration enhances the user experience, allowing for more efficient robot development and simulation processes through intuitive, voice-based control.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/nasa-jpl/rosa-isaacsim","license":null}},{"forgeId":"forge_nasa_npo_53328_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53328-1","sourceUrl":"https://software.nasa.gov/software/NPO-53328-1","confidence":"high"},"type":"software","title":"PlanetThrak, software for modeling thermal fracturing in ocean worlds","abstract":"Computing the depths of potential thermal fracturing in different planetary bodies based on simple two layer models of their interiors. This information is important for understanding the depths of possible water rock interactions that might provide energy for life, and also for understanding the physical properties of the upper rocky crusts that might be probed by geophysical measurements.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/vancesteven/PlanetThrak","license":null}},{"forgeId":"forge_nasa_npo_53333_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53333-1","sourceUrl":"https://software.nasa.gov/software/NPO-53333-1","confidence":"high"},"type":"software","title":"fortformat.rs - Fortran format parsing in Rust","abstract":"This package can parse Fortran fixed-width and list-directed format strings and then serialize data into that text format or deserialize data from that text format into memory.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/joshua-laughner/fortformat","license":null}},{"forgeId":"forge_nasa_npo_53338_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53338-1","sourceUrl":"https://software.nasa.gov/software/NPO-53338-1","confidence":"high"},"type":"software","title":"SWOT River Spatial Scale Analysis Software","abstract":"This software will be used by the SWOT project, the SWOT Algorithm Development Team, the SWOT Calibration and Vaidation Team, The SWOT Science Team and the Hydrology Community in general to analyze, interpret and filter the SWOT river data to study both the limits of the SWOT measurement, and the river hydrology science that can be done with SWOT data.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/SWOTAlgorithms/river-spatial-scale","license":null}},{"forgeId":"forge_nasa_npo_53344_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53344-1","sourceUrl":"https://software.nasa.gov/software/NPO-53344-1","confidence":"high"},"type":"software","title":"Weak Lensing Cosmological Inference Software Pipeline for Roman Space Telescope's High Latitude Imaging Survey","abstract":"This cosmology pipeline is specifically tailored to extract cosmological information (in the form of estimates of cosmological parameters) from the Roman Space Telescope High Latitude Imaging Survey data . This software pipeline will enable the Roman high-latitude imaging survey to achieve its extraordinary cosmological potential, while simultaneously providing unprecedented volumes of exquisite data for an enormous range of astrophysical investigations.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/Roman-HLIS-Cosmology-PIT","license":null}},{"forgeId":"forge_nasa_npo_53347_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53347-1","sourceUrl":"https://software.nasa.gov/software/NPO-53347-1","confidence":"high"},"type":"software","title":"CRYOLAVASAURUS","abstract":"CRYOLAVASAURUS is a scientific modeling toolkit designed to simulate cryovolcanic activity at Europa and its observable signatures, with potential applications to other Ocean Worlds. The project includes a series of MATLAB scripts that model different physical, geological, thermal, and compositional components of this process, as well as data inputs and visual outputs.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/ElodieLesage/Cryolavasaurus","license":null}},{"forgeId":"forge_nasa_npo_53369_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53369-1","sourceUrl":"https://software.nasa.gov/software/NPO-53369-1","confidence":"high"},"type":"software","title":"Veloserver","abstract":"Veloserver is a geospatial data visualization server designed to dynamically return velocity data such as winds and ocean currents from weather models and other datasets. It returns the data in formats optimized for visualizing in a web client including animated vector streamlines via gribjson. It includes built-in caching to reduce requests to external data sources and deliver quick results. It was originally developed for the NASA Earth Surface Mineral Dust Source Investigation (EMIT) mission for use by the Multi-Mission Geographic Information System (MMGIS) software.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/NASA-AMMOS/Veloserver","license":null}},{"forgeId":"forge_nasa_npo_53372_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53372-1","sourceUrl":"https://software.nasa.gov/software/NPO-53372-1","confidence":"high"},"type":"software","title":"Parallel Observing System Simulation Experiment (ParOSSE) Framework","abstract":"The Parallel Observing System Simulation Experiment (ParOSSE) code serves as a flexible and extensible framework for the evaluation of science benefit for current and new observing systems. It is designed to rapidly explore the information content in diverse measurement concepts using simulated reference data (a nature run), an instrument simulator, and a set of analysis and plotting functions. This version is tailored specifically for the needs of the National Oceanic and Atmospheric Administration (NOAA).","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://github.com/ParOSSE/parosse-noaa","license":null}},{"forgeId":"forge_nasa_npo_53382_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53382-1","sourceUrl":"https://software.nasa.gov/software/NPO-53382-1","confidence":"high"},"type":"software","title":"Radiative Transfer Emulator","abstract":"This software will allow for the emulation of radiative transfer, specifically within exoplanet atmospheres. It will calculate the heating and cooling of atmospheric layers from incident stellar radiation and thermal flux. Broadly, this will involve a module to solve radiative transfer the traditional way to create a training set, and a module to learn the important relations based on this data . The ML architecture will be a recurrent neural network and/or a transformer model. These methods have been used before in Earth atmosphere contexts.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/imalsky/Emulator","license":null}},{"forgeId":"forge_nasa_npo_53411_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53411-1","sourceUrl":"https://software.nasa.gov/software/NPO-53411-1","confidence":"high"},"type":"software","title":"ECOSTRESS Collection 2 Level 2 Land Surface Temperature and Emissivity (LSTE) Product Generating Code","abstract":"This software package includes the code for the ECOSTRESS Collection 2 Level 2 Land Surface Temperature and Emissivity (LSTE) Product Generating Software (PGE). It was designed for use by the ECOSTRESS mission as a precursor for the Surface Biology and Geology (SBG) mission . This software provides estimates of LSTE and cloud mask data acquired by the ECOSTRESS radiometer. This package can be utilized for remote sensing research in Jupyter notebooks and deployed for operations in data processing pipelines. This software is being released according to the SPD-41 Open-Science requirements of NASA-funded projects.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/ECOSTRESS-Collection-3/ECOv003-L2-LSTE","license":null}},{"forgeId":"forge_nasa_npo_53421_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53421-1","sourceUrl":"https://software.nasa.gov/software/NPO-53421-1","confidence":"high"},"type":"software","title":"BioSTAR - NASA's Bioburden and Sampling Tool for Assessing Risk","abstract":"BioSTAR is an interactive, web-based tool that streamlines bioburden estimation and Planetary Protection Equipment List (PPEL) creation for spacecraft hardware. It converts sampling results into rigorous statistical estimates of microbial contamination with quantified uncertainty, integrating validated recovery efficiencies from common sampling devices. Users can access reference data from previous flight projects, apply NASA-STD 8719.27 specifications when direct sampling is unavailable, and generate spore densities with full probability distributions. BioSTAR also enables streamlined PPEL building, supporting reporting and risk analysis . The tool is available at https://biostar.jpl.nasa.gov/. Access privileges are required. For questions, access requests, or feedback, please contact michael.dinicola@jpl.nasa.gov.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa-jpl/biostar","license":null}},{"forgeId":"forge_nasa_npo_53433_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53433-1","sourceUrl":"https://software.nasa.gov/software/NPO-53433-1","confidence":"high"},"type":"software","title":"Time-series Forecasting Evaluation and Deployment (Time-FED)","abstract":"The Time-FED system is a machine learning system designed for preparing time-series for a variety of ML models. At its core, it is a sophisticated software framework for data scientists to transform time-series datasets into ML-ready datasets and trained models. The produced models are then ready for a real-time environment for forecasting purposes. One of the key features of Time-FED is its configuration flexibility for ML research. The system is designed by and for data science. By taking a generalized approach, Time-FED is capable of adapting to new use-cases all via its vast configuration. This framework allows for new infusions and use-case opportunities, making it an attractive collaboration platform for researchers interested in ML software developed by JPL.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/JPLMLIA/Time-FED.  Additionally, the docs are partially available here: https://jplmlia.github.io/Time-FED/","license":null}},{"forgeId":"forge_nasa_npo_53445_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53445-1","sourceUrl":"https://software.nasa.gov/software/NPO-53445-1","confidence":"high"},"type":"software","title":"CLC - a joint extrinsics-only LIDAR-camera calibration tool","abstract":"CLC establishes a procedure for gathering data to compute the relative transformations between each sensor's coordinates. CLC processes this data to report the sensor geometry and some uncertainty metrics to let the user know how trustworthy the results are, and how this confidence could be improved","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/dkogan/camera-lidar-calibration","license":null}},{"forgeId":"forge_nasa_npo_53446_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53446-1","sourceUrl":"https://software.nasa.gov/software/NPO-53446-1","confidence":"high"},"type":"software","title":"DEWPython","abstract":"DEWPython is a Python implementation of the Deep Earth Water (DEW) model for calculating thermodynamic properties of aqueous species at high temperatures (100-1200 degrees C) and pressures (1-60 kbar). The package streamlines the input process for the DEW model and integrates SUPCRT96/SUPCRTBL functionality, allowing users to compute Gibbs energies of formation, equilibrium constants, and standard volume changes for reactions in extreme environments.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/mmelwani/DEWPython","license":null}},{"forgeId":"forge_nasa_npo_53447_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53447-1","sourceUrl":"https://software.nasa.gov/software/NPO-53447-1","confidence":"high"},"type":"software","title":"ECCO Modeling Utilities (EMU)","abstract":"ECCO Modeling Utilities (EMU) a set of computational tools for analyzing the ECCO ocean state estimate. EMU is geared toward analyzing the model underlying the ECCO estimate, as opposed to exploring its discrete stateoutput in itself . In doing so, EMU helps investigate physical relationships governing variables in space, time and type that are difficult to infer from the state alone (e.g., causation). EMU is menu-driven with no modeling expertise required for its usage, aimed at separating the technical task of devising and implementing model computations (what EMU does) from the scientific application of these calculations (what EMU enables).","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/ECCO-GROUP/ECCO-EIS","license":null}},{"forgeId":"forge_nasa_npo_53458_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53458-1","sourceUrl":"https://software.nasa.gov/software/NPO-53458-1","confidence":"high"},"type":"software","title":"Constraint Based Fuzz Testing","abstract":"This repository contains a library fuzz for fuzz testing flight software. The main function, generate_tests, provided by the library, generates a test suite, which is a list of tests. Each test is a list of commands (a named data record), which can be sent to the flight software, referred to as the System Under Test (SUT), from a FIT script. Each test is randomly generated, optionally restricted by user provided constraints written in an expressive temporal logic. The objective of fuzzing is to invoke unlikely, untried, command sequences on the flight software in an attempt to break it.","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/havelund/fuzzing","license":null}},{"forgeId":"forge_nasa_npo_53468_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53468-1","sourceUrl":"https://software.nasa.gov/software/NPO-53468-1","confidence":"high"},"type":"software","title":"ECOSTRESS Collection 2 Level 1 Radiance, Attitude, & Geolocation Product Generating Code","abstract":"This software package includes the code for the ECOSTRESS Collection 2 Level 1 Product Generating Software (PGE). It was designed for use by the ECOSTRESS mission as a precursor for the Surface Biology and Geology (SBG) mission . This software provides corrected spacecraft altitude, calibrated at-sensor radiances and geolocation tags acquired by the ECOSTRESS radiometer. This package can be utilized for remote sensing research in Jupyter notebooks and deployed for operations in data processing pipelines. This software is being released according to the SPD-41 Open-Science requirements of NASA-funded projects as a counterpart to EMIT L1B geolocation open source package.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/ECOSTRESS-Collection-3/ECOv003-L1","license":null}},{"forgeId":"forge_nasa_npo_53469_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53469-1","sourceUrl":"https://software.nasa.gov/software/NPO-53469-1","confidence":"high"},"type":"software","title":"Python Tools for Machine Learning Bias Correction, Data Quality Filtering, and Uncertainty Analysis of OCO-2 XCO2 Retrievals","abstract":"The package ingests v11 OCO-2 Level 2 Lite files, derives >40 M training examples (2015-2022) matched to TCCON or 100km \"small-areas,\" and trains four Quantile-Regression-Forest models. Inference produces bias-corrected and filtered XCO2 and prediction intervals for every sounding, reducing land's bias RMSE by 20% and recovering usable data previously flagged QF=1.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/JPLMLIA/OCO_bias_filt","license":null}},{"forgeId":"forge_nasa_npo_53483_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53483-1","sourceUrl":"https://software.nasa.gov/software/NPO-53483-1","confidence":"high"},"type":"software","title":"Python suite for retrievals and analysis of microwave limb sounding data.","abstract":"A modular suite of python software that supports research on future instrument capabilities and retrieval and analysis from airborne microwave limb sounding instruments.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/njlivesey/dualpy","license":null}},{"forgeId":"forge_nasa_npo_53508_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53508-1","sourceUrl":"https://software.nasa.gov/software/NPO-53508-1","confidence":"high"},"type":"software","title":"EOS MLS Level 2 Data Processing Software, version 6","abstract":"This software accomplishes the following: The software reads MLS Level 1 products -- the EOS Microwave Limb Sounder (MLS) calibrated measurements of microwave radiances products -- and operational meteorological data to produce a set of estimates of atmospheric temperature and composition","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-MLS/mlspgs","license":null}},{"forgeId":"forge_nasa_npo_53509_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53509-1","sourceUrl":"https://software.nasa.gov/software/NPO-53509-1","confidence":"high"},"type":"software","title":"GDAL Plugin for NISAR HDF5 data products with Cloud-Optimized Access","abstract":"The NISAR GDAL driver solves the critical problem of making complex, multi-layered NISAR HDF5 product data easily accessible and usable within the broad ecosystem of GDAL-supported geospatial software. It bridges the gap between the specialized HDF5 file structure and the standardized raster data model expected by GIS applications by intelligently discovering and presenting relevant raster layers as distinct subdatasets, correctly interpreting and applying NISAR-specific georeferencing (including projection and geotransform from embedded coordinate/spacing datasets), and extracting file-level and dataset-specific metadata into standard GDAL domains. F","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/ozzp/nisar-hdf5-gdalplugin","license":null}},{"forgeId":"forge_nasa_npo_53512_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53512-1","sourceUrl":"https://software.nasa.gov/software/NPO-53512-1","confidence":"high"},"type":"software","title":"EOS MLS Level 1 Data Processing Software, version 6","abstract":"This software accepts the EOS MLS Level 0 science/engineering data and the EOS Aura spacecraft ephemeris/attitude data and produces calibrated instrument radiance and associated engineering and diagnostic data. The unique features of this software lie with the instrument and its unique capabilities to measure atmospheric radiance at the earth's limb.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-MLS/mlspgs","license":null}},{"forgeId":"forge_nasa_npo_53517_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53517-1","sourceUrl":"https://software.nasa.gov/software/NPO-53517-1","confidence":"high"},"type":"software","title":"INvestigation of Convective UpdraftS (INCUS), Dynamic Microwave Radiometer (DMR) Level 1B Algorithm","abstract":"The algorithm processes the spacecraft telemetry to provide an estimate of geolocation and other relevant observing geometry needed for understanding of the data. The main purpose of the algorithm is to transform the radiometric counts to the antenna temperature and brightness temperature. The algorithm also flags the data for quality control and creates netCDF output files.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/sci-mary/DMR-ground-processing","license":null}},{"forgeId":"forge_nasa_npo_53534_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53534-1","sourceUrl":"https://software.nasa.gov/software/NPO-53534-1","confidence":"high"},"type":"software","title":"MATLAB codes: Evaluation of Wet Snow Dielectric Mixing Models for LWA estimation in Greenland Percolation Zone","abstract":"Determining the effective permittivity of snow and firn is essential for the accurate estimation of liquid water amount (LWA). Here, we compare ten commonly used microwave dielectric mixing models for estimating LWA in snow and firn using L-band radiometry. We specifically focus on the percolation zone of the Greenland Ice Sheet (GrIS), where the average volume fraction of liquid water is approximately 6 percent. We used L-band brightness temperature (TB) observations from the NASA Soil Moisture Active Passive (SMAP) mission in an inversion-based framework to estimate LWA, applying different dielectric mixing formulations in forward simulation .","category":"design_integration","categoryRaw":"design and integration tools","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/HossanAlamgir/DielectricModels4WetSnow","license":null}},{"forgeId":"forge_nasa_npo_53544_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53544-1","sourceUrl":"https://software.nasa.gov/software/NPO-53544-1","confidence":"high"},"type":"software","title":"image-data","abstract":"image-data is a lightweight and efficient C++17 library for parsing and writing VICAR image files, a format widely used by NASA's Jet Propulsion Laboratory (JPL) on missions such as Mars 2020 and the Mars Science Laboratory. It is designed to address the challenge of decoding the VICAR format, which is commonly used for both internal mission data and publicly archived imagery in the Planetary Data System (PDS). The library is small, portable, and optimized for fast decoding, providing a modern and maintainable solution for working with mission -critical image data using the C++17 standard.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa-jpl/image-data","license":null}},{"forgeId":"forge_nasa_npo_53549_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53549-1","sourceUrl":"https://software.nasa.gov/software/NPO-53549-1","confidence":"high"},"type":"software","title":"Derived meteorological products for stratospheric observations","abstract":"This software interpolate meteorological fields (such as, temperature, wind speed, and ozone) to match the times and locations of atmospheric measurements. These routines also derive additional variables, including but not limited to static stability, potential temperature, equivalent latitude, and characterization of the jets and tropopauses.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-MLS/derived-meteorological-products/","license":null}},{"forgeId":"forge_nasa_npo_53558_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53558-1","sourceUrl":"https://software.nasa.gov/software/NPO-53558-1","confidence":"high"},"type":"software","title":"Global Sea Surface Height Anomaly Level 2 and Level 3 NetCDF Product Generation","abstract":"The software produces homogenized high quality NASA sea surface height datasets. It applies multiple rounds of quality control and validation algorithms to generate a unique quality flag for the data. It is designed to do so efficiently via highly parallelized serverless cloud computing using AWS Lambda and S3, allowing for near real time production of Level 2 and Level 3 data products","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/ssh-pipelines/altimetry-processing-pipeline","license":null}},{"forgeId":"forge_nasa_npo_53560_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53560-1","sourceUrl":"https://software.nasa.gov/software/NPO-53560-1","confidence":"high"},"type":"software","title":"Cloud Tomography Visualization","abstract":"The software illustrates the mission concept for a proposed constellation of cubesats intended to observe the 3-D structure of clouds. Additionally, the software converts scientific tomography data into a web-compatible format suitable for real-time visualization .","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/jackiryan/tomography-visualization","license":null}},{"forgeId":"forge_nasa_npo_53570_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53570-1","sourceUrl":"https://software.nasa.gov/software/NPO-53570-1","confidence":"high"},"type":"software","title":"Ocean Spatiotemporal Clustering System (OSTCS)","abstract":"A modular geospatial remote sensing pipeline that integrates NASA satellite data for oceanographic analysis using location blind time series clustering techniques. Features automated data downloading from NASA EarthData and implementation of functional data clustering via hypothesis testing k-means (Zambom et al., 2019) adapted for remote sensing applications. The clustering algorithm uses ANOVA and t-test statistics with conditional logic for time series grouping, processing 10 years of satellite data (May 2015-May 2025) to identify temporal patterns independent of spatial location before mapping results geographically. Built on hybrid Python-R architecture with functional data analysis, multi-resolution data fusion, and visualization capabilities.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/Originaljsx/OSTCS","license":null}},{"forgeId":"forge_nasa_npo_53571_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53571-1","sourceUrl":"https://software.nasa.gov/software/NPO-53571-1","confidence":"high"},"type":"software","title":"Disentangling Jupiter's Complex Atmospheric Processes Through the Application of Machine Learning Methods to JunoCam Data - v0.1","abstract":"The software has the following functions: 1) Create training data from JunoCam and Hubble Space Telescope in the form of segments from flattened maps2) Train a deep learning model for photometric calibration of JunoCam3) Provide a set of metrics to evaluate the calibration4) Post process the data by creating global mosaics of the calibrated segments 5) Provide tools to convert the data to PDS compliant formats","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/junocamcalibration/JunoCam_calibration_utils and https://github.com/junocamcalibration/JunoCam_calibration_UNSB","license":null}},{"forgeId":"forge_nasa_npo_53613_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53613-1","sourceUrl":"https://software.nasa.gov/software/NPO-53613-1","confidence":"high"},"type":"software","title":"drive-primer: A high-fidelity simulation suite for mobility planning","abstract":"Current mobility planning for downlink operations of the Mars 2020 rover depends on low fidelity slip tables parameterized by discrete terrain classes. Extrapolation of rover performance on these broad terrain classes is difficult and oftentimes inaccurate. This is especially crucial during mobility faults with highly non-linear and time-dependent dynamics on the wheels, where we can observe slip-sinkage, embedding, and cross slip. We propose drive-primer, a Bayesian optimization-driven framework to replicate mobility faults in a high-fidelity Project Chrono CRM/SPH simulator. The contributions of drive-primer are three-fold. (1) A parameter identification method to discover the local physics based parameters of terrain that has been driven over -- reconstructed in simulation with stereo-camera height maps, trajectory/poses generated by VO/SAPP, spacecraft EVRs, and joint telemetry. (2) This terrain parameterization is in a continuous parameter space (rather than broad classes), which is useful for qualitative comparison and analysis with respect to previous drive segments. (3) We demonstrate a use case, where with our dp-table tool and calibrated parameters, we generate a slip table that fuses telemetry and slip-slope CRM/SPH simulations into a Gaussian process for a more precise and 'high fidelity' slip table.","category":"aerospace","categoryRaw":"vehicle management space air ground","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa-jpl/drive-primer","license":null}},{"forgeId":"forge_nasa_npo_53614_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53614-1","sourceUrl":"https://software.nasa.gov/software/NPO-53614-1","confidence":"high"},"type":"software","title":"Orbiting Climate Observatory (OCO) Publication Tool","abstract":"Orbiting Carbon Observatory 2 (OCO-2) is an exploratory science mission designed to collect space-based global measurements of atmospheric CO2 with the precision, resolution, and coverage needed to characterize sources and sinks (fluxes) on regional scales. The Orbiting Carbon Observatory 3 (OCO-3) is a space instrument that will investigate important questions about the distribution of carbon dioxide on Earth as it relates to growing urban populations and changing patterns of fossil fuel combustion. Both study atmospheric carbon dioxide from space. It is important for these missions to keep track of the scientific discoveries made with the data collected by them. The OCO Publication Tool was designed to assist with this effort by taking alerts about newly published research and collecting them in a combined database that acts as a record of publications and keeps tracks of highlights from these publications.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-OCO/oco-publications","license":null}},{"forgeId":"forge_nasa_npo_53625_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53625-1","sourceUrl":"https://software.nasa.gov/software/NPO-53625-1","confidence":"high"},"type":"software","title":"Orbiting Climate Observatory 2 (OCO-2) Command Access Request (CAR) System","abstract":"OCO-2 collects a great number of high-resolution measurements, which provides a greater spatial distribution of CO2 over the entire globe; in short, a bigger, clearer, more complete picture of global CO2. These measurements are combined with data from the ground-based network to provide scientists with the information that they need to better understand the processes that regulate atmospheric CO2 and its role in the carbon cycle. This enhanced understanding is essential for improving predictions of future atmospheric CO2 increases and its impact on Earth's climate. The instrument was designed so that the science team could identify targets around the globe for observation and select which ones they want to observe on for a given day. The OCO-2 CAR tool collects information about OCO-2's potential targets for a given time period and allows the science team to make their selections and automatically notifies the instrument operations team. The website helps inform the science team's selections by providing them information about past target selections.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-OCO/oco2-car","license":null}},{"forgeId":"forge_nasa_npo_53627_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53627-1","sourceUrl":"https://software.nasa.gov/software/NPO-53627-1","confidence":"high"},"type":"software","title":"Orbiting Climate Observatory 3 (OCO-3) Command Access Request (CAR) System","abstract":"The Orbiting Carbon Observatory 3 (OCO-3) is a space instrument that will investigate important questions about the distribution of carbon dioxide on Earth as it relates to growing urban populations and changing patterns of fossil fuel combustion. OCO-3 explores, for the first time, daily variations in the release and uptake of carbon dioxide by plants and trees in the major tropical rain forests of South America, Africa, and South-East Asia, the largest stores of above ground carbon on our planet. Measuring the daily variations in these major carbon systems addresses an important missing component in our knowledge and is crucial for explaining global variations in atmospheric carbon dioxide levels. NASA developed and assembled the instrument using spare materials from OCO-2. The OCO-3 CAR tool collects information about OCO-3's potential targets for a given time period. It then generates a report used in a mission planning tool (CLASP). After observations have occurred, the CAR system keeps track of actual observations and discards information about ones that did not take place. The science team also updates information about how successful individual observations were, which feeds back into the report generated for CLASP.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/NASA-OCO/oco3-car","license":null}},{"forgeId":"forge_nasa_npo_53628_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53628-1","sourceUrl":"https://software.nasa.gov/software/NPO-53628-1","confidence":"high"},"type":"software","title":"Honeycomb Grafana","abstract":"Time series data visualization in 3D is a particularly challenging problem. Many solutions to this have been put forward however most assume a data schema that is difficult to generalize. This software looks to a take an existing 3D visualization platform, Honeycomb, and abstract the data handling from the actual visualization to allow plugging in a wide variety of data sources into the viewer. This software integrates with Grafana, an open source data observability platform that itself integrates with a wide-variety of database backends. This allows the Honeycomb viewer to focus on data visualization rather than data management/querying. It also opens avenues for easy integration with other tools/software such as Foxglove and ROS.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa-jpl/honeycomb","license":null}},{"forgeId":"forge_nasa_npo_53630_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53630-1","sourceUrl":"https://software.nasa.gov/software/NPO-53630-1","confidence":"high"},"type":"software","title":"Stuck Bits Detection Benchmark for Commodity Hardware","abstract":"The program reserves memory_size megabytes of memory using malloc and writes an array of different repeating pattern to the reserved locations. After a user-specified wait time, the memory location is then read back again, and the read pattern compared to the written one. Errors are then logged to <output_file_template>.csv in a CSV format. Kernel page information is also saved to allow logged virtual memory addresses to be converted to physical memory addresses. mlock is used to ensure that no memory is swapped out, while __clear__cache calls in between reads and writes ensure that data is read from DRAM and not the intermediate caches.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa-jpl/memhold","license":null}},{"forgeId":"forge_nasa_npo_53647_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53647-1","sourceUrl":"https://software.nasa.gov/software/NPO-53647-1","confidence":"high"},"type":"software","title":"GOES-SIF: Near-Real Time Solar-induced Chlorophyll Fluorescence (SIF) Estimation over the United States derived from OCO-3 and GOES-R ABI","abstract":"The objective of this research was to train a machine learning model to predict Solar-Induced Chlorophyll Fluorescence (SIF) by fusing data from the Orbiting Carbon Observatory-3 (OCO-3) instrument with multispectral data from the Geostationary Operational Environmental Satellites-R (GOES-R) series of weather satellites. This model was able to predict SIF at 1 km (0.01 degree) spatial resolution with hourly temporal resolution during daytime over the continental United States (CONUS). Validation of the model with reserved data points was performed to ensure that the predictions of SIF showed agreement with observations. A dropout test, where all points within a small region were excluded from the training set, was also performed to ensure that spatial biases were not incorporated into the data through training.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/jackiryan/GOES-SIF","license":null}},{"forgeId":"forge_nasa_npo_53707_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53707-1","sourceUrl":"https://software.nasa.gov/software/NPO-53707-1","confidence":"high"},"type":"software","title":"auto-priors-rs - Automatic TCCON priors","abstract":"This software is specifically designed to handle both ad hoc user requests for input files needed to run GGG for variable times and locations as well as ongoing generation of these files for sites with routinely operating instruments. Compared to other efforts to accomplish this task, auto-priors-rs is significantly more maintainable and extensible. By using Rust as the primary language, the strong type system design minimizes runtime errors. This is important as failures of this system impact users around the globe. It also facilitates future upgrades by allowing more errors to be caught at compile time.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/TCCON/auto-priors-rs","license":null}},{"forgeId":"forge_nasa_npo_53720_1","source":{"institution":"NASA","subUnit":"Jet Propulsion Laboratory","subUnitCode":"JPL","nativeId":"NPO-53720-1","sourceUrl":"https://software.nasa.gov/software/NPO-53720-1","confidence":"high"},"type":"software","title":"Delay Tolerant Networking Interface for Robotics Systems","abstract":"Develop a gateway module to enable communication between isolated ROS2 networks through a DTN using the ION framework. Ensure transparent interoperability (ROS2 nodes should exchange data without any modification to their code). Design an autonomous discovery mechanism allowing gateways to detect each other and establish communication automatically. Guarantee reliable data delivery despite network disruptions, latency, or intermittent connectivity. Provide a modular, reusable C library easily integrable into other systems.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa-jpl/ros2-ion","license":null}},{"forgeId":"forge_nasa_ssc_00151_1","source":{"institution":"NASA","subUnit":"Stennis Space Center","subUnitCode":"SSC","nativeId":"SSC-00151-1","sourceUrl":"https://software.nasa.gov/software/SSC-00151-1","confidence":"high"},"type":"software","title":"Engineering Units Generator (EUGEN)","abstract":"EUGEN converts digitized sensor output voltage data to engineering units. The tool creates individual processed data files (one file per transducer per test run), converting raw voltage to meaningful measurements such as pressure or temperature. Engineering Units are generated by the Low Speed Data Processing System (LSDPS) in addition to performing calculated values or parameters at different levels in order to provide the customer with the final data product. LSDPS utilizes the NIST REFPROPS program to calculate thermo-physical properties over a wide range of temperatures and pressures. Use of these programs requires proficiency in Linux, C and PV-Wave (separate license required) programming languages and bash scripts. A GCC compiler is invoked with the make file in each C code program directory. Winplot is the general-purpose plotting utility.A Developers Guide provides specifics on the hardware and software requirements needed to execute the tool.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_ssc_00181","source":{"institution":"NASA","subUnit":"Stennis Space Center","subUnitCode":"SSC","nativeId":"SSC-00181","sourceUrl":"https://software.nasa.gov/software/SSC-00181","confidence":"high"},"type":"software","title":"Application Research Toolbox (ART)","abstract":"The Application Research Toolbox (ART) is a collection of computer programs that implement algorithms and parametric mathematical models for simulating remote sensing systems, developed in MATLAB. The ART is intended to be especially useful for performing design -tradeoff studies and statistical analyses to support the rational development of design requirements for multispectral imaging systems. Among other things, the ART affords a capability to synthesize coarser-spatial-resolution image-data sets from finer-spatial-resolution data sets and multispectral-image-data products from hyperspectral-image-data products. The ART also provides for synthesis of image-degradation effects, including point-spread functions, misregistration of spectral images, and noise. The ART can utilize real or synthetic data sets, along with sensor specifications, to create simulated data sets. In one example of a typical application, simulated data pertaining to an existing multispectral sensor system are used to verify the data collected by the system in operation. In the case of a proposed sensor system, the simulated data can be used to conduct trade studies and statistical analyses to ensure that the sensor system will satisfy the requirements of potential scientific, academic, and commercial user communities. ART is designed to run on a standard Windows NT/2000 workstation and MATLAB version 6.5. A Programmers Reference is included to provide additional detail on setting up the operational environment.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_ssc_00281","source":{"institution":"NASA","subUnit":"Stennis Space Center","subUnitCode":"SSC","nativeId":"SSC-00281","sourceUrl":"https://software.nasa.gov/software/SSC-00281","confidence":"high"},"type":"software","title":"Rocket Plume Spectroscopy Simulation for Hydrocarbon-Fueled Rocket Engines","abstract":"Enhancements and modifications to a code developed for plume spectral data analysis in 1994 have made the original computer program applicable to the Space Shuttle Maine Engine and the Diagnostic Test-bed Facility Thruster (DTFT). The new code can now handle the non-uniform wavelength intervals at which spectral computations are made.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_ssc_00321","source":{"institution":"NASA","subUnit":"Stennis Space Center","subUnitCode":"SSC","nativeId":"SSC-00321","sourceUrl":"https://software.nasa.gov/software/SSC-00321","confidence":"high"},"type":"software","title":"Phenological Parameters Estimation Tool (PPET)","abstract":"The Phenological Parameters Estimation Tool (PPET) is a set of algorithms implemented in MATLAB that estimates key vegetative phenological parameters. For a given year, the PPET software package takes in temporally processed vegetation index data (3-D spatio-temporal arrays) generated by the Time Series Product Tool (TSPT) and outputs spatial grids (2-D arrays) of vegetation phenological parameters. As a precursor to PPET, the TSPT uses quality information for each pixel of each date to remove bad or suspect data, and then interpolates and digitally filters the time series to produce a continuous, smoothed vegetation index product in which data voids are eliminated. Both the TSPT and PPET use Moderate Resolution Imaging Spectroradiometer (MODIS) satellite multi-spectral data as a default, but each software package is easily modifiable and could be used with any high-temporal-rate remote sensing system that is capable of producing vegetation indices.Unlike other known plant phenological parameter estimation software, the PPET produces not only common phenological parameters but also real-time and custom parameters without a priori assumptions about the shape of the phenological cycle. Common phenological parameters, like those produced in PPET, are associated with the annual vegetation growth cycle. They quantitatively describe vegetative states related to annual cyclical growing seasons, such as green-up, maturity, senescence, and dormancy, by analyzing the temporal shape of given vegetation index time series. The real-time phenological and custom parameters are formed from a cumulative sum (integral) produced at a fixed temporal interval. In addition, a cumulative vegetation index and time-specific/pest-specific phenological parameters can be designed to optimize the detection of vegetation damage from specific pests and diseases. These problem-specific phenological parameters have the potential to be integrated into near real-time, predictive surveillance systems (i.e. early warning systems) and, with improved vegetative state information, could assist decision makers in making intelligent vegetation and associated land resource management choices.MATLAB, MATLAB Runtime Library and ERDAS IMAGINE are required to run the software.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_ssc_00339","source":{"institution":"NASA","subUnit":"Stennis Space Center","subUnitCode":"SSC","nativeId":"SSC-00339","sourceUrl":"https://software.nasa.gov/software/SSC-00339","confidence":"high"},"type":"software","title":"Spatial Resolution Verification Tool (SRVT)","abstract":"An automated Spatial Resolution Verification Tool (SRVT) was developed to rapidly determine the spatial resolution characteristics of remotely sensed aerial and satellite imagery. Most current methods for assessing spatial resolution characteristics of imagery rely on pre-deployed engineered targets and are performed only at selected times within pre-selected scenes. The SRVT addresses these insufficiencies by finding uniform, high-contrast edges from urban scenes and then using these edges to determine standard estimators of spatial resolution, such as the modulation transfer function (MTF) and the relative edge response (RER).Developed using the MATLAB programming language and environment, this automated software algorithm assesses every image in an acquired data set, using edges found within each image, and in many cases eliminating the need for dedicated edge targets. SRVT automatically identifies high-contrast, uniform edges and calculates the MTF and RER of each image, and when possible, within sections of an image, so that the variation of spatial resolution characteristics across the image can be analyzed. The automated algorithm is capable of quickly verifying the spatial resolution quality of all images within a data set, enabling the appropriate use of those images in a number of applications.The SRVT has been validated against traditional techniques using IKONOS and QuickBird satellite imagery.","category":"imaging_optics","categoryRaw":"data and image processing","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_ssc_00393","source":{"institution":"NASA","subUnit":"Stennis Space Center","subUnitCode":"SSC","nativeId":"SSC-00393","sourceUrl":"https://software.nasa.gov/software/SSC-00393","confidence":"high"},"type":"software","title":"Software Suite to Support In- Flight Characterization of Remote Sensing Systems","abstract":"A software suite, developed to support NASAs in- flight characterization of commercial remote sensing systems, efficiently automates reproducible processing of ground truth data. It is unique in that it takes input from a number of disparate data sources, condenses and rapidly processes it, to a form useable by the characterization process. It has been largely automated to reduce operator error as much as possibleWritten and developed in the MATLAB programming environment, the characterization suite consists of radiometric, geometric and spatial scripts that require knowledge of MODTRAN and expertise to run. Each type of characterization relies on knowledge of ground characteristics, or ground truth, some of which must be acquired at the time of sensor overpass. Examples of ground truth data include target reflectance, incident solar irradiance, atmospheric pressure and water vapor, aerosol content, and target location. All of these data sets must be processed in order to be used for in- flight characterization.Previously used to perform radiometric, geometric, and spatial characterization on the IKONOS, QuickBird, OrbView-3, and AWiFS satellite sensors.","category":"software_data","categoryRaw":"data servers processing and handling","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_ssc_00404","source":{"institution":"NASA","subUnit":"Stennis Space Center","subUnitCode":"SSC","nativeId":"SSC-00404","sourceUrl":"https://software.nasa.gov/software/SSC-00404","confidence":"high"},"type":"software","title":"Time Series Product Tool (TSPT) 3.0","abstract":"The Time Series Product Tool (TSPT) is custom designed software developed to compute and display superior quality Normalized Difference Vegetation Index (NDVI) images from satellite data products for enabling or aiding rapid regional surveillance of canopy greenness for crops, forests, and other vegetative surfaces. TSPT was developed in the MATLAB programming environment, and allows users to compute and display various Moderate Resolution Imaging Spectroradiometer (MODIS) products as single time frame and multi-temporal change images, as time series plots at a selected location, or as temporally processed image videos. This is significant because the labor involved with manually creating these types and quantities of products is considerable; however, by using the TSPT software tool, this process becomes simplified, efficient, and largely automated.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_ssc_00424","source":{"institution":"NASA","subUnit":"Stennis Space Center","subUnitCode":"SSC","nativeId":"SSC-00424","sourceUrl":"https://software.nasa.gov/software/SSC-00424","confidence":"high"},"type":"software","title":"Stennis Space Center (SSC) Site Status Mobile Application","abstract":"This application provides SSC civil servants, contractors, and tenants the ability to view the Center's weather radar and current site status bulletin from a mobile device. The application also alerts users via push notification when a new site status is posted. Available at the Apple App Store.","category":"operations","categoryRaw":"business systems and project management","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":"https://itunes.apple.com/us/app/ssc-site-status/id706044417?mt=8","license":null}},{"forgeId":"forge_nasa_ssc_00492","source":{"institution":"NASA","subUnit":"Stennis Space Center","subUnitCode":"SSC","nativeId":"SSC-00492","sourceUrl":"https://software.nasa.gov/software/SSC-00492","confidence":"high"},"type":"software","title":"Coastal Salinity and Temperature (CSalT) Web Application","abstract":"The Coastal Salinity and Temperature Monitoring (CSalT) web application Version 1.0, objective is to provide daily access to salinity and temperature data on a continuous and unrestricted basis to authorized users. Numerical model data from multiple sources is collected and integrated with NASA remotely sensed satellite data to provide up-to-date and historical information on water temperature, salinity and oyster lease locations for coastal environments along the Gulf of Mexico. This information is provided in a Google Maps based interface with custom controls for navigation and analysis enabling users to review trends and statistics for their areas of interest. The data can be used to complement in-situ data to help assess oyster health and has the potential to provide information that can aid in the decision making process for identifying suitable habitat for future oyster reef locations.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_ssc_00505","source":{"institution":"NASA","subUnit":"Stennis Space Center","subUnitCode":"SSC","nativeId":"SSC-00505","sourceUrl":"https://software.nasa.gov/software/SSC-00505","confidence":"high"},"type":"software","title":"Algorithm for Automated Sargassum Detection for Landsat-8 OLI Imagery","abstract":"Methodology and software were implemented to automatically detect Sargassum spp., a floating aquatic seaweed, in 30-meter LANDSAT-8 Operational Land Imager (OLI) imagery. This Sargassum spp. detection is an extended form of Hus approach to derive a floating algae index (FAI), which is defined as the difference between the reflectance at the near infrared band (NIR, 859 nm) (vegetation red edge) and the linear baseline between the red band (645 nm) and short-wave infrared band (SWIR, 1240 or 1640 nm). The Hus algorithm was developed for the Moderate Resolution Imaging Spectroradiometer (MODIS) data , but we extended it for use with the OLI bands (655, 865, and 1609 nm), which are comparable to MODIS bands (645, 859, and 1640 nm). We also developed a high resolution true color product to mask cloud pixels in the OLI scene by applying a threshold to top of the atmosphere (TOA) radiances in the red (655 nm), green (561 nm), and blue (443 nm) wavelengths, and software to remove false positive identifications of Sargassum spp in the imagery. Hus algorithm derives a FAI for each Sargassum spp identified pixel. Our algorithm only flags the presence of Sargassum spp in an OLI pixel by indicating that any pixel with a FAI > 0.0 is a Sargassum spp pixel. Additionally, our software geo-locates the flagged Sargassum spp pixels identified in the OLI imagery into the U.S. Navy Global HYCOM model grid. One element of the model grid used, covers an area 0.125degree of latitude by 0.125 degree of longitude. An OLI pixel is only 30m by 30 m. To resolve the differences in spatial coverage, a scheme was developed in which the total number of Landsat OLI pixels within a grid element of the model are counted, and if more than 1% of those pixels are pixels flagged as containing Sargassum spp, then the geographical location within the model is annotated. The end product is an ASCII file that contains latitude, longitude pairs that are used as input for the next stage in the processing stream, which is a clustering algorithm or a model initialization parameter. The numerical model grid must be in p lace before the geolocation takes place.The focus of this application is the automatic identification of Sargassum spp. in visible data of the Operational Land Imager (OLI) on board LANDSAT-8 in the Gulf of Mexico. The identification is followed up by a routine to map their location inside the Hybrid Coordinate Ocean Model MODEL (HYCOM) surface grid. This methodology, developed by the Naval Research Laboratory for the NASA/Applied Science and Technology Project (ASTPO), is applicable worldwide requiring only minor changes in the geolocation of the area of interest.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_ssc_00507","source":{"institution":"NASA","subUnit":"Stennis Space Center","subUnitCode":"SSC","nativeId":"SSC-00507","sourceUrl":"https://software.nasa.gov/software/SSC-00507","confidence":"high"},"type":"software","title":"MEKONG RIVER TOTAL SUSPENDED SEDIMENT SOFTWARE APPLICATIONS (Mekong_TSS)","abstract":"The Mekong River Total Suspended Sediment Software Application (TSS_Mekong) computes the total suspended sediment (TSS) concentrations of the Mekong River from data of the Operational Land Imager (OLI), flying on board of the LANDSAT-8. In this application, computation of TSS follows a two-step process which includes; 1) generating the remote sensing reflectance and/or surface reflectance products using SeaDAS, a NASA comprehensive image analysis package for the processing, display, analysis , and quality control of ocean color data, and 2) running the programgen_tss on the SeaDAS output files to generate the total suspended sediment (TSS) images. The TSS_Mekong was developed with in-situ measurements of the Mekong River waters, acquired by NASA, the Naval Research Laboratory (NRL) and Khon Kaen University of Thailand personnel during March 2016.","category":"environment_climate","categoryRaw":"environmental science earth air space exoplanet","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"General Public Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_16074_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-16074-1","sourceUrl":"https://software.nasa.gov/software/LEW-16074-1","confidence":"high"},"type":"software","title":"CSPAN Axial-Flow Compressor Conceptual Design Code","abstract":"This span-line analysis technology uses isentropic simple radial equilibrium to determine a flow path.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_16323_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-16323-1","sourceUrl":"https://software.nasa.gov/software/LEW-16323-1","confidence":"high"},"type":"software","title":"Axial-Flow Turbine Off-Design (AXOD) Performance","abstract":"AXOD computes the flow and efficiency of multistage axial-flow turbines as functions of speed and pressure ratio. The technology uses a span-line analysis with simple radial equilibrium. The loss model includes blade-row inlet losses, blade-row losses, and stage-test losses. Coefficients are selected to match the known design-point performance, and the internal model provides the off-design performance.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_16582_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-16582-1","sourceUrl":"https://software.nasa.gov/software/LEW-16582-1","confidence":"high"},"type":"software","title":"Computational Fluid Dynamics (CFD) Seal Analysis Code","abstract":"This technology is a computer program designed for the study of fluid dynamic forces.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_16768_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-16768-1","sourceUrl":"https://software.nasa.gov/software/LEW-16768-1","confidence":"high"},"type":"software","title":"Advanced Ducted Propfan Analysis Code (ADPAC)","abstract":"Developed by the Allison Engine Company under contracts with Glenn Research Center, ADPAC solves tightly coupled internal/external flows through future-concept short-duct turbofan engines.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_16855_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-16855-1","sourceUrl":"https://software.nasa.gov/software/LEW-16855-1","confidence":"high"},"type":"software","title":"APNASA, Average-Passage Multistage Turbomachinery Flow Field Analysis Code","abstract":"APNASA simulates the three-dimensional viscous flowfield through an entire compressor or turbine consisting of multiple rows of blades in a single computational job. A grid is generated which encompasses all blade rows. Boundary conditions are imposed upstream of the first blade row and downstream of the last blade row-no boundary conditions are set between blade rows. The code marches forward in time on the flowfield solution within all the blade rows. During the solution process the code periodically calculates the time-average glow in each of the blade rows and information required to model blade-row interaction effects between each blade row and its neighbors. The code passes this information to all of the blade rows as it continues forward in time. When the solution converges to a user-specified tolerance, the simulation of the flowfield through the entire turbomachine is realized and the user obtains a time-average description of the three-dimensional viscous flow in each blade row. Since information on blade row interactions is passed from row-to-row throughout the solution process, the simulation includes the time-average effects of neighboring blade rows on one another","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_17293_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-17293-1","sourceUrl":"https://software.nasa.gov/software/LEW-17293-1","confidence":"high"},"type":"software","title":"A Comprehensive C Controller For A Magnetically Supported Vertical Rotor: Version 1.0","abstract":"FATMaCC (Five-Axis, Three-Magnetic-Bearing Control Code), is a versatile control code that possesses many desirable features that were not available in previous in-house controllers. The ultimate goal in designing this code was to achieve full rotor levitation and control at a loop time of 50 s. Using a 1-GHz processor the code will control a five-axis system in either a decentralized or a more elegant centralized (model control ) mode at loop time of 56 s. In addition, it will levitate and control (with only minor modification to the input-output wiring) a two-axis and / or a four-axis system. Stable rotor levitation and control of any of the system mentioned above are accomplished through appropriate key presses to modify parameters, such as stiffness, damping, and bias. A signal generation block provides 11 excitation signals. An excitation signal is then superimposed on the radial bearing x- and y- control signals, thus producing a resultant force vector. By modulating the signals on the bearing x0 and y- axes with a cosine and sine function, respectively, a radial excitation force vector is made to rotate 360 about the bearing geometric center. The rotation of the force vector is achieved manually by using key press or automatically by engaging the \" one-per-revolution\" feature. Rotor rigid body modes can be excited by using the excitation module. Depending on the polarities of the excitation signal in each radial bearing, the bounce or tilt mode will be excited","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_17448_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-17448-1","sourceUrl":"https://software.nasa.gov/software/LEW-17448-1","confidence":"high"},"type":"software","title":"ACD Aerodynamic Design of Multistage Axial-Flow Compressors","abstract":"ACD is an analysis code used for the aerodynamic design of multistage axial-flow compressors. The technology provides velocity diagrams on the streamlines at the blade-row edges. Blade elements are defined by centerline curve and thickness distribution, and blade-element inlet and outlet angles are established through empirical incidence and deviation-angle adjustments to the velocity diagrams. Blade elements can be stacked to provide the full blade design.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_17449_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-17449-1","sourceUrl":"https://software.nasa.gov/software/LEW-17449-1","confidence":"high"},"type":"software","title":"ACOD Multistage Axial-Flow Compressor Off-design","abstract":"A companion tool to Glenn Research Center's ACD software (LEW-17448), ACOD is streamline analysis code for predicting the off-design performance of multistage axial-flow compressors. Flow, blading, and loss are modeled similarly to ACD.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_17450_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-17450-1","sourceUrl":"https://software.nasa.gov/software/LEW-17450-1","confidence":"high"},"type":"software","title":"Centrifugal Off- Design Performance (CCODP) Compressor","abstract":"CCODP is a one-dimensional off- design performance prediction code used for centrifugal compressors. Correlations account for the following types of loss: inlet guide vane, impeller incidence, shock, skin friction, blade loading, trailing edge, clearance, vaneless and vaned diffuser friction, recirculation, and disk friction.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_17451_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-17451-1","sourceUrl":"https://software.nasa.gov/software/LEW-17451-1","confidence":"high"},"type":"software","title":"CMPSTK Multi-Stage Axial-Flow Compressor Off- Design","abstract":"Developed for studying variable geometry effects at the conceptual design level, CMPSTK is a combination of the STGSTK and CMPGEN computer codes. STGSTK predicts multistage axial-flow compressor off- design performance using mean-line stage stacking, and CMPGEN estimates design -speed flow range and efficiency ratios.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_17454_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-17454-1","sourceUrl":"https://software.nasa.gov/software/LEW-17454-1","confidence":"high"},"type":"software","title":"TURBAN Turbomachine Design Code","abstract":"TURBAN analysis is performed at the arithmetic mean diameter. The stage velocity diagrams are either all similar (therefore have the same work factor) or are determined from an input stage work split. All stages have the same stator exit angle. Stage-by-stage tailoring of the velocity diagrams is not allowed.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_17670_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-17670-1","sourceUrl":"https://software.nasa.gov/software/LEW-17670-1","confidence":"high"},"type":"software","title":"Time-Accurate Quasi-One Dimensional Reactive Code For Design And Analysis Of Gasdynamic-Based Propulsion Systems","abstract":"A time-accurate, quasi-one-dimensional, reactive CFD code for design and analysis of gasdynamic-based propulsion systems has been developed. These include, but are not limited to, wave rotor based internal and external combustion systems, Pulse Detonation Engines (PDEs), and deflagrative pulse combustors. The code utilizes established numerical techniques and simplified loss-models to accurately simulate system flow fields. It contains robust boundary condition procedures which yield limit cycle behavior even in extreme off-design scenarios. The simplified quasi-one-dimensional nature of the code yields rapid solutions using modest computational resources. This allows for timely parametric analysis and preliminary design of conceptual systems.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_17674_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-17674-1","sourceUrl":"https://software.nasa.gov/software/LEW-17674-1","confidence":"high"},"type":"software","title":"Modular Aero-Propulsion System Simulation (MAPSS)","abstract":"MAPSS is a flexible turbofan engine simulation environment that provides easy access to health, control, and engine parameters through a graphical user interface. The technology can be used as a simulation environment for developing and testing advanced control algorithms, or it can run transient simulations or generate state-space linear models for creating a piecewise linear controller.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_17816_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-17816-1","sourceUrl":"https://software.nasa.gov/software/LEW-17816-1","confidence":"high"},"type":"software","title":"SNAP, Version 2.3","abstract":"SNAP is an N-body high-fidelity propagation program that can model the trajectories of the planets, the Sun, and virtually any natural satellite in the solar system.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_17898_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-17898-1","sourceUrl":"https://software.nasa.gov/software/LEW-17898-1","confidence":"high"},"type":"software","title":"Compressible Flow Toolbox","abstract":"The Compressible Flow Toolbox is a set of algorithms that solve classical compressible equations for isentropic flow, fanno flow, Rayleigh flow, normal shock, oblique shock, and expansion. Implemented in the MATLAB programming language, the technology can be used in the analysis of one-dimensional steady flow with constant entropy, with friction, with heat transfer, or with supersonic Mach numbers.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_18315_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-18315-1","sourceUrl":"https://software.nasa.gov/software/LEW-18315-1","confidence":"high"},"type":"software","title":"Commercial Modular Aero-Propulsion System Simulation (C-MAPSS)","abstract":"Written in a combination of MATLAB and Simulink, C-MAPSS provides a realistic simulation of a large commercial turbofan engine. The technology includes a number of graphical user-interface screens that allow point-and-click operation.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_18315_2","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-18315-2","sourceUrl":"https://software.nasa.gov/software/LEW-18315-2","confidence":"high"},"type":"software","title":"Commercial Modular Aero-Propulsion System Simulation (C-MAPSS), Version 2","abstract":"Version 2 of C-MAPSS provides a transient simulation of a large commercial turbofan engine with a realistic engine control system. Written in a combination of MATLAB and Simulink, the software supports easy access to health, control, and engine parameters through a graphical user interface. Retaining the convenience and user-friendliness of the original, Version 2 includes three actuators (as compared to one) and offers an improved controller as well as added actuator and sensor dynamics.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_18624_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-18624-1","sourceUrl":"https://software.nasa.gov/software/LEW-18624-1","confidence":"high"},"type":"software","title":"Commercial Modular Aero-Propulsion System Simulation 40k (C-MAPSS40k)","abstract":"Developed in the MATLAB/Simulink environment, C-MAPSS40k is a high-fidelity transient simulation of a generic commercial turbofan engine with a 40,000-pound thrust. The nonlinear physics-based component-level model operates up to Mach 0.8 over a wide ambient temperature range and executes faster than real time. The model can be run from the command line or by using a graphical user interface.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_19031_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19031-1","sourceUrl":"https://software.nasa.gov/software/LEW-19031-1","confidence":"high"},"type":"software","title":"Computed Tomography Cylinder Unwrapper/Re-slicer Software (CT-CURS), Version 2","abstract":"CT-CURS is a dedicated unwrapping/re-slicing software tool for computing tomography data from cylindrical and partially cylindrical structures. The technology can be used as a complement to vendor software or can be utilized as a completely standalone visualization program.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_19061_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19061-1","sourceUrl":"https://software.nasa.gov/software/LEW-19061-1","confidence":"high"},"type":"software","title":"Object-oriented Turbomachinery Analysis Code (OTAC)","abstract":"The OTAC software is a set of interpreted objects that extend the capabilities of the NPSS software framework to allow for design and analysis of turbomachinery. OTAC allows for user specification of various gas compositions as the working fluid. The user also has flexibility in selecting loss models, deviation models, and blockage models, and can create and apply their own such correlations.OTAC is an engineering research tool still in development with new features being added and existing features refined.NPSS is the Numerical Propulsion System Simulation code; it performs 1-D thermodynamic cycle analysis of gas turbine engines. Access to NPSS is required to run the OTAC software.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_19165_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19165-1","sourceUrl":"https://software.nasa.gov/software/LEW-19165-1","confidence":"high"},"type":"software","title":"Toolbox for the Modeling and Analysis of Thermodynamic Systems (T-MATS)","abstract":"T-MATS is open source software code. The Toolbox for the Modeling and Analysis of Thermodynamic Systems (T-MATS) is a Simulink toolbox intended for use in the modeling and simulation of thermodynamic systems and their controls. T-MATS contains generic thermodynamic and controls components that may be combined with a variable input iterative solver and optimization algorithm to create complex systems to meet the needs of a developer. Developement of this tool was completed on behalf of the NASA Aviation Safety Program's Vehicle Systems Safety Technologies (VSST) project located at the Glenn Research Center in Cleveland, OH.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/T-MATS","license":null}},{"forgeId":"forge_nasa_lew_19264_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19264-1","sourceUrl":"https://software.nasa.gov/software/LEW-19264-1","confidence":"high"},"type":"software","title":"EADIN Communication Protocol","abstract":"The product of this work is a communication protocol which allows microcontrollers to talk with eachother in a structured fashion. As such, it is embodied in C++ code that runs on the microcontroller. The software is not mission certified and is being used for demonstration and testing purposes only. The current goal of this project is to realease the software open source to enable community participation. We have external companies requesting that we release this software.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/EADINLite","license":null}},{"forgeId":"forge_nasa_lew_19488_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-19488-1","sourceUrl":"https://software.nasa.gov/software/LEW-19488-1","confidence":"high"},"type":"software","title":"Simplified Quasi-Two-Dimensional Computational Fluid Dynamic Simulation for Rotating Detonation Engine Analysis","abstract":"A quasi-two-dimensional, computational fluid dynamic (CFD) simulation of a rotating detonation engine (RDE) has been developed. The simulation operates in the detonation frame of reference and utilizes a relatively coarse grid such that only the essential primary flow field structure is captured. This construction and other simplifications yield rapidly converging, steady solutions that can be obtained on a modern single processor computer. Viscous effects, and heat transfer effects are modeled using source terms. The effects of potential inlet flow reversals are modeled using boundary conditions. Output from the simulation compares favorably to measured data from numerous experimental RDE rigs. The speed and fidelity of the code render it useful as a performance optimization tool as well as a diagnostic tool to supplement the current limitations of experimental measurement techniques in the hostile engine environment.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_20136_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20136-1","sourceUrl":"https://software.nasa.gov/software/LEW-20136-1","confidence":"high"},"type":"software","title":"SUPIN Supersonic Inlet Design and Analysis Tool (Version 2025A, June 2025)","abstract":"The SUPIN Supersonic Inlet Design and Analysis Tool performs design and analysis of axisymmetric pitot, three-dimensional pitot, axisymmetric-spike, two-dimensional, and streamline-traced inlets using an input data file consisting of input factors. SUPIN writes an output data file containing inlet performance metrics and geometric data. The inlet performance metrics calculated include the flow rates, total pressure recovery, and drag. SUPIN can create the surface grids for the inlets that may be used to visualize the inlet geometry, as well as, generate volume grids for computational fluid dynamics (CFD) simulations. SUPIN can also automatically generate three-dimensional, multi-block structured grids for CFD simulations.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_20180_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20180-1","sourceUrl":"https://software.nasa.gov/software/LEW-20180-1","confidence":"high"},"type":"software","title":"Three-Dimensional Nozzle Design Code","abstract":"This program uses the three-dimensional method of characteristics and streamline-tracing techniques to develop complex nozzle expansion surfaces. It is intended to facilitate integration of a high speed vehicle aft-body with its propulsive flowpath.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://github.com/nasa/Three-Dimensional-Nozzle-Design-Code","license":null}},{"forgeId":"forge_nasa_lew_20413_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20413-1","sourceUrl":"https://software.nasa.gov/software/LEW-20413-1","confidence":"high"},"type":"software","title":"Upgrades to OpenNCC","abstract":"New features added to code addressing combustor cooling and combustor-turbine coupled simulations. The new features included high-order CFD method for large eddy simulations (LES), improved overset mesh interface, vastly improved sliding mesh interface.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_20423_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20423-1","sourceUrl":"https://software.nasa.gov/software/LEW-20423-1","confidence":"high"},"type":"software","title":"A Simple Model for Rotating Detonation Rocket Engine Sizing and Performance Estimates","abstract":"A simple model for a Rotating Detonation Rocket Engine (RDRE) engine cycle. Two implementations of this model are provided. The first implementation is a Visual Basic computer code that resides as a macro for execution in a Microsoft Excel Spreadsheet. The spreadsheet is the interface for the code where required inputs may be supplied and outputs are recorded. The alternate implementation is a MATLAB code. The MATLAB implementation includes a user interface and the MATLAB subroutines that perform the RDRE calculations. The result is a RDRE simulation that runs on a personal computer and can deliver reasonable estimates of engine performance, size, and flow rate for a given notional application. This in turn allows preliminary assessment of RDRE benefits for various missions.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_20560_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20560-1","sourceUrl":"https://software.nasa.gov/software/LEW-20560-1","confidence":"high"},"type":"software","title":"Cryogenic Flow Boiling in Heated Tubes Code Infrastructure for Thermal Desktop","abstract":"To enable the design of future in-space cryogenic propellant vehicles such as Lunar and Martian ascent and descent stages and the nuclear thermal propulsion system, high accuracy models of various phases of the propellant transfer process are required. This NTR focuses on modeling and development of new code infrastructure of steady state flow boiling through the transfer line that connects a propellant tank to an engine or customer receiver tank, which is required to set limits on the allowable heat flux into the line. Using the largest ever collection of available cryogenic heated tube data, universal cryogenic flow boiling correlations were recently developed for various regimes of the boiling curve. However, to model flow boiling in heated tubes, these individual correlations must be patched together to provide a continuous predictive curve of wall superheat as a function of preponderant parameters. This NTR covers the individual flow boiling correlations along with the logic and methodology for patching the correlations together to produce a single continuous boiling curve in a user-defined subroutine. In turn, the subroutine can be called by higher order lumped capacitance codes such as Thermal Desktop.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_lew_20614_1","source":{"institution":"NASA","subUnit":"Glenn Research Center","subUnitCode":"GRC","nativeId":"LEW-20614-1","sourceUrl":"https://software.nasa.gov/software/LEW-20614-1","confidence":"high"},"type":"software","title":"Advanced Geared Turbofan 30,000lbf \u2013 Electrified (AGTF30-e) Dynamic Engine Model and Controller","abstract":"The Advanced Geared Turbofan 30,000lbf - Electrified (AGTF30-e) is a dynamic model of a geared turbofan with electrification options. The model is built upon the previously released Advanced Geared Turbofan 30,000lbf (AGTF30). The model was constructed with the Toolbox for Modeling and Analysis of Thermodynamic Systems (T-MATS) within the MATLAB/Simulink Coding environment. The engine model is based upon the same NASA N+3 concept as the original AGTF30. It features a compact core and a variable area fan nozzle. The AGTF30-e has several features that can be leveraged to carryout numerous studies with respect to electrification. The model can represent a conventional engine or a mild hybrid that includes some electrified features. The model can also represent boost operation, which defines thrust augmentation over key mission segments. The final primary operating mode is power extraction, in which a significant amount of power is extracted from the engine shafts to produce thrust elsewhere on the airframe. In addition, there are options to enable additional features such as electric power transfer (EPT) to enhance performance at low engine power levels, and Turbine Electrified Energy Management (TEEM) to improve transient operability and alleviate dynamically driven design constraints. Finally, the model can implement two methods of engine and electric machine integration. One method provides a baseline through integrating electric machines with each engine shaft. The other method reflects the Versatile Electrically Augmented Turbine Engine (VEATE) gearbox approach and couples the two engine shafts though a planetary gearbox that can be used to manipulate power transfer through the electromechanical powertrain.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":false},"schemaVersion":"1.0","software":{"releaseType":"Open Source","repositoryUrl":"https://www.github.com/nasa/AGTF30-e","license":null}},{"forgeId":"forge_nasa_mfs_32554_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-32554-1","sourceUrl":"https://software.nasa.gov/software/MFS-32554-1","confidence":"high"},"type":"software","title":"Multidimensional, Multiphysics Computational Heat Transfer Analysis Software (UNIC)","abstract":"The Multidemensional, Multiphysics Computational Heat Transfer Analysis Software (UNIC) solves transient, coupled, and simultaneous conjugate heat transfer solutions commonly encountered in rocket engine and launch vehicle component design and analysis .","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Release Only","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_32929_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-32929-1","sourceUrl":"https://software.nasa.gov/software/MFS-32929-1","confidence":"high"},"type":"software","title":"Generalized Fluid System Simulation Program (GFSSP), Version 702 (Educational Version)","abstract":"The Generalized Fluid System Simulation Program (GFSSP) is a general-purpose computer program for analyzing steady state and time-dependent flowrates, pressures, temperatures, and concentrations in a complex flow network. The program is capable of modeling phase changes, compressibility, mixture thermodynamics, and external body forces such as gravity and centrifugal forces. GFSSP was developed at Marshall Space Flight Center for flow analysis of Rocket Engine Turbopumps and Propulsion Systems. GFSSP was the recipient of the NASA Software of the Year Award in 2001.GFSSP is a network flow solver. The thermo-fluid system to be analyzed is discretized into a network of nodes connected by branches. Conservation of mass and energy is solved in the nodes to calculate fluid pressures and temperatures. The momentum equation is solved in the branches for flow rates. Conjugate Heat Transfer may be added to the model through the use of solid nodes connected by conductors. A graphical user interface, MIG (Modeling Interface for GFSSP), allows users to build models by pointing and clicking.Properties for common fluids in propulsion applications are provided by the GASP/WASP and GASPAK property packages. Users can also supply fluid property interpolation tables. A library of common fluid components such as pipes, orifices, and valves is provided. Built-in advanced options include pressure and flow regulators, valve opening/closing, and propellant tank pressurization/draining. Thirty-two example problems demonstrate the use of the various capabilities of the code.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_33019_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-33019-1","sourceUrl":"https://software.nasa.gov/software/MFS-33019-1","confidence":"high"},"type":"software","title":"Generalized Fluid System Simulation Program (GFSSP), Version 702","abstract":"The Generalized Fluid System Simulation Program (GFSSP) is a general-purpose computer program for analyzing steady state and time-dependent flowrates, pressures, temperatures, and concentrations in a complex flow network. The program is capable of modeling phase changes, compressibility, mixture thermodynamics, and external body forces such as gravity and centrifugal forces. GFSSP was developed at Marshall Space Flight Center for flow analysis of Rocket Engine Turbopumps and Propulsion Systems. GFSSP was the recipient of the NASA Software of the Year Award in 2001.GFSSP is a network flow solver. The thermo-fluid system to be analyzed is discretized into a network of nodes connected by branches. Conservation of mass and energy is solved in the nodes to calculate fluid pressures and temperatures. The momentum equation is solved in the branches for flow rates. Conjugate Heat Transfer may be added to the model through the use of solid nodes connected by conductors. A graphical user interface, MIG (Modeling Interface for GFSSP), allows users to build models by pointing and clicking. Customized branch options or new model logic may be added to the code through Fortran user subroutines.Properties for common fluids in propulsion applications are provided by the GASP/WASP and GASPAK property packages. Users can also supply fluid property interpolation tables. A library of common fluid components such as pipes, orifices, and valves is provided. Built-in advanced options include pressure and flow regulators, valve opening/closing, and propellant tank pressurization/draining. Thirty-two example problems demonstrate the use of the various capabilities of the code.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_mfs_33320_1","source":{"institution":"NASA","subUnit":"Marshall Space Flight Center","subUnitCode":"MSFC","nativeId":"MFS-33320-1","sourceUrl":"https://software.nasa.gov/software/MFS-33320-1","confidence":"high"},"type":"software","title":"Chemical Equilibrium with Applications in MATLAB (CEAM)","abstract":"This software is an adaptation of the FORTRAN based Gordon-McBride Chemical Equilibrium with Application (CEAM) computer program developed 50 years ago. This software incorporates modern programming techniques, data management, and adds unique user features. A standalone graphical user interface application has been created. An App for use within MATLAB is provided. A stand alone executable application is now included. A package for adding CEAM to python has been compiled.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. and Foreign Release","repositoryUrl":null,"license":null}},{"forgeId":"forge_nasa_ssc_00592","source":{"institution":"NASA","subUnit":"Stennis Space Center","subUnitCode":"SSC","nativeId":"SSC-00592","sourceUrl":"https://software.nasa.gov/software/SSC-00592","confidence":"high"},"type":"software","title":"NDAS ( NASA Data Acquisition System )","abstract":"NASA Data Acquisiton System (NDAS) encompasses a suite of Data Acquisition Applications including acquisition, data processing, calibration, display, recording as well as distribution. This software system is intended to be used across all data acquisition hardware platforms.","category":"propulsion","categoryRaw":"propulsion","trl":null,"availability":[{"fieldOfUse":"all","exclusivity":"either","geographic":"global","status":"available","notes":"Contact TTO to confirm field-of-use and exclusivity options"}],"exportControl":{"itar":false,"ear":true},"schemaVersion":"1.0","software":{"releaseType":"U.S. Government Purpose Release","repositoryUrl":null,"license":null}}];

