// Returns { ok: true, text } on success, or { ok: false, error } with a
// human-readable message on failure. Callers should surface the error.
async function callClaude(prompt, maxTokens = 1024) {
  try {
    const response = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        model: "claude-sonnet-4-20250514",
        max_tokens: maxTokens,
        messages: [{ role: "user", content: prompt }],
      }),
    });
    if (!response.ok) {
      const body = await response.text().catch(() => "");
      console.error("API HTTP error:", response.status, body);
      return {
        ok: false,
        error: `API returned ${response.status}. ${body.slice(0, 200)}`,
      };
    }
    const data = await response.json();
    if (data.type === "error") {
      return {
        ok: false,
        error: data.error?.message || "Unknown API error",
      };
    }
    const textBlock = data.content?.find((c) => c.type === "text");
    if (!textBlock?.text) {
      console.error("No text block in response:", data);
      return { ok: false, error: "No text returned by the model" };
    }
    return { ok: true, text: textBlock.text };
  } catch (e) {
    console.error("Claude API error:", e);
    return { ok: false, error: e?.message || "Network error" };
  }
}

// Robust JSON extraction. Walks the response tracking string state and
// brace depth to find the first balanced JSON value, even if Claude adds
// prose before/after or includes braces in commentary.
function extractJson(text, expect = "object") {
  if (!text) return null;
  // Strip code fences if present
  let cleaned = text.replace(/```(?:json)?/gi, "").trim();

  // Prefer content inside <json>...</json> sentinel if Claude obeyed
  const tagMatch = cleaned.match(/<json>([\s\S]*?)<\/json>/i);
  if (tagMatch) cleaned = tagMatch[1].trim();

  const openChar = expect === "array" ? "[" : "{";
  const closeChar = expect === "array" ? "]" : "}";
  const start = cleaned.indexOf(openChar);
  if (start === -1) return null;

  let depth = 0;
  let inString = false;
  let escape = false;
  let end = -1;
  for (let i = start; i < cleaned.length; i++) {
    const ch = cleaned[i];
    if (escape) {
      escape = false;
      continue;
    }
    if (inString) {
      if (ch === "\\") {
        escape = true;
      } else if (ch === '"') {
        inString = false;
      }
      continue;
    }
    if (ch === '"') {
      inString = true;
      continue;
    }
    if (ch === openChar) depth++;
    else if (ch === closeChar) {
      depth--;
      if (depth === 0) {
        end = i;
        break;
      }
    }
  }
  if (end === -1) {
    console.error("Unbalanced JSON. Raw text:", cleaned.slice(0, 800));
    return null;
  }
  const candidate = cleaned.slice(start, end + 1);
  try {
    return JSON.parse(candidate);
  } catch (e) {
    console.error("JSON parse failed:", e, "Candidate:", candidate.slice(0, 500));
    return null;
  }
}

