// ============================================================
// MAIN APP
// ============================================================

export default function App() {
  const [view, setView] = useState("home");
  const [selectedTech, setSelectedTech] = useState(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [filters, setFilters] = useState({ category: null, center: null, type: null, institution: null });
  const [savedIds, setSavedIds] = useState(new Set());
  const [aiBriefs, setAiBriefs] = useState({});
  const [aiSearchActive, setAiSearchActive] = useState(false);
  const [aiSearchResults, setAiSearchResults] = useState(null);
  const [aiSearchLoading, setAiSearchLoading] = useState(false);

  // Load saved items from persistent storage
  useEffect(() => {
    (async () => {
      try {
        const result = await window.storage?.get("forge:saved");
        if (result) {
          const ids = JSON.parse(result.value);
          setSavedIds(new Set(ids));
        }
      } catch (e) {
        // No saved items yet
      }
    })();
  }, []);

  const toggleSaved = async (id) => {
    const next = new Set(savedIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSavedIds(next);
    try {
      await window.storage?.set("forge:saved", JSON.stringify([...next]));
    } catch (e) {
      console.error("Save failed:", e);
    }
  };

  const openDetail = (tech) => {
    setSelectedTech(tech);
    setView("detail");
    window.scrollTo(0, 0);
  };

  const goHome = () => {
    setView("home");
    setSearchQuery("");
    setFilters({ category: null, center: null, type: null, institution: null });
    setAiSearchActive(false);
    setAiSearchResults(null);
    window.scrollTo(0, 0);
  };

  const startSearch = (q) => {
    setSearchQuery(q);
    setView("search");
    setAiSearchActive(false);
    window.scrollTo(0, 0);
  };

  // Standard keyword filter
  const filteredTech = useMemo(() => {
    let list = TECHNOLOGIES;
    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      list = list.filter(
        (t) =>
          t.title.toLowerCase().includes(q) ||
          t.description.toLowerCase().includes(q) ||
          t.category.toLowerCase().includes(q) ||
          t.id.toLowerCase().includes(q)
      );
    }
    if (filters.category) list = list.filter((t) => t.category === filters.category);
    if (filters.center) list = list.filter((t) => t.center === filters.center);
    if (filters.type) list = list.filter((t) => t.type === filters.type);
    if (filters.institution) list = list.filter((t) => t.source?.institution === filters.institution);
    return list;
  }, [searchQuery, filters]);

  return (
    <div
      style={{
        backgroundColor: "#F4EFE6",
        color: "#161513",
        minHeight: "100vh",
        fontFamily: "'IBM Plex Sans', system-ui, sans-serif",
      }}
    >
      {/* Embedded fonts and base styles */}
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,300..900&family=IBM+Plex+Sans:wght@300;400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap');

        * { -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }

        .display { font-family: 'Fraunces', serif; font-variation-settings: 'opsz' 144, 'SOFT' 0; letter-spacing: -0.02em; }
        .display-italic { font-family: 'Fraunces', serif; font-style: italic; font-variation-settings: 'opsz' 144; letter-spacing: -0.01em; }
        .mono { font-family: 'IBM Plex Mono', monospace; }

        @keyframes fadeUp {
          from { opacity: 0; transform: translateY(8px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .fade-up { animation: fadeUp 0.5s cubic-bezier(0.16, 1, 0.3, 1) both; }

        @keyframes shimmer {
          0% { opacity: 0.4; } 50% { opacity: 0.8; } 100% { opacity: 0.4; }
        }
        .shimmer { animation: shimmer 1.5s ease-in-out infinite; }

        button:focus-visible, input:focus-visible, textarea:focus-visible, select:focus-visible {
          outline: 2px solid #BC4A23; outline-offset: 2px;
        }

        ::selection { background: #BC4A23; color: #F4EFE6; }

        .hover-lift { transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease; }
        .hover-lift:hover { transform: translateY(-2px); border-color: #BC4A23; }
      `}</style>

      <Header onHome={goHome} savedCount={savedIds.size} />

      {view === "home" && (
        <HomeView
          onSearch={startSearch}
          onOpenTech={openDetail}
          onAiSearch={() => {
            setView("aimatch");
            window.scrollTo(0, 0);
          }}
          onDiscoveryScan={() => {
            setView("discovery");
            window.scrollTo(0, 0);
          }}
        />
      )}

      {view === "search" && (
        <SearchView
          query={searchQuery}
          setQuery={setSearchQuery}
          filters={filters}
          setFilters={setFilters}
          results={filteredTech}
          onOpenTech={openDetail}
          savedIds={savedIds}
          toggleSaved={toggleSaved}
        />
      )}

      {view === "detail" && selectedTech && (
        <DetailView
          tech={selectedTech}
          onBack={() => setView("search")}
          aiBriefs={aiBriefs}
          setAiBriefs={setAiBriefs}
          isSaved={savedIds.has(selectedTech.id)}
          onToggleSave={() => toggleSaved(selectedTech.id)}
          onRequest={() => {
            setView("request");
            window.scrollTo(0, 0);
          }}
          onBuildCase={() => {
            setView("buildcase");
            window.scrollTo(0, 0);
          }}
        />
      )}

      {view === "aimatch" && (
        <AiMatchView
          loading={aiSearchLoading}
          setLoading={setAiSearchLoading}
          results={aiSearchResults}
          setResults={setAiSearchResults}
          onOpenTech={openDetail}
          onBack={goHome}
        />
      )}

      {view === "discovery" && (
        <DiscoveryScanView
          onOpenTech={openDetail}
          onBack={goHome}
        />
      )}

      {view === "buildcase" && selectedTech && (
        <BusinessCaseView
          tech={selectedTech}
          onBack={() => setView("detail")}
          onRequest={() => {
            setView("request");
            window.scrollTo(0, 0);
          }}
        />
      )}

      {view === "request" && selectedTech && (
        <RequestView tech={selectedTech} onBack={() => setView("detail")} onHome={goHome} />
      )}

      <Footer />
    </div>
  );
}

